INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 1, 'S yisem n Öebbi, Aênin Ipêunun,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 2, 'Ccekôan i Öebbi, Mass imavalen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 3, 'Aênin Ipêunun,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 4, 'Agellid n wass iqeîîiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 5, 'D Keçç ay naâbed, d Keçç ay nepper d Amâ²iwen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 6, 'Awi ya$ d ubrid iweqmen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 7, 'Abrid n wid i T$atev; ur n wid i K isserfayen, ne$ n im$eôôqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 1, 'Alm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 2, 'Appan Tezmamt, ur degs ccekk, d nnhaya i wid ipêezziben;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 3, 'wid iumnen s tbavnit, ipéallan, ipseddiqen seg wayen iten N$at;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 4, 'wid iumnen s wayen i k d irsen, akked wayen id irsen, uqbel ik, u, $ef laxeôt, nitni, pputebbten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 5, 'Widak, di nnhaya n Mass nnsen, widak, d isaâdiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 6, 'Wid ijehlen, s tidep, iâuva fellasen ma tnubav ten, ne$ ur ten tnubav. Ur ppamnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 7, 'Isle$ Öebbi ulawen nnsen, akked imeééu$en nnsen. Irs le$yaô $ef allen nnsen. Fellasen aâaqeb abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 8, 'Ger yimdanen, llan wid iqqaôen: "numen s Öebbi akked wass aneggaru”; nitni, ur llin d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 9, 'La xedâen Öebbi akked wid iumnen. Ur xedâen siwa iman nnsen, ur faqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 10, 'Aîan deg ulawen nnsen; Irna yasen Öebbi aîan. Fellasen aâaqeb aqeôêan, ilmend n wayen skiddiben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 11, 'Ma nnan asen: "ur ssefsadet di tmurt"! A d inin: "nekwni d wid, kan, ipleqqimen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 12, 'Day maççi d nitni, s tidep, ay d ifessaden, maca ur faqen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 13, 'Ma nnan asen: "amnet, akken umnen medden"! A d inin: "day a namen, akken umnen ije$lufen"? Day maççi d nitni, s tidep, ay d ije$lufen, maca ur éôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 14, 'Ma mmugren d wid iumnen, ad inin: "numen". Mara yilin weêêedsen, ar ccwaîen nnsen, ad inin: "nekwni yidwen! Nekwni la nettihi kan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 15, 'Öebbi ad Ittihi fellasen. Isnerna yasen lbwe$v nnsen; ddebdeben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 16, 'Widak, d wid iu$en ttelfan s nnhaya; ur d issasay ssuq nnsen, ur pwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 17, 'Tevôa yidsen am win issa$en times. Mi tnewweô ayen i s d izzin, Öebbi Iddem tafat nnsen, Iooa ten di tillas, ur pwalin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 18, 'Âaégen, gugmen, dre$len; ihi, nitni ur d ppu$alen s abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 19, 'Ne$ am usigna igenni, degs tillas, tirmegt, lebôaq. Pparran ivudan nnsen deg imeééu$en nnsen, mgal ssiâqat; ad nnestaôen si tmeppant. Öebbi Izzi i ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 20, 'Qôib i sen iêwi lebôaq, iéôi. Yal tikelt ideg i sen icâal, ad ddun syis. Mi sen ixsi, ad êebsen. Ma ihwa yaS i Öebbi, ad asen Ikkes timesliwt akked yiéôi nnsen. Öebbi, s tidep, Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 21, 'A yimdanen! Âabdet Mass nnwen ikwen Ixelqen, kunwi, akked wid i kwen id izwaren, amar a pêezzbem;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 22, 'i wen Irran tamurt d usu, igenni d lebni; id Isse$li d aman seg igenni, Issuffe$ ed yissen ppemôa, d ôôeéq i kunwi. Ihi, ur pparrat tanudda i Öebbi, u kunwi teéôam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 23, 'Ma tellam di ccekk, $ef wayen id Nessers ar umdan nne£, awit ed tasuôep i p icban. Neccdet ed inagan nnwen, war Öebbi, ma tessawalem tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 24, 'Ma ur tessawvem, u, war ccekk, ur tessawavem, êezzbet i tmes isseô$an imdanen, id$a$en, ippuheggan i ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 25, 'Becceô wid iumnen, u xeddmen ayen ilhan, ar i nitni, leonanat, ddawat sen isaffen ppazzalen. Yal tikelt ara ppuôeéqen, si ppemôa nnsen, ad inin: "d aya is neppuôeéq, uqbel". Ippunefk asen i ten icban. Din, jjwao nnsen d ayen iûfan. Degsen ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 26, 'Ih, ur Ikukra ara Öebbi, a d Ifk amedya n tizip, ne$ ip i$elben. Wid iumnen éôan neppa d tidep, s$uô Mass nnsen. Wanag wid ijehlen qqaôen: "acu Ib$a Öebbi s umedya agi"? Yis, Itellif aîas; yis, Inehhu aîas. Ur Itellif yis, siwa iballa$en;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 27, 'wid ipôuéun lemâahda n Öebbi, deffir lmitaq iS, issemfaôaqen ayen id Iumeô Öebbi ad imlil, issefsaden di tmurt. Widak d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 28, 'Amek ara tnekôem Öebbi? Tellam temmuten, Issader kwen id. Sinna, a kwen Ine$, sinna, a kwen id Issider, sinna, $uôeS a ppu$alem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 29, 'D Neppa i wen Ixelqen ayen akw illan di tmurt; sinna, Izzi ar igenni, Iwqem it d ûa igenwan. Neppa, Issen yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 30, 'Mi Inna Mass ik, i lmalayek: "Nek ad Rre$ aneûûaf di tmurt". Nnant aS: "day a Pperrev, degs, win ara isfesden degs, ara izzizlen idamen? Wanag, nekwenti nesbuccuâ K s ccekôan, u Neôôequ yaK". Inna: "Nek, èôi$ ayen ur teéôimt".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 31, 'Isseêfev akw ismawen i Adem. Sinna, Issken iten i lmalayek, Inna: "efkemt iyI d ismawen n wigi, ma kunemti d sut tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 32, 'Nnant: "gedha s yisseK! Ur nessin, siwa i a$ Teslemdev. Keçç, s tidep, d Amusnaw, d Bab n ûûwab".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 33, 'Inna: "a Adem, efk asent ismawen nnsen". Mi sent imla ismawen nnsen, Inna: "day ur a kwent Nni$ ara: Nek Ssne$ tabavnit n tmurt akked igenwan, u èôi$ ayen d teqqaôem, akked wayen teppeffrem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 34, 'Mi Nenna i lmalayek: "knumt i Adem"! Knant, siwa Iblis. Iugi, u isme$weô iman is. Illa seg ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 35, 'Nenna: "a Adem, ezde$ keçç akked tmeîîut ik, di Loennet, eççet segs, s tawant, ayen i wen ihwan. Ur ppaéet ar ttejôa yagi, mulac a ppilim d imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 36, 'Ikellex iten Cciîan fellas. Issuffe$ iten id seg wanda llan. Nenna: "ûûubbet, d icenga bbwaygarawen. I kunwi, di tmurt, i$imi akked zzhu, siwa tallit".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 37, 'Adem iîîef awalen n Mass is. Issuref as. Neppa, s tidep, Issuruf, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 38, 'Nenna: "ûûubbet segs, akken ma tellam. War ccekk, a kwen id tas nnhaya s$uôI". Wid iddan d nnhaya, ur ppagwaden, ur $weblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 39, 'Wid ijehlen u skaddben issekniyen nne£, widak d at tmes, degs ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 40, 'A yAt Isôail! Mmektit ed l$it iW, is ikwen Öeéqe$. Eîîfet di lemâahda W, ad Ïîfe$ di lemâahda nnwen. D nek iwumi ara têezzbem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 41, 'Amnet s wayen id Sserse$, itebbten ayen illan $uôwen. Ur ppilit d imezwura ara t iagwin. Ur ppa$et, s issekniyen iW, ayen ôxisen. D nek iwumi ara têezzbem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 42, 'Ur slusut, i tidep, tikerkas. Ur teffret tidep, u kunwi teéôam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 43, 'èéallet, zekkit, îîinzet akked wid iîîinizen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 44, 'Day a ppamôem ise$ i medden, a ppeppum iman nnwen? U kunwi teqqaôem Tazmamt. Day ur tefhimem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 45, 'Ssutret lemâawna n ûûbeô akked téallit. Ih, dayen iwaâôen, siwa i imeéluven,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 46, 'wid iêûan ar ad mlilen akked Mass nnsen, u $uôeS, nitni, war ccekk, ad u$alen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 47, 'A yAt Isôail! Mmektit ed l$it iW, is ikwen Öeéqe$. Nek, Smenyafe$ kwen i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 48, 'Ëezzbet i wass ideg ur ippuoazi yiwen deg umkan n wayev, s wacemma. Ur tepwaqbal ccafuâa segs, ur tepwaîîaf, segs, le$ôama, ur ten ppaâwanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 49, 'Mi kwen Nsellek seg ugdud n Ferâun, sâaddayen fellawen aâaqeb adiran. Zellun arrac nnwen, ssidiren tilawin nnwen. Ayagi d taluft tabarart, s$uô Mass nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 50, 'Mi, yiswen, Nessemfaôeq ill, Nsellek ikwen, Ne$meq agdud n Ferâun, kunwi la tepwalim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 51, 'Mi Nga lemâahda i Musa, kuéet wavan; sinna, deffir es, teddam d uâajmi. Kunwi d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 52, 'Sinna, deffir waya, Nsemmeê awen, amar a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 53, 'Mi Nefka, i Musa, Tazmamt akked ufraz, amar a ppeppwanhum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 54, 'Mi inna Musa i ugdud is: "a yagdud iw! Kunwi, s tidep, tdensem iman nnwen, mi teddam d uâajmi. Ssutret ssmaê i Uxellaq nnwen; mmin$et, ppif i kunwi ar Uxellaq nnwen. Issuref awen. Neppa, s tidep, Issuruf, Ipêunu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 55, 'Mi tennam: "a Musa! Ur neppamen yisek, d awez$i, alamma nwala Öebbi, âinani". Tewwet ikwen id ssiâqa, kunwi tepwalim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 56, 'Sinna, Nerra kwen id, deffir tmeppant nnwen, amar a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 57, 'S usigna, Nerra yawen tili. Nessers awen d lmenna, ifeôôuoen: "eççet si téidanin is ikwen N$at". Ur a£ dnisen, maca densen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 58, 'Mi Nenna: "kecmet tamdint agi, eççet degs, s tawant, ayen i wen ihwan; kecmet si tebburt, s lekni; init: nendem. Ad awen Nsemmeê tuccva nnwen, a Nernu i iâaôviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 59, 'Wid idensen bedlen awal, ur d win i sen nnan. Nessers ed, i wid idensen, tawa$it seg igenni, ilmend n tucmitin nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 60, 'Mi issuter Musa aman i ugdud is, Nenna: "ewwet aéôu, s uâkkwaz ik". Feggvent ed, segs, mrawsnat tliwa. Yal wa iéôa anda ara issew. "Eççet, esswet, si ôôeéq n Öebbi. Ur ssefsadet di tmurt am imjaêen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 61, 'Mi tennam: "a Musa! Ur nesteqnaâ bippa s yiwen n lqut. Nuj a$ Mass ik, ad a$ d Issuffe$ ayen d teggar tmurt: tizzegzewt is, axyaô is, ticcert is, laâds is, lebûel is". Inna: "teb$am a pbedlem ayen ilhan s wayen ixuûen? Üûubbet ar Maûeô, a n tafem, war ccekk, ayen tessutrem". I$li d fellasen ddell akked ééelt. Sebbeben d urrif n Öebbi. Ayagi, acku llan ugin issekniyen n Öebbi, neqqen lambiyya, war ssebba. Ayagi, imi âuûan, u zgaren tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 62, 'Ih, wid iumnen, udayen, imasiêiyen, iûabiyen, kra iumnen s Öebbi akked wass aneggaru, u xeddmen ayen ilhan, ad sâun arraz ar Mass nnsen, ur ppagwaden, ur $weblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 63, 'Mi Nga laâqed yidwen, Nessuli adrar sennig wen: "eîîfet nezzeh ayen i wen Nefka, mmektit ed i illan degs, amar a pêezzbem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 64, 'Sinna, deffir waya, twexxôem. Lemmer maççi d lfevl n Öebbi fellawen, akked uêunu S, a ppilim seg imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 65, 'Ni$ tessnem wid, segwen, iccven di Ssebt. Nenna yasen: "ilit d iddawen imaâfan"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 66, 'Nerra p d amedya i imuddiren akked wid i ten id ineûfen, u d aâggen i wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 67, 'Mi inna Musa i ugdud is: "Öebbi, s tidep, Iumeô awen d a ppezlum tafunast". Nnan: "day a tettihiv fella$"? Inna: "ad iyi Isseô Öebbi! Ur ppili$ seg at war tussna".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 68, 'Nnan: "nuj a$ ar Mass ik, ad a$ d Ibeggen anta p". Inna: "Neppa, s tidep, la Iqqaô: tafunast ur wessret, ur meééiyet, garasen. Xedmet i wen d ippumôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 69, 'Nnan: "nuj ar Mass ik, ad a$ d Ibeggen ini s". Inna: "Neppa, s tidep, la Iqqaô: d tafunast tawôa$t, ini imfeooeo, ad iaâoeb w ip iwalan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 70, 'Nnan: "nuj ar Mass ik, ad a$ d Ibeggen anta p. £uône$, s tidep, tistan ppemcabint. Ih, ma Ib$a Öebbi, a nepwanhu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 71, 'Inna: "Neppa, s tidep, la Iqqaô: d tafunast ur taâtib si tyerza n tmurt, ne$ si tissit n yigran, tûeêêa, ur tepwacôev". Nnan as: "tura, tebbwiv d tidep". Zlan p. Qôib ur ewqimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 72, 'Mi ten$am yiwen, wa irra p id $ef wa. Öebbi Issuffe$ ed ayen teppeffrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 73, 'Nenna: "ewwtet ep s kra ines". Akka i Issidir Öebbi lmeggtin. Issenâat awen issekniyen iS, amar a pfehmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 74, 'Sinna, deffir waya, qquôen wulawen nnwen; cuban aéôu, ne$ kteô, di ta$eôt. Ih, llan iéôa iseg d pfeggiven isaffen. Llan, s tidep, wid ipceqqiqen, teff$en d waman segsen. S tidep, llan wid i$ellin si tugwdi n Öebbi. Ur I$fil Öebbi $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 75, 'Day tôe$bem a kwen amnen? Ni$ arbaâ, segsen, ssemêasen i wawal n Öebbi, sinna, mi t fehmen, ad as bedlen udem, u nitni éôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 76, 'Mi mmugren wid iumnen, ad inin: "numen". Mi qqimen garasen, qqaôen: "day ad asen tinim ayen i wen Imla Öebbi, a kwen nna$en yis, ar Mass nnwen? Day ur tepmeyyizem ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 77, 'Ne$ ur éôin ara, Öebbi Issen ayen teffren, akked wayen qqaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 78, 'Garasen, at war ta$uôi, ur nessin Tazmamt, siwa ayen nnwan. Nitni $ilen kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 79, 'A tawa$it n wid ipparun Tazmamt s ifassen nnsen, sinna, qqaôen: "ayagi s$uô Öebbi", iwakken ad a$en, yis, ayen ôxisen! A tawa$it nnsen, ilmend n wayen uran ifassen nnsen! A tawa$it nnsen, $ef wayen keppben!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 80, 'Nnan: "ur a$ tepnal tmes, d awez$i, siwa kra n wussan". Ini: "day teîîfem lemâahda s$uô Öebbi? Öebbi, d awez$i, ur Izeggil lemâahda S. Ne$ teqqaôem, $ef Öebbi, ayen ur tessinem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 81, 'Xaîi, win ikesben tucmip, u tennev as tuccva s…, widak, d at tmes, degs ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 82, 'Wid iumnen, u xeddmen ayen ilhan, widak, d at Loennet, degs ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 83, 'Mi Nga laâqed i At Isôail: "ur âabdet siwa Öebbi. Elhut ar imawlan, ar llzem nnwen, ar igujilen, ar igellilen. Init i medden, awal imaânen. èéÈallet, zekkit". Sinna, twexxôem, siwa kra segwen, u, kunwi, tnumrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 84, 'Mi wen Nga laâqed nnwen: "ur zzazalet idim nnwen, ur pemssuffu$et seg ixxamen nnwen". D$a twefqem, kunwi d inagan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 85, 'Sinna, kunwi d wid immin$en, tessuff$em arbaâ segwen, seg ixxamen nnsen. Tezzim asen s ibekkaven akked taâdawt. Ma usan kwen id, d imeêbas, tfeddum ten. Irna, ipwagdel awen usuffe$ nnsen. Day tumnem deg uêric n Tezmamt, tnekôem wayev? Anwa ay d arraz n wid, segwen, ixedmen aya, ma maççi d ddell, di tmeddurt n ddunit, u, ass n tnekra, ad ppunefken i uâaqeb uqsiê mavi? Ur I$fil Öebbi $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 86, 'Widak d wid iu$en tudert n ddunit s laxeôt, ur ippifsus fellasen uâaqeb, ur ppusellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 87, 'Ni$ Nefka Tazmamt i Musa. Nuzen ed imazanen, deffir es. Nefka abeggen i Âisa, mmi s n Meryem, Null it s ôôuê iqedsen. Yal tikelt ideg ara kwen id ias umazan, s wayen ur awen nehwi, tesme$wôem iman nnwen. Kra teskaddbem ten, kra ten$am ten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 88, 'Nnan: "ulawen nne$ qquôen". Xaîi, Ixza ten Öebbi, ilmend n tijehli nnsen. Drus iten wid iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 89, 'Mi ten id tusa Tezmamt, s$uô Öebbi, d atebbet n wayen illan $uôsen, - u llan, iu$ lêal, ssuturen ad $elben wid ijehlen - mi ten id iusa wayen ssnen, ugin t. Ad Inâal Öebbi ijehliyen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 90, 'I icmet wayen i$ef zzenzen iman nnsen! Ugin ayen id Issers Öebbi. Ëesden mi id Issers Öebbi, si lfevl iS, i win i S ihwan n yimdanen iS. Sebbeben urrif ar wayev. I ijehliyen, aâaqeb isdullun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 91, 'Ma nnan asen: "amnet s wayen id Issers Öebbi"! A d inin: "numen s wayen id irsen $uône$". Nekôen ayen i t id itebâan, u neppa d tidep, d atebbet n wayen illan $uôsen. Ini: "acimi tneqqem lambiyya n Öebbi, zik, ma d lmumnin ay tellam"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 92, 'Ni$ iusa kwen id Musa, s ubeggen. Sinna, deffir es, teddam akked uâajmi. Kunwi d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 93, 'Mi Nga laâqed yidwen, Nessuli adrar sennig wen: "eîîfet nezzeh ayen i wen Nefka, u ssemêesset". Nnan d: "nesla u nâuûa". Ikecm asen uâajmi ar wul, si tjehli nnsen. Ini: "dir it wayen i wen iumeô liman nnwen, ma d lmumnin ay tellam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 94, 'Ini: "maday, ar Öebbi, axxam aneggaru i kunwi kan, ur pkkan ara imdanen, mennit tameppant, ma tessawalem tidep"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 95, 'D awez$i, ur p pmennin, ilmend n wayen xedmen ifassen nnsen. Öebbi Issen imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 96, 'A ten tafev, war ccekk, êemmlen tameddurt sennig medden, sennig imcurak. Atan yiwen segsen, issaram ad idder agim iseggwasen. Te$wzi n laâmeô is, ur as tessifrir aâaqeb. Öebbi Ipwali ayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 97, 'Ini: "anwa illan d acengu n Jebrayen"? D neppa, s tidep, it id issersen $ef wul ik, s leb$i n Öebbi. D atebbet n wayen it id izwaren, d nnhaya u d abecceô n lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 98, 'Win illan d acengu n Öebbi, lmalayek iS, imazanen iS, Jebrayen, Mikail…, ihi, Öebbi d acengu ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 99, 'Ni$ Nessers ak d issekniyen iberrzen. I ten inekôen, siwa iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 100, 'Day yal tikelt ideg ara gen laâqed, a t ixdaâ urbaâ segsen? Ih, tegwti segsen, ur uminen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 101, 'Mi ten id iusa umazan s$uô Öebbi, itebbet ayen illan $uôsen, arbaâ n wid iwumi teppunefk Tezmamt, rran Tazmamt n Öebbi s azagur nnsen, amzun ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 102, 'Ddan akked wayen xedmen ccwaîen mgal tagelda n Sliman. Sliman ur ijhil. Maca ccwaîen jehlen. Sseêfaven i medden ssêur, akked wayen id irsen, di Babil, ar lmalayek Harut akked Marut. Ur sselmaden yiwen, mebla ma nnan: "nekwni n$ewwu kan, ur jehhel"! ÊÊÊËefven, $uôsen, amek ara ssemfaôaqen argaz akked tmeîîut is. Ur îîurun yiwen syis, siwa ma Ib$a Öebbi. ÊÊÊËefven ara ten ivuôôen, ur ten ineffaâ. Ni$ éôan ar win i p iu$en, ur as illi umur di laxeôt. War ccekk, ard ucmit wayen is zzenzen leôwaê nnsen, lemmer éôin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 103, 'Lemmer, s tidep, uminen u êezzben, ad ifrir warraz s$uô Öebbi, lemmer ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 104, 'A wid iumnen! Ur qqaret: "Âass a$ d", init: "Wali a$ d", u ssemêesset. I ijehliyen, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 105, 'Ur b$in ara ijehliyen, seg wid iwumi teppunefk Tezmamt, akked imcurak, ad awen d irs kra n lxiô, s$uô Mass nnwen. Öebbi Ismenyaf, s uêunu S, win i S ihwan. Öebbi d Bab n lfevl ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 106, 'Ur Nessemsay assekni, ne$ ur t Nesseppu, mebla ma Nebbwi d win it yifen, ne$ i t icban. Day ur teéôiv ara Öebbi Izmer i yal cci?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 107, 'Day ur teéôiv ara, ar n Öebbi tagelda n tmurt akked igenwan? Ur tesâim, war Öebbi, bab, ne$ asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 108, 'Ne$ teb$am a ppesteqsim Amazan nnwen, akken ippusteqsa, zik, Musa? Win ibeddlen liman s tijehli, innetlaf ar yir abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 109, 'Si leêsed nnsen, aîas seg wAt Tezmamt, mi sen d tban tidep, budden awen tijehli, mbaâd liman nnwen. Ssemêet, ssemsut, ar d Ias Öebbi s lameô iS. Ni$ Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 110, 'èéallet, zekkit. Ayen ara tezzewrem n lxiô i iman nnwen, a t tafem ar Öebbi. Öebbi, s tidep, Ipwali ayen akw txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 111, 'Nnan: "ur ikeççem Loennet, siwa win illan d uday, ne$ d amasiêi". D wagi ay d asirem nnsen. Ini: "awit ed atebbet nnwen, ma tessawalem tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 112, 'Xaîi, win iunzen i Öebbi, u d aâôvi, ad isâu arraz is, ar Mass is. Ur ppagwaden, ur $weblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 113, 'Nnan wudayen: "imasiêiyen ur sennden s acemma". Nnan imasiêiyen: "udayen ur sennden s acemma". U nitni la qqaôen Tazmamt. Akka, wid ur nessin ara, nnan am nitni. Ad Iêudd Öebbi, garasen, ass n tnekra, $ef wayen i$ef mgarraden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 114, 'Anwa idensen sennig wid igedlen, di leowamaâ n Öebbi, asmekti n yisem iS, u lhan d deg ussexôeb nnsen? Widak, ur iwata ara a ten kecmen, siwa ma s tugwdi. I nitni, ddell di ddunit, u aâaqeb abarar di laxeôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 115, 'N Öebbi agmuv akked utaram. Ar wanda tezzim, din Udem n Öebbi. Ih, Öebbi d Ajemmal, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 116, 'Nnan: "Öebbi Isâa mmi S". Gedha s yiS! Ni$ ineS i illan di tmurt akked igenwan. Akw, péallan i Neppa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 117, 'Axellaq n tmurt akked igenwan. Ma Iseyya lameô, ad as Yini kan: "ili"! Ad yili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 118, 'Nnan wid ur nessin: "a lemmer ad a$ d Immeslay Öebbi, ne$ ad a$ d ias ussekni"! Akka ay nnan wid i ten id izwaren, am awalen nnsen. Ppemcabin wulawen nnsen. Ni$ Nbeggen ed issekniyen i ugdud ipputebbten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 119, 'Ih, Nuzen ik id, s tidep, d abcir, u d aneddaô. Ur ippili fellak usteqsi $ef at wu$ud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 120, 'Ur k pôavin wudayen ne$ imasiêiyen, alamma teddiv d ddin nnsen. Ini: "d nehhu n Öebbi ay d nehhu". Ma teddiv akked usirem nnsen, deffir wayen ik ed iusan n tmusni, ur k ipfukku, si Öebbi, bab, ne$ asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 121, 'Wid iwumi Nefka Tazmamt, qqaôen p leqôaya iwatan. Widak umnen yis. Wid i p iugin, widak d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 122, 'A yAt Isôail! Mmektit ed l$it iW, is i kwen £ate$. Nek, Smenyafe$ kwen i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 123, 'Ëezzbet i wass ideg ur ippuqeîîi yiwen, deg umkan n wayev, s wacemma; ur tepwaqbal le$ôama segs, ur t tenfaâ ccafuâa, ur ppusellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 124, 'Ibôahim, mi t Ijeôôeb Mass is, s wawalen, iu$ awal. Inna: "Nek, a k Rre$ d win ara inehhun medden". Inna: "u si tarwa w"? Inna: "lemâahda W ur taâna ara imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 125, 'Mi Nerra Axxam d lemqam i yimdanen, u d amkan n laman: "erret lemqam n Ibôahim d loamaâ"! Nâuhed i Ibôahim akked Ismaâil: "zzizdget Axxam iW, i wid idewwiôen, wid ip$imin, wid iîîinizen, wid ikennun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 126, 'Mi inna Ibôahim: "a Mass iw! Err wagi d tamdint n laman, £it imezda$ is s ppemôat; wid, segsen, iumnen s Öebbi akked wass aneggaru". Inna: "win ijehlen, a t Ooe$ ad izhu cwiî, sinna, a t Nehôe$ ar uâaqeb n tmes. A tu$alin tucmip"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 127, 'Ibôahim akked Ismaâil, mi ssalayen leêyuv n Uxxam: "a Mass nne$! Eqbel s$uône$, Keçç, s tidep, d Win Isellen, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 128, 'A Mass nne$! Err ane$ d imvuâen iK, u, si dderya nne$, lois ar aK ianzen. Mel a$ isekkiren nne$, Ssuref a$. Keçç, s tidep, Tessurufev, Tepêunuv.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 129, 'A Mass nne$! Azen asen d amazan segsen, ad asen iqqaô issekniyen iK, ad asen isseêfev Tazmamt akked ûûwab, a ten izzizdeg. Keçç, s tidep, d Uzmir, d Bab n ûûwab".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 130, 'Anwa iugin ddin n Ibôahim, siwa win iccemten iman is? Ni$ Nefren it di ddunit. Di laxeôt, neppa, war ccekk, seg iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 131, 'Mi s Inna Mass is: "anez"! Inna: "unze$ aS i Mass imavalen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 132, 'Iweûûa yis Ibôahim arraw is - akken Iaâqub -: "a yarraw iw, Öebbi, s tidep, Ifren awen ddin, ur ppemmtet siwa ma tunzem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 133, 'Ne$ tellam d inagan mi d ters tmeppant ar Yaâqub, mi inna i tarwa s: "anwa ara tâabdem deffir i"? Nnan: "a naâbed Öebbi k, u Öebbi n lejdud ik: Ibôahim, Ismaâil, Isêaq. Öebbi Yiwen. Nekwni nunez aS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 134, 'Wigi d lois i iâaddan. Ines ayen ikseb, nnwen ayen tkesbem. Ur kwen steqsayen $ef wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 135, 'Nnan: "ilit d udayen ne$ d imasiêiyen, a ppepwanhum". Ini: "Xaîi, maca ddin n Ibôahim, imalen ar tidep. Ur illi seg imcurak".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 136, 'Init: "numen s Öebbi akked wayen id irsen $uône$, wayen id irsen ar Ibôahim, Ismaâil, Isêaq, Iaâqub, laâôac, ayen ippunefken i Musa, Âisa, ayen ippunefken i lambiyya, s$uô Mass nnsen. Ur nessemgarrad yiwen segsen, nekwni nunez aS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 137, 'Ma umnen ayen icuban ayen tumnem, atnan pwanhan. Ma wexxôen, haaten kan di lefôaq. Iqadd ik Öebbi, segsen. Neppa Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 138, 'Ssbi$a, n Öebbi. Anwa yifen Öebbi i ssbi$a? Nekwni d iâabbaden iS.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 139, 'Ini: "day ad a$ tnamrem $ef Öebbi, u Neppa d Mass nne$, u d Mass nnwen? I nekwni igiten nne$, i kunwi igiten nnwen. Nekwni d izedganen iS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 140, 'Ne$ a d tinim: "s tidep, Ibôahim, Ismaâil, Isêaq, Iaâqub, laâôac, llan d udayen, ne$ d imasiêiyen"? Ini: "Anwa i isnen sennig akw, d kunwi ne$ d Öebbi"? Anwa i idensen sennig win iffren ccada, i isâa s$uô Öebbi? Ur I$fil Öebbi $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 141, 'Asatu agi iâadda. Ines ayen ikseb, nnwen ayen tkesbem. Ur fellawen asteqsi $ef wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 142, 'Ad inin ije$lufen, ger medden: "acu iten iswexxôen si lqibla nnsen, u$uô llan péallan"? Ini: "N Öebbi agmuv akked utaram. Inehhu win i S ihwan, s abrid uwqim".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 143, 'Akka ay kwen Nerra d lois alemmas, iwakken a ppilim d inagan n medden, ad yili Umazan d anagi nnwen. Nerra lqibla u$uô teppezziv, iwakken kan a Néeô anwa iddan d Umazan, anwa iu$alen ar deffir. D lhejna, siwa i wid Inha Öebbi. Ur Iveggiâ Öebbi liman nnwen. Ih, Öebbi, i yimdanen, d Umâin, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 144, 'Ni$ Nwala, tezziv udem ik ar igenni. A k Nawi ar lqibla ara tôaviv. Ezzi udem ik ar Loamaâ n Lêaôam. Anida tellam, zzit udmawen $uôes. Ih, wid iwumi teppunefk Tezmamt, éôan p d tidep s$uô Mass nnsen. Ur I$fil Öebbi $ef wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 145, 'Xas a d tawiv, i wid iwumi teppunefk Tezmamt, yal assekni, ur tezzin ar lqibla k. Keçç, ur tezzi ar lqibla nnsen. Kra segsen, ur tezzin ar lqibla n wiyav. Ma teddiv akked usirem nnsen, mbaâd ma tusa k id, s$uône£, tussna, a ppiliv, imiren, seg imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 146, 'Wid iwumi Nefka Tazmamt ssnen p, akken ssnen arraw nnsen. War ccekk, arbaâ segsen teffren tidep, u nitni éôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 147, 'Tidep s$uô Mass ik, ur ppili seg wid ipcukkun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 148, 'I yal yiwen, loiha u$uô izzi. Sâut timenyugert ar lxiô. Anda teddam, ad Yili Öebbi yidwen akw. Öebbi, s tidep, Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 149, 'Ansi d tusiv, ezzi udem ik ar Loamaâ n Lêaôam. Neppat, ih, d tidep s$uô Mass ik. Ur I$fil Öebbi $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 150, 'Ansi d tef$ev, zzi udem ik ar Loamaâ n Lêaôam. Anida tellam, zzit udmawen nnwen $uôes, iwakken ur kwen pnamaren imdanen, siwa wid idensen, segsen. Ur ten ppagwadet, agwadet iyI. Ad awen Time$ l$it iW, amar a ppepwanhum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 151, 'Akken i wen Nuzen Amazan segwen, immal awen issekniyen nne£, izzizdig ikwen, isselmad awen Tazmamt, akked ûûwab; isselmad awen ayen ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 152, 'Mmektit iyI d, a kwen id Mmekti$. Snemmret iyI, ur jehlet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 153, 'A wid iumnen! Ssutret tallalt, s ûûbeô akked téallit. Ih, Öebbi ar iûebôiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 154, 'Ur qqaôet mmuten wid ipwan$an deg ubrid n Öebbi. Xaîi d imuddiren, maca ur teêûim ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 155, 'War ccekk, a kwen Njeôôeb s kra usigwed, n llaé, n nneqs n wayla, n leôwaê, n l$ellat. Ssefreê iûebôiyen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 156, 'Wid, ma u$en tawa$it, qqaôen: "nekwni n Öebbi, nekwni, a nu$al $uôeS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 157, 'Widak, fellasen téilla s$uô Mass nnsen, akked uêunu. Widak d wid ipwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 158, 'Ih, ÛÜafa akked Meôwa, seg isekkiren n Öebbi. Win iêuoen s Axxam, ne$ iéuô it, ulac u$ilif fellas, ma izzi yasent. Yif it win izzin, s leb$i s. Ih, Öebbi Ippara tajmilt, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 159, 'Ih, wid iteffren ayen id Nessers ubeggen akked nnhaya, mbaâd ma Nbeggen it i yimdanen, di Tezmamt, widak, Ixza iten Öebbi, xzan ten wid ixezzun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 160, 'Kkes ed wid inedmen u xedmen ayen ilhan, u beggnen d. Widak, ad asen Ssurfe$. Nek Ssurufe$, Pêunu$.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 161, 'Ih, wid ijehlen u mmuten d ijehliyen, widak, fellasen xezzu n Öebbi, lmalayek, akked yimdanen, meôôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 162, 'Degs ad wekkôen. Ur ippifsus fellasen uâaqeb, ur illi w ara ten id iwalin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 163, 'Öebbi nnwen d Öebbi Yiwen. Ur illi ôebbi siwa Neppa, Aênin Ipêunun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 164, 'Ih, di lxelq n tmurt akked igenwan: afraz ger yiv akked wass, lbabuô ippazalen di yill, s wayen infâan medden, ayen id Issers Öebbi n waman, seg igenni - Issidir yissen tamurt, deffir tmeppant is, Issenkar, degs, yal lweêc -, abeddel n wavu akked usigna i imuêepmen ad yili ger igenni akked tmurt. War cekk, ard issekniyen i ugdud ipmeyyizen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 165, 'Ger yimdanen, llan wid ippadamen tanudda, war Öebbi. Ëemmlen ten akken Ippuêemmel Öebbi. Wid iumnen zaden akken êemmlen Öebbi. Awufan wid idensen, mi walan aâaqeb, ad éôen ar tazmert akw n Öebbi, u Öebbi Iqseê deg uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 166, 'Mara zekkôen uvfiôen nnsen, wid ipwatebâan, u walan aâaqeb, u tfukk yidsen lemxalîa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 167, 'ad inin uvfiôen: "a lemmer a nu$al, a ten nzekkeô akken i $ zekkôen"! Akka ay sen Issken Öebbi igiten nnsen. A yamxix nnsen, ur d teff$en si tmes!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 168, 'A yimdanen! Eççet seg wayen iêellen, imaânen, di tmurt. Ur teddut di lateô n Cciîan. Neppa, s tidep, d acengu nnwen n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 169, 'Ippameô awen kan tuccva, lâaô; a ppinim, $ef Öebbi, ayen ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 170, 'Ma nnan asen: "ddut akked wayen id Issers Öebbi", a d inin: "xaîi, a neddu akked wayen id nufa ar imezwura nne$". I ma llan imezwura nnsen ur meyyzen acemma, ur pwanhan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 171, 'Amedya n wid ijehlen, d amedya n win u$uô ppu$un, seg akken ur issel, siwa i usu$u akked uberreê. D iâeééugen, d igugam, d ider$alen, nitni ur pmeyyizen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 172, 'A wid iumnen! Eççet si téidanin ikwen N$at. Snemmret Öebbi, ma d Neppa ay tâabdem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 173, 'I awen Igdel Öebbi, siwa loifa, idamen, aksum n yilef, akked îêegga i war Öebbi. Win terra tmara, ur ib$i, ur izgir tilas, ur illi d abekkav is. Ih, Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 174, 'Ih, wid iteffren ayen id Issers Öebbi, si Tezmamt, ppa$en yis ayen ôxisen, widak, siwa times ara ççen, deg iâabbav nnsen. Ur asen Ipmeslay Öebbi, ass n tnekra, ur ten Izzizdig. Fellasen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 175, 'Widak, d wid iu$en ttelfan s nnhaya, aâaqeb s ssmaê. Acu ara ten iûebbôen si tmes?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 176, 'Akka, acku Issers ed Öebbi Tazmamt, s tidep. Ih, wid imgarraden $ef Tezmamt, haaten di lfiôaq u$miq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 177, 'Ise$, maççi ma tezzim udmawen nnwen, ar ugmuv akked utaram. Maca, ise$ d wid iumnen s Öebbi, s wass aneggaru, s lmalayek, s Tazmamt, s lambiyya. U ppaken ayla, $ef lemêibba S, i llzem, igujilen, igellilen, win d ibbwi ubrid, imapparen, akw i uberru n waklan. D wid ipéallan, ipzekkin, ippaîîafen di lemâahda nnsen, ma âahden, iûebôiyen di lmeêna akked twa$it, di tegwnip n ccqa. D wigi i illan di tidep, d wigi i ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 178, 'A wid iumnen! Iura fellawen ppaô n tmegrav. Lêeôô s lêeôô, akli s wakli, nnta s nnta. Win iwumi isemmeê gma s kra: îlaba s lewqama, feddu s lewqama. Ayagi, d sshala s$uô Mass nnwen, akked uêunu. Win iff$en abrid, deffir waya, ad isâaddi aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 179, 'I kunwi, ppaô d tameddurt, a yuâqilen. Amar a pêezzbem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 180, 'Iura fellawen: ma tusa d tmeppant, ar yiwen degwen, ma iooa d lxiô, a t ifk i imawlan is, akked llzem, s lqanun. D ayen ilezmen i wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 181, 'Win it ibeddlen mbaâd ma isla yas, abekkav is siwa $ef wid it ipbeddilen. Öebbi, s tidep, Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 182, 'Ur idnib win iten issemûalaêen acku iugad rrya, ne$ abekkav, s$uô win ippuweûûan. Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 183, 'A wid iumnen! Iura fellawen uéummu, akken iura $ef imezwura nnwen, amar a pêezzbem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 184, 'Ussan ipwaêesben. Win iuvnen segwen ne$ illan ippinig, annect n wussan nniven. Wid i s izemren, feddu ad cceççen igellil. Win izaden lxiô, ilha yas. Ma tuéamem, ppif i kunwi, lemmer teéôim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 185, 'Aggur n ÔÖemvan, ideg d irs Leqwôan, d nnhaya i medden, d abeggen n nnhaya akked ufraz. Win segwen iwalan illul ed waggur, a t iuzum. Win iuvnen ne$ illan ippinig, annect n wussan nniven. Öebbi Ib$a yawen sshala, ur awen Ib$a ara cedda. A pfukem tallit, a pkabrem Öebbi imi kwen Inha, amar a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 186, 'Ma steqsan k, imdanen iW, fellI, Nek Qeôbe$. Pjawabe$ i unuju n yimsuter, ma ipper iyI. Ihi, ad iyI d jawben, ad amnen yissI, amar ad pwanhun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 187, 'Iêell awen, deg iv uéummu, a pqeôôbem ar tlawin nnwen. Nitenti d lebsa nnwen, kunwi d lebsa nnsent. Iéôa Öebbi ar tellam tepkellixem iman nnwen. Issuref awen, Isemmeê awen. Tura qeôôbet $uôsent, nadit ayen i wen Iura Öebbi. Eççet, esswet, ar pferzem lxiv amellal, si lxiv aberkan, di tafrara. Sinna, uéummet ar yiv. Ur pqeôôibet $uôsent, ma tâazlem iman nnwen di lowamaâ. D tigi ay d tilas n Öebbi. Ur pqeôôibet $uôsent! Akka i Ipbeggin Öebbi issekniyen iS i yimdanen, amar ad êezzben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 188, 'Ur ppemyeççat ayla nnwen, garawen, d aêerfi, ur t ppaket i yimêaddan, iwakken a ppeççem amur, seg wayla n medden, di lmenkweô, u kunwi teéôam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 189, 'La k steqsayen $ef tlalit n waggur. Ini: "d lewqat i medden, u i lêio". Ise$, maççi d anekcum ar ixxamen si zdeffir nnsent. Maca, ise$ d aêezzeb i Öebbi. Kecmet ixxamen si tebbura nnsen. Ëezzbet i Öebbi, amar a prebêem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 190, 'Nna$et deg ubrid n Öebbi wid i kwen ipna$en. Ur zegret tilas. Öebbi, s tidep, ur Iêemmel ara wid izegren tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 191, 'Nna$et pen anda ten tufam, ssuff$et pen seg wanda i kwen ssuff$en. Ahewwel iwâaô kteô umennu$. Ur ten nepna$et ar Loamaâ n Lêaôam, siwa ma nnu$en kwen degs. Ma nnu$en kwen, nna$et pen. Akka aqeîîi ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 192, 'Ma fukken, Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 193, 'Nna$et pen alamma tfukk lfetna, u iu$al ddin i Öebbi. Ma fukken, ur pna$et, siwa imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 194, 'Aggur iôqan s waggur iôqan. Tiririt n ppaô $ef wayen ippugedlen. Win ikwen id ibbwven, awvet ep, akken ikwen id ibbwev. Ëezzbet i Öebbi. Cfut ar Öebbi ar wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 195, 'Ssedqet deg ubrid n Öebbi. Ur d ppawit tawa$it, s ifassen nnwen. Maânet. Öebbi, s tidep, Iêemmel iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 196, 'Öuêet ar lêio akked lâumôa, i Öebbi. Ma têeûlem, ssadaqa tushilt. Ur pseîîilet iqweôôa nnwen, ar ppawev tikci s amkan is. Win iuvnen, segwen, ne$ ihlek aqeôôu s, ad ifdu s uéummu, ne$ ssadaqa, ne$ iseflan. Mi tellam di laman, win izuôen ur iêuo, ad iseddeq ayen i s isehlen. Win ur nufa ara, ad iuéum krav wussan di lêio, ûa wussan ar tu$alin, akken ad awven mraw. Ayagi i win ur nesâi tawacult illan ar Loamaâ n Lêaôam. Ëezzbet i Öebbi, cfut ar Öebbi Iwâaô deg uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 197, 'Lêio deg wagguren ipwassnen. Win iâazmen, degsen, ad iêuo, ihi, di lêio ur telli tuzzuft, ne$ ayen n dir, ne$ nnmara. Ayen txedmem n lxiô, Iéôa t Öebbi. Awit aâwin, maca aâwin amxallef d aêezzeb. Ëezzbet iyI a yuâqilen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 198, 'Uu ili u$ilif fellawen ma tessarmem lfevl s$uô Mass nnwen. Mi d tûubbem si Aâôafat, mmektit ed Öebbi, ppama n lemqam iôqan. Mmektit eP id, akken i kwen Inha, wanag tellam, uqbel, seg im$eôôqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 199, 'Sinna, ddut anda ddan medden, ssutret ssmaê i Öebbi. Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 200, 'Mi tfukkem isekkiren nnwen, mmektit ed Öebbi, akken d tesmektayem imezwura nnwen, ne$ kteô. Ger imdanen, wid iqqaôen: "a Mass nne$! Efk a$ di ddunit". Ur ppawin amur di laxeôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 201, 'Llan, garasen, wid iqqaôen: "a Mass nne$! Efk a$ di ddunit, ise$, di laxeôt, ise$. Esseô a$ seg uâaqeb n tmes".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 202, 'Widak, ad awin amur seg wayen kesben. Öebbi Ip$awal deg uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 203, 'Mmektit ed Öebbi, deg ussan iâuden. Win i$awlen di sin wussan, ur icciv ara; win iâaîlen, ur icciv ara, ma illa d win ipêezziben. Ëezzbet i Öebbi. Cfut, ar $uôeS ara tepwafesrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 204, 'Yiwen ger imdanen, iâoeb ik umeslay is, $ef tmeddurt n ddunit. Irra Öebbi d Anagi, $ef wayen illan deg ul is. U neppa iqseê i tilla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 205, 'Mi izzi, ad ikkat di tmurt, iwakken ad issefsed degs, ad isqucc igran akked lmal. Öebbi ur Iêemmel ara asefsed.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 206, 'Ma nnan as: "êezzeb i Öebbi"! A t tekcem lqwedôa ubekkav. Ad isteqnaâ s Loahennama. A yir usu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 207, 'Ger imdanen, win izzenzen iman is, issaram llza n Öebbi. Öebbi d Umâin ar imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 208, 'A wid iumnen! Kecmet di tifrat s lekmal is, ur teddut d lateô n Cciîan. Neppa, s tidep, d acengu nnwen n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 209, 'Ma teccvem, deffir n tisin ubeggen $uôwen, cfut Öebbi d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 210, 'Day a pôaoun kan, ad asen d Ias Öebbi, akked lmalayek, di tili usigna? Ad iûaô lameô. Ar Öebbi ara u$alen lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 211, 'Steqsi At Isôail, acêal issekniyen iberrzen i sen Nefka. I win ipbeddilen tikci n Öebbi, deffir tisin is $uôes, ihi, Öebbi Iqseê deg uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 212, 'Wid ijehlen, ccebêen asen tameddurt n ddunit. Ttihin $ef wid iumnen. Wid ipêezziben ad ilin sennig sen, ass n tnekra. Öebbi Ip$iti win i S ihwan, s lufa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 213, 'Llan imdanen d yiwen n lois. Iuzen ed Öebbi lambiyya ad beccôen, ad nabin. Issers ed, yidsen, Tazmamt s tidep, iwakken ad Iêudd ger medden, $ef wayen i$ef mgarraden. I imgarraden fellas, siwa wid iwumi teppunefk, mbaâd ma iusa ten id ubeggen. Ppemyasamen. Inha Öebbi wid iumnen deg wayen n tidep, i$ef mgarraden, s tsriê iS. Öebbi Inehhu win i S ihwan, s abrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 214, 'Day t$ilem a pkecmem Loennet, wanag ur kwen id iusi wayen id iusan ar wid i kwen id izwaren? Mmugren d lmeêna, ccqa, zzelzla, armi inna umazan akked wid iumnen yides: "melmi laânaya n Öebbi"? Day, s tidep, ur d teqôib ara laânaya n Öebbi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 215, 'Steqsan k $ef wayen ara fken. Ini: "ayen ara tefkem n lxiô, i imawlan, i llzem, i igujilen, i igellilen, i w ar d iawi ubrid". Ayen ara txedmem n lxiô, war ccekk, Iéôa t Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 216, 'Iura fellawen umennu$, u neppa d ayen tkeôhem. Ahat tkeôhem ayen ilhan i kunwi, ahat têemmlem ayen n dir i kunwi. Öebbi Issen, kunwi ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 217, 'La k steqsayen ma ad yili umennu$ deg waggur iôqan. Ini: "amennu$ degs, d abekkav. Abekkav it i$elben, ar Öebbi, d assefôe$ $ef ubrid n Öebbi, d ankaô is, u d ankaô n Loamaâ n Lêaôam; d assuffe$, segs, imezda$ is". Ahewwel i$leb amennu$. Zgan a kwen pna$en, alamma swexxôen kwen, ma zemren, si ddin nnwen. Win, segwen, iff$en i ddin is, ad immet d ajehli. Widak, mêan igiten nnsen di ddunit, di laxeôt. Widak, d at tmes, degs, nitni, ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 218, 'Ih, wid iumnen, win iunagen u juhden deg ubrid n Öebbi, widak ggunin aêunu n Öebbi. Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 219, 'La k steqsayen $ef ccôab akked leqwmeô. Ini: "degsen abekkav meqqwôen, akked ibu$ar i medden. Abekkav nnsen i$leb ibu$ar nsen". La k steqsayen, acu ara seddqen. Ini: "ayen iugaren". Akka i wen Ipbeggin Öebbi issekniyen, amar a pmeyyzem', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 220, 'af ddunit akked laxeôt. La k steqsayen $ef igujilen. Ini: "ppif ma txedmem asen lxiô. Ma txulvem ten, d atmaten nnwen". Öebbi Ifrez ger ufessad akked uâaôvi. Ma ihwa yaS i Öebbi, a kwen Icebbwel. Ih, Öebbi d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 221, 'Ur ppa$et timcurak alamma umnent. Taklit iumnen tif tamcarekt, xas taâoeb ikwen. Ur pnasabet imcurak alamma umnen. Akli iumnen yif amcarek, xas iaâoeb ikwen. Widak, neccden ar tmes. Öebbi Inecced ar Loennet akked ssmaê, ma Irad. Ipbeggin issekniyen iS i medden, amar a d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 222, 'La k steqsayen $ef tarda. Ini: "d aîan. Âazlet tilawin di tarda, ur pqeôôibet $uôsent alamma ûfant. Mi ûfant, qeôôbet $uôsent, akken i wen Iumeô Öebbi". Ih, Öebbi Iêemmel wid iutuben, Iêemmel wid izzizdigen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 223, 'Tilawin nnwen d aêôiq n tyerza nnwen. Melmi teb$am, aset s aêôiq nnwen. Zzewret lxiô i yiman nnwen, êezzbet i Öebbi. Cfut ar kunwi a T temmagrem. Becceô lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 224, 'Ur ssekcamet Öebbi mara teggallem a ppizdigem, a pêezzbem, a ppessemûalêem medden. Öebbi Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 225, 'Ur kwen Ipqissi ara Öebbi $ef tgallit $ef awal. Maca, a kwen Iqiss $ef wayen kesben wulawen nnwen. Öebbi Ipsemmiê, Iêellem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 226, 'Wid iggullen ur pqeôôiben ar tlawin nnsen, ad gganin kué wagguren. Ma bedlen ôôay, ihi, Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 227, 'Ma âazmen berru, ihi, Öebbi Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 228, 'Timnufaq ad aôount krav tardiwin. Ur asent iêell ara ad ffrent ayen Ixleq Öebbi, di tâabbav nnsent, ma umnent s Öebbi akked wass aneggaru. Ma b$an irgazen nnsent ad mûalaêen, izzewr iten lêal a tent id rren, di lmudda nni. Akken pwalasent ay ppalasent, s lqanun. I yirgazen, asurif $er loiha nnsent. Öebbi d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 229, 'Berru, sin iberdan; tiririt, s lqanun; aserreê s lewqama. Ur awen iêell ara a ppedmem kra, seg wayen i sent tefkam - siwa ma ugaden ur pqadaôen ara tilas n Öebbi. Ma tugadem ur pqadaôen ara tilas n Öebbi, ulac u$ilif fellasen $ef wayen is ara d tefdu iman is. D tigi ay d tilas n Öebbi, ur tent zegret. Wid izegren tilas n Öebbi, widak, d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 230, 'Ma ibra yas, ur as têell, imiren, alamma tu$ argaz nniven. Ma ibra yas, ulac u$ilif fellasen ma u$alen ar din, ma walan qudôen tilas n Öebbi. D tigi ay d tilas n Öebbi. Ibeggen itent i ugdud issnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 231, 'Ma tebram i tlawin, u sâaddant tallit nnsent, erret pent id, s lqanun, ne$ serrêet asent, s lqanun. Ur tent pparat s uêeppem, a ppeccvem. Win ixedmen akka, idens iman is. Ur ppuraret s issekniyen n Öebbi. Mmektit ed ayen i kwen I$at Öebbi, akked wayen i wen d Issers si Tezmamt, akw si ûûwab. Ipnabi kwen yis. Ëezzbet i Öebbi. Cfut ar Öebbi Issen yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 232, 'Ma tebram i tlawin, u sâaddant tallit nnsent, ur asent tekset ad a$ent irgazen nnsent, ma mwafaqen s lqanun. Ar waya ay pwanecden wid, segwen, iumnen s Öebbi, akked wass aneggaru. Ppif akka, i tezdeg akked ûûfawa nnwen. Öebbi Issen, kunwi ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 233, 'Tiyimmatin ad ssuîvent arraw nnsent, sin iseggwasen mden, i win ib$an ad itim ussuîev. £ef ubabat, lmakla akked lebsa nnsent, s lqanun. Ur ipwakellaf yiman siwa ar wayen iwumi izmer. Tarwa ur teîîuôôu imma s, ur teîîuôôu baba s. I uweôôat, am akka. Ma b$an ad kksen tuîîva, mcawaôen, ulac u$ilif fellasen. Ma teb$am tamôebbit, a ppessuîîev tarwa nnwen, ulac u$ilif fellawen, ma txelûem ayen i wen ilaqen, s lqanun. Ëezzbet i Öebbi. Cfut ar Öebbi Ipwali ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 234, 'Wid, segwen, issuff$en taôwiêt, u ooan d tilawin, ad aôount kué wagguren akked mraw wussan. Mi sâaddant tallit nnsent, ulac u$ilif fellawen deg wayen xedment deg iman nnsent, di lqanun. Öebbi Iéôa ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 235, 'Ulac u$ilif fellawen, ma tennam d a pxevbem tilawin, ne$ ma teffrem. Iéôa Öebbi, ar tesmektayem tent id. Maca, ur asent âahdet, di tbavnit, siwa ma tennam awal uwqim. Ur ferrut $ef lemlak, alamma ibbwev lajel iuran. Cfut ar Öebbi Iéôa i illan degwen. Ëadret iman nnwen segS. Cfut ar Öebbi Ipsemmiê, Iêellem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 236, 'Ulac u$ilif fellawen ma tebram i tlawin ur tennulem, ne$ iwumi ur tefkim lwajeb. Efket asent tikci iweqmen. Asâay s tezmert is, igellil s tezmert is. D lwajeb i iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 237, 'Ma tebram asent, uqbel a tent tennalem, u, iu$ lêal, tefkam asent lwajeb, ihi, azgen n wayen i sent tefkam, siwa ma semêent, ne$ isemmeê usemsaô n jjwao. Ssmaê iqôeb nezzeh ar uêezzeb. Ur tepput lfevl garawen. Öebbi, s tidep, Ipwali ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 238, 'Ëarbet $ef téilla, u taéallit talemmast. Beddet i Öebbi, s wannuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 239, 'Ma tugadem, s ibeddi, ne$ di rrekba. Ma tellam di laman, mmektit ed Öebbi, akken i wen Isselmed ayen ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 240, 'Wid segwen issuff$en taôwiêt, u ooan d tilawin, ad asent vemnen aseggwas n wuççi, ur tent ssuffu$en. Ma ff$ent, ulac u$ilif fellawen, deg wayen xedment, deg iman nnsent, di lqanun. Öebbi d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 241, 'I tembwurab taqviât, s lqanun. D lwajeb $ef wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 242, 'Akka i wen Ipbeggin Öebbi issekniyen iS, amar a pêemûem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 243, 'Day ur twalav ara wid iff$en, seg ixxamen nnsen, d igima, ugaden tameppant. Inna yasen Öebbi: "emmtet"! Sinna, Issader ten id. S tidep, Öebbi d Bab n lfevl $ef yimdanen, maca tegwti n yimdanen ur snemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 244, 'Nna$et deg ubrid n Öebbi. Cfut ar Öebbi Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 245, 'Win iôevlen aôeîîal umâin i Öebbi, ad as t id Irr s lufa. Öebbi Ippaîaf, Ismiri. £uôeS a ppu$alem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 246, 'Day ur twalav ara imvebbôen seg wAt Isôail, deffir Musa? Mi nnan i nnbi nnsen: "azen a$ d agellid, a nenna$ deg ubrid n Öebbi". Inna: "ma iura fellawen umennu$, day a ppagim a ppenna$em"? Nnan: "ur a$ issefk ara a neqqim ur nepna$ ara, deg ubrid n Öebbi. Ni$ ssuff$en a$ d, nekwni akked tarwa nne$, seg ixxamen nne$". Mi iura fellasen umennu$, wexxôen, siwa drus segsen. Öebbi Issen imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 247, 'Inna yasen nnbi nnsen: "Ni$ Öebbi, s tidep, Iuzen awen d Ïalut, d agellid". Nnan: "amek ara yili d agellid nne$? Nezwar it akken neklal tagelda. Ur as ippunefk wayla". Inna: "Öebbi, s tidep, Ifren it garawen, u Irna yas aîas n tmusni akked loeppa". Ippak Öebbi tagelda S i win i S ihwan. Öebbi d Ajemmal, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 248, 'Inna yasen, nnbi nnsen: "s tidep, assekni n tgelda s, d tisin $uôwen usenduq. Degs talwit s$uô Mass nnwen, akked wayen id igwran, seg wayen id teooa twacult n Musa, akked tin n Haôun. A t id awint lmalayek. Ih, deg waya, d assekni i kunwi, ma d lmumnin ay tellam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 249, 'Mi iffe$ Ïalut, s lâaskeô, inna: "Öebbi, s tidep, a kwen Ijeôôeb s wasif. Win iswan segs, ur illi yidi. Win ur neswi, neppa, s tidep, yidi. Kkes ed win iswan cwiî, deg ufus is". Swan segs, siwa ixeîîayen segsen. Mi zegren, neppa akked wid iumnen yides, nnan: "ur nezmir assa, i Oalut akked lâaskeô is". Nnan wid issarmen ar nitni ad mlilen d Öebbi: "acêal d abrid, îayfa tameééyant te$leb îayfa tameqwôant, ma Irad Öebbi". Öebbi ar iûebôiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 250, 'Mi qublen Oalut akked lâaskeô is, nnan: "a Mass nne$! Azen a$ d ûûbeô, Tebbet isurifen nne$, Awes a$ mgal agdud ijehliyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 251, 'Irad Öebbi, rebêen ten. Dawed in$a Oalut. Ifka yas Öebbi tagelda akked ûûwab. Isselmed as seg wayen i S ihwan. Lemmer ur Issemnamar ara Öebbi, imdanen, a ppefsed tmurt. Maca, Öebbi d Bab n lfevl $ef imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 252, 'Atnan issekniyen n Öebbi; Nemmal ak ten, s tidep. Keçç, war ccekk, seg imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 253, 'Imazanen agi, Nesmenyaf kra i wiyav. Garasen, wid iwumi Immeslay Öebbi. Issuli kra segsen, tiseddaôin. Nefka abeggen i Âisa, mmi s n Meryem, u Nekfa t s ôôuê iôqan. Lemmer i S ihwi i Öebbi, ur ppemyen$an wid i ten id ivefôen, deffir n tisin ubeggen $uôsen. Maca, mgarraden. Segsen wid iumnen, segsen wid ijehlen. Lemmer i S ihwi i Öebbi, ur ppemyen$an, maca Öebbi Ixeddem ayen i S ihwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 254, 'A wid iumnen! Seddqet seg wayen ikwen N$at, uqbel tisin n wass ideg ur telli ttjara, ne$ tiddukla, ne$ ccafuâa. Ijehliyen, d nitni ay d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 255, 'Öebbi, ur illi ôebbi siwa Neppa, Amuddir, Imezgi. Ur Ipnuddum, ur Iggan. IneS i illan deg igenwan, i illan di tmurt. Anwa akka ara icufâan $uôeS, siwa ma s tsriê iS? Issen i illan zdat sen, i illan deffir sen. Ur êemûen kra, si tmusni S, siwa ayen i S ihwan. Lewsaâ usgeld iS, d tamurt akked igenwan. Ur T issaâtab uêareb fellasen. Neppa, d Aâlayan, d Ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 256, 'Ddin maççi s yi$il. Ni$ tepwafôez lewqama si l$welîa. Win iugin iôebbiten n tkerkas u iumen s Öebbi, ihi, iîîef afus ioehden, ur nceqqeq. Öebbi Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 257, 'Öebbi d Bab n wid iumnen. Issuffe$ iten id si tillas ar tafat. Imawlan n wid ijehlen, d iôebbiten n tkerkas. Ssuff$en ten id si tafat ar tillas. Widak, d at tmes, nitni, degs ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 258, 'Day ur twalav ara win inumren Ibôahim $ef Mass is, acku Ifka yas Öebbi tagelda? Mi inna Ibôahim: "Mass iw d win Issidiren, Ineqqen", inna d: "nek ssidire$, neqqe$". Inna Ibôahim: "ihi, Öebbi Issenqaô ed iîij seg ugmuv; keçç, ssenqeô it id seg utaram"! Inneêcam win ijehlen. Öebbi ur Inehhu yara agdud imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 259, 'Ne$ am win iâaddan di temdint tilemt, thudd wakali. Inna: «amek ara d Issider Öebbi tagi, deffir tmeppant is?» In$a t Öebbi twinas iseggwasen, sinna, Issenker it, Inna: «acêal teqqimev?» Inna d: «qqime$ ibwass, ne$ ur ibbwiv wass». Inna: «xaîi, teqqimev twinas iseggwasen. Muqel lqut ik akked tissit ik, ur xûiôen. Muqel a$yul ik. A k Nerr d assekni i medden. Muqel i$san amek ara ten Nessemlil, sinna, ad asen Nessels aksum». Mi ipputebbet, inna: «éôi$ Öebbi Izmer i yal cci».', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 260, 'U mi inna Ibôahim: «a Mass iw! Ssenâat iyi amek tessidirev lmeggtin». Inna: «day ur tuminev ara?» Inna: «xaîi, maca iwakken ad ithedden wul iw». Inna: «ihi, îîef kué igvav, awi ten id $uôek, sinna, err, di yal i$il, amur segsen. Sinna, siwel asen, a d asen dumatu. Cfu ar Öebbi d Uohid, d Uûwib».', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 261, 'Wid ipseddiqen ayla nnsen deg ubrid n Öebbi, cuban aâqqa id igren sa tyedrin. Di yal taydrep, twinas iâqqayen. Öebbi Issugut i win i S Ihwan. Öebbi d Ajemmal, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 262, 'Wid ipseddiqen ayla nnsen deg ubrid n Öebbi, ur seddan, i wayen ssedqen, tiyta ne$ rregmat, ad awin arraz nnsen s$uô Mass nnsen; ur ppagwaden, ur $weblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 263, 'Awal imaânen akked ssmaê, ifen aseddeq i vefôent rregmat. Öebbi d Asâay, Iêellem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 264, 'A wid iumnen! Ur ssemsayet ssadaqa nnwen, s tiyta akked rregmat. Am win iseddqen ayla s, iwakken a t walin medden, ur iumin s Öebbi akked wass aneggaru. Icuba taéôut i i$umm wakal. Iwwet fellas uzayev, iooa p d asuki. Ur sfaydin acemma seg wayen bbwin. Öebbi ur Inehhu ara agdud ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 265, 'Wid ipseddiqen ayla nnsen, ssaramen ad Iôavi Öebbi, u tebbten iman nnsen, cuban leonan di ti$ilt. Iwwet fellas ugeffur, ifka d sin imuren n l$ella s. Ma ur iwwit fellas ugeffur, d nnda. Öebbi Ipwali ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 266, 'Yiwen degwen, ma tusa t id tewser, u $uôes tarwa tuôhift, day ad issirem ad isâu leonan n tezdayin akked tfeôôant, isaffen ppazzalen ddaw as, degs, i neppa, yal ppemôa? Têuza t tnifift degs times, iô$a. Akka i wen Ipbeggin Öebbi issekniyen, amar a pmeyyzem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 267, 'A wid iumnen! Seddqet seg wayen imaânen i teîfem, seg wayen i wen d Nessuffe$ si tmurt. Ur fernet ucmit, segs, ayen ur teppadamem siwa ma s tuqna n wallen, a t tseddqem. Cfut ar Öebbi d Asâay, d Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 268, 'Cciîan iâahed awen tiggulelt, iumeô awen lâaô. Öebbi Iâahed awen ssmaê s$uôeS akked lfevl. Öebbi d Ajemmal, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 269, 'Ippak ûûwab i win i S Ihwan. Win iwumi ippunefk ûûwab, ni$ ippunefk as aîas n lxiô. Siwa uâqilen i ismektayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 270, 'Ayen tefkam useddeq, ne$ teqqnem n tuqqna, Öebbi, s tidep, Iéôa t. Ur llin imâiwnen i imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 271, 'Ma tefkam ssadaqat âinani, ilha. Yif it ma s tuffra, u ma tefkam tent i ime$ban. Ad pwakksent kra si tucmitin nnwen. Öebbi Ippuxebbeô $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 272, 'Ur fellak a ten tenhuv. Maca Öebbi Inehhu win i S Ihwan. Ayen tefkam n lxiô, i iman nnwen. Ur tefkim siwa $ef udem n Öebbi. Ayen tefkam n lxiô, a kwen id iu$al, u kunwi ur kwen dennisen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 273, 'I ime$ban ifelsen deg ubrid n Öebbi, ur nezmir ad inigen di tmurt; wur nessin, inwa ten d imeôkantiyen, seg wakken êekmen. A ten tâaqlev ar tiddi nnsen: ur ssuturen imdanen s nnbec. Ayen tefkam n lxiô, s tidep, Öebbi Iéôa t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 274, 'Wid ifkan ayla nnsen deg iv, deg wass, s tuffra u âinani, ad awin arraz nnsen ar Mass nnsen; ur ppagwaden, ur $weblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 275, 'Wid iteppen rrba, ur d pnekkaren siwa am ara d kren win issexbibev Cciîan, mi t innul. Ayagi, acku nnan: «ttjara am rrba kan». Öebbi Iêell ttjara, Igdel rrba. Win n tusa lewûaya s$uô Mass is, d$a ixva, ines ayen iâaddan. Lameô is ar Öebbi. Wid iu$alen, widak d at tmes, nitni, degs, ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 276, 'Ad Imêu Öebbi rrba, ad Isbuôket ssadaqa. Öebbi ur Iêemmel ara yal ajehli amednub.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 277, 'Ih, wid iumnen, u xeddmen ayen ilhan, u péallan, u pzekkin, ad awin arraz nnsen ar Mass nnsen; ur ppagwaden, ur $weblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 278, 'A wid iumnen! Ëezzbet i Öebbi. Eooet ayen d igwran si rrba, ma d lmumnin ay tellam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 279, 'Ma ur tewqimem ara, êûut ara kwen Inna$ Öebbi akked Umazan iS. Ma tnedmem, nnwen ôaselmal. Ur denniset, ur pwadenset.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 280, 'I win illan di lhejna, aôout liser. Ma tseddqem, yif it i kunwi, lemmer teéôim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 281, 'Ëezzbet i wass n tu$alin nnwen ar Öebbi. Imiren, yal yiwen ad as ippunefk wayen ikseb; nitni ur pwadensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 282, 'A wid iumnen! Ma tesâam îlaba ar lajel ipwassnen, arut ep. A p iaru umaru segwen, s ûûfawa. Ur ippagwi umaru a p iaru, akken i s Isselmed Öebbi. Ad iaru ayen ar as yini umeîîalbu. Ad iêezzeb i Öebbi, Mass is. Ur issenqas acemma segs. Ma illa umeîîalbu d abuhal, ne$ d uôhif, ne$ ur izmir ad yini neppa, ihi, ad yini umeddakwel is s ûûfawa. Sbeddet sin inagan seg irgazen nnwen. Ma ur llin ara sin irgazen, argaz akked snat n tlawin, seg wid tôuvam ad cehhden. Ma te$lev yiwet segsent, tayev a d temmekti. Ur ppagwin inagan, ma pwanecden. Ur stehzayet a p tarum, meééiyet ne$ meqqwôet, ar lajel is. Ayagi iwzen kteô ar Öebbi, iwata kteô i ccada, iwulem kteô ad awen ikkes ccekk. Kkes ed ssuq i tefram imiren garawen; ulac u$ilif fellawen, ma ur t turim ara. Awit inagan deg uzenzi nnwen. Ur ippili ujuôu $ef umaru ne$ $ef unagi. Ma tjuôem, ihi, dir ikwen. Ëezzbet i Öebbi. Öebbi Isselmad ikwen. Öebbi Iéôa yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 283, 'Ma d iminigen ay tellam, ur tufim amaru, a ppeppunefk ôôhina. Ma ifka yiwen segwen lamana i wayev, win iwumi teppunefk, a p irr i win i s ifkan lamana s. Ad iêezzeb i Öebbi, Mass is. Ur ppeffret ccada. Win ip iffren, ihi, neppa, idneb wul is. Öebbi Iéôa ay txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 284, 'N Öebbi i illan deg igenwan, i illan di tmurt. Ama tesseknem i illan deg iman nnwen, ne$ te$bam t, a kwen Iêaseb Öebbi fellas. Ad Isemmeê i win i S Ihwan, ad Iâaqeb win i S Ihwan. Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 285, 'Iumen Umazan s wayen id iusan, $uôes, s$uô Mass is. Lmumnin, akw, umnen s Öebbi akked lmalayek iS, Tizmamin iS, imazanen iS. Ur nesemgirrid yiwen ger imazanen iS. Nnan: «nesla, nunez. Ssmaê iK a Mass nne$! £uôeK tu$alin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 286, 'Ur Ipkellif Öebbi yiman, siwa ar wayen iwumi izmer. Ines wayen ikseb, mgal is wayen iddem. A Mass nne$! Ur a$ Pqassa ma neppu, ne$ neccev. A Mass nne$! Ur a$ Sbibbi taâkkwemt akken ip Tesbabbev i wid i $ d izwaren. A Mass nne$! Ur a$ Sbibbi ayen iwumi ur nezmir. Semmeê ane$, Suref a$, Ëun fellane$. Keçç d Bab nne$, Srebê a$ $ef ugdud ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 1, 'Alm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 2, 'Öebbi, ur illi ôebbi siwa Neppa, Amuddir, Imezgi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 3, 'Issers ak d Tazmamt s tidep, d atebbet n wayen ip id izwaren. Issers ed Tuôa akked Linoil,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 4, 'uqbel, d nnhaya i medden. Issers ed Leqwôan. Ih, wid inekôen issekniyen n Öebbi, fellasen aâaqeb uqûiê. Öebbi d Uzmir, Ippara d ppaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 5, 'Ih, Öebbi ur aS iffir wacemma di tmurt, ne$ deg igenni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 6, 'D Neppa i wen Ippaken udem, di tâabbav, akken i S ihwa. Ur illi ôebbi siwa Neppa, Uzmir, Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 7, 'Neppa i k ed Issersen Tazmamt, degs issekniyen uvhiôen, nitni d tayimmap n Tezmamt. Wiyav d licwaô. D$a, wid iwumi mmalen wulawen, teddun akked wayen illan d licwaô, ssaramen ahewwel, ssaramen asefhem is. I Issnen asefhem is, siwa Öebbi. Qqaôen imawlan n tmusni: "numen yis. S$uô Mass nne$ akw". Id ismektayen, siwa uâqilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 8, 'A Mass nne$! Ur Smili ulawen nne$, mbaâd ma Tenhiv a$. Efk a$ d, s$uôeK, aêunu. Ih, Keçç, ard Am$it.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 9, 'A Mass nne$! Keçç, s tidep, ara Ijemmlen medden, ass i$ef ur illi ccekk. S tidep, Öebbi ur Izeggel lemâahda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 10, 'Ih, wid ijehlen, ur sen d ippawi acemma, ar Öebbi, wayla nnsen, ne$ tarwa nnsen. Widak, d nitni ay d isufa n tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 11, 'D tin n ugdud n Ferâun akked wid i ten id izwaren. Skaddben issekniyen nne£. Iwwet iten Öebbi, ilmend ibekkaven nnsen. Öebbi Iwâaô i uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 12, 'Ini i wid ijehlen: "a ppepwa$elbem, a ppepwafesrem di Loahennama". A yir usu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 13, 'Ni$ d assekni, i kunwi, mi mlalent snat trebbuyaâ. Yiwet tepna$ deg ubrid n Öebbi; tayev d tajehlit, twala d snat, s yiéôi s. Öebbi Ippak afus, s tallalt iS, i win i S ihwan. Deg wayagi, s tidep, aselmed i wid ipwalin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 14, 'D tucbiêt ay d tedheô i yimdanen leêmala n ccehwiyyat: tilawin, tarwa, iâammuôen ibararen n ddheb akked lfeîîa, iâawdiwen n ccetla, lmal, akal. Ayagi, d zzhu n tmeddurt n ddunit. Öebbi, $uôeS amkan lâali, n tu$alin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 15, 'Ini: "ad awen mle$ i yifen aya? I wid ipêezziben, ar Mass nnsen, leonanat, ddawat sen isaffen ppazzalen, degsen ad wekkôen, tilawin iûfan, akked llza s$uô Öebbi". Öebbi Ipwali imdanen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 16, 'wid iqqaôen: "a Mass nne$! Nekwni, s tidep, numen. Ihi, Semmeê a$ ibekkaven nne$, Sellek a$ seg uâaqeb n tmes".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 17, 'Iûebôiyen, imawlan n tidep, imvuâen, wid ipseddiqen, wid iste$fiôen di tafrara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 18, 'Icuhhed Öebbi ar ur illi ôebbi, siwa Neppa. Akken lmalayek, akked imawlan n tmusni. Ibedd i lmizan. Ur illi ôebbi, siwa Neppa, Uzmir, Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 19, 'Ih, ddin ar Öebbi d annuz. Ur mgarraden wid iwumi teppunefk Tezmamt, armi deffir n tisin n tussna $uôsen, wa iqheô wa. Wid inekôen issekniyen n Öebbi, ihi, Öebbi Ip$awal deg uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 20, 'Ma nuqmen k, ini: "unze$ aS i Öebbi. Akken, wid iddan yidi. Ini i wid iwumi teppunefk Tezmamt, akked at war tussna: "ma tunzem"? Ma unzen, ihi, pwanhan. Ma wexxôen, ay fellak siwa anabi. Öebbi Ipwali imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 21, 'Ih, wid inekôen issekniyen n Öebbi, u pna$en lambiyya, war ssebba, u pna$en wid seg yimdanen ippamôen lmizan, becceô iten s uâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 22, 'Widak, d wid iwumi mêan igiten nnsen di ddunit, di laxert. Ur sâin isellaken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 23, 'Day ur twalav ara wid iwumi ippunefk kra si Tezmamt, la ssuturen, i Tezmamt n Öebbi, aêuddu garasen? Sinna, ad iwexxeô urbaâ segsen, u nitni pnamaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 24, 'Ayagi, acku nnan: "ur a$ teppep tmes, siwa kra n wussan". I$uôô iten, di ddin nnsen, wayen id snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 25, 'Amek ihi, ma Njemmel iten, ass ideg, ur degs ccekk, yal yiwen ad i$ellet ayen ikseb, nitni ur ppudensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 26, 'Ini: "a Öebbi, Agellid n tgelda, Teppakev tagelda i win i K ihwan, Teppeksev tagelda i win i K ihwan, Tepâuzzuv win i K ihwan, Tesdulluv win i K ihwan. Lxiô deg ufus i K. Ih, Keçç, Tzemrev i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 27, 'Tessekcamev iv deg wass. Tessekcamev ass deg iv. Tessuffu$ev amuddir si lmegget. Tessuffu$ev lmegget seg umuddir. Tep$itiv win i K ihwan, war aktili".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 28, 'Lmumnin ur pparan ijehliyen d iêbiben nnsen, war lmumnin. Win ixedmen aya, ur illi, s wacemma, ar Öebbi. Kkes ed aêezzeb i têezzbem iman nnwen segsen. Iâaggen awen Öebbi s yiman iS. Tu$alin ar Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 29, 'Ini: "ama teffrem i illan deg idmaren nnwen, ne$ tessnaâtem t, Öebbi Iéôa t". Iéôa i illan deg igenwan, i illan di tmurt. Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 30, 'Ass ideg yal iman ad iaf irs ed, wayen ixdem n lxiô, akked wayen ixdem n cceôô, ad issirem a ppili, garas yides, tallit $ezzifen! Iâaggen awen Öebbi, af yiman iS. Öebbi d Umâin ar imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 31, 'Ini: "ma têemmlem Öebbi, ddut yidi. A kwen Iâuzz Öebbi, ad awen Isemmeê ibekkaven nnwen. Öebbi Ipsemmiê, Ipêunu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 32, 'Ini: "ssemêesset i Öebbi akked Umazan". Ma wexxôen, ihi Öebbi ur Iêemmel ara ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 33, 'Ih, Öebbi Ismenyaf, i imavalen, Adem, Nuê, tawacult n Ibôahim, tawacult n Âimôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 34, 'Wa iurew wa. Öebbi Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 35, 'Mi tenna tmeîîut n Âimôan: "a Mass iw! Wekkle$ aK ayen illan di tâabbuî iw, d lewkala, Eqbel s$uôi. Keçç, ih, d win Isellen, d Amusnaw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 36, 'Mi p id turew, tenna: "a Mass iw! Urwe$ p id d nnta". - Öebbi Iéôa, sennig akw, d acu d turew. Ddkeô, maççi am nnta. - "Nek semma$ as Meryem, rri$ p seddaw tecvaî iK, neppat akked tarwa s, mgal Cciîan imenfi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 37, 'Iôêeb yis Mass is, asteôêeb ilhan; Isgem ip, tigmi ilhan; Ikwellef ip i Zakariyya. Yal tikelt ara iôuê $uôes Zakariyya ar lmiêreb, a n iaf tesâa ôôeéq. Inna: "a Meryem! Ansi i m d ikka waya"? Tenna: "s$uô Öebbi. Öebbi, s tidep, Iôeééeq win i S ihwan, war aktili".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 38, 'D$a Zakariyya inuj $uô Mass is, inna: "a Mass iw! Efk iyi d, s$uôeK, tarwa ifazen. Keçç, s tidep, Tsellev i unuju".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 39, 'Mi ibedd, ipéalla di lmeêreb, ssawlent as d lmalayek: "Ibecceô ik Öebbi s Yaêia, d atebbet n wawal n Öebbi, d ssid, d azedgan, d nnbi, seg iâaôviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 40, 'Inna: "a Mass iw! Amek ara sâu$ aqcic? Ni$ wessre$, tameîîut iw d tiâiqeôt". Inna: "akka, Öebbi Ixeddem ayen i S ihwan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 41, 'Inna: "a Mass iw! Efk iyi d assekni". Inna: "assekni ik, ur tepmeslayev i medden krav wussan. As$al kan. Mmekti d aîas Mass ik, sbuccaâ iT tameddit, tafrara".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 42, 'Mi s nnant lmalayek: "a Meryem! Öebbi, s tidep, Ifren ikem, Izzazdeg ikem, Ismenyaf ikem i tlawin imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 43, 'A Meryem! Anez i Mass im, knu yaS, îîinez akked wid iîîinizen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 44, 'Ayagi si tmucuha i iffren, Nweêêa yak t. Ur telliv yidsen, mi jebden taseqqaôt, anwa segsen ara itkelfen $ef Meryem. Ur telliv yidsen mi mqellaâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 45, 'Mi s nnant lmalayek: "a Meryem! Öebbi, s tidep, Ibecceô ikem s wawal s$uôeS, ism is: lmasiê Âisa, mmi s n Meryem; mucaâ di ddunit akked laxert; seg iqôiben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 46, 'A d ipmeslay i medden, si dduê, am unqaqôi, ad yili seg iâaôviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 47, 'Tenna: "a Mass iw! Amek ara sâu$ aqcic, ur iyi innul urgaz"? Inna: "akka. Öebbi Ixelleq ayen i S ihwan. Ma Iseyya lameô, ad as Yini kan: "ili"! Ad yili".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 48, 'Ad as Isselmed Tazmamt, ûûwab, Tuôa, Linoil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 49, 'D amazan ar At Isôail: "ni$ nek usi$ d, $uôwen, s issekniyen s$uô Mass nnwen. Nek ad awen d xelqe$, s talaxt, ayen icban afôux, ad ûuve$ degs, ad iu$al d afôux, ma Ib$a Öebbi. Ad sseêlu$ ader$al, amuvin n lbeôû, a d ssidre$ lmeggtin, ma Ib$a Öebbi. Ad awen ini$ d acu teppeppem, akked wayen txezznem deg ixxamen nnwen. Deg waya, s tidep, d assekni i kunwi, ma d lmumnin ay tellam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 50, 'A d tebbte$ iyi d izwaren di Tuôa, ad awen êelle$ kra n wayen illan ipwagdel awen. Usi$ d, $uôwen, s ussekni, s$uô Mass nnwen. Ëezbet i Öebbi, a$et iyi awal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 51, 'Öebbi, s tidep, d Mass iw, u d Mass nnwen. Ihi, âabdet eP, d wagi ay d abrid uwqim".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 52, 'Mi israê Âisa tijehli s$uôsen, inna: "anwi ay d imâiwnen iw ar Öebbi"? Nnan as d lexwan: "nekwni d imâiwnen n Öebbi. Numen s Öebbi, eched ar nekwni d imvuâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 53, 'A Mass nne$! Numen s wayen id Tessersev, nedda d umazan, Aru ya$ seg inagan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 54, 'Undin. Iundi Öebbi. Öebbi Yif akw imendayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 55, 'Mi s Inna Öebbi: "a Âisa! Nek ad Ddme$ ôôuê ik, a k id Ssali$ $uôI, a k id Ssiferre$ seg wid ijehlen, ad Rre$, wid iddan yidek, sennig wid ijehlen, ar ass n tnekra". Sinna, tu$alin nnwen $uôI, ad Ëudde$, garawen, $ef wayen i$ef teppemgarradem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 56, 'Ma d wid ijehlen, a ten Âaqbe$ di ddunit, di laxert, aâaqeb aqeûêan. Ur asen ppilin isellaken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 57, 'Wanag wid iumnen u xeddmen ayen ilhan, ad asen Ifk arrazen nnsen. Öebbi ur Iêemmel ara imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 58, 'Ayagi i ak Nemmal seg issekniyen, akked usmekti uûwib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 59, 'Ih, amedya n Âisa, ar Öebbi, am umedya n Adem. Ixelq it seg wakal, sinna, Inna yas: "ili"! Illa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 60, 'Tidep, s$uô Mass ik. Ur ppili seg wid ipcukkun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 61, 'I win i k inumren fellas, deffir wayen i k id iusan n tussna, ini: "yyaw a nenced tarwa nne$, tarwa nnwen, tilawin nne$, tilawin nnwen, iman nne$, iman nnwen. Sinna, a nemmesgill, a nd²âu ad Ixzu Öebbi ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 62, 'Ih, tagi d tamacahup n tidep, ur illi ôebbi siwa Öebbi. Ih, Öebbi, Neppa, war ccekk, d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 63, 'Ma wexxren, ihi Öebbi Issen ifessaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 64, 'Ini: "a yAt Tezmamt! Yyaw ar wawal azduklan garane$ yidwen. A naâbed siwa Öebbi, ur aS nepcarak acemma; ur pparan, kra segne$ kra, d iôebbiten, war Öebbi". Ma wexxôen, init: "cehhdet ar nekwni d imvuâen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 65, 'A yAt Tezmamt! Acimi temnamarem $ef Ibôahim? Ur n risent Tuôa akked Linoil, armi deffir es, day ur tmeyyzem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 66, 'Kunwi, atan temnamarem $ef wayen tessnem. Ihi, acimi temnamarem $ef wayen ur tessinem? Öebbi Issen, kunwi ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 67, 'Ur illi Ibôahim d uday ne$ d amasiêi, maca illa d amvuâ imalen ar tidep. Ur illi seg imcurak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 68, 'Ih, imdanen iqeôben nezzeh ar Ibôahim, war ccekk, d wid i t ivefôen, akked Nnbi agi, akked wid iumnen. Öebbi d Bab n lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 69, 'Arbaâ, seg At Tezmamt, ib$a a kwen itlef. Ara telfen siwa iman nnsen, ur éôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 70, 'A yAt Tezmamt! Acimi tugim issekniyen n Öebbi, u kunwi tepwalim?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 71, 'A yAt Tezmamt! Acimi teslusum, i tidep, ayen idensen, u teppeffrem tidep, kunwi teêûam?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 72, 'Arbaâ, seg At Tezmamt, inna: "amnet mi iuli wass, s wayen id irsen ar wid iumnen, nekôet tameddit". Amendeô ma a d u$alen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 73, 'Ppamnet kan win ivefôen ddin nnwen. Ini: "ih, nnhaya d nnhaya n Öebbi. A ppeppunefk i yiwen am wayen i wen ippunefken". Ne$ a kwen namren af Mass nnwen. Ini: "lfevl, s tidep, deg ufus n Öebbi, Ippak it i win i S ihwan". Öebbi d Ajemmal, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 74, 'Iâateq aêunu S i win i S ihwan. Öebbi d Bab n lfevl ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 75, 'Seg wAt Tezmamt, illa win, xas teooiv as adrim aîas, ad ak t id irr. Illa wayev segsen, ma teooiv as adinar, ur ak t id ippara, alamma tezgiv $uôes. Akka, acku nitni nnan: "ur a$ d ppawven at war tussna". U ggaren d tikerkas $ef Öebbi, u nitni éôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 76, 'Xaîi! Win iîîfen di lemâahda s, u iêezzeb…ihi, Öebbi Iêemmel wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 77, 'Ih, wid ippa$en s lemâahda n Öebbi akked tgallit nnsen, ayen ôxisen, widak, ur ppawin amur di laxert, ur asen Ipmeslay Öebbi, ur ten id Ipmuqul, ass n tnekra, ur ten Izzizdig. Fellasen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 78, 'Ih, arbaâ segsen ssexsaôen Tazmamt s yilsawen nnsen, iwakken a p$ilem n Tezmamt, ayen ur nelli n Tezmamt. Qqaôen: "aya s$uô Öebbi", u neppa ur illi s$uô Öebbi. U qqaren tikerkas $ef Öebbi, u nitni éôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 79, 'Ur ippunefk ara i umdan iwumi Ifka Öebbi Tazmamt, ûûwab, u Irra t d nnbi, ad iu$al ad yini i medden: "ilit d imdanen iw, war Öebbi". Maca: "ilit d iselmaden, imi tesselmadem Tazmamt, u tlemdem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 80, 'Ur awen Iumeô ara a pperrem lmalayek akked lambiyya, d imawlan. Day awen Iameô tijehli, mbaâd ma tellam d imvuâen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 81, 'Mi Iîîef Öebbi laâqed n lambiyya: "s tidep, Fki$ awen si Tezmamt akw si ûûwab, sinna, iusa kwen id umazan, i itebbten ayen illan $uôwen. Amnet yis, âiwnet ep". Inna: "tâazmem u tqeblem, f waya, laâqed iW"? Nnan as: "naâzem". Inna: "ihi, cehhdet, Nek, yidwen, seg inagan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 82, 'Wid iwexxôen, deffir waya, nitni d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 83, 'Day b$an ddin ur nelli n Öebbi? U Neppa, unzen aS i illan di tmurt akked igenwan, b$an ne$ ugin. £uôeS, tu$alin nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 84, 'Ini: "numen s Öebbi, akked wayen id irsen $uône$, akked wayen id irsen ar Ibôahim, Ismaâil, Isêaq, Iaâqub, laâôac, ayen ippunefken i Musa, Âisa, akked lambiyya, s$uô Mass nnsen. Ur nesmenyaf yiwen degsen. Nekwni nunez aS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 85, 'Win ib$an ddin, war annuz, ur ipwaqbal s$uôes. U neppa, di laxert, seg imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 86, 'Amek ara Inhu Öebbi agdud inekôen deffir liman is, u cehhden ar Amazan d tidep, u iusa ten id ubeggen? Öebbi ur Inehhu agdud imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 87, 'Widak, aqeîîi nnsen d ddell s$uô Öebbi, d lmalayek, akked imdanen meôôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 88, 'Degs ad wekkôen; ur ippifsus fellasen uâaqeb, ur stiseren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 89, 'Kkes ed wid iu$alen nedmen, deffir waya, u xedmen ayen ilhan. Ih, Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 90, 'Ih, wid ijehlen, deffir liman nnsen, sinna, rnan di tijehli, ur tepwaqbal nndama nnsen. Widak d im$eôôqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 91, 'Ih, wid ijehlen, u mmuten d ijehliyen, ur ipwaqbal s$uô yiwen degsen, azal n tmurt n ddheb, a t id ifdu. I widak, aâaqeb aqeôêan, ur sâin amâiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 92, 'Ur teppawvem ar ppuba, d awez$i, alamma tseddqem seg wayen têemmlem. Kra n wayen tseddqem n cci, ihi, Öebbi Iéôa t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 93, 'Yal lqut illa iêell i At Isôail, siwa ayen igdel Isôail i iman is, uqbel a d ters Tuôa. Ini: "awit ed Tuôa, $eôt ep, ma tessawalem tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 94, 'Wid id igren tikerkas $ef Öebbi, deffir waya, nitni d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 95, 'Ini: "Inna d Öebbi tidep; ddut d ddin n Ibôahim, i imalen ar tidep, ur nelli seg imcurak".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 96, 'Ih, axxam amezwaru, i irsen i medden, war ccekk, d win n Bekka. Iôqa, d nnhaya i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 97, 'Degs issekniyen iberrzen; d axxam n Ibôahim. Win it ikecmen, atan di laman. I Öebbi, iwata ad êuoen medden s Axxam, ma zemren a t awven. Win iugin, ihi, Rebbi ur Iêwao ara imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 98, 'Ini: "a yAt Tezmamt! Acimi tnekôem issekniyen n Öebbi"? Öebbi d Anagi n wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 99, 'Ini: "a yAt Tezmamt! Acimi teîîeôôifem, wid iumnen, seg ubrid n Öebbi? Tessaramem t iaâwej, u kunwi d inagan". Ur I$fil Öebbi $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 100, 'A wid iumnen! Ma tu$em awal i urbaâ, seg wid iwumi teppunefk Tezmamt, a kwen rren d ijehliyen, deffir liman nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 101, 'Amek tnekôem, u kunwi $ôan awen d issekniyen n Öebbi, u, garawen, Amazan iS? Win iîîfen di Öebbi, ni$ ipwanha s abrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 102, 'A wid iumnen! Ëezzbet i Öebbi, akken Iklal aêezzeb. Ur ppemmtet alamma tunzem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 103, 'Eîfet akw di teêmilt n Öebbi, ur ppemfaôaqet. Mmektit ed ayen ikwen I$at Öebbi. Mi tellam d icenga, Issemlal ulawen nnwen. S l$it iS, tu$alem d atmaten. Tellam $ef rrif n maylellif n tmes, Isellek ikwen segs. Akka i wen Ipbeggin Öebbi issekniyen iS, amendeô ma a ppepwanhum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 104, 'Amar ad yili, segwen, lois i ineccden ar lxiô, ippamôen lqanun, itekksen ayen n dir. Widak d imerbaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 105, 'Ur ppilit am wid imfaôaqen, u mgarraden, deffir n tisin ubeggen $uôsen. I widak, aâaqeb aqeôêan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 106, 'ass ideg ara imlulen wudmawen, ara ibriken wudmawen. Wanag wid iwumi ara ibriken wudmawen nnsen: "tnekôem, deffir liman nnwen? Jeôôbet aâaqeb, ilmend n wayen tnekôem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 107, 'Wanag wid iwumi ara a imlulen wudmawen nnsen, ad ilin deg uêunu n Öebbi. Nitni, degs, ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 108, 'D wigi ay d issekniyen n Öebbi. Neqqaô ak ten id, s tidep. Ur Ib$i Öebbi ddens i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 109, 'N Öebbi i illan deg igenwan, i illan di tmurt. Ar Öebbi tu$alin n lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 110, 'Tifem akw leoyus id iff$en i medden. Teppamôem lqanun, teppekksem ayen n dir, tumnem s Öebbi. Ppif, i At Tezmamt, lemmer uminen. Garasen lmumnin; tegwti degsen d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 111, 'Cwiî kan ara kwen vuôôen. Ma nnu$en kwen, ad rewlen, sinna, ur sâun amâiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 112, 'Iwwet iten ddell anda ma llan, siwa wid iîîfen di teêmilt n Öebbi, u di teêmilt n medden. Lqan urrif n Öebbi, u te$li d tiggulelt fellasen. Ayagi, acku llan nekôen issekniyen n Öebbi, la neqqen lambiyya, war ssebba. Ayagi, imi âuûan u zgaren tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 113, 'Ur aâdilen. Illa lois, seg At Tezmamt, i iqqaôen issekniyen n Öebbi deg iv, u nitni kennun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 114, 'Umnen s Öebbi akked wass aneggaru, ppamôen lqanun, tekksen ayen n dir, pêirin ar lxiô. Widak seg iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 115, 'Ayen xedmen n lxiô, ur asen ipwankaô. Öebbi Issen wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 116, 'Ih, wid ijehlen, ur asen d ippawi acemma, ar Öebbi, wayla nnsen, ne$ tarwa nnsen. Widak d at tmes, degs ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 117, 'Amedya n wayen pseôôifen di tmeddurt n ddunit agi, am umedya n wavu, degs abruri. Iêuza iger n ugdud idensen iman is. Isnegr it. Ur ten Idnis Öebbi; d iman nnsen ay dennisen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 118, 'A wid iumnen! Ur pparat d iêbiben, wur nelli segwen. Ur zgalen a kwen hewwlen. B$an a kwen hejjnen. Ni$ ibda d lbwe$v seg imawen nnsen. Ayen iffren deg ulawen nnsen, i$elb it. Ni$ Nbeggen awen ed issekniyen, ma tepmeyyizem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 119, 'Atan kunwi d wid i ten iêemmlen, ur kwen êemmlen. Tumnem di Tezmamt, s lekmal is. Ma mmugren kwen, ad inin: "numen". Mi $aben, ad $eééen ivudan nnsen si zzâaf fellawen. Ini: "emmtet si zzâaf nnwen"! Ih, Öebbi Iéôa i illan deg idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 120, 'Ma iusa kwen id ise$, a ten isnu$ben. Ma tevôa yidwen tucmip, ad feôêen yis. Ma tûebôem, u têezbem, ur kwen teîîuôôu s wacemma, tandit nnsen. Ni$ Izzi Öebbi i wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 121, 'Mi teff$ev, ûûbeê zik, si twacult ik, temmalev i lmumnin imukan umennu$, Öebbi Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 122, 'Mi qôib feclent snat n trebbuyaâ nnwen, u Öebbi d Bab nnsent. Iwata i yal lmumen, ad ippkel $ef Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 123, 'Ni$ Iâiwen ikwen Öebbi di Badô, mi tellam tendellem. Ihi, êezzbet i Öebbi, amar a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 124, 'Mi tenniv i lmumnin: "day ur testeqnaâm ara, mi kwen Iâiwen Öebbi s krav igima n lmalayek, id irsen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 125, 'Xaîi, ma tûebôem u têezzbem, ma $ewwsen d fellawen, a kwen Iâiwen Mass nnwen, s smus igima n lmalayek ikkaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 126, 'Ur Iga akka Öebbi, siwa i ubecceô nnwen, ad rtiêen yis wulawen nnwen. Rrbeê s$uô Öebbi kan, Uzmir, Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 127, 'Iwakken ad Iôé arbaâ n wid ijehlen, ne$ a ten Iééaâ, ad u$alen nne$wnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 128, 'Ur k iaâna lameô s wacemma. Ad asen Issuref, ne$ a ten Iâaqeb, nitni d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 129, 'N Öebbi i illan deg igenwan, i illan di tmurt. Ipsemmiê i win i S ihwan. Ipâaqab win i S ihwan. Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 130, 'A wid iumnen! Ur teppet rrba ipzeggiden, tepzeggid. Ëezzbet i Öebbi, amar a prebêem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 131, 'Ëezzbet ilmend n tmes i ippuheggan i ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 132, 'A$et awal i Öebbi akked Umazan, amar ad yili uêunu fellawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 133, '£iwlet ar ssmaê s$uô Mass nnwen, akked Loennet iwsâan am tmurt akked igenwan. Teppuhegga d i wid ipêezziben,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 134, 'wid ipseddiqen - sâan ne$ xuûûen -, wid isnusun reffu, wid ipsemmiêen i medden - Öebbi Iêemmel lâuûam -,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 135, 'wid, ma xedmen tucmip, ne$ densen iman nnsen, a d mmektin Öebbi, ad ste$fôen $ef ibekkaven nnsen. Anwa Ipsemmiêen ibekkaven siwa Öebbi? Ur pgerninen deg wayen xedmen, u nitni éôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 136, 'Widak, akafi nnsen d ssmaê n Mass nnsen, akked leonanat, ddawat sen isaffen ppazzalen, degsen ad wekkôen. D arraz igerzen i wid issewqamen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 137, 'Âaddant tedyanin uqbel nnwen. Iniget di tmurt, walit amek tevôa d wid id iggaren tikerkas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 138, 'Wagi d abeggen i medden, d nnhaya akked unecced i wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 139, 'Ur ppifcilet, ur $webnet, d kunwi i iaâlayen, ma d lmumnin ay tellam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 140, 'Ma iêuza kwen lada, ni$ lada i t icban iêuza agdud. Ussan agi Nerra ten, ger medden, d tidwal, iwakken ad Yissin Öebbi wid iumnen, ad Iddem segwen inagan. Öebbi ur Iêemmel ara imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 141, 'Iwakken ad Ijeôôeb Öebbi wid iumnen, u ad Isqucc ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 142, 'Day t$ilem a pkecmem Loennet, wanag ur Iéôi ara Öebbi wid ijuhden segwen, ur Issin ara iûebôiyen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 143, 'Ni$ tepmennim tameppant, uqbel a p id temmagrem. Ni$ twalam p, kunwi tepmuqulem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 144, 'Muêemmed d Amazan kan. Ni$ âaddan imazanen, uqbel is. Ma immut ne$ ipwan$a, day a ppu$alem ar deffir? Win ara iu$alen ar deffir, ur iîîuôôu Öebbi s wacemma. Öebbi ad Ikafi wid isnemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 145, 'Ur ipmeppat umdan siwa ma Irad Öebbi, di lajel iuran. Win ib$an akafi n ddunit, ad as t Nefk. Win ib$an akafi n laxeôt, ad as t Nefk. A Nkafi wid isnemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 146, 'Acêal n lambiyya i innu$en, idda yidsen urbaâ iqwan, ur fcilen seg wayen iten issaâtben, deg ubrid n Öebbi, ur xuzen, ur fkin mayna. Öebbi Iêemmel iûebôiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 147, 'Awal nnsen, siwa mi nnan: "a Mass nne$! Semmeê a$ ibekkaven nne$, akked tugut nne$ di lameô nne$. Tebbet isurifen nne$, Sserbeê ane$ $ef ugdud ijehliyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 148, 'Ifka yasen Öebbi akafi n ddunit, akked ukafi lâali n laxert. Öebbi Iêemmel lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 149, 'A wid iumnen! Ma tu$em awal i wid ijehlen, a kwen rren ar deffir, a ppu$alem txesôem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 150, 'Xaîi! Öebbi d Bab nnwen. Neppa, Yif akw imâiwnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 151, 'A Nessekcem tugdi deg ulawen n wid ijehlen, imi curken i Öebbi, ayen iwumi ur d irs ara udabu. Axxam nnsen d times. A yir tanezdu$t i imednas!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 152, 'Ni$ Issawel awen Öebbi tidep, di lemâahda S, mi ten tesnegrem, s tsriê iS. Armi, mi tfeclem, temnamarem f lameô, taâûam mbaâd ma Issken awen d ayen têemmlem. Garawen wid ib$an ddunit, garawen wid ib$an laxert. Sinna, Issebâad ikwen fellasen, iwakken a kwen Ijeôôeb. Ni$ Isemmeê awen. Öebbi d Bab n lfevl i lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 153, 'Mi tulim ur d tezzim, u Nnbi inecced ikwen ar ineggura nnwen. Ineûûef awen a$ilif s wayev, iwakken ur t$webnem $ef wayen i wen iôuêen, akked wayen ikwen iu$en. Öebbi Iéôa ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 154, 'Sinna, deffir u$ilif, Issers awen d laman, ives id i$lin $ef urbaâ segwen. Ni$ arbaâ pêebbiôen $ef yiman nnsen, nnwan, $ef Öebbi, ayen ur nelli d tidep, nnwaya n at war tussna. Qqaôen: "day illa wayen i $ iaânan, di lameô"? Ini: "s tidep, lameô akw i Öebbi". Teffren, deg iman nnsen, ayen ur ak mmalen. Qqaôen: "lemmer illi wayen i $ iaânan, di lameô, ur nepwan$a dagi". Ini: "xas ma tellam deg ixxamen nnwen, wid i$ef tura tmen$iwt, a ten tawev s imîeôêen nnsen. Iwakken ad Ijeôôeb Öebbi i illan deg idmaren nnwen, ad Izzizdeg i illan deg ulawen nnwen. Öebbi Iéôa i illan deg idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 155, 'Ih, wid segwen iwexxôen asmi mlalent trebbuyaâ, d Cciîan kan iten iccacven, ilmend n kra n wayen kesben. Ni$ Isemmeê asen Öebbi. Akka, Öebbi Ipsemmiê, Iêellem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 156, 'A wid iumnen! Ur ppilit am wid ijehlen. Nnan i watmaten nnsen iunagen di tmurt, ne$ ipna$en: "lemmer llin $uône$, ur mmuten, ur twan$an". Ad Irr Öebbi, ayagi, d aneggaf deg ulawen nnsen! Öebbi Issidir, Ineqq. Öebbi Ipwali ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 157, 'Ma tepwan$am deg ubrid n Öebbi, ne$ temmutem, ssmaê n Öebbi akked uêunu, war ccekk, ifen ayen la jemâan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 158, 'Ma temmutem ne$ tepwan$am, war ccekk, ar Öebbi ara tepwafesrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 159, 'S uêunu n Öebbi, têelmev $uôsen. Lemmer tqeûêev, tes$aôev ul ik, ad baâden fellak. Semmeê asen, ssuter ad ppusemmêen, ciweô iten $ef lameô. Mi tseyyiv, ppkel $ef Öebbi. Ih, Öebbi Iêemmel wid ippkalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 160, 'Ma Iâiwen ikwen Öebbi, ur kwen irennu yiwen. Ma Iooa kwen, anwa illan a kwen iâiwen, deffir eS? £ef Öebbi ara ppeklen lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 161, 'Ur issefk ara i nnbi ad idnes. Win idensen, a d ias s wayen idnes, ass n tnekra. Sinna, yal wa, ad as ippunefk wayen ikseb. Nitni, ur ten pmeôôiôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 162, 'Day win iddan d llza n Öebbi am win isebebben urrif n Öebbi, u tanezdu$t is d Loahennama? A taggara tucmip!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 163, 'Ur aâdilen ar Öebbi. Öebbi Ipwali acu xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 164, 'Ni$ Öebbi I$at lmumnin, mi sen d Iuzen Amazan segsen, immal asen issekniyen iS, izzizdig iten, isseêfav asen Tazmamt akked ûûwab, ulamma llan, zik, di ttelfan n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 165, 'Ma tu$em tiyta, ni$ terram p berdayen. Tennam: "ansi waya"? Ini: "aya seg iman nnwen". Öebbi, s tidep, Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 166, 'Ayen ikwen iwwten, ass n temlilit n trebbuyaâ, s tsriê n Öebbi. Iwakken ad Iéeô anwi ay d lmumnin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 167, 'u ad Iéeô anwi ay d ixabiten. Nnan asen: "yyaw, nna$et deg ubrid n Öebbi, ne$ éedmet". Nnan: "lemmer nessin a nenna$, yili nedda n yidwen". Assen, nitni, ar tijehli, ne$ $eô liman, ay qeôben kteô. Qqaren, s yimawen nnsen, ayen ur nelli deg ulawen nnsen. Öebbi Yif akw akken Iéôa ayen teffren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 168, 'Wid innan i watmaten nnsen, u nitni qqimen: "lemmer i $ ssemêessen, ur pwan$en". Ini: "sdarit iman nnwen si tmeppant, ma tessawalem tidep ".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 169, 'Ur p$ili mmuten wid ipwan$an deg ubrid n Öebbi. Xaîi, d imuddiren. Ad ppuôeéqen ar Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 170, 'Ad feôêen s wayen i sen Ifka Öebbi, si lfevl iS. Zhan, imi wid deffir sen, mazal ur ten id nelêiq, ur ppagawaden, ur $weblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 171, 'Zhan s l$it n Öebbi, akked lfevl. Öebbi ur Iveggiâ arraz n lmumnin;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 172, 'wid id ijawben i Öebbi akked Umazan, mbaâd ma sâaddan lêif. Arraz ameqwôaêan i wid, segsen, ixeddmen ayen ilhan, u êezzben;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 173, 'wid iwumi nnan medden: "ni$ mlalen fellawen imdanen, ihi, agwadet pen". D$a isnerna liman nnsen, nnan: "Iqadd a$ Öebbi, Awkil Amxallef".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 174, 'U$alen d s l$it n Öebbi akked lfevl, ur ten innul cceôô; ddan d llza n Öebbi. Öebbi d Bab n lfevl ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 175, 'Akka kan ay d Cciîan. Issagwad s imeddukwal is. Ur ten ppagwadet, agwadet iyI, ma d lmumnin ay tellam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 176, 'Ur k $webbnen wid ip$awalen ar tijehli. Nitni, s tidep, ur vvuôôen Öebbi, s wacemma. Ib$a Öebbi ur asen Iteg amur di laxert. Fellasen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 177, 'Ih, wid iu$en tijehli s liman, ur vvuôôen Öebbi s wacemma. Fellasen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 178, 'Ur êeppben wid ijehlen, ar telha yasen, lmudda i sen Nefka. Nefka yasen kan lmudda, iwakken ad rnun ibekkaven. Fellasen aâaqeb isdullun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 179, 'Ur illi di leb$i n Öebbi, ad Ioo lmumnin di liêala nnwen, alamma Ifrez axabit seg umâin. Ur illi di leb$i n Öebbi, ad awen Imel tabavnit. Maca, Iferren Öebbi wid i S ihwan, d imazanen iS. Ihi, amnet s Öebbi akked imazanen iS. Ma tumnem, u têezzbem, a ppawim arraz ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 180, 'Ur êeppben wid ipcuêêun deg wayen i sen Ifka Öebbi, si lfevl iS, ard lxiô nnsen. Xaîi, d cceôô nnsen. Ayen cuêêen a ten iarez seg umgaôv, ass n tnekra. I Öebbi, lweôt n tmurt akked igenwan. Öebbi Iéôa ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 181, 'Ni$ Isla Öebbi i wawal n wid innan: "s tidep, Öebbi d igellil, nekwni d isâayen". A Naru ayen nnan, akked wayen n$an n lambiyya, war ssebba. Ad asen Nini: "jeôôbet aâaqeb ujajiê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 182, 'Ayagi, ilmend n wayen xedmen ifassen nnwen. Öebbi ur Ipdennis imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 183, 'Wid innan: "Ih, Öebbi Iâahed a$ ur neppamen s Umazan, alamma issenâat a$ d asfel, ara teçç tmes". Ini: "ni$ usan kwen id imazanen, uqbel iw, s ubeggen, akw s wayen d tennam. Ihi, acimi i ten ten$am, ma tessawalem tidep"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 184, 'Ma skaddben k, ni$ skaddben imazanen, uqbel ik, usan d s ubeggen, Ihellilen, akked Tezmamt timnewweôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 185, 'Yal iman ad ijeôôeb tameppant. Ass n tnekra, ad awen ippunefk, kan, warraz nnwen. Win isellken si tmes, ikecmen Loennet, ni$ irbeê. Tameddurt, di ddunit, d zzhu kan ip$uôôun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 186, 'A ppeppujeôôbem deg wayla nnwen akked yiman nnwen. Ad wwten aîas degwen, wid iwumi teppunefk Tezmamt, uqbel nnwen, akked imcurak. Ma tûebôem u têezzbem, ayagi, s tidep, d ayen isselêayen lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 187, 'Mi Iîîef Öebbi laâqed n wid iwumi teppunefk Tezmamt: "a p tbeggnem i medden, ur p teppeffrem". Rran p deffir izugar nnsen, u$en yis, ayen irxisen. I icmet wayen u$en!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 188, 'Ur p$ili ad sellken, seg uâaqeb, wid ifeôêen s wayen fkan, u b$an a ten ccekôen $ef wayen ur xdimen. Fellasen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 189, 'N Öebbi tagelda n tmurt akked igenwan. Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 190, 'Ih, di lxelq n tmurt akked igenwan, akked umgirred n yiv akked wass, d issekniyen i uâqilen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 191, 'Wid id ismektayen Öebbi s ibeddi, s i$imi, s tuééla. Pmeyyizen lxelq n tmurt akked igenwan. A Mass nne$! Ur Texliqev aya d aêerfi. Gedha s yiseK! Sellek a$ seg uâaqeb n tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 192, 'A Mass nne$! Ni$, s tidep, Keçç, Texziv win Teskecmev ar tmes. Ur llin wid ara isellken imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 193, 'A Mass nne$! S tidep, nesla i uneccad, la inecced ar liman: "amnet s Mass nnwen"! Numen. A Mass nne$! Semmeê a$ ibekkaven nne$, Kkes ane$ tucmitin nne$, Ssiwev a$, ar ssmaê iK, akked wid zeddigen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 194, 'A Mass nne$! Efk ane$ ayen i a$ Tâahdev s imazanen iK; ur a$ Xezzu ass n tnekra. Keçç, s tidep, ur Tzeglev lemâahda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 195, 'Irra yasen Mass nnsen: "Nek ur Veggiâe$ igi n win, segwen, issewqamen, d ddkeô ne$ d nnta. Wa ikka d seg wa. Wid iunagen, u ssuff$en ten seg ixxamen nnsen, iâatben deg ubrid iW, innu$en, ipwan$an, war ccekk, ad asen Kkse$ tucmitin nnsen, a ten Skecme$ ar leonanat, ddawat sen isaffen ppazzalen". D akafi s$uô Öebbi. Öebbi, $uôeS akafi amxallef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 196, 'Ur k ipqelliq lexdaâ n wid ijehlen di temdint.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 197, 'Cwiî n zzhu, sinna, axxam nnsen d Loahennama. A yir usu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 198, 'Maca, i wid iêezzben i Mass nnsen: leonanat, ddawat sen isaffen ppazzalen, degsen ad wekkôen, d inebgawen n Öebbi. U d wayen illan ar Öebbi, d amxallef i izedganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 199, 'Ih, seg wAt Tezmamt, wid iumnen s Öebbi, s wayen akw i wen ed irsen, akked s wayen i sen d irsen. Unzen i Öebbi, ur u$en ara s issekniyen n Öebbi, ayen ôxisen. I widak, arraz s$uô Mass nnsen. Ni$ Öebbi Ip$awal deg uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 200, 'A wid iumnen! Üebôet, aznet ûûbeô, begset, êezzbet i Öebbi, amar a prebêem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 1, 'A yimdanen! Ëezzbet i Mass nnwen, ikwen Ixelqen seg yiwen n lxelq, u Ixelq ed segs ayugan is. Issuffe$ ed, segsen, aîas n yirgazen akked tlawin. Ëezzbet i Öebbi i$ef tepmesteqsayem, akw i tâabbuvin. Öebbi, s tidep, Izga Iquôaâ kwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 2, 'Efket ayla nnsen i igujilen, ur pparat dduni deg umkan n lâali. Ur pparat ayla nnsen d ayla nnwen. Ih, wagi d abekkav ameqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 3, 'Ma tugadem ur tweznem ara ar igujilen, a$et ayen i wen ihwan n tlawin: snat, kravt, kuét. Ma tugadem ur tessaâdalem ara, yiwet kan, ne$ taklatin nnwen. Akka i iwulem, ur ppakwret.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 4, 'Efket tuççit nnsent i tlawin, d tikci. Ma rrant awen d kra segs, s leb$i nnsent, ççet ep, s lfeôê akked llza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 5, 'Ur ppaket i ije$lufen ayla nnwen, win i wen Ifka Öebbi i tmeddurt. Öeéqet pen segs, sselset pen, ééiédet awal nnwen $uôsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 6, 'Jeôôbet igujilen, alamma bbwven i jjwao. Ma tufam ten éewôen, efket asen ayla nnsen. Ur ten teppet s uveggaâ d usexseô, uqbel ad im$uôen. Ameôkanti ad iêezzeb, ame$bun ad içç s lekyasa. Mara sen tefkem ayla nnsen, s inagan fellas. Nesteqnaâ s Öebbi i leêsab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 7, 'I yirgazen, amur seg wayen d ooan imawlan akked llzem. I tlawin amur seg wayen d ooan imawlan akked llzem. Ama cwiî, ne$ aîas, d amur ilezmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 8, 'Ma êedôen, i ufôaq, llzem, igujilen, igellilen, ôeéqet pen segs, tinem asen awal uûwib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 9, 'Ad agwaden wid id iooan, deffir sen, tarwa tagellilt. Ad agwaden fellasen. Ad êezzben i Öebbi, s wawal iweznen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 10, 'Ih, wid iteppen, s ddens, ayla igujilen, la teppen kan times deg iâabbav nnsen, ad pwagren deg ujajiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 11, '£ef tarwa nnwen, Iweûûa kwen Öebbi: i uqcic amur n snat tullas. Ma llant sennig snat n tullas, nnsent amur wis kué n lweôt. Ma yiwet i illan, ines uzgen. I imawlan is, i yal wa, amur wis sdis n wayen id iooa, ma isâa mmi s. Ma ur isâa ara mmi s, u weôten t imawlan is, amur wis kué i immas. Ma isâa atmaten, i immas amur wis sdis, kkes ed ayen ippuseôfen ne$ îlabat. Imawlan nnwen, arraw nnwen, ur teéôim ara menyif iten, akken i kwen nefâan. D aêeppem n Öebbi. Öebbi, s tidep, Izga d Bab n ûûwab, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 12, 'Nnwen uzgen n wayen id ooant tlawin nnwen, ma ur sâint ara tarwa. Ma sâant mmit sent, i kunwi amur wis kué n wayen id ooant, kkes ed ayen ippuseôfen ne$ îlabat. I nitenti, amur wis kué n wayen id teooam, ma ur tesâim ara mmit wen. Ma tesâam mmit wen, i nitenti amur wis îam n wayen id teooam, kkes ed ayen ippuseôfen ne$ îlabat. Ma d argaz awêid ne$ d tameîîut tawêiî, ma isâa agmat ne$ taultmap, i yal wa segsen, amur wis sdis. Ma deg waîas ay llan, ad feôqen amur wis krav, war ccqa, kkes ed ayen ippuseôfen ne$ îlabat. D aweûûi n Öebbi. Öebbi Iéôa, Iêellem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 13, 'D tigi ay d tilisa n Öebbi. Win issemêessen i Öebbi akked Umazan iS, a t Issekcem ar leonanat, ddawat sen isaffen ppazzalen, degsen ad wekkôen. D wagi ay d rrbeê ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 14, 'Win iâuûan Öebbi akked Umazan iS, izegren tilas iS, a t Issekcem ar tmes, degs ad iwekkeô, ad isâaddi aâaqeb isdullun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 15, 'I tid ixedmen lâaô di tlawin nnwen, awit ed, fellasent, kué inagan nnwen. Ma cehhden d, kemnet pent di texxamin, alamma teddem itent tmeppant, ne$ Iga yasent Öebbi abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 16, 'Wid segwen it ixedmen, âaqbet pen. Ma nedmen, u xedmen ayen ilhan, anfet asen. Öebbi, s tidep, Izga Issuruf, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 17, 'Issuruf kan Öebbi i wid ixedmen cceôô ur éôin, sinna, steôoâen, war laâvil. Widak, ad asen Issuref Öebbi. Öebbi Izga d Bab n ûûwab, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 18, 'Ur illi usuref i wid ixedmen tucmitin. Alamma, mi d tusa yiwen tmeppant, a d yini: "nek steôoâe$ tura". Akken, wid immuten u nitni d ijehliyen. Widak, Nhegga yasen d aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 19, 'A wid iumnen! Ur awen iêell ara a pweôten tilawin, ur qbilent, ne$ ad asent tekksem jjwao, iwakken a ppawim amur seg wayen i sent tefkam, siwa ma xedment lâaô ibanen. Illit yidsent, s lqanun. Ma tkeôhem tent, ahat tkeôhem ayen ideg Irra Öebbi lxiô meqqwôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 20, 'Ma teb$am a pbedlem tameîîut s tayev, u tefkam tuççit i yiwet, ur as tekkset acemma. Ma tekksem, d ayen n dir u d abekkav n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 21, 'Amek ara tekksem imi temyekcamem, u bbwint s$uôwen laâqed meqqwôen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 22, 'Ur ppa$et tilawin i u$en ibabaten nnwen, kkes ed ayen iâaddan. Ayagi, s tidep, d lâaô, d dduni, d yir brid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 23, 'Pwadeglent awen tyimmatin nnwen, issit nnwen, tissetmatin nnwen, tiâamtiwin nnwen, tixaltitin nnwen, issit n ugmat, issit n tweltmap, tiyimmatin nnwen i kwen issuîîven, tissetmatin nnwen ukud teîîvem, tivegwalin nnwen, issit id tessekrem n tlawin nnwen ukud tcerkem usu - ma ur tecrikem ara usu, ulac u$ilif -, tilawin n warraw id turwem. Ur zdukulet snat tsetmatin, kkes ed ayen iâaddan, - Öebbi, s tidep, Izga Ipsemmiê, Ipêunu -,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 24, 'tilawin ijewoen, kkes ed taklatin nnwen. D Öebbi i wen Iuran. Iêell awen, deffir waya, a ppezhum s wayla nnwen, s lewqama, maççi s lemveôôa. Tid, segsent, ukud tezham, fket asent arrazen nnsent, d aêeppem. Ur illi u$ilif fellawen deg wayen i$ef temwafaqem, deffir uêeppem. Öebbi, s tidep, Izga d Bab n ûûwab, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 25, 'Wid, segwen, ur nezmir ara ad a$en tiêuôiyn iumnen, ad a$en si teklatin nnwen, tid iumnen. Öebbi Yif akw akken Iéôa liman nnwen. Wa seg wa. A$et pent, s tsriê n twacult nnsent, fket asent arrazen nnsent, s lqanun. D tizedganin, maççi d tucmitin, ne$ d tid iff$en abrid. ÛMa u$alent d tiêuôiyn, sinna xedment lâaô, aâaqeb nnsent azgen n win n tiêuôiyn. Akka i win, segwen, ippagwaden abekkav. Ma tûebôem, ppif i kunwi. Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 26, 'Ib$a Öebbi ad awen Ibeggen, a kwen Iawi d wansayen n wid i kwen id izwaren, a d Iu$al $uôwen. Öebbi d Bab n ûûwab, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 27, 'Ib$a Öebbi ad awen Issuref. B$an wid iteddun d lemcihwat, a pmalem lmil abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 28, 'Ib$a Öebbi ad Issifes fellawen. Ipwaxleq umdan d uôhif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 29, 'A wid iumnen! Ur ppemyeççat ayla garawen, d aêerfi, kkes ed ma d ssuq i$ef temwafaqem. Ur neqqet iman nnwen. Ih, Öebbi Izga Ipêunu fellawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 30, 'Win ixedmen akka, s zzkaôa akked ddens, deqqal a t Nger ar tmes. Ayagi, izga d ayen isehlen i Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 31, 'Ma tjunbem ayen meqqwôen, seg wayen i wen ipwakksen, a Nessuref i tucmitin nnwen, a kwen Nessekcem anekcum ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 32, 'Ur ppasmet, ma Ismenyaf Öebbi kra i wiyav. I yirgazen, amur seg wayen kesben; i tlawin, amur seg wayen kesbent. Ssutret i Öebbi, si lfevl iS. Ih, Öebbi Izga Issen yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 33, 'Nerra, i yal wa, iweôôaten n wayen d ooan imawlan, llzem, akked wid ukud tâaqqdem. Efket asen amur nnsen. Öebbi Izga Ipwali yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 34, 'Irgazen ad ûunen tilawin, imi Ismenyafa Öebbi kra $ef kra, ilmend n wayen pseôôifen seg wayla nnsen. Tilawin imaânen, iunzen, ipêaraben $ef sser n wayen Iêureb Öebbi. Tid s$uô tugadem tuêsift, nna$et pent, âazlet pent deg imîeôêen, ôebbit pent. Ma u$ent awen awal, ur tent ppawvet. Ih, Öebbi Izga Âalay, Meqqweô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 35, 'Ma tugadem ad mfaôaqen, aznet amêaddi n twacult n neppa, wayev n twacult n neppat. Ma b$an ad mûalaêen, a ten Issemâaceô Öebbi. Öebbi, s tidep, Izga Âalay, Iéôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 36, 'Âabdet Öebbi, ur aS pcaraket acemma. Elhut ar lwaldin, ar llzem, ar igujilen, ar ime$ban, ar loaô i wen ippilin akked win ur awen neppili, ar umeddakwel ar yidis, ar iminig, ar waklan nnwen. Öebbi, s tidep, ur Iêemmel ara amzuxi, imnefxi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 37, 'wid ipcuêêun u ppamôen i medden ccêa, iteffren ayen i sen Ifka Öebbi, si lfevl iS - Nhegga d, i ijehliyen, aâaqeb isdullun -;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 38, 'wid ipûeôôifen ayla nnsen, iwakken a ten id walin medden, ur uminen s Öebbi akked wass aneggaru; wid isâan Cciîan d amsaâaf. A yir amsaâaf!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 39, 'Acu ar asen iôuêen, lemmer uminen s Öebbi akked wass aneggaru, u ûeôôfen seg wayen is iten Iôéeq Öebbi? Öebbi Izga Issen iten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 40, 'Öebbi, s tidep, ur Idennes s wayen iwzen ubelkim. Ma tebbwiv d ise$, a t Irr d sin, a d Ifk, s$uôeS, arraz ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 41, 'Amek, ihi, ma Nusa, si yal lois, s unagi; ma Nusa, yissek, d anagi $ef wigi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 42, 'Assen, wid ijehlen u âuûan Nnbi, ad ssirmen a ten tesseblaâ tmurt. Ur teffren awal i Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 43, 'A wid iumnen! Ur pqeôôibet ar téallit ma tsekôem, alamma teéôam acu d teqqaôem. Ne$ ma tellam s loanaba - siwa ma la teppinigem -, alamma tessardem. Ma tuvnem ne$ tunagem, ne$ iusa d yiwen segwen si ccicma, ne$ tennulem tilawin, ur tufim aman, ddmet akal zeddigen, sâaddit ep $ef udmawen nnwen d ifassen nnwen. Ih, Öebbi Izga Ipqili, Ipsemmiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 44, 'Day ur twalav ara wid iwumi ippunefk kra si Tezmamt? Ppa$en d ttelfan, b$an a ppennetlafem seg ubrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 45, 'Öebbi Yif akw akken Issen icenga nnwen. Nesteqnaâ s Öebbi d Bab. Nesteqnaâ s Öebbi d Amâiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 46, 'Seg udayen, wid iîîeôôifen awalen seg inumak nnsen. Qqaôen: "nesla, naâûa, ssemêes i wayen ur d nnin, muqel a$ d". Ssaâwjen ilsawen nnsen, kkaten di ddin. Lemmer, s tidep, qqaôen: "nesla, nunez, ssel, muqel a$ d", war ccekk, yif it i nitni, u iwqem kteô. Maca, Ixza ten Öebbi, ilmend n tijehli nnsen. Ur ppamnen, siwa ixeîîayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 47, 'A wid iwumi teppunefk Tezmamt! Amnet s wayen id Nessers, d atebbet n wayen illan $uôwen, uqbel a Nes$ab udmawen, a ten Nerr ar deffir, ne$ a ten Nexzu, akken Nexza at Ssebt. Lameô n Öebbi ad iâaddi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 48, 'Öebbi, s tidep, ur Ipsemmiê mara S carken. Ipsemmiê ayen nniven, i win i S ihwan. Win icurken i Öebbi, ni$ ibbwi abekkav abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 49, 'Day ur twalav ara wid iran iman nnsen zeddigit? Maca, Öebbi Izzizdig win i S ihwan. Ur pwadensen ula s uclem utemôiw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 50, 'Wali amek id gren tikerkas $ef Öebbi. Ayagi kan, d abekkav n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 51, 'Day ur twalav ara wid iwumi ippunefk kra si Tezmamt? Umnen s iôebbiten n tkerkas, u qqaôen, i wid ijehlen, ar widak pwanhan sennig wid iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 52, 'Widak d wid Ixza Öebbi. Wid ara Ixzu Öebbi, ur asen teppafev amâiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 53, 'Ne$ sâan kra si tgelda, d$a ur ppaken i medden ula d atemôiw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 54, 'Ne$ êesden medden, deg wayen i sen Ifka Öebbi, si lfevl iS. Ni$ Nefka, i twacult n Ibôahim, Tazmamt, ûûwab. Nefka yasen tagelda tameqwôaêant.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 55, 'Segsen wid iumnen yis, segsen wid i p iugin. Beôka ten ajajiê n Loahennama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 56, 'Ih, wid inekôen issekniyen nne£, deqqal a ten Nerr ar tmes. Mi ô$an igwelman nnsen, ad asen d Nenûef s igwelman nniven, ad jeôôben aâaqeb. Ih, Öebbi Izga d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 57, 'Wid iumnen, ixeddmen ayen ilhan, a ten Nessekcem ar leonanat, ddawat sen isaffen ppazzalen, din ad wekkôen, i lebda. I nitni, degsen, tilawin zeddigen; a ten Nawi ar tili isburrun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 58, 'S tidep, Iumeô awen Öebbi a pperrem lamanat i imawlan nnsent, a pêuddem s lmizan, ma têuddem ger medden. Ih, ilha wayen u$uô i kwen Ipnabi Öebbi. Öebbi, s tidep, Izga Issel, Ipwali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 59, 'A wid iumnen! A$et awal i Öebbi. A$et awal i Umazan akked imawlan n lameô segwen. Ma temgarradem $ef lêaoa, erret ep ar Öebbi akked Umazan, ma tumnen s Öebbi akked wass aneggaru. Ppif akka, d ppawil amxallef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 60, 'Day ur twalav ara wid iumnen, zi$emma, s wayen ik ed irsen, d wayen id irsen, uqbel ik? B$an aêuddu iôebbiten n tkerkas, ulamma pwamôen a ten nekôen. Ib$a Cciîan a ten itlef ttelfan u$miq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 61, 'Ma nnan asen: "aset ed ar wayen id Issers Öebbi, akw ar Umazan", a pwaliv ixabiten wexxôen ak, ugin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 62, 'Amek ihi, ma u$en tiyta, ilmend n wayen xedmen ifassen nnsen, sinna, a d asen $uôek, ad ggalen s Öebbi: "neb$a kan lewqama akked lembwafqa".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 63, 'Widak, Iéôa Öebbi i illan deg ulawen nnsen. Ihi, îîixeô asen, nabi iten, meslay iten, $ef iman nnsen, s wawal iqenâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 64, 'Ur d Nuzen Amazan, siwa kan iwakken ad as a$en awal, ma Irad Öebbi. Wid idensen iman nnsen, ma usan k id, d$a ssutren ssmaê i Öebbi, u issuter Umazan ad ppusemmêen, ad afen Öebbi Issuruf, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 65, 'Xaîi! S Mass ik, ur ppamnen, alamma rran k d amêaddi, deg wayen i$ef mgarraden. Sinna, ur ppafen, deg iman nnsen, ara ten ihewwlen, deg wayen id têuddev. Ad anzen yal annuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 66, 'Lemmer i sen Nuri: "mmin$et"! Ne$ "ff$et seg ixxamen nnwen"! Ur p xeddmen, siwa kra segsen. Ppif, i nitni, lemmer xdimen ayen u$uô pwanecden. D atebbet uûwib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 67, 'Imiren ad asen Nefk, s$uône£, arraz ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 68, 'A ten Nenhu s abrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 69, 'Wid ippa$en awal i Öebbi akked Umazan, widak atnan ar wid I$at Öebbi ger lambiyya, wid issdaqen, ccuhada, ûûalêin. Ay telha tdukli d wigi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 70, 'Wagi d lfevl s$uô Öebbi. Nesteqnaâ s Öebbi d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 71, 'A wid iumnen! Ëadret iman nnwen! èéedmet d igrawen, ne$ ééedmet akw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 72, 'Ih, garawen win ipâaîîilen. Ma tu$em tiyta, ad yini: "I$at iyi Öebbi, ur lli$ yidsen, d anagi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 73, 'Ma iusa kwen id lfevl s$uô Öebbi, ad yini, war ccekk, amzun ur telli tegmap garawen: "a lemmer lli$ yidsen, ad rebêe$ rrbeê ameqwôaêan"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 74, 'Ad nna$en deg ubrid n Öebbi wid izznuzun tameddurt n ddunit i laxert. Win ipna$en deg ubrid n Öebbi, immut ne$ irbeê, ad as Nefk arraz ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 75, 'Acu kwen iu$en, ula tepna$em ara deg ubrid n Öebbi? Uôhifen seg irgazen, tilawin, igwerdan, i la iqqaôen: "a Mass nne$! Ssuffe$ ane$ si temdint agi ized$en imednas. Efk ane$ d bab s$uôeK, Efk ane$ d asettaô s$uôeK".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 76, 'Wid iumnen pna$en deg ubrid n Öebbi. Wid ijehlen pna$en deg ubrid iôebbiten n tkerkas. Nna$et imeddukwal n Cciîan. Ni$ tiêeôci n Cciîan d tuôhift.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 77, 'Day ur twalav ara wid iwumi nnan: "brut i ifassen, ééalet, zekkit"? Mi sen iura umennu$, arbaâ, segsen, ugaden imdanen, tugwdi n Öebbi, ne$ tugwdi i p i$elben. Qqaôen: "a Mass nne$! Acimi i $ Turiv amennu$? A lemmer i t Teswexxôev cwiî"! Ini: "zzhu n ddunit d amnuc, tif it laxert i win ipêezziben. Ur tepwadensem ula s yiclem utemôiw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 78, 'Anda tellam a kwen id tawev tmeppant, xas ma tellam di lebôuo ioehden. Ma iusa ten id yise$, ad inin: "wagi s$uô Öebbi". Ma tusa ten id tucmip, ad inin: "tagi s$uôek". Ini: "akw s$uô Öebbi". Acu iu$en agdud agi, ur izmir ad ifhem awalen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 79, 'Yal ise$ i k id iusan, s$uô Öebbi. Yal tucmip i k id iusan, s$uô iman ik. Nuzen ik id i medden, d Amazan. Nesteqnaâ s Öebbi d Anagi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 80, 'Win iu$en awal i Umazan, iu$ awal i Öebbi. Win iwexxôen, ur k id Nuzen d amêareb nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 81, 'Qqaôen: "annuz"! Mi k îîaxxôen, ad iêekku deg iv, urbaâ segsen, ayen ur d tenniv. Öebbi Ipparu ayen êekkun deg iv. Wexxeô asen, ppkel $ef Öebbi. Nesteqnaâ s Öebbi d Awkil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 82, 'Day ur pmeyyizen ara Leqwôan? Lemmer illi si war Öebbi, ad afen degs aîas n wayen imgarraden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 83, 'Ma iusa ten lameô n laman ne$ n lxuf, a t berrêen. Lemmer i t ssawven i Umazan akked imawlan n lameô nnsen, ad xebôen wid, segsen, ib$an ad éôen. Lemmer maççi d lfevl n Öebbi akked uêunu S fellawen, a ppeddum d Cciîan, siwa kra kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 84, 'Nna$ deg ubrid n Öebbi. D iman ik kan ara tkellfev. Efk afud i lmumnin. Izmer Öebbi ad Issers tazmert n wid ijehlen. Öebbi Yif iten tazmert, Yif iten aâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 85, 'Win icefâan ccafuâa ilhan, ad iawi, segs, amur. Win icefâan ccafuâa icemten, ad iawi, segs, sin imuren. Öebbi Izga Issenqad yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 86, 'Ma nnan awen d: "azul"! Erret asen azul it yifen, ne$ erret asen t. Ih, Öebbi Izga Iêeppeb yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 87, 'Öebbi, ur illi ôebbi siwa Neppa, a kwen Issemlil, ass n tnekra, ur degs ccekk. Anwa i iqqaôen tidep sennig Öebbi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 88, 'Acu i kwen iu$en: tebvam $ef sin, $ef ixabiten? Izzaâ ten Öebbi ilmend n wayen kesben. Day teb$am a ppenhum win Itlef Öebbi? Win Itlef Öebbi, ur as teppafev abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 89, 'B$an a ppilim d ijehliyen am nitni, a ppemcabim. Ur sâut iêbiben segsen, alamma unagen deg ubrid n Öebbi. Ma wexxôen, îîfet pen, nna$et pen anda ten tufam, ur sâut segsen aêbib ne$ asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 90, 'Kkes ed wid iusan ar ugdud ukud tesâam laâqed, ne$ i kwen id iusan, gguman wulawen nnsen a kwen nna$en, ne$ ad nna$en agdud nnsen. Lemmer i S ihwi i Öebbi, yili Ifka yasen adabu fellawen, a kwen nna$en. Ma âazlen iman nnsen segwen, ur kwen nnu$en, ssutren awen d tifrat, ur kwen Ippawi Öebbi $uôsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 91, 'A ppafem wiyav i ib$an tifrat yidwen, akked tifrat akked ugdud nnsen. Yal tikelt ideg ara ten rren ar lfetna, ad kecmen degs. Ma ur aâzilen ara iman nnsen segwen, ur awen ssutren ara tifrat, ur fukken ara amennu$, îîfet pen, nna$et pen anda ten tufam. Widak, Nefka yawen fellasen adabu n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 92, 'Ur ippunefk ara i lmumen ad ine$ lmumen, siwa ma i$lev. Win in$an lmumen di le$wlav, ad iserreê i wakli iumnen, a ppeppunefk ddeyya i twacult is, siwa ma seddqen p. Ma illa seg ugdud acengu nnwen, u neppa d lmumen, ad iserreê i wakli iumnen. Ma illa seg ugdud ukud tesâam laâqed, a ppeppunefk ddeyya i twacult is, ad iserreê i wakli iumnen. Win ur nezmir ara, ad iuéum sin wagguren, wa deffir wa, d nndama i Öebbi. Öebbi Izga Iééeô, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 93, 'Win in$an lmumen s lemâamda, aqeîîi ines d Loahennama, degs ad iwekkeô. A d Izâaf Öebbi fellas, a t Ixzu, ad as d Iheggi aâaqeb abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 94, 'A wid iumnen! Ma tennu$em deg ubrid n Öebbi, beggnet iman nnwen. Ur qqaôet i win i wen d ssutren tifrat: "ur telliv d lmumen"! Teb$am cci n tmeddurt n ddunit. £uô Öebbi, aîas u$iti. Akka ay tellam zik. Öebbi Ifeôôeo fellawen. Beggnet iman nnwen. Ih, Öebbi Izga Issen ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 95, 'Ur aâdilen ara wid iqqimen si lmumnin, siwa wid ivôuôan, akked wid ijuhden deg ubrid n Öebbi, s wayla nnsen akked yiman nnsen. Ismenyaf Öebbi wid ijuhden s wayla nnsen akked yiman nnsen, i wid iqqimen. Akw, Iwaââed asen Öebbi ûûam. Ifrez Öebbi imjuhad af wid iqqimen, s warraz ameqwôaêan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 96, 'aseqôeb $uôeS, ssmaê, akked uêunu. Öebbi Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 97, 'Ih, i wid iwumi ddment lmalayek leôwaê, u densen iman nnsen, ad inint: "anida tellam"? A d inin: "nella d uôhifen di tmurt". Ad inint: "day ur tewsiâ ara tmurt n Öebbi, a ppinigem degs"? Widak, axxam nnsen d Loahennama. A tu$alin tucmip!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 98, 'Kkes ed uôhifen, argaz, tameîîut, agrud, ur nezmir i tsensert, ur nepwanhu s abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 99, 'Widak, amar Öebbi ad asen Isemmeê. Öebbi Izga Ipqili, Ipsemmiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 100, 'Win iunagen deg ubrid n Öebbi, ad iaf, di tmurt, aîas n ssôanat akked lufa. Win iff$en seg uxxam is, d iminig ar Öebbi akked Umazan iS, sinna, temmuger it tmeppant, arraz is atan ar Öebbi. Öebbi Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 101, 'Mi teppeddum di tmurt, ulac u$ilif ma teééeméim taéallit, ma tugadem a d ééedmen fellawen wid ijehlen. Ih, ijehliyen banen d icenga nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 102, 'Ma telliv garasen, tezwaôev asen i téallit, ilaq a ppili terbaât, segsen, yidek, s ibeddi, ad îîfen leslaê nnsen. Mi knan, ad ilin deffir wen. A d tas terbaât nniven ur neééul, ad ééalen yidek, ad êadren iman nnsen, akked leslaê nnsen. Ssarmen wid ijehlen, a p$eflem $ef leslaê nnwen akked lqecc nnwen, iwakken a d ééedmen fellawen, yiwet n ééedma. Ulac u$ilif ma tessersem leslaê nnwen, ma ihero ikwen ugeffur ne$ tuvnem. Ëëadret iman nnwen. Ih, Öebbi Ihegga, i ijehliyen, aâaqeb isdullun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 103, 'Mi tfukkem taéallit, mmektit ed Öebbi s ibeddi, s i$imi, s tuééla. Mi teppuvemnem, ééalet. Taéallit, ih, tura i lmumen, s lewqat is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 104, 'Ur fecclet deg uvfaô n ugdud. Ma tmeênem, ula d nitni meênen am kunwi. Tessaramem, ar Öebbi, ayen ur ssaramen. Öebbi Izga Iéôa, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 105, 'Ih, Nessers ak d Tazmamt, s tidep, iwakken a pêuddev ger imdanen, s wayen i k id Issenâat Öebbi. Ur ppili d axûim n lxeyyan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 106, 'Ssuter ssmaê i Öebbi. Öebbi, s tidep, Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 107, 'Ur pnnavaê $ef wid ixeynen iman nnsen. Öebbi, s tidep, ur Iêemmel ara win ixeynen, idenben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 108, 'B$an ad ffren i medden, ur zmiren ad ffren i Öebbi. Neppa Illa yidsen mara d qqaôen, deg iv, awalen i$ef ur Iôuva. Öebbi Izga Izzi i wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 109, 'Atan kunwi tnuvêem fellasen, di tmeddurt n ddunit. Anwa ara innavêen Öebbi fellasen, ass n tnekra? Ne$ anwa ar yilin fellasen d awkil?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 110, 'Win ixedmen cceôô, ne$ idnes iman is, sinna, issuter ssmaê i Öebbi, ad iaf Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 111, 'Win ibbwin abekkav, ibbwi it, kan, i iman is. Öebbi Izga Iéôa, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 112, 'Win ifalîan ne$ ibbwin abekkav, irra p id $ef wur nexdim, ibbwi lâaô, akked ubekkav n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 113, 'Lemmer maççi d lfevl n Öebbi fellak, akked uêunu S, iaâzem urbaâ, segsen, a k telfen. Ur tellifan siwa iman nnsen. Ur k îîuôôun s wacemma. Issers ak d Öebbi Tazmamt akked ûûwab. Isselmed ak ayen ur tessinev. Izga lfevl n Öebbi, fellak, d ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 114, 'Aîas n wayen qqaôen ur imâin, siwa ayen iumôen ssadaqa, ne$ lqanun, ne$ lemûalêa ger medden. Win ixedmen aya, issarem ad Iôavi Öebbi, deqqal ad as Nefk arraz ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 115, 'Win ixuûmen Amazan, mbaâd ma tepwabeggen as d nnhaya, iteddun d ubrid ur d wid n lmumnin, a t Neoo akken iooa. A t Nenheô ar Loahennama. A tu$alin tucmip!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 116, 'Ih, Öebbi ur Ipsemmiê ma ad aS carken. Ipsemmiê ayen nniven, i win i S ihwan. Win icurken i Öebbi, innetlef ttelfan u$miq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 117, 'La pnujun ar nnta, war Neppa. La pnujun kan ar Cciîan aballa$.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 118, 'Ixza t Öebbi. Inna: "ad awi$ amur ippuêeppmen, seg imdanen ik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 119, 'A ten telfe$, a ten ssenêesse$, ad asen amôe$ ad gezmen imeééu$en ubeqôi, ad asen amôe$ ad bedlen lxelq n Öebbi". Win idmen Cciîan d bab, war Öebbi, ixseô lexsaôa n tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 120, 'Ipâahad asen, issenêas iten. Ayen i sen iâahed Cciîan, d a$uôôu kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 121, 'Widak, axxam nnsen d Loahennama, ur ppafen, segs, tisensert.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 122, 'Wid iumnen, u xeddmen ayen ilhan, a ten Nessekcem ar leonanat, ddawat sen isaffen ppazzalen, degsen ad wekkôen, i lebda. Lemâahda n Öebbi a ppevôu. Anwa issawalen tidep sennig Öebbi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 123, 'Ur illi s usirem nnwen, ne$ s win n At Tezmamt. Win ixedmen cceôô, ad ippuqeîîi fellas. Ur Ippaf, war Öebbi, bab ne$ asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 124, 'Win ixeddmen ayen ilhan, d ddkeô ne$ d nnta, u neppa iumen…, widak ad kecmen Loennet, ur pwadensen s yiclem utemôiw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 125, 'Anwa iûegmen ddin is sennig win iunzen i Öebbi, u neppa d laâûem, u idda d ddin n Ibôahim, i imalen ar tidep? Öebbi Irra Ibôahim d aêbib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 126, 'N Öebbi i illan deg igenwan, i illan di tmurt. Öebbi Izga Izzi i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 127, 'Steqsayen k $ef tlawin. Ini: "Öebbi ad awen Issefhem fellasent. Ayen i wen $ôan di Tezmamt, $ef tlawin tigujilin, iwumi ur tefkim ara i sent iuran, u teb$am a tent ta$em. Akked igwerdan imeéyanen. A pbeddem i igujilen s lmizan. Ayen akw txeddmem n lxiô, Öebbi, s tidep, Izga Iéôa t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 128, 'Ma tugad tmeîîut ad as ibru, ne$ ad as iwexxeô urgaz is, ulac u$ilif fellasen ma ufan lemwafaqa garasen. Ppif lemwafaqa. Imdanen, deg iman nnsen d imceôôiyen. Ma tgerzem u têezzbem, Öebbi, s tidep, Izga Iéôa ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 129, 'Ur tezmirem a ppeddum s lmizan, ger tlawin, xas teb$am. Ihi, ur pmalet yal tumlin a p teooem, amzun d tamejgugelt. Ma tgam ayen ilhan, u têezzbem, s tidep, Öebbi Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 130, 'Ma mfaôaqen, ad I$it Öebbi yal wa, s ôôeéq iS. Öebbi Izga d Ajemmal, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 131, 'N Öebbi i illan deg igenwan, i illan di tmurt. Ni$ Nweûûa wid iwumi teppunefk Tezmamt, uqbel nnwen, u Nweûûa kwen, a pêezzbem i Öebbi. Ma tnekôem, ihi, n Öebbi i illan deg igenwan, i illan di tmurt. Öebbi Izga d Asâay, d Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 132, 'N Öebbi i illan deg igenwan, i illan di tmurt. Nesteqnaâ s Öebbi d Awkil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 133, 'Ma ihwa yaS, a kwen Ikkes a yimdanen! A d Iawi wiyav. Öebbi Izga Izmer i waya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 134, 'Win ib$an a$ellet n ddunit, ihi, ar Öebbi a$ellet n ddunit akked win n laxeôt. Öebbi Izga Issel, Ipwali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 135, 'A wid iumnen! Teddut s lmizan, d inagan n Öebbi, xas $ef yiman nnwen, ne$ imawlan u llzem, ama d ameôkanti, ama d igellil. Izwar iten Öebbi. Ur teddut d lhawiyya, ur twezznem ara. Ma txutlem, ne$ twexxôem, ihi, Öebbi Izga Iéôa ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 136, 'A wid iumnen! Amnet s Öebbi akked Umazan iS, akked Tezmamt id Issers i Umazan iS, akked Tezmamt id Issers, uqbel. Win inekôen Öebbi, lmalayek iS, Tizmamin iS, imazanen iS, akked wass aneggaru, ihi innetlaf ttelfan u$miq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 137, 'Ih, wid iumnen, sinna, nekôen, sinna, umnen, sinna, nekôen, sinna, zaden di nnkeô, ur sen Ipsemmiê Öebbi, ur ten Ippawi d ubrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 138, 'Becceô ixabiten ar fellasen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 139, 'Wid ipparan ijehliyen d iêbiben, war lmumnin, day ssarmen $uôsen tazmert? Tazmert, s tidep, ar Öebbi yakw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 140, 'Ni$ Nessers awen d, di Tezmamt: "ma teslam la nekôen issekniyen n Öebbi, la ttihin fellasen, ur p$imit yidsen, alamma bedlen ameslay. Mulac a ppilim am nitni". Öebbi, s tidep, a d Issemlil ixabiten akked ijehliyen di Loahennama, meôôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 141, 'Wid i kwen iquôâan, ma Ifka yawen d Öebbi l$elb, a d inin: "day ur nella ara yidwen"? Ma illa wayen rebêen ijehliyen, ad inin: "day ur nêuôeb ara fellawen, nsellek ikwen si lmumnin"? Ad Iêudd Öebbi garawen, ass n tnekra. Ur Ippara ara Öebbi, i ijehliyen, abrid ar lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 142, 'Ih, ixabiten xedâen Öebbi. D Neppa iten Ixedâan. Ma kren d i téallit, a d kren d imaâguza, akken kan a ten id walin medden. Cwiî kan id smektayen Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 143, 'Ur banen akka, ne$ akka; $eô wigi, ne$ $eô wiyav. Win Itlef Öebbi ur as teppafev abrid, d awez$i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 144, 'A wid iumnen! Ur pparat ijehliyen d iêbiben, war lmumnin. Day teb$am ad aS tefkem, i Öebbi, adabu ibanen, mgal kwen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 145, 'Ih, ixabiten di lqaâa n wadda n tmes, ur asen teppafev asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 146, 'Kkes ed wid ituben, ixeddmen ayen ilhan, iîîfen di Öebbi, izzazdgen ddin nnsen ar Öebbi. Widak, ad ilin ar lmumnin. Deqqal a d Iawi Öebbi, i lmumnin, arraz ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 147, 'Acu ara Ixdem Öebbi s uâaqeb nnwen, ma tesnemmrem, tumnem? Ni$ Öebbi Ippara tajmilt, Iéôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 148, 'Ur Iêemmel ara Öebbi nnaâlat, siwa seg win ipwadensen. Öebbi Izga Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 149, 'Ma txedmem lxiô âinani, ne$ teffrem t, ne$ tsemmêem abekkavu, Öebbi Izga Ipsemmiê, d Aêernuk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 150, 'Ih, wid inekôen Öebbi akked imazanen iS, u b$an ad ssemfaôqen Öebbi akked imazanen iS, qqaôen: "numen s kra, nenkeô kra". B$an ad awin abrid garasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 151, 'Widak, d ijehliyen n ûûeê. Nhegga, i ijehliyen, aâaqeb isdullun', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 152, 'Wid iumnen s Öebbi akked imazanen iS, ur ten ssemgarraden, widak, deqqal a ten id ias warraz nnsen. Öebbi Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 153, 'La k d ssuturen, At Tezmamt, ad asen d tessersev Tazmamt seg igenni. Ni$ ssutren, i Musa, sennig waya. Nnan as: "ssenâat a$ d Öebbi, a T nwali". Tebbwi ten ssiâqa, ilmend n ddens nnsen. Sinna, âabden aâjmi, mbaâd ma iusa ten id ubeggen. Nesemmeê asen aya. Nefka, i Musa, adabu n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 154, 'Nessuli adrar sennig sen, ilmend n laâqed nnsen. Nenna yasen: "kecmet si tebburt s lekni". Nenna yasen: "ur txalafet ssebt". Neîîef segsen laâqed iûeêêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 155, 'Imi neqven laâqed nnsen, u nekôen issekniyen n Öebbi, u n$an lambiyya, war ssebba, u nnan: "ulawen nne$ duben". Xaîi, d Öebbi iten Isel$en, ilmend n tjehli nnsen. Drus kan i iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 156, 'Ilmend n nnekô nnsen, u gren d, $ef Meryem, acehrir abarar;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 157, 'u nnan: "nekwni nen$a Âisa, mmi s n Meryem, Amazan n Öebbi". Ur t n$in, ur t semmôen $ef umidag. D lexyal kan ger wallen nnsen. Ih, wid imgarraden fellas, atnan di ccekk fellas, ur éôin fellas acemma, teddun kan d nnwaya. Metbut, ur t nn$in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 158, 'Xaîi! Issuli t Öebbi $uôeS. Öebbi Izga d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 159, 'Ur illi yiwen, seg wAt Tezmamt, ur numin yis, uqbel tameppant is. Ass n tnekra ad yili d anagi nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 160, 'Ilmend n ddens n wudayen, Negdel asen tiéidanin i illan êellent asen, imi da$en, îîeôôifen aîas seg ubrid n Öebbi;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 161, 'u ssexdamen rrba, i illan tepwakkes asen, u teppen ayla n medden, d aêerfi. Nhegga d, i ijehliyen segsen, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 162, 'Maca, wid, segsen, izaden di tmusni, lmumnin iumnen s wayen ik ed irsen, akked wayen id irsen, uqbel ik, wid ibedden i téallit, wid ipzekkin, wid iumnen s Öebbi akked wass aneggaru, widak, ad asen Nefk arraz ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 163, 'Ih, Nweêêa yak ed, akken Nweêêa i Nuê, akked lambiyya deffir es. Nweêêa i Ibôahim, Ismaâil, Isêaq, Iaâqub, laâôac, Âisa, Yub, Yunes, Harun, Sliman. Nefka Ihellilen i Dawed.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 164, 'Akked lambiyya i$ef ik ed Neêka, uqbel; akked lambiyya, i$ef ur ak ed Neêki. S tidep, Immeslay Öebbi i Musa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 165, 'Lambiyya ipbecciôen, inedôen, iwakken ur pnamaren medden $ef Öebbi, deffir imazanen. Öebbi Izga d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 166, 'Maca, Icuhhed Öebbi $ef wayen ik ed Issers, s tmusni S. Ad cehhdent lmalayek. Nesteqnaâ s Öebbi d Anagi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 167, 'Ih, wid ijehlen, u îîeôôifen seg ubrid n Öebbi, ni$ nnetlafen ttelfan u$miq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 168, 'Ih, wid ijehlen u densen, ur sen Ipsemmiê Öebbi, ur ten Ippawi d ubrid,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 169, 'siwa abrid n Loahennama, degs ad wekkôen, i lebda. Ayagi, Izga d ayen isehlen i Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 170, 'A yimdanen! Ni$ iusa kwen id Umazan, s tidep, s$uô Mass nnwen. Amnet, ppif i kunwi. Ma tugim, ihi n Öebbi, i illan di tmurt akked igenwan. Öebbi Izga Iéôa, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 171, 'A yAt Tezmamt! Ur sfuhruyet ddin nnwen. Ur qqaret, $ef Öebbi, siwa tidep. Lmasiê Âisa, mmi s n Meryem, d amazan kan n Öebbi; d awal iS i Irra ar Meryem, u d ôôuê s $uôeS. Ihi, amnet s Öebbi akked imazanen iS, ur qqaôet: "krav"! Ëebset, ppif i kunwi. Öebbi d Yiwen kan n Öebbi. Gedha s yiS, ma ad Isâu mmi S! IneS i illan deg igenwan, i illan di tmurt. Nesteqnaâ s Öebbi d Awkil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 172, 'Ur ismummi ara lmasiê, ma illa d amdan n Öebbi. Akken lmalayek tuqôibin. Wid ismummin a T âabden, u zuxxen, ad pwafessren akw $uôeS.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 173, 'Wanag wid iumnen, u xedmen ayen ilhan, ad asen Ifk arraz nnsen, ad asen Irnu si lfevl iS. Ma d wid ismummin u zuxxen, a ten Iâaqeb aâaqeb aqeôêan. Ur ppafen, war Öebbi, bab ne$ asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 174, 'A yimdanen! Ni$ iusa kwen id utebbet s$uô Mass nnwen, u Nessers awen ed tafat ibanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 175, 'Wanag wid iumnen s Öebbi, i iîîfen degS, a ten Issekcem ar uêunu S akked lfevl. A ten Inhu $uôeS, deg ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 176, 'Cawôen k. Ini: "Öebbi Isfehm awen d $ef llzem. Ma immut urgaz, war tarwa, isâa taultmap, i neppat azgen n wayen id iooa. Neppa a p iwôet, ma ur tesâi tarwa. Ma snat ay llant, amur wis krav i yal ta, n wayen id iooa. Ma llan watmaten akked tessetmatin, i uqcic amur n snat n tullas". Ibeggen awen d Öebbi akken ur tepnnetlafem. Öebbi Iéôa yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 1, 'A wid iumnen! Eîîfet deg iâahden nnwen. Ëellen awen lmal n tejlibt, kkes ed wid i wen nnan. Ur awen têell ara ûûyada, mara têuoem. Öebbi, s tidep, Ippameô ayen i S ihwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 2, 'A wid iumnen! Ur ssiôxiset isekkiren n Öebbi, aggur iôqan, îêegga, snaoeq, wid iteddun ar Uxxam n Lêaôam, saramen lfevl akked llza n Mass nnsen. Üegdet mi tfukkem. Xas tcuênem agdud i wen igedlen Loamaâ n Lêaôam, ur iwata ara a pzegrem tilas. Mâawanet ar yise$ akked uêezzeb, ur ppemâawanet ar ubekkav akked lbe$wv. Ëezzbet i Öebbi. S tidep, Öebbi Iwâaô deg uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 3, 'I wen ipwagedlen d loifa, idim, aksum n yilef, wayen ipwamezlen i war Öebbi, ayen ippuxenqen, ayen i pwaûerâan, ayen igrarben, ayen ippuberrzen, ayen içça lweêc - siwa ma tessawvem tezlam t -, îêegga i tezôa, aseqdec n tseqqaôt. Ayagi d ucmit. Assa, wid ijehlen uysen si ddin nnwen. Ur ten ppagwadet, agwadet iyI. Assa, Nnekmale$ awen ddin nnwen, Tame$ awen l$it iW, Öuva$ awen annuz d ddin. Win terra tmara di tegwnip n llaé, ur iffi$ abrid, Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 4, 'A k steqsayen acu i sen iêellen. Ini: "iêell awen wayen imaânen. Ayen d teppawin s lewêuc ipûeggiden. Tesêefvem asen ayen i wen Isseêfev Öebbi. Eççet seg wayen i wen d îîfen, mmektit ed fellas isem n Öebbi". Ëezzbet i Öebbi. Öebbi, s tidep, Ip$awal deg uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 5, 'Assa, iêell awen wayen imaânen. Iêell awen lqut n wid iwumi teppunefk Tezmamt, - iêell asen lqut nnwen -; tilawin tiêuôiyin iumnen, tilawin tiêuôiyin seg wid iwumi teppunefk Tezmamt, uqbel nnwen, ma tefkam asent tuççit nnsent; d uwqimen maççi d ucmiten, ur teppeddum d temddukwal. Win iugin liman, mêan igiten is. Neppa, di laxeôt, seg imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 6, 'A wid iumnen! Ma tekkrem ar téallit, ssirdet udmawen nnwen, ifassen nnwen alamma d ti$wmaô, sâaddit ifassen illexsen $ef iqweôôa nnwen, ssirdet ivaôen nnwen ar twelza. Ma tellam s loanaba, zzizdget. Ma tuvnem ne$ tunagem, ne$ iusa d yiwen segwen si ccicma, ne$ tennulem tilawin, ur tufim aman, ddmet akal zeddigen, sâaddit ep $ef udmawen nnwen akked ifassen nnwen. Ur Ib$a ara Öebbi a kwen Iqelleq, maca Ib$a a kwen Izzizdeg, ad awen Itim l$it iS, amar a pesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 7, 'Mmektit ed l$it ikwen I$at Öebbi, akked nnesba ikwen Inuseb, mi tennam: "nesla u nunez". Ëezzbet i Öebbi. Öebbi, s tidep, Issen i illan deg idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 8, 'A wid iumnen! Illit d ôôsem ar Öebbi, d inagan at lmizan. Ur kwen issencaf dd$el n ugdud, ur twezznem. Wezznet. Lmizan iqôeb aîas ar uêezzeb. Ëezzbet i Öebbi. Öebbi, s tidep, Issen ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 9, 'Iâahed Öebbi ssmaê akked warraz ameqwôaêan, i wid iumnen, u xeddmen ayen ilhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 10, 'Wid ijehlen u skaddben issekniyen nne£, widak d at ujajiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 11, 'A wid iumnen! Mmektit ed l$it ikwen I$at Öebbi, amek agdud ipheggi iman is, ad isâaddi afus is fellawen. Iîîef akin ifassen nnsen, segwen. Ëezzbet i Öebbi. £ef Öebbi ara ppeklen lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 12, 'Ni$ Irra Öebbi laâqed i At Isôail. Nessuffe$ ed, segsen, mrawsin imvebbôen. Inna Öebbi: "Nek yidwen ma téullem, tzekkam, tumnem s imazanen iW, u tâawnem ten, tôevlem i Öebbi aôeîîal igerzen. War ccekk, ad awen Kkse$ tucmitin nnwen, a kwen Skecme$ di leonanat, ddawat sen isaffen ppazzalen. Win ijehlen segwen, deffir waya, ni$ innetlaf seg ubrid umâin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 13, 'Imi ooan laâqed nnsen, Nexza ten, Nesgursel ulawen nnsen. Ssexsaôen inumak n wawalen, ppun amur n wayen i$ef pwafekkôen. Mazal a d temlilev d lexdaâ nnsen, siwa drus segsen. Semmeê asen u ssuref. Öebbi, s tidep, Iêemmel iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 14, 'Wid iqqaôen: "nekwni d imasiêiyen", Nerra laâqed yidsen, ppun amur n wayen i$ef pwafekkôen. Nessker ed, garasen, taâdawt akked dd$el, ar ass n tnekra. Deqqal a ten Ixebbeô Öebbi $ef wayen la ûenâan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 15, 'A yAt Tezmamt! Ni$ iusa kwen id Umazan nne£. Ad awen ibeggen aîas n wayen la teppeffrem, n Tezmamt. Ad Ipsemmiê i waîas. Ni$ tusa kwen id tafat s$uô Öebbi, akked Tezmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 16, 'Inehhu yis Öebbi, ar iberdan n tifrat, wid iôe$ben llza S. A ten Issuffe$ si tillas ar tafat, s tsriê iS. A ten Inhu s abrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 17, 'Ni$ jehlen wid innan: "Öebbi, s tidep, d lmasiê, mmi s n Meryem". Ini: "anwa isâan kra n lkwelf, s$uô Öebbi, ma ihwa yaS ad Ine$ lmasiê, mmi s n Meryem, imma s, akked wayen akw illan di tmurt"? N Öebbi tagelda n tmurt, igenwan, akked wayen illan garasen. Ixelleq ayen i S ihwan. Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 18, 'Udayen akked imasiêiyen, nnan: "nekwni d tarwa n Öebbi, d wid Ismenyaf". Ini: "acimi, ihi, ikwen Ipâaqab $ef ibekkaven nnwen? Xaîi, kunwi d imexlaq am wiyav". Ad Isemmeê i win i S ihwan, ad Iâaqeb win i S ihwan. N Öebbi tagelda n tmurt, igenwan, akked wayen illan garasen. Taggara $uôeS.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 19, 'A yAt Tezmamt! Ni$ iusa kwen id Umazan nne£, ad awen ibeggen, mi tâadda tallit war imazanen. Akka ur d teqqaôem ara: "ur a$ d iusi ubeccaô, ne$ uneddaô". Ihi, iusa kwen id ubeccaô, uneddaô. Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 20, 'Mi inna Musa i ugdud is: "a yagdud iw! Mmektit ed l$it ikwen I$at Öebbi. Irra segwen lambiyya, Irra kwen d igeldan. Ifka yawen ayen ur Ifki i yiwen, deg imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 21, 'A yagdud iw! Kecmet akal iôqan, i wen Iura Öebbi. Ur d ppu$alet $er deffir wen, a d tegwrim txesôem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 22, 'Nnan: "a Musa! Degs agdud iâafriten, nekwni ur p nkeççem, d awez$i, alamma ff$en d segs. Mi d ff$en segs, a nekcem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 23, 'Sin irgazen, seg wid iugaden - Isâad iten Öebbi -, nnan: "kecmet $uôsen si tebburt; ma tkecmem, kunwi, ih, a prebêem. Ppeklet af Öebbi, ma d lmumnin ay tellam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 24, 'Nnan: "a Musa! Nekwni ur p nkeççem, d awez$i, skud mazal iten degs. Öuê, keçç d Mass ik, nna$et. Nekwni a neqqim dagi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 25, 'Inna: "a Mass iw! Ay melke$, nek, siwa iman iw akked gma; ihi, Semfaôeq a$ d ugdud".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 26, 'Inna: "ihi, tamurt agi tepwagdel asen. Ukuéet iseggwasen ad menîaôen di lberr. Ur $webben $ef ugdud iballa$en".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 27, 'Eêku yasen, s tidep, taqûit n sin warrac n Adem, mi îêeggan i sin. S$uô yiwen tepwaqbel. S$uô wayev ur tepwaqbel ara. Inna: "war ccekk, a k n$e$". Inna: "Iqebbel kan Öebbi îêegga s$uô wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 28, 'Ma ibbwev iyi d ufus ik, ad iyi ten$ev, nek, ur k id ippawev ufus iw, a k n$e$. Nek, ppagwade$ Öebbi, Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 29, 'Nek, b$i$ a ppawiv abekkav iw, akked ubekkav ik, a ppiliv seg wat tmes. Winna d aqeîîi imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 30, 'Iaâzem, deg iman is, ad ine$ gma s, d$a in$a t. Igwra d seg imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 31, 'Iuzen ed Öebbi tagerfa, tkeôôev akal, iwakken ad as tessenâat amek ara i$umm loeppa n gma s. Inna: "a ssexv iw! Ur bbwive$ ad ili$ am tgerfa yagi, ad $umme$ loeppa n gma". Igwra d seg wid inedmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 32, 'Ilmend n waya, Nura i At Isôail, ar win in$an amdan ur nen$i yiwen, ur nessefsed di tmurt, amzun in$a imdanen meôôa. Win issadren yiwen, amzun issader imdanen meôôa. Ni$ usan ten id imazanen nne£, s ubeggen. Sinna, deffir waya, s tidep, aîas degsen ssuguten di tmurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 33, 'Aqeîîi n wid ipna$en Öebbi akked Umazan iS, u ssenkaren asefsed di tmurt, siwa timen$iwt, ne$ asemmeô $ef umidag, ne$ anegzum ufus sya, uvaô sya, ne$ anfay si tmurt. Ayagi, d aqeîîi nnsen di ddunit. Di laxeôt, fellasen aâaqeb ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 34, 'Kkes ed wid inedmen, uqbel a pvebbôem fellasen. Cfut ar Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 35, 'A wid iumnen! Ëezzbet i Öebbi, nadit a pqeôôbem $uôeS, nna$et deg ubrid iS, amar a prebêem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 36, 'Ih, wid ijehlen, xas ad sâun i illan akw di tmurt, rnu yas win i t icban, iwakken ad fdun, yis, iman nnsen seg uâaqeb, ass n tnekra, ur ipwaqbal segsen. Fellasen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 37, 'Ad b$un a d ff$en si tmes, ur llin d wid id iteff$en. Fellasen aâaqeb imezgi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 38, 'Amakwar, tamakwart, gezmet asen ifassen nnsen, d aqeîîi n wayen xedmen, d aâaqeb s$uô Öebbi. Öebbi d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 39, 'Win inedmen, deffir ddens is, u iu$al d aâôvi, ad as Issuref Öebbi. Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 40, 'Day ur teéôiv ara n Öebbi tagelda n tmurt akked igenwan? Ipâaqab win i S ihwan, Ipsemmiê i win i S ihwan. Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 41, 'A Nnbi! Ur k $weblen wid ip$awalen ar tijehli, seg wid iqqaôen numen, s imawen nnsen, ur uminen wulawen nnsen, seg wudayen issemêasen i tikerkas, issemêasen i ugdud nniven, ur d nusi $uôek. Pbeddilen awalen deffir ussefhem nnsen. Qqaôen: "ma ippunefk awen d waya, ddemt ep; ma ur awen d ippunefk ara, $uôwat"! Win Ib$a Öebbi a t Ihewwel, ur t tepsellikev, s wacemma, seg ufus n Öebbi. Widak, d wid iwumi ur Ib$a ara Öebbi, ad izdigen wulawen nnsen. Di ddunit ad pwaxzun. Di laxeôt fellasen aâaqeb abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 42, 'Wid issemêasen i tikerkas, iteppen leêôam, ma usan k id, fru garasen, ne$ eoo iten. Ma teooiv ten, ur k îîuôôun s wacemma. Ma têuddev, êudd garasen s lmizan. Öebbi, s tidep, Iêemmel wid iweznen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 43, 'Amek ara k id asen, s aêuddu, u nitni sâan Tuôa, degs aêuddu n Öebbi? Sinna, deffir waya, ad wexxôen. Ur llin wigi si lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 44, 'Ih, Nessers ed Tuôa, degs nnhaya akked tafat, ferrun yis ger wudayen, lambiyya imvuâen. U iôabaniyen akked lecyux seg wayen jemâen, si Tezmamt n Öebbi, u llan d inagan is. Ur ppagwadet imdanen, agwadet iyI. Ur d ppa$et, s issekniyen iW, ayen ôxisen. Wid ur nepêuddu yara s wayen id Issers Öebbi, widak d ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 45, 'Nura yasen degs: ôôuê s ôôuê, tiî s tiî, anzaren s wanzaren, ameééu$ s umeééu$, tu$mest s tu$mest, leoruê ad ppuêesben. Win iooan, d le$ôama s. Wid ur nepêuddu yara s wayen id Issers Öebbi, widak d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 46, 'Nuzen ed, deffir sen, Âisa, mmi s n Meryem, a d itebbet ayen it id izwaren di Tuôa. Nefka yas Linoil, degs nnhaya akked tafat, a d itebbet ayen it id izwaren di Tuôa. D nnhaya u d anabi i wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 47, 'At Linoil, iwata ad êudden s wayen id Issers, degs, Öebbi. Wid ur nêudd ara s wayen id Issers Öebbi, widak d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 48, 'Nessers ak d Tazmamt, s tidep, a d tebbet ayen ip id izwaren n Tezmamt. Nvemn ip. Ihi, êudd garasen s wayen id Issers Öebbi. Ur teddu d lhawiyyat nnsen, beôôa n wayen i k id iusan n tidep. I yal wa, Nefka lqanun akked ubrid. Lemmer i S ihwi i Öebbi, yili Irra kwen d yiwen n lois. Maca, iwakken a kwen Ijeôôeb $ef wayen i wen Ifka, mzizlet ar lxiô. Ar Öebbi tu$alin nnwen akw. A kwen Ixebbeô $ef wayen tellam temgarradem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 49, 'Ëudd garasen s wayen id Issers Öebbi. Ur teddu d lhawiyyat nnsen. £uôek a k hewwlen $ef kra seg wayen i k d Issers Öebbi. Ma wexxôen, éeô ar Öebbi Ib$a kan a ten Iwwet $ef kra ibekkaven nnsen. Ih, aîas n medden d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 50, 'Day b$an aêuddu n zzman n war tussna? Anwa yifen Öebbi d Amêaddi, i ugdud ineûêen liman?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 51, 'A wid iumnen! Ur pparat, d iêbiben, udayen akked imasiêiyen. Garasen d iêbiben. Win, segwen, i ten irran d iêbiben, ad yili segsen. Öebbi, s tidep, ur Inehhu agdud imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 52, 'A pwaliv imuvan n wul, ppazzalen $uôsen, qqaôen asen: "nugad ay d itezzin fella$". Ahat a d Ias Öebbi s l$elb, ne$ s lameô s$uôeS. A d gwrin di nndama, $ef wayen ffren deg iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 53, 'A d inin wid iumnen: "day d wigi i iggullen s Öebbi, tagallit meqqwôen, ar nitni llan yidwen"? Mêan igiten nnsen, gwran d d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 54, 'A wid iumnen! Win segwen iooan ddin is…, ihi, deqqal Öebbi a d Iawi agdud Iêemmel, i T iêemmlen; ad ôavin lmumnin, ad qesêen ar ijehliyen. Ad nna$en deg ubrid n Öebbi. Ur ppagwaden alummu n win iplummun. Ayagi d lfevl n Öebbi, Ippak it i win i S ihwan. Öebbi d Ajemmal, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 55, 'Imawlan nnwen siwa Öebbi akked Umazan iS, wid iumnen, wid ipéallan, pzekkin, u nitni îîinizen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 56, 'Wid irran d imawlan nnsen, Öebbi, Amazan iS, akked wid iumnen…, ih, akabar n Öebbi, d nitni ara irebêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 57, 'A wid iumnen! Ur pparat d iêbiben wid id ilhan, di ddin nnwen, s wurar d utihi, seg wid iwumi teppunefk Tezmamt, uqbel nnwen, akw seg ijehliyen. Ëezzbet i Öebbi, ma d lmumnin ay tellam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 58, 'Ma teddnem i téallit, fellas ad mmaâlken, ad uraren. Ayagi, acku nitni d agdud ur nefhim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 59, 'Ini: "a yAt Tezmamt! Acu i$ef la $ ttehmem, siwa imi numen s Öebbi, akked wayen id Issers $uône$, akked wayen id Issers uqbel? Tegwti degwen d iballa$en".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 60, 'Ini: "ad awen mle$ aqeîîi n Öebbi icemten sennig wagi? Wid Ixza Öebbi, sserfan T, Irra ten d iddawen, d ilfawen". Âabden iôebbiten n tkerkas. Widak, atnan di liêala tucmip mavi, di ttelfan u$miq seg ubrid uûwib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 61, 'Mi d usan $uôwen, qqaôen: "numen". Ni$ kecmen d s tijehli, u nitni ff$en yis. Öebbi Yif akw akken Issen, ayen teffren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 62, 'La tepwaliv aîas, degsen, p$awalen ar ubekkav akked wanfal, teppen leêôam. I icmet wayen xeddmen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 63, 'A lemmer i sen kksen iôabiyen akked lecyax, awal ubekkav akked wuççi n leêôam? I icmet wayen la ûenâen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 64, 'Qqaôen wudayen: "iskkweô ufus n Öebbi". D ifassen nnsen i isekkwôen. Pwaxzan ilmend n wayen d qqaôen. Xaîi! Ifassen iS llin, Ip$iti akken i S ihwa. Ayen i k d irsen, s$uô Mass ik, war ccekk, irennu i waîas segsen, leb$wev akked tijehli. Nessker garasen cceêna, akked dd$el, ar ass n tnekra. Yal tikelt ara caâlen times i îôad, a p Issexsi Öebbi. Pnadin asefsed di tmurt. Öebbi ur Iêemmel ara ifessaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 65, 'At Tezmamt, lemmer day umnen u êezzben, yili, war ccekk, Nekkes asen tucmitin nnsen, u Nesskecm iten ar leonanat isaâdiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 66, 'Lemmer day îîifen di Tuôa akked Linoil, akked wayen i sen d irsen s$uô Mass nnsen, war ccekk, ad ççen sennig sen, akw seddaw ivaôen nnsen. Illa garasen lois iôeznen. Aîas, degsen, dirit wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 67, 'A yAmazan, mel ayen i k d irsen, s$uô Mass ik. Ma ur t temliv ara, ur tessawvev ara tabrap iS. Öebbi a k Ifukk si l$aci. Öebbi, s tidep, ur Inehhu agdud ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 68, 'Ini: "a yAt Tezmamt! Ur tellim deg wacemma, alamma teddam d Tuôa, Linoil, akked wayen i wen d irsen, s$uô Mass nnwen". Ayen i k d irsen s$uô Mass ik, war ccekk, irennu, i waîas segsen, leb$wev akked tijehli. Ur $webbel $ef ugdud ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 69, 'Ih, wid iumnen, udayen, iûabiyen, imasiêiyen, wid iumnen s Öebbi akked wass aneggaru, u xeddmen ayen ilhan, ur ppagwaden, ur $weblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 70, 'Ni$ Nga laâqed i At Isôail, Nuzen asen imazanen. Yal tikelt ara ten id ias umazan s wayen ur asen nehwi, wa a t skiddben, wa a t n$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 71, '£ilen ur ippili uhewwel. Dre$len, âaégen. Sinna, Issuref asen Öebbi. Sinna, aîas degsen dre$len, âaégen. Öebbi Ipwali acu xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 72, 'Ni$ jehlen wid iqqaôen: "Öebbi, s tidep, d lmasiê, mmi s n Meryem". U inna lmasiê: "a yAt Isôail! Âabdet Öebbi, Mass iw, d Mass nnwen". Ih, win icerken i Öebbi, Igdel as Öebbi Loennet. Axxam is d times. Ur llin isellaken i imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 73, 'Ni$ jehlen wid iqqaôen: "Ih, Öebbi d wis krav n krav". Ur illi ôebbi siwa Öebbi Yiwen. Ma ur xvin ara i wayen qqaôen, war ccekk, aâaqeb aqeôêan ad iêaz wid ijehlen segsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 74, 'Day ur tuben ara ar Öebbi, u ssuturen aS ssmaê? Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 75, 'Lmasiê, mmi s n Meryem, d amazan kan. Ni$ âaddan, uqbel is, imazanen. Imma s tessawal tidep. Llan teppen lqut. Wali amek i asen Nepbeggin issekniyen; sinna, wali amek la ppagwin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 76, 'Ini: "day a ppaâbdem, war Öebbi, ayen ur nezmir a kwen ivuôô, ne$ a kwen infaâ"? Öebbi, Neppa, Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 77, 'Ini: "a yAt Tezmamt! Ur rennut, di ddin nnwen, ayen ur nelli d tidep. Ur teddut d lemcihwat n ugdud innetlafen zik, i itelfen aîas, u telfen seg ubrid uûwib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 78, 'Pwaxzan wid ijehlen, seg wAt Isôail, s$uô iles n Dawed akked Âisa, mmi s n Meryem; ayagi, $ef wayen âuûan, u zgaren tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 79, 'Ur ppemyekkasen ayen xedmen n dir. I icmet wayen xeddmen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 80, 'A pwaliv aîas segsen, ad xalven wid ijehlen. War ccekk, icmet wayen xedmen i iman nnsen. Ad Izâaf Öebbi fellasen. Nitni ad wekkôen deg uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 81, 'Lemmer uminen s Öebbi, Nnbi, akked wayen i sen d irsen, ur ten pparan d iêbiben. Maca aîas, segsen, d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 82, 'A ppafev icenga iqeûêanen mavi, n wid iumnen, d udayen akked wid ipcaraken. A ppafev wid iqeôben mavi, s lmaênana, ar wid iumnen, d wid innan: "nekwni d imasiêiyen". Ayagi, acku llan degsen ixelwiyen, iôehbaniyen, u nitni ur sme$wôen ara iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 83, 'Ma slan i wayen id iusan ar Umazan, a pwaliv allen nnsen ççuôent d imeîîi, seg wayen ufan n tidep. Qqaôen: "a Mass nne$! Numen, Aru ya$ seg inagan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 84, 'Acu i $ iu$en ur numin s Öebbi akked wayen i $ d iusan n tidep; ur nessarem a $ Issekcem, Mass nne$, s agdud iâaôviyen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 85, 'A ten Ioazi Öebbi, $ef wayen d qqaôen, s leonanat, ddawat sen isaffen ppazzalen, degsen ad wekkôen. Wagi d aoazi n lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 86, 'Wid ijehlen, u skaddben issekniyen nne£, widak, d at Loahennama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 87, 'A wid iumnen! Ur pgeddilet ayen imaânen i wen Iêell Öebbi. Ur zegret tilas. Öebbi, s tidep, ur Iêemmel ara wid izegren tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 88, 'Eççet seg wayen ikwen Iôéeq Öebbi, iêellen, imaânen. Ëezzbet i Öebbi. YiS, kunwi, ay tumnem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 89, 'Ur kwen Ipqassa Öebbi $ef tgallit n tkerkas. Maca, a kwen Iqiss $ef tgallit n ûûeê. Takweffaôt is: a ppecceççem mraw ime$ban, akken tecceççam tawacult nnwen, ne$ a ten tesselsem, ne$ a pserêem i wakli. Win ur nwâa ara, ad iuéum krav wussan. D tagi ay d takweffaôt n tgallit nnwen, ma teggullem. Eîîfet di tgallit nnwen. Akka i wen d Ipbeggin Öebbi issekniyen, amar a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 90, 'A wid iumnen! Ccôab, leqwmeô, tiâancuôin, taseqqaôt, d ayen kan icemten, seg igi n Cciîan. Ihi, veôôeft asen, amar a prebêem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 91, 'Ib$a kan Cciîan ad isker ticenga akked dd$el garawen, s ccôab akked leqwmeô, a kwen iveôôef seg usmekti n Öebbi, akked téallit. Day ur tepfukkum ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 92, 'A$et awal i Öebbi, a$et awal i Umazan. £uôwat! Ma twexxôem, cfut ar Amazan, iwata yas kan anabi ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 93, 'Ur telli tiyta deg wid iumnen, u xeddmen ayen ilhan, $ef wayen ççan, ma êezzben, umnen, xedmen ayen ilhan, sinna êezzben, umnen, sinna, êezzben u maânen. Öebbi Iêemmel lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 94, 'A wid iumnen! War ccekk, a kwen Iweddeb Öebbi $ef wayen tepûeggidem s ifassen nnwen, u s ixtucen nnwen, iwakken ad Iéeô Öebbi anwa i T ippagwaden, di tbavnit. Win izegren tilas, deffir waya, fellas aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 95, 'A wid iumnen! Ur pûeggidet di zzyaôa nnwen. Win iûeggden segwen, u iâammed, aqeîîi: ad iseddeq, si lmal is, ayen in$a s ûûyada s, a d êudden, f waya, sin irgazen iêesbiyen segwen. D tikci ara iawven ar Lkaâba. Ne$ takweffaôt: ad icceçç ime$ban, ne$, ayen iswan aya, ad iuéum. Ad ijeôôeb vveôô n lameô is. Öebbi Isemmeê i wayen iâaddan. Win iu$alen a d Irr Öebbi segs ppaô. Öebbi d Uzmir, Ippara d ppaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 96, 'Têell awen ûûyada n yill akked uççi s. D lqut i kunwi akw iminigen. Tepwagdel awen ûûyada di tmurt, skud aql akwen d zziyyaô. Ëezzbet i Öebbi, $uôeS ara tepwafesrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 97, 'Irra Öebbi Lkaâba d axxam iôqan ipwabnan i l$aci, aggur iôqan, asfel, isenoaq, ayagi iwakken a ppeéôem ar Öebbi Iéôa i illan deg igenwan u di tmurt, u Öebbi Issen yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 98, 'Cfut iwâaô uâaqeb n Öebbi. Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 99, 'Amazan, iwata yas kan unabi. Öebbi Iéôa ayen temmalem u ayen teppeffrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 100, 'Ini: "ur iaâdil ara wayen n dir akked wayen imaânen", xas teswehm ik lkwetôa n wayen n dir. Ëezzbet i Öebbi, a yuâqilen, amar a prebêem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 101, 'A wid iumnen! Ur steqsayet $ef t$awsiwin ara kwen icwe$ben, ma mlan awen tent. Ma testeqsam fellasent mara d iprusu Leqwôan, ad awen ppufessrent. Öebbi Isemmeê aya. Öebbi Ipsemmiê, Iêellem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 102, 'Ni$ isteqsa fellasent ugdud, uqbel nnwen. Sinna, segsent, gwran d d ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 103, 'Ur d Ifki Öebbi Baêiôa, ne$ Sayba, ne$ Waûila, ne$ Ëami. Maca, wid ijehlen gren d tikerkas $ef Öebbi. Tegwti degsen ur fhimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 104, 'Ma nnan asen: "yyaw ar wayen id Issers Öebbi, u ar Umazan". Qqaôen: "beôka ya$ ayen id nufa, $ef waya, $eô imezwura nne$". I ma imezwura nnsen ur ssinen acemma, ur pwanhan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 105, 'A wid iumnen! Fellawen iman nnwen. Ur kwen iîîuôôu win innetlafen, ma tepwanham. Ar Öebbi, tu$alin nnwen akw. A kwen Ixebbeô $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 106, 'A wid iumnen! Ccada garawen, ma tusa d tmeppant ar yiwen segwen. Di lawan uweûûi, sin irgazen iêesbiyen, segwen, ne$ wiyav war segwen, ma tellam d iminigen di tmurt, u tusa kwen id twa$it n tmeppant. A ten qesden deffir téallit. Ma tcukkem, sgallet pen s Öebbi: "ur d nesfayday syis, xas iaâna llzem nne$, ur nteffer ccada n Öebbi, mulac, nekwni a nili seg imednab".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 107, 'Ma ivehô ed fellasen denben, ad ppuneûfen s wiyav, si loiha n wid vuôôen imezwura. Ad ggalen s Öebbi: "ih, ccada nne$ tif ccada nnsen. Ur nzegger tilas, mulac, war ccekk, a nili seg imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 108, 'Ppif akka iwakken a d awin ccada iwulmen, ad agwaden a ppili tgallit deffir tgallit nnsen. Ëezzbet i Öebbi, ssemêesset, Öebbi ur Inehhu agdud iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 109, 'Ass ideg ara Issemlil Öebbi imazanen, ad Yini: "acu i wen d jawben"? Ad inin: "ur telli tussna $uône$. D Keçç, s tidep, i Issnen tibavniyin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 110, 'Mi Inna Öebbi: "a Âisa, mmi s n Meryem! Mmekti d i kwen £$ate$, keçç akked imma k, mi k Âiwne$ s ôôuê iôqan. Tepmmeslayev i medden si dduê, am unqaqôi. Mi k Slemde$ Tazmamt, ûûwab, Tuôa, Linoil. Mi tûenâav, si talaxt, ûûifa n ufrux, s– tsriê iW; tûuvev degs, tu$al d afôux, s– tsriê iW. Tesseêlayev agugam, amuvin n lberû, s– tsriê iW. Mi tessenkarev lmeggtin, s– tsriê iW. Mi Sbaâde$ fellak At Isôail, mi d tusiv $uôsen, s ubeggen, u nnan wid ijehlen segsen: "ayagi iban d ssêur kan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 111, 'Mi Weêêa$ i inmahalen: "amnet yissI, akw s umazan iW". Nnan: "numen. Echhed ar nekwni d imvuâen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 112, 'Mi nnan inmahalen: "a Âisa, mmi s n Meryem! Ma Izmer Mass ik ad a$ d Issers lmaida seg igenni"? Inna: "êezzbet i Öebbi, ma d lmumnin ay tellam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 113, 'Nnan: "neb$a a neçç segs, a nevmen ulawen nne$, a néeô ar tenniv a$ d tidep, a nili d inagan iS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 114, 'Inna Âisa, mmi s n Meryem: "a Öebbi, Mass nne$, Ssers a$ d lmaida, seg igenni, ad a$ tili d lâid i umezwaru u i uneggaru nne$, u d assekni s $uôeK. £it a$ d. Keçç, Tifev akw im$iten".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 115, 'Inna Öebbi: "ad awen p id Sserse$. Win ijehlen segwen, deffir waya, a t Âaqbe$ aâaqeb ur Sâadda$ i yiwen deg imavalen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 116, 'Mi Inna Öebbi: "a Âisa, mmi s n Meryem! D keçç i innan i l$aci: erret a$, nek akked imma, d sin iôebbiten war Öebbi"? Inna: "gedha s yiseK! Ur iyi ippunefk ara a d ini$ ayen i$ef ur sâi$ lêeqq. Lemmer i t id nni$, yili Teéôiv t. Tesnev i illan deg iman iw, ur ssine$ ayen illan deg iman iK. Keçç, s tidep, d Amusnaw n tbavniyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 117, 'I asen nni$, siwa ayen iyi d Tumôev: âabdet Öebbi, Mass iw, u Mass nnwen. Lli$ d anagi nnsen, skud lli$ garasen. Mi iyi n Tessuliv $uôeK, d Keçç i ten id Iquôâan. Keçç, d Anagi n yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 118, 'Ma Tâaqbev ten, ni$ d imdanen iK, ma Tsemmêev asen, Keçç, s tidep, d Uzmir, d Bab n ûûwab".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 119, 'Inna Öebbi: "wagi d ass ideg ara stenfâan imawlan n tidep, si tidep nnsen. I nitni leonanat, ddawat sen isaffen ppazzalen, ad wekkôen degsen, i lebda". Iôuva ten Öebbi, u ôuvan T, d wagi ay d rrbeê ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 120, 'N Öebbi tagelda n tmurt akked igenwan, akked wayen illan degsen. Neppa Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 1, 'A neckeô Öebbi i Ixelqen tamurt akked igenwan. Irra tillas, tafat. Sinna, wid ijehlen pparan tanudda i Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 2, 'Neppa, ikwen Ixelqen s talaxt, sinna, Iseyya lajel. £uôeS lajel ipwassnen. Deffir waya, kunwi la tepcukkum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 3, 'Neppa, d Öebbi deg igenwan, di tmurt. Issen sser nnwen, d wayen d teqqaôem. Iéôa ayen tkesbem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 4, 'Ur ten id ippas ussekni seg issekniyen n Mass nnsen, mebla ma ugin t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 5, 'Ni$ skaddben tidep, mi ten id tusa. A ten id ias usali n wayen i$ef ttihin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 6, 'Day ur walan ara acêal isuta, uqbel nnsen, ay Nekkes. Nesserked iten di tmurt akken ur kwen Nesserked. Nuzen asen aîas ugeffur, Nerra yasen isaffen, ppazzalen seddawat sen. Nesnegr iten ilmend ibekkaven nnsen. Nxelq ed, deffir sen, sself nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 7, 'Xas ad ak ed Nessers Tazmamt, di lka$ev, ara nnalen s ifassen nnsen, war ccekk, a d inin wid ijehlen: "wagi, s tidep, siwa ssêur n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 8, 'Qqaôen: "a lemmer id irs $uôes lmelk". Lemmer a n Nessers lmelk, war ccekk, ad iûaô lameô, sinna, ur pganin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 9, 'Lemmer i t Nerri d lmelk, yili Nerra t d argaz, ad as Nessels ayen plusun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 10, 'Ni$ mmaâlken $ef imazanen, uqbel ik. Ayen i$ef ttihin, izzi i wid, segsen, immaâlken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 11, 'Ini: "ddut di tmurt, sinna walit amek tevôa d wid iskiddiben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 12, 'Ini: "w i t ilan wayen akw illan di tmurt akked igenwan"? Ini: "d Öebbi". Iura, deg iman iS, aêunu. A kwen Issemlil i wass n tnekra, ur ccekk fellas. Wid isxesôen iman nnsen, ur ppamnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 13, 'IneS i ized$en deg iv, deg wass. Neppa Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 14, 'Ini: "day ara sâu$ bab, war Öebbi, Axellaq n tmurt akked igenwan? Neppa Icceççay ur t cceççayen". Ini: "nek pwamôe$ d ad ili$ d amenzu ara ianzen. Ur ppilit seg imcurak".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 15, 'Ini: "nek ugade$, ma aâûa$ Mass iw, aâaqeb n wass ameqwôaêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 16, 'Win imenâan segs, assen, ni$ Iêun fellas. Wagi d rrebê n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 17, 'Ma Isâadda Öebbi fellak cedda, ur p itekkes yiwen, siwa Neppa. Ma Isrebê ik, Neppa Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 18, 'D Neppa ay d Aqehhaô, sennig imdanen iS; d Neppa ay d Bab n ûûwab, i Iéôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 19, 'Ini: "anda p ccada sennig akw tiyav"? Ini: "Öebbi d Anagi gari yidwen. Iweêêa yi d Leqwôan agi, iwakken a kwen nabi$ yis, kunwi akked wid u$uô ibbwev. Day, kunwi, war ccekk, a pcehhdem ar, ar tama n Öebbi, llan iôebbiten nniven"? Ini: "ur cehhde$"! Ini: "Neppa d Öebbi, siwa Yiwen. Nek, rri$ akin ayen tepcarakem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 20, 'Wid iwumi Nefka Tazmamt, ssnen p, akken ssnen arraw nnsen. Wid isxesôen iman nnsen, ihi, ur ppamnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 21, 'Anwa idensen sennig win d igren tikerkas $ef Öebbi, ne$ iskaddben issekniyen iS? Ih, ur rebêen imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 22, 'Ass ideg ara ten Nefser meôôa, sinna a Nini i wid icurken: "anda ten icriken nnwen, i la tâabdem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 23, 'Deg uhewwel nnsen, siwa ma nnan d: "s Öebbi, Mass nne$, ur nelli d imcurak"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 24, 'Wali amek skaddben $ef yiman nnsen. Itelf iten wayen la d snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 25, 'Garasen wid i k issemêasen. Nerra aêurrim $ef ulawen nnsen, iwakken ur t fehmen. Tiâééegt deg imeééu$en nnsen. Ma walan yal assekni, ur ppamnen yis. Alamma, ma usan d $uôek, a k namren, ad ak inin wid ijehlen: ayagi siwa tiêkayin imezwura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 26, 'Sîixxiôen segs, îîeôôifen segs. Ay squccun siwa iman nnsen, ur faqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 27, 'Lemmer a ten twaliv, mara bedden ar tmes, a d inin: a ssexv nne$! Awi $ irran, ur neskiddib issekniyen n Mass nne$! A nili si lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 28, 'Xaîi! Iban asen d wayen teffren, zik. Lemmer a d kren, ad u$alen ar wayen i sen ipwagedlen. Nitni, s tidep, d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 29, 'U qqaôen: "siwa tameddurt n ddunit i illan. Nekwni, ur fella$ tanekra".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 30, 'Lemmer a pwaliv mara bedden ar Mass nnsen, ad Yini: "ni$ ayagi s tidep"? A d inin: "ih, s Mass nne$"! Ad Yini: "ihi jeôôbet aâaqeb, ilmend n wayen tejhilem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 31, 'Ni$ xesôen wid iskaddben timlilit akked öÖebbi. Alamma, ma iusa ten id yimir, deqzalla, a d inin: "a yamxix nne$, $ef wayen ideg nestehza"! Nitni ad bibben tiâakkwumin nnsen $ef izugar nnsen. I icmet wayen bubben!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 32, 'Tameddurt n ddunit d urar kan akked lhawiyya. Axxam aneggaru, war ccekk, yif ip i wid ipêezziben. Day ur tepmeyyizem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 33, 'Ni$ Neéôa i$webben ik, s tidep, wayen qqaôen. Ihi, nitni ur k skiddiben. Maca imednas veggôen issekniyen n Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 34, 'Ni$ skaddben imazanen uqbel ik. Üebôen $ef wayen i ten skaddben, akked wayen i ten meêênen, armi i ten id iusa usellek nne£. Ur illi ubeddel i wawalen n Öebbi. Ni$ usan k id, kra isallen imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 35, 'Ma ééay fellak uwexxeô nnsen, ma tzemôev a tessarmev aderbuz di tmurt, ne$ sellum s igenni, ad asen d tawiv assekni. Ma ihwa yaS i Öebbi, a ten Issemlil ar nnhaya. Ur ppili seg wid ur nessin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 36, 'Siwa wid isellen, ara d ijawben. Lmegtin a ten id Issker Öebbi, sinna, $uôeS tu$alin nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 37, 'Qqaôen: "acimi ur as d irs ara ussekni s$uô Mass is"? Ini: "Öebbi, s tidep, Izmer a d Issers assekni", maca tegwti degsen ur éôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 38, 'Ur illi lweêc di tmurt, ne$ ufrux ippafgen s wafriwen is, ur nelli d leoyus am kunwi. Ur Nestehza, di Tezmamt, $ef wacemma. Sinna, ar Mass nnsen, ad pwafessren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 39, 'Wid iskaddben issekniyen nne£, âaégen, gugmen, di tillas. Win i S ihwan i Öebbi, a t Itlef. Win i S ihwan, a t Iawi d ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 40, 'Ini: "twalam ma iusa kwen id uâaqeb n Öebbi, ne$ ma iusa kwen id yimir, day ar war Öebbi ara tnaâôem, ma tessawalem tidep?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 41, 'Xaîi! £uôeS ara tnujem. Ad Issiferr ayen i$ef tnujem $uôeS, ma ihwa yaS, a ppeppum ayen tcurkem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 42, 'Ni$ Nuzen ed ar leoyus, uqbel ik. Nesâadda fellasen tilufa, ccqa, amar ad êiwten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 43, 'A lemmer êawten, mi ten id tusa tiyta nne£. Maca, qehôen wulawen nnsen. Cciîan Icebbeê asen ayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 44, 'Mi ppun ayen i sen d smmektin, Nelli yasen tibbura n yal cci, armi, mi feôêen s wayen i sen ippunefken, Newwet iten, deqzalla. D$a qevâen layas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 45, 'Pwakksen wid id igwran seg ugdud idensen. Ccekôan i Öebbi, Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 46, 'Ini: "twalam, ma Iddem awen Öebbi timesliwt nnwen, akked iéôi nnwen; ma Isle$ ulawen nnwen; anwa ôebbi, war Öebbi, ar awen ten id iawin"? Wali amek Nessefham issekniyen, u nitni, sinna, zzin akin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 47, 'Ini: "acu twalam, ma iusa kwen id uâaqeb n Öebbi, deqzalla, ne$ âinani? Day ara Ine$, siwa agdud imednas"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 48, 'Ur d Nuzen imazanen, siwa i ubecceô, d unabi. Wid iumnen, ixeddmen ayen ilhan, ur ppagwaden, ur $weblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 49, 'Wid iskaddben issekniyen nne£, a ten iêaz uâaqeb, ilmend n wayen be$wven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 50, 'Ini: "ur awen qqare$ sâi$ igerrujen n Öebbi, ur ssine$ tabavnit; ur awen qqare$: nek, d lmelk. Nek, teddu$ kan akked wayen iyi d ippuweêêan". Ini: "day iaâdel uder$al d win ipwalin? Day ur d tepmeyyizem ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 51, 'Nabi yis wid iugaden ad pwafessren ar Mass nnsen. Ur sâin bab, war Neppa, ne$ amcafaâ. Amar ad êezzben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 52, 'Ur ppara wid ipnujun $uô Mass nnsen, taûebêit, tameddit, pnadin udem iS. Ur fellak a ten têasbev deg wacemma, ur fellasen a k êasben, deg wacemma. Ma terriv ten, ihi, a ppiliv seg imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 53, 'Akka ay Nhewwel kra s wiyav, iwakken a d inin: "day d wigi i I$at Öebbi, garane$"? Day ur Issin ara Öebbi, sennig akw, wid isnemmiren?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 54, 'Ma usan k id wid iumnen s issekniyen nne£, ini: "tifrat fellawen"! Mass nnwen Iura, i iman iS, aêunu. Ihi, i win, segwen, ixedmen tucmip, ur iâammed, sin akin, isteôoaâ, u ixdem ayen ilhan, Neppa Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 55, 'Akka ay Nfeûûel issekniyen, iwakken a d iban ubrid ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 56, 'Ini: "nek, ippugdel iyi ad âabde$ wid u$uô la tepnujum, war Öebbi". Ini: "ur teddu$ d lemcihwat nnwen, mulac ad nnetlafe$, ur ppili$ seg wid ipwanhan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 57, 'Ini: "nek, îîfe$ deg ubeggen n Mass iw. Teskaddbem t. Ur illi $uôi wayen u$uô têarem. Ih, aêuddu $eô Öebbi kan. Issawal tidep. Neppa Yif akw wid issenqaden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 58, 'Ini: "lemmer illi $uôi wayen u$uô têarem, yili iûaô lameô, gari yidwen". Öebbi Yif akw akken Issen imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 59, '£uôeS tisura n tbavnit. Siwa Neppa itent Issnen. Iéôa i illan di lberr, di yill. Ur i$elli ifer siwa ma Iéôa t. Akken aâqqa di tillas n tmurt, tizzegzewt, ta$eôt, akw di tezmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 60, 'D Neppa i wen ippaddamen leôwaê deg iv. Iéôa ay txeddmem, deg wass. Sinna, Ippara kwen id degs, iwakken ad ivôu lajel ipwassnen. Sinna, $uôeS tu$alin nnwen, sinna, a kwen Ixebbeô $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 61, 'D Neppa ay d Aqehhaô sennig imdanen iS. Ippazen ed $uôwen imêaraben, alamma, ma tusa d tmeppant ar yiwen segwen, ad ddmen ôôuê is, imceggâen nne£. Nitni ur stehzayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 62, 'Sinna, ad u$alen ar Öebbi, Bab nnsen n tidep. Aêuddu, day maççi d ayla S? Neppa Yif akw akken Ip$awal ar uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 63, 'Ini: "anwa ara kwen Isellken si tillas n lberr d yill, u$uô tnujem s uêiwet akked tugwdi"? "Ma Isellek a$ si tagi, war ccekk, a nili seg wid isnemmiren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 64, 'Ini: "Öebbi Isellek ikwen segs, akw si yal lhemm, sinna, kunwi la tepcarakem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 65, 'Ini: "Neppa, Izmer ad awen d Iazen aâaqeb sennig wen, ne$ seddaw ivaôen nnwen. Ne$ a kwen Issemfaôaq, kra segwen ad jeôôben leqheô n wiyav". Wali amek id Nemmal issekniyen, amar ad meêûen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 66, 'Iskaddeb it ugdud ik, u neppa d tidep. Ini: "ur awen lli$ d awkil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 67, 'Yal asali s lweqt is. A ppu$alem a ppeéôem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 68, 'Ma twalav wid ipnamaren $ef issekniyen nne£, eoo iten, alamma bedlen anamer. Ma iseppu k Cciîan, mi d temmektiv, ur p$imi d ugdud imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 69, 'Ur isefk ara i wid ipêezziben, a ten êasben deg wacemma. Maca d asmekti, amar ad êezzben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 70, 'Eoo wid irran ddin nnsen d urar, d aqesseô. T$uôô iten tmeddurt n ddunit. Mmekti d yis, ard a ipwaîîef umdan $ef wayen ikseb. Ur isâi, war Öebbi, bab ne$ amcafaâ. Yal le$ôama ur tepwaqbal segs. Widak d wid ipwaîfen $ef wayen kesben. I nitni tissit iô$an, aâaqeb aqeôêan, ilmend n wayen la jehlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 71, 'Ini: "day a nâaô, war Öebbi, ayen ur a$ neneffaâ, ur a$ neîîuôôu? U a nu$al a nwexxeô, deffir nnhaya n Öebbi, am win $ewwan ccwaîen di tmurt, u ippuêeyyeô". Pnecciden t imeddukwal ar nnhaya: "yya $uône$"! Ini: "d nnhaya n Öebbi, s tidep, ay d nnhaya. Nepwameô a nanez i Mass imavalen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 72, 'èéalet, êezzbet aS. £uôeS, Neppa, ara tepwafessrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 73, 'D Neppa i Ixelqen tamurt akked igenwan, s tidep. Ass ideg ara Yini: "ili"! Ad yili. Awal iS d tidep. IneS tagelda. Ass uûuvu n lbuq, Iéôa i iffren d wayen ivehôen. Neppa d Bab n ûûwab, i Iéôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 74, 'Mi inna Ibôahim i baba s, Azaô: "day a pperrev tiâancuôin d iôebbiten? Nek wala$ k, keçç akked ugdud ik, di ttelfan n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 75, 'Akka, Nessken i Ibôahim, tagelda n tmurt akked igenwan, iwakken ad yili seg wid itebbten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 76, 'Mi t i$umm yiv, iwala itri, inna: "wagi d Mass iw". Mi ixsi, inna: "ur êemle$ ara wid ixessin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 77, 'Mi iwala iuli d waggur n tziri, inna: "wagi d Mass iw". Mi i$ab, inna: "ma ur iyi Inha ara Mass iw, ad ili$, war ccekk, seg ugdud im$eôôqen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 78, 'Mi iwala iîij ineqqeô ed, inna: "wagi d Mass iw, wagi meqqweô kteô". Mi i$li, inna: "a yagdud iw! Nek rri$ akkin ayen tepcarakem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 79, 'Nek zzi$ udem iw ar Win Ixelqen tamurt akked igenwan, male$ ar tidep. Ur lli$, nek, seg imcurak".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 80, 'Ixuûem it ugdud is, inna: "day ad iyi txaûmem $ef Öebbi? Ni$ Inha yi; ur ugade$ ayen i S tcurkem, siwa ma illa wayen i S ihwan i Mass iw. Tussna n Mass iw tezdi yal cci, day ur d tesmektayem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 81, 'Amek ara ugade$ ayen tepcarakem, ur tugadem mi kunwi tepcarakem, i Öebbi, ayen iwumi ur d Issers adabu fellawen? Anwa, ger sin ikabaran, i iklalen laman, maday tessnem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 82, 'Wid iumnen, ur sselsen ddens i liman nnsen, widak ad ilin di laman, u nitni pwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 83, 'D wagi ay d awal nne£. Nefka yas t i Ibôahim, mgal agdud is. Nessalay tiseddaôin, win i£ £ ihwan. Ih, Mass ik d Bab n ûûwab, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 84, 'Nefka yas Isêaq akked Yaâqub. I sin, Nenha ten. Nenha, zik, Nuê akw, ger tarwa s, Dawed, Sliman, Yub, Yusef, Musa, Haôun, - Akka ay Nepkafi iâaôviyen -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 85, 'Zakarya, Yeêya, Âisa, Ilyas, - akw seg iâaôviyen -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 86, 'Ismaâil, Lyasâa, Yunes, Luî, - akw Nesmenyaf iten $ef imavalen -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 87, 'akw seg ibabaten nnsen, si tarwa nnsen, akked watmaten nnsen. Nefren iten, u Nebbwi ten d ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 88, 'Tagi d nnhaya n Öebbi. Inehhu yis win i S ihwan, deg imdanen iS. Lemmer curken, war ccekk, ad asen imêu wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 89, 'D wigi iwumi d Nebbwi Tazmamt, ûûwab, akked lambiyya. Ma jehlen widak yis, ihi, Nekwni Nwekkel ip i ugdud ur njehhel yis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 90, 'Wigi d wid Inha Öebbi. Ddu d nnhaya nnsen. Ini: "ur awen suture$, fellas, taqdiât. Neppa d asmekti kan i imavalen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 91, 'Ur qudôen Öebbi azal n lqedô iS, mi qqaôen: "ur d Issers Öebbi acemma ar umdan". Ini: "anwa id Issersen Tazmamt, id ibbwi Musa, d tafat u d nnhaya i medden? Tepparam p di lkwa$ev i tesskanem. Aîas ay teppeffrem. Tlemdem ayen ur tessinem, kunwi akked imezwura nnwen". Ini: "D Öebbi". Sinna, anef asen ad uraren s nnmara nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 92, 'Tagi d Tazmamt, Nessers ip id teôqa, a ptebbet ayen ip id izwaren, a ppendeô tayimmap n temdinin akked wayen i s d izzin. Wid iumnen s laxeôt, umnen yis. Nitni bedden i téilla nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 93, 'Anwa idensen sennig win d igren tikerkas $ef Öebbi? Ne$ inna: "ppuweêêa$ d", ur as d ippuweêêa wacemma? U win innan: "a d sserse$ am wayen id Issers Öebbi"? Lemmer a pwaliv imednas, di maylellif n tmeppant, u lmalayek élent ed ifassen nnsent: "ssuff$et ed tiôwiêin nnwen. Assa, a ppeppuqeîîim s uâaqeb isneêcamen, ilmend n wayen teqqaôem $ef Öebbi, ur d tidep. U tellam tessem$waôem iman nnwen, $ef issekniyen iS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 94, 'Ni$ tusam a£ d, d ifôiden, akken ikwen Nexleq abrid amezwaru. Teooam deffir wen, ayen i wen Nefka. Ur Nwala, $uôwen, imcafâen nnwen, wid i tâabdem, nitni, d icriken nnwen. Ni$ temfaôaqem, u ooan kwen wid la tâabdem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 95, 'Öebbi, s tidep, Ifeôôec aâqqa, i$es. Issuffu$ ed amuddir si lmegget. Issuffu$ ed lmegget seg umuddir. Akka ay d Öebbi. Acimi tugim?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 96, 'Issenkar tafrara. Irra iv i ureyyeê, iîij d waggur i leêsab. D wagi ay d aseyyi n Uzmir, Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 97, 'D Neppa i wen Irran itran, ad awen mlen abrid, di tillas n lberr akked yill. Ni$ Nemmal issekniyen i ugdud issnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 98, 'D Neppa ikwen id Ixelqen si yiman afôid, sinna: amkan, tarusi. Ni$ Nemmal issekniyen i ugdud ifehhmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 99, 'D Neppa id Isrusun aman seg igenni. Nessuffu$ ed yissen yal im$an. Nessuffu$ ed yissen tizzegzewt. Nessuffu$ ed yissen iâaqqayen mbabben, iguza n ppmeô id ipûubbun si tezdayin, leonanat n tfeôôant, uzemmur, n ôemman, ppemcabin ne$ ur ppemcabin. Walit ppemôa nnsen mi d teffe$ tebbwa. Ih, deg waya, war ccekk, issekniyen i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 100, 'Rran i Öebbi, leonun d icriken, u Ixelq iten. Snulfan aS d arrac, tullas, ur éôin. Gedha s yiS! Ay Aâlay sennig wayen d qqaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 101, 'Axellaq n tmurt akked igenwan, amek ara Isâu mmi S, ur Isâi tameddakwelt? U Ixleq yal cci, u Neppa, yal cci, Issen it.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 102, 'D wagi ay d Öebbi, Mass nnwen, ur illi ôebbi siwa Neppa. Ixleq yal cci, ihi âabdet eP. Neppa d Awkil n yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 103, 'Ur T tepsami tmu$li. Neppa Ipsami tamu$li. Neppa d Laîif, i Izôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 104, 'Ni$ iusa kwen id ara twalim, s$uô Mass nnwen. Win iwalan, i iman is; win idre$len, mgal is. Ur lli$ nek d amêareb nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 105, 'Akka ay Nessefham issekniyen, iwakken ad inin: "tlemdev", iwakken a t Nbeggen i ugdud issnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 106, 'Ddu d wayen ik ed ippuweêêan, s$uô Mass ik; ur illi ôebbi siwa Neppa. Eoo imcurak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 107, 'Lemmer i S ihwi i Öebbi, ur curken. Ur k Nerra d amêareb nnsen, ur telliv d awkil nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 108, 'Ur naâlet wid u$uô la pnujun, war Öebbi. Axaîeô ad naâlen Öebbi, s lbe$wv, war tamusni. Akka ay Ncebbeê igiten is i yal lois. Sinna, ar Mass nnsen, tu$alin nnsen; a ten Ixebbeô $ef wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 109, 'Ggulen s Öebbi, tagalit meqqwôen, ar ma iusa ten id ussekni, ar ad amnen yis. Ini: "issekniyen ar Öebbi kan". Acu i kwen irran têussem ar, xas ma iusa ten id, ur ppamnen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 110, 'A Neppi ulawen nnsen, d yiéôi nnsen, akken ur uminen yis abrid amezwaru. A ten Neoo di lbe$wv nnsen, d ider$alen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 111, 'Xas Nekwni Nessers asen d lmalayek, u mmeslayen asen d lmeggtin, u Nefser asen d, yal cci, zdat sen, ur ppamnen, siwa ma ihwa yaS i Öebbi. Maca, aîas degsen ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 112, 'Akka ay Nerra, i yal nnbi, acengu. Ccwaîen, seg imdanen akw si leonun, ppemweêêin garasen awal uziyn i u$uôôu. Lemmer i S ihwi, i Mass ik, ur p xeddmen. Ihi, eoo iten ar wayen d snulfuyen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 113, 'iwakken ad mmalen $uôes ulawen n wid ur numin s laxeôt, a t ôavin, ad gemren ayen zerâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 114, 'Day b$i$ amêaddi, war Öebbi? D Neppa i wen d Issersen Tazmamt, s ussefhem. Wid iwumi Nefka Tazmamt, éôan, ar neppat, ters ed s$uô Mass ik, s tidep. Ur ppili seg wid ipcukkun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 115, 'Awal n Mass ik ibbwev, s tidep akked lmizan. Ur illi ubeddel deg wawal iS. Neppa Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 116, 'Ma tu$ev awal i tegwti n wid illan di tmurt, a k telfen seg ubrid n Öebbi. Teddun kan d wayen nwan. Nitni snulfuyen d kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 117, 'Ih, Mass ik Issen sennig akw, anwi innetlafen seg ubrid iS. Neppa Issen sennig akw, anwi ipwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 118, 'Eççet ayen i$ef d immekti isem n Öebbi, ma tumnem s issekniyen iS.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 119, 'Acu ikwen iu$en, ur teppeppem ara seg wayen i$ef d immekti isem n Öebbi? Ni$ Issfehm awen ayen i wen Igdel, siwa ma ipwaêeppem fellawen. Ih, aîas ay tellifen, s zzhu nnsen, war tussna. Ni$ Mass ik Iugar akw akken Issen wid izegren tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 120, 'Ekkset abekkav uvhiô akked uffir. Ih, wid ibbwin abekkav, ad ppuqeîîin $ef wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 121, 'Ur teppet ayen i$ef ur d immekti ara, isem n Öebbi. Ih, ayagi d ixmiô. Ih, ccwaîen pweêêin i imeddukwal nnsen, a kwen namren. Ma tu$em asen awal, kunwi, s tidep, tcurkem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 122, 'Ma win illan d lmegget, Nessider it id, Nga yas tafat, iteddu yis ger medden, day d amedya s, win illan di tillas, ur izmir ad iffe$ segsent. Akka, ippucebbeê i ijehliyen, wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 123, 'Akka ay Nerra, ad ppandin di yal tamdint, ibe$wviyen is, uqsiêen mavi. Ppandin kan i iman nnsen, ur faqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 124, 'Ma iusa ten id ussekni, ad inin: "ur neppamen, alamma iusa ya$ d ayen id iusan ar imazanen n Öebbi". Öebbi Yif akw akken Issen, anida ara Ifk tabôap iS. Ad iôxisen, ar Öebbi, wid ibe$wven. Fellasen aâaqeb uqsiê, ilmend n wayen ppandin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 125, 'Win Ib$a Öebbi a t Inhu, ad illi idmaren is ar wannuz. Win Ib$a a t Itlef, ad Irr idmaren is deyqen, têeyyôen, amzun ippaâôav ad iali s igenni. Akka i Ippara Öebbi axerwaâ i wid ur numin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 126, 'Wagi d abrid uwqim n Mass ik. Ni$ Nessefham issekniyen i ugdud ismektayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 127, 'I nitni, axxam n tifrat ar Mass nnsen. Neppa d Bab nnsen, $ef wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 128, 'Ass ideg ara ten Ifser meôôa: "a yagraw n leonun, ni$ tcerrâem deg imdanen"? A d inin imawlan nnsen, seg imdanen: "a Mass nne$! Kra segne$ $elten si kra, Nebbwev ar lajel nne$, i $ Terriv". Inna: "d times ay d tanezdu$t nnwen, ad degs twekkôem, siwa ma ur aS ihwi i Öebbi". Ih, Mass ik d Bab n ûûwab, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 129, 'Akka ay Neppara kra imednas d iêbiben n kra, ilmend n wayen keppben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 130, '"A yagraw n leonun d yimdanen, day ur kwen id usan ara imazanen segwen? Mmalen awen issekniyen iW, nedôen kwen $ef temlilit n wass nnwen agi". Nnan d: "ncehhed $ef yiman nne$". T$uôô iten tmeddurt n ddunit. Cehhden $ef yiman nnsen ar nitni, s tidep, llan d ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 131, 'Akka, acku Mass ik ur Isquccu tamdint, s ddens, ma llan imezda$ is d i$wefliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 132, 'I yal yiwen, tiseddarin seg wayen ixdem. Ur I$effel Mass ik $ef wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 133, 'Mass ik d Asâay, d Bab uêunu. Ma ihwa yaS a kwen Ikkes, a d Inûef, deffir wen, ayen i S ihwan, akken ikwen id Ixleq si tarwa n ugdud nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 134, 'Ih, ayen i wen ippuâahden, a d ias, war ccekk. Ur tezmirem, kunwi, a ppesfunngem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 135, 'Ini: "a yagdud iw! Xedmet akken tewâam, nek ad xedme$. Deqqal a ppeéôem iwumi ara telhu taggara n Uxxam". S tidep, ur rebêen imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 136, 'Gan aS i Öebbi amur, seg wayen id Ifka n l$ella, akked lmal. Nnan: "wagi i Öebbi –- di tikta nnsen -, wagi i icriken nne$". Ayen gan i icriken nnsen, ur ippawev ar Öebbi. Ayen gan i Öebbi, neppa, ad yawev ar icriken nnsen. I icmet wayen id pêuddun!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 137, 'Akka ay cebbêen icriken nnsen, i waîas n yimcurak, timen$iwt n tarwa nnsen, iwakken a ten squccen, u ad irwi ddin nnsen, fellasen. Lemmer i S ihwi i Öebbi, ur p xeddmen. Eoo iten ar wayen d snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 138, 'Nnan: "lmal akked l$ella yagi ppugedlen, ur ten itepp, siwa win i $ ihwan". S tikta nnsen. Lmal iwumi gedlen iârar nnsen, lmal iwumi ur d ppadren fellasen, isem n Öebbi. D asnulfu mgal iS. A ten Iqeîîi $ef wayen d snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 139, 'Qqaôen: "ayen illan deg iâabbav n lmal agi, i ddker nne$ kan, ipwagdel i tlawin nne$". Ma ilul ed immut, ad mlilen $uôes. A ten Iqeîîi $ef wayen d qqaôen. Neppa, s tidep, d Bab n ûûwab, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 140, 'Ni$ xesôen wid in$an arraw nnsen. D tiderwect, war tussna. Gedlen ayen i s iten I$at Öebbi, snulfan d mgal Öebbi. Ni$ nnetlafen, ur pwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 141, 'D Neppa id Ixelqen leonanat s iâricen, ne$ war iâricen, tizdayin, zerriâa n yal ûûenf, i wuççi; azemmur akked rreman ippemcabin, ne$ ur neppemcabi. Eççet si ppemôa nnsen, ma fkan d, efket leêqq is, ass u$ellet nnsen. Ur ssugutet. Neppa, s tidep, ur Iêemmel ara wid ipêawalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 142, 'Si lmal, aggway d wussu. Eççet seg wayen ikwen Iôéeq Öebbi. Ur teddut d iberdan n Cciîan. Neppa, s tidep, d acengu nnwen n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 143, 'Ïamt tyugiwin, snat u$welmi, snat umâiz. Ini: "d sin n ddker i Igdel, ne$ d snat n nnta, ne$ d ayen illan deg iâabbav n snat n nnta? Xebbôet iyi d, s tussna, ma tessawalem tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 144, 'Seg ile$wman, snat, seg ubeqôi, snat. Ini: "d sin n ddker i Igdel, ne$ d snat n nnta, ne$ d ayen illan deg iâabbav n snat n nnta, ne$ tellam d inagan mi kwen id Iweûûa Öebbi $ef waya"? Anwa idensen sennig win id igren tikerkas $ef Öebbi, iwakken ad itlef imdanen, ur issin. Ih, Öebbi ur Inehhu agdud imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 145, 'Ini: "ur ufi$ ipwagdel a t içç yiwen, deg wayen iyi d ippuweêêan, siwa ma illa d loifa, ne$ d idim immaren, ne$ d aksum n yilef - wagi, war ccekk, d lewsex -, ne$ îêegga s d$wel i war Öebbi. Win i$ef ippuêeppem, ur ib$i, ur ib$wiv, Mass ik, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 146, 'I wudayen, Negdel ayen akw isâan acaren, seg ubeqôi akked u$welmi, Negdel asen tassemt nnsen, siwa tin n iârar nnsen, iâabbav, akked wayen ipwaxelven akked i$san. Akka ay ten Nepkafi, ilmend n îîeôô nnsen. Nekwni, war ccekk, d At Tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 147, 'Ma skaddben k, ini: "Mass nnwen d Bab uêunu iwsâan, ur ipwexxiô ssexv iS, af ugdud ibe$wviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 148, 'Ad inin imcurak: "lemmer i S ihwi i Öebbi, nekwni akked imezwura nne$, ur ncurek, ur negdel acemma". Akka ay skaddben imezwura nnsen, armi jeôôben ssexv nne£. Ini: "day tesâam tussna ar a$ d tesseknem? Teppeddum kan d nnwaya, kunwi tesnulfuyem d kan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 149, 'Ini: "n Öebbi timenna tunûiêin. Lemmer i S ihwi, yili Inha kwen akw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 150, 'Ini: "awit ed inagan nnwen, ara icehhden ar Öebbi Igdel ayagi". Ma cehhden, ur cehhed yidsen. Ur teddu d lhawiyya n wid iskaddben issekniyen nne£, akked wid ur numin s laxeôt, u pparan tanudda i Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 151, 'Ini: "yyaw, ad ini$. I wen Igdel Mass nnwen: ur aS tepcarakem acemma; elhut ar imawlan nnwen; ur neqqet tarwa nnwen, di tigullelt - d Nekwni ara kwen Iôeéqen yidsen -, ur ppaéet ar lâaô, d uvhiô ne$ d uffir; ur neqqet amdan, d ayen Igdel Öebbi, siwa ma s lêeqq". Ar waya i kwen Iweûûa, amar a pfehmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 152, 'Ur pqeôôibet s ayla ugujil, siwa s wayen ilhan, alamma immeêtel. Weznet, ktilet s lewqama. Ur Nepkellif amdan siwa ar wayen iwumi izmer. Ma thedôem d, weznet, xas ma $eô llzem nnwen. Qadôet lemâahda n Öebbi. Iweûûa kwen $ef waya, amar a d temmektim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 153, 'D wagi ay d abrid iW uwqim, ddut degs. Ur teddut d iberdan ara kwen isîixôen seg ubrid iS. Iweûûa kwen $ef waya, amar a pêezzbem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 154, 'Sinna, Nefka Tazmamt i Musa. Tewqem i wid imaânen, tfeûûel yal cci, d nnhaya u d aêunu. Amar ad amnen s timlilit n Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 155, 'Tagi d Tazmamt, Nessers ip id, teôqa. Ihi, ddut yides, êezzbet, amar fellawen aêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 156, 'Ur d teqqaôem ara: "ters ed kan Tezmamt $eô sin leoyus, uqbel nne$, ur neéôi d acu sselmaden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 157, 'Ne$ a d tinim: "lemmer id ters Tazmamt $uône$, yili nif iten akken nepwanha". Ni$ iusa kwen id ubeggen, s$uô Mass nnwen, d nnhaya u d aêunu. Anwa idensen sennig win iskaddben issekniyen n Öebbi, u iooa iten? A Nqeîîi wid iooan issekniyen nne£, s yir aâaqeb, ilmend n wayen la ppaooan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 158, 'D acu pôaoun, siwa ma ten id asent lmalayek, ne$ a d Ias Mass ik, ne$ a d asen kra issekniyen n Mass ik? Ass ideg ara d asen kra issekniyen n Mass ik, ur infaâ umdan liman is, ma, iu$ lêal, ur iumin ara, ne$ ur iksib lxiô, di liman is. Ini: "gganit, nekwni, ih, la nepgani".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 159, 'Ih, wid ibvan ddin nnsen, u gan ikabaren, ur tepkkiv yidsen deg wacemma. Lameô nnsen ar Öebbi kan, sinna, a ten Ixebbeô $ef wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 160, 'Win id iusan s yise$, ines mraw i t icban; win id iusan s tucmip, ad ippuqeîîi s tin kan i p icban; nitni ur pwadensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 161, 'Ini: "nek, Inha iyi Mass iw, ar ubrid uwqim, d ddin n ddwam, win n Ibôahim, i imalen ar tidep, ur nelli seg imcurak".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 162, 'Ini: "ih, taéallit iw, iseflan iw, tudert iw, tameppant iw, i Öebbi, Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 163, 'Ur aS illi ucarek. Pwamôe$ d s waya: nek d amduâ amenzu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 164, 'Ini: "day b$i$ mass, war Öebbi? U Neppa d Mass n yal cci". Ur ikesseb yal yiman, siwa mgal is. Ur ipbibbi win ibubben taâkkwemt n wayev. Sinna, ar Mass nnwen, tu$alin nnwen. Sinna, a kwen Ixebbeô $ef wayen tellam temgaradem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 165, 'D Neppa i kwen Irran d igensas di tmurt. Irra, kra segwen, tiseddaôin sennig wiyav, iwakken a kwen Ijeôôeb $ef wayen i wen Ifka. Ih, Mass ik Ip$awal deg uâaqeb. Neppa, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 1, 'Almû.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 2, 'Tazmamt ters ed $uôek, ur teppili segs lhejna deg idmaren ik, iwakken a pnabiv yis; u d asmekti i lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 3, 'Ddut d wayen id irsen $uôwen, s$uô Mass nnwen. Ur teddut d imawlan, war Neppa. Drus id tesmektayem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 4, 'Acêal n temdinin ay Nessenger. Tusa ten id tiyta nne£, deg ives nnsen, ne$ deg uqeggel nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 5, 'Ti$ôi nnsen, mi ten id tusa tiyta nne£, siwa mi d nnan: "ih, nella d imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 6, 'War ccekk, a Nesteqsi wid u$uô id Nuzen, a Nesteqsi imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 7, 'War ccekk, ad asen Neêku, s tmusni, ur Nelli N$ab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 8, 'Awzan, assen, d tidep. Wid iwumi ééayet lweznat nnsen, widak d wid irebêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 9, 'Wid iwumi fessuset lweznat nnsen, widak d wid ixesôen iman nnsen, seg akken sednasen issekniyen nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 10, 'Ni$, s tidep, Nesrekd ikwen di tmurt, Nerra yawen, degs, tamâict nnwen. Drus ay tesnemmirem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 11, 'Ni$, s tidep, Nxelq ikwen, sinna, Nmesl ikwen, sinna, Nenna i lmalayek: "knumt i Adem"! Knant, siwa Iblis. Ur illi seg wid iknan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 12, 'Inna: "acu k iîîfen ur tekniv ara, mi k d Umôe$"? Inna d: "Nek, ife$ t. Txelqev iyi si tmes, Txelqev t si talaxt".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 13, 'Inna: "ihi, ûûub segs! Ur ak ippunefk ara a ppesme$wôev iman ik, degs. Effe$, keçç seg wid ixuûen"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 14, 'Inna: "Eoo iyi, ar ass ideg ara d kkren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 15, 'Inna: "keçç, ih, seg wid ara iqqimen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 16, 'Inna d: "imi iyi Tâammdev a$ewwu, ad asen qqime$, war ccekk, deg ubrid iK uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 17, 'Sinna, ad asen d tekke$ zdat, deffir, yeffus, zelmev. Ur Teppafev, $eô tugwti segsen, asnemmer".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 18, 'Inna: "effe$ segs, d ameêquô ippuvegôen! War ccekk, ad Acaôe$ Loahennama s wid, segsen, i k ivefôen, akked yiswen akw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 19, 'A Adem, ezde$ Loennet, keçç akked tmeîîut ik, eççet seg wayen i wen ihwan. Ur pqeôôibet ttejôa agi, mulac a ppilim seg imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 20, 'I$ewwa ten Cciîan, iwakken ad asen d iban âaryan nnsen i illan iffer. Inna: "Ikkes awen, kan, Mass nnwen, ttejôa agi, iwakken ur teppilim d lmalayek, ne$ ur tepwekkiôem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 21, 'Iggul asen: "nek, i kunwi, d unûiê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 22, 'Isdull iten s u$uôôu. Mi âaôven si ttejôa nni, walan iman nnsen aâran. Lhan d la pcuddun, $ef iman nnsen, afriwen n Loennet. Issawel asen d Mass nnsen: "day ur awen Gdile$ ara ttejôa nni? Ad awen Ini$: war ccekk, Cciîan, i kunwi, d acengu n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 23, 'Nnan: "a Mass nne$! Nvuôô iman nne$. Ma ur a$ Tsemmêev, ur Têunev fella$, a nili seg imexsuôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 24, 'Inna: "erset! Kra d icenga n kra. A pzed$em di tmurt, a ppezhum, tallit kan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 25, 'Irna: "degs a ppidirem, degs a ppemmtem, segs a d teff$em".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 26, 'A tarwa n Adem! Ni$ Nessers awen ed aceîîiv ara kwen issôen, ôôêuê, akked uceîîiv uêezzeb. Wagi yif iten". Ayagi seg issekniyen n Öebbi, amar a d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 27, 'A tarwa n Adem! £uôwat a kwen ihewwel Cciîan, akken id issuffe$ imezwura nnwen si Loennet! Ikkes asen iceîîiven nnsen, iwakken ad asen issken âaryan nnsen. Neppa, war ccekk, ipwali kwen - neppa akked ccetla s - seg wanda ur ten tepwalim. Ni$ Nerra ccwaîen d imawlan n wid ur numin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 28, 'Mi xedmen ayen n dir, ad inin: "nufa d akka ar imezwura nne$, u Öebbi Iumeô a$ d $uôes. Ini: "Öebbi, s tidep, ur Ippameô ar wayen n dir. Day a d tinim $ef Öebbi, ayen ur tessinem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 29, 'Ini: "Iumeô ed Öebbi lmizan. Zzit $uôeS udmawen nnwen di yal lekni, nujet $uôeS. £uôeS, s ddin iûfan. Akken ikwen id Ixleq, a ppu$alem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 30, 'Arbaâ Inha it, arbaâ iura ttelfan fellas. Nitni, s tidep, rran ccwaîen d iêbiben, war Öebbi. U $ilen nitni, war ccekk, pwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 31, 'A tarwa n Adem! Ccebêet i yal lekni, eççet, esswet, ur sîuqqutet. Neppa, s tidep, ur Iêemmel ara wid isîuqquten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 32, 'Ini: "anwa i igedlen ccbaêa n Öebbi, id Issuffe$ i imdanen iS, akked ôôeéq ilhan"? Ini: "ayagi, di tmeddurt n ddunit, i wid iumnen. I nitni kan ass n tnekra". Akka ay Nfeûûel issekniyen i ugdud issnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 33, 'Ini: "Mass iw Igdel kan ayen n dir, d uvhiô ne$ d uffir, abekkav, tem$weô war ssebba, a pcarkem i Öebbi ayen iwumi ur d irs udabu, a ppinim $ef Öebbi ayen ur tessinem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 34, 'Yal lois isâa lajel. Ma iusa d lajel nnsen, ur t swexxiôen s ssaâa, ur t id ééaéan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 35, 'A tarwa n Adem! Ma usan kwen id imazanen segwen, mmalen awen issekniyen iW, wid ipêezziben, ixeddmen ayen ilhan, ur ppagwaden, ur $weblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 36, 'Wid iskaddben issekniyen nne£, u sme$wôen iman nnsen fellasen, widak d at tmes, nitni degs ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 37, 'Anwa idensen sennig win id igren tikerkas $ef Öebbi, ne$ iskaddben issekniyen iS? Widak, a ten iêaz umur i sen iuran di Tezmamt. Alamma, mi ten id usan imceggâen nne£, ad ddmen leôwaê nnsen, ad inin: "anida ten wid u$uô tepnujum, war Öebbi"? A d inin: "ur ten nufi". Ad cehhden, $ef yiman nnsen, ar nitni llan d ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 38, 'Inna: "kecmet di tmes ar leoyus n leonun akked yimdanen, i kwen id izwaren"! Yal tikelt ara ikcem lois, ad ixzu gma s. Alamma, mi mlalen degs akw, ad yini uneggaru nnsen $ef umezwaru nnsen: "a Mass nne$! Wigi telfen a$, Aâqeb iten s tmes, berdayen". Inna: "i yal yiwen berdayen, maca ur teéôim ara".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 39, 'Inna umezwaru nnsen i uneggaru nnsen: "ur kwen smenyafen i nekwni, ihi jeôôbet aâaqeb, ilmend n wayen tkeppbem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 40, 'Ih, wid iskaddben issekniyen nne£, u sme$wôen iman nnsen fellasen, ur asen tellin tibbura igenni, ur keçmen Loennet, skud ur iâadda ara ul$em di tiî n tsegnit. Akka ay Nepqeîîi ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 41, 'I nitni ameîôeê di Loahennama, ad $ummen s tmes. Akka ay Nepqeîîi imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 42, 'Wid iumnen, ixeddmen ayen ilhan - ur Nepkellif i umdan siwa ayen iwumi izmer - widak, d at Loennet, nitni, degs, ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 43, 'A Nekkes i d igwran n dd$el, deg idmaren nnsen. Isaffen ad ppazzalen ddawat sen. Ad inin: "ccekôan i Öebbi i $ Inhan $eô waya. Ur nepwanhu, lemmer ur a$ Inha ara Öebbi. Ni$ usan d imazanen n Mass nne$, s tidep". Ad pwanecden: "appan Loennet, tweôtem p, ilmend n wayen txeddmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 44, 'At Loennet ad siwlen i at tmes: "ni$ nufa i $ Iâahed Mass nne$, s tidep. Ma tufam ayen i wen Iâahed Mass nnwen, s tidep"? A inin: "Ih". Iberreê uberraê garasen: "xezzu n Öebbi i imednas,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 45, 'wid iîîeôôifen seg ubrid n Öebbi, ssaramen t d uâwij, u nekôen laxeôt".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 46, 'Garasen ssteô. £ef iqacucen, irgazen, ssnen ten akw, ar ûûiffat nnsen. Ad siwlen i at Loennet: "tifrat fellawen"! Ur p keççmen, xas ssarmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 47, 'Mi zzint wallen nnsen ar at tmes, ad inin: "a Mass nne$! Ur a$ Ppara s agdud imednas"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 48, 'Ad siwlen at iqacucen i irgazen, ssnen ten ar ûûiffat nnsen. Ad inin: "acu i wen d issuli wayen tjemâam akked wayen tzuxxem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 49, 'Day wigi d wid i$ef teggulem, ar ur sen ippak Öebbi aêunu? "Kecmet Loennet, ur teppagwadem, ur t$weblem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 50, 'At tmes ad siwlen i at Loennet: "smiret ed fellane$ aman, ne$ seg wayen is ikwen I$at Öebbi". Ad inin: "Öebbi, s tidep, Igdel iten i ijehliyen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 51, 'wid irran ddin nnsen d zzhu, d urar, u t$uôô iten tmeddurt n ddunit". Ihi, assa, a ten Neppu, akken ppun timlilit n wass nnsen agi, u nekôen issekniyen nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 52, 'Ni$ Nusa ten id s Tezmamt, Nfeûûel ip s tussna. D nnhaya, d aêunu i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 53, 'Day la pôaoun kan veôôu s? Ass n tisin n veôôu s, ad inin wid illan, iu$ lêal, ppun p: "ni$ usan d imazanen n Mass nne$, s tidep. Day nesâa imcafâen ara $ icafâen, ne$ ad a$ rren, a nexdem ayen mgirrden wayen nxeddem"? Ni$ sxeûôen iman nnsen. Itelf iten wayen d snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 54, 'S tidep, Mass nnwen d Öebbi. Ixelq ed tamurt akked igenwan di sdis wussan, sinna, Iâannec $ef usgeld. Ip$ummu iv s wass, ip$awalen $uôes. Iîij, aggur, akked yitran unzen i lameô iS. Day maççi ineS lxelq akked lameô? D Asaâdi Öebbi, Mass imavalen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 55, 'Naâret Mass nnwen, s wannuz, di tbavnit. Neppa, s tidep, ur Iêemmel ara wid izegren tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 56, 'Ur ssefsadet di tmurt deffir useêôet is. Naâôet eP, s tugwdi d usirem. Aêunu n Öebbi, s tidep, ar tama n lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 57, 'D Neppa id Ippaznen avu, d abecceô s uêunu S. Alamma, ma ibbub ed asigna aéayan, Nenheô it ar tmurt immuten. Nesse$li d syis aman. Nessuffe$ ed yissen yal ppemôa. Akka ay d Nessuffu$ lmeggtin, amendeô ma d tesmektim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 58, 'Di tmurt lâali, teff$en d im$an is, ma Irad Öebbi. Di tin icemten, teff$en d kan d iweqweqen. Akka ay Nepbeggin issekniyen i ugdud isnemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 59, 'Ni$ Nuzen ed Nuê i ugdud is. Inna: "a yagdud iw! Âabdet Öebbi! Ur tesâim ôebbi war Neppa. Nek ugade$ fellawen aâaqeb, ass ameqwôaêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 60, 'Nnan imvebbôen n ugdud is: "$uône$, s tidep, aql ak di ttelfan n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 61, 'Inna: "a yagdud iw! Ur illi dgi ttelfan. Maca nek d amazan s$uô Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 62, 'Bbwi$ awen d tibratin n Mass iw, a kwen neûêe$. Ssne$, s$uô Öebbi, ayen ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 63, 'Day twehmem mi kwen id iusa usmekti s$uô Mass nnwen, ibbwi t id urgaz segwen, iwakken a kwen inabi, iwakken a pêezzbem, amar fellawen aêunu"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 64, 'Skaddben t. Nsellek it, akked wid illan yides, di lbabuô. Ne$meq wid iskaddben issekniyen nne£. Nitni, s tidep, d agdud ader$al.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 65, 'Ar Âad, gmat sen Hud. Inna: "a yagdud iw! Âabdet Öebbi! Ur tesâim ôebbi, war Neppa. Day ur tepêezziben ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 66, 'Nnan imvebbôen, wid ijehlen seg ugdud is: "s tidep, $uône$, deg k tisselbi; $uône$, ih, keçç seg wid iskiddiben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 67, 'Inna: "a yagdud iw! Ur dgi tisselbi. Maca nek d amazan s$uô Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 68, 'Bbwi$ awen d tibratin n Mass iw. Nek, i kunwi, d aneûûaê muman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 69, 'Day twehmem mi kwen id iusa usmekti s$uô Mass nnwen, ibbwi t id urgaz segwen, iwakken a kwen inabi. Mmektit ed mi kwen Irra d igensas, deffir ugdud n Nuê. Isem$weô aîas lqedd nnwen. Mmektit ed lxiô n Öebbi, amar a prebêem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 70, 'Nnan: "day a$ d tusiv, iwakken a naâbed Öebbi Yiwen, a neoo ayen llan âabden imezwura nne$? Awi ya$ d ayen is la $ tessagwadev, ma d tidep ay tessawalev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 71, 'Inna: "ni$ iwwet ikwen id ddell akked zzâaf s$uô Mass nnwen. Day ad iyi namren $ef ismawen i tefkam, kunwi akked imezwura nnwen, i wid iwumi ur d Issers Öebbi kra udabu. Ihi, gganit, nek yidwen seg wid ara igganin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 72, 'Nsellek it, akked wid illan yides, s uêunu s$uône£. Nessenger wid iskaddben issekniyen nne£, ur nelli d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 73, '£uô Tamud, gmat sen Üaliê. Inna: "a yagdud iw! Âabdet Öebbi! Ur tesâim ôebbi war Neppa. Ni$ iusa kwen id ubeggen s$uô Mass nnwen. Tal$wemt agi n Öebbi, d assekni i kunwi. Ooet ep a ppeçç di tmurt n Öebbi. Ur p îîuôôut, mulac a kwen iêaz uâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 74, 'Mmektit ed mi kwen Irra d igensas, deffir Âad. Isseqâad ikwen di tmurt, tepparram lebôuj di swaêel, teqqazem ixxamen deg durar. Ihi, mmektit ed lxiô n Öebbi, ur ssexsaôet tamurt, s usefsed".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 75, 'Imvebbôen seg ugdud is, wid isme$awôen iman nnsen, nnan i wuôhifen, wid segsen iumnen: "day teéôam ar ÛüÜaliê d amazan s$uô Mass is"? Nnan: "ih, numen s wayen is id ippuceggaâ".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 76, 'Nnan imzuxiyen: "nekwni, s tidep, nenkeô ayen is tumnem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 77, 'Ëerrfen avaô n tel$wemt, gelzen lameô n Mass nnsen. Nnan: "a Üaliê, awi ya$ d ayen is la $ tessagwadev, ma d amazan ay telliv".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 78, 'Tewwet iten zzenzla, gwran d, deg ixxamen nnsen, d loeppat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 79, 'Iwexxeô asen, u inna: "a yagdud iw! Ni$ ssawve$ awen d tabôap n Mass iw, neûêe$ kwen, maca ur têemmlem ara win ineûêen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 80, 'I Luî, mi inna i ugdud is: "day a txeddmem lâaô ur ixdim yiwen, uqbel nnwen, deg imavalen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 81, 'Ih, kunwi tpeddum ar irgazen, tcehwam ten, war tilawin. Kunwi, ih, d agdud izegren tilas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 82, 'Tiririt n ugdud is siwa nnan: "ssuff$et pen si temdint nnwen, nitni d imdanen issaramen tezdeg".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 83, 'Nsellek it, neppa akked twacult is, siwa tameîîut is, teqqim akked wid igwran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 84, 'Nesse$li d fellasen ageffur…Wali amek tevôa d ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 85, '£uô Madian, gmat sen Cuâayeb. Inna: "a yagdud iw! Âabdet Öebbi! Ur tesâim ôebbi war Neppa. Ni$ iusa kwen id ubeggen s$uô Mass nnwen. Ktilet, weznet, s lewqama. Ur îîuôôut medden di cci nnsen, ur ssefsadet di tmurt, deffir useêôet is. I kunwi yif it wayagi, ma d lmumnin ay tellam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 86, 'Ur p$imit di yal abrid, tessagwadem u tessefôa$em seg ubrid n Öebbi, wid iumnen yiS. Teb$am t d uâwij. Mmektit ed mi tellam d takwemmict, Iketteô ikwen. Walit amek tevôa taggara ifessaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 87, 'Ma illa iumen urbaâ segwen s wayen is id ppuceggâa$, arbaâ nniven ur iumin ara. Üebôet ard Iêudd Öebbi garane$. Neppa Yif akw imêaddan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 88, 'Nnan d imvebbôen imzuxiyen, n ugdud is,: "a k nessuffe$ a Cuâayeb, keçç, akked wid iumnen yidek, si temdint nne$, ne$ a d tu$alev ar ddin nne$". Inna: "xas nugi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 89, 'Ihi, nger ed tikerkas $ef Öebbi, ma nu$al ar ddin nnwen, mbaâd ma Isellek a$ Öebbi, segs. Ur a$ ilaq ara a nu$al $uôes, siwa ma Irad Öebbi, Mass nne$. Mass nne$ Issemêalleq i yal cci s tmusni. Nepkel $ef Öebbi". A Mass nne$! Fru p garane$ akked ugdud nne$, s tidep. Keçç Tifev akw wid iferrun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 90, 'Nnan imvebbôen, wid ijehlen, n ugdud is: "ma teddam d Cuâayeb, war ccekk a pxesôem."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 91, 'Tewwet iten zzenzla, gwran d, deg ixxamen nnsen, d loeppat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 92, 'Wid iskaddben Cuâayeb, u$alen amzun ur zdi$en. Wid iskaddben Cuâayeb, d nitni ay d imexûuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 93, 'Iwexxeô asen, u inna: "a yagdud iw! Ni$ ssawve$ awen d tibôatin n Mass iw, neûêe$ kwen. Amek ara $weble$ $ef ugdud ijehliyen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 94, 'Ur Nuzen ara nnbi ar temdint, mebla ma Newwet imezda$ is s cedda, akked lemveôôa, amar ad êiwten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 95, 'Sinna, Nerra ise$ deg umkan n tucmip, armi wexxôen, nnan: "ni$ jeôôben imezwura nne$ lemveôôa akked ttrika". Newwet iten deqzalla, nitni ur bnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 96, 'Lemmer kan uminen u êezzben imezda$ n temdinin, war ccekk, ad asen Nelli lbaôakat seg igenni akked tmurt. Maca, skaddben. Nessemêalleq asen, ilmend n wayen keppben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 97, 'Day $ilen imezda$ n temdinin, ur ten id teppawev tiyta nne£, deg yiv, nitni îîsen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 98, 'Ne$ day $ilen imezda$ n temdinin, ur ten id teppawev tiyta nne£, deg wazal, nitni ppuraren?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 99, 'Day $ilen sellken i tandit n Öebbi? Siwa agdud i ixesôen, i i$ilen sellken i tandit n Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 100, 'Ne$ day ur d Iban ara, i wid ara iweôten tamurt, deffir imezda$ is, ar, ma ihwa ya£, a ten Newwet $ef ibekkaven nnsen, a Nesle$ ulawen nnsen, d$a nitni ur sellen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 101, 'D timdinin agi, i$ef ak Nêekku, si teqûivin nnsent. Ni$ usan $uôsent imazanen nnsent, s ubeggen. Ur llint d tid ara iamnen deg wayen skaddbent uqbel. Akka i Iselle$ Öebbi ulawen ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 102, 'Ur Nufi nnesba ar tegwti nnsen. Nufa, tegwti nnsen, d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 103, 'Sinna, deffir sen, Nuzen ed Musa, s issekniyen nne£, ar Ferâun akked imvebbôen is. Densen ten. Wali amek tevôa d ifessaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 104, 'Inna Musa: "a Ferâun! Nek d amazan s$uô Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 105, 'D ûûeê, ur qqaôe$, $ef Öebbi, siwa tidep. Ih, usi$ kwen id, s ubeggen n Mass nnwen. Ihi, azen yidi At Isôail".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 106, 'Inna: "ma tusiv d s ussekni, zzi t id, ma tessawalav tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 107, 'Iveggeô taâkwazt is, appan d azrem n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 108, 'Issuffe$ ed afus is, iban ed d amellal i imnezhen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 109, 'Nnan d imvebbôen n ugdud n Ferâun: "wagi, s tidep, d aseêêar amusnaw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 110, '"Ib$a a kwen issuffe$ si tmurt nnwen, d acu t lameô nnwen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 111, 'Nnan: "anef as, neppa akked gma s. Azen iberraêen ar temdinin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 112, 'ad ak d awin yal aseêêar amusnaw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 113, 'Usan d iseêêaren n Ferâun, nnan: "s tidep, ad a$ tkafiv, ma d nekwni ara i$elben"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 114, 'Inna: "ih, u, s tidep, a ppilim d iqôiben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 115, 'Nnan: "a Musa! A pveggôev keçç, ne$ a nveggeô nekwni"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 116, 'Inna: "veggôet"! Mi veggôen, sdehcen allen n l$aci, ssagwden ten. Bbwin d ssêur anect ilat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 117, 'Nweêêa i Musa: "veggeô taâkwazt ik"! Apan tesseblaâ ayen d ûenâan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 118, 'Tûaô tidep, inqev wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 119, 'Akka ay pwa$elben. U$alen ar deffir, d unqisen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 120, '£lin iseêêaren, knan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 121, 'Nnan: "numen s Mass imavalen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 122, 'Mass n Musa akked Haôun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 123, 'Inna Ferâun: "day tumnem yis, uqbel ma âammde$ awen? Ayagi, war ccekk, d tifxep. Tundim p di temdint, iwakken a ppessuff$em, segs, imezda$ is. Ihi, deqqal a ppeéôem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 124, 'War ccekk, ad awen gezme$ afus ssya, avaô ssya. Sinna, ih, a kwen semmôe$ akw $ef imudag".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 125, 'Nnan: "nekwni a nu$al ar Mass nne$.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 126, 'Terriv d ppaô segne$, imi kan numen s issekniyen n Mass nne$, mi $ d usan. A Mass nne$! Azen a$ d ûûbeô, Ddem leôwaê nne$ d imvuâen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 127, 'Imvebbôen n ugdud n Ferâun, nnan: "day a ppeooev Musa akked ugdud is, ad ssefsaden di tmurt, a kwen ooen, keçç akked iôebbiten ik"? Inna: "a nene$ arrac nnsen, a nessider tilawin nnsen. Nekwni, sennig sen, d iqehhaôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 128, 'Inna Musa i ugdud is: "ppret afus n Öebbi, u ûebôet. Tamurt, war ccekk, n Öebbi. A p iwôet win i S ihwan, deg imdanen iS. Taggara i wid ipêezziben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 129, 'Nnan: "njaf uqbel a $ d tasev, u deffir tisin ik". Inna: "amar Mass nnwen ad Ine$ acengu nnwen, a kwen Irr d igensas di tmurt, ad Iwali amek ara txedmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 130, 'Newwet, d$a, lois n Ferâun s iseggwasen n llaé, akked nneqs n ppemôa, amar a d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 131, 'Ma iusa ten id ise$, ad inin: "nne$ wagi". Ma tusa ten id tucmip, a p sbibben i Musa akked wid illan yides. Ayen iveôôun yidsen, day maççi ar Öebbi kan? Maca, tegwti segsen ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 132, 'Nnan: " wicqa assekni ara d tawiv, ur a$ tepseêêirev yis. Nekwni, ur neppamen yisek".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 133, 'Nuzen asen aêemmal, ajôad, tilkin, imqweôqwôen, idammen, d issekniyen ifeûlen. Sme$wôen iman nnsen. Llan d agdud ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 134, 'Mi tevôa yidsen twa$it, qqaôen: "a Musa! Nâaô Mass ik i nekwni, s wayen i k Iâahed. Ma tekksev a$ tawa$it, a namen yisek, a nazen yidek At Isôail".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 135, 'Mi sen Nekkes tawa$it, ar lajel iten iggunin, atnan nitni xedâan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 136, 'Nerra d segsen ppaô, N$emq iten deg ill, imi skaddben issekniyen nne£, ur d celâen degsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 137, 'Nessewôet i ugdud i illan qehôen t, igmav akked ituram n tmurt, i Neôqa. Itam wawal ûûam n Mass ik, $ef At Isôail, ilmend n wayen ûebôen. Nhudd ayen iûennaâ Ferâun akked ugdud is, u wayen bennun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 138, 'Nesâadda ill i At Isôail. Mmugren d agdud i iâabden tiâancuôin is. Nnan: "a Musa! Err ane$ ôebbi am iôebbiten nnsen". Inna: "kunwi, s tidep, d agdud ur nessin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 139, 'Wigi, s tidep, ad inger wayen ideg llan, ad inqev wayen xeddmen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 140, 'Inna: "day awen budde$ ôebbi, war Öebbi, u Neppa Ismenyaf ikwen $ef imavalen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 141, 'Mi kwen Nsellek si lois n Ferâun, sukken fellawen aâaqeb uqsiê mavi; neqqen arrac nnwen, ssidiren tilawin nnwen. Deg waya, ajeôôeb s$uô Mass nnwen ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 142, 'Nemlal akked Musa kravet wavan, Nerna yasen mraw. Tebbwev tallit n Mass is, kuzet wavan. Inna Musa i gma s Haôun: "enûef iyi ar ugdud iw, exdem ayen ilhan, ur teddu d ubrid ifessaden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 143, 'Mi d iusa Musa ar temlilit nne£, u Immeslay as Mass is, inna: "a Mass iw! Ssenâat iyi d, a K wali$". Inna d: "ur iyI tepwaliv, d awez$i, maca muqel s adrar. Ma iqqim deg umekkan is, ad iyI twaliv". Mi d Iusa Mass is s adrar, Irra t d saêel. I$li Musa, ixsef. Mi d iuki, inna: "gedha s yiseK! Utube$ K, nek d amezwaru n lmumnin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 144, 'Inna: "a Musa! Aql I Smenyafe$ k $ef imdanen, i tebôatin iW, i wawal iW. Ddem ayen i k d Fki$, ili seg wid isnemmiren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 145, 'Nura yas, di tlewêin, si yal cci, anabi akked ufeûûel n yal cci. Ddem itent s tezmert, ameô i ugdud ik a tent iîîef s lmaâna nnsent. Ad awen Ssekne$ tanezdu$t iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 146, 'Ad Veôôfe$, seg issekniyen iW, wid isme$wôen iman nnsen di tmurt, war ssebba. Mi walan yal assekni, ur ppamnen yis. Ma walan abrid uûwib, ur teddun degs. Ma walan abrid n le$wlav, a t awin. Ayagi, acku, s tidep, skaddben issekniyen nne£, ur d celâen degsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 147, 'Wid iskaddben issekniyen nne£, akked temlilit n laxeôt, ur swin igiten nnsen. Day a ten kafin $ef wayen ur nelli d ayen xeddmen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 148, 'Agdud n Musa, deffir es, isbedd, s ôôêuê is, aâjmi bu loeppa isrugmuten. Day ur walan ara ar, s tidep, ur asen d ipmeslay, ur la ten inehhu s abrid? Âabden t, llan d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 149, 'Mi ppuêeccmen, u walan ar, zi$ nnetlafen, nnan: "ma ur Iêun ara fella$ Mass nne$, ma ur a$ Isemmeê ara, war ccekk, a nu$al seg imexsuôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 150, 'Mi d iu$al Musa ar ugdud is, s wurrif akked lêemûa, inna: "ay d ucmit wayen is iyi tneûfem, deffir iw! Teb$am a d i$iwwel lameô n Mass nnwen"? Iveggeô tilewêin, iîîef gma s seg uqeôôu, ijebt it id $uôes. Inna d: "a mmi s n yimma, s tidep, iêqeô iyi ugdud, qôib iyi n$an. Ur ssefôaê icenga yissi. Ur iyi pparra seg ugdud imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 151, 'Inna: "a Mass iw! Semmeê ane$, nek akked gma, Ssekcem a$ ar uêunu K. Keçç, Tifev akw wid ipêunun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 152, 'Ih, wid iâabden aâajmi, a d i$li fellasen wurrif n Mass nnsen, ad ndellen di tmeddurt n ddunit. Akka ay Nepqeîîi wid id isnulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 153, 'Wid ixedmen tucmitin, sinna, steôoâen deffir sent, u umnen, Mass ik, s tidep, deffir sent, ar Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 154, 'Mi irs wurrif is, iddem ed Musa tilewêin. Di tira nnsent, nnhaya akked uêunu i wid ippagwaden Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 155, 'Ifren ed Musa ûatet irgazen seg ugdud is, ad mlilen yidne£. Mi ten tewwet zzenzla, inna: "a Mass iw! Lemmer i K ihwi, yili, iu$ lêal, Ten$iv ten, u Tegliv yissi. Day ad a$ Temêuv, ilmend n wayen xedmen ije$lufen segne$? Wagi d ahewwel iK kan, Tettellifev syis win i K ihwan, Tnehhuv win i K ihwan. Keçç d Bab nne$, Semmeê a$, Ëun fella$, Keçç Tifev akw wid ipsemmiêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 156, 'Aru ya$ ise$ di ddunit, di laxeôt; aql a$ nu$al ed $uôeK". Inna d: "aâaqeb iW, a t Sâaddi$ $ef win iyI ihwan. Aêunu W ijemmel yal cci. A t Aru$ i wid ipêezziben, ipzekkin, akked wid iumnen s issekniyen nne£,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 157, 'wid iteddun d Umazan, Nnbi ur ne$ôi, i ufan iura $uôsen di Tuôa akked Linoil". Iumeô asen d lqanun, Itekkes asen ayen n dir. Iêell asen lâali, igdel asen dduni. Ikkes asen aruz akked lqid nnsen. Ihi, wid iumnen yis, i t iâawnen, i t isellken, iddan d tafat id irsen yides, widak d imerbaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 158, 'Ini: "a yimdanen! Nek d Amazan n Öebbi $uôwen meôôa. Neppa, ineS tagelda n tmurt akked igenwan. Ur illi ôebbi siwa Neppa. Issidir, Ineqq". Ihi, amnet s Öebbi akked Umazan iS, Nnbi ur ne$ôi, i iumnen s Öebbi akked wawal iS. Ddut yides, amar a ppepwanhum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 159, 'Deg ugdud n Musa, arbaâ iteddu s tidep. U syis ay pêuddun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 160, 'Nessemfaôaq iten $ef mrawsin laâôac, n leoyus. Mi s issuter ugdud is tissit, Nweêêa i Musa: ewwet aéôu s tâakwaz ik. F$ent ed segs mrawsnat tliwa; akka, yal amdan iéôa anda ara issew. Nesbur iten s usigna, Nessers asen d lmenna akked ifeôôuoen: "eççet seg wayen ilhan, is ikwen N$at". Ur a£ dnisen, maca la ddennisen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 161, 'Mi pwanecden: "zed$et di temdint agi, eççet segs, ayen i wen ihwan, init: "laâfu"! Âaddit di tebburt, s lekni. Ad awen Nsemmeê tuccva nnwen. A Nernu i lâuûam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 162, 'Wid idensen segsen, neûfen awalen s wid ur nelli d wid i sen nnan. Nuzen asen tiyta seg igenni, ilmend n wayen ddennisen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 163, 'Steqsi ten $ef temdint i illan $ef rrif n yill, mi ur d rzin di ssebt, mi ten id usan iselman nnsen, walan ten, ass n ssebt. Ass, war ssebt, ur ten id ppasen. Akka ay ten Njeôôeb, deg wayen ssexsaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 164, 'Mi d inna lois, segsen: "iwumi la tepnabim agdud ara Isqucc Öebbi, ne$ ara Iâaqeb s leqseê"? Nnan: "d aste$feô ar Mass nnwen, amar ad êezzben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 165, 'Mi ppun ayen i$ef pwafekkôen, Nsellek wid itekksen ayen n dir, Nesâadda aâaqeb adiran $ef imednas, ilmend n wayen ssexsaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 166, 'Mi sme$wôen iman nnsen $ef wayen i sen ipwakksen, Nenna yasen: "ilit d uddawen ucmiten"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 167, 'Mi Ixebbeô Mass ik, ard asen d Iazen ara ten iâaqben, s ééuô, alamma d ass n tnekra. Mass ik, s tidep, Ip$awal ar uâaqeb. Neppa, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 168, 'Nessemfaôaq iten di tmurt, d leoyus, garasen wid imaânen, garasen wid ur nemâin. Njeôôeb iten s ise$iyen akked tucmitin, amar a d u$alen s abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 169, 'Neûfen ten, deffir sen, ineûûafen i iweôten Tazmamt. Ppaddamen lerbaê n ddunit, qqaôen: "ad a$ semmêen". Ma rnan usan ten id lerbaê, am widen, a ten ddmen. Day ur âahden ara s Tezmamt, ard tidep kan, ara inin $ef Öebbi? U lemden i illan degs. Ppif axxam aneggaru, i wid ipêezziben. Day ur tfehmem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 170, 'Wid iîîfen di Tezmamt, ipéallan, s tidep, ur Nveggiâ arraz n lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 171, 'Mi Nessuli adrar sennig sen, amzun d tili, $ilen, s tidep, ara d i$li fellasen. Ïîfet nezzeh ayen i wen Nefka, smektit ed ayen illan degs, amar a pêezzbem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 172, 'Mi d Iddem Mass ik, si tgeééal n tarwa n Adem, dderya nnsen, Inna yasen a d cehhden $ef yiman nnsen: "day ur Lli$ ara d Mass nnwen"? Nnan: "ih, ncehhed". Akka ur d teqqaôem ara, ass n tnekra: "s tidep, ayagi d ayen ur neéôi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 173, 'Ne$ a d tinim: "d imezwura nne$ kan i icurken, zik. Nekwni d tarwa deffir sen. Day a$ Ten$ev, ilmend n wayen xedmen wid iôejjnen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 174, 'Akka ay Nfeûûel issekniyen, amar a d u$alen s abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 175, 'Eêku yasen d tadyant n win iwumi Nefka issekniyen nne£. Irra ten akin. Idda yides Cciîan, iu$al seg wid i$eôqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 176, 'Lemmer i £ ihwi, Nessuli t yissen. Maca, ib$a tamurt, idda d lhawiyya s. Ihi, amedya s am win n waydi, ma teddiv p fellas, ad ilehhet, ma teooiv t, ad ilehhet. D wagi ay d amedya n ugdud i iskaddben issekniyen nne£. Eêku d tadyant, amar a d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 177, 'Agdud iskaddben issekniyen nne£, d yir amedya. Pddennisen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 178, 'Win Inha Öebbi, ihi, idda d ubrid. Wid Itlef Öebbi, nitni d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 179, 'Ni$ Neswejd ed, i Loahennama, aîas n leonun akked yimdanen. Sâan ulawen, ur fehhmen yissen; sâan allen, ur pwalin yissent; sâan imeééu$en, ur sellen yissen. Nitni am lmal, ne$ nnetlafen kteô. Wigi d i$wefliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 180, 'I Öebbi, ismawen ûûam. Naâôet eP, yissen. Veôôfet seg wid issexsaôen ismawen iS. Ad ppuqeîîin $ef wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 181, 'Deg wayen Nexleq, yiwen n lois ivfeô tidep. Ipêuddu syis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 182, 'Wid iskaddben issekniyen nne£, a ten Nawi, cwiî, cwiî, ar wanda ur éôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 183, 'Ad asen Fke$ lmudda. Ih, ticeôkep iW d tunûiêt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 184, 'Day ur d tepmeyyizem ara? Ur illi umeddakwel nnwen d aôehbani. Neppa, d aneddaô kan ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 185, 'Day ur walan ara tagelda n tmurt, igenwan, akked wayen Ixleq Öebbi n cci? Ni$, ahat, iqeôb ed lajel nnsen. Anwa awal, deffir wagi, ar amnen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 186, 'Win Itlef Öebbi, ur Isâi nnahi. A ten Ioo ad hemlen di tjehli nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 187, 'A k steqsayen $ef yimir, melmi ara d yili. Ini: "i t Iéôan siwa Mass iw. D Neppa kan a t id Isseknen, di lweqt is. Ad iaéay di tmurt akked igenwan. Ur kwen id ippawev siwa deqzalla". A k steqsayen amzun tesâiv asali fellas. Ini: "i t Issnen siwa ÔÖebbi", maca tegwti n yimdanen ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 188, 'Ini: "ur ksibe$ i iman iw, aba$uô ne$ vveôô, kkes ed ayen Irad Öebbi. Lemmer ssine$ tabavnit, ad ôwu$ lxiô, ur iyi ipnal ixmiô. Nek d aneddaô kan, u d abcir, i ugdud iumnen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 189, 'D Neppa ikwen id Ixelqen si yiwen n yiman. Iddem ed segs tameîîut is, ad izde$ yides. Mi insa yides, tebbwi tadist tafessast; telêa yis. Mi d teûbeê ééayet, naâôen Öebbi: "a Mass nne$! Ma Tefkiv a$ d aâeôvi, war ccekk, a nili seg wid isnemmiren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 190, 'Mi sen d Ifka aâeôdi, rran aS icriken s wayen i sen d Ifka. I aâlay Öebbi, sennig wayen pcaraken!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 191, 'Day ad carken ayen ur nexliq acemma, u d nitni i ipwaxelqen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 192, 'Ur zmiren a ten âiwnen, ne$ ad âiwnen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 193, 'Ma tnecdem ten ar nnhaya, ur teddun yidwen. Iâuva fellawen ma tnecdem ten, ne$ ma tessusmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 194, 'S tidep, wigi tnaâôem, war Öebbi, d imdanen am kunwi. Naâret pen, ma ad awen d rren, maday tessawalem tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 195, 'Day sâan ivaôen, ad lêun fellasen, ne$ sâan ifassen, ad ddmen yissen, ne$ sâan allen, ad walin yisent, ne$ sâan imeééu$en, ad slen yissen. Ini: "naâret icriken nnwen, sinna, andit iyi. Ur iyi sganayet".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 196, 'Ih, Bab iw d Öebbi id Issersen Tazmamt, i Iêemmlen lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 197, 'Wid tnaâôem, war Neppa, ur zmiren a kwen âawnen, ne$ ad âawnen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 198, 'Ma tnecdem ten ar nnhaya, ur sellen. A ten twaliv a k id pmuqulen, nitni ur pwalin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 199, 'Ddem ayen ilhan, ameô ar lewqama, veôôef i wid ur nessin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 200, 'Ma ilaâj ik Cciîan ar dduni, ppkel $ef Öebbi. Neppa, s tidep, Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 201, 'Ih, wid ipêezziben, ma innul iten urbaâ n ccwaîen, a d mmektin, d$a ad asen llint wallen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 202, 'Zgan $elîen atmaten nnsen, d$a nitni ur xevvun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 203, 'Ma ur asen d tebbwiv ara assekni, ad ak inin: "acimi ur t id isnulfa ara"? Ini: "teddu$ kan d wayen iyi d ippuweêêan, s$uô Mass iw". Wagi, s$uô Mass nnwen, d tafat, d nnhaya, d aêunu, i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 204, 'Ma qqaôen Leqwôan ssemêesset as, ssusmet, amar fellawen aêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 205, 'Mmekti d Mass ik, deg iman ik, s wannuz akked lxuf, s wawal irsen, taûebêit, tameddit. Ur ppili seg i$wefliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 206, 'Ih, wid illan ar Mass ik, ur sme$wôen ara iman nnsen, $ef uâbad iS. Sbuccuâen T, i Neppa kennun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 1, 'Steqsan k $ef rrbeê. Ini: "rrbeê i Öebbi akked Umazan. Ihi, êezzbet i Öebbi, elhut garawen, a$et awal i Öebbi akked Umazan iS, ma d lmumnin ay tellam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 2, 'Lmumnin d wid kan iwumi ippergigi wul nnsen, ma Ipwabder ed Öebbi. Ma $ôan asen issekniyen iS, ad innerni liman nnsen. £ef Mass nnsen, ay ppeklen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 3, 'Wid ibedden i téallit, ipûeôôifen seg wayen is iten N$at.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 4, 'Wigi d ûûeê, d lmumnin. I nitni, ar Mass nnsen, tiseddaôin, ssmaê, akked l$it uùkyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 5, 'Akken ik id Issuffe$ Mass ik, seg uxxam ik, s tidep, wanag ur ib$i urbaâ si lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 6, 'La k pnamaren $ef tidep, deffir ubeggen is, amzun kan pwanehôen ar tmeppant, nitni pêekkiôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 7, 'Mi wen Iâahed Öebbi, ara ppili nnwen, yiwet si snat n trebbuyaâ, tessarmem a ppili nnwen tin ur nepwaselleê. Öebbi Ib$a a d itebbet tidep s wawalen iS, ad ôéen wakali ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 8, 'A ppili tidep, ad inqev lbaîel, xas ugin ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 9, 'Mi tepprem afus s$uô Mass nnwen, Ijaweb awen d: "Nek ad awen Fke$ agim lmalayek, mestebâant".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 10, 'Irra t kan Öebbi d abecceô iwakken ad nnevmanen yis wulawen nnwen. Ur illi l$elb, siwa s$uô Öebbi. Öebbi, s tidep, d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 11, 'Mi kwen I$umm s yives, d îîmana s$uôeS; Isse$li d fellawen aman seg igenni; a kwen Izzizdeg yissen, ad Issebâad, fellawen, a$way n Cciîan, ad Isseohed ulawen nnwen, ad Itebbet, yissen, isurifen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 12, 'Mi Iweêêa Mass ik i lmalayek: "Nek yidkwent; tebbtemt wid iumnen. Ad Skecme$ tugdi deg ulawen n wid ijehlen. Ewwtemt sennig tmegrav, ewwtemt ar ixfawen ivudan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 13, 'Ayagi, acku nitni, s tidep, xuûmen Öebbi akked Umazan iS. I win ixuûmen Öebbi akked Umazan iS, ihi, Öebbi Iwâaô deg uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 14, 'Wagi i kunwi, jeôôbet ep! U i ijehliyen, aâaqeb n tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 15, 'A wid iumnen! Ma temmugrem d wid ijehlen la d éeddmen, ur sen reggwlet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 16, 'Win i sen irewlen, assen, siwa ma la issewjad i umennu$, ne$ ma ikcem s arbaâ, winna, a t immager wurrif n Öebbi; axxam is d Loahennama, a yir tu$alin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 17, 'Ur ten tennu$em, maca d Öebbi iten Innu$en. Ur teôoimev mi tôeomev, maca Öebbi Iôoem, iwakken ad Ijeôôeb lmumnin s ujeôôeb umâin s$uôeS. Öebbi, s tidep, Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 18, 'Akka, Ih, Öebbi Issadar ticeôkep ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 19, 'Tessutrem l$elb, atan iusa kwen id. Ma tfukkem, ppif i kunwi. Ma tu$alem, a Nu$al. Ula iwumi tent, bippa, trebbuyaâ nnwen, xas îîuqtent. Ih, Öebbi Idda d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 20, 'A wid iumnen! A$et awal i Öebbi akked Umazan iS. Ur T ppaooat, u kunwi tsellem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 21, 'Ur ppilit am wid innan: "nesla", nitni ur sellen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 22, '£eô Öebbi, s tidep, ineggura imexlaq d iâeééugen, d igugam, ur nfehhem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 23, 'Lemmer Iéôi Öebbi degsen lxiô, yili Irra ten sellen. Ma Irra ten sellen, war ccekk, ad akwren avaô, u nitni aâûan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 24, 'A wid iumnen! Jawbet i Öebbi akked Umazan, ma Inced ikwen ar wayen ikwen issidiren. Cfut ar Öebbi Ippili ger umdan akked wul is. £uôeS, Neppa, s tidep, ara tepwafessrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 25, 'Ëezzbet i uhewwel. Ur ipêaz ara kan imednas segwen, weêêedsen. Cfut ar Öebbi Iqseê deg uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 26, 'Mmektit ed mi, kunwi, drus ay tellam, d uôhifen di tmurt, teppagwadem a kwen xevfen medden. Iûûeô ikwen, Isellek ikwen s l$elb iS, I$at ikwen s wayen ilhan, amender ma a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 27, 'A wid iumnen! Ur pxeyyinet Öebbi akked Umazan, ur pxeyyinet lamanat nnwen, kunwi teéôam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 28, 'Cfut ar, ayla nnwen akked tarwa nnwen, d ahewwel kan, u ar £uô Öebbi, ôôaîeb ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 29, 'A wid iumnen! Ma têezzbem i Öebbi, ad awen Ifk afraz, ad awen Imêu tucmitin nnwen, ad awen Isemmeê. Öebbi d Bab n lfevl ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 30, 'Ma ppandin ak, wid ijehlen, iwakken a k êebsen, ne$ a k n$en, ne$ a k ssuff$en; ppandin u Öebbi Ippandi. Öebbi Yif akw imendayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 31, 'Ma $ôan asen issekniyen nne£, ad inin: "ih, nesla. Ma ihwa ya$ a d nini am ayagi. Ayagi, s tidep, siwa d timucuha imezwura".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 32, 'Mi nnan: "a Öebbi, ma illa wagi d tidep s$uôeK, Sse$li d, fella$, id$a$en seg igenni, ne$ Awi a$ d aâaqeb aqeôêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 33, 'Ur illi Öebbi d win ara ten Iâaqben, skud telliv garasen. Ur Illi Öebbi d win ara Ipâaqben ma nitni la suturen ssmaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 34, 'Acimi ur ten Ipâaqab ara Öebbi, u nitni swexxiôen si Loamaâ n Lêaôam, ur llin d imawlan is. Imawlan is, d wid kan ipêezziben. Maca, tegwti segsen ur éôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 35, 'Taéallit nnsen deg Uxxam, siwa aseffeô akked llir. Jeôôbet aâaqeb, $ef wayen tjehhlem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 36, 'Ih, wid ijehlen pûeôôifen ayla nnsen, iwakken ad veôôfen seg ubrid n Öebbi. A t ûeôôfen, ad asen iu$al d lexsaôa. Sinna, ad ppu$elben. Wid ijehlen ad pwafessren di Loahennama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 37, 'Iwakken ad Ifrez Öebbi dduni d lâali, ad Irr ixabiten, wa $ef wa, a ten Izdi akw, a ten Irr ar Loahennama. Widak d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 38, 'Ini i wid ijehlen: "ma fukken, ad awen Isemmeê ayen iâaddan; ma u$alen, ihi, akken tevôa d imezwura".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 39, 'Nna$et pen alamma tfukk lfetna, u iu$al ddin s lekmal is, i Öebbi. Ma êebsen, Öebbi, s tidep, Ipwali ay xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 40, 'Ma wexxôen, cfut ar Öebbi d Bab nnwen, Bab amxalef, Asellak amxalef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 41, 'Akken ib$u yili wayen id t$eltem n cci, cfut amur wis smus n Öebbi akked Umazan iS, akked llzem, igujilen, ime$ban, win d ibbwi ubrid; ma illa tumnem s Öebbi akked wayen id Nessers i umdan nne£, ass n ufraz, ass ideg mlalent snat n trebbuyaâ. Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 42, 'Mi tellam di loiha taqôibt, u nitni agwemmav, imnayen seddawat wen, xas temyefkem ppaâud, tzeglem timlilit. Maca, iwakken ad Isâaddi Öebbi lameô ara iâaddin, ad immet win immuten, s ubeggen, ad yidir win idren, s ubeggen. Öebbi, s tidep, Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 43, 'Mi k ten id Issenâat Öebbi, d takwemmict, di targit ik ... Lemmer ik ten id Issenâat qwan, war ccekk, a pfeclem, a ppemnamarem $ef lameô. Maca, Öebbi Ijbeô ikwen. Ih, Neppa Issen i illan deg idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 44, 'Mi wen ten Issenâat, mi ten temmugrem, twalam ten d takwemmict. Iééeméi kwen ar tmu$li nnsen, iwakken ad Isâaddi Öebbi lameô ara iâaddin. Ar Öebbi ppu$alen lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 45, 'A wid iumnen! Ma temmugrem d arbaâ, tebbtet, mmektit ed aîas Öebbi, amar a prebêem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 46, 'A$et awal i Öebbi akked Umazan iS, ur ppemnamaret. Mulac a pfeclem, a pnegfem. Üebôet! S tidep, Öebbi ar iûebôiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 47, 'Ur ppilit am wid id iff$en s tem$weô, seg ixxamen nnsen, iwakken a ten id walin medden. Swexxiôen seg ubrid n Öebbi. Öebbi Izzi i wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 48, 'Mi sen icebbeê Cciîan igiten nnsen, u inna: "ur kwen i$elleb yiwen seg imdanen, ass agi. Nek d amalal nnwen". Mi mwalant snat trebbuyaâ, iuker avaô, inna: "nek xvi$ kwen, nek wala$ ayen ur twalam, nek ugade$ Öebbi. Öebbi Iqseê deg uâaqeb".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 49, 'Mi nnan ixabiten akked imehzulen n wul: "wigi, i$uôô iten ddin nnsen". Win ippeklen $ef Öebbi, ihi, Öebbi d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 50, 'Lemmer a pwaliv mara ddment lmalayek leôwaê n wid ijehlen, ad kkatent udmawen nnsen, izugar nnsen. "Jeôôbet aâaqeb n tmeô$iwt!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 51, 'Ayagi ilmend n wayen d bbwin ifassen nnwen", u Öebbi ur pdennis imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 52, 'Am tikli n ugdud n Ferâun akked wid i ten id izwaren. Nekôen issekniyen n Öebbi. Issemêaleq asen Öebbi s ibekkaven nnsen. Ih, Öebbi d Uzmir, Iqseê deg uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 53, 'Akka, acku Öebbi ur Ipbeddil l$it is I$at agdud, alamma bedlen i illan deg iman nnsen. Öebbi Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 54, 'Am tikli n ugdud n Ferâun akked wid i ten id izwaren. Skaddben issekniyen n Mass nnsen. Nen$a ten s ibekkaven nnsen, Ne$meq agdud n Ferâun; llan akw d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 55, '£uô Öebbi, imexlaq ucmiten mavi, d wid ijehlen, d$a ur uminen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 56, 'wid ukud tgiv lemâahda, sinna, di yal tikelt, neqven lemâahda nnsen, u nitni ur pêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 57, 'Ma tugarev ten di îôad, sserwel yissen wid i ten id ivefôen, amar a d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 58, 'Ma tugadev lexdaâ seg ugdud, err iten akin, s tezdeg. Öebbi, s tidep, ur Iêemmel ara ixeddaâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 59, 'Ur p$ilin menâan, wid ijehlen. Nitni, s tidep, ur zmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 60, 'Heggit asen d ayen iwumi tzemrem n lemêella akked yimnayen, a ppessagwdem yissen acengu n Öebbi, acengu nnwen, akked wiyav, war segsen, ur tessinem; Öebbi Issen iten. Ayen tseddqem n cci, deg ubrid n Öebbi, ad awen d iu$al. Kunwi ur tepwadensem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 61, 'Ma nudan talwit, nadi ep. Ppkel $ef Öebbi. Neppa, s tidep, Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 62, 'Ma b$an a k xedâan, ihi, âammed $ef Öebbi, Neppa i k Ifkan afus s tallalt iS, akked lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 63, 'Issemlal ulawen nnsen. Lemmer a pûeôfev i illan akw di tmurt, ur tessemliliv ulawen nnsen. Maca, Öebbi Issemlal iten. Neppa, s tidep, d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 64, 'A Nnbi! Âammed $ef Öebbi, keçç, akked wid iddan yidek si lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 65, 'A Nnbi! Eg lêir i lmumnin, ad nna$en. Ma llan segwen warem iûebôiyen, ad rnun snat twinas. Ma llan segwen twinas, ad rnun agim n wid ijehlen, acku, nitni d agdud ur nfehhem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 66, 'Tura, Issafes Öebbi fellawen. Iéôa tella garawen rrehma. Ihi, ma llan segwen twinas iûebôiyen, ad rnun snat twinas, ma llan segwen agim, ad rnun sin igima, ma Irad Öebbi. Öebbi ar iûebôiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 67, 'Ur issefk ara i Nnbi ad isâu imeêbas, alamma pwa$elben di tmurt. Teb$am tukci n ddunit. Öebbi Ib$a laxeôt. Öebbi d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 68, 'Lemmer maççi d ayen iuran s$uô Öebbi, izwar ed, yili a kwen iwwet uâaqeb abarar, ilmend n wayen tebbwim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 69, 'Eççet ayen ilhan, iêellen, seg wayen i t$elltem, êezzbet i Öebbi. Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 70, 'A Nnbi! Ini i wid teîîfem seg imeêbas: "ma Iufa Öebbi lxiô deg ulawen nnwen, ad awen Ifk ayen yifen ayen i wen ipwakksen, ad awen Isemmeê. Öebbi Ipsemmiê, Ipêunu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 71, 'Ma b$an a k xedâan, ni$ iu$ lêal xedâen Öebbi. D$a, Ikkes asen ôôay. Öebbi Iéôa, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 72, 'Ih, wid iumnen, iunagen, ijuhden s wayla nnsen, akked yiman nnsen, deg ubrid n Öebbi, wid isnubgten u fkan afus, widak d imeddukwal bwaygarasen. Wid iumnen ur unagen, ur awen llin d imeddukwal, s wacemma, alamma unagen. Ma ppren afus nnwen di ddin, iwata yawen ad asen tefkem afus, siwa mgal agdud ukud tâaqdem. Öebbi Ipwali ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 73, 'Wid ijehlen d imeddukwal bwaygarasen. Ma ur tgim ara akka, a ppili lfetna di tmurt, akked usefsed ameqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 74, 'Wid iumnen, iunagen, ijuhden deg ubrid n Öebbi, wid isnubgten u fkan afus, widak, s tidep, d lmumnin. I nitni ssmaê akked l$it ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 75, 'Wid iumnen syin $er da, u unagen, u juhden yidwen, widak segwen. Llzem ppemyilin kteô di Tezmamt n Öebbi. Öebbi, s tidep, Izôa yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 1, 'Öebbi akked Umazan iS kksen aêeppem i imcurak ukud tâaqqdem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 2, 'Ddut di tmurt kué wagguren. Cfut ar kunwi ur tesfunnugem i Öebbi, u Öebbi ad Isdull ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 3, 'Aberreê i medden, s$uô Öebbi akked Umazan iS, ass n êioo ameqwôaêan, ar Öebbi akked Umazan iS, kksen aêeppem i imcurak. "Ma testeôoâam, ppif i kunwi, ma twexxôem, cfut ar kunwi ur tesfunnugem i Öebbi". Becceô wid ijehlen s uâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 4, 'Kkes ed wid ukud tâaqqdem seg imcurak, sinna ur kwen bbwiven s wacemma, ur ullen yiwen mgal nnwen. Ïîfet di lemâahda nnsen ar lmudda s. Öebbi, s tidep, Iêemmel wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 5, 'Mi âaddan wagguren iôqan, nna$et imcurak anda ten tufam. Ïîfet pen, êeôset pen, andit asen yal taxettalt. Ma steôoâan, ééulen, zekkan, ooet asen abrid. Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 6, 'Ma issuter ak laânaya, yiwen seg imcurak, êareb fellas, ard issel i wawal n Öebbi, sinna, ssiwev it s amkan is n laman. Akka, acku nitni, s tidep, d agdud ur nessin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 7, 'Amek ara tili i imcurak, lemâahda s$uô Öebbi u s$uô Umazan iS, siwa wid tâahdem ar Loamaâ n Lêaôam. Skud sweqmen yidwen, sweqmet yidsen. Öebbi, s tidep, Iêemmel wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 8, 'Amek, mi kwen $elben, ur kwen qudôen ilmend n yi$es, ne$ n lemâahda. Öuvan kwen s imawen nnsen; ulawen nnsen ugin. Tegwti segsen d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 9, 'U$en s issekniyen n Öebbi ayen ôxisen. Ssefôa$en $ef ubrid iS. S tidep, ay dir wayen xeddmen nitni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 10, 'Ur qudôen lmumen ilmend n yi$es, ne$ n lemâahda. Wigi, ih, d wid izegren tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 11, 'Ma steôoâan, ééulen, zekkan, d atmaten nnwen di ddin. Nepfeûûil issekniyen i ugdud issnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 12, 'Ma sêenten tagalit nnsen, deffir lemâahda nnsen, u wwten di ddin nnwen, nna$et iqweôôa n tijehli. Nitni, s tidep, ur ppaîafen di tgallit. Amar ad fukken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 13, 'Day ur tepna$em ara agdud i isêenten tagalit nnsen, u ib$an ad ssuff$en Amazan, u nitni heomen kwen d imezwura? Day ten tugadem? D Öebbi i iklalen a T tagwadem, ma d lmumnin ay tellam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 14, 'Nna$et pen, a ten Iâaqeb Öebbi s ufus nnwen, a ten Ixzu, a kwen Iserbeê fellasen, ad Icfu idmaren n ugdud n lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 15, 'Ad Ikkes urrif n wulawen nnsen. Öebbi Issuruf i win i S ihwan. Öebbi d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 16, 'Day t$ilem a ppepwaterkem, wanag ur Iéôi Öebbi wid, degwen, ijuhden, ur neddi d imawlan, war Öebbi akked Umazan iS, akked lmumnin? Öebbi Iéôa ay txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 17, 'Ur issefk ara i imcurak ad kecmen leowamaâ n Öebbi, ad cehhden $ef tijehli nnsen. Widak neqven igiten nnsen, di tmes ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 18, 'Ara ikecmen kan leowamaâ n Öebbi, d wid iumnen s Öebbi akked wass aneggaru, iééulen, izekkan, ippagwaden siwa Öebbi. Ahat wigi ad ilin seg wid ipwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 19, 'Day terram win i isswan iéaâlak, i ibedden i Loamaâ n Lêaôam, am win iumnen s Öebbi akked wass aneggaru u innu$ deg ubrid n Öebbi? Ur aâdilen ar Öebbi. Öebbi ur Inehhu agdud imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 20, 'Wid iumnen, iunagen, u nnu$en deg ubrid n Öebbi s wayla nnsen akked iman nnsen, aâlay umekkan nnsen, ar Öebbi. Wigi d wid ara irebêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 21, 'Ibecceô iten Mass nnsen s uêunu s$uôeS, akked llza, akked leonanat, degsen ssaâd imezgi;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 22, 'ad wekkôen degsen i lebda. Ih, ar Öebbi, arraz ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 23, 'A wid iumnen! Ur pparat d imawlan, ibabaten nnwen akked watmaten nnwen, ma smenyafen tijehli i liman. Wid segwen i ten iran d imawlan, ad ilin, nitni, d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 24, 'Ini: "maday, sennig Öebbi akked Umazan iS, akked umennu$ deg ubrid iS, ay têemmlem ibabaten nnwen, tarwa nnwen, atmaten nnwen, tilawin nnwen, alag nnwen, ayla i tkesbem, ttjaôa i tugadem a ppe$li, tinezdu$in i kwen iâaoben, ihi, gganit ar d Ias Öebbi, s lameô iS. Öebbi ur Inehhu agdud iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 25, 'Ni$ Isrebê ikwen Öebbi deg waîas imukan, akked wass n Ëunain, mi kwen taâoeb îîaqa nnwen. Ur awen d tebbwi acemma. Tamurt iwsâan, tu$al awen tediyeq. D$a tezzim d, trewlem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 26, 'Sinna, Issers ed Öebbi talwit iS $ef Umazan iS, akked lmumnin, Issers ed iâsekôiwen ur tepwalim. Iâaqeb wid ijehlen. D wagi ay d aqeîîi ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 27, 'Sinna, deffir waya, Öebbi Issuruf i win i S ihwan. Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 28, 'A wid iumnen! Imcurak maâfunit kan. Ur d pqeôôiben ar Loamaâ n Lêaôam, mara ifukk useggwas agi nnsen. Ma tugadem lqella, a kwen I$it Öebbi, s lfevl iS, ma ihwa yaS. Ih, Öebbi d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 29, 'Nna$et wid ur numin ara s Öebbi, u s wass aneggaru, ur pgeddilen ayen Igdel Öebbi akked Umazan iS, ur xeddmen ddin n tidep, seg wid iwumi teppunefk Tezmamt, alamma xelûen tabzert s war amunnu, d imejjîuêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 30, 'Nnan wudayen: "Âuzayeô d mmi S n Öebbi". Nnan imasiêiyen: "lmasiê d mmi S n Öebbi". Ayagi, nnan t id s imawen nnsen. Ppaâwaden d awal n wid ijehlen, n zik. A ten Ine$ Öebbi! Acêal îeôôifen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 31, 'Rran lquôôaê nnsen, ixelwiyen nnsen, lmasiê mmi s n Meryem, d imawlan war Öebbi. Pwamôen kan ad âabden Öebbi Yiwen; ur illi ôebbi siwa Neppa. Gedha syiS, seg wayen pcaraken!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 32, 'B$an s yimawen nnsen ad ssexsin tafat n Öebbi. I Ib$a Öebbi, ad Itim kan tafat iS, di nneqwma ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 33, 'D Neppa id Iuznen Amazan iS, s nnhaya akked ddin n tidep, iwakken a t Issifer $ef ddin meôôa, xas ugin ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 34, 'A wid iumnen! Aîas n lqweôôaê d ixelwiyen, s tidep, teppen d aêerfi ayla n medden. U îeôôifen seg ubrid n Öebbi. Wid ixeznen ddheb d lfeîîa, ur ten pseddiqen deg ubrid n Öebbi, becceô iten s uâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 35, 'Ass ideg ara ô$en di tmes n Loahennama, ad kwin, yissen, inyiren nnsen, ibeôdiyen nnsen, iârar nnsen. "D ayagi ay txezznem i iman nnwen. Jeôôbet ayen txezznem!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 36, 'Ih, ar Öebbi, amvan n wagguren: mrawsin; di Tezmamt n Öebbi, ass ideg Ixleq tamurt akked igenwan. Garasen, kué ôqan. D wagi ay d ddin n ddwam. Ur ddenniset iman nnwen degsen. Nna$et ijehliyen $ef ccfa, akken i kwen nnu$en $ef ccfa. Cfut, Öebbi Iteddu d wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 37, 'Aswexxeô n waggur d timerniwt kan n tijehli. Nnetlafen yis wid ijehlen. Aseggwas a t êellen, aseggwas a t gedlen, iwakken ad wafqen amvan n wayen Igdel Öebbi. Ad êellen ayen Igdel Öebbi. Âaoben ten yir igiten nnsen. Öebbi ur Inehhu agdud ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 38, 'A wid iumnen! Acu kwen iu$en? Ma nnan awen: "hejjmet ar ubrid n Öebbi", a ppebrum i iman nnwen. Day kwen taâoeb tmeddurt n ddunit, sennig tin n laxeôt? Zzhu n tmeddurt n ddunit d amejîiîuê kan, zdat win n laxeôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 39, 'Ma ur tehjjimem ara, a kwen Iâaqeb s lqeôê, a d Iawi agdud nniven, deg umekkan nnwen. Ur T teîîuôum s wacemma. Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 40, 'Ma ur t tsellkem, ihi, Isellek it Öebbi, mi t ssuff$en wid ijehlen. Wissin n sin, mi llan deg ifri, mi inna i umeddakwel is: "kkes a$wbel, Öebbi, s tidep, yidne$". Issers ed Öebbi talwit iS fellas, Iâawen it s iâsekriwen, ur ten twalam. Isse$li mavi awal n wid ijehlen. Awal n Öebbi, neppa, aâlay sennig akw. Öebbi d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 41, 'Hejjmet fessusit u ééayit, juhdet s wayla nnwen akked yiman nnwen, deg ubrid n Öebbi. Ppif wakka i kunwi, lemmer teéôim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 42, 'Lemmer d aba$uô isehlen, d inig wezzilen, yili vefôen k in. Maca, $wezzif fellasen umecwaô. Ad ggalen s Öebbi: "lemmer nezmir, yili neffe$ yidwen". Nn$an iman nnsen, Öebbi Iéôa ar nitni, war ccekk, d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 43, 'Ad ak Isemmeê Öebbi! Acimi i sen tserêev? Ard ak d iban anwi innan tidep, a ppissinev ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 44, 'Ur ak d ssutren ara tsriê, wid iumnen s Öebbi akked wass aneggaru, mi juhden s wayla nnsen akked yiman nnsen. Öebbi Issen wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 45, 'I k issutren tsriê, d wid ur numin s Öebbi akked wass aneggaru. Cukken wulawen nnsen, d$a, s ucukku nnsen, kukran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 46, 'Lemmer b$in tuff$a, yili heggan as d ayen ilaqen. Maca, Iugi Öebbi ad ppucegâan, Iurez iten. Nnan asen: "qqimet d wid iqqimen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 47, 'Lemmer ffi$en yidwen, ar awen rnun siwa ccwal. War ccekk, ad kecmen garawen, b$an ahewwel nnwen. Kra segwen ssemêasen asen. Öebbi Issen imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 48, 'Ni$ b$an, si zik, ahewwel. Sxeôben ak lumuô, armi d tusa tidep. Ivehô ed lameô n Öebbi, nitni ur b$in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 49, 'Garasen win id innan: "serreê iyi, ur iyi gar di lfetna"! Day ur $lin ara di lfetna? Loahennama, s tidep, a ppezzi i ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 50, 'Ma iusa k id yise$ ad $weblen. Ma tusa k id twa$it, ad inin: "ni$, iu$ lêal, neqva lameô nne$". Ad wexxôen, zzhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 51, 'Ini: "ur a$ ipêaz wacemma, siwa ayen i $ Iura Öebbi". Neppa d Bab nne$. £ef Öebbi ara ppeklen lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 52, 'Ini: "acu teggunim ad ivôu yidne$, siwa yiwen si sin ise$iyen? Nekwni negguni a kwen Iwwet Öebbi, s uâaqeb ara d iasen s$uôeS, ne$ seg ifassen nne$. Ihi gganit, nekwni a neggani yidwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 53, 'Ini: "seddqet, teb$am ne$ tugim, d ayen ur neppwaqbal segwen, d awez$i. Kunwi, s tidep, d agdud iballa$en".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 54, 'Ay sen ikksen a tepwaqbal ssadaqa nnsen, imi kan jehlen, s tidep, ar Öebbi akked Umazan iS, u s laâgez kan ay d ppasen ar tpéallit, s usmiglez kan ay pseddiqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 55, 'Ur k ippaâoab wayla nnsen, ne$ tarwa nnsen. Ib$a kan Öebbi a ten Iâaqeb yissen di tmeddurt n ddunit, ad iffe$ ôôuê nnsen, nitni d ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 56, 'Ad ggalen s Öebbi, ar nitni, war ccekk, segwen. Ur nitni segwen, maca d agdud iugaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 57, 'Lemmer ad afen ssôan, ne$ ifran, ne$ anda ara kecmen, ad ôuêen $uôes s tazla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 58, 'Garasen, wid ikkaten deg k, $ef ssadaqat. Ma ippunefk asen segsent, ad ôavin, ma ur asen ippunefk, ad neêwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 59, 'Lemmer nitni, s tidep, ôuvan ayen i sen Ifka Öebbi akked Umazan iS, u nnan d: "nesteqnaâ s Öebbi. Ad a$ d Ifk, si lfevl iS, Öebbi akked Umazan iS. Ih, d Öebbi i$ef neô$eb".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 60, 'Ssadaqat siwa i ime$ban, iéawaliyen, i wid ice$wlen degsent, i usemlili n wulawen, i userreê imeêbas, i imeîîulba, i ubrid n Öebbi, i win d ifka ubrid. D aêeppem s$uô Öebbi. Öebbi d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 61, 'Garasen, wid icettmen deg Umazan, qqaôen: "neppa d aêessas". Ini: "d aêessas n lxiô i kunwi. Iumen s Öebbi, iumen lmumnin. D aêunu i wid iumnen segwen". I wid icettmen deg Umazan n Öebbi, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 62, 'Ad awen ggalen s Öebbi, iwakken a kwen ôavin. Öebbi akked Umazan iS, Iklal kteô a T ôavin, lemmer llin d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 63, 'Day ur éôin ara ar, win ixuûmen Öebbi akked Umazan iS, i neppa times n Loahennama, ad iwekkeô degs? D wagi ay d ddell abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 64, 'Ixabiten ugaden ad asen d ters tsuôep, ad asen tessken i illan deg ulawen nnsen. Ini: "mmaâlket. Öebbi, s tidep, a d Issuffe$ ayen tugadem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 65, 'Ma testeqsav ten, a d inin, war ccekk: "la nheddeô kan, nepqessiô". Ini: "day la tettihim di Öebbi akked issekniyen iS, akked Umazan iS?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 66, 'Ur steôoiâat. Ni$ tu$alem ar tijehli, deffir liman nnwen". Ma Nsemmeê i urbaâ segwen, a Naâqeb arbaâ, imi nitni llan d ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 67, 'Ixabiten akked txabitin, wa ippameô i wa, ayen n dir, ppemyegdalen lewqama, pcuddun ifassen nnsen. Ppun Öebbi, Ippu ten. Ih, ixabiten d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 68, 'Iwaââed Öebbi, i ixabiten, txabitin, akked ijehliyen, times n Loahennama, degs ad wekkôen. Beôka ten. Ixza ten Öebbi. Fellasen aâaqeb imezgi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 69, 'am imezwura nnwen. Llan ifen kwen tazmert, $elben kwen ayla, tarwa. Zhan deg umur nnsen, tezham deg umur nnwen, akken zhan imezwura nnwen deg umur nnsen. Teccvem akken ccven nitni. Widak, mêan igiten nnsen di ddunit, di laxeôt. Widak d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 70, 'Day ur ten id iusa ara usali imezwura nnsen? Agdud n Nuê, Âad, Tamud, agdud n Ibôahim, At Median, tid ippin. Usan ten id imazanen nnsen, s ubeggen. Ur ten Idennis Öebbi, maca llan dennisen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 71, 'Lmumnin, argaz tameîîut, d imeddukal wa n wa. Ppamôen lewqama, pgeddilen ayen n dir. Péallan, pzekkin, ppa$en awal i Öebbi akked Umazan iS. Wigi, ad Iêun Öebbi fellasen. Ih, Öebbi d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 72, 'Iwaââed Öebbi i lmumnin, argaz tameîîut, leonanat, ddawat sen isaffen ppazzalen, ad wekkôen degsen; ixxamen igerzen di leonanat n Âaden, akked llza s$uô Öebbi - iten i$elben akw -. D wagi ay d rrbeê ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 73, 'A Nnbi! Jahed ijehliyen akked ixabiten. Iqsiê $uôsen. Axxam nnsen d Loahennama, d taggara tucmip!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 74, 'Ggulen s Öebbi ur d nnin, wanag nnan awal n tijehli. Jehlen deffir wannuz nnsen. Vemâen ayen iwumi ur wâan. Ur êzinen imi iten I$at, si lfevl iS, Öebbi akked Umazan iS. Ma steôoâen, yif it i nitni. Ma wexxôen, a ten Iâaqeb Öebbi s leqôeê, di ddunit, di laxeôt. Ur sâun, di tmurt, bab ne$ amâiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 75, 'Garasen, wid iâahden Öebbi: "ma Ifka ya$ d, si lfevl iS, a nseddeq, a nili si lâuûam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 76, 'Mi sen Ifka si lfevl iS, a t bexwlen, ad wexxôen, ad namren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 77, 'Issegwra yasen d tanaâuôt deg ulawen nnsen, ar ass ideg ara mlilen yideS, imi xed$an Öebbi deg wayen i S âahden, imi llan skiddiben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 78, 'Day ur éôin ara Öebbi Issen sser nnsen akked wayen qqaôen u, ar Öebbi Issen tibavniyin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 79, 'Wid ipqeôôiven di lmumnin i ib$an ad seddqen, u deg wid i iufan siwa tazmert nnsen, d$a ttihin fellasen; ad Ittihi Öebbi fellasen. Fellasen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 80, 'Ssuter ad ppusemmêen, ne$ qqim. Ma tessutrev ûavet iberdan, ur sen Ipsemmiê Öebbi, d awez$i. Akka, imi nitni jehlen ar Öebbi akked Umazan iS. Öebbi ur Inehhu agdud iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 81, 'Wid igwran, feôêen mi llan deffir Umazan n Öebbi. Ugin ad nna$en s wayla nnsen akked teôwiêt nnsen, deg ubrid n Öebbi. Nnan: "Ur pôuêut deg una$uô". Ini: "times n Loahennama teêma kteô, lemmer day fehhmen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 82, 'Anef ad vsen cwiî, ad run aîas, d aqeîîi n wayen keppben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 83, 'Ma Irra k id Öebbi ar urbaâ segsen, u ssutren ak d tsriê ad ff$en, ini: "d awez$i, ur teppeff$em yidi, ur tepna$em acengu yidi. Akken, kunwi, iâoeb ikwen i$imi, abrid amenzu, ihi, qqimet akked ineggura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 84, 'Ur péalla $ef yiwen degsen, ma immut, d awez$i. Ur pbedda ar tenîelt is. Nitni, s tidep, jehlen ar Öebbi akked Umazan iS, mmuten nitni d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 85, 'Ur k ippaâoab wayla nnsen, ne$ dderya nnsen. Öebbi Ib$a kan a ten Iâaqeb yissen di ddunit, ad asen teffe$ taôwiêt nitni d ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 86, 'Ma ters ed tsuôep: "amnet s Öebbi, jahdet akked Umazan iS", imeôkantiyen nnsen a k ssutren tsriê, ad inin: "anef ane$ ar wid iqqimen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 87, 'Öuvan ad ilin akked wid igwran. Ppusel$en wulawen nnsen, ur fehhmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 88, 'Maca, amazan akked wid iumnen yides, jehden s wayla nnsen akked yiman nnsen. Widak, nnsen lxiô. Widak, d nitni ara irebêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 89, 'Ihegga yasen d Öebbi leonanat, ddawat sen isaffen ppazzalen, degsen ad wekkôen. D wagi ay d rrbeê ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 90, 'Wid id iufan ssebba, seg waâôaben n ucluê, usan d, ad asen ifk tsriê. Wid iskaddben Öebbi akked Umazan iS, qqimen. Wid ijehlen, segsen, ad sâaddin aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 91, 'Ur telli tuzzma $ef uôhifen, imuvan, wid ur nufi ara fken, ma neûêen ar Öebbi akked Umazan iS. Ur telli tuzzma $ef iâaôviyen. Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 92, 'Am akken, i wid ik id iusan a ten tneqqlev, tenniv: "ur awen ufi$ ara kwen ineqqlen". U$alen, allen feggvent seg imeîîawen, $weblen imi ur ufin ara sedqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 93, 'Tuzzma kan $ef wid ik issuturen tsriê, nitni d imeôkantiyen. Öuvan ad ilin akked ineggura. Isle$ Öebbi ulawen nnsen, d$a ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 94, 'Ad awen ssutren ssmaê, ma tu$alem d $uôsen. Ini: "ur ssuturet ssmaê, ur kwen numin d awez$i. Ni$ Imla ya$ Öebbi asali nnwen. Ad Iéeô Öebbi akked Umazan iS, igiten nnwen. Sinna, a ppu$alem ar Umusnaw n wayen iffren akked wayen ur neffir, ad awen Imel ayen txeddmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 95, 'Ad awen gren Öebbi, mi d tu$alem $uôsen, iwakken ad asen tanfem. Wexxeôt asen; nitni, s tidep, d laâôuô; axxam nnsen d Loahennama, d aqeîîi n wayen keppben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 96, 'Ad awen ggalen iwakken a ten tôavim. Ma tôuvam ten, ihi, Öebbi ur Ipôavi agdud iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 97, 'Aâôaben n ucluê zaden di tijehli akked nnxayel, zeggwiren ar uzgar n tilas id Issers Öebbi i Umazan iS. Öebbi d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 98, 'Ger waâôaben n ucluê, wid iêesben ayen seddqen d tabzert. Ggunin a ppekêes fellawen teswiât. Fellasen abeddel adiran n teswiât! Öebbi Issel, Issen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 99, 'Ger waâôaben n ucluê, wid iumnen s Öebbi d wass aneggaru, êesben ayen seddqen a ten iééié ar Öebbi akked téilla Umazan. Day maççi, s tidep, d ayen ara ten iééiéen? A ten Issekcem Öebbi deg uêunu S. Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 100, 'Imenza i izwaren, seg iminigen, imâiwnen, akked wid i ten iâanden ar lewqama, Iôuva ten Öebbi, ôuvan T. Ihegga yasen d leonanat, ddawat sen isaffen ppazzalen, ad wekkôen degsen, i lebda. D wagi ay d rrbeê ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 101, 'Ger waâôaben n ucluê, i wen d izzin, llan at sin wudmawen, akw ger imezda$ n Lmadina. Zgan di nnxayel. Ur ten tessinev. Nekwni, Nessen iten. A ten Nâaqeb berdayen, sinna, ad ppunefken i uâaqeb abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 102, 'Wiyad qaôôen s ibekkaven nnsen, ssemlalen igi ilhan d win nniven icemten. Izmer Öebbi ad asen Issuref. S tidep, Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 103, 'Eddem ed ssadaqa seg wayla nnsen, a ten tezzizdeg, a ten tûeffi. èÈéal ilmend nnsen. Ih, tiéilla k d talwit nnsen. Öebbi Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 104, 'Day ur éôin ara Öebbi, Neppa, Iqebbel asteôoaâ s$uô ixdimen iS? Ippaîaf ssadaqat. Ih, Öebbi Issuruf, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 105, 'Ini: "xedmet! Ad Iwali igiten nnwen, Öebbi, Umazan iS, akked lmumnin. Tu$alin nnwen ar Umusnaw n wayen iffren akked wayen ur neffir, ad awen Imel ayen txeddmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 106, 'Wiyav pganin lameô n Öebbi, a ten Iâaqeb, ne$ ad asen Issuref. Öebbi d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 107, 'Wid irran loamaâ i lemveôôa akked tijehli, i lefôaq ger lmumnin; d taxettalt i wid, iu$ lêal, llan pna$en Öebbi akked Umazan iS, ad ggalen, war ccekk: "ay neb$a siwa lewqama". Ad Icehhed Öebbi ar nitni, s tidep, d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 108, 'Ur ppili, degs, d awez$i. Iklal kteô, tilin ik, loamaâ ibnan $ef uêezzeb, seg wass amenzu. Degs irgazen i iêemmlen ad izdigen. Öebbi Iêemmel izedganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 109, 'Day win issersen lebni s $ef uêezzeb i Öebbi akked llza, ur yif ara win issersen lebni s $ef rrif n ucôuf ara iseggxen? Iseggex yis ar tmes n Loahennama. Öebbi ur Inehhu agdud imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 110, 'Izga lebni, bnan, ippara ccekk deg ulawen nnsen, alamma gezmen wulawen nnsen. Öebbi d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 111, 'Ih, Öebbi Iu$ ar lmumnin, iman nnsen akked wayla nnsen, imi Loennet i nitni. Pna$en deg ubrid n Öebbi. Nn$an, pwan$an. D lemâahda fellas, s tidep, di Tuôa, di Linoil akked Leqwôan. Anwa yifen Öebbi di tuîîfa n lemâahda s? Feôêet, ihi, di ssuq tsewwqem. Wagi d rrbeê ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 112, 'Wid isteôoâen, wid iâabden, wid ipcekkiôen, ixelwiyen, wid iîîinizen, wid ikennun, wid ippamôen lewqama, wid ipgeddilen ayen n dir, wid ipêaraben $ef tlisa n Öebbi ... Becceô lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 113, 'Ur issefk ara i Nnbi akked wid iumnen, ad ssutren ad pwasemmêen imcurak, xas ppilin asen, ma iban asen d ar, nitni, war ccekk, d at tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 114, 'Ibôahim ur issuter ara ad ipwasemmeê baba s, siwa ilmend n lemâahda i s ifka. Mi s d iban ar neppa d acengu n Öebbi, ifra p yides. Ibôahim, war ccekk, ippanez, iêellem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 115, 'Ur p Ixeddem Öebbi, ad Itlef agdud mbaâd ma Inha ten, alamma i sen Ibeggen acu ara êezzben. Öebbi, s tidep, Issen yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 116, 'Ih, Öebbi, IneS tagelda n tmurt akked igenwan, Issidir, Ineqq. Ur awen illi, war Öebbi, bab ne$ amâiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 117, 'Ni$ Issuref Öebbi i Nnbi akked iminigen, akked imâiwnen i iddan yides, di lweqt uwâiô, mbaâd ma qôib nneqlaben wulawen n urbaâ segsen. Sinna, Issuref asen. Ih, Neppa, i nitni, dUmâin, d''Aênin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 118, 'U i krav id igwran, armi, tamurt iwsâan, tediyyeq fellasen. Vaqen deg iman nnsen. Ufan ur illi ssôan si Öebbi, siwa Neppa. Sinna, Issuref asen, akken ad steôoâen. Öebbi, s tidep, Issuruf, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 119, 'A wid iumnen! Ëezzbet i Öebbi, ilit seg imawlan n tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 120, 'Ur issefk ara i imezda$ n Lmadina, d wayen i sen d izzin n waâôaben n ucluê, ad gwrin deffir Umazan n Öebbi, ne$ ad smenyafen iman nnsen i iman is. Ayagi, acku ur ten ipêaz fad, ne$ âaggu, ne$ llaé, deg ubrid n Öebbi. Ur keçmen akal ara isserfun ijehliyen, ur ppaîîafen acemma s$uô ucengu, siwa ma dayen i sen iuran d igi n wayen ilhan. Öebbi, s tidep, ur Isôuêu arraz iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 121, 'Ur pûeôôifen cwiî ne$ aîas, ur zeggren asif, siwa ma iura yasen, iwakken a ten Ikafi Öebbi $ef wayen ilhan deg wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 122, 'Ur Issefk ara i lmumnin ad ff$en akw. Awufan ad iffe$ ugraw si yal arbaâ, ad $bun di ddin, ad nabin agdud nnsen, mara u$alen $uôsen. Amar ad steêdren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 123, 'A wid iumnen! Nna$et ijehliyen i kwen iqeôben. Ad afen, $uôwen, teqseê. Cfut, Öebbi Ippili d wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 124, 'Mi d ters tsuôep, llan garasen wid iqqaôen: "anwa degwen, iwumi terna tagi, di liman"? Ma d wid iumnen, terna yasen liman, u nitni feôêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 125, 'Ma d wid iwumi blan wulawen, terna ammus i wammus nnsen. Mmuten u nitni d ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 126, 'Day ur walan ara, ar nitni la d sskaren lfetna, yal aseggwas, yiwen ubrid ne$ berdayen? Sinna, ur steôoiâen, ur d smektayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 127, 'Mi d ters tsuôep, ad mesmuqalen: "day illa yiwen ikwen id Ipwalin"? Sinna, ad wexxôen. Isswexxeô Öebbi ulawen nnsen, imi nitni d agdud ur nfehhem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 128, 'Ni$ iusa kwen id Umazan seg iman nnwen. èéay fellas laâtab nnwen. Ipêarab fellawen, d umâin, d aênin i lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 129, 'Ma wexxôen, ini: "Iqadd iyi Öebbi. Ur illi ôebbi siwa Neppa. FellaS ppekle$. Neppa d Mass n usgeld ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 1, 'Alô, wigi d issekniyen n Tezmamt tuûwibt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 2, 'Day d lwehma, i medden, ma Nweêêa n i urgaz nnsen: "nabi imdanen, becceô wid iumnen ar ad afen arraz umâin ar Mass nnsen"? Nnan ijehliyen: "wagi, s tidep, d aseêêar n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 3, 'Ih, Mass nnwen d Öebbi, i Ixelqen tamurt akked igenwan di sdis wussan. Sinna, Iâannec $ef usgeld, Iseyyi lameô. Ur illi umcafaâ siwa ma Iâammed as. D wagi ay d Öebbi, Mass nnwen. Ihi, âabdet eP. Day ur d tesmektayem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 4, '£uôeS akw tu$alin nnwen. Lemâahda n Öebbi d tidep. Ih, Inezzu axlaq, Ippales, iwakken ad Ikafi wid iumnen u xeddmen ayen ilhan, s lmizan. I wid ijehlen, tissit iô$an, aâaqeb aqeôêan, imi llan jehlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 5, 'D Neppa i Irran iîij d lefnaô, aggur d tafat. Iwezn as tiswaâin, iwakken a ppissinem amvan iseggwasen, akked leêsab. Ur Ixliq Öebbi ayagi, siwa s tidep. Ipfeûûil issekniyen i ugdud issnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 6, 'S tidep, di lemgarda ger yiv akked wass, akked wayen Ixleq Öebbi di tmurt akked igenwan, ard issekniyen i ugdud i ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 7, 'Ih, wid ur negguni ara timlilit yidne£, i tqennaâ tmeddurt di ddunit, u rekden degs, d wid i istehzan $ef issekniyen nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 8, 'Wigi, axxam nnsen di tmes, ilmend n wayen keppben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 9, 'Ih, wid iumnen u xeddmen ayen ilhan, a ten Inhu Mass nnsen, s liman nnsen. Ad ppazzalen isaffen seddawat sen, di leonanat isaâdiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 10, 'Anuju nnsen degs: "gedha s yissek a Öebbi"! Azul nnsen d: "tifrat". Anuju nnsen aneggaru: "ccekôan i Öebbi, Mass imavalen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 11, 'Lemmer ad Iaâoel Öebbi cceôô ar imdanen, akken nitni êaren $ef lxiô, yili ibbwev asen lajel nnsen. A Nanef i wid ur negguni ara timlilit yidne£, ad ddebdben di lbe$wv nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 12, 'Amdan, ma iêuza t ccqa, ad a£ £ d isiwel, iééel, iqqim ne$ ibedd. Mi s Nekkes ccqa s, ad iteddu amzun ur d inuj $uône£ilmend n ccqa i t iêuzan. Akka ay ppucebêen igiten nnsen i imaâfan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 13, 'Ni$ Nesqucc isuta, uqbel nnwen, imi densen. Ussan d $uôsen imazanen nnsen, s ubeggen, ur llin d wid ara iamnen. Akka ay Nepqeîîi agdud ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 14, 'Sinna, Nerra kwen d igensas di tmurt, deffir sen, a Nwali amek ara txedmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 15, 'Ma $ôan asen issekniyen nne£ iberrzen, wid ur negguni ara timlilit yidne£, ad inin: "awi d Leqwôan nniven, ne$ beddel it". Ini: "ur felli a t beddle$, s leb$i n yiman iw. Teddu$ kan akked wayen iyi d ippuweêêan. Nek ugade$, ma xedâa$ Mass iw, aâaqeb n wass ameqwôaêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 16, 'Ini: "lemmer i S ihwi i Öebbi, ur awen t id mli$, ur awen t id mmekti$. Ni$ zed$e$ yidwen tameddurt, uqbel is. Day ur tfehmem ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 17, 'Anwa i idensen kteô, ger win id igren tikerkas $ef Öebbi, ne$ win inekôen issekniyen iS? Ih, ur rebêen ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 18, 'La âabden, war Öebbi, ayen ur ten neîîuôu, ur ten nenfaâ. La qqaôen: "wigi d imcafâen nne$ ar Öebbi". Ini: "day a pxebbôem Öebbi $ef wayen ur Issin, di tmurt akked igenwan"? Gedha s yiS! I Aâlay sennig wayen pcaraken!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 19, 'Llan imdanen d yiwen n lois kan. Sinna, mgaraden. Lemmer ur d izwar ara wawal, s$uô Mass ik, ad yili uêuddu, garasen, $ef wayen i$ef mgaraden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 20, 'La qqaôen: "a lemmer id irs $uôes ussekni n Mass is"! Ini: "tabavnit ar Öebbi kan. Ihi, gganit. Nek, yidwen, seg wid iggunin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 21, 'Ma Nesêess i imdanen aêunu, deffir twa$it i ten iêuzan, atnan la ppandin i issekniyen nne£. Ini: "Öebbi Yif akw akken Ip$awal di tiêeôci". Imersulen nne£, s tidep, pparun ayen teppandim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 22, 'Neppa i kwen Ippawin di lberr, di yill. Alamma, mi tellam di lembwabeô, teppedum degsen s wavu uûwib, feôêen yis, tusa d tbucivant $uôsen, ppasent ed lemwao $uôsen, si yal tama, êulfan a d tezzi fellasen. Naâôen Öebbi, s lqaâida i Neppa: "ma Tsellkev a$ si tagi, ar a nili seg wid isnemmiren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 23, 'Mi ten Isellek, imiren u$alen be$wven di tmurt, war ssebba. A yimdanen! Lbe$wv nnwen, siwa $ef yiman nnwen. Zzhu di tmeddurt n ddunit, sinna, $uône£ tu$alin nnwen, ad awen Nmel ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 24, 'Amedya n tmeddurt di ddunit, am aman kan. Nesse$li ten id seg igenni, xelven akked im$an n tmurt, iseg teppen imdanen akked lmal. Mi tcebbeê tmurt, tu$al d tuzyint, $ilen, imezda$ is, ar deg ufus nnsen ay tella. Iusa p id lameô nne£, deg iv, ne$ deg wass, Nerra p d ahicuô, amzun ur teoouoeg ass izeryen. Akka ay Nfeûûel issekniyen i ugdud ipxemmimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 25, 'Inecced Öebbi s axxam n tifrat. Inehhu win i S ihwan, ar ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 26, 'I wid iweqmen, lewqama, ternuv as. Udmawen nnsen, ur ten ipnal bufsus, ne$ ddell. Widak, d at Loennet, nitni, degs ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 27, 'Aqeîîi n wid id ibbwin tucmitin, d tucmip itent icban. Ad ndellen. Ur sâun amenêul ar Öebbi. Amzun $ummen wudmawen nnsen, s ccevyat n yiv iberkanen. Widak d at tmes, nitni, degs, ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 28, 'Ass ideg ara ten Nfesser akw, a Nini, imiren, i wid icurken: "imukan nnwen, kunwi akked icriken nnwen"! Sinna Nessemfaôaq iten. A d inin, icriken nnsen: "maççi d nekwni ay tâabdem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 29, 'Ad Iqadd Öebbi, d Anagi garane$ yidwen, ar ur d necliâ deg uâbbed nnwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 30, 'Din, yal amdan ad iwali ayen iwasa. Ad u$alen ar Öebbi, Bab nnsen n tidep. Itelf iten wayen d snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 31, 'Ini: "anwa ikwen Ip$itin seg igenni akked tmurt? Anwa ay d Bab n tmejjin akked yiéôi? Anwa id Issuffu$en amuddir si lmegget, id Issuffu$en lmegget seg umuddir? Anwa i Iseyyin lameô"? A d inin: "d Öebbi". Ini: "ihi, day ur tepêezzibem ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 32, 'D wagi ay d Öebbi, Mass nnwen n tidep. Deffir tidep, acu i illan, siwa ttelfan? Ihi, acimi texdâam?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 33, 'Akka i iûaô wawal n Mass ik, $ef wid ixedmen tucmitin. Ih, nitni ur ppamnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 34, 'Ini: "day illa ger icriken nnwen, win id inzan lxelq, sinna, iules as d"? Ini: "Öebbi inezzu lxelq, sinna, Ippales as d. Ihi, amek ara twexxôem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 35, 'Ini: "day illa, ger icriken nnwen, win i inehhun ar tidep"? Ini: "Öebbi Inehhu ar tidep. Win Inehhun ar tidep, day ur Yif ara, akken Iklal tikli yideS, win ur nennehhu, siwa ma ipwanha? Acu ikwen iu$en? Amek tepseyyim"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 36, 'Tegwti, segsen, teddun kan d nnwaya. Nnwaya, war ccekk, ur tebbwi acemma si tidep. Ih, Öebbi Issen acu xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 37, 'Leqwôan agi ur d innulfa ara, war Öebbi. Maca, d atebbet n wayen it id izwaren, d afeûûel n Tezmamt, ur degs ccekk, s$uô Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 38, 'Ne$ la qqaôen: "isnulfa t id". Ini: "awit ed tasuôep i t icban, neccdet seg wanda tzemrem, war Öebbi, ma tessawalem tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 39, 'Xaîi, skaddben ayen ur nekcim di tmusni nnsen, ur ten id iusi usefhem is. Akka ay skaddben, wid i ten id izwaren. Wali, ihi, amek tevôa d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 40, 'Garasen, wid iumnen yis; garasen, wid ur numin yis. Mass ik Yif akw akken Issen ifessaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 41, 'Ma skaddben k, ini: "i nek igiten iw, i kunwi igiten nnwen. Ur teppkam deg wayen xedme$, ur ppka$ deg wayen txedmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 42, 'Garasen, llan wid i k issemêasen. Day tzemrev a pperrev ad slen iâeééugen, ma llan ur fehhmen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 43, 'Garasen, llan wid i k ipmuqulen. Day tzemrev a ppenhuv ider$alen, ma llan ur pwalin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 44, 'Öebbi, s tidep, ur Iddennis imdanen, s wacemma, maca imdanen densen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 45, 'Ass ideg ara ten Ifser, amzun sâaddan kan saâa n wass, ad msaâqalen. Ni$ xesôen wid iskaddben timlilit d Öebbi. Ur pwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 46, 'Ad ak Nessken kra seg wayen i sen Nâahed, ne$ a k id Nawi $uône£. Ihi, $uône£ tu$alin nnsen. Sinna, Öebbi d Anagi n wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 47, 'I yal lois, amazan. Ma iusa d umazan nnsen, a ppefru garasen s lmizan, ur pwadensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 48, 'Qqaôen: "melmi lemâahda agi, ma tessawalem tidep?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 49, 'Ini: "ur mlike$ i iman iw vveôô, ne$ aba$uô, siwa ayen Ib$a Öebbi. Yal lois s lajel is". Ma iusa d lajel nnsen, ur t swexxiôen s saâa, ur t id sseqôaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 50, 'Ini: "acu twalam, ma iusa kwen id uâaqeb iS, deg iv, ne$ deg wass? Acimi êaren $uôeS ibe$wviyen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 51, 'D$a, ma iusa d, a ppamnem yis? Tura, aql akwen t$eûbem fellas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 52, 'Sinna, ad asen inin i wid idensen: "jeôôbet aâaqeb n lebda. Ma teppuqeîîan siwa kan $ef wayen tkeppbem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 53, 'Steqsayen k: "d tidep ayagi"? Ini: "ih, s Mass iw, ar ayagi d tidep! Kunwi ur tezmirem i usfunneg".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 54, 'Xas ad isâu, yal amdan idensen, i illan di tmurt, ur d ifeddu yis. Ffren nndama mi walan aâaqeb. Aêuddu garasen, s lmizan, ur pwadensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 55, 'Day, s tidep, maççi n Öebbi i illan di tmurt akked igenwan? Ih, day lemâahda n Öebbi maççi d tidep? Maca, tegwti segsen ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 56, 'Neppa Issidir, Ineqq. £uôeS ara tu$alem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 57, 'A yimdanen! Ni$ iusa kwen id unabi s$uô Mass nnwen, akked ccfa n wayen iblan ulawen, akked nnhaya, akked uêunu i lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 58, 'Ini: "s lfevl n Öebbi akked uêunu S, s waya, xas ad feôêen". Yif ayen pkemmimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 59, 'Ini: "twalam ayen i wen d Issers Öebbi n ôôeéq? Terram segs leêlal d leêôam". Ini: "Iâammed awen Öebbi, ne$ tesnulfam d $ef Öebbi"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 60, 'Acu ara meyyzen, ass n tnekra, wid id igren tikerkas $ef Öebbi? Ih, Öebbi d Bab n lfevl af imdanen, maca tegwti segsen ur snemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 61, 'Ur teppiliv di liêala, ur temmalev si Leqwôan, ur tepce$wilem di kra, mebla ma Nella d Inagan nnwen, mara tweqmem. Lmizan ubelkim di tmurt u deg igenni, ur idrig i Mass ik. Akken seddaw waya, ne$ sennig es. Akw, di Tezmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 62, 'Ih, s tidep, iêbiben n Öebbi ur ppagwaden, ur $weblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 63, 'Wid iumnen u llan êezzben,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 64, 'a ten beccôen s lxiô di tmeddurt n ddunit, di laxeôt. Ur illi ubeddel deg wawalen n Öebbi. D wagi ay d rrbeê ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 65, 'Ur k i$webbel wawal nnsen. Ih, tazmert akw n Öebbi. Neppa Isell, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 66, 'S tidep, day maççi n Öebbi i illan deg igenwan, i illan di tmurt? D acu îîafaôen wid ipnujun, war Öebbi, ar icriken? Ïîafaôen kan nnwaya. Oaââlen kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 67, 'Neppa, i wen Irran iv i ureyyeê nnwen, ass iwakken a pwalim. Deg waya, s tidep, d issekniyen i ugdud isellen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 68, 'Nnan: "Öebbi Isâa aqcic. Gedha s yiS! Neppa d Ameôkanti. IneS i illan deg igenwan, i illan di tmurt. Ur tesâim adabu $ef waya. Day a d tinim $ef Öebbi, ayen ur tessinem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 69, 'Ini: "s tidep, wid id igren tikerkas $ef Öebbi, ur rebêen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 70, 'Zzhu di ddunit, sinna, $uône£ tu$alin nnsen. D$a, ad asen Nsâaddi aâaqeb uqsiê, imi llan jehlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 71, 'Eêku yasen d tadyant n Nuê, mi inna i ugdud is: "a yagdud iw! Ma ééayit fellawen tilin iw, akked usmekti w n issekniyen n Öebbi, $ef Öebbi ppekle$, ihi, zduklet lameô nnwen akked icriken nnwen. Sinna, ur awen teppili lhejna $ef lameô nnwen, d$a, frut ep felli, ur iyi sganit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 72, 'Ma twexxôem, ur awen ssuture$ taqdiât. Ih, taqdiât iw ar Öebbi kan. Felli lameô ad ili$ seg imvuâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 73, 'Skaddben t. Nsellek it, akked wid illan yides, di lbabuô. Nerra ten d igensas. Ne$meq wid iskaddben issekniyen nne£. Wali amek tevôa d wid ippunedôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 74, 'Sinna, deffir es, Nuzen ed imazanen ar igduden nnsen. Usan ten id s ubeggen. Ur ssawven ad amnen $ef wayen nekôen zik. Akka ay Nselle$ ulawen ixabiten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 75, 'Sinna, deffir sen, Nuzen ed Musa akked Haôun, ar Ferâun akked imvebbôen is, s issekniyen nne£. Sme$wôen iman nnsen. Llan d agdud ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 76, 'Mi ten id tusa tidep, s$uône£, nnan: "wagi, ih, d ssêur n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 77, 'Inna Musa: "day a tinim d ssêur wagi, i tidep mi kwen id tusa"? Ur rebêen iseêêaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 78, 'Nnan: "day d tusiv $uône$, ad a$ tesîixxôev seg wayen id nufa ar imezwura nne$, a ppu$alem, di sin, d imeqwôanen di tmurt? Ur numin, nekwni, yiswen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 79, 'Inna Ferâun: "awit iyi d yal aseêêar amusnaw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 80, 'Mi d usan iseêêaren, inna yasen Musa: "veggôet ara tveggôem"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 81, 'Mi veggôen, inna Musa: "ayen d tebbwim d ssêur. S tidep, a t Inqev Öebbi". Ih, Öebbi ur Issewqam ara igiten ifessaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 82, 'Öebbi Itebbit tidep, s wawal iS, xas ugin ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 83, 'I iumnen s Musa, siwa tarwa seg ugdud is, ilmend n tugdi uhewwel n Ferâun akked imvebbôen is. Ih, Ferâun d abe$wvi di tmurt. Neppa, s tidep, seg imaâfan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 84, 'Inna Musa: "a yagdud iw! Ma teppamnem s Öebbi, ppeklet fellaS ma d imvuâen ay tellam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 85, 'Nnan: "neppkel $ef Öebbi. A Mass nne$, ur a$ ppara d ahewwel i ugdud imednas;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 86, 'Sellek a$, s uêunu K, seg ugdud ijehliyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 87, 'Nweêêa i Musa akked gma s: "ebnut ixxamen i ugdud nnwen di Maûeô, erret ixxamen nnwen ar lqibla, beddet i téallit. Becceô lmumnin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 88, 'Inna Musa: "a Mass nne$! S tidep, Tefkiv i Ferâun akked imvebbôen is, ôôêuê akked wayla di tmeddurt n ddunit, a Mass nne$, iwakken ad nnetlafen seg ubrid iK. A Mass nne$, Squcc ayla nnsen, S$eô ulawen nnsen, ur ppamnen alamma walan aâaqeb aqeôêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 89, 'Inna: "ih, tepwaqbel tnaâôit nnwen. Ddut di lewqam, ur teddut d ubrid n wid ur nessin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 90, 'Nezzger At Isôail di yill. Vefôen ten Ferâun akked iâsekôiwen is, s leb$wev d lewâaôa. Armi ibbwev ad i$meq, inna: "umne$! Ih, ur illi ôebbi siwa Win is umnen At Isôail. Nek seg imvuâen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 91, 'Tura! Ni$ zik taâûav, telliv seg ifessaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 92, 'Assa, a Nsellek loeppa k, a d tegwri d assekni i wid ara k id ineûfen. Aîas n medden, s tidep, stehzan deg issekniyen nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 93, 'Ni$ Nessers At Isôail deg umkan umâin, u N$at iten s wayen ilhan. Ur mgaraden armi ten id tusa tussna. Ih, Mass ik ad Iêudd garasen, ass n tnekra, ilmend n wayen i$ef llan mgaraden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 94, 'Ma tcukkev $ef wayen i k ed Nessers, steqsi wid i iqqaôen Tazmamt, uqbel ik. Ni$ tusa k id tidep, s$uô Mass ik, ur ppili seg wid ipcukkun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 95, 'Ur ppili seg wid i iskaddben issekniyen n Öebbi, a ppiliv seg imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 96, 'Ih, wid i$ef iûaô Wawal n Mass ik, ur ppamnen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 97, 'xas usan ten id akw issekniyen, alamma walan aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 98, 'A lemmer telli temdint iumnen, u infaâ p liman is, siwa agdud n Yunes! Mi umnen, Nveôôef segsen aâaqeb imdelli di tmeddurt n ddunit. Neooa ten zzhan tallit kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 99, 'Ma ihwa yaS i Mass ik, ad amnen wid illan di ddunit, akken ma llan. Day a pêeppmev, keçç, i imdanen ad amnen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 100, 'Ur ippamen umdan siwa ma Irad Öebbi. Isdullu wid ur nfehhem ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 101, 'Ini: "walit i illan di tmurt akked igenwan. Ula iwumi issekniyen akked ineddiôen, i ugdud ur neppamen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 102, 'Day a pganin kan amedya n wussan n wid i ten id izwaren? Ini: "gganit, nek yidwen, seg wid ipganin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 103, 'Sinna, a Nsellek imazanen nne£, akked wid iumnen. Akka ay d lwajeb fella£, a Nsellek lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 104, 'Ini: "a yimdanen! Ma tcukkem di ddin iw, nek ur âabde$ wid tâabdem, war Öebbi. Maca, âabde$ Öebbi ara Idmen leôwaê nnwen. Pwamôe$ ad ili$ si lmumnin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 105, 'Sbedd udem ik i ddin, s umili ar tidep, ur ppili seg imcurak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 106, 'Ur pnuju, war Öebbi, ar wayen ur k inefâan, ur k iîîuôôun. Ma txedmev akken, keçç, imiren, a ppiliv seg imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 107, 'Ma Isâadda fellak Öebbi ccqa, ur ak illi ujebbaô siwa Neppa. Ma Irad ak lxiô, ur illi usebîîel i lfevl iS. Ippak it i win i S ihwan, deg ixdimen iS. Neppa Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 108, 'Ini: "a yimdanen! Ni$ tusa kwen id tidep s$uô Mass nnwen! Win ipwanhan, ipwanha kan i iman is; win innetlafen, innetlef kan i iman is. Ur lli$, nek, d awkil nnwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 109, 'Ddu d wayen ik ed ippuweêêan, eûbeô ard Iêudd Öebbi. Neppa, Yif akw imêaddan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 1, 'Alô. Tazmamt, issekniyen iS ppuûewwben, sinna, ppufeûûlen s$uô Uûwib i Ipwaxebbôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 2, 'Ur âabdet siwa Öebbi. Nek, s$uôeS $uôwen, d aneddaô u d abcir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 3, 'Ssutret ssmaê i Mass nnwen, steôoâet aS, ad Ifeôôeo fellawen afeôôeo ilhan, ar lajel ipwassnen. Ippak lfevl iS i yal bab n lfevl. Ma twexxôem, nekk ugade$ a ppeppuâqbem, ass ameqwran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 4, 'Tu$alin nnwen, ar Öebbi. Neppa Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 5, 'Day nitni, s tidep, ur snefvasen ara idmaren nnsen, iwakken ad ffren fellaS? Xas $ummen s iceîîiven nnsen, day ur Iéôa ara ayen teffren akked wayen d qqaôen? Neppa, s tidep, Issen i illan deg idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 6, 'Ur illi lweêc di tmurt, mebla ma illa ôôeéq is ar Öebbi. Issen tanezdu$t is, tanîelt is. Meôôa, di Tezmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 7, 'D Neppa i Ixelqen tamurt akked igenwan di sdis wussan. Asgeld iS illa $ef waman. A kwen Ijeôôeb anwi segwen ara ixedmen ayen ilhan, sennig wiyav. Ma tenniv: "ih, kunwi a d tekkrem deffir tmeppant nnwen", wid ijehlen, war ccekk, a d inin: "ayagi, kan, d ssêur n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 8, 'Ma Neswexxeô asen aâaqeb ar imir ipwassnen, war ccekk, a d inin: "d acu iT iîîfen"? Ass ideg ara ten id iawev, day illa wa ara ten iveôôfen segs? Ad asen izzi wayen i$ef pmmaâliken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 9, 'Ma Nesêess i umdan aêunu nne¨£, sinna, Nekkes as t, atan ad iayes, ad ijhel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 10, 'Ma Nesêess as l$it, deffir twa$it i t innulen, atan ad yini: "fukkent felli lemêayen", d$a, neppa, ad ifôeê, ad izux.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 11, 'Kkes ed wid iûebbôen, ixeddmen ayen ilhan. I widak ssmaê akked tikci meqqwôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 12, 'Ahat teppaoav kra n wayen ik ed ippuweêêan. Pzemmiven yis idmaren ik mara qqaôen: "a lemmer i s d irs ugerruj, ne$ idda d, yides, lmelk"! Keçç d aneddaô kan. Öebbi d Awkil n yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 13, 'Ne$ ad inin: "isnulfa t id". Ini: "awit ed, s usnulfu, mraw n tsuôtin am neppa. Naâôet ayen iwumi tzemrem, war Öebbi, ma tessawalem tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 14, 'Ma ur awen d rran ara, cfut ar irs ed kan s tussna n Öebbi, ar ur illi ôebbi siwa Neppa. Ihi, ma kunwi d imvuâen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 15, 'I wid ib$an tameddurt n ddunit akked ôôêuê is, a Nkafi, degs, igiten nnsen, ur asen Ntekkes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 16, 'Widak, ur ppafen, di laxeôt, siwa times. Ad i$li wayen ûenâen degs; inqev wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 17, 'Day win iddan d ubeggen, s$uô Mass is, u immal as t unagi s$uôeS…? U, uqbel is, Tazmamt n Musa, d nnhaya u d aêunu. Wigi umnen yis. Win i p inekôen, seg ikubar, ppaâud is d times. Ur ppili di ccekk fellas. Neppa, ih, d tidep s$uô Mass ik. Maca, tegwti n medden ur ppamnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 18, 'Anwa idensen sennig win id isnulfan tikerkas $ef Öebbi? Wigi a d rsen i Mass nnsen. A d inin inagan: "d wigi i iskaddben $ef Mass nnsen". Day Öebbi ur Ixezzu yara imednas?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 19, 'I isîixxiôen seg ubrid n Öebbi, i t issarmen d uâwij, nitni ur uminen s laxeôt?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 20, 'Wigi, ur sfunnugen di tmurt, ur asen illi bab, war Öebbi. Fellasen aâaqeb ar wayev. Ur zmiren ad slen, ur pwalin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 21, 'D wigi i isxesôen iman nnsen. Itelf iten wayen d snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 22, 'Ur illi ccekk, ih, nitni ad xesôen, di laxeôt, sennig wiyav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 23, 'Ih, wid iumnen, u xeddmen ayen ilhan, u unzen aS i Mass nnsen, widak d at Loennet, degs ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 24, 'Amedya n snat n trebbuyaâ am uder$al, uâééug, akked win ipwalin, win isellen. Day âadlen sin imedyaten agi? Day ur d tesmektayem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 25, 'Ni$ Nuzen ed Nuê i ugdud is: "nek d aneddaô nnwen ipbegginen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 26, 'iwakken ur tâabdem siwa Öebbi. Nek ugaded aâaqeb fellawen, ass aqeôhan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 27, 'Nnan imvebbôen, wid ijehlen, seg ugdud is: "keçç, $uône$, d amdan am nekwni. Nwala, d ôôdiyen nne$, kan, war ameyyez, i k ivefôen. Ur nwala s wacu i $ tifem. Xaîi, nêesb ikwen d ikeddaben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 28, 'Inna: "a yagdud iw! Acu twalam ma ddi$ d ubeggen n Mass iw? Ifka yi d aêunu s$uôeS. Idreg fellawen. Day a t nêeppem fellawen, ma kunwi tugim t?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 29, 'A yagdud iw! Ur awen ssuture$ ayla, ilmend is; taqdiât iw ar Öebbi kan. Ur ppara$, nek, wid iumnen. S tidep, ad mlilen d Mass nnsen. Maca, nek wala$ kwen d agdud ur nessin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 30, 'A yagdud iw! Acu ara yi isellken seg ufus n Öebbi, lemmer i ten rri$ akin, day ur d tesmektayem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 31, 'Ur awen qqaôe$: $uôi lexzayen n Öebbi. Ur ssine$ tabavnit. Ur qqaôe$: nek d lmelk. Ur qqaôe$ i wid êeqôent wallen nnwen: ur asen Ippak ara Öebbi lxiô, d awez$i. Yif akw Öebbi akken Iéôa, i illan deg iman nnsen. Mulac ad ili$ seg imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 32, 'Nnan: "a Nuê! Ni$ tnamrev a$, tessugtev a$ anamer. Ihi, awi ya$ d ayen i $ tâahdev, ma tessawalev tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 33, 'Inna: "d Öebbi kan ar awen t id Iawin, ma ihwa yaS. Kunwi ur tesfunnugem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 34, 'Xas b$i$ a kwen neûêe$, ur tesfaydayam seg wanûaê iw, ma Ib$a Öebbi a kwen Itlef. Neppa d Mass nnwen; tu$alin nnwen $uôeS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 35, 'Ne$ qqaôen: "isnulfa t id". Ini: "ma snulfa$ t id, lbe$wv iw i yiri w. Nek, ur ppka$ di lbe$wv nnwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 36, 'Ippuweêêa d i Nuê: "ur ippamen yiwen, d awez$i, seg ugdud ik, siwa wid illan umnen. Ihi, ur k icqi wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 37, 'Eûnaâ lbabuô, ger wallen nne£, s uweêêi nne£. Ur iyI d pmeslay $ef wid idensen, war ccekk, ad $emqen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 38, 'La iûennaâ lbabuô. Yal tikelt ara âaddin $uôes imvebbôen n ugdud is, tkaâriren fellas. Inna: "ma temmaâlkem degne$, ihi, a nemmaâlek degwen akken temmaâlkem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 39, 'Deqqal a ppeéôem, u$uô ara d ias uâaqeb ara t isdullen, ara iêaz uâaqeb imezgi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 40, 'Alamma, mi d iusa lameô nne£, la pfeggiven igwefran d ihedman, Nenna: "awi degs tayuga n yal ûûenf, tawacult ik - siwa wid i$ef id izwar wawal -, akked wid iumnen". Drus kan i iumnen yides.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 41, 'Inna: "rekbet degs, s yisem n Öebbi, acali s akked trusi s. Mass iw, s tidep, Ipsemmiê, Ipêunu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 42, 'Icula yissen, di lemwao anect idurar. Issawel Nuê i mmi s, i illan weêdes: "a mmi ali d yidne$, ur teppiliv ar ijehliyen"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 43, 'Inna: "ûûôan iw d adrar, ad iyi isellek seg waman". Inna: "assa, ulac leslak si lameô n Öebbi, siwa i win i$ef Iêun". Âaddant lemwao garasen. Iûebê ed seg wid ipwa$emqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 44, 'Nnan: "a tamurt, seblaâ aman im, a yigenni eûûfu". Aman zzren. Iûaô lameô: irs $ef Loudi. Iffe$ uberraê: akin agdud imednas!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 45, 'Inuj Nuê ar Mass is, inna: "a Mass iw! Ni$ mmi n twacult iw. Ih, lemâahda K d tidep, Keçç Tifev akw imêaddan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 46, 'Inna: "a Nuê! Neppa, s tidep, ur illi n wacult ik. Ih, neppa ur ixdim ayen ilhan. Ihi, ur iyI d steqsay $ef wayen ur tessinev. Nek a k Ssakwaye$, ur teppiliv seg wid ur nessin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 47, 'Inna: "a Mass iw! Ili di lâawen iw, iwakken ur K id steqsaye$ $ef wayen ur ssine$. Ma ur iyi Tsemmêev, ur Têunev felli, ad ili$ seg imexsuôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 48, 'Nnan d: "a Nuê! Ers ed s tifrat s$uône£, akked lbaôaka, fellak akw $ef leoyus i illan yidek. Kra n legyus, a ten N$it. Sinna, fellasen s$uône£, aâaqeb aqeôêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 49, 'Tagi si teqûivin n tbavnit, Nweêêa yak tent. Ur tent tessinev, keçç, ne$ agdud ik, uqbel wagi. Ihi, eûbeô, taggara, war ccekk, i wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 50, 'I Âad, gmat sen Hud, inna: "a yagdud iw! Âabdet Öebbi! Ur tesâim ôebbi, war Neppa. Kunwi tesnulfuyem d kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 51, 'A yagdud iw! Ur awen ssuture$ taqdiât $ef waya. Taqdiât iw ar Win kan, iyi d Ixelqen. Day ur tefhimem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 52, 'A yagdud iw! Ssutret ssmaê i Mass nnwen, sinna, steôoâet aS. Ad awen d Isse$li ageffur d ihedman, ad awen irnu tazmert i tezmert nnwen. Ur ppu$alet d ibe$wviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 53, 'Nnan as: "a Hud! Ur a$ d tusid s ubeggen, ur neppaoa, nekwni, iôebbiten nne$, ilmend n wawal ik, ur numin yisek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 54, 'Neqqaô kan, d kra iôebbiten nne$, i k i$eôqen". Inna: "nek, Anagi w d Öebbi, u cehhdet ar ur ppka$ ara deg wayen tepcarakem,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 55, 'war Neppa. Ihi, andit iyi akken ma tellam, sinna ur iyi sganayet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 56, 'Nek, ppekle$ af Öebbi, Mass iw u Mass nnwen. Ur illi umexluq ur Iîîif seg ixef is. Ih, Mass iw deg ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 57, 'Ma wexxôen, ni$ ssawve$ awen d ayen i$ef id ppuceggâa$ $uôwen. A d Inûef, Mass iw, agdud war kunwi. Ur T teîîuôum s wacemma. Mass iw, s tidep, d Amêareb n yal cci".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 58, 'Mi d iusa lameô nne£, Nsellek Hud akked wid iumnen yides, s uêunu s$uône£. Nsellek iten seg uâaqeb uwâiô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 59, 'Akka Âad. Nekôen issekniyen n Mass nnsen, âuûan imazanen iS. Ddan d lameô n yal aqehhaô iggernennen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 60, 'A ten ivfeô xezzu di ddunit agi, u deg wass n tnekra. Day, war ccekk, ur jhilen ara Âad, ar Mass nnsen? Day maççi: "akin Âad, agdud n Hud"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 61, 'I Tamud, gmat sen ÛüÜaliê, inna: "a yagdud iw! Âabdet Öebbi! Ur tesâim ôebbi, war Neppa. Neppa Ixelq ikwen seg wakal, Izzde$ ikwen fellas. Ssutret aS ssmaê, sinna, steôoâet aS. Mass iw, s tidep, Iqeôb ed, Ippara d awal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 62, 'Nnan as: "a Üaliê, ni$ telliv garane$, uqbel aya, d asirem nne$. Day ad a$ tekksev aâbad n wayen âabden imezwura nne$? Nekwni, s tidep, aql a$ di ccekk imcebbwel, $ef wayen u$uô la $ tneccdev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 63, 'Inna: "a yagdud iw! Acu twalam ma ddi$ d ubeggen n Mass iw? Ifka yi d aêunu s$uôeS. Acu ara yi isellken seg ufus n Öebbi, ma aâûa$ $uôeS? Iyi ternam, siwa taxessaôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 64, 'A yagdud iw! Tagi d tal$wemt n Öebbi, d assekni i kunwi. Eooet ep a ppeks di tmurt n Öebbi. Ur p pjeyyifet, mulac a kwen id isami uâaqeb iqeôben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 65, 'Gezmen as ivaôen. Inna: "zhut deg ixxamen nnwen, krav wussan. Apan lemâahda ur nepwankaô".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 66, 'Mi d iusa lameô nne£, Nsellek Üaliê akked wid iumnen yides, s uêunu s$uône£, si ddell n wass nni. Ih, Mass ik d Uohid, d Uzmir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 67, 'Asu$u iwwet wid idensen, gwran d d imeslax deg ixxamen nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 68, 'amzun ur rbiêen degsen. Day, s tidep, ur jhilen ara Tamud, ar Mass nnsen? Day maççi: "akin Tamud"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 69, 'Ni$ usan d imceggâen nne£ ar Ibôahim, s ubecceô. Nnan: "tifrat"! Inna: "tifrat"! Ur iâaîîel ara ibbwi d aâjmi icwin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 70, 'Mi iwala ifassen nnsen ur d ééilen ara $uôes, isêassef iten, iugad iten. Nnan: "ur ppagwad, nekwni neppuceggaâ ed ar ugdud n Luî".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 71, 'Tameîîut is tbedd, tevûa. Nbecceô ip s Isêaq, akked Yaâqub, deffir Isêaq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 72, 'Tenna: "a lêif iw, day a d arwe$, nek d tam$aôt, u argaz agi inu, wesser? Ayagi, s tidep, d lwehma"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 73, 'Nnan: "day twehmev di lameô n Öebbi? Aêunu n Öebbi, akked lbaôaka S, fellawen ay at uxxam. Ih, Neppa d Amaâzuz, Mucaâ".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 74, 'Mi s tekkes tugwdi i Ibôahim, u iusa t id ubecceô, inumer a£ $ef ugdud n Luî.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 75, 'Ibôahim, s tidep, iêellem, ippanez, isteôoiâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 76, '"A Ibôahim, ur keççem deg waya. Ni$ iusa d lameô n Mass ik. Nitni, a ten id ias uâaqeb, war tifrat".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 77, 'Mi usan imceggâen nne£ ar Luî, innu$ben, ur isâi i$il a ten ifukk. Inna: "wagi d ass uwâiô".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 78, 'Iusa d ugdud is, zeêfen d $uôes. Llan, zik, xeddmen tucmitin. Inna: "a yagdud iw! Atent an issi, nitenti zeddigit, i kunwi. Ëezbet i Öebbi, ur iyi pêeccimet ar inebgawen iw. Day ur illi ara, garawen, urgaz aêesbi"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 79, 'Nnan: "ni$ teéôiv ur nesâi lêeqq deg issi k. Keçç, s tidep, teéôiv d acu neb$a".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 80, 'Inna: "a lemmer i wen zmire$, ne$ sâi$ tayep ioehden"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 81, 'Nnan: "a Luî, nekwni d imceggâen n Mass ik. Ur k id ppawven. Öuê akked twacult ik, deg iv. Yiwen degwen ur d itezzi! Kkes ed tameîîut ik. Neppat, s tidep, a ppepwwet s wayen ara ten iwwten. Ih, ppaâud nnsen, taûebêit. Ni$ tqeôb ed tûebêit"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 82, 'Mi d iusa lameô nne£, Nesredm ip. Nesse$li d fellas abruri n yiéôa ibelbaven n talaxt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 83, 'Pwanesxen ar Mass ik. Nitni, ur bâiden i imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 84, 'I Madian, gmat sen Cuâayeb, inna: "a yagdud iw! Âabdet Öebbi! Ur tesâim ôebbi, war Neppa. Ur ssenqaset di lkil akked lmizan. Nek, wala$ kwen teôwam, u ugade$ fellawen aâaqeb, ass itezzin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 85, 'A yagdud iw! Ktilet, weznet, s lewqama. Ur îîuôôut imdanen deg wayla nnsen, ur pdenniset, tessefsadem di tmurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 86, 'Yif it i kunwi wayen d iqqimen i Öebbi, ma d lmumnin ay tellam. Ur lli$, nek, d amêareb nnwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 87, 'Nnan: "a Cuâayeb, day a$ umôen wawalen ik, a neoo ayen âabden imezwura nne$? Ne$ a nexdem, deg wayla nne$, ayen ur a$ nehwi? Keçç, s tidep, d uêlim, d uûwib".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 88, 'Inna: "a yagdud iw! Acu twalam, ma ddi$ d ubeggen n Mass iw? I$at iyi yis, l$it imaânen. Ur b$i$ a kwen mgirrde$, siwa $ef wayen i wen gedle$. B$i$ kan, s wayen zemre$, ad awen ûegme$ tikli. Lâawen iw s$uô Öebbi kan. Ppekle$ fellaS, utube$ T.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 89, 'A yagdud iw! Awer kwen teppara nnmara w d ibe$wviyen, a ppevôu yidwen akken tevôa d ugdud n Nuê, ne$ win n Hud, ne$ win n Üaliê! Agdud n Luî, ur ibâad ara segwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 90, 'Ssutret ssmaê i Mass nnwen, sinna, steroâet aS. Mass iw, s tidep, Ipêunu, Ipêemmil".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 91, 'Nnan: "a Cuâayeb, ur nefhim ara aîas n wayen id tenniv. Aql a$ nwala k d uôhif garane$. Lemmer maççi d alag ik, war ccekk, a k neôoem. Ur a$ tezmirev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 92, 'Inna: "a yagdud iw! Day Öebbi, $uôwen, yif iT walag iw, di tezmert? Terram T ar deffir n waârur nnwen. Mass iw, s tidep, Izzi i wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 93, 'A yagdud iw! Xedmet deg umekkan nnwen, nek ad xedme$. Deqqal a ppeéôem, u$uô ara d ias uâaqeb ara t isdullen, anwa ay d akeddab. Âasset, nek, yidwen, ad âasse$".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 94, 'Mi d iusa lameô nne£, Nsellek Cuâayeb akked wid iumnen yides, s uêunu s$uône£. Asu$u iwwet wid idensen, gwran d d imeslax deg ixxamen nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 95, 'amzun ur rbiêen degsen. Day maççi: "akin Madian"! Am: "akin Tamud"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 96, 'Ni$ Nuzen ed Musa, s issekniyen nne£, akked udabu n ûûeê,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 97, '$uô Ferâun akked imvebbôen is. Ddan d lameô n Ferâun. Lameô n Ferâun ur illi d uûwib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 98, 'Ad izwir i ugdud is, ass n tnekra, a ten inheô ar usario n tmes. A yasario ucmit u$uô pwanehôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 99, 'A ten ivfeô xezzu di tagi, u deg wass n tnekra. A tikci tucmip ippunefken!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 100, 'Ayagi, si teqûivin n temdinin, i k d Nessawal. Garasent tid ibedden, tid ipwamegren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 101, 'Ur ten Nednis. Maca, densen iman nnsen. Ur ten nefâan s wacemma, iôebbiten nnsen i la naâôen, war Öebbi, mi d iusa lameô n Mass ik. I sen rnan, siwa ssxev.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 102, 'Akka tiyta n Mass ik. Mi Iwwet timdinin i idensen, s tidep, tiyta S teqôeê, teqseê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 103, 'Ih, deg waya, assekni i wid iugaden aâaqeb n laxeôt. Ass nni, d ass unejmaâ n yimdanen. Ass nni, d ass n ccada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 104, 'A t Neswexxeô kan ar lajel iuran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 105, 'Ass ideg ara d ias, ur d ipmeslay yiwen, siwa ma s tesriê iS. Ad ilin igeswaêen, isaâdiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 106, 'Wanag igeswaêen ad ilin di tmes, s unazaâ d imeîîi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 107, 'ad wekkôen dinna, ayen ara dumen tmurt akked igenwan, siwa ma ur Irad ara Mass ik. Ih, Mass ik Ixeddem ayen i S ihwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 108, 'Wanag isaâdiyen, di Loennet, ad wekkôen, dinna, ayen ara dumen tmurt akked igenwan, siwa ma ur Irad ara Mass ik. D tikci n war tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 109, 'Ur k ikeççem ccekk $ef wayen âabden widak. Ayen âabden am wayen âabden imezwura nnsen, zik. War ccekk, ad asen Nefk amur nnsen, ur inqis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 110, 'Ni$, s tidep, Nefka Tazmamt i Musa. Mgarraden fellas. Lemmer ur d izwar ara wawal s$uô Mass ik, yili useyyi garasen. Haaten, ih, di ccekk imcebbwel fellas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 111, 'War ccekk, akken ma llan, ad Ikafi Mass ik igiten nnsen, s lmizan. Neppa, s tidep, Issen ayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 112, 'Ihi, ili d uwqim, akken i k ippunefk lameô, keçç akked wid isteôoâen yidek. Ur be$wvet. Neppa, s tidep, Ipwali ay txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 113, 'Ur pqeôôibet ar wid idensen, a kwen tnal tmes! Ur tesâim bab, war Öebbi, ihi, ur tepwasellkem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 114, 'èéal ûbeê, tameddit, kra n lewqat n yiv. S tidep, ise$iyen neqqven tucmitin. Ayagi d asmekti i wid ismektayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 115, 'Eûbeô! Öebbi, s tidep, ur Iveggiâ taqdiât n lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 116, 'A lemmer llan, di tsuta i kwen id izwaren, imezgiyen ineqqven asefsed di tmurt! Qlilit kan seg wid Nsellek segsen. Wid idensen ddan akked wayen i ten izhan, u$alen d ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 117, 'Ur Isquccu ara Mass ik timdinin, d aêerfi, ma llan imezda$ nnsent d lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 118, 'Lemmer i S ihwi i Mass ik, ad Irr imdanen d yiwen n lois. Zgan mgarraden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 119, 'Kkes ed wid i$ef Iêun Mass ik. Ixelq iten i wayagi. Itam wawal n Mass ik: "ad Acaôe$ Loahennama, war ccekk, s leonun akked yimdanen mejmulen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 120, 'Ayen akw i k ed Neêka n tmucuha imazanen, iwakken a Ntebbet ul ik, yissent. Id iusan dagi d tidep, d anabi u d asmekti i lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 121, 'Ini i wid ur numin ara: "xedmet ay tzemrem, nekwni s tidep, la nxeddem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 122, 'Gganit, nekwni la nepgani".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 123, 'N Öebbi tabavnit n tmurt akked igenwan. £uôeS ara u$alen akw lumuô. Ihi, âabed iT, ppkel fellaS. Ur I$effel ara Mass ik, $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 1, 'Alô. Wigi d issekniyen n Tazmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 2, 'Ih, Nessader it id d Leqwôan, s taâôabt, amar a pfehmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 3, 'Nekwni Nêekku yak tiêkayin igerzen mavi, deg wayen i k Nweêêa di Leqwôan agi, xas telliv, uqbel is, seg wid istehzan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 4, 'Mi inna Yusef i baba s: "a baba! Nek wala$ mrawyan itran, iîij, akked waggur, wala$ ten knan iyi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 5, 'Inna: "a mmi! Ur êekku ayen twalav i watmaten ik, ad ak andin ticeôkep. Cciîan, s tidep, d acengu n ûûeê n umdan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 6, 'Akka, a k Ifren Mass ik, u ak Isselmed asefru n temsal, u ad Itim l$it iS, i keçç akked twacult n Yaâqub, akken it Itam, zik, af lejdud ik: Ibôahim akked Isêaq. Mass ik, s tidep, d Amusnaw, d Uûwib".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 7, 'Ni$, di Yusef akked watma s, illa ussekni i wid isteqsayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 8, 'Mi nnan: "war ccekk, ifen a$, Yusef akked gma s, akken iten iêemmel babat nne$, u nekwni d îîeôma. Babat nne$, s tidep, haat di ttelfan n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 9, 'En$et Yusef, ne$ nfut ep si tmurt, a d ilhu degwen babat wen, sinna, a ppu$alem d imdanen ixeddmen ayen ilhan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 10, 'Inna win d immeslayen, degsen: "ur neqqet Yusef, veggôet ep ar lqaâa n wannu. Ma tgam akka, a t iddem yiwen umsebrid".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 11, 'Nnan: "a babat nne$, acu k iu$en, ur a$ tuminev ara, $ef Yusef. Nekwni, fellas, s tidep, d unûiêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 12, 'Sseddu t yidne$ azekka, ad izhu, ad iurar. Nekwni, war ccekk, a nêareb fellas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 13, 'Inna: "nek, s tidep, $weble$ ma tebbwim t yidwen, ugade$ a t içç lweêc, kunwi testehzam degs".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 14, 'Nnan: "ma içça t lweêc, u nekwni d îîeôma, s tidep a nili d imexsuôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 15, 'Mi t bbwin, mwafaqen a t rôen ar lqaâa n wannu, Nweêêa yas: "ad asen temlev, s tidep, lameô agi nnsen, nitni ur éôin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 16, 'U$alen d tameddit, ar babat sen, pprun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 17, 'Nnan: "a babat nne$, s tidep, nôuê a nemzizzel, neooa Yusef ar lqecc nne$, içça t lweêc. Ur a$ teppamnev, xas nenna d tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 18, 'Bbwin d tasedrit is, degs idamen n rrya. Inna: "xaîi! D iman nnwen i wen d iccacven lameô. Ilha ûûbeô. Anuju $eô Öebbi, mgal ayen d teêkam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 19, 'Usan d iminigen, uznen win id ippagwmen, issader ssvel is. Inna: "a lxiô, wagi d aqcic"! Ffren t, amzun d sselâa. Öebbi Iéôa acu xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 20, 'Zzenzen t, s ôôxa, s kra iûuôdiyen. Ur as fkin ara azal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 21, 'Inna, i tmeîîut is, Umaûôi i t iu$en: "eôêeb yis, amar ad a$ infaâ, at nerr d mmit nne$". Akka ay Nesseqâad Yusef di tmurt, iwakken ad as Nesseêfev asefru n temsal. Öebbi d Amezwaru s lameô iS, maca tegwti n medden ur éôin ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 22, 'Mi d immeêtel, Nefka yas ûûwab, tussna. Akka ay Nepkafi iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 23, 'Teb$a t tin u$ur izde$. Terra tibbura, u tenna: "eyya keçç"! Inna: "ad iyi Ineooi Öebbi! Ni$ bab iw iôêeb yissi. S tidep, ur rebêen imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 24, 'S tidep, teb$a t, u neppa ib$a p, lemmer ur iwala ara atebbet n Mass is. Akka, iwakken a Nessebâad fellas tuccva, lâaô. Neppa, s tidep, seg imdanen nne£ izedganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 25, 'Uzzlen ar tebburt, tcerreg as tasedrit is, si zdeffir. Mmugren, argaz is, ar tebburt. Tenna: "acu ay d aqeîîi n win iâabwlen ad iccmet tawacult ik, siwa lêebs ne$ aâaqeb aqeôêan"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 26, 'Inna: "d neppat iyi ib$an". Icuhhed ed yiwen unagi si twacult is: "ma teqqeôs tsedrit si zdat, tenna d tidep, u neppa d akeddab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 27, 'Ma teqqeôs tsedrit si zdeffir, teskaddeb, u neppa seg at tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 28, 'Mi iwala teqqeôs tsedrit si zdeffir, inna: "ayagi, war ccekk, si nncub nnkwent. Ih, nncub nnkwent d timeqwôaêanin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 29, 'A Yusef, ppu ayagi, u kem ssuter ssmaê ubekkav im. Kem, s tidep, teccvev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 30, 'La qqaôent tlawin, di temdint: "tameîîut umdebbeô têemmel acrik is. Teshebl ip tayri. F akken nwala, appan, s tidep, di ttelfan n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 31, 'Mi tesla s nncub nnsent, tuzen $uôsent, thegga yasent tanalt. I yal yiwet segsent, tefka tafrut. Tenna: "effe$ ed garasent". Mi t walant, isdehc itent, jerêent ifassen nnsent, nnant: "êaca Öebbi, wagi maççi d amdan, wagi siwa d lmelk ukyis".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 32, 'Tenna: "d wagi i$ef iyi tlummemt. Ih, b$i$ t, neppa iqqim zeddig. Ma ur ixdim ara ay s umôe$, war ccekk, ad ipwaêbes, ad ipwaêqeô".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 33, 'Inna: "a Mass iw! Smenyafe$ lêebs i wayen u$ur iyi d ssawalent. Ma ur Tesbaâdev ara felli nncub nnsent, ad male$ $uôsent, ad ili$ seg wid ur nessin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 34, 'Ijaweb as d Mass is. Issebâad fellas nncub nnsent. Neppa, s tidep, Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 35, 'Sinna, mi ten usan issekniyen, ufan, war ccekk, ilaq a t irr ar lêebs, kra n tallit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 36, 'Kecmen yides, ar lêebs, sin ilmeéiyen. Inna yiwen degsen: "nek wala$ iman iw, la teééme$ ccôab". Inna d wayev: "nek wala$ iman iw, la ppawi$ a$ôum $ef uqeôôu w, la teppen segs ifrax. Ssefru ya$ p id. Ih, nwala k seg iâaôviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 37, 'Inna: "seg wayen iyi ss$eô Mass iw, ad awen p id ssefru$, uqbel a kwen id iawev lqut i wen ppakken. Nek ooi$ ddin n ugdud ur numin s Öebbi, u nitni nekôen laxeôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 38, 'Ddi$ d ddin n lejdud iw: Ibôahim, Isêaq akked Yaâqub. Ur a$ ippunefk a nezdukkel acemma i Öebbi. Ayagi si lfevl n Öebbi fellane$, akw $ef imdanen. Maca, tegwti n yimdanen ur snemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 39, 'A yimeddukwal iw n lêebs, menyif imawlan imfaôaqen, ne$ Öebbi Yiwen, Aqehhaô?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 40, 'Ay tâabdem, war Neppa, d ismawen kan i sen tefkam, kunwi akked imezwura nnwen. Ur asen d Issers ara Öebbi kra udabu. Lêukm ar Öebbi kan. Iumeô ed ur tâabdem, siwa Neppa. D wagi ay d ddin uûwib, maca tegwti n yimdanen ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 41, 'A yimeddukwal iw n lêebs, wanag yiwen degwen ad ismiri ccôab, i bab is, wayev ad ippusemmeô $ef umidag, ifrax ad nneqben aqeôôu s. Ippuseyya lameô $ef wayen iyi d testeqsam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 42, 'Inna i win iêûa ad islek, segsen: "ar bab ik, smekti iyi d". Cciîan iseppu t, ur t id ismekti ar bab is. Irna, di lêebs, kra iseggwasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 43, 'Inna ugellid: "nek wala$ ûa testan tiqebwaniyin, la tent teppent ûa tuvâifin, akked ûa tyedrin tizegzawin, tiyav d tiqquôanin. A yimvebbôen, ssefrut iyi d targit, ma tellam seg wid issefruyen tirga".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 44, 'Nnan: "d tirga iwlellsen. Ur nelli d imusnawen i usefru n tirga".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 45, 'Win i isellken si sin nni, armi tallit id immekti, inna: "nek, ad awen d awi$ asefru ines, aznet iyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 46, 'A Yusef, bab n tidep, ssefru ya$ d: ûa testan tiqebwaniyin, la tent teppent ûa tuvâifin, akked ûa tyedrin tizegzawin, tiyav d tiqquôanin. Amar, ma u$ale$ ar imdanen, amar ad éôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 47, 'Inna: "zerâat ûa iseggwasen imyevfaôen. Ayen tzerâam, eooet ep di tyedrin is, siwa cwiî ara teççem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 48, 'Sinna, deffir sen, a d asen ûa iwaâôen. Ad ççen ayen i sen theggam siwa cwiî, seg wayen txeznem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 49, 'Sinna a d ias, deffir waya, useggwas n tallalt i medden, ideg ara éden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 50, 'Inna ugellid: "awit ep id $uôi". Mi t id iusa umersul, inna: "u$al ar bab ik, u steqsi t acu ay d l$eôv n tlawin i ijerêen ifassen nnsent. Mass iw, s tidep, Issen nncub nnsent".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 51, 'Inna: "acu ara d tinimt mi teb$amt Yusef"? Nnant: "êaca Öebbi, ur nufi $uôes tuccva". Tenna d tmeîîut umvebbeô: "tura, a d tban tidep. D nek i t ib$an, ma d neppa, s tidep, d bab n tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 52, '"Akka, iwakken ad iéeô ur t xdiâa$ ara s tuffra. Öebbi ur Inehhu nncub n lxeyyan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 53, 'Ur pzekki$ iman iw. Tanefsit, s tidep, tezzu$uô ar tuccva, siwa ma Iêun Mass iw. Mass iw, s tidep, Ipsemmiê, Ipêunu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 54, 'Inna ugellid: "awit ep id $uôi, d laâtiq iw". Mi s immeslay, inna: "keçç, assa, nefka yak adabu, laman".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 55, 'Inna: "wekkel iyi $ef lemxazen n tmurt, nek d amêareb amusnaw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 56, 'Akka ay Nesseqâad Yusef di tmurt, ad izde$ anda i s ihwa. Nepêunu $ef win i £ ihwan, ur Nesôuêu arraz iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 57, 'S tidep, arraz n laxeôt yif it, i wid iumnen u llan pêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 58, 'Usan watmaten n Yusef, kecmen $uôes, iâqel iten, nitni ur t âqilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 59, 'Mi sen ifka ppâabgat nnsen, inna: "awit iyi d gmat wen s babat wen. Day ur twalam ara zade$ awen lkil, u, nek, ife$ akw wid isnebgaten?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 60, 'Ma ur iyi t id tebbwim ara, ur awen nepktili $uôi, ur iyi d tepsamim ".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 61, 'Nnan: "a nêawet baba s fellas; akka ara nexdem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 62, 'Inna i iqeddacen is: "rret selâa nnsen deg icekkaôen nnsen, amar a p âaqlen mara awven ar twacult nnsen, amar a d u$alen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 63, 'Mi bbwven ar babat sen, nnan: "a babat nne$, igdel fella$ lkil, azen gmat nne$ yidne$, iwakken a d nektil. Nekwni, war ccekk, a nêareb fellas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 64, 'Inna: "day a kwen amne$ fellas, akken i kwen umne$, zik, $ef gma s? Öebbi Yif akw imêaraben. Neppa Iphunu sennig akw iêninen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 65, 'Mi ldin lqecc nnsen, ufan tu$al iten id selâa nnsen. Nnan: "a babat nne$, ur neb$i tagi, selâa nne$ tu$al a$ d. A d nessikrer i twacult nne$, a nêareb $ef gmat nne$, a d nernu ppâabga n ul$wem. Tagi d ppâabga tushilt".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 66, 'Inna: "ur t sedduye$ yidwen, d awez$i, siwa ma tcubkem iyi s Öebbi, ard a yi t id terrem, siwa ma zzin awen". Mi s âahden, inna: "Öebbi d Awkil $ef wayen id nenna".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 67, 'Inna: "a tarwa, ur keççmet si yiwet n tebburt, kecmet si tebbura imgarraden. Ula i wen xedme$, bippa, ar loiha n Öebbi. Aêuddu siwa win n Öebbi. FellaS ppekle$, fellaS ay ppeklen wid ippkalen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 68, 'Mi kecmen akken i sen iumeô babat sen, ula i sen ixdem, bippa, ar loiha n Öebbi. D ayen ilezmen kan i iseyya Yaqub, deg iman is. Neppa, s tidep, isâa tamusni i s Nesselmed, maca tegwti n yimdanen ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 69, 'Mi kecmen ar Yusef, ibbwi gma s $uôes, inna: "nekkini d gma k, ur $webbel $ef wayen xeddmen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 70, 'Mi sen ifka ppâabgat nnsen, irra taqbuct deg ucekkaô n gma s. Sinna, iberreê uberraê: "a yat terkaf, kunwi, war ccekk, d imakwaren"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 71, 'Nnan, u zzin $uôsen: "d acu tesôuêem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 72, 'Nnan: "nesôuê taqbuct ugellid. Win ip id ibbwin, ad as nefk ppâabga n ul$wem. Nek, vemne$ t".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 73, 'Nnan: "s Öebbi, nni$ teéôam ur d nusa ara a nessefsed tamurt, ur nelli d imakwaren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 74, 'Nnan: "d acu ay d aqeîîi s, ma teskadbem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 75, 'Nnan: " aqeîîi n win i p ibbwin di tcekkaôt is, d yiman is. Akka ay nepkafi imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 76, 'Ibda la ipqellib icekkaôen, uqbel win n gma s, sinna, issuffe$ ip id seg ucekkaô n gma s. Akka ay Nefka ticeôkep i Yusef. Ur izmir ad iîîef gma s, s lqanun ugellid, siwa ma Irad Öebbi. Nessalay, tiseddaôin, win i £ihwan. Sennig bu tussna, illa Umusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 77, 'Nnan: "ma iuker, ni$ iuker, zik, yiwen n watma s". Iffer ip Yusef $uôes, ur asen p id inna ara. Inna: "aql akwen deg yir êala. Öebbi Yif akw akken Iéôa ayen d teqqaôem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 78, 'Nnan: "a yameqwôan, baba s, s tidep, wesser. Eîîef yiwen segne$ deg umekkan is. Nwala k, ih, telliv si lâuûam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 79, 'Inna: "ur a$ Iâammed Öebbi a neîîef, siwa win u$uô nufa ta$awsa nne$. Mulac, war ccekk, a nili d imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 80, 'Mi uysen segs, mcawaôen, inna umeqwôan segsen: "day ur teéôim ara, ar babat wen tcubkem t s Öebbi, u, zik, tveggâam Yusef? Ihi, ur pôuêu$ si tmurt a, d awez$i, alamma iserreê iyi baba, ne$ Ifra Öebbi felli. Neppa, Yif akw imêaddan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 81, 'U$alet ar babat wen, tinem as: a babat nne$, mmi k, s tidep, iuker. Ncehhed kan $ef wayen neéôa, ur nessawev i tbavnit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 82, 'Steqsi tamdint ideg i nella, akked terkift ukud nedda. Ih, d tidep, ay d nenna".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 83, 'Inna: "xaîi! Lameô seg iman nnwen. Ilha ûûbeô. Amar Öebbi a yi ten id Iawi akw. Neppa, s tidep, d Bab n ûûwab, d Amusnaw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 84, 'Ijuneb iten, u inna: "a lêif iw $ef Yusef"! Allen is ijegger itent u$ilif, innu$ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 85, 'Nnan: "s Öebbi, tezgiv tesmektayev d Yusef, alamma tu$alev d amuvin, ne$ seg wid immuten".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 86, 'Inna: "la pcetki$ kan i Öebbi, s uneémi w akked u$wbel iw. Ssne$, s$uô Öebbi, ayen ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 87, 'A yarraw iw, ôuêet, steqsit $ef Yusef akked gma s. Ur ppayset di tecvaî n Öebbi. Ih, i ippaysen di tecvaî n Öebbi, siwa agdud ijehliyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 88, 'Mi bbwven $uôes, nnan as: "a yameqwôan, nekwni akked twacult nne$, nepwa$. Nusa d s selâa ôxisen, semd as lkil, seddeq a$. Öebbi, s tidep, Ipkafi wid ipseddiqen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 89, 'Inna: "teéôam i tgam i Yusef akked gma s, mi kunwi, d wid ur nessin"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 90, 'Nnan: "keçç, s tidep, maççi d Yusef "? Inna: "nek d Yusef, atan gma. Ni$ I$at a$ Öebbi. Ih, wid ipêezziben, wid iûebbôen ... Öebbi, s tidep, ur Isôuêu arraz iâaôviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 91, 'Nnan: "s Öebbi ar k Ismenyaf Öebbi garane$. Nekwni, s tidep, neccev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 92, 'Inna: "ur telli tiyta degwen, assa. Ad awen Isemmeê Öebbi! Neppa Yif akw wid ipêunun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 93, 'Awit tasedrit iw agi, erret ep $ef udem n baba, ad iêlu yiéôi s. Aset ed $uôi, s twacult nnwen, meôôa".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 94, 'Mi teqlaâ terkift, babat sen ibda la iqqaô: "nek, s tidep, sraêe$ rriêa n Yusef, awi d kan ur teqqaôem ara: la isxeôwiv".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 95, 'Nnan: "s Öebbi, ar k mazal di ttelfan ik n zik".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 96, 'Mi d iusa ubcir, issers as p $ef udem is, llint ed wallen is, inna: "day ur awen nni$ ara: nek ssne$, s$uô Öebbi, ayen ur tessinem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 97, 'Nnan as: "a babat nne$, ssuter ad a$ pwasemmêen ibekkaven nne$. S tidep, nella d imednab".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 98, 'Inna: "deqqal ad ssutre$, i Mass iw, ad awen Isemmeê. Neppa, s tidep, Ipsemmiê, Ipêunu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 99, 'Mi bbwven ar Yusef, isteôêeb s imawlan is. Inna: "kecmet ar Maseô, di laman, ma Irad Öebbi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 100, 'Issuli imawlan is ar usgeld. £lin, knan as. Inna: "a baba! D wagi ay d asefru n targit iw, n zik. Ni$ Issuffe$ ip Mass iw! Ni$ Iga yi leqôaô mi yi d Issuffe$ si lêebs. Ikkes ikwen id si sseêôa, deffir tismin i isker Cciîan, gari d watma. Mass iw, s tidep, d Laîif i win i S ihwan. Ih, Neppa d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 101, 'A Mass iw, ni$ Tefkiv iyi si tgelda, Tesêefvev iyi asefru n temsal. Axellaq n tmurt akked igenwan, Keçç, d Bab iw di ddunit, di laxeôt, Eddem ôôuê iw d amvua, Ssiwev iyi ar wid imaânen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 102, 'Tagi, si teêkayin n tbavnit, Nweêêa yak p in. Ur telliv $uôsen, mi mwafaqen a p andin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 103, 'Tegwti n yimdanen, xas tâapbev, ur ppamnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 104, 'Ur asen ssutur kra n teqdiât. Neppa, d asmekti kan i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 105, 'I illan deg issekniyen di tmurt akked igenwan! La teddun fellasen, maca wexxôen asen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 106, 'Tegwti, segsen, ur ppamnen s Öebbi, siwa ma curken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 107, 'Day ppeklen ur asen isburru yara uâaqeb n Öebbi, ne$ ur ten id ippas ara yimir, deqzalla, ur pfaqan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 108, 'Ini: "wagi d abrid iw, la pnuju$ ar Öebbi ad Ildi allen, i nek akked wid iddan yidi. Gedha s Öebbi! Ur lli$ seg wid ipcaraken".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 109, 'Nuzen ed kan, uqbel ik, irgazen seg imezda$ n temdinin, iwumi Nweêêa. Day ur unagen ara di tmurt, ad walin amek tevôa d wid i ten id izwaren? Ih, pifxiô axxam aneggaru i wid ipêezziben. Day ur tefhimem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 110, 'Alamma, mi uysen imazanen, u meyyzen ar skaddben ten, tusa ten id tallalt s$uône£. Nepsellik win i £ ihwan. Ur ipwakkas ara ssxev nne£, i ugdud ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 111, 'Ni$, di teêkayin nnsen, illa uselmed i yuâqilen. Ur telli d awal id innulfan. Neppat tetebbet ed ay d izwaren, tfeûûel ed yal cci. D nnhaya u d aêunu i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 1, 'Almô. Wigi d issekniyen n Tezmamt. Ayen i k d irsen, s$uô Mass ik, d tidep, maca tegwti n medden ur ppamnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 2, 'Öebbi i Issulin igenwan war tigwejda ara twalim, sinna, Iâannec $ef usgeld. Iêeppem i yiîij d waggur ad ddun, akw, ar lajel ipwassnen. Iseyyi lameô, Ipfeûûil issekniyen, amar a pepputebbtem $ef temlilit d Mass nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 3, 'Neppa i Isswesâen tamurt. Irra degs idurar, isaffen. Irra tayuga di yal ppemôa. Ip$ummu ass s yiv. Deg waya, s tidep, d issekniyen i ugdud ipxemmimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 4, 'Di tmurt, tibêirin tioiratin, leonanat n téuôin, nnaâma, tizdayin, v$an ne$ ur v$in, cerken aman nnsen. Nesmenyaf kra i kra, i wuççi. Deg waya, s tidep, d issekniyen i ugdud ifehmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 5, 'Ma twehmev, issewham ay d qqaôen: "ma nu$al d akal, day fella$, s tidep, lxelq amaynut"? D wigi i inekôen Mass nnsen. Wigi, azaglu $ef tmegôav. Wigi d at tmes, nitni, degs, ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 6, 'Sêaren k ar tucmip, uqbel ise$. Ni$ vôant am tigi, uqbel nnsen. Mass ik, s tidep, $uôeS ssmaê i imdanen deg wayen ccven. Mass ik, s tidep, Iwâaô deg uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 7, 'La qqaôen wid ijehlen: "a lemmer id irs $uôes ussekni, s$uô Mass is". Keçç, d aneddaô kan. I yal agdud, win inehhun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 8, 'Öebbi Iéôa i illan di yal tadist, amek teddun inzikmiren. Yal cci, $uôeS, s lmizan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 9, 'Amusnaw n wayen iffren akked wayen ur neffir. Ameqwôan, Aâlayan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 10, 'Iâuva segwen win i$emven awal, d win it iberêen, win iffren deg iv, d win d ivehôen deg wass.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 11, 'Isâa iâssasen zdat es, deffir es, pêaraben fellas, s lameô n Öebbi. Öebbi, s tidep, ur Ipbeddil i illan deg ugdud, alamma bedlen i illan deg iman nnsen. Ma Irad Öebbi ayen n dir, i ugdud, ur t itekkes yiwen. Ur sâin amâiwen, war Neppa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 12, 'D Neppa i wen d Ippawin lebôaq, degs tugdi, asirem. Isskar ed asigna aéayan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 13, 'Tesbuccuâ aS termegt, s ccekôan, akken lmalayek, seg wakken ugadent eP. Ippazen ed ssiâqat, Ipêaz yisent win i S ihwan. Nitni pnamaren $ef Öebbi. Neppa teqseê tezmert iS.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 14, '£uô Neppa, anuju n tidep. Wid u$uô la pnujun, war Neppa, ur asen d pparan s wacemma. Am win issendin ifassen i waman, ib$a ad awven s imi s, ur ibbwiv ar leb$i s. Anuju ijehliyen ar ttelfan kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 15, 'I Öebbi la kennun wid illan di tmurt akked igenwan, b$an ne$ ugin, akked tili nnsen, taûebêit, tameddit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 16, 'Ini: "anwa ay d Mass n tmurt akked igenwan"? Ini: "d Öebbi. Ihi day a pperrem d iêbiben, war Neppa, wid ur nemlik, i yiman nnsen, aba$uô ne$ vveôô"? Ini: "day iaâdel uder$al akked win ipwalin? Ne$, day âadlent tillas akked tafat? Ne$, rran imcurak i Öebbi, i ixelqen am lxelq iS, ufan t ippemcabi"? Ini: "d Öebbi i Ixelqen yal cci. D Neppa ay d Yiwen, d Aqehhaô".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 17, 'Isse$lay ed aman, seg igenni. Serrun deg $ezôan, s leqdeô nnsen. Acercuô ippawi ikuftan ippifliwen. Ppemcabin ikuftan ar wayen fessin di tmes, iwakken ad ûenâen ôôêuê ne$ dduzan. Akka ay d Isskan Öebbi tidep akked tkerkas. Ihi ikuftan ad ppuveggôen, ma d wayen inefâen medden, a d igwri di tmurt. Akka ay d Ippak Öebbi imedyaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 18, 'Lfayeq i wid ijawben i Mass nnsen. Wid ur aS njaweb ara, xas ad sâun i illan akw di tmurt, berdayen, ur ten id ifeddu. I widak, leêsab adiran. Axxam nnsen d Loahennama. A tanezdu$t tucmip!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 19, 'Day win iéôan ar ayen i k d irsen, s$uô Mass ik, d tidep, am win idre$len? Siwa uâqilen id ismektayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 20, 'Wid iîîfen di laâqed n Öebbi, ur pôuéun nnesba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 21, 'Wid issemlilen ayen id Iumeô Öebbi ad imlil, u ppagwaden Mass nnsen, u ppagwaden aqeîîi adiran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 22, 'Wid iûebôen, ssaramen udem n Mass nnsen, bedden i téallit, pseddiqen seg wayen is iten N$at, s tuffra u âinâni, swexxiôen tucmip s yise$. I nitni, agwav s Axxam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 23, 'Leonanat n Âaden ara kecmen, akked wid ixeddmen ayen ilhan, seg ibabaten nnsen, si tlawin nnsen, si tarwa nnsen. Lmalayek a d ppasent $uôsen si yal tabburt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 24, 'Tifrat fellawen, ilmend n wayen tûebôem! D asaâdi, wagwav s Axxam!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 25, 'Wid ipôuéun laâqed n Öebbi, deffir lemwafaqa s, wid igezmen ayen d Iumeô Öebbi ad imlil, u ssefsaden di tmurt, wigi, i nitni xezzu, i nitni yir axxam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 26, 'Öebbi Issugut ôôeéq i win i S ihwan, u Iwezzen. Taâoeb iten tmeddurt n ddunit. Tameddurt n ddunit, d urar kan, zdat laxeôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 27, 'La qqaôen wid ijehlen: "a lemmer id iris, $uôes, ussekni s$uô Mass is"! Ini: "Öebbi, s tidep, Itellif win i S ihwan. Inehhu $uôeS, wid isteôoiâen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 28, 'wid iumnen, iwumi itheddin wul, mara d mmektin Öebbi". Ni$, s usmekti n Öebbi, pheddinen wulawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 29, 'Ssaâd, akked taggara igerzen, i wid iumnen, ixeddmen ayen ilhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 30, 'Akka ay k id Nuzen, i lois id zwaren leoyus, ad asen temlev, ayen ik d Nweêêa. Nitni jehlen $uô Uênin. Ini: "Neppa d Mass iw, ur illi ôebbi siwa Neppa; ppekle$ fellaS, asteôoaâ iw $uôeS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 31, 'A lemmer kan Leqwôan isselêa idurar, iceqqeq tamurt, ne$ issenîeq ed lmeggtin! Xaîi! Lumuô akw i Öebbi. Day ur éôin ara wid iumnen, ar, ma ihwa yaS, Öebbi ad Inhu medden meôôa? Zgan wid ijehlen a ten tewwet ssixîa, ilmend n wayen xeddmen. Ne$ a ppevôu ar tama n yixxamen nnsen, alamma tusa d lemâahda n Öebbi. Öebbi, s tidep, ur Ipzeggil ppaâud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 32, 'Ni$ mmaâlken, uqbel ik, deg imazanen. Ooi$ lmudda i wid ijehlen, sinna, Ïîfe$ ten. A yaâaqeb iW imiren!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 33, 'Day Win Ibedden, ar yal amdan, $ef wayen ikseb…? Curken aS i Öebbi. Ini: "semmit asen! Ne$, ad aS temlem ayen ur Iéôi di tmurt? Ne$ d ismawen n tkerkas"? Xaîi! Wid ijehlen, âaobent pen nncub nnsen. Ppuveôôfen seg ubrid. Win Itlef Öebbi, ur isâi w ara t inhun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 34, 'Fellasen aâaqeb, di tmeddurt n ddunit. Aâaqeb n laxert, s tidep, aâer. Ur sâin ara ten ifukken, seg ufus n Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 35, 'Amek tga Loennet i ippuweââden i wid iêezzben: ddaw as isaffen ppazzalen, lqut is akked tili s, d imezgiyen. D tagi ay d taggara n wid iêezzben. Taggara ijehliyen, d times.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 36, 'Wid iwumi Nefka Tazmamt, ad feôêen s wayen i k d irsen. Illa wayen ugin kra ikabaren. Ini: "pwamôe$ kan ad âabde$ Öebbi, ur aS pcarake$. Pnuju$ $uôeS, tu$alin iw $uôeS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 37, 'Akka ay t id Nessers, d ûûwab, s taâôabt. Ma teddiv d lhawiyya nnsen, deffir tisin n tussna $uôek, ur k ipfukku bab ne$ asettaô, seg ufus n Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 38, 'Ni$ Nuzen ed imazanen, uqbel ik, Nefka yasen tilawin, tarwa. Ur ippunefk ara i umazan a d iawi assekni siwa ma Iâammed Öebbi. Yal lajel s Tezmamt is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 39, 'Iseffev u Itebbit Öebbi ay S ihwan. £uôeS tayimmap n Tezmamt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 40, 'Ama Nessken ak kra n wayen i sen Nâahed, ama Neddem ôôuê ik, ay fellak kan d isallen, ay fella£ d aqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 41, 'Day ur walan ara Neppas ed ar tmurt, Nessenqas di leryaf is? Öebbi Ipseyyi; yiwen ur ipnamar aseyyi iS. Neppa, Ip$awal di leêsab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 42, 'Ni$ ppandin wid i ten id izwaren. Tiêeôci, akw, ar Öebbi. Iéôa i ikseb yal iman. Ad éôen ijehliyen anwa ara iawven s Axxam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 43, 'Qqaôen wid ijehlen: "ur telliv d amazan". Ini: "ad Iqadd Öebbi d Anagi gari yidwen, akked kra isâan tussna n Tazmamt".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 1, 'Alô. Tazmamt, Nessers ak p id, iwakken a ppessuff$ev imdanen si tillas ar tafat, s wannuf n Mass nnsen, s abrid n Wuzmir, Amaâzuz,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 2, 'Öebbi ilan i illan deg igenwan, i illan di tmurt. A ssxev ijehliyen, ilmend uâaqeb uqsiê,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 3, 'i ismenyafen tameddurt n ddunit wala laxeôt, i iswexxiôen seg ubrid n Öebbi, u ssaramen t d uâwij! Widak, atnan di ttelfan u$miq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 4, 'Ur d Nuzen amazan, siwa s tmeslayt n ugdud is, iwakken ad asen ibeggen. Öebbi Itellif win i S ihwan, Inehhu win i S ihwan. Neppa d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 5, 'Ih, ni$ Nuzen ed Musa, s issekniyen nne£: "ssuffe$ agdud ik, si tillas ar tafat. Mmekti yas d ussan n Öebbi". Deg waya, war ccekk, d issekniyen i yal aûebôi isnemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 6, 'Mi inna Musa i ugdud is: "mmektit ed l$it ikwen I$at Öebbi, mi kwen Isellek si lois n Ferâun, i issuken fellawen lhemm uqsiê. Zellun arrac nnwen, ssidiren tilawin nnwen. Deg waya, s$uô Mass nnwen, d cedda tameqwôaêant".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 7, 'Mi d Inna Mass nnwen: "ma tesnemmrem, ih, ad awen Rnu$. Ma tjehlem, aâaqeb iW, war ccekk, ad iwâaô".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 8, 'Inna Musa: "ma tjehlem, kunwi akked wid n tmurt meôôa, ihi, Öebbi d Asâay, d Amaâzuz".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 9, 'Day ur kwen id ibbwiv ara usali imezwura nnwen: agdud n Nuê, Âad, Tamud, akked wid iten ivefôen? Ur ten issin yiwen, siwa Öebbi. Usan ten id imazanen nnsen, s ubeggen. Rran ifassen nnsen s imawen nnsen, nnan: "S tidep, nejhel ayen i$ef d teppuceggâam. Ih, nekwni di ccekk imcebbwel, $ef wayen u$uô la $ tneccdem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 10, 'Nnan imazanen nnsen: "day illa ccekk di Öebbi, Axellaq n tmurt akked igenwan? Inecced ikwen id, iwakken ad awen Isemmeê kra ibekkaven nnwen, a kwen Ioo ar lajel ipwassnen". Nnan: "kunwi, s tidep, d imdanen kan, am nekwni. Teb$am ad a$ tesîixxôem, seg wayen llan âabden imezwura nne$. Awit a$ d adabu n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 11, 'Nnan asen imazanen nnsen: "nekwni d imdanen kan, am kunwi, maca Öebbi Iteg ccan i win i S ihwan, deg imdanen iS. Ur a$ ippunefk ara ad awen d nawi adabu, siwa s wannuf n Öebbi. £ef Öebbi ara ppeklen lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 12, 'Acu i $ iu$en, ur nepkal ara $ef Öebbi? Ni$ Imla ya$ iberdan nne$; neûbeô, war ccekk, i lmerta i tesâaddam fella$. £ef Öebbi ara ppeklen, at letkal".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 13, 'Nnan wid ijehlen i imazanen nnsen: "war ccekk, a kwen nessuffe$ si tmurt nne$, ne$ a d tu$alem ar ddin nne$". Iweêêa yasen d Mass nnsen: "s tidep, a Nesqucc imednas,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 14, 'd$a, war ccekk, a kwen Nerr d imezda$ n tmurt, deffir sen". Ayagi, i win ippagwaden tilin iW, ippagwaden aberri W.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 15, 'Ssarmen l$elb. Ixseô yal aqehhaô amnafeq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 16, 'Loahennama deffir es, ad ites aman iwexmiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 17, 'Tissit d tije$wimin, ur izmir ad isseblaâ. Tameppant a d teppas si yal tamnaî, neppa ur ipmeppat. Deffir es aâaqeb uqsiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 18, 'Amedya n wid ijehlen, ar Mass nnsen: igiten nnsen am i$i$den i$ef iédem wavu, ass n tbucivant. Ur d ppawin acemma, seg wayen kesben. D wagi ay d ttelfan u$miq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 19, 'Day ur twalav ara, Öebbi Ixleq tamurt akked igenwan, s tidep? Ma ihwa yaS, a kwen Ikkes, a d Iawi lxelq amaynut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 20, 'Ayagi, i Öebbi, ur illi d ayen izzenzafen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 21, 'A d rsen akw zdat Öebbi. Ad inin uôhifen i imzuxiyen: "s tidep, nella nedda yidwen, ma tzemrem ad a$ tsellkem kra, seg uâaqeb n Öebbi"? A d inin: "lemmer i $ Inha Öebbi, yili nwelleh ikwen. Iâuva fella$, neêmeq ne$ neûbeô, ur a$ illi ssôan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 22, 'Mi isuyya lameô, a d yini Cciîan: "Öebbi, d ûûeê, Iweââd awen lemâahda n tidep. Weââde$ awen, $uôe$ kwen. Ur sâi$ adabu fellawen, siwa anecced nnwen. Tu$em awal iw. Ur iyi plummut, lummet iman nnwen. Ur zmire$ a kwen âawne$, ur tezmirem ad iyi tâawnem. Nekôe$ wid iyi tepcarakem, zik. I imednas, s tidep, aâaqeb aqeôêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 23, 'Ad skecmen wid iumnen, ixeddmen ayen ilhan, ar leonanat, ddawat sen isaffen ppazzalen, ad wekkôen dinna, s wannuf n Mass nnsen. Azul nnsen dinna d: "tifrat"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 24, 'Day ur twalav ara, amek id Ifka Öebbi amedya? Awal lâali am ttejôa lâali, iéuôan is ôûan, iferkawen is di tegnewt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 25, 'Teppak ed lfakia s, di yal imir, s wannuf n Mass is. Ippawi d Öebbi imedyaten i imdanen, amar a d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 26, 'Amedya n wawal ucmit, am ttejôa tucmip, teqlaâ sennig wakal, war leqôaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 27, 'Öebbi Itebbit wid iumnen s wawal utebbet, di tmeddurt n ddunit akked laxeôt. Öebbi Itellif imednas. Öebbi Ixeddem ayen i S ihwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 28, 'Day ur twalav ara wid ineûfen l$it n Öebbi, s tijehli? Ssersen agdud nnsen deg uxxam n twa$it.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 29, 'Loahennama ad ô$en degs: a yir leqôaô!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 30, 'Gan aS i Öebbi tanudda, iwakken ad telfen seg ubrid iS. Ini: "zzhut! S tidep, leqôaô nnwen d times".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 31, 'Ini i imdanen iW iumnen, ad bedden i téallit, ad seddqen seg wayen iten N$at, s tuffra u âinani, uqbel a d ias wass ideg ur illi ssuq, ur telli tdukli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 32, 'Öebbi i Ixelqen tamurt akked igenwan, id Isse$layen aman seg igenni, Issufu$ ed yissen ppemôa, d ôôeéq i kunwi. Inub fellawen s isaffen, u s lbabuô i iteddun di yill, s lameô iS.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 33, 'Inub fellawen s yiîij d waggur, d imezgiyen. Inub fellawen s yiv akked wass.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 34, 'Ifka yawen seg wayen akw i S tessutrem. Ma pêesbem l$it n Mass nnwen, ur tessawavem. Ih, amdan, s tidep, d amednus, d ajehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 35, 'Mi inna Ibôahim: "a Mass iw! Err tamdint agi d tin n laman, Âatq a$, nek d warraw iw, seg wannuz n tâancuôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 36, 'A Mass iw, nitenti, s tidep, telfent aîas n medden. Win iddan yidi, neppa, s tidep, sgi. Win iyi âuûan, Keçç, s tidep, Tepsemmiêev, Tepêunuv.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 37, 'A Mass nne$! Nek rri$ tanezdu$t, i kra n warraw iw, di te$zut ibuôen, ar Uxxam iK iôqan. A Mass nne$! Iwakken ad bedden i téallit. Err ulawen n kra n medden, ad iêninen $uôsen, £it iten s ppemôat, amar ad snemmren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 38, 'A Mass nne$! Keçç, s tidep, Teéôiv ayen neffer akked wayen nenna. Ur iffir wacemma i Öebbi, di tmurt ne$ deg igenni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 39, 'Ccekôan i Öebbi iyi d Ifkan, di tewser iw, Ismaâil akked Isêaq. Mass iw, s tidep, Issemêas i tnaâôit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 40, 'A Mass iw, Err iyi ad bedde$ i téallit. Akked kra, si tarwa w. A Mass iw, Steôêeb s unuju w.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 41, 'A Mass nne$! Semmeê ane$, nek d lwaldin iw, akked lmumnin, ass ideg ara d ias uqeîîi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 42, 'Ur p$ili ar I$fel Öebbi, $ef wayen xeddmen imednas. Iooa ten kan, ar ass ideg ara beêêren allen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 43, 'Ad p$awalen, iqweôôa ff$en d, allen ur ferzent, ulawen d ilmawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 44, 'Nabi imdanen af wass ideg ara ten id yas uâaqeb. Ad inin wid idensen: "a Mass nne$! Efk ane$ lmudda wezzilen, a d njaweb i unabi K, a neddu d imazanen". "Day ur teggulem ara kunwi, zik, ar ur tep$abem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 45, 'Tzed$em ixxamen n wid ivuôôen iman nnsen. U Nbeggen awen d amek i sen Nga, u Nefka yawen d imedyaten".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 46, 'Ni$ undin ccbukat nnsen. Ccbukat nnsen haatent ar Öebbi, xas ma ccbukat nnsen d tid ara isse$lin idurar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 47, '£uôek a p$ilev Öebbi ad Izgel lemâahda S, i imazanen. S tidep, Öebbi d Uzmir, Ippara d ppaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 48, 'Ass ideg tamurt a ppu$al maççi d tamurt; akken igenwan; a d asen ar Öebbi Yiwen, Aqehhaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 49, 'A pwaliv, assen, ibe$wviyen pwaqqnen wa $er wa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 50, 'Lebsa nnsen d qevôan, times t$umm udmawen nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 51, 'Iwakken ad Ikafi Öebbi yal amdan, $ef wayen ikseb. Öebbi, s tidep, Ip$awal di leêsab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 52, 'Wagi d anecced i imdanen, ad pwanedôen yis, ad éôen ar siwa Neppa ay d Öebbi Yiwen, a d mmektin uâqilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 1, 'Alô. Wigi d issekniyen n Tezmamt, u d Leqwôan ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 2, 'Ahat wid ijehlen ssaramen ad ilin d imvuâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 3, 'Eoo iten ad ççen, ad zhun, a ten issedhu usirem. Deqqal ad éôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 4, 'Ur Nesquccu tamdint, siwa ma d ayen i s iuran, ipwassnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 5, 'Ur illi lois ara d isqeôben, ne$ ara iswexxôen lajel is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 6, 'Nnan: "a win u$uô d irs usmekti! Keçç, war ccekk, d aôehbani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 7, 'Acimi ur a$ d tusiv ara, s lmalayek, ma d tidep ay tessawalev"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 8, 'Ur Nesrusu lmalayek, siwa s tidep. Imiren, ur pganin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 9, 'Ih, Nekwni Nessers ed asmekti. Ih, Nekwni a Nêareb fellas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 10, 'Ni$ Nuzen ed, uqbel ik, i ikabaren imezwura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 11, 'Ur ten id ippas umazan, mebla ma ttahan fellas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 12, 'Akka ay t Nessekcam deg ulawen ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 13, 'Ur uminen yis, ulamma ooan d imezwura tannumi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 14, 'Xas ad asen Nelli tabburt igenni, ad ppalin $uôes,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 15, 'a d inin, war ccekk: "ittules iéôi nne$, ne$ nekwni d agdud iwumi sseêren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 16, 'Ni$ Nerra itran deg igenni. Ncebbeê iten i wid ipmuqulen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 17, 'Nesdari ten, si yal cciîan imenfi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 18, 'Kkes ed win d issemêessen s tufra, A p iddu, fellas, ujajiê n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 19, 'Tamurt Nessewsaâ p; Nerra fellas idurar; Nessem$i d, degs, yal cci, s lmizan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 20, 'Nerra, degs, lqut i kunwi, akw i wid ur tecceççayem ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 21, 'Lexzayen n yal cci, $uône£ kan. Siwa s lkil ipwassnen i ten id Nesrusu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 22, 'Nuzen ed avu isswayen. Nesse$li d aman seg igenni, yissen Nessew ikwen. Ur llin ara lexzayen is $uôwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 23, 'Ih, d Nekwni i Issidiren, i Ineqqen. D Nekwni ay d Iweôôaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 24, 'Ni$ Nessen imezwura nnwen, Nessen ineggura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 25, 'Ih, Mass ik, Neppa, a ten id Ifser. Ih, Neppa, d Bab n ûûwab, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 26, 'Ni$ Nexleq amdan si talaxt taberkant i meslen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 27, 'Nexleq loenn, iu$ lêal, si tmes n ccili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 28, 'Mi Inna Mass ik, i lmalayek: "Nek Xelqe$ amdan, si talaxt taberkant i meslen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 29, 'Mi t Mesle$, u Üûuve$ as si ôôuê iW, ersemt $uôes, knumt".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 30, 'Knant akw lmalayek, akken ma llant,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 31, 'siwa Iblis, iugi ad yili ar wid iknan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 32, 'Inna: "a yIblis, acu ik iu$en, ur telliv ar wid iknan"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 33, 'Inna: "ur kennu$ i umdan, i Txelqev si talaxt taberkant i meslen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 34, 'Inna: "effe$ segs! Aql ak, ihi, d imenfi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 35, 'Ih, fellak ddell alamma d ass uqeîîi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 36, 'Inna: "a Mass iw! Eoo iyi alamma d ass n tnekra nnsen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 37, 'Inna: "ih, keçç seg wid ipganin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 38, 'ar ass n yiùmir ipwassnen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 39, 'Inna: "a Mass iw! Imi yi Terriv d a$ewway, war ccekk, ad asen cebbêe$ ddunit, a ten $ewwu$, akken ma llan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 40, 'Kkes ed imdanen iK izedganen garasen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 41, 'Inna: "$uôI, wagi d abrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 42, 'War ccekk, ur tesâiv adabu $ef imdanen iW, siwa wid i k ivefôen seg imjaêen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 43, 'Loahennama, s tidep, d ppaâud nnsen akw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 44, 'D m ûa tebbura; ar yal tabburt, s urbaâ ines.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 45, 'Ih, wid ipêezziben, di leonanat akked tliwa:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 46, 'kecmet pen di tifrat, akked laman"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 47, 'Nekkes i illan d dd$el, deg idmaren nnsen. D atmaten, deg imîeôêen, mqabalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 48, 'Ur âaggun degsen, ur ten id ssuffu$en segsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 49, 'Xebbeô ixdimen iW; Nek, s tidep, Psemmiêe$, Pêunu$.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 50, 'U aâaqeb iW d aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 51, 'Xebbeô iten $ef inebgawen n Ibôahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 52, 'Mi kecmen $uôes, nnan: "tifrat"! Inna: "s tidep, nugad ikwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 53, 'Nnan: "ur ppagwad, a k nbecceô kan, s uqcic amusnaw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 54, 'Inna: "tbecceôm iyi d, mi wessre$. Acu iyi d tbeccôem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 55, 'Nnan: "Nbecceô ik id, s tidep, ur ppili seg wid iuysen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 56, 'Inna: "anwa iuysen aêunu n Mass is, siwa im$eôôqen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 57, 'Inna: "d acu ay d lmeqsud nnwen, a yimceggâen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 58, 'Nnan: "Nekwni, s tidep, neppuceggaâ d s agdud ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 59, 'Kkes ed tawacult n Luî, ara nsellek akw,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 60, 'siwa tameîîut is. Ih, Nseyya a ppili, neppat, seg ineggura".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 61, 'Mi ôuêen imceggâen ar twacult n Luî,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 62, 'inna: "kunwi, s tidep, d imdanen ur nessin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 63, 'Nnan: "xaîi, Nusa d, $uôek, s wayen rran di ccekk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 64, 'Nusa d, $uôek, s tidep. Nekwni, war ccekk, nessawal tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 65, 'Öuê akked twacult ik, mi mazal yiv. Ddu deffir sen. Ur d itezzi yiwen degwen! Âaddit anda i wen ippunefk lameô".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 66, 'Nseyya yas lameô agi: a d gwrin ad pwagezmen wakali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 67, 'Usan d, imezda$ n temdint, feôêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 68, 'Inna: "wigi, s tidep, d inebgawen iw, ur iyi cmmatet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 69, 'Ëezbet i Öebbi, ur iyi sdullut"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 70, 'Nnan: "day ur ak negdil ara imdanen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 71, 'Inna: "atent an issi, ma taânam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 72, 'S tudert ik, ar ddebdeben si ssekôan nnsen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 73, 'Iwwet iten usu$u, tafrara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 74, 'Nesrewt ip. Nesse$li d fellasen ageffur n yiéôa n talaxt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 75, 'Deg waya, s tidep, d issekniyen i wid issnen ad ssikden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 76, 'Apan, ih, deg ubrid n yal ass.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 77, 'Deg waya, s tidep, d assekni i lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 78, 'Ih, llan At Teégi, war ccekk, d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 79, 'Nerra d ppaô segsen. Ihi, atent an, snat nni, deg ubrid ibanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 80, 'Ni$ At Lêioô skaddben imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 81, 'Nebbwi yasen d issekniyen nne£. Wexxôen asen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 82, 'Llan qqazen ixxamen n laman, deg idurar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 83, 'Iwwet iten usu$u, taûebêit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 84, 'Ulay sen ixdem wayen la keppben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 85, 'Ur Nexliq tamurt, igenwan, akked wayen illan garasen, siwa s tidep. Imir a d ias, war ccekk. Ihi, ssuref s lekyasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 86, 'Ih, Mass ik d Axellaq, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 87, 'Ni$ Nefka yak d ûa i usniles, akked Leqwôan ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 88, 'Ur pmuqul ar wayen is N$at kra n twaculin nnsen. Ur $webbel ilmend nnsen. Zger tacvaî ik $ef lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 89, 'Ini: "nekkini, s tidep, d aneddaô ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 90, 'Akken id Nessers i wid ibvan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 91, 'i irran Leqwôan d iêricen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 92, 'S Mass ik, ard a ten Nesteqsi akw', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 93, '$ef wayen xeddmen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 94, 'Ihi, emdeê ayen i$ef i k ippunefk lameô, îixxeô i imcurak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 95, 'Ih, a k Nqennaâ mgal wid ittihin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 96, 'i irran ôebbi nniven, ar tama n Öebbi. Deqqal ad éôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 97, 'Ni$ Neéôa ar ul ik, keçç, iaâûeô seg wayen qqaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 98, 'Sbuccaâ Mass ik s ccekôan. Ili seg wid ikennun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 99, 'Aâbed Mass ik, ar k id ias utebbet!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 1, 'Ad ias lameô n Öebbi, ur pêirit $uôes. Gedha s yiS! Ay Aâlay, sennig wayen pcaraken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 2, 'Issrusu d lmalayek s ôôuê si lameô iS, $ef win i S ihwan, deg imdanen iS: "Nedôet ar ur illi ôebbi siwa Nek. Ihi, êezzbet iyI".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 3, 'Ixleq tamurt akked igenwan, s tidep. Ay Aâlay sennig wayen pcaraken!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 4, 'Ixelq ed amdan si tiqqit; atan iu$al aS, d axûim n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 5, 'Ixelq awen d lmal, segsen iceîîiven iêman, aba$uô, u, segsen, teppeppem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 6, 'D ccbaêa nnwen mara ten id terrem, u mara ten teksem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 7, 'Ppawin tiâkkwmin nnwen ar tmurt ur teppawvem, siwa ma tâapbem. Ih, Mass nnwen, war ccekk, d Umâin, d Aênin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 8, 'Iâewdiwen, iserdyan, i$wyal, i rrekba nnwen akked ccbaêa. Ixelleq ayen ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 9, 'D Öebbi i Ippawin d ubrid. Ff$en segs. Ma ihwa yaS, a kwen Inhu meôôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 10, 'D Neppa i wen d Isse$layen aman seg igenni. Segsen tissit nnwen, segsen ttjuô i itepp lmal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 11, 'Isskar awen d yissen nnaâma, azemmur, tizdayin, tiéuôin, akked yal ppemôa. Deg waya, s tidep, assekni i ugdud ipxemmimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 12, 'Inub awen d s yiv akked wass, iîij akked waggur. Itran ppemnuben s lameô iS. Deg waya, s tidep, issekniyen i ugdud ifehmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 13, 'I wen d Ixleq di tmurt, degs initen imgarraden. Deg waya, s tidep, assekni i ugdud ismektayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 14, 'D Neppa i Inuben s yill, iwakken a pteppem, segs, aksum aleqqaq, a d teksem, segs, rrêuê i teppeqqnem. A pwaliv lbabuô ipcerrig it, iwakken a pnadim si lfevl iS, amar a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 15, 'Issers idurar $ef tmurt, ur teppembwiwil yiswen; isaffen, iberdan, amar a ppepwanham;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 16, 'timuliwin: s yitran, nitni pwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 17, 'Day Win Ixelqen am win ur nxelleq? Day ur d tesmektayem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 18, 'Lemmer a pêesbem l$it n Öebbi, ur tezmirem. Ih, Öebbi, war ccekk, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 19, 'Öebbi Iéôa ayen teffrem akked wayen teqqaôem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 20, 'Wid u$uô pnujun, war Öebbi, ur illi wayen xelqen. D nitni i ipwaxelqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 21, 'D lmeggtin ur d imuddiren, ur éôin melmi ara ten id ssekren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 22, 'Öebbi nnwen d Öebbi Yiwen. Wid ur numin ara s laxeôt, d ulawen nnsen i iugin. U nitni pzzuxun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 23, 'War ccekk, Öebbi Iéôa ayen teffren, akked wayen qqaôen. Neppa, s tidep, ur Iêemmel ara imzuxiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 24, 'Ma nnan asen: "d acu id Issers Mass nnwen"? Qqaôen: "d timucuha imezwura".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 25, 'Ad bibben, ass n tnekra, tiâakkwmin nnsen, s pmam nnsent, akked wumur si tâakkwmin n wid telfen, mebla ma faqen. Day maççi dir it wayen bubben?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 26, 'Ih, undin p, wid i ten id izwaren. Öebbi Iaâtad lebni nnsen, si llsas. I$li d ssqef fellasen. Iusa ten id uâaqeb seg wanda ur bnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 27, 'Sinna, ass n tnekra, a ten Idull, ad Yini: "anda ten icriken iW, i$ef temnamarem"? Nnan imawlan n tussna: "war ccekk, ddell akked ddens, assa, $ef ijehliyen', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 28, 'iwumi ddment lmalayek leôwaê, nitni densen iman nnsen". A d ssutren tifrat: "ur nexdim kra n tucmip". Xaîi, Öebbi, s tidep, Iéôa ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 29, 'Kecmet si tebbura, ar Loahennama; degs a pwekkôem. A yicmet uxxam imzuxiyen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 30, 'Ad inin i wid ipêezziben: "d acu id Issers Mass nnwen"? A d inin: "d lxiô". I wid imaânen, ise$ di ddunit agi. Pifxiô, war ccekk, axxam aneggaru. Ay d umâin uxxam n wid ipêezziben!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 31, 'Ad kecmen leonanat n Âaden, ddawat sen isaffen ppazzalen; degsen, i nitni, ayen i sen ihwan. Akka i Ipkafi Öebbi wid ipêezziben,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 32, 'wid iwumi ddment lmalayek leôwaê, nitni maânen, ad asen inint: "tifrat fellawen! Kecmet Loennet, ilmend n wayen txeddmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 33, 'Day a pôaoun kan tisin n lmalayek $uôsen, ne$ a d iawev lameô n Mass ik? Akka ay xedmen imezwura nnsen. Ur ten Idnis Öebbi, maca densen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 34, 'D tucmitin xeddmen, i ten iwwten. Izzi yasen wayen i$ef pmmaâliken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 35, 'Nnan wid ipcaraken: "Lemmer i S ihwi i Öebbi, ur naâbed acemma, war Neppa, nekwni akked imezwura nne$. Ur negdel acemma, war ayen Igdel". Akka ay xedmen imezwura nnsen. Day illa wayen iwatan i Umazan, siwa awal ipbegginen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 36, 'Ni$ Nuzen ed amazan i yal lois: "âabdet Öebbi, janbet iôebbiten n tkerkas". Garasen, llan wid Inha Öebbi; garasen, wid i$ef iura ttelfan. Iniget di tmurt, walit amek tevôa d inekkaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 37, 'Xas tôe$wbev $ef nnhaya nnsen, Öebbi, s tidep, ur Inehhu wid Itlef. Ur asen illi usettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 38, 'Ggulen s Öebbi, liman iûeêêan nnsen, ar ur d Ippara ara Öebbi wid immuten. Xaîi, lemâahda fellas d tidep, maca tegwti n medden ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 39, 'Iwakken ad asen d ibeggen ayen i$ef mgarraden, iwakken ad éôen wid ijehlen, ar nitni, war ccekk, llan d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 40, 'Awal nne£ kan, i t$awsa, ma Neb$a p, ad as Nini: "ili"! A ppili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 41, 'Wid iunagen i Öebbi, mbaâd ma pwadensen, a ten Nesserked di ddunit s yise$. Arraz n laxeôt a t i$leb, war ccekk, lemmer éôin', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 42, 'wid iûebôen u ppeklen $ef Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 43, 'Id Nuzen, uqbel ik, siwa irgazen iwumi Nweêêa. Steqsit imawlan usmekti, ma ur teéôim ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 44, 'S ubeggen akked Ihellilen, Nuzen ak d asmekti, iwakken a pbeggnev i medden, ayen i sen d irsen, amar a d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 45, 'Wid iundin tucmitin, aâni $ilen ur Iôemmu ara Öebbi di tmurt, ne$ ur ten id ippawev ara uâaqeb, seg wanda ur bnin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 46, 'Ne$ ur ten id ikkat ara di cce$l nnsen, ur sfunnugen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 47, 'Ne$ ur ten ikkat ara cwiî, cwiî. Ih, Mass nnwen, war ccekk, Issuruf, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 48, 'Day ur walan ara ayen akw Ixleq Öebbi, ippara tili s yeffus, zelmev; tkennu i Öebbi, s wannuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 49, 'I Öebbi ikennu meôôa wayen illan deg igenwan, akked wayen illan di tmurt, imexlaq akked lmalayek. Nitni ur sme$wôen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 50, 'Ppagwaden Mass nnsen, sennig sen, xeddmen ayen i sen ippumôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 51, 'Inna Öebbi: "ur sâut sin iôebbiten. Neppa, d Öebbi Yiwen kan. Ihi, Nek, agwadet iyI".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 52, 'IneS i illan di tmurt akked igenwan. Ddin, ineS i lebda. Day a têezzbem i war Öebbi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 53, 'S$uô Öebbi, ayen akw ikwen i$aten. D$a mi kwen têuza lemveôôa, $uôeS ay tnedhem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 54, 'Sinna, mi wen Ikkes lemveôôa, arbaâ segwen, atnan pcaraken i Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 55, 'Nekôen, akka, i sen Nefka. Zhut, deqqal a ppeéôem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 56, 'La qesden, i wur ssinen, amur seg wayen is iten Neôzeq. S Öebbi, ar fellawen asteqsi, $ef wayen id tesnulfuyem!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 57, 'Gern aS d, i Öebbi, tullas. Gedha s yiS! I nitni, ayen ssarmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 58, 'Ma becceôn yiwen s teqcict, ad yibrik wudem is, ad iqbeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 59, 'Ad iveôôef iman is, si medden, ilmend n yir usali it id ibbwven. A p ijmaâ, tamara, ne$ a p irr seddaw wakal? Ay dir wamek debbiôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 60, 'I wid ur numin ara s laxert: amedya ucmit. I Öebbi: amedya aâlayen mavi. Neppa d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 61, 'Öebbi, lemmer Ipqissi medden, $ef ddens nnsen, ur d Ippaoa, degs, amexluq. Maca, Iswexxiô iten ar lajel ipwassnen. Ma iusa d lajel nnsen, ur t swexxiôen, ur t id seqôaben, s ssaâa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 62, 'Garen aS d, i Öebbi, ayen keôhen. Skaddben yilsawen nnsen, mi qqaôen ar ayen ilhan, nnsen. Ay nnsen, war ccekk, d times. Ih, nitni ad zwiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 63, 'S Öebbi, ni$ Nuzen ed, i leoyus, uqbel ik. Cciîan icebbeê asen igiten nnsen. Assa, d bab nnsen. I nitni, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 64, 'Nessader ak edTazmamt, iwakken kan ad asen tbeggnev ayen i$ef mgarraden, akw i nnhaya akked uêunu i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 65, 'Öebbi Isse$li d aman, seg igenni. Issader yissen akal, deffir tmeppant is. Deg waya, s tidep, assekni i ugdud isellen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 66, 'Ih, ameyyez, i kunwi, di lmal. Nesswa kwen s wayen illan deg ufwad nnsen, ger lfert d idamen, i$i iûfan, aéidan i wid itessen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 67, 'Si ppemôa n tezdayin akked tfeôôant, teppawim d ayen iûûekôen, akked ôôezq igerzen. Deg waya, s tidep, assekni i ugdud ifehmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 68, 'Iweêêa Mass ik i tzizwa: "gemt ixxamen deg durar, di ttjuô, di te$wôasin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 69, 'Sinna, eççemt si yal ppemôa. Ddumt s wannuz, iberdan n Mass nnkwent. Iteffe$ ed seg iâabbav nnsent ayen tessen, n yal ini, degs êellu i imdanen". Deg waya, s tidep, assekni i ugdud ipxemmimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 70, 'Ixelq ikwen Öebbi, sinna, ad awen Iddem ôôuê. Kra, segwen, ad ccerfeffen mavi, alamma ur ppissinen acemma mbaâd ma ssnen. Ih, Öebbi d Amusnaw, d Aêernuk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 71, 'Öebbi Ismenyaf ad I$it kra i wiyav. Wid Ismenyaf, ur ilaq ara ad rren, ôôeéq nnsen, i waklan nnsen, d$a ad âadlen yidsen. Day ara nekôen l$it n Öebbi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 72, 'Iga yawen Öebbi, seg iman nnwen, tilawin nnwen. Ifka yawen, si tlawin nnwen, arraw d warraw n warraw. Iôeéq ikwen s wayen ilhan. Day ad amnen di tkerkas, ad nekôen l$it n Öebbi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 73, 'Âabden, war Öebbi, wid ur nesâi acemma, swayes ara ten ôeéqen, si tmurt akked igenwan, u ur zmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 74, 'Ur d ppawit imedyaten i Öebbi. Ih, Öebbi Issen, kunwi ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 75, 'Ifka d Öebbi amedya n wakli, d ayla, ur izmir i wacemma, akked yiwen iwumi Nefka, s $uône£, ôôeéq ilhan. Ipseddiq, segs, s tuffra ne$ âinani. Day âadlen? Ccekôan i Öebbi. Maca, tegwti, segsen, ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 76, 'Ifka d Öebbi amedya n sin irgazen. Yiwen d agugam, ur izmir i wacemma. D taâkkwemt i bab is. Anda it iuzen, ur d ippawi lxiô. Day iaâdel akked win ippamôen lêeqq, u neppa deg ubrid uwqim?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 77, 'N Öebbi tabavnit n tmurt akked igenwan. Lameô n yimir, am unqaj n tiî kan, ne$ ur ibbwiv. Ih, Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 78, 'Öebbi Issuffe$ ikwen id si tâabbav n tyimmatin nnwen, ur tessinem acemma. Ifka yawen timejjin, iéôi, ul, amar a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 79, 'Day ur walan ara ifôax, têeppem fellasen lhawa igenni, ur ten iîîif yiwen siwa Öebbi? Deg waya, s tidep, issekniyen i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 80, 'Öebbi Irra yawen ixxamen nnwen d tanezdu$t. Irra yawen ixxamen, s igwelman n lmal nnwen. Fessusit, ass n yinig, d wass uqeggel. Taduî nnsen, ccâaô nnsen, inéaden nnsen, i leêwal akked dduzan, tallit kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 81, 'Deg wayen Ixleq, Öebbi Ifka yawen d tili. Irra yawen, deg idurar, ûûôanat. Ifka yawen iceîîiven i kwen isdarayen seg u$amac, iceîîiven i kwen ipfukkun si lbe$wv nnwen. Akka, ad awen Itim l$it iS. Amar a ppanzem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 82, 'Ma wexxôen, i illan fellak, siwa awal ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 83, 'Âaqlen l$it n Öebbi, sinna, nekôen t. Tegwti, degsen, d ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 84, 'Ass ideg ara d Nessker, si yal lois, anagi, imiren ur ippili tesriê i wid ijehlen, u nitni ur ste$fiôen', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 85, 'Mi walan, imednas, aâaqeb, ur ippifsus fellasen, ur ppestaâfun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 86, 'Mi walan, wid ipcaraken, wid curken, ad inin: "a Mass nne$! D wigi i d icriken nne$ u$uô nepnuju, war Keçç". Ad asen d rren: "kunwi, war ccekk, d ikeddaben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 87, 'Assen, ad fken mayna i Öebbi. Itelf iten wayen d snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 88, 'Wid ijehlen, u sîixxiôen seg ubrid n Öebbi, Nerna yasen aâaqeb sennig wayev, ilmend n wayen ssefsaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 89, 'Ass ideg ara d Nessker, i yal lois, anagi segsen, fellasen, a k id Nawi d anagi mgal wigi. Nessers ak d Tazmamt, d abeggen n yal cci, d nnhaya, d aêunu, u d abecceô i imvuâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 90, 'Ih, Öebbi Iumeô ed lêeqq, akked lewqama, talalt i llzem. Igdel tucmitin, ayen n dir, ddeôk. A kwen Ipnabi, amar a d temmektim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 91, 'Eîîfet di lemâahda n Öebbi ma tâahdem. Ur êentet di tgallit ma tetebbtem, u tcubkem Öebbi. Ih, Öebbi Iéôa acu txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 92, 'Ur cebbut tin ifsin lxiv is, mbaâd ma tcudd it, s loehd. Tepparam tagallit nnwen i umkellex garawen: ad ikk lois sennig wayev. Öebbi Ipjeôôib ikwen kan, yis. War ccekk, ad awen Ibeggen, ass n tnekra, ayen i$ef temgarradem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 93, 'Lemmer i S ihwi, i Öebbi, a kwen Irr d yiwen n lois. Maca, Itellif win i S ihwan, Inehhu win i S ihwan. S tidep, a ppepusteqsim $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 94, 'Ur pparat tagallit nnwen i umkellex garawen. Ad iccev uvaô mbaâd ma iîîef. A pjeôbem tawa$it, ilmend n wayen tveôôfem seg ubrid n Öebbi. I kunwi, aâaqeb abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 95, 'Ur ppa$et s lemâahda n Öebbi ayen ôxisen. Ih, yif it i kunwi wayen illan $eô Öebbi, lemmer teéôim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 96, 'Ayen illan $uôwen, ad ifukk; ayen illan $eô Öebbi, ad idum. War ccekk, a Nkafi wid iûebôen, s wazal n wayen xeddmen ifuqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 97, 'Wid ixeddmen ayen ilhan, d ddkeô ne$ d nnta, u umnen, a ten Nessider di tmeddurt tumâint, a ten Nkafi s wazal n wayen xeddmen ifuqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 98, 'Mara te$ôev Leqwôan, ssuter a k Iaâteq Öebbi, si Cciîan imenfi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 99, 'Neppa, s tidep, ur isâi adabu $ef wid iumnen, i ippeklen $ef Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 100, 'Adabu ines, $ef wid kan i t irran d bab, d wid i S ipcaraken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 101, 'Ma Nbeddel assekni s ussekni, u Öebbi Yif akw akken Issen ayen id Issers, a d inin: "keçç, d win kan id isnulfuyen". Xaîi! Tegwti, degsen, ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 102, 'Ini: "Issers it id ôôuê iôqan, s$uô Mass ik, s tidep, iwakken ad itebbet wid iumnen; d nnhaya u d abecceô i imvuâen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 103, 'Ih, Neéôa, qqaôen: "d amdan kan it isselmaden". Tameslayt n win d gren, d tabeôôanit, wagi d awal aâôab n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 104, 'Ih, wid ur numin ara s issekniyen n Öebbi, ur ten Inehhu Öebbi. I nitni, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 105, 'Ih, gren d kan tikerkas, wid ur numin ara s issekniyen n Öebbi. Widak, d nitni ay d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 106, 'Win inekôen Öebbi, deffir liman is, siwa ma êeppmen fellas, u ul is izga iumen…. Ma d wid illin idmaren nnsen, ar tijehli, ad Izâaf Öebbi fellasen. Fellasen aâaqeb abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 107, 'Ayagi, acku smenyafen tameddurt n ddunit i laxeôt. Ih, Öebbi ur Inehhu agdud ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 108, 'D wigi iwumi Isle$ Öebbi ulawen nnsen, timejjin nnsen, iéôi nnsen. Wigi d i$efliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 109, 'War ccekk, nitni, di laxeôt, ad ilin d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 110, 'Sinna, Mass ik, s tidep, i wid iunagen mbaâd ma thewwlen, sinna juhden, ûebôen; ih, Mass ik, deffir waya, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 111, 'Ass ideg ara d ias, yal yiwen, ad inamer $ef yiman is, u yal yiwen ad iîîukafi $ef wayen ixdem, nitni ur pwadensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 112, 'Ifka d Öebbi amedya n temdint, i illan di laman u îîmana. Ippas ip id ôôeéq is, s lufa, si yal tama. Tenkeô l$it n Öebbi. Isukk Öebbi fellas tawa$it n llaé akked lweêc, ilmend n wayen la ûûenâan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 113, 'Ni$ iusa ten id umazan, segsen. Skaddben t, iwwet iten uâaqeb, nitni densen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 114, 'Eççet seg wayen is ikwen I$at Öebbi, i iêellen, i imaânen. Snemmret l$it n Öebbi, ma d Neppa ay tâabdem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 115, 'I yawen Igdel siwa loifa, idim, aksum n yilef, akked wayen id irsen s yisem ur nelli d win n Öebbi. Ma d win terra tmara, ur ijuô, ur inufeq, Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 116, 'Ur qqaôet tikerkas id ppawin ilsawen nnwen: "aya d leêlal, aya d leêôam". A d tegrem tikerkas $ef Öebbi. Wid id iggaren tikerkas $ef Öebbi, ur rebêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 117, 'Drus ara zhun, fellasen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 118, 'I wudayen, Negdel ayen i$ef i k Neêka, iu$ lêal. Ur ten Nednis, maca nitni ddennisen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 119, 'Sinna, Mass ik, i wid ixedmen cceôô, ur ssinen, d$a steôoâen deffir waya, u sweqmen, Mass ik, war ccekk, deffir waya, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 120, 'Ibôahim, ih, d amdan i imalen ar tidep, i iunzen i Öebbi. Ur illi seg imcurak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 121, 'Isnemmar l$it iS. Ifren it u Inha t s abrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 122, 'Nefka yas di ddunit ise$, u, di laxeôt, neppa, s tidep, ad yili seg izedganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 123, 'Sinna, Nweêêa yak d a ppedduv d ddin n Ibôahim, i imalen ar tidep. Ur illi seg imcurak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 124, 'Ssebt, iu$al kan i wid imgarraden fellas. Ih, Mass ik ad Iêudd garasen, ass n tnekra, $ef wayen llan mgarraden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 125, 'Enced s abrid n Mass ik, s ûûwab akked nnhaya tumâint. Mmeslay iten, s yiles aéidan mavi. Ih, Mass ik Yif akw akken Issen, anwi i iff$en seg ubrid iS. Neppa Yif akw akken Issen, anwi i ipwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 126, 'Ma tâaqbem, âaqbet akken teppuâaqbem. Ma tûebôem, yif it i iûebôiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 127, 'Eûbeô. Üûebô ik s Öebbi kan. Ur $webben ilmend nnsen, ur pveyyiq si tcengal nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 128, 'Ih, Öebbi Atan ar wid ipêezziben, akked wid issewqamen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 1, 'Gedha s Win Ibbwin amdan iS, d iminig n yiv, si Loamaâ n Lêaôam, ar Loamaâ ibaâden mavi, ideg Neôqa i as d izzin, iwakken ad as Nessken, seg issekniyen nne£. Ih, Neppa, d Win Isellen, Ipwalin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 2, 'Nefka Tazmamt i Musa, u Nerra p d nnhaya i At Isôail. "Ur sâut awkil, war Nek".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 3, 'D tarwa n wid i Nebbwi akked Nuê. Neppa, s tidep, d amdan isnemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 4, 'Nsseyya di Tezmamt, i At Isôail: "war ccekk, a ppesfesdem, di tmurt, berdayen, u aîas ara tesme$wôem iman nnwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 5, 'Mi d iusa usefsed amenzu segsen, Nuzen awen d imdanen nne£, s loehd uqsiê, kecmen ixxamen; lemâahda tevôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 6, 'Sinna, Nerra d ppaô nnwen, segsen. Nebbwi yawen d ayla, tarwa. Nesîuqqet iâsekôiwen nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 7, 'Ma tmaânem, i iman nnwen, ma tdensem, i iman nnwen. Mi d tusa lemâahda taneggarut, ssexven udmawen nnwen, kecmen Loamaâ, akken i t kecmen abrid amenzu; hudden, wakali, ayen is ipzuxxun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 8, 'Ahat Mass nnwen ad Iêun fellawen. Ma tulsem, a Nales. Nerra Loahennama d lêebs i ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 9, 'Ih, Leqwôan agi inehhu ar wayen iweqmen mavi, ibecceô lmumnin i ixeddmen ayen ilhan, ar i nitni akafi meqqwôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 10, 'Wanag wid ur numin ara s laxeôt, Nhegga yasen d aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 11, 'Amdan issawal i cceôô, akken issawal i lxiô. Amdan izga d aêemmaq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 12, 'Nerra, iv akked wass, d sin issekniyen. Assekni n yiv Nerra d tellis, Nerra win n wass d win ipwalin, iwakken a pnadim lfevl n Mass nnwen, a ppissinem amvan iseggwasen, akked leêsab. Yal ta$awsa, Nfeûûel ip akken iwata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 13, 'I yal amdan, Ncudd as lbext is s amgarv is. Ass n tnekra, ad as d Nessuffe$ tazmamt ara iaf teldi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 14, '"£eô tazmamt ik! Tqaddev, assa, s yiman ik, i uqeîîi k".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 15, 'Win ipwanhan, i iman is kan, win innetlafen, innetlaf mgal iman is kan. Ur ipbibbi yiwen taâkkwemt n wayev. Ur Nekkat, alamma Nuzen amazan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 16, 'Ma Neb$a a Nesqucc tamdint, Neppak lameô i isâiyen is, ad xedmen, degs, cceôô. Ad iâaddi fellas Wawal, a p Nhudd wakali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 17, 'Acêal n tsuta ay Nesqucc, deffir Nuê! Ad Iqadd Mass ik, i tussna akked tmeéôiwt ibekkaven n imdanen iS.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 18, 'Win ib$an taêemmaqt, Nezzazzal as degs, i £ ihwan, i win i £ Neb$a. Sinna, Nerra yas Loahennama ad din iô$, indell, ippuveggeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 19, 'Win ib$an laxeôt, iaâzem fellas yal laâzem, u neppa iumen; widak, tajmilt i laâzem nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 20, 'I akw, i wigi d wiyav, Nwessaâ tikci s$uô Mass ik. Tikci n Mass ik, ur meêdudet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 21, 'Wali amek Nesmenyaf kra i wiyav. War ccekk, di laxeôt, lfeôq d usmenyef, ad ilin sennig waya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 22, 'Ur sâu, ar tama n Öebbi, ôebbi nniven, mulac a ppu$alev d imdelli, d imveggaâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 23, 'Iseyya d Mass ik: ur tâabdem siwa Neppa, elhut ar imawlan. Ma, $uôek wesser yiwen, ne$ ma wessren i sin, ur asen qqaô: "ttfuh"! Ur ten ppara. Mmeslay asen s lkyasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 24, 'Zger fellasen tacvat n lmaênana. Ini: "a Mass iw! Ëun fellasen, akken iyi d ssekren d amejtuê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 25, 'Mass nnwen Yif akw akken Issen, i illan deg iman nnwen. Ma telham, Neppa, s tidep, Ipsemmiê wid isteôoiâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 26, 'Efk i llezm ik amur is, akw i ume$bun akked win d ibbwi ubrid. Ur pjeggiê d ajeggeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 27, 'Ijeggaêen, s tidep, d atmaten n Cciîan. Cciîan ijhel ar Mass is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 28, 'Ma tfuôqev ten, tôe$bev u tegguniv aêunu s$uô Mass ik, ini yasen awal aéidan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 29, 'Ur pcuddu afus ik ar yiri k, ur as berru aîas, mulac a ppu$alev d ambaûi, d ame$bun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 30, 'S tidep, Mass ik I$ennu win i S ihwan, u Iwezzen. Neppa, s tidep, Ipwali, Issen imdanen iS.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 31, 'Ur Neqqet arraw nnwen, ma tugadem tiggulelt. D Nekwni ara ten Iôezqen, kunwi yidsen. Ih, timen$iwt nnsen d tucmip meqqwôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 32, 'Ur zennut, d ayen n dir, d abrid ucmit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 33, 'Ur neqqet amdan i wen Igdel Öebbi, siwa ma di tidep. Win ipwan$an s le$deô, ihi, a Nefk adabu i walag is. Ur ipjuôôu di tmen$iwt, ihi, neppa, ad ippusellek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 34, 'Ur pnalet ayla ugujil, siwa ar wayen imaânen, ar d immeêtel. Qadôet lemâahda; ih, lemâahda s usteqsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 35, 'Qadôet lkil ma tektalem, weznet s lmizan imaânen. Yif it wakka, a ppelhu taggara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 36, 'Ur îîafaô ayen ur tessinev. Timejjin, iéôi, ul, s tidep, ad ppuseqsin akw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 37, 'Ur teddu di tmurt, d amzuxxi. Ih, keçç ur tezmirev, d awez$i, a pneqôev tamurt, ne$ a ppessiwvev laâli idurar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 38, 'Adiran, deg waya akw, Ikerh it Mass ik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 39, 'Ayagi, seg wayen i k Iweêêa Mass ik, n ûûwab. Ur ppara, ar tama n Öebbi, ôebbi nniven, mulac a ppepwaveggôev ar Loahennama d ambaûi, d amnafeq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 40, 'Day wen d Ifren Mass nnwen arrac, u Iddem, i iman iS, tullas, si lmalayek? S tidep, kunwi tegrem d awal anecilat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 41, 'Ih, ay d Nebbwi di Leqwôan agi, iwakken a d mmektin. I yasen d irna, siwa a$unfu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 42, 'Ini: "lemmer llin yides iôebbiten, akken la d qqaôen, yili ad nadin abrid ara ten iawin ar n Bab n usgeld".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 43, 'Gedha s yiS, aîas i Aâlay sennig wayen d qqaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 44, 'Ppanzen aS igenwan di ûa, tamurt, u wayen illan degsen. Ur illi wayen ur aS neppanez, ur T Nesbuccuâ s ccekôan. Maca, ur tfehmem ara annuz nnsen. Ih, Neppa Iêellem, Ipsemmiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 45, 'Mara teqqaôev Leqwôan, Neppara, garak d wid ur numin ara s laxeôt, aêurrim abavni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 46, 'Nerra $ef ulawen nnsen ssteô, iwakken ur t fehmen; di tmejjin nnsen, tiâéegt. Ma tesmektiv d, di Leqwôan, Mass ik d Yiwen, ad zzin akin, s u$unfu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 47, 'Nekwni, Nif akw akken Neéôa, acu iwumi sellen, mara k ssemêasen, mara hedôen, mi qqaôen imednas: "la teppeddum kan d urgaz iwumi sseêren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 48, 'Wali amek i k d bbwin imedyaten. Nnetlafen. Ur zmiren ad afen abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 49, 'Nnan: "day mi nu$al d i$san, d a$webbaô, d ûûeê a d nu$al di lxelq amaynut"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 50, 'Ini: "ilit d azôu ne$ d uzzal,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 51, 'ne$ d lxelq id iusan deg idmaren nnwen". A d inin: "anwa ara a $ d irren"? Ini: "d Win ikwen id Ixelqen, abrid amenzu". Ad huzen iqweôôa nnsen $uôek, ad inin: "melmi ayagi"? Ini: "izmer ad yili iqeôb ed".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 52, 'Ass ideg ara awen d Isiwel, a d tjawbem s ccekôan iS, a p$ilem cwiî kan ay teqqimem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 53, 'Ini i imdanen iw ad inin awal ifuqen. Cciîan, s tidep, isskar ameôéi garasen. Ih, Cciîan d acengu n ûûeê i umdan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 54, 'Mass nnwen Yif akw akken ikwen Issen. Ad Iêun fellawen, ma Ib$a; a kwen Iâaqeb ma Ib$a. Ur k id Nuzen ara d awkil nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 55, 'Mass ik Yif akw akken Iéôa i illan di tmurt akked igenwan. Ni$ Nesmenyaf kra n lambiyya i wiyav. I Dawed Nefka Ihellilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 56, 'Ini: "nujet $eô wid tepkabarem, war Neppa. Ur zmiren ad awen kksen ccqa, ne$ a t bedlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 57, 'Wigi u$uô la pnujun, la pqelliben ppawil ara ten isqeôben nezzeh ar Mass nnsen. Ssaramen aêunu S, ppagwaden aâaqeb iS". Ih, aâaqeb n Mass ik, issagwad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 58, 'Ur telli temdint ur Nesquccu, uqbel ass n tnekra, ne$ ur Nâaqeb s leqseê. Ayagi iura di Tezmamt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 59, 'I £ iîîfen $ef uceggaâ issekniyen, d nnkeô nnsen, kan, s$uô imezwura. Nuzen ed tal$wemt i Tamud, d ayen pwalin. Densen p. Ur d Neppazen issekniyen siwa i ussigwed.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 60, 'Mi k Nenna: "Mass ik, s tidep, Izzi i imdanen". Ma dayen i k Nerra teéôiv t, d ahewwel kan i medden. Akken ttejôa tamenâult di Leqwôan. Nessagwad iten. Ay sen d irennu siwa nnfaq ameqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 61, 'Mi Nenna i lmalayek: "knumt i Adem", knant, siwa Iblis. Inna: "day ad knu$ i win Txelqev s talaxt"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 62, 'Inna: "Twalav wagi i Tâuzzev sennig iw, lemmer a yi Teooev, ar ass n tnekra, war ccekk, ad $wu$ tarwa s, siwa ixeîîayen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 63, 'Inna: "Öuê! Wid, segsen, i iddan yidek, ihi, aqeîîi nnwen d Loahennama, d aqeîîi meqqwôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 64, 'Laâaj win iwumi tzemôev, degsen, s ta$wect ik. £ewwes fellasen s imnayen ik, d iterrasen ik. Ecrek yidsen ayla, tarwa. Âahed asen". I yasen iâahed Cciîan, siwa a$uôôu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 65, '" Ma d imdanen iW, ur tesâiv adabu fellasen". Mass ik Iqadd d Awkil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 66, 'Mass nnwen, i wen Isselêayen lbabuô di yill, a pnadim lfevl iS. Ih, Neppa Ipêunu fellawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 67, 'Ma tevôa yidwen lmuûiba di yill, ayen u$uô tepnujum, war Neppa, ittellif. Mi kwen Isellek ar lberr, twexxôem. Amdan izga d lkaraâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 68, 'Day t$ilem ur Ipseggix ara tamurt yiswen, ne$ ur awen d Ippazen ara tabucivant, d$a ur teppafem awkil?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 69, 'Ne$ day t$ilem ur kwen id Ippara ara tikelt nniven, ad awen d Iazen aûeôûaô, a kwen I$mes ilmend n tijehli nnwen, sinna ur teppafem, mgal a£, amalal?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 70, 'Ni$ Nkeyyes tarwa n Adem. Nebbwi ten di lberr, di yill, N$at iten s wayen ilhan, Nesmenyaf iten, nezzeh, i waîas seg wid i Nexleq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 71, 'Ass ideg ara Nenced akw imdanen, s imvebôen nnsen; win id tusa tezmamt is yeffus is, widak ad $ôen tazmamt nnsen, ur pwadensen s tissegnit;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 72, 'win illan d ader$al di tagi, ad yili d ader$al di laxeôt, ad izid di tuff$a n ubrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 73, 'S tidep, qôib i k hewwlen $ef wayen i k d Nweêêa, a d tesnulfuv ayen nniven, mgal a£. D$a, a k rren d aêbib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 74, 'Lemmer ur k Ntebbet ara, qôib tmalev cwiî $uôsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 75, 'Yili ad ak Nesâaddi tudert akked tmeppant, berdayen, sinna, ur teppafev, mgal a£, w ara k isellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 76, 'Ih, qôib i k id srewlen si tmurt, a k id ssuff$en segs. Yili cwiî kan ara d gwrin, deffir ek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 77, 'D tannumi imazanen nne£, id Nuzen, uqbel ik. Ur teppafev ara abeddel, di lâadda nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 78, 'Bedd i téallit mi istu$la yiîij, alamma d tellis n yiv. Leqwôan, tafrara. Ih, Leqwôan, tafrara, isâa inagan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 79, 'Aâwez yis kra n yiv, d nnafila k, amar a k id Irr Mass ik, deg umkan i pcekkiôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 80, 'Ini: "a Mass iw! Ssekcem iyi, anekcum n tidep. Ssuffe$ iyi, tuff$a n tidep. Efk iyi, s$uôeK, adabu ipselliken".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 81, 'Ini: "tusa d tidep, $abent tkerkas. Ih, tikerkas ilaq ad $abent".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 82, 'Nesrusu d, si Leqwôan, ayen illan d êellu akked uêunu i lmumnin. I irennu, i imednas, siwa lexsaôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 83, 'Ma N$at amdan ad iwexxeô, ad iveôôef iman is. Ma iêuza t wugur ad iayes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 84, 'Ini: "yal yiwen ixeddem akken ipwali. Mass nnwen Yif akw akken i Issen anwa i ipwanhan kteô".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 85, 'Steqsan k id $ef ôôuê. Ini: "ôôuê si lameô n Mass iw. Drus kan n tmusni i wen ippunefken".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 86, 'Ma ihwa ya£, a Nekkes ayen i k Nweêêa. D$a ur teppafev, mgal a£, awkil,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 87, 'siwa aêunu s$uô Mass ik. Ih, lfevl iS, i keçç, izga meqqweô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 88, 'Ini: "lemmer ad mlilen imdanen akked leonun, iwakken a d awin am Leqwôan agi, ur d ppawin i t icban, xas mâawanen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 89, 'Ni$ Nefka d i imdanen, di Leqwôan agi, si yal imedyaten. Tegwti n yimdanen ur b$in, siwa tijehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 90, 'Nnan: "ur k neppamen alamma tesfeggvev a$ d a$balu, si tmurt;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 91, 'ne$, tesâiv leonan n tezdayin akked tfeôôant, ideg feggven isaffen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 92, 'ne$, a d tesse$liv igenni d ifeûlan, akken i $ tzuxxev; ne$, a d tasev s Öebbi akked lmalayek, zdat nne$;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 93, 'Ne$ a ppesâuv axxam imzewweq, ne$ a ppaliv s igenni. Ur neppamen, s walluy ik, alamma tessersev ane$ d tazmamt ara n$eô". Ini: "gedha s Mass iw! Day lli$ d ayen nniven, siwa d amdan amazan"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 94, 'I iîîfen imdanen ur uminen, mi ten id tusa nnhaya, mara d inin kan: "Iuzen ed Öebbi amdan d amazan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 95, 'Ini: "lemmer llint, di tmurt, lmalayek, teddunt di laman, yili Nessers asent ed, seg igenni, lmelk amazan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 96, 'Ini: "Iqadd Mass iw d Anagi, gari yidwen. Neppa, s tidep, Ipwali imdanen iS, Issen iten".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 97, 'Win Inha Öebbi, atan idda d ubrid. Wid Itlef, ur asen teppafev imawlan, war Neppa, d awez$i. A ten id Nefser ass n tnekra $ef udmawen nnsen, dre$len, gugmen, âaégen. Axxam nnsen d Loahennama. Mi tenqes tmes, ad asen Nernu ajajiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 98, 'D wagi ay d aqeîîi nnsen, imi nekôen issekniyen nne£, u nnan: "day mi nu$al d i$san, d a$webbaô, a d nu$al di lxelq amaynut"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 99, 'Ne$, day ur walan ara ar Öebbi i Ixelqen tamurt akked igenwan, Izmer a d Ixleq i ten icban? Irra yasen lajel, ur degs ccekk. Ur b$in imednas, siwa tijehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 100, 'Ini: "lemmer tesâim igerrujen uêunu n Mass iw, ur ten tepnalem, a ppagwadem a ten tûeôôfem. Amdan izga d imceêêi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 101, 'Ni$ Nefka, i Musa, tza issekniyen iberrzen. Steqsi At Isôail. Mi d iusa $uôsen, inna yas Ferâun: "a Musa! Nek, wala$, war ccekk, seêêern ak".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 102, 'Inna: "ni$ teéôiv ur d issers yiwen wigi, d tiftilin, siwa Mass n tmurt akked igenwan. Nek, wala$, a Ferâun, war ccekk, tîeêênev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 103, 'Ib$a a ten iééaâ si tmurt, N$emmeq it, akked wid iddan yides, meôôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 104, 'Deffir es, Nenna i At Isôail: "zed$et tamurt. Mi d tusa lemâahda n laxeôt, a kwen id Nawi, d îayfat".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 105, 'Nessers it id s tidep. S tidep, ay d irs. Nuzen ik id, kan, i ubecceô d uneddeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 106, 'Leqwôan Nfeôq it, iwakken a t temlev i medden, s laâqel. Nessader it id, s l$eôv.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 107, 'Ini: "amnet yis, ne$ qqimet". Ih, ma mlan t i wid tebbwev tussna, uqbel is, ad $lin $ef udmawen, knan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 108, 'Ad inin: "gedha s Mass nne$! Tûaô lemâahda n Mass nne$".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 109, 'Ad $lin $ef udmawen s imeîîawen. Ad innerni wannuz nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 110, 'Ini: "nujet $er Öebbi, ne$ nujet $er Uênin. Akken tnujem, ineS ismawen imaânen yifen akw wiyav". Di téallit ik, ur saâlay ûûut ik, ur t ssrusu. Ad isker kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 111, 'Ini: "ccekôan i Öebbi, ur Nesâi aqcic, ur Nesâi acrik di tgelda, ur Nesâi bab mgal asdullu". Ssem$weô iT yal tem$weô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 1, 'Ccekôan i Öebbi, id Issersen Tazmamt, i uxdim iS. Aâwaj, degs, ur Irri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 2, 'Tewqem, iwakken a ppâaggen $ef ssxev uwâiô, s$uôeS; u a pbecceô lmumnin ixeddmen ayen ilhan, ar nnsen warraz igerzen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 3, 'Ad ilin degs, i lebda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 4, 'A ppâaggen i wid innan: "Öebbi Isâa mmi S".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 5, 'Ur illi wayen ssnen fellas; akken, imezwura nnsen. D awal uqbiê id iff$en seg imawen nnsen. D tikerkas kan ay ssawalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 6, 'Ahat a phelkev iman ik, ar loiha nnsen, a p$weblev, imi ur uminen ara s usali agi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 7, 'Ni$ Nerra i illan di tmurt, d ccbaêa ines, iwakken a Néeô menyif iten, ar igiten ilhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 8, 'A Nu$al a Nerr, i illan degs, d akal ibuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 9, 'Ne$ t$ilev d At yifri kan, akked Öaqim, ay d lwehma, ger issekniyen nne£?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 10, 'Mi ssôen iman nnsen ilmeéiyen deg ifri, nnan: "a Mass nne$! Efk ane$ d aêunu s$uôeK; Err a$ lameô nne$ d uûwib".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 11, 'Deg ifri, Nesle$ imeééu$en nnsen, acêal iseggwasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 12, 'Sinna, Nessker iten id, a Néeô anta, ger snat n trebbuyaâ, i iêesben acêal qqimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 13, 'Nekwni, ad ak Neêku, s tidep, taqsiî nnsen. Nitni, ih, d ilmeéiyen, umnen s Mass nnsen. Nerna yasen nnhaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 14, 'Nesseohed ulawen nnsen, mi kren nnan: "Mass nne$ d Mass n tmurt akked igenwan. Ur nepnuju, d awez$i, ar ôebbi, war Neppa, mulac a d nini awal dduni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 15, 'Widak d agdud nne$. Âabden iôebbiten, war Neppa. Ay$eô ur a$ d bbwin, fellasen, adabu n ûûeê? Anwa i idensen sennig win id igren tikerkas $ef Öebbi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 16, 'Mi ten tfuôqem, nitni akked wayen âabden war Öebbi, essôet iman nwen deg ifri. Ad awen Izraâ, Mass nnwen, seg uêunu S. Ad awen Iheggi amwanes i lameô nnwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 17, 'A pwaliv iîij, mi d inqeô, iwexxeô i ifri nnsen, ar yeffus. Mi i$li, ad asen iâaddi $eô zelmev. Nitni, din, di littsaâ. Ayagi seg issekniyen n Öebbi. Win Inha Öebbi, neppa ipwanha; win Itlef, ur isâi, d awez$i, bab ara t inhun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 18, 'Ad as tiniv ukin, nitni îîsen. Ntezzi ten yeffus, zelmev. Aydi nnsen, $ef umnaô, iééel ivaôen is. Lemmer a ten twaliv, ad asen trewlev, si tugdi; a k terkeb, segsen, lefqaâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 19, 'Akka ay ten id Nessenker, iwakken ad mesteqsin. Inna yiwen segsen: "acêal n lweqt ay tesâaddam"? Nnan d: "nesâadda ass ne$ ur ibbwiv wass". Nnan: "Mass nnwen Yif akw akken Izôa ay tesâaddam. Aznet ar temdint, yiwen segwen, s idrimen agi nnwen. Ad iwali anwa lqut iûfan mavi, ad awen d iawi ôôeéq, segs. Ad iêader iman is, iwakken ur awen ipfaq yiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 20, 'Nitni, war ccekk, ma éôan kwen, a kwen ôeomen, ne$ a kwen rren ar ddin nnsen, d$a ur trebêen, d awez$i".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 21, 'Akka ay sen ten Nessken, iwakken ad éôen ar lemâahda n Öebbi d tidep; u, $ef yimir, ur illi ccekk. Mi mqellaân $ef lameô nnsen, nnan: "bnut axxam sennig sen. Mass nnsen Yif akw akken iten Issen". Nnan wid iwumi iâadda wawal, $ef lameô nnsen: "a nerr, ihi, lemqam sennig sen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 22, 'Ad inin: "di krav yidsen, aydi nnsen d wis kué"; u ad inin: "di semus yidsen, aydi nnsen d wis sdis", pqelliben tabavnit. U ad inin: "di ûa yidsen, aydi nnsen d wis îam". Ini: "Mass iw Yif akw akken Iéôa amvan nnsen. Drus kan i t iéôan". Ur pnamar fellasen, siwa $ef wayen id ivehôen. Ur ppesteqsay yiwen fellasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 23, 'Ur qqaô ta$awsa a p xedme$, s tidep, azekka,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 24, 'siwa ma Irad Öebbi. Mmekti d Mass ik, ma teppuv. Ini: "amar ad iyi Inhu Mass iw, ar wayen yifen ayagi di ûûwab".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 25, 'Sâaddan, deg ifri nnsen, krav twinas iseggwasen, rnan tza nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 26, 'Ini: "Öebbi Yif akw akken Iéôa, acêal sâaddan. IneS tabavnit n tmurt akked igenwan. Amek Neppa Ipwali, Isell! Ur sâin bab, war Neppa. Ur Izdukkul yiwen i useyyi S".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 27, 'Mel ayen ik ed ippuweêêan, si Tezmamt n Mass ik. Ur illi ubeddel deg wawal iS. Ur teppafev ssôan, war Neppa, d awez$i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 28, 'Üebbeô iman ik, akked wid ipnujun ar Mass nnsen, taûebêit, tameddit, pnadin udem iS. Ur ten tekkes si ger wallen ik, a pvemâav lefnun n tmeddurt n ddunit. Ur ssemêas i win iwumi Nesse$fel ul is, ar usmekti nne£, i iddan d lhawiyya s, iwumi iffuhri lameô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 29, 'Ini: "tidep s$uô Mass nnwen. Ad iamen win ib$an, ad ijhel win ib$an". Ih, Nhegga d times, i imednas; ad asen zzin iêeoouoa s. Ma ppren d, ad asen ppunefken waman am uzzal ifsin. Ad cwin wudmawen nnsen. A tissit tamcumt, a tanezdu$t tucmip!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 30, 'Ih, wid iumnen, ixeddmen ayen ilhan, s tidep, ur Nveggiâ akafi n win ixedmen ayen ilhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 31, 'I wigi, leonanat n Âaden, ddaw sen isaffen ppazzalen. Ad qqnen, dinna, imeqyasen n ddheb, ad lsen iceîîiven izegzawen n leêrir, êewcen s ddheb. Ad élen, degs, $ef imîeôêen izewwqen. A lebsa lâali, a tanezdu$t tumâint!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 32, 'Awi yasen d amedya n sin irgazen. I yiwen, Nefka snat tebêirin n téuôin, Nezzi yasent tizdayin, Nerra iger garasent.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 33, 'Yal tibêirt teppak ed l$ella s, ur ipxuûûu, segs, wacemma. Nesfeggev asif garasent.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 34, 'I$ellet ed ppemôa. Inna i umdakwel is, mi s immeslay: "$elbe$ k taôkunt, iffe$ k alag".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 35, 'Idens iman is mi ikcem leonan is, inna: "ur cukke$ ara, d awez$i, ad iqucc wayagi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 36, 'Ur cukke$ ara ad yili yimir, u ma bbwve$ ar Mass iw, ard affe$, war ccekk, ayen yifen aya, deg umekkan is".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 37, 'Inna yas umdakwel is, mi s immeslay: "day tnekôev Win ik Ixelqen seg wakal, sinna, si tiqqit, sinna, Imessel ik d argaz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 38, 'Maca, Neppa d Öebbi, Mass iw. Ur pcarake$ yiwen, i Mass iw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 39, 'Lemmer id tenniv, mi tkecmev ar tebêirt ik: akken Irad Öebbi. Ur telli tezmert siwa s$uô Öebbi. Ma twalav iyi d, nek, tifev iyi ayla, tarwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 40, 'Izmer Mass iw ad iyi d Ifk ayen i ifen tibêirt ik. A d Iazen $uôes ssxev, seg igenni, a ppu$al d aêecraruf issiccigen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 41, 'ne$, ad zzren waman is, ur ten teppafev, d awez$i".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 42, 'Tqucc l$ella s. D$a la izeyyeô ifassen is, $ef wayen iseôôef fellas. Tqucc tfeôôant is. Inna: "a yamxix iw, a lemmer ur curke$ yiwen, i Mass iw"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 43, 'Ur as illi urbaâ ara t isellken, war Öebbi. Ur isellek iman is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 44, 'Akka, laânaya s$uô Öebbi, Tidep. Yif akw i ukafi, Yif akw i taggara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 45, 'Awi yasen d amedya n tmeddurt n ddunit. Am aman id Nesse$li seg igenni. Eâluâlen yissen im$an n tmurt. D$a u$alen d asa$uô, issebruzzaâ iten wavu. Ni$ Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 46, 'Ayla akked dderya d ccbaêa n tmeddurt n ddunit. Ar Mass ik, leûlaê idumen ifen ten i ukafi, ifen ten i tmeôoiwt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 47, 'Ass ideg ara Nesselêu idurar, a pwaliv tamurt d aza$aô. A ten Nefser, ur Neppaoa yiwen segsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 48, 'A d rsen zdat Mass ik, d leûfuf: "ni$ tusam a£ d, akken ikwen Nexleq tikelt tamenzut. Irna tetebbtem ar ur awen Neppara ppaâud, d awez$i".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 49, 'Ters ed Tezmamt. A pwaliv ibe$wviyen s uêebbiô, $ef wayen illan degs. Qqaôen: "a yamxix nne$! Acimi tazmamt agi ur teooi ayen meééiyen, u wayen meqqwôen, armi ten teêseb"? Ufan illa wayen xedmen. Mass ik ur Idennis yiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 50, 'Mi Nenna i lmalayek: "knumt i Adem", knant, siwa Iblis. Neppa, si leonun, iaâûa lameô n Mass is. Day a ten terrem, neppa akked tarwa s, d imawlan, war Nek? U nitni d icenga nnwen! D abdil ucmit n imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 51, 'Ur ten Rri$ d inagan n lxelq n tmurt akked igenwan, ne$ n lxelq nnsen. Ur Ïîife$ im$eôôqen d imâiwnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 52, 'Ass ideg ara d Yini: "neccdet wid iyI terram d icriken iW". Ad asen siwlen, ur asen d pparan. Nerra, garasen, asif n twa$it.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 53, 'Ibe$wviyen ad walin times. ÊëËûan ar nitni, degs, ara $lin. Ur ppafen, segs, tisensert.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 54, 'Ni$ Nefka d, di Leqwôan agi, yal amedya, i imdanen. Maca, ipnamar umdan sennig akw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 55, 'D acu i iîîfen imdanen ad amnen, mi ten id tusa nnhaya, u ad ste$fôen Mass nnsen? Ar ten id tas kan, tin ivôan d imezwura, ne$ ar d irs, zdat sen, uâaqeb?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 56, 'Ur Neppazen imazanen, siwa i ubecceô d uneddeô. Wid ijehlen pnamaren, s tkerkas, îîeggiôen yissent tidep. Pmaâliken $ef issekniyen iW, akked wayen i$ef ppunedôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 57, 'Anwa idensen sennig win iwumi d pwafekkôen issekniyen n Mass is, iwexxeô asen, u ippu i ixdem ufus is. Ih, Nerra aêurrim $ef wulawen nnsen, ur t fehhmen; akked tiâéegt deg imeééu$en nnsen. Ma tneccdev ten ar nnhaya, ur pwanhan, d awez$i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 58, 'Mass ik Ipsemmiêen, d Bab uêunu. Lemmer ad Iêud fellasen ilmend n wayen kesben, ad I$iwel ar uâaqeb nnsen. Maca, sâan ppaâud, ur ppafen segs tisensert.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 59, 'Timdinin nni i Nesqucc mi densent, Nga ppaâud i usquccu nnsent.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 60, 'Mi inna Musa i uqeddac is: "ur êebbse$ alamma bbwve$ ar umlili n sin ilellen, xas ad sâaddi$ tallit".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 61, 'Mi bbwven ar umlili nnsen, ppun aslem nnsen. Iu$al ar yill d ilelli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 62, 'Mi zegren, inna i uqeddac is: "awi a$ d imekli nne$, ni$ naâteb deg inig nne$ agi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 63, 'Inna: "ur twalav ara, mi nreyyeê ar teéôut, nek ppu$ en aslem? D Cciîan kan iyi isseppun ur ak nni$. Ibbwi abrid is ar yill, d lwehma"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 64, 'Inna: "d ayagi ay neb$a". D$a u$alen d $ef isurifen nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 65, 'Ufan d amdan seg imdanen nne£, iwumi Nefka aêunu s$uône£. Neslemd as tussna i illan $uône£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 66, 'Inna yas Musa: "Ma ad ddu$ yidek, ad iyi tesêefvev ay tesnev n ûûwab"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 67, 'Inna d: "keçç, s tidep, ur tezmiôev, yidi, a pûebôev.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 68, 'Amek ara tûebôev i wayen i$ef ur tesâiv asali"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 69, 'Inna: "ad iyi tafev, ma Irad Öebbi, d aûebôi. Ur pnaqwame$ lameô ik".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 70, 'Inna: "ma teddiv yidi, ur iyi d steqsay $ef wacemma, alamma smekti$ k id fellas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 71, 'Lêan, armi rekben di lbabuô. Ixeôq it. Inna: "txeôqev t, iwakken ad $evûen l$aci s! Ni$ ayen txedmev d dduni".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 72, 'Inna: "day ur ak nni$ ara, keçç, s tidep, ur tezmiôev, yidi, a pûebôev, d awez$i"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 73, 'Inna: "ur iyi pqasa imi ppu$, ur ssukku lwaâôan $ef lameô iw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 74, 'Lêan, armi d mmugren ileméi. In$a t. Inna: "ten$iv amdan ur nen$i yiwen! Ni$ d ayen idensen ay txedmev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 75, 'Inna: "day ur ak nni$ ara, keçç, s tidep, ur tezmiôev, yidi, a pûebôev, d awez$i"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 76, 'Inna: "ma steqsa$ k $ef t$awsa, deffir ta, ur teddu yidi. Ni$ ssutre$ ak d ssmaê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 77, 'Lêan, armi bbwven ar imezda$ n yiwet n temdint, ssutren asen lqut. Ugin a ten snubgten. Ufan en lêiv, qôib ad i$li. Iûeggem it. Inna: "ma teb$iv, tzemrev a ppepwaxellûev $ef waya".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 78, 'Inna: "Tura a nemfaôaq. Ad ak d fke$ lmaâna n wayen i$ef ur tezmirev a pûebôev, d awez$i".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 79, 'Lbabuô nni, n igellilen i ixedmen di yill. B$i$ a t ôée$, acku yiwen ugellid, deffir sen, itekkes yal lbabuô, s yi$il.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 80, 'Wanag ileméi nni, llan imawlan is d lmumnin. Nugad ad iêeppem fellasen tinufqa, tijehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 81, 'Neb$a ad asen d Irr, Mass nnsen, it yifen: win iûfan, iqeôben nezzeh aêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 82, 'Wanag lêiv, n sin warrac igujilen n temdint. Illa ugerruj seddaw as, i nitni. Babat sen d argaz ilhan. Mass ik Ib$a, ard im$uôen, ara d ssuff$en agerruj nnsen. D aêunu s$uô Mass ik. Ur t xdime$ s lameô iw. D tagi ay d lmaâna n wayen i$ef ur tezmiôev a pûebôev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 83, 'Steqsan k $ef Bu sin wacciwen. Ini: "ad awen d awi$, fellas, asmekti".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 84, 'S tidep, Nefka yas di tmurt, u Nsehhel as iberdan di yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 85, 'Iîîef yiwen n ubrid,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 86, 'armi sanda i$elli yiîij. Iufa i$elli $ef tala ilu$en. Iufa n $uôes agdud. Nenna: "a Bu sin wacciwen, âaqeb iten, ne$ lhu $uôsen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 87, 'Inna: "win idensen a t nâaqeb, sinna, ad iu$al ar Mass is at Iâaqeb aâaqeb unekkaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 88, 'Wanag i win iumnen, ixeddmen ayen ilhan, akafi igerzen. Ad as Nini i isehlen si lameô nne£".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 89, 'Sinna, ilêa d yiwen n ubrid,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 90, 'armi sanda d ineqqeô yiîij. Iufa n ineqqeô ed $ef ugdud, iwumi ur Nefki ar at isdarin segs.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 91, 'Am akka. Ni$ ibbwev a£ d akw usali s.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 92, 'Sinna, idda d yiwen n ubrid,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 93, 'armi ibbwev ger sin iêdiden. Iufa, deffir sen, agdud qôib ur fehhmen awal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 94, 'Nnan: "a Bu sin wacciwen, s tidep, Iaouo akked Maouo la ssefsaden di tmurt. A k nxelleû ma terriv ûûuô garane$ yidsen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 95, 'Inna: "yif it iyi Ifka Mass iw. Efket iyi afus, ad rre$ ûûuô garawen yidsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 96, 'Awit iyi d tiqaùmtin n wuzzal alamma irgel wayen illan ger idurar". Inna: "ûuvet alamma tekker degs tmes. Awit iyi d ad smire$ fellas nnêas ifsin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 97, 'D$a ur zmiren a t id zegren, ur zmiren a t id flun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 98, 'Inna: "ayagi d aêunu s$uô Mass iw. Mi d tusa lemâahda n Mass iw, a t Isawi. Lemâahda n Mass iw d tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 99, 'Assen, a ten Neoo ad ddehmen wa $ef wa. Aûuvu di lbuq, d$a a ten Nessemlil akw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 100, 'A d Nessken nezzeh Loahennama, assen, i ijehliyen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 101, 'wid iwumi sêurrment wallen nnsen, mgal asmekti W. Llan ur zmiren i usemêes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 102, 'Day $ilen, wid ijehlen, ad rren imdanen iW, d imawlan war Nek? Ih, Nhegga Loahennama, d axxam i ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 103, 'Ini: "ad awen mle$ at igiten imexsuôen sennig wiyav?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 104, 'Wid iwumi iweddeô laâtab nnsen di tmeddurt n ddunit, wanag nitni nwan gerzen igi"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 105, 'Widak d wid i inekôen issekniyen n Mass nnsen, akked temlilit yideS. Mêan igiten nnsen. Ur ten Nwezzen, ass n tnekra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 106, 'Atan uqeîîi nnsen: Loahennama, imi jehlen, u mmaâlken deg issekniyen iW, akked imazanen iW.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 107, 'Ma d wid iumnen, ixeddmen ayen ilhan, axxam nnsen d leonanat n Loennet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 108, 'Degs ad wekkôen, ur ssuturen ayen nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 109, 'Ini: "lemmer ill d lmidad, i wawalen n Mass iw, ad iqqaô yill, uqbel ad fukken wawalen n Mass iw, xas a d nawi i t icban n lmidad".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 110, 'Ini: "nek d amdan kan, am kunwi. Weêêan iyi d ar Öebbi nnwen, d Öebbi Yiwen. Win issaramen timlilit n Mass is, ad ixdem ayen ilhan, ur ipcarak yiwen deg waâbad n Mass is".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 1, 'Khiâû.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 2, 'Asmekti uêunu n Mass ik, i umdan iS Zakarya;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 3, 'mi iger, i Mass is, ti$ôi tabavnit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 4, 'Inna: "a Mass iw! S tidep, ôéent laâvam iw, aqeôôu iôeq si ccib. A Mass iw! Anuju $uôeK uroin iyi isnu$ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 5, 'Nek ugade$ llzem iw, deffir i. Tameîîut iw d tiâiqeôt. Efk iyi d lfeôx s$uôeK;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 6, 'ad iyi iwôet, ad iwôet si twacult n Yaâqub. Err it, a Mass iw, d win iôuvan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 7, '"A Zakarya, s tidep, Nbecceô ik s uqcic, ism is Yeêya. Ur Nefki, i yiwen, ism agi, uqbel is".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 8, 'Inna: "a Mass iw! Amek ara sâu$ aqcic, tameîîut iw d tiâiqeôt, u nek $emqe$ di tewser"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 9, 'Inna: "Akka. Inna d Mass ik: ayagi ishel fellI. Ni$ Xelqe$ k, zik, ur telliv d acemma".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 10, 'Inna: "a Mass iw! Efk iyi d assekni". Inna: "assekni ik, ur tepmeslayev i medden, krav wavan, ur tuvnev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 11, 'Iffe$ ed ar ugdud is, si lemqam. Iweêêa yasen ad anzen ûûbeê, tameddit".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 12, '"A Yeêya, eîîef Tazmamt, s loehd". D ûûebyan, Nefka yas ûûwab,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 13, 'lmaênana akked ûûfawa, s$uône£. Ipêezzib;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 14, 'ibedd i imawlan is; ur illi d aqehhaô ne$ d amâaûi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 15, 'Tifrat fellas asmi d ilul, asmi ara immet, asmi ara d iu$al d amuddir!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 16, 'Smekti d, di Tezmamt, Meryem, asmi taâzel iman is, si twacult is, di tama ugmuv.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 17, 'Terra ssteô garas yidsen. Nuzen as d ôôuê nne£. £uôes, amzun d amdan ifuqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 18, 'Tenna: "ad iyi Ëerz Uênin, segk, ma tepêezzibev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 19, 'Inna: "nek, d amersul kan n Mass im, ad am fke$ aqcic iûfan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 20, 'Tenna: "amek ara sâu$ aqcic, ur iyi innul umdan, ur lli$ d tazennant"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 21, 'Inna: "Akka. Inna d Mass im: ayagi, ishel fellI. A t Nerr d assekni i medden, d aêunu s$uône£. D lameô ippuêeppmen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 22, 'Tebbwi tadist; syis taâzel iman is, di tama ibaâden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 23, 'Bdan p id inzikmiren ar loedra n tezdayt. Tenna: "anna$ lemmer mmute$, uqbel ayagi, ad pwappu$ akw"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 24, 'Issawel as d, seddaw as: "kkes a$wbel, ih, Mass im Irra i$éeô, seddaw am.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 25, 'Hucc, ar $uôem, loedra n tezdayt, ad am d i$li ppmeô amaynut ibwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 26, 'Eçç, ssew, ssefôeê iéôi m. Ma twalav yiwen n umdan, ini as: nek, s tidep, uéame$ i Uênin, ur pmeslaye$, assa, i umdan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 27, 'Tôuê yis ar ugdud is, tebbwi t. Nnan: "a Meryem! Ni$ tusiv d, s temsalt ihejjnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 28, 'A ultmas n Haôun, ur illi baba m d argaz ucmit, ur telli imma m d tazennant".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 29, 'Teswâad $uôes. Nnan: "amek ara nemmeslay i ûûebyan di dduê"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 30, 'Inna: "nek d amdan n Öebbi. Ifka yi d Tazmamt. Irra yi d nnbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 31, 'Iôqa yi anda lli$. Iweûûa yi taéallit, u zzakat, skud mazal iyi d amuddir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 32, 'Ad bedde$ i yimma. Ur iyi Irri d aqehhaô, ne$ d ccaqi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 33, 'Tifrat felli asmi d lule$, asmi ara mmte$, asmi ara d u$ale$ d amuddir"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 34, 'D wagi ay d Âisa, mmi s n Meryem. D awal n tidep, i$ef cukken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 35, 'Ur iûwib ara, i Öebbi, ad Isâu kra n mmi S. Gedha syiS! Ma Iseyya lameô, ad as Yini kan: "ili"! Ad yili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 36, 'Öebbi, s tidep, d Mass iw, d Mass nnwen. Ihi, âabdet eP. D wagi ay d abrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 37, 'Mgarraden ikabaren garasen. A tawa$it n wid ijehlen, mara walin ass abarar!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 38, 'Ara slen, ara walin, ass ideg ara d asen $uône£! Maca, imednas, assa, di ttelfan s ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 39, 'Nabi ten, $ef ass n ssixîa, mara iûaô lameô. Nitni, di l$eflan, nitni ur uminen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 40, 'Ih, d Nekwni, ara Iweôten tamurt akked wayen illan fellas. £uône£ tu$alin nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 41, 'Smekti d, di Tezmamt, Ibôahim. Ih, Neppa, illa d bab n tidep, d nnbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 42, 'Mi inna i baba s: "a baba! Acimi tâabdev win ur nsell, ur nepwali, ur k ip$itin s wacemma?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 43, 'Ih, a baba, Nek ippunefk iyi d, si tmusni, ayen ur ak neppunefk. Ihi ddu yidi, a k nhu$ ar ubrid ilhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 44, 'A baba! Ur âabbed Cciîan. Ni$ Cciîan illa d amâaûu i Uênin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 45, 'A baba! Nek, ugade$ a k iwwet uâaqeb n Uênin, a ppiliv d ameddakwel n Cciîan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 46, 'Inna d: "day tugiv keçç, a Ibôahim, iôebbiten iw? Ma ur tfukkev ara, war ccekk, a k ôeome$! Ïixxeô iyi tallit $wezzifen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 47, 'Inna: "ili di tifrat. Ad ssutre$ i Mass iw, ad ak Isemmeê. Neppa, s tidep, Iâuzz iyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 48, 'Ad âazle$ iman iw segwen, akked wayen tepnujum, war Öebbi. Ad naâôe$ Mass iw, ahat, s unuju w, ar Mass iw, ur $webne$ ara".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 49, 'Mi iaâzel iman is segsen akked wayen âabden, war Öebbi, Nefka yas Isêaq akked Yaâqub. Yal yiwen, Nerra t d nnbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 50, 'Nefka yasen seg uêunu nne£. Nerna yasen ccekôan umâin, lfayeq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 51, 'Smekti d, di Tezmamt, Musa. Ih, neppa, illa d aâeôvi, d amazan, d nnbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 52, 'Nessawel as d, si îîeôf ayeffus n udrar. Nessqeôb it id, ad as Nmel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 53, 'Nefka yas, seg uêunu nne£, gma s, Haôun, d nnbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 54, 'Smekti d, di Tezmamt, Ismaâil. Ih, neppa, illa d win ippaîafen di lemâahda s, d amazan, d nnbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 55, 'Iumeô i twacult is, taéallit, zzakat. Iôuva t Mass is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 56, 'Smekti d, di Tezmamt, Idris. Ih, neppa, illa d bab n tidep, d nnbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 57, 'Nessuli t s amkan aâlayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 58, 'D wigi i I$at Öebbi, ger lambiyya, ger tarwa n Adem, ger wid i Nebbwi akked Nuê, ger tarwa n Ibôahim, akked Isôail, ger wid Nenha u Nefren. Ma $ôan asen issekniyen n Uênin, ad $lin knan, s imeîîawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 59, 'Lxwelf nnsen d asatu i iooan taéallit, ddan d ccehwiyyat. Ad magren ttelfan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 60, 'Kkes ed wid isteôoâen, iumnen, xeddmen ayen ilhan. Wigi, ad kecmen Loennet, ur pwadensen s wacemma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 61, 'Leonanat n Âaden i Iwaââed Uênin, i imdanen iS, di tbavnit. Lemâahda S, s tidep, a ppevôu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 62, 'Ur sellen, degs, i yir awal, siwa: "tifrat"! Dinna, lqut nnsen, ûûbeê, tameddit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 63, 'D tagi ay d Loennet, ara Nerr d lweôt, i wid ipêezziben, seg imdanen nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 64, 'Ur d nepûubbu, siwa ma s lameô n Mass ik. IneS i illan zdat nne$, i illan deffir nne$, akked wayen illan garasen. Mass ik ur Iteppu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 65, 'Mass n tmurt, igenwan, akked wayen illan garasen. Ihi, âabed iT, ili d imezgi deg uâbad iS. Day tesnev win isâan ism iS?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 66, 'La iqqaô umdan: "ma mmute$, day a yi d ssuff$en d amuddir"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 67, 'Day ur icfa ara umdan, ar t id Nxelq, zik, ur illi d acemma?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 68, 'S Mass ik, ara ten Nefser, nitni akked cwaîen. Sinna, a ten Nerr ad zzin i Loahennama, $ef tgwecrar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 69, 'Sinna, a d Nekkes, si yal arbaâ, wid ibe$wven nezzeh, ar Uênin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 70, 'Sinna, d Nekwni, war ccekk, i Isnen sennig akw, imenza ar tmeô$iwt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 71, 'Akken tellam, a pqeôbem $uôes. Akka, ar Mass ik, d aseyyi imuêeppmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 72, 'Sinna, a Nsellek wid ipêezziben. A Neoo degs, imednas, $ef tgwecrar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 73, 'Mara asen $ôen issekniyen iberrzen nne£, qqaôen wid ijehlen i wid iumnen: "menyif sin irebbuyaâ di temâict akw i lemwansa"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 74, 'Acêal isuta i Nesqucc, uqbel nnsen, ifen ten tarkunt, ûûifa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 75, 'Ini: "ad Irnu Uênin di laâmeô, i im$eôôqen, alamma walan acu i sen ippuwaââden: d aâaqeb ne$ d imir. Ad éôen anwa illan deg umkan adiran mavi, ay d bu lâaskeô uôhifen mavi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 76, 'Ad Irnu Öebbi nnhaya i wid ipwanhan. Ar Mass ik, leûlaê idumen ifen akafi, asisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 77, 'Ma twalav win iugin issekniyen nne£, u inna: "tarkunt, tarwa ad iyi ppunefkent, war ccekk"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 78, 'Aâni issen tabavnit, ne$ iu$ lemâahda s$uô Uênin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 79, 'Xaîi, a Naru ayen inna. Ad as Nessi$wzef nezzeh aâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 80, 'A Newôet ay d inna, a d ias $uône£, d awêid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 81, 'Xtaôen, war Öebbi, iôebbiten ar asen d iawin tazmert.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 82, 'Xaîi! Ad nekôen aâbad nnsen, ad asen u$alen d ixûimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 83, 'Ur twalav ara, Nuzen ed ccwaîen i ijehliyen, la ten laâjen s ljuô?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 84, 'Ur pêiri fellasen, la Nessalay kan leêsab nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 85, 'Ass ideg ara Nefser wid ipêezziben ar Uênin, d imaâôaven,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 86, 'a Nenheô ijehliyen, d aqwvaô, ar Loahennama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 87, 'Ur sâin ccafuâa, siwa win iu$en lemâahda ar Uênin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 88, 'Nnan: "Isâa Uênin, aqcic".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 89, 'Ni$ tebbwim d abeââuq!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 90, 'Segs, qôib flan igenwan, tcerreg tmurt, grurjen idurar s édiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 91, 'Gren aS mmi S, i Uênin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 92, 'Ur iwjib ara, i Uênin, ad Isâu mmi S.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 93, 'Akken llan di tmurt akked igenwan, siwa ay d iteddun, ar Uênin, s waâbad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 94, 'Ih, Iêseb iten, Issen nezzeh amvan nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 95, 'Akw a d asen $uôeS, ass n tnekra, yiwen yiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 96, 'War ccekk, wid iumnen, ixeddmen ayen ilhan, a ten Iâuzz Uênin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 97, 'Nerra t kan d ushil, s tmeslayt ik, iwakken a pbeccôev, syis, wid iêezzben, u a pnedôev agdud iggernenn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 98, 'Acêal isuta ay Nesqucc uqbel nnsen! Day a pmagrev yiwen degsen, ne$ a ppeslev i uswecwec nnsen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 1, 'Ïh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 2, 'Ur ak d Nessader ara Leqwôan iwakken a p$weblev.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 3, 'D asmekti kan i win ippagwaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 4, 'D tarusi s$uô Win Ixelqen tamurt akked igenwan aâlayen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 5, 'Aênin i Iâanncen $ef usgeld.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 6, 'IneS i illan deg igenwan, i illan di tmurt, i illan garasen, i illan seddaw tmurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 7, 'Ma téaâvev, ihi, Neppa Iéôa sser, akked wayen iffren sennig es.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 8, 'Öebbi, ur illi ôebbi siwa Neppa. IneS ismawen imxulaf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 9, 'Ma tusa k id teqûiî n Musa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 10, 'Mi iwala times, inna i twacult is: "qqimet dagi, nek wala$ times. Amar awen d awi$, segs, asafu, ne$ ad afe$, di tmes, nnhaya".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 11, 'Mi ibbwev $uôes, Ssawlen as d: "a Musa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 12, 'Nek, s tidep, d Mass ik. Ekkes arkasen ik, ih, aql ak di Ïuwa, ta$zut iôqan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 13, 'Nek Smenyafe$ k, sell ed i uweêêi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 14, 'Nek, s tidep, d Öebbi, ur illi ôebbi siwa Nek. Ihi, âabed iyI, ééal ilmend usmekti W.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 15, 'Imir, s tidep, a d ias. B$i$ a t Ffre$, iwakken yal yiwen a t Nkafi $ef wayen ixdem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 16, '£uôek a k issefôe$ fellas, win ur numin ara yis, i iddan d lhawiyya s! Mulac a pnegrev.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 17, 'D acu p tinna deg ufus ayeffus ik, a Musa"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 18, 'Inna: "d taâkwazt iw, fellas tekkaye$, syis sse$laye$ d iferrawen i lmal iw. Sseqdace$ p i wayen nniven".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 19, 'Inna: "veggeô ip, a Musa"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 20, 'Iveggeô ip, tu$al d azrem, ippeênunuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 21, 'Inna: "ddem ip, ur ppagwad, ad as Nerr udem is amenzu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 22, 'Eémev afus ik, s idis ik. A d iffe$ d amellal, ur ihlik. D assekni nniven,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 23, 'iwakken ad ak Nessken, seg issekniyen nne£ imeqwôaêanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 24, 'Öuê ar Ferâun. Neppa, s tidep, d aqehhaô".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 25, 'Inna: "a Mass iw! Lli idmaren iw,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 26, 'Sehhel iyi lameô iw,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 27, 'Efsi tiyersi seg iles iw,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 28, 'ad fehmen awal iw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 29, 'Efk iyi amâiwen di twacult iw:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 30, 'gma Haôun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 31, 'Ssem$weô, syis, tazmert iw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 32, 'Zdukkel it ar lameô iw,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 33, 'iwakken a K nesbuccaâ aîas,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 34, 'a K id nesmekti aîas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 35, 'Keçç, s tidep, la $ d Tepwaliv"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 36, 'Inna: "tepwaqbel tuppra k, a Musa"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 37, 'Ni$ Nâateq ik, tikelt nniven,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 38, 'mi Nweêêa, i yimma k, ayen i Nweêêa:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 39, 'err it deg usenduq, veggeô it s asif. A t issers wasif deg uqeôqaô, a t iddem ucengu W, u d acengu is. Fki$ ak si lmaênana W, a ppeppuôebbiv zdat wallen iW.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 40, 'Mi telêa ultma k, tenna: "ma ad awen mle$ w ara itkelfen fellas"? Nerra k id i yimma k, ad fukken imeîîawen is, ur têezzen ara. Ten$iv amdan, Nsellek ik si le$wben. Njeôôeb ik s lfetnat. Tzed$ev kra iseggwasen ar at Madian. Sinna, tusiv d s lqwedôa, a Musa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 41, 'Smenyafe$ k i iman iW.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 42, 'Öuêet, keçç akked gma k, s issekniyen iW, ur stehzayet $ef usmekti W.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 43, 'Öuêet ar Ferâun. Neppa, s tidep, d aqehhaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 44, 'Mmeslayet as s wawal amelêan, amar a d immekti, ne$ ad iagwad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 45, 'Nnan: "a Mass nne$! Nugad ad a$ iglez, ne$ ad ijuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 46, 'Inna: "ur ppagwadet, Nek, war ccekk, yidwen, Selle$, Pwali$.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 47, 'Öuêet $uôes, tinem as: "nekwni d imazanen n Mass ik, seddu yidne$ At Isôail, ur ten ppâaqab ara. Aql a$ nusa k id s issekniyen n Mass ik. Tifrat i wi iddan d nnhaya!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 48, 'S tidep, neppuweêêa d, ar ad ippuâaqeb win inekôen, iwexxôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 49, 'Inna: "anwa T Mass nnwen, a Musa"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 50, 'Inna: "Mass nne$ d Win Ifkan lxelq is i yal cci, sinna, Inha".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 51, 'Inna: "amek tevôa d isuta timezwura"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 52, 'Inna: "i ten Iéôan, d Mass iw, di Tezmamt. Mass iw ur I$ellev, ur Iteppu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 53, 'Win i wen irran tamurt d dduê. Iga yawen degs iberdan. Issers ed aman seg igenni. Nessuffu$ ed yissen tiyugiwin n yal ûûenf n le$ôus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 54, 'Eççet, ekset lmal nnwen. Deg waya, s tidep, d issekniyen i imawlan n ddehn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 55, 'Segs, Nxelq ikwen; degs, a kwen Nerr; segs, a kwen id Nessuffe$, tikelt nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 56, 'Ni$ Nessken as akw issekniyen nne£ inkeô, iugi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 57, 'Inna: "day a$ d tusiv, s ssêur ik, a Musa, ad a$ tessuff$ev seg wakal nne$?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 58, 'War ccekk, ad ak d nawi ssêur i t icban. Err garane$ yidek ppaâud, deg umekkan iwulmen, ur t nezgal, ur t tezgalev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 59, 'Inna: "ppaâud nnwen ass n tme$ôa, a d mlilen medden, di tûebêit".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 60, 'Izzi Ferâun, ijmaâ ed ccbukat is, d$a iusa d.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 61, 'Inna yasen Musa:"a tawa$it nnwen! Ur d garet tikerkas $ef Öebbi, a kwen Isxev s uâaqeb. Ni$ ad ixseô win d igren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 62, 'Mcawaôen f lameô nnsen, ffren ayen mmeslayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 63, 'Nnan: "ihi, sin agi d iseêêaren, b$an a kwen ssuff$en seg wakal nnwen, s ssêur nnsen. Ad kksen abrid nnwen amxallef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 64, 'Jemâat ed ccbukat nnwen, sinna aset ed d leûfuf. Ni$ ad irbeê, assa, win iufraren"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 65, 'Nnan: "a Musa! A pveggôev keçç, ne$ d nekwni ara iveggôen d imezwura"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 66, 'Inna: "xaîi, veggôet"! Si ssêur nnsen, iwala amzun leêêun imraren akked tâakwzin nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 67, 'Musa, deg iman is, iêus i lxuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 68, 'Nenna: "ur ppagwad! Keçç, s tidep, sennig sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 69, 'Veggeô i illan deg ufus ik ayeffus! Ad isseblaâ ay d snulfan". Ay d snulfan, siwa ccbukat iseêêaren. Anda idda useêêar, ur irebbeê ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 70, '£¨lin iseêêaren, knan, nnan: "numen s Mass n Haôun akked Musa".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 71, 'Inna: "day tumnem yiS, uqbel i wen serrêe$? Neppa, zi$, d ameqwôan nnwen. Isêefv awen ssêur. War ccekk, ad awen gezme$, avaô sya, afus sya, u a kwen ûemmôe$ af umidag n leodar n tezdayin. A ppeéôem, s tidep, anwa ay d bab uâaqeb meqqwôen, u ara idumen sennig wiyav".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 72, 'Nnan: "ur k nesmenyaf, d awez$i, i wayen i $ d iusan ubeggen, akw i Win i $ Ixelqen. Seyyi i k ihwan a pseyyiv. Aseyyi k, d aseyyi $ef tmeddurt n ddunit agi kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 73, 'Ih, numen s Mass nne$, iwakken ad a$ Isemmeê tuccva nne$, akked wayen n ssêur i têeppmev fellane$. Pifxiô Öebbi d Imezgi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 74, 'Ih, Loahennama i win iusan ar Mass is, d abe$wvi. Ur ipmeppat degs, ur d ippidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 75, 'Win i iusan $uôeS d lmumen u ixdem ayen ilhan, widak ad ilin deg imukan aâlayen mavi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 76, 'leonanat n Âaden, ddawat sen isaffen ppazzalen, ad wekkôen din. Ayagi, d akafi i win zeddigen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 77, 'Ni$ Nweêêa i Musa: "ôuê, deg iv, akked imdanen iW. Egg asen abrid akiwan, di yill. Ur ppagwad a kwen in vefôen, ur ppiwêic".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 78, 'Ferâun, s iâsekôiwen is, vefôen ten. Isseblaâ ten yill, içça ten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 79, 'Itlef Ferâun agdud is, ur inhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 80, 'A yAt Isôail! Ni$ Nsellek ikwen seg ucangu nnwen. Nefka yawen ppaâud, ar loiha tayeffus n udrar. Nessers awen d lmenna, ifeôôuoen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 81, 'Eççet si lmakla ilhan, i s ikwen N$at. Ur zegret tilas fellas, mulac a kwen immager urrif iW. Win immuger urrif iW, ni$ igrareb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 82, 'U Nek, s tidep, Psemmiêe$ i win isteôoâen, iumnen, ixeddmen ayen ilhan, d$a ipwanha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 83, '"Acu i k i$eûben seg ugdud ik, a Musa"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 84, 'Inna: "zgan deffir i. £awle$ d $ureK, a Mass iw, iwakken a Pôaviv".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 85, 'Inna: "ih, ni$ Njeôôeb agdud ik, deffir ek. Itelf iten Usamiri".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 86, 'Iu$al ed Musa s agdud is, s zzâaf d wumri. Inna: "a yagdud iw! Day ur awen Ifka ara, Mass nnwen, lemâahda lâali? Day tâaîîel fellawen lemâahda? Ne$ day teb$am a kwen immager urrif n Mass nnwen? Tzeglem ppaâud iw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 87, 'Nnan: "ur nezgil ppaâud ik, s leb$i nne$. Maca, nbubb tiâakkwmin n ôôêuê n ugdud, d$a nveggeô iten. Akken i iveggeô Usamiri".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 88, 'Issuffe$ asen d aâejmi, d ameslux isrugmuten. Nnan: "wagi d ôebbi nnwen u d ôebbi n Musa. Ippu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 89, 'Day ur walan ara, ur asen d ippara awal, ur izmir a ten ivuôô, ne$ a ten infaâ?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 90, 'Ni$ Haôun inna yasen, uqbel: "a yagdud iw! Teppuhewwlem kan, yis. Mass nnwen, s tidep, d Aênin. Ddut yidi, vefôet lameô iw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 91, 'Nnan: "ur tnepfukku akaber is, d awez$i, alamma iu$al ed Musa $uône$".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 92, 'Inna: "a Haôun! D acu i k iîîfen, mi ten twalav nnetlafen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 93, 'Day ur teddiv ara yidi? Day tugiv lameô iw"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 94, 'Inna: "a mmi s n yimma! Ur iyi ppaîîaf si tamart iw, ne$ seg uqeôôu w. Nek, s tideps, ugade$ ad iyi d tiniv: tessemfaôaqev At Isôail, ur tu$ev awal iw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 95, 'Inna: "d acu t leqsed ik a Usamiri"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 96, 'Inna: "wala$ ayen ur walan. Ddme$ d tummeét n lateô umazan, veggôe$ p. Akka ay êusse$ deg iman iw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 97, 'Inna: "ôuê ihi, a ppevôu yidek di tmeddurt a ppeqqaôev: ur iyi pnalet! U, s tidep, $uôek ppaâud ik ur tezmirev a t tzeglev. Muqel ôebbi ik, u$uô mazal teqqimev, ard a t nesseô$, a t ssebruzzaâ ar yill, wakali".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 98, 'Mass nnwen, siwa Öebbi. Ur illi ôebbi siwa Neppa. Tamusni S tjemmel yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 99, 'Akka i k Nêekku, seg isallen n zik. Ni$ Nefka yak d, s$uône£, asmekti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 100, 'Win i s iwexxôen, ad iâabbi taâkkwemt, ass n tnekra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 101, 'Ad wekkôen dinna. Ay dir ip fellasen ppaâbga, ass n tnekra!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 102, 'Ass ideg ara d ûuven di lbuq, a d Nefser ibe$wviyen, zgezwen assen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 103, 'Ad swecwicen wa i wa: "mraw kan i teqqimem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 104, 'Nekwni, Nif akw akken Nessen, ayen d qqaôen, mi sen inna yiwen umxallef degsen: "teqqimem kan ibwass".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 105, 'Steqsayen k $ef idurar. Ini: "a ten Issebruzzaâ Mass iw, d iwzan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 106, 'A ten Irr d aza$aô ibuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 107, 'Ur tepwaliv degs i iâawjen, ne$ i izzren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 108, 'Assen, ad vefôen aberraê, war zzrug. Ad irs ûûut zdat Uênin, a ppeslev kan i uswecwec.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 109, 'Assen, ur ten tenfaâ ccafuâa, siwa i win Iooa Uênin, u Iôuva t $ef wawal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 110, 'Issen i illan zdat sen, i illan deffir sen. Ur illi sanda ara T issinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 111, 'Ad îîinzen wudmawen i Umuddir n lebda. Ara ixesôen d win ibubben ddens.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 112, 'Win ixeddmen ayen ilhan, u neppa iumen, ur ippagwad ddens, ne$ aqhaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 113, 'Akka, Nessers it id, d Leqwôan s taâôabt. Nenewwel ed, degs, aâeggen, amar ad êezben, u a ten id ias usmekti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 114, 'D Ameqwôan Öebbi, Agellid, Tidep. Ur pêiri, di t$uôi, uqbel ma ifukk uweêêi s, $uôek. Ini: "a Mass iw! Ernu yi di tmusni".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 115, 'Ni$ Nâahed, zik, Adem. Ippu, ur Nufi $uôes laâzem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 116, 'Mi Nenna i lmalayek: "knumt i Adem", knant, siwa Iblis i iugin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 117, 'Nenna: "a Adem, wagi, s tidep, d acengu k, akked tmeîîut ik. £urwat a kwen id issuffe$, si Loennet, a p$weblem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 118, 'Ih, keçç, degs, ur teplaéev, ur tâarruv.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 119, 'S tidep, keçç, degs, ur tepfadev, ur k iîîuôôu yiîij".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 120, 'I$wa t Cciîan, inna: "a Adem, ad ak ssekne$ ttejôa uwekkeô, akw n tgelda n lebda"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 121, 'Eççan segs, d$a walan iman nnsen âaryan, bdan la tessôen iman nnsen, s iferrawen n Loennet. Adem iaâûa Mass is, idda di le$wlav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 122, 'Sinna, Ifren it Mass is, Issuref as, Inha t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 123, 'Inna: "ûûubet segs akw, wa d acengu n wa. Ma tusa kwen id nnhaya, s$uôI, win iddan d nnhaya iW, ur ipputellef, ur i$webbel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 124, 'Win iooan asmekti W, tameddurt is d tucmip. Ass n tnekra, a t Nefser d ader$al".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 125, 'A d yini: "a Mass iw! Acimi iyi Tfesrev d ader$al, ni$ lli$ pwali$?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 126, 'A d Yini: "akken i k id iusan ssekniyen nne£, teppuv iten, akken ara tepwappuv, assa".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 127, 'Akka ay Nepqeîîi win izegren tilas, ur numin s issekniyen n Mass is. U, s tidep, aâaqeb n laxeôt iwâaô kteô, u ad idum kteô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 128, 'Day ur ten inha ara wacêal isuta i Nesqucc, uqbel nnsen? La leêêun $ef tnezdu$in nnsen. Deg wayagi, s tidep, d issekniyen i imawlan n ddehn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 129, 'Lemmer ur d izwar ara wawal, s$uô Mass ik, akked lajel ipwassnen, yili, war ccekk, iûaô uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 130, 'Ihi, bibb ayen d qqaôen, sbuccaâ s ccekôan Mass ik, uqbel ad inqeô yiîij, uqbel ad i$li, deg iv. Anez di levôuf n wass, amar fellak aôavi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 131, 'Ur ppara allen ik ar wayen i Nefka i kra n twaculin nnsen. D ajeooig n tmeddurt di ddunit, iwakken a ten Njeôôeb yis. A$iti n Mass ik yif it, u ad idum kteô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 132, 'Ameô taéallit i twacult ik, êerz ip. Ur ak Nessutur ôôeéq, d Nekwni ara k Iôeéqen. Laâquba d aêezzeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 133, 'Nnan: "a lemmer i $ d iusi s ussekni s$uô Mass is"! Day ur ten id iusa ara ubeggen, deg wayen illan di tewôeqtin timezwura?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 134, 'Lemmer iten Nesqucc s uqeîîi, uqbel neppa, a d inin, war ccekk: "a Mass nne$! Acimi ur a$ d Tunzev ara amazan? A neddu d issekniyen iK, uqbel a nendell u a neppuqeîîi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 135, 'Ini: "akw, la nepgani. Ihi gganit. A ppissinem anwi i iddan d ubrid ilhan, anwi i ipwanhan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 1, 'Iqeôb ed i medden uqeîîi nnsen, u nitni stehzan, ur d rzin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 2, 'Ur ten d ippas usmekti amaynut, s$uô Mass nnsen, mebla ma ppuraren, mara s sslen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 3, 'Ur d rzin wulawen nnsen. Ppemcawaôen wid idensen, s tuffra: "d acu t wagi, siwa amdan am kunwi? Day a pvefôem ssêur, kunwi tepwalim"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 4, 'Inna: "Mass iw Iéôa timenna deg igenni, di tmurt. Neppa Issel, Issen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 5, 'Maca, nnan: "d taffa n tirga. Xaîi! Isnulfa t id. Xaîi! Neppa d amedyaz. Aha san, ad a$ d iawi assekni, akken id ippuceggaâ i imezwura"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 6, 'Ur tumin, uqbel nnsen, yal temdint Nesqucc, day ad amnen nitni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 7, 'Ur d Nuzen, uqbel ik, siwa irgazen, iwumi Nweêêa. Steqsit imawlan usmekti, ma ur teéôim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 8, 'Ur ten Nerri d tifekkiwin ur ntepp lqut. Ur wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 9, 'Sinna, Neîîef deg wayen i sen Nâahed, u Nsellek iten akked wid i £ ihwan. Nen$a imcumen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 10, 'Ih, Nessers awen ed Tazmamt, degs asmekti nnwen. Day ur tefhimem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 11, 'Acêal n temdinin idensen ay Neôéa! Nexleq, deffir sent, agdud nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 12, 'Mi êussen i lwaâôan nne£, atnan la regwlen, segs.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 13, 'Ur regwlet ara, u$alet ar wayen is testasrem, ar ixxamen nnwen. Amar fellawen asteqsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 14, 'Nnan: "a yamxix nne$, nella, s tidep, d imednas"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 15, 'Ur tfukk ti$ôi yagi nnsen, armi ten Nerra d aqecqac urhif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 16, 'Ur Nexliq ara, i wurar nne£, igenni, tamurt, akked wayen illan garasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 17, 'Lemmer day Neb$i lhawiyya, yili Nebbwi p id, s $uône£, maday Naâna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 18, 'Xaîi! Nekkat tikerkas s tidep. Tneqq itent. Neqvent. A tawa$it nnwen, ilmend n wayen d teggarem!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 19, 'IneS kra illan di tmurt akked igenwan. Wid illan $uôeS, ur sme$wôen ara iman nnsen, $ef uâabed iS. Ur âaggun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 20, 'Ppanzen iv akked wass, ur sêissifen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 21, 'Ne$ ddmen d, si tmurt, iôebbiten id ipparan ar ddunit?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 22, 'Lemmer llin degsen iôebbiten, war Öebbi, war ccekk, ad fesden. Gedha s Öebbi, Mass n usgeld, seg wayen id ggaren!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 23, 'Ur fellaS asteqsi $ef wayen Ixeddem. Nitni, fellasen asteqsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 24, 'Ne$ day ddmen iôebbiten, war Neppa? Ini: "Awit ed atebbet nnwen". Ayagi d asmekti i wid illan yidi, d asmekti i wid illan, uqbel i. Maca, tegwti segsen, ur ssinen tidep. D$a zzin akin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 25, 'Ur d Nuzen amazan, uqbel ik, siwa ma Nweêêa yas ar: "ur illi ôebbi siwa Nek, ihi âabdet iyI".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 26, 'Nnan: "Isâa Uênin aqcic". Gedha s yiS! Xaîi! D imdanen imaâzuzen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 27, 'Ur S d zeggwiren deg wawal, xedmen s lameô iS.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 28, 'Iéôa i illan zdat sen, akked wayen illan deffir sen. Ur ççafâan, siwa $ef win Iôuva. U nitni, si lxuf iS, pêadaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 29, 'Win, segsen, id innan: "nek d ôebbi, war Neppa", a t Nqeîîi s Loahennama. Akka ay Nepqeîîi imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 30, 'Ne$ wid ijehlen ur walan ara tamurt akked igenwan llan mlalen? Nessemfaôaq iten, Nga s waman kra n wayen idren. Ihi, day ur ppamnen ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 31, 'Nerra di tmurt idurar, iwakken ur tepêerrik ara yissen. Nerra, degsen, tiza d iberdan, amar ad pwanhun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 32, 'Nerra igenni d ssqef innestaôen, u nitni ooan issekniyen nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 33, 'D Neppa i Ixelqen iv akked wass, iîij akked waggur, yal wa iteddu deg ubrid is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 34, 'Ur Nefka ara, uqbel ik, tameddurt n lebda i umdan. Day keçç a ppemmtev, nitni ad wekkôen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 35, 'Yal amdan ad ijeôôeb tameppant. Nepjeôôib ikwen s cceôô, akked lxiô. D ahewwel. £uône£ tu$alin nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 36, 'Mara k id walin wid ijehlen, pmmaâliken kan fellak: "d wagi id ikkaten deg iôebbiten nnwen"? Nitni nekôen asmekti n Uênin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 37, 'Ipwaxleq umdan si leêmeq. Ad awen d Ssenâate$ issekniyen iW, ihi, ur iyI $eûbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 38, 'Qqaren: "melmi lemâahda yagi, ma tessawalem tidep"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 39, 'Wid ijehlen, a lemmer ad éôen tagwnip ideg ur d tekksen udmawen nnsen, ne$ iârar nnsen, si tmes! Nitni ur pwasellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 40, 'Xaîi! A ten id ias, deqzalla, a ten iwwet ba$a, ur zmiren a t rren, ne$ ad gganin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 41, 'Ni$ ttahan $ef imazanen, uqbel ik! Ayen i$ef mmaâlken, izzi d $ef wid, segsen, i ittahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 42, 'Ini: "anwa ara kwen ifukken, iv akked wass, seg Uênin"? Maca, ooan asmekti n Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 43, 'Ne$ sâan iôebbiten ara ten ifukken, war Nekwni? Ur zmiren ad sellken iman nnsen, ur sâin imâiwnen mgal a£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 44, 'Xaîi! Nestaser i wigi akked imezwura nnsen, ar tewser nnsen. Day ur walan ara, Neppas ed ar tmurt, Nessenqas si leryaf is? Day d Nitni ara irebêen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 45, 'Ini: "la kwen nedôe$ kan, s uweêêi". Ur sellen iâééugen i unabi ma ppunedôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 46, 'Ma iêuza ten uûuvu uâaqeb n Mass ik, war ccekk, a d inin: "a ssexv nne$! Ih, nella d imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 47, 'A n Nessers lmizanat iûewben, ass n tnekra. Ur ipwadnes umdan s wacemma. Xas d aâqqa ucceryad, a t id Nawi. Nesteqnaâ yisne£ i uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 48, 'Ni$ Nefka i Musa akked Haôun, afraz, akked tafat d usmekti, i wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 49, 'Wid ippagwaden Mass nnsen, ur T walan, u pêaraben $ef yimir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 50, 'Wagi d asmekti iôqan, id Nessader. Day a t tagwim kunwi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 51, 'Ni$ Nefka, zik, nnhaya s i Ibôahim? Nella Nessen it.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 52, 'Mi inna i baba s akked ugdud is: "d acu tent tâancurin agi, i la tepkabarem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 53, 'Nnan d: "Nufa d imezwura nne$ la tent âabden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 54, 'Inna: "ihi, tellam, kunwi akked imezwura nnwen, di ttelfan n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 55, 'Nnan: "tusiv a$ d, s tidep, ne$ keçç seg wid ippuraren"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 56, 'Inna: "xaîi. Mass nnwen d Mass n tmurt akked igenwan, id Ixleq. Nek, seg inagan n waya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 57, 'S Öebbi, ard ad andi$ i tâancuôin nnwen, mara teîîixxôem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 58, 'Isseftutes itent, siwa tameqwôant degsent, amar a d u$alen $uôes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 59, 'Nnan: "anwa i igan akka i iôebbiten nne$? Neppa, war ccekk, d amednus".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 60, 'Nnan: "nesla i ileméi, itent id iudren, isem is Ibôahim".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 61, 'Nnan: "awit ep id, zdat wallen n medden, amar ad ilin d inagan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 62, 'Nnan: "day d keçç i igan akka, i iôebbiten nne$, a Ibôahim"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 63, 'Inna: "xaîi, i igan akka, d ameqwôan nnsen agi. Steqsit pen, ma pmeslayen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 64, 'Endekwalen d. Nnan: "ih, d kunwi ay d imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 65, 'Sinna, bran i iqweôôa nnsen: "ni$ wigi, teéôiv, ur pmeslayen ara"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 66, 'Inna: "day tâabdem, war Öebbi, ayen ur kwen inefâan, ur kwen iîîuôôun, s wacemma?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 67, 'Tfuh i kunwi, akked wayen tâabdem, war Öebbi! Day ur tefhimem ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 68, 'Nnan: "sseô$et ep, u sellket iôebbiten nnwen, ma tâazmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 69, 'Nenna: "a times, ili d tasmuvi u d talwit, i Ibôahim".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 70, 'Undin as p. Nerra ten d imexsuôen mavi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 71, 'Nsellek it, akked Luî, ar tmurt i Neôqa i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 72, 'Nefka yas Isêaq, Nerna yas Yaâqub. I sin, Nerra ten d wid imaânen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 73, 'Nerra ten d imvebbôen, nehhun s lameô nne£. Nweêêa yasen igiten ilhan, taéallit, azekki. Llan d wid i £ iâabden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 74, 'I Lut, Nefka ûûwab, tamusni. Nsellek it si temdint i illan txeddem tucmitin. Llan, s tidep, d agdud n dir, d laâôuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 75, 'Nesskecm it deg uêunu nne£. Neppa, ih, seg wid imaânen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 76, 'I Nuê, zik, mi inâaô. Njaweb as ed. Nsellek it, neppa akked twacult is, si lefqaâ abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 77, 'Neneêêel it mgal agdud i iskaddben issekniyen nne£. Llan, s tidep, d agdud n dir. Ne$ves iten meôôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 78, 'I Dawed akked Sliman, mi êudden $ef yiger, ideg ksant wulli n medden. Nella d Inagan uêuddu nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 79, 'Nessfehm as p i Sliman. I sin, Nefka ûûwab, tamusni. Nêeppem i idurar akked igvav ad sbuccâen Dawed. D ayen Newqem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 80, 'Nessêefv as, ad awen iûnaâ iceîîiven, ara iêarben fellawen si tiytiwin. Day a ppesnemmrem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 81, 'I Sliman, avu n tarikt, ipûuvu s lameô is, $er tmurt i Neôqa. Nezga Néeô yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 82, 'Ger ccwaîen, wa i$evves as, wa iqubel cce$l nniven. Nella d imêaraben nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 83, 'I Yub, mi inuj $eô Mass is: "nek pwa$e$. Keçç, Tifev akw wid ipêunun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 84, 'Njaweb as ed. Nekkes as it ivuôôen; Nerra yas d tawacult is, akw, yides, tin i p icban. D aêunu s$uône£, d asmekti i iâabaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 85, 'Ismaâil, Idris, Dulkifl, akken ma llan, d iûebôiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 86, 'Nesskecm iten deg uêunu nne£. Nitni, s tidep, seg wid imaânen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 87, 'I Dannun, mi iôuê s wurrif. I$il ur Nesâi ara adabu fellas. Inâaô, di tellis: "ur illi ôebbi siwa Keçç. Gedha s yiseK! Nek lli$ si imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 88, 'Njaweb as ed. Nâateq it si éémik. Akka ay Nâateq lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 89, 'I Zakaria, mi inuj $uô Mass is: "a Mass iw! Ur iyi Ippaooa ara d amengur. Keçç, Tifev akw iweôôaten".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 90, 'Njaweb as ed. Nefka yas Yaêia, Nesseêla yas tameîîut is. Nitni, s tidep, izga izwar lxiô nnsen. Pnujun $uône£, s tugwdi d usirem. Unzen a£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 91, 'Ar tin i iqqimen zeddiget, Nûuv si ôôuê nne£. Nerra p, neppat akked mmi s, d assekni i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 92, 'Lois agi nnwen, war ccek, d lois yiwen. Nek d Mass nnwen, ihi âabdet iyI.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 93, 'Gezmen lameô nnsen garasen. £uône£, akw, ara d u$alen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 94, 'Win ixeddmen ayen ilhan u irna iumen, ur ipôuêu laâtab is. Ih, Nekwni Nepparu fellas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 95, 'Ipwagdel asen a d u$alen $eô temdint i Nesqucc,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 96, 'alamma serrêen d i Iaouo d Maouo. Nitni, si yal ti$ilt, a d azzlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 97, 'Tqeôb ed lemâahda n tidep. Atan iqquô yiéôi n wid ijehlen: "a tawa$it nne$! Ni$ nella ne$fel $ef waya. U, aâer, nella d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 98, 'Kunwi, s tidep, akked wayen tâabden, war Öebbi, d is$aôen n Loahennama. £ures, kunwi, teppeddum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 99, 'Lemmer llin widak d iôebbiten, ur p keççmen. Akw, ad wekkôen degs.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 100, 'I nitni, degs, zzhir. Nitni, degs, ur sellen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 101, 'Ma d wid iwumi izwar ssaâd, s$uône£, widak, segs, ad baâden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 102, 'Ur sellen i ûûut is. Ad wekkôen deg wayen cihwant teôwiêin nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 103, 'Ur ten i$webbel lweêc abarar. A ten magrent lmalayek: "assa, d ass nnwen, i wen ippuwaââden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 104, 'Ass ideg ara Nesnefvas igenni am tweôqep n tira, akken Nebda axlaq amezwaru, ad as Nales. D lemâahda fellane£. Akka, ih, ara Nexdem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 105, 'Ni$ Nura deg Ihellilen, deffir usmekti: "ara iweôten tamurt, d imdanen iW imaânen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 106, 'Deg wayagi, war ccekk, d asali i ugdud iâabbaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 107, 'Ur k id Nuzen, siwa d aêunu i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 108, 'Ini: "iyi d ippuweêêan, siwa: Öebbi nnwen d Öebbi Yiwen kan. Kunwi ma d imvuâen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 109, 'Ma wexxôen, ini: "âaggne$ awen, akken ma tellam; ur éôi$ ma iqôeb, ne$ ibâad, ayen i wen ippuwaââden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 110, 'Neppa, s tidep, Issen awal d iff$en, Issen ayen tessusmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 111, 'Ur éôi$ ma, ayagi, ahat d ahewwel nnwen, u d zzhu n tallit kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 112, 'Inna: "a Mass iw! Eêkem s tidep. Mass nne$, Aênin, i nepper d Amâiwen, mgal ayen teppandim".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 1, 'A yimdanen! Ëezzbet i Mass nnwen, zzenzla n yimir, stidep, d tadyant tabarart.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 2, 'Ass ideg ara p twalim, yal timôebbit a ppeppu win tessuîîuv, yal tadist a ppexseô. A pwaliv imdanen ssekôen, ur sskiôen. Maca, aâaqeb n Öebbi iwâaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 3, 'Ger yimdanen, illa win ipnamaren $ef Öebbi, war tamusni. Iteddu d yal cciîan imcebbwel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 4, 'Iura fellas: "ar wagi, win i t irran d bab is, ara t itlef, s tidep, u a t inheô ar uâaqeb ujajiê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 5, 'A yimdanen! Ma di ccekk ay tellam f tnekra, ihi, Nekwni, s tidep, Nxelq ikwen seg wakal, sinna, si tiqqit n l$ella, sinna, seg urgan, sinna, si tecriêt, texleq ur texliq, iwakken ad awen Nbeggen. Neppara, di tâabbuvin, ayen i £ ihwan, alamma d lajel ipwassnen. Sinna, Nessuffu$ ikwen id d llufanat, sinna a ppim$uôem. Segwen llan wid ippemmten, u segwen win ara iawven d awessur, ard ur ippisin acemma seg wayen issen. A pwalid akal d a$uôaô. Ma Nesse$li d ageffur fellas, ad ikker, ad icuff, a d ifk tayuga n yal ûûenf uziyn n le$ôus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 6, 'Ayagi, acku Öebbi d Tidep. D Neppa id Issidiren lmeggtin. Neppa Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 7, 'U imir a d ias, war ccekk fellas. U Öebbi a d Issker wid illan di tneîlin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 8, 'Ger imdanen, illa win ipnamaren $ef Öebbi, war tamusni, ne$ nnhaya, ne$ Tazmamt ifeten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 9, 'Icuff aqenduô, iwakken ad itlef seg ubrid n Öebbi. Fellas xezzu di ddunit. Deg wass n tnekra, a Nessuk fellas aâaqeb n tmeô$iwt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 10, 'Ayagi, $ef wayen id urwen ifassen ik. U Öebbi ur Idennis imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 11, 'Ger yimdanen, win iâabden Öebbi, $ef rrif. Ma iusa t id lxiô, ad ithenni yis. Ma iusa t id uhewwel, ad iswexxeô udem is. Öuêent as, ddunit, laxeôt. Ayagi d lexsaôa n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 12, 'Ipnuju, war Öebbi, ar wayen ur t neîîuôôu, ur t neffaâ. D wagi ay d ttelfan u$miq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 13, 'Ipnuju ar bu vveôô izwaren aba$uô ines. Ay d bab ucmit, ay d acrik ucmit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 14, 'Öebbi, s tidep, ad Issekcem wid iumnen, i ixeddmen ayen ilhan, ar Loennet, ddaw as isaffen ppazzalen. Öebbi, s tidep, Ixeddem ayen Ib$a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 15, 'Win i oaâlen ur t Ipsellik ara Öebbi, di ddunit, di laxeôt, ad iâalleq amrar s igenni, sinna, ad igzem nnefs is. Ad iéeô ma tiêêeôci s temêa ayen i t irêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 16, 'Akka ay t id Nessader, d issekniyen iberrzen. U Öebbi, s tidep, Inehhu win i S ihwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 17, 'Ih, ass n tnekra, ad Iêudd Öebbi ger wid iumnen, udayen, iûabiyen, imasiêiyen, u iâabbaden n tmes, wid ipcaraken. Öebbi, s tidep, Iwala yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 18, 'Ur twalav ara knan i Öebbi i illan deg igenwan, i illan di tmurt: iîij, aggur, itran, idurar, ttjuô, lêayawan, aîas n yimdanen. Aâaqeb d lewoeb $ef aîas. Win Isdull Öebbi, ur illi w ara t iâuzzen. Ih, Öebbi Ixeddem ayen i S ihwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 19, 'Atnan sin ixûimen ppemqellaân $ef Mass nnsen. S tmes ay pwafeûlen iceîîiven n wid ijehlen. Ad mmiren, $ef iqweôôa nnsen, waman iô$an', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 20, 'ara issefsin ayen illan deg iâabbav nnsen, akked igwelman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 21, 'I nitni, ijekwaven n wuzzal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 22, 'Yal tikelt ara ssirmen a d ff$en segs, seg wakken meênen, a ten rren $uôes: "jeôôbet aâaqeb n tmeô$iwt"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 23, 'Öebbi, s tidep, ad Issekcem wid iumnen, ixeddmen ayen ilhan, ar Loennet, ddaw as isaffen ppazzalen. Degs ad qqnen imeqyasen n ddheb d lyaqut. Leêrir deg iceîîiven nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 24, 'Pwanhan s awal umâin, pwanhan s abrid Umaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 25, 'Ih, i wid ijehlen i issefôa$en abrid n Öebbi, akked Loamaâ n Lêaôam, i Nerra i imdanen, ama d amezda$ n din, ama d abeôôani; i win ib$an degs tijehli, s ddens, a Nesâaddi aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 26, 'Mi Nhegga i Ibôahim, amkan n Uxxam: "ur iyI pcarak acemma! Zizdeg axxam iW i wid idewwiôen, wid ibedden, wid iîîinizen, iknan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 27, 'Enced medden ar lêio. A d asen $uôek $ef uvaô, ne$ $ef yal amerkub ulîif. A d asen si yal abrid ibaâden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 28, 'Ad cehhden $ef l$it nnsen. A d smektin ism n Öebbi, deg ussan ipwassnen, $ef ubhim n lmal i sen Ifka. Eççet segs, cceççet ame$bun, aéawali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 29, 'Sinna, ad ssirden, ad qenâen asirem nnsen, ad dewwôen i Uxxam aqdim".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 30, 'Akka. Win ippâuzzun ayen Igdel Öebbi, ilha yas kteô, ar Mass is. Ëellen awen lmal, siwa wid i wen mlan. Janbet lâaô n tâancuôin, janbet awal n ééuô;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 31, 'am wid imalen ar tidep ar Öebbi, ur aS pcaraken. Win ipcaraken i Öebbi, amzun i$li d seg igenni, u iccelqef it ufôux, ne$ inheô it wavu, s amekkan lqayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 32, 'Akka. Win ippâuzzun isekkiren n Öebbi, ihi, d aêezzeb n wulawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 33, 'I kunwi degs aba$uô ar lajel ipwassnen, sinna, îêegga nnsen ar Uxxam aqdim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 34, 'I yal lois, Nefka asekkir, iwakken a d smektin ism n Öebbi, $ef ubhim n lmal is iten N$at. Öebbi nnwen d Öebbi Yiwen. Ihi, anzet aS. Becceô itubiyen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 35, 'wid iwumi ppergigin wulawen nnsen mara d mmektin Öebbi, wid iûebbôen i wayen iten iu$en, wid ipéallan u pseddiqen seg wayen is iten N$at.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 36, 'Lmal iqebbwan, Nerra yawen ten, seg isekkiren n Öebbi. Degsen lfayda i kunwi. Bedret fellasen isem n Öebbi, mara d rsen. Mi $lin $ef ibeôdiyen nnsen, eççet segsen, cceççet aâîîaô, aéawali. Akka ay d Nenub fellawen yissen, amar a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 37, 'Ur ippawev ar Öebbi uksum nnsen, ne$ idamen nnsen, d awez$i. Ara T iawven, d aêezzeb nnwen. Am akka, Inub fellawen yissen, iwakken ad aS tgem ccan i Öebbi, ilmend n nnhaya nnwen s$uôeS. Becceô wid imaânen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 38, 'Ih, Öebbi Ipfukku wid iumnen. Ih, Öebbi ur Iêemmel ara yal lxayen ajehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 39, 'Tsriê i wid ipwawwven imi pwadensen - Öebbi, s tidep, Izmer a ten Isellek -,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 40, 'wid id ssuff$en seg ixxamen nnsen, war ssebba, imi kan qqaôen: "Mass nne$ d Öebbi". Lemmer ur Iswexxiô ara Öebbi imdanen, kra s kra, ara ipwahudden, war ccekk, d tiqwebtin, timezgida, lemûellat, lowamaâ ideg d smektayen, aîas, ism n Öebbi. Ih, Öebbi Ippaâwan win iT ippaâwanen. Öebbi, s tidep, d Uohid, d Uzmir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 41, 'Wid, ma Nessqâad iten di tmurt, bedden i téallit, pzekkin, ppamôen lewqama, gedlen tuccva. Ar Öebbi ara d gwrin lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 42, 'Ma skaddben k, ni$ skaddben, uqbel nnsen, igduden n Nuê, Âad, akked Tamud,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 43, 'agdud n Ibôahim, akked ugdud n Luî,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 44, 'At Madyan. Skaddben Musa. Fki$ lmudda i ijehliyen, sinna, Zzi$ d fellasen. A tuzzma W imiren!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 45, 'Acêal n temdinin ay Nesqucc imi densent. Haatent ppint. Xlan lebyar, akked lebruo uohiden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 46, 'Day ur unagen ara di tmurt? Ad sâun, $ef waya, ulawen ad fehmen yissen, imeééu$en ara islen yissen. Maca, maççi d allen, d ulawen deg idmaren i idre$len.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 47, 'B$an k a d tesqeôbev aâaqeb. Öebbi ur Ipzeggil lemâahda S, d awez$i. Ni$ ass, ar Mass ik, am agim iseggwasen, s leêsab nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 48, 'Acêal n temdinin iwumi Fki$ lmudda, u irna densent. Sinna, Zzi$ fellasent. £uôI tu$alin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 49, 'Ini: "a yimdanen! Nek, $uôwen, d aneddaô kan ipbegginen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 50, 'I wid iumnen, ixeddmen ayen ilhan, ssmaê akked ôôeéq ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 51, 'Wid iaânan asfunneg issekniyen nne£, widak d at ujajiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 52, 'Ur d Nuzen, uqbel ik, amazan ne$ nnbi, mebla ma ikecm ed Cciîan, deg wayen imenna, ma imenna. Itekkes Öebbi ayen d issekcam Cciîan, sinna, Itebbit issekniyen iS. Öebbi d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 53, 'Iwakken ad Irr aggway n Cciîan d ahewwel, i at wulawen iblan akked at wulawen aquôan. Ih, imednas atnan di t$ennant tu$miqt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 54, 'Iwakken ad éôen wid iwumi teppunefk tmusni, ar neppa d tidep, s$uô Mass ik. Ad amnen yis. Ad as anzen wulawen nnsen. Öebbi, s tidep, Inehhu wid iumnen, s abrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 55, 'Zgan wid ijehlen di ccekk fellas, ar ten id ias yimir, deqzalla, ne$ ibbwev iten id uâaqeb n wass abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 56, 'Assen, tagelda i Öebbi. Ad Iêudd garasen. Wid iumnen, ixeddmen ayen ilhan, ad ilin di Loennet n ssuâada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 57, 'I wid ijehlen, iskaddben issekniyen nne£, aâaqeb isdullun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 58, 'Wid iunagen, deg ubrid n Öebbi, sinna, pwan$an ne$ mmuten, a ten I$it Öebbi, war ccekk, s ôôeéq umâin. Ih, Öebbi Yif akw im$iten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 59, 'A ten Issekcem anekcum ara ôadin. Ih, Öebbi d Amusnaw, Iêellem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 60, 'Akka. Win iâaqben akken ippuâaqeb, sinna, ipwadnes, war ccekk, a t Isellek Öebbi. Ih, Öebbi Ipqili, Ipsemmiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 61, 'Akka, acku Öebbi Issekcam iv deg wass, Issekcam ass deg yiv. U Öebbi Issel, Ipwali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 62, 'Akka, acku Öebbi d tidep, ma d ayen u$uô pnujun, war Neppa, d tikerkas. Ih, Öebbi d Aâlâyan, d Ameqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 63, 'Day ur twalav ara Öebbi Isse$li d aman, seg igenni, d$a izzegzew wakal? Ih, Öebbi d Laîif, Iéôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 64, 'IneS i illan deg igenwan, i illan di tmurt. Ih, Öebbi, ar Neppa d Asâay d Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 65, 'Ur twalav ara Öebbi Inub ed fellawen s wayen illan di tmurt, akked lbabur ippazalen di yill, s lameô iS. Iîîef igenni ur d i$elli f tmurt, siwa ma Iunef as. Ih, Öebbi, war ccekk, Issuruf u Ipêunu i imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 66, 'D Neppa ikwen Issadren, sinna, ara kwen In$en, sinna, ara kwen id Issadren. Amdan, s tidep, d ajehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 67, 'I yal lois, Nefka asekkir, teddun degs. Ulay$eô i k pna$en $ef lameô. Nuj ar Mass ik; ih, aql ak, keçç, di nnhaya tuwqimt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 68, 'Ma numren k, ini: "Öebbi Yif akw akken Issen ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 69, 'Öebbi ad Iêudd garawen, ass n tnekra, $ef wayen tellam temgarradem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 70, 'Day ur teéôiv ara Öebbi Issen i illan deg igenni akked tmurt? Ayagi, s tidep, di Tezmamt. Ih, ayagi ishel i Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 71, 'La âabden, war Öebbi, ayen iwumi ur d Issers adabu, ayen ur ssinen. Imednas, ur illi wa ara ten isellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 72, 'Ma mlan asen issekniyen nne£ iberrzen, a pâaqlev asmmummi deg udmawen n wid ijehlen. Qôib ad éevmen $ef wid i sen iqqaôen issekniyen nne£. Ini: "a kwen xebbôe$ af wayen i$elben aya: times i Iâahed Öebbi i wid ijehlen". A tu$alin tucmip!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 73, 'A yimdanen! Ippunefk ed umedya, selt as d: ih, wid u$uô tepnujum, war Öebbi, ur zmiren, d awez$i, a d xelqen izi, xas mlalen $ef waya. Ma illa wayen i sen iuker yizi, ur zmiren ad as t id kksen. D uôhif umsuter, d uôhif win issuter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 74, 'Ur qudôen ara Öebbi, azal n lqedô iS. Ih, Öebbi d Uohid, d Uzmir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 75, 'Öebbi Iferren imazanen ger lmalayek, u ger imdanen. Ih, Öebbi Issel, Ipwali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 76, 'Issen i illan zdat sen, i illan deffir sen. Ar Öebbi ad u$alen lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 77, 'A wid iumnen! Ïîinzet u knut, âabdet Mass nnwen, xedmet lxiô, amar a prebêem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 78, 'Jahdet ar Öebbi lêeqq ujahed iS. Neppa Ifren ikwen. Ur kwen Ihejjen ara di ddin, ddin ubabat wen Ibôahim. Neppa, i wen isemman, zik, imvuâen. Deg waya, ad yili Umazan d anagi nnwen, u a ppilim d inagan n medden. Ihi, ééallet, zekkit, teîîfem di Öebbi. Neppa d Bab nnwen. D Bab amxallef, d Asellak amxallef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 1, 'Ni$ lmumnin rebêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 2, 'Wid ipéallan s wannuz;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 3, 'wid ijunben yir awal;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 4, 'wid ipzekkin;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 5, 'wid iêurben af tuzzuft nnsen', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 6, '- siwa ar tlawin nnsen, ne$ taklatin nnsen. Akka, ur degsen tiyta;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 7, 'wid ib$an sennig waya, widak zegren tilisa -,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 8, 'wid ipqadaren lamanat nnsen, u lemâahda nnsen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 9, 'wid iwennâen tiéilla nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 10, 'D wigi ay d iweôôaten,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 11, 'wid ara iweôten Loennet, degs ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 12, 'Ni$ Nexleq amdan, seg ufûil n talaxt,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 13, 'sinna, Nerra t d tiqqit deg umekkan n laman;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 14, 'sinna, tiqqit Nxelq ip d argen; d$a, argen Nxelq it d acelleqluq; d$a, acelleqluq Nxelq it d i$san; d$a, Nessels aksum i yi$san. Sinna, Nxelq it d lxelq amaynut. Ad Ibarek Öebbi, Imxeyyeô ixellaqen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 15, 'Sinna, deffir waya, war ccekk, a ppemmtem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 16, 'Sinna, ih, ass n tnekra, a d tu$alem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 17, 'Ni$ Nexleq, sennig wen, ûa iberdan. Ur Nelli, $ef uxlaq, seg i$wefliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 18, 'Nessader ed, seg igenni, aman s lmizan. Naâteq iten di tmurt. Nezmer a ten Nessôuê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 19, 'Nxelq awen, yissen, leonanat n tezdayin akked téuôin; degsen, i kunwi, aîas n yizwayen, teppeppem segsen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 20, 'Akked ttejôa, id iff$en seg udrar n Sina. Teppak ed zzit u ddhin, i wid iteppen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 21, 'Ih, di lmal, aselmed i kunwi. Nesswa kwen s wayen illan deg iâabbav nnsen. Aîas n uba$uô degsen, i kunwi. Teppeppem segsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 22, 'Fellasen, u $ef lbabuô, ppawin kwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 23, 'Ni$ Nuzen ed Nuê i ugdud is. Inna: "a yagdud iw! Âabdet Öebbi. Ur awen illi ôebbi, war Neppa. Day ur tepêezziben ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 24, 'Nnan imvebbôen ijehliyen, n ugdud is: "wagi d amdan kan, am kunwi; ib$a a d ikk sennig wen. Lemmer i S ihwi i Öebbi, a d Issers lmalayek. Ur nesli s waya, ar lejdud nne$ imezwura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 25, 'Neppa d argaz kan aôehbani. Qaôaâet ep, tallit kan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 26, 'Inna: "a Mass iw! Awes iyi, skaddben iyi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 27, 'Nweêêa yas d: "eûnaâ lbabuô, ger wallen nne£, s uweêêi nne£. Mi d iusa lameô nne£, la pfeggiven igwefran, d ihedman, awi degs, tayuga n yal ûûenf, akked twacult ik, siwa wid, segsen, i$ef id izwar wawal. Ur iyI d steqsay af wid idensen, nitni, war ccekk, ad pwa$evsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 28, 'Mi tâanncev di lbabur, keçç akked wid illan yidek, ini: ccekôan i Öebbi i $ Iselken seg ugdud imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 29, 'Ini: "a Mass iw! Ssers iyi deg umekkan iôqan; Keçç Tifev akw wid issrusun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 30, 'War ccekk, ayagi, d issekniyen, u Nekwni, Nezga d wid ipjeôôiben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 31, 'Sinna, Nxelq ed, deffir sen, isuta nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 32, 'Nuzen asen d amazan, segsen: "âabdet Öebbi, ur tesâim ôebbi, war Neppa. Day ur tepêezzibem ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 33, 'Nnan imvebbôen ijehliyen n ugdud is, wid iugin u inekôen timlilit n laxeôt, wid Ne$na di tmeddurt n ddunit: "wagi d amdan kan am kunwi, itepp seg wayen teppeppem, itess seg wayen teppessem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 34, 'Ma tessemêessem i umdan i kwen icban, war ccekk, kunwi seg imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 35, 'Day i wen iâahed ard a d teff$em mara temmtem, tu$alem d akal, d i$san?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 36, 'Ibâad, Ibâad, ayen i wen ippuwaââden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 37, 'I illan kan, d tameddurt n ddunit. A nemmet, a nidir, nekwni ur d neppenkar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 38, 'Neppa, d argaz kan id igren tikerkas $ef Öebbi. Nekwni, ur numin yis".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 39, 'Inna: "a Mass iw! Awes iyi, skaddben iyi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 40, 'Inna: "garane$ d cwiî, a d gwrin di nndama".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 41, 'Iwwet iten usu$u, s tidep. Nerra ten d rrmim. Err akin, agdud imednas!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 42, 'Sinna, Nxelq ed, deffir sen, isuta nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 43, 'Lois ur d isseqôab, ur iswexxiô, lajel is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 44, 'Sinna, Nuzen ed imazanen nne£, wa deffir wa. Yal tikelt ideg ara d ias umazan, ar lois is, a t skiddben. Nerra ten mestebâan, Nerra ten d tidyanin. Err akin, agdud ur neppamen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 45, 'Sinna, Nuzen ed Musa akked gma s Haôun, s issekniyen nne£, akked udabu n ûûeê,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 46, '$eô Ferâun akked imvebbôen is. Sme$wôen iman nnsen. Llan d agdud amzuxxi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 47, 'Nnan: "Day a namen sin imdanen am nekwni, u agdud nnsen d aklan nne$"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 48, 'Skaddben ten, d$a u$alen seg wid ipwan$an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 49, 'Ni$ Nefka Tazmamt i Musa, amar ad pwanhun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 50, 'Nerra mmi s n Meryem, akked imma s, d assekni. Nesduri ten di ti$ilt, degs laman d waman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 51, 'A yimazanen, eççet seg wayen imaânen, xedmet ayen ilhan, Nek, èôi$ ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 52, 'Lois agi nnwen, s tidep, d lois yiwen. Nek, d Mass nnwen, ihi êezbet iyI.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 53, 'Bvan lameô nnsen garasen, mi mfaôaqen. Yal akabar ifôeê s wayla s.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 54, 'Eoo iten di maylellif nnsen, tallit kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 55, 'Day $ilen mi sen Nefka ayla, tarwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 56, 'ad asen Nezzazal lxiô? Xaîi, ur faqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 57, 'Ih, wid, si tugwdi n Mass nnsen, pêadaren,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 58, 'wid iumnen s issekniyen n Mass nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 59, 'wid ur nepcarak i Mass nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 60, 'wid ippaken ayen fkan, ulawen nnsen ugaden mi, nitni, ad u$alen ar Mass nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 61, 'widak, pêirin ar lxiô u, $uôes, zeggwiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 62, 'Ur Nepkellif taôwiêt, siwa ar wayen iwumi tezmer. £uône£ Tazmamt, tessawal tidep. Nitni ur twadensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 63, 'Maca, ulawen nnsen di maylellif, $ef tagi. U rnan yir igiten i waya, a ten xedmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 64, 'Alamma, mi Nesâadda aâaqeb $ef isâayen nnsen, a d su$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 65, '"Ur psu$ut, ass agi, kunwi, segne$, ur tepwasellkem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 66, 'Ni$ mlan awen issekniyen iW, trewlem asen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 67, 'tesme$wôem iman nnwen fellasen. Teppaâwazem, tekkatem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 68, 'Day ur meyyzen ara Awal? Day ur ten id iusa ara, wayen ur d nusi ar lejdud nnsen imezwura?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 69, 'Ne$ day ur ssinen ara amazan nnsen, imi t nekôen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 70, 'Ne$ qqaôen: "ikcem it loenn"? Xaîi, iusa ten id s tidep. Tegwti degsen, kerhen tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 71, 'Lemmer tedda tidep d lhawiyyat nnsen, war ccekk, tamurt, igenwan, akked wayen illan degsen, ad fesden. Xaîi, Nebbwi yasen d asmekti nnsen. Nitni asmekti nnsen ooan t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 72, 'Ne$, ad asen tessutrev taqdiât? Ppif taqdiât n Mass ik. Neppa Yif akw iôeééaqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 73, 'Keçç, s tidep, la ten tneccdev s abrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 74, 'Wid ur numin ara s laxeôt, s tidep, ff$en i ubrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 75, 'Xas Nêun fellasen, u Nekkes asen ccqa nnsen, ad vellelen di leqheô nnsen, ad ddebdeben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 76, 'Ni$ Nesâadda fellasen aâaqeb. Ur knan i Mass nnsen, ur nujen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 77, 'Armi, mara asen Nelli tabburt uâaqeb iqesêen, imiren, degs, ad aysen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 78, 'Neppa i wen Ixelqen timesliwt, iéôi, ulawen. Drus ay tesnemmirem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 79, 'Neppa ikwen Iwezzâen di tmurt. £uôeS ara tepwafesrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 80, 'Neppa i Issidiren, i Ineqqen. IneS afraz n yiv akked wass. Day ur tefhimem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 81, 'Xaîi. Nnan akken d nnan imezwura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 82, 'Nnan: "Ma nemmut, nu$al d akal, d i$san, day a $ d ssekren?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 83, 'Ni$ ippuâahed wayagi i nekwni, akw, zik, i imezwura nne$. Ayagi, siwa d timucuha imezwura".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 84, 'Ini: "wi p ilan tmurt, akked wayen illan degs, ma tessnem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 85, 'A d inin: "d Öebbi". Ini: "ihi, day ur d tesmektayem ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 86, 'Ini: "anwa ay d Mass n ûa igenwan? Mass n usgeld ameqwôaêan"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 87, 'A d inin: "d Öebbi". Ini: "ihi, day ur tepêezzibem ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 88, 'Ini: "anwa i Isâan tagelda n yal cci, ger ifassen iS; Neppa Ipêarab, ur illi uêareb fellaS, ma teppissinem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 89, 'A d inin: "d Öebbi". Ini: "ihi, acimi tepwamelkem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 90, 'Xaîi! Nefka yasen tidep, nitni, war ccek, d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 91, 'Ur Isâi Öebbi mmi S. Ur illi ôebbi ar tama S. Mulac yal ôebbi ad iawi ayen id ixleq, wa ad iagwar wa. Gedha s Öebbi, seg wayen id snulfuyen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 92, 'Amusnaw n wayen iffren akked wayen ur neffir. D Aâlayan, sennig wayen pcaraken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 93, 'Ini: "a Mass iw! Lemmer a yi d Tesseknev acu i sen ippuâahden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 94, 'A Mass iw, ur iyi Ppara deg ugdud imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 95, '"S tidep, Nezmer ad ak Nessken acu i sen Nâahed".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 96, 'Err akin tucmip s lfayeq. Nekwni Neéôa, sennig wiyav, ayen d snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 97, 'Ini: "a Mass iw! Ëerz iyi seg u$wayen n ccwaîen. Êë', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 98, 'Ëerz iyi, a Mass iw! Ur dgi ppilin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 99, 'Armi, mi d tusa tmeppant yiwen degsen, inna: "a Mass iw! Err iyi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 100, 'amar ad xedme$ ayen ilhan deg wayen ooi$". Xaîi, d awal kan id inna. Tella, deffir es, tse$lit, alamma d ass n tnekra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 101, 'Ma ûuven di lbuq, assen, ur ppemyilin, ur pmesteqsayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 102, 'Wid iwumi ééay lmizan nnsen, nitni rebêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 103, 'Wid iwumi fessus lmizan nnsen, d nitni i issexsôen iman nnsen. Di Loahennama ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 104, 'A ppesser$ tmes udmawen nnsen, ad asen zelgen icenfiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 105, 'Day ur awen qaren ara issekniyen iW, wanag la ten tnekôem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 106, 'Nnan: "a Mass nne$! I$leb ane$ ccum nne$. Nella d agdud im$eôqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 107, 'A Mass nne$! Ssuffe$ ane$ segs. Ma nesnager, ihi, d imednas ay nella".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 108, 'Ad Yini: "qqimet degs, ur pmeslayet"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 109, 'Ih, illa urbaâ n imdanen iW i iqqaôen: "a Mass nne$! Numen. Semmeê ane$, Ëun fella$, Keçç Tifev akw wid ipêunun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 110, 'Tettihim fellasen armi i wen sseppun asmekti W, u tdessem degsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 111, 'Nek, assa, Kufa$ ten $ef wayen ûebôen. D nitni, war ccekk, ay d imerbaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 112, 'Inna: "acêal iseggwasen i teqqimem deg wakal"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 113, 'Nnan: "Neqqim ass, ne$ ur ibbwiv wass, steqsi wid iêepben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 114, 'Inna: "cwiî kan ay teqqimen, lemmer, s tidep, day tessinem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 115, 'Day t$ilem Nxelq ikwen, kan, di rrayaâ; ar ur d teppu$alem $uône£?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 116, 'Ay Meqqweô Öebbi, Agellid, Tidep! Ur illi ôebbi, siwa Neppa, Mass n usgeld ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 117, 'Win inaâôen, ar tama n Öebbi, ôebbi nniven, ur isâi ppbut fellas, aqeîîi s ar Mass is kan. Ih, ur rebêen ara ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 118, 'Ini: "a Mass iw! Semmeê u Ëun. Keçç, Tifev akw wid ipêunun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 1, 'Tasurep, Nessader ip id, Nêeppem ip id; Nessader ed, degs, issekniyen iberrzen, amar a d temmektim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 2, 'Tin ne$ win iznan, jekwvet, yal yiwen segsen, tawinest iberdan; ur kwen p$aven $ef udem n Öebbi, ma tellam tumnem s Öebbi akked wass aneggaru. Arbaâ n lmumnin, ad yili d anagi uâaqeb nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 3, 'Win iznan ur ippa$ siwa tin iznan, ne$ tamcarekt. Tin iznan ur p ippa$ siwa win iznan, ne$ amcarek. Ipwagdel waya i lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 4, 'Wid itehmen tiâaôviyin, d$a ur d bbwin kué inagan, jekwvet pen îamet iberdan; ur qeblet ccada nnsen, d awez$i. Widen d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 5, 'Kkes ed wid isteôoâen, deffir waya, u xedmen lfayeq. Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 6, 'Wid itehmen tilawin nnsen, ur sâin inagan, siwa iman nnsen, yiwen segsen ad iggal s Öebbi, kué iberdan, ar neppa d bab n tidep,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 7, 'akked ubrid wis smus ar a t Ixzu Öebbi ma iskaddeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 8, 'Ur teppuâaqeb tmeîîut, ma teggul s Öebbi, kué iberdan, ar neppa seg wid iskadben,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 9, 'akked ubrid, wis smus ar fellas zzâaf n Öebbi, ma issawel ed tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 10, 'A lemmer ur illi fellawen lfevl n Öebbi akked uêunu S! Öebbi, s tidep, Issuruf, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 11, 'Ih, wid isweûlen tikerkas, d agraw segwen. Ur p$ilit d cceôô i kunwi, xaîi, d lxiô nnwen. Yal yiwen, degsen, ibbwi ayen ibbwi ubekkav. Aâaqeb abarar i win, segsen, i ibbwin amur ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 12, 'A lemmer lmumnin, argaz tameîîut, mi s slan, meyyzen lxiô, deg iman nnsen, u nnan: "wagi d tikerkas ibanen"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 13, 'A lemmer d bbwin, fellas, kué inagan! Ma ur d bbwin ara inagan, ar Öebbi, wigi, d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 14, 'Lemmer ur illi fellawen lfevl n Öebbi akked uêunu S, di ddunit akked laxeôt, a ppesâaddim aâaqeb abarar $ef wayen i$ef temcawaôem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 15, 'Mi p id teggarem s yilsawen nnwen, u teqqaôen s imawen nnwen ayen ur tessinem, t$ilem d ulac. Neppa, ar Öebbi, d abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 16, 'Lemmer, mi as teslam, tennam: "ur a$ issefk ara umeslay $ef waya! Gedha s yiseK! Wagi d acehrir abarar".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 17, 'Inuba kwen Öebbi ur teppalsem, am akka, d awez$i, ma d lmumnin ay tellam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 18, 'Ipbeggin awen Öebbi issekniyen. Öebbi d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 19, 'Ih, wid ib$an a d iazel lâaô, ar wid iumnen, fellasen aâaqeb aqeôêan di ddunit, di laxeôt. Öebbi Issen, kunwi ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 20, 'A lemmer ur illi fellawen lfevl n Öebbi akked uêunu S! U Öebbi d Umâin, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 21, 'A wid iumnen! Ur teddut di lateô n Cciîan. Win iteddun di lateô n Cciîan, ar la iteddu di lâaô akked tuccva. Lemmer ur illi fellawen lfevl n Öebbi akked uêunu S, ur ippizdig degwen yiwen, d awez$i. Maca, Öebbi Izzizdig win i S ihwan. Öebbi Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 22, 'Wid, degwen, iwumi ippunefk lfevl akked terkunt, ur pgalan $ef tikci i llzem, i ime$ban, i wid iunagen deg ubrid n Öebbi. Ad semmêen, ad ssurfen. Day ur têemmlem ara mara awen Isemmeê Öebbi? Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 23, 'Ih, wid ipqeôôiven tilawin zeddigen, istehzan, iumnen, ad pwaxzun di ddunit, di laxeôt. Fellasen aâaqeb abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 24, 'Ass ideg ara d cehhden $ef igiten nnsen, ilsawen nnsen, ifassen nnsen, ivaôen nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 25, 'assen, ad asen Ifk Öebbi ayen ppalasen, s tidep. Ad éôen ar Öebbi d Tidep ibanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 26, 'Yir tlawin i yir irgazen, yir irgazen i yir tlawin. Tilawin n lâali i irgazen n lâali, irgazen lâali i tlawin n lâali. Wigi ur ppkan deg wayen qqaôen. I nitni, ssmaê akked ôôeéq ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 27, 'A wid iumnen! Ur keçmet ixxamen ur nelli nnwen, alamma s tsriê, u alamma tselmem $ef imawlan nnsen. Ppif akka i kunwi, amar a d tesmektim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 28, 'Ma ur tufim êedd degsen, ur keçmet alamma s tsriê. Ma nnan awen d: "u$alet", u$alet. Yif it wakka i ûûfawa nnwen. Öebbi Iéôa ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 29, 'Ulac u$ilif fellawen ma tkecmem ixxamen ur nepwazde$, ma tella t$awsa nnwen degsen. Öebbi Iéôa acu d teqqaôem, u wacu teppeffrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 30, 'Ini i wid iumnen ad brun i wallen nnsen, ad ssôen tuzzuft nnsen. Yif it wakka i ûûfawa nnsen. Öebbi, s tidep, Iéôa ayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 31, 'Ini i tid iumnen ad brunt i wallen nnsent, ad ssôent tuzzuft nnsent, ur d sskanent, di zzin nnsent, siwa ayen d ivehôen segs, ad $umment idmaren nnsent. Ur d sskanent ccbuê nnsent, siwa i irgazen nnsent, ne$ ibabaten nnsent, ne$ im$aôen nnsent, ne$ iqcicen nnsent, ne$ irbiben nnsent, ne$ atmaten nnsent, ne$ iqcicen n watmaten nnsent, ne$ wid n tsetmatin nnsent, ne$ tiqeddacin nnsent, ne$ taklatin nnsent, ne$ iqeddacen imudduzen, ne$ arrac ur nelleméi. Ur kkatent dderz, ad ipwassen zzin nnsent uffir. Steôoâet akw i Öebbi, a lmumnin, amar a prebêem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 32, 'Jewoet i iâzriyen nnwen, akked wid imaânen seg waklan nnwen, akked teklatin nnwen. Ma d ime$ban ay llan, a ten Iôéeq Öebbi, s lfevl iS. Öebbi d Ajemmal, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 33, 'Wid ur nufa ara ar a$en, ad ûebôen ar ten id Iôéeq Öebbi, s lfevl iS. Wid, seg waklan nnwen, i ib$an ad asen tarum aserreê, arut asen ma teéôam ten, d at lxiô ay llan. Fket asen seg ayla i wen Ifka Öebbi. Ur pêeppimet $ef teklatin nnwen, tiquêbit, i rrbeê nnwen di tmeddurt n ddunit, ma b$ant tezdeg. Ma têeppmen, Öebbi, deffir uêeppem nnsent, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 34, 'Ni$ Nessader awen ed issekniyen iberrzen, akked umedya n wid iâacen uqbel nnwen, d anabi i wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 35, 'Öebbi d tafat n tmurt akked igenwan. Amedya n tafat iS d takwap degs taftilt. Taftilt daxel n tqeôâap. Taqeôâap, amzun d itri acôaôaq, tecâal it ttejôa iôqan, tazemmurt ur nelli n ugmuv ne$ n utaram. Qôib a pfet zzit is, ur p tennul tmes. Tafat $ef tafat. Ippawi Öebbi win i S ihwan ar tafat iS. Ippak ed Öebbi imedyaten i medden. Öebbi Iéôa yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 36, 'Deg ixxamen i Ib$a Öebbi ad ufraren, ideg ara d immekti yisem iS, sbuccuâen T ssbeê, tameddit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 37, 'Irgazen ur tes$afal ttjaôa, ne$ ssuq, $ef usmekti n Öebbi, $ef téallit, $ef zzakat; ppagwaden ass, ideg ara nehwwalen wallen akked wulawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 38, 'Iwakken a ten Ikafi Öebbi $ef wayen xeddmen d amxallef, ad asen Irnu si lfevl iS. Öebbi Ip$iti win i S ihwan, war aktili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 39, 'Igiten n wid ijehlen, am aylal deg uza$aô. Win ifuden, ad i$il d aman. Alamma mi ibbwev $uôes, ur ippaf acemma. A n iaf Öebbi, Issuli as leêsab is. Öebbi Ip$awal deg uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 40, 'Ne$ am tillas di yill le$miq. T$umm it lmuja, sufella lmuja, sufella asigna. Tillas sennig tiyav. Ma issuffe$ ed afus is, ur issawev a t iwali. Win iwumi ur Iga ara Öebbi tafat, ur isâi tafat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 41, 'Day ur twalav ara, sbuccuâen Öebbi i illan di tmurt akked igenwan? Ifrax deg waffug. Issen taéallit akked usbuccaâ n yal yiwen. Öebbi Iéôa ayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 42, 'N Öebbi tagelda n tmurt akked igenwan. £uô öÖebbi tu$alin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 43, 'Ur twalav ara Öebbi Isselêay asigna, sinna, a t Izdi, sinna, a t Issem$weô? D$a a pwaliv ageffur a d iffe$ si zdaxel is. Isrusu d, seg idurar igenni, abruri. Ad Iwwet yis, win i S ihwan, a t Iveôôef $ef win i S ihwan. Tafat n lebôaq iS qôib a ppeglu s yiéôi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 44, 'Öebbi Ismizwar iv akked wass. Deg wayagi, s tidep, d aselmed i wid isâan iéôi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 45, 'Öebbi Ixleq akw lêayawan, seg waman. Garasen, illa win ippeênunufen $ef uâabbuv is, win ileêêun $ef sin ivaôôen, win ileêêun $ef kué. Ixelleq Öebbi ayen i S ihwan. Öebbi, s tidep, Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 46, 'Ni$ Nessader ed issekniyen iberrzen. Öebbi Inehhu win i S ihwan, ar ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 47, 'Qqaôen: "numen s Öebbi akked Umazan, nu$ awal". Sinna, deffir waya, iwexxeô urbaâ segsen. Wigi ur llin d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 48, 'Mi pwanecden ar Öebbi akked Umazan iS, ad Iêudd garasen, arbaâ segsen iwexxeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 49, 'Ma sâan lêeqq, a d asen $uôes, d imvuâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 50, 'Day helken wulawen nnsen, ne$ cukken, ne$ ugaden a ten Isneêyaf Öebbi akked Umazan iS? Xaîi, widak d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 51, 'Timenna n lmumnin, mara ssutren aêuddu n Öebbi akked Umazan iS, ad Iêudd garasen, d tigi kan: "nesla, nôuva". D wigi ay d imerbaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 52, 'Win iôuvan Öebbi akked Umazan iS, ippagwaden Öebbi, ipêezziben, nitni d isaâdiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 53, 'Ggulen s Öebbi, tagallit meqqwôen, ar ma tumôev asen, ard ad ff$en, war ccekk. Ini: "ur pgallat, annuz ipwassen. Öebbi, s tidep, Iéôa ayen txeddmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 54, 'Ini: "ôavit Öebbi, ôavit Amazan". Ma wexxôen, fellas, neppa, ayen kan i s sbabben, fellawen kunwi ayen i wen sbabben. Ma tôuvam T, a ppeppwanhum. I iwatan i Umazan, siwa awal ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 55, 'Iâahed Öebbi, i wid iumnen segwen, u xedmen ayen ilhan, ara ten Irr, war ccekk, d igensas di tmurt, akken Irra wid i ten id izwaren; ara ad asen Isseqâad ddin nnsen i$ef i ten Iôuva; ar ad asen Issegwri laman, deffir tugdi. Âabden iyI, ur iyI pcaraken acemma. Wid ijehlen, deffir waya, widak d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 56, 'Beddet i téallit, zekkit, a$et awal i Umazan. Amar aêunu fellawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 57, '£uôwat a p$ilem wid ijehlen sfunnugen di tmurt. Axxam nnsen d times. A tu$alin tucmip!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 58, 'A wid iumnen! S uâammed nnwen ara d kecmen, $uôwen, waklan nnwen akw wid, degwen, ur nebli$ ara, krav iberdan ideg ur telsim ara: uqbel taéallit n tafrara, $ef îîhuô mara tekksem iceîîiven, deffir téallit n lâica. Ulac u$ilif fellawen ne$ fellasen, ma wa iéuô wa, deffir lewqat agi. Akka i wen d Ibeggen Öebbi issekniyen. Öebbi Iéôa, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 59, 'Ma bel$en warrac nnwen, s uâammed nnwen, am wid i ten id izwaren. Akka i wen d Ibeggen Öebbi issekniyen iS. Öebbi Iéôa, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 60, 'Ulac u$ilif $ef tâuqaô i iâaddan i jwao, ma kksent iceîîiven nnsent, mebla ma sseknent ccbuê nnsent. Ma setêant, yif it i nitenti. Öebbi Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 61, 'Ur telli tiyta deg uder$al, ne$ deg urejdal, ne$ deg umuvin, ne$ degwen, ma teççam deg ixxamen nnwen, deg wid n ibabaten nnwen, deg wid n tyimmatin nnwen, deg wid n watmaten nnwen, deg wid n tsetmatin nnwen, deg wid iâammiten nnwen, deg wid n tâammitin nnwen, deg wid ixaliten nnwen, deg wid n txaltitin nnwen, deg wid ideg tesâam tisura, ar uêbib nnwen. Ulac u$ilif fellawen ma teççam d agraw, ne$ d ifôiden. Mara tkecmen ixxamen, msalamet s wazul iôqan, aêmayan, s$uô Öebbi. Akka i wen d Ibeggen Öebbi issekniyen. Amar a pfehmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 62, 'Lmumnin, siwa wid iumnen s Öebbi akked Umazan iS. Ma llan yides $ef lameô iten icerken, ur pôuêun alamma ssutren as tsriê. Ih, wid i k issuturen tsriê, d nitni i iumnen s Öebbi akked Umazan iS. Ma ssutren ak tsriê, $ef kra iten iaânan, serreê i win i k ihwan, segsen. Ssuter i Öebbi ad sen Isemmeê. Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 63, 'Ur êepbet asiwwel garawen i Umazan, am mara temsawalem. Ih, Iéôa Öebbi wid, segwen, ippensaren s tuffra. Ad steêdren wid mgirrden lameô iS: ad ppuhewwlen, ne$ ad sâaddin aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 64, 'Ih, day maççi n Öebbi, i illan di tmurt akked igenwan? Ni$ Iéôa amek tellam $uôeS. Ass n tu$alin nnsen $uôeS, ad asen Imel d acu xedmen. Öebbi Issen yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 1, 'Ad Iôqu Win id Issadren afraz, i umdan iS, iwakken ad yili d aneddaô imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 2, 'Win Ilan tagelda n tmurt akked igenwan; ur Isâi mmi S; ur aS illi ucrik di tgelda. Ixleq yal cci, Iwezn it s lmizan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 3, 'Ddmen, war Neppa, iôebbiten ur nexliq acemma. D nitni i ipwaxelqen. Ur pseyyin vveô ne$ aba$uô, i iman nnsen. Ur pseyyin di tmeppant ne$ di tmeddurt, ne$ di tnekra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 4, 'Nnan wid ijehlen: "ayagi, d tikerkas kan. Isnulfa tent id, iâawen it, fellas, ugdud nniven. Ni$ densen u skaddben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 5, 'Nnan: "d timucuha imezwura, i iura; qqaôen as tent ûûbeê, tameddit".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 6, 'Ini: "Issader it id, Win Issnen sser n tmurt akked igenwan. Neppa, s tidep, Izga Ipsemmiê, Ipêunu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 7, 'Nnan: "d acut Umazan agi i iteppen lqut, iteddun ar leswaq? A lemmer id irs $uôes lmelk, ara yilin yides d aneddaô,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 8, 'ne$ ippunefk as ugerruj, ne$ isâa aqwiô itepp segs"! Nnan imednas: "la teppeddum kan d urgaz iwumi sseêren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 9, 'Wali amek id ppaken fellak imedyaten. Nnetlafen, ur zmiren ad pwanhun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 10, 'Ad Iôqu Win ad ak Ifken, ma Irad, i ifen ayagi: leonanat, ddawat sen isaffen ppazzalen. Ad ak Issali lebôuo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 11, 'Xaîi, nekôen imir. Nhegga d times i win inekôen imir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 12, 'Mi ten twala si tama ibaâden, ad as slen s leêôaôa akked zzhir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 13, 'Mara $lin degs, nitni pwarzen deg umekkan uqmiv, ad siwlen, dinna, i wangar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 14, '"Ur ssawalet ara, assa, i yiwet n wangar, ssiwlet i waîas n wangaren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 15, 'Ini: "ppif ayagi, ne$ Loennet n lebda i Nâahed i wid ipêezziben? D neppat ay d arraz, ay d taggara, i nitni".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 16, 'I nitni degs, ayen i sen ihwan, i lebda. D lemâahda i$ef Iuksan Mass ik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 17, 'Ass ideg ara ten Ifser, nitni akked wid âabden, war Öebbi, ad Yini: "d kunwi i itelfen imdanen iW agi, ne$ d nitni i iff$en abrid"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 18, 'A d inin: "gedha s yiseK! Ur a$ issefk a neddu d bab, war Keçç. Maca, T$atev ten, nitni akked imezwura nnsen, armi ppun asmekti, u$alen d agdud ixeûôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 19, 'Atan nekôen kwen $ef wayen d tennam. Ihi ur tezmirem i tsensert, ne$ i leslak. Win idensen, degwen, a Nessukk fellas, aâaqeb ameqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 20, 'Ur d Nuzen, uqbel ik, imazanen, mebla ma llan teppen lqut, u teddun ar leswaq. Nerra kwen, wa ihewwel wa, ma a pûebôem. Mass ik Izga la d Ismuqul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 21, 'Nnan wid ur nessarem ara timlilit yidne£: "a lemmer id ssersen lmalayek $uône$, ne$ nwala Mass nne$"! Ni$ sme$wôen aîas iman nnsen, u ffuhrin aîas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 22, 'Ass ideg ara walin lmalayek, ur ippili wassen d abecceô ibe$wviyen, s lxiô. A d inin: d aêdid ur nepwazgar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 23, 'Nezzi $eô igiten nnsen, Nerra ten d a$ebbaô immebruzzâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 24, 'Imawlan n Loennet, assen, di tnezdu$t akked trusi iufraren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 25, 'Ass ideg ara iceqqeq igenni s usigna, ideg ara d ssersen lmalayek, ta deffir ta,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 26, 'tagelda, assen, tidep, i Uênin. D ass uwâiô i ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 27, 'Ass ideg ara i$eéé umednus ifassen is, ad yini: "a yamxix iw, a lemmer ddi$ d ubrid Umazan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 28, 'A tawa$it pwa$e$, a lemmer ur rri$ ara winnat d aêbib!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 29, 'Ni$ itelf iyi seg usmekti i illan iusa yi d. Cciîan, i umdan, izga d axeddaâ".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 30, 'Inna Umazan: "a Mass iw! Ar ugdud iw, s tidep, Leqwôan agi d askeôfeé".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 31, 'Akka, i yal nnbi, Nefka acengu seg ibe$wviyen. Iqadd Mass ik, i nnhaya akked usellek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 32, 'Nnan wid ijehlen: "a lemmer i s d ssersen Leqwôan, deg yiwet n tikelt"! Akka, iwakken a Ntebbet ul ik, yis. Nesemderri t d idurra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 33, 'Ur ak d ppawin amedya, mebla ma Nuzen ak d tidep, akked ufesser amxallef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 34, 'Wid ara ipwafesren af udmawen nnsen, ar Loahennama, widak d at umkan n dir mavi, d at ubrid im$eôôeq mavi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 35, 'Ni$ Nefka yas Tazmamt i Musa, u Nerna $uôes gma s, Haôun, d am²âiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 36, 'Nenna: "ôuêet ar ugdud i inekôen issekniyen nne£". Nhudd iten qeccuc meccuc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 37, 'Agdud n Nuê, mi nekôen imazanen, Ne$ves iten, u Nerra ten d assekni i medden. Nhegga i imednas aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 38, 'Âad, Tamud, At Öôas, u aîas isuta garasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 39, 'I yal wa, Nefka imedyaten. Yal wa, Neôéa t wakali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 40, 'Ni$ âaddan $ef taddart i$ef id i$li ugeffur ageswaê. Day qqimen ur p walan ara? Xaîi, ur ssaramen ara tanekra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 41, 'Mi k walan, ppemsexxiôen kan fellak: "day d wagi id Iuzen Öebbi, d Amazan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 42, 'Qôib i $ itlef seg iôebbiten nne$, lemmer ur neûbiô fellasen". Deqqal ad éôen mara walin aâaqeb, anwa i innetlafen, kteô, seg ubrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 43, 'Twalav win i irran lhawiyya s d ôebbi s? Day ad as tiliv, keçç, d awkil?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 44, 'Day t$ilev tegwti, segsen, sellen ne$ fehmen? Nitni am lmal kan, aâer $elben ten akken nnetlafen seg ubrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 45, 'Ma twalav Mass ik, amek id Ifka tili? Lemmer i S ihwi, Irra p d tusbiî. D$a Nefka yas itij d ppbut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 46, 'Sinna, Njebd ip id $uône£, ajbad isehlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 47, 'D Neppa i wen Irran iv d aceîîiv, ives d areyyeê, u Irra ass d tanekra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 48, 'D Neppa i wen d Iuznen avu, d abecceô s uêunu S. Nessers ed, seg igenni, aman iûfan;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 49, 'iwakken a Neêyu yissen tamurt immuten; a Nessew yissen aîas seg wid id Nexleq n lmal, akked imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 50, 'Ni$ Nfeôq iten garasen, iwakken a d mmektin. Tegwti n yimdanen ugin; atnan kan di tijehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 51, 'Lemmer i £ ihwi, yili Nuzen aneddaô, i yal tamdint.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 52, 'Ur ppa$ awal i ijehliyen. Nna$ iten yis, amennu$ ameqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 53, 'D Neppa i Issemfaôaqen sin ilellen, yiwen êlaw, d aéidan, wayev ôéag, d ameô$an. Irra, garasen, agadir, aêdid ur nepwazgar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 54, 'D Neppa i Ixelqen amdan seg waman. Ifka yas laâmum, lexwal. Mass ik Izga d Win Izemren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 55, 'La âabden, war Öebbi, ayen ur ten inefâan, ur ten ivuôôen. Ajehli, ar loiha n Mass is, izga d win issefôa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 56, 'Nuzen ik id kan, i ubecceô d uneddeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 57, 'Ini: "ur awen ssutre$, $ef waya, kra n teqdiât. Ssutre$ kan, i win ib$an, ad ia$ abrid $eô Mass is".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 58, 'Ppkel $ef Umuddir ur Nepmeppat. Sbuccaâ iT s ccekôan. Iqadd i tussna ibekkaven n imdanen iS.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 59, 'I Ixelqen tamurt, igenwan, akked wayen illan garasen, di sdis wussan. Sinna, Aênin Iâannec af usgeld. Steqsi w iT issnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 60, 'Ma pwanecden: "knut i Uênin"! A d rren: "d acu T Uênin? Day a neknu i w ara $ d tamôev"? D a$unfu i sen irna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 61, 'Ad Iôqu Win Irran itran deg igenni. Irna degs, lefnaô, akked waggur bu tziri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 62, 'D Neppa i Irran iv akked wass mestebâan, i win ib$an ad ismekti, ne$ ib$an ad isnemmer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 63, 'Ixdimen n Uênin, i ileêêun di tmurt di lehna, ma numren ten at war tussna, qqaôen: "tifrat"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 64, 'I ippaâwazen i Mass nnsen, knan ne$ bedden;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 65, 'I iqqaôen: "a Mass nne$! Veôôef segne$ aâaqeb n Loahennama. Ih, aâaqeb is ipwaêeppem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 66, 'Neppat, s tidep, d tadirant, i tnezdu$t akked i$imi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 67, 'Wid, ma seôôfen, ur veggiâen, ur pcuêêun: igi iwulmen atan garasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 68, 'Wid ur nenâaô ôebbi nniven, ar tama n Öebbi. Ur neqqen amdan, d ayen Igdel Öebbi, siwa $ef tidep. Ur zennun. Win ixedmen ayagi, ibbwi ibekkaven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 69, 'Ad ippuâaqeb berdayen, ass n tnekra. Ad iwekkeô d imdelli;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 70, 'siwa win isteôoâen, iumnen, ixeddmen ayen ilhan. I wigi, ad Inûef Öebbi tucmitin nnsen, s yise$iyen. Öebbi Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 71, 'Win isteôoâen, ixeddmen ayen ilhan, ihi, iutub Öebbi s ppuba n tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 72, 'Wid ur ncehhed ccada n rrya; u, ma mmugren tifukal, ddan d ukyisen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 73, 'Wid, mara asen d smmektin issekniyen n Mass nnsen, ur d neggar tiâéegt ne$ tider$elt fellasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 74, 'Wid iqqaôen: "a Mass nne$! Err tilawin nne$, akked dderya nne$, d ssuâada n wallen. Err ane$ d wid inehhun wid ipêezziben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 75, 'Widak ad ppuoazin s t$uôfatin, ilmend n wayen ûebôen. Ad magren, dinna, azul, tifrat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 76, 'Dinna, ad wekkôen, d amkan amxalef i tnezdu$t d i$imi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 77, 'Ini: "ur d Irezzu Mass iw, degwen, ma ur tnujem $uôeS. Ni$ tnekôem? Ad iu$al waya d ayen ilezmen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 1, 'Ïsm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 2, 'Atnan issekniyen n Tezmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 3, 'Ahat tqelqev iman ik, imi ur ppilin d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 4, 'Ma ihwa ya£, ad asen d Nessers assekni seg igenni, ad îinzent, zdat es, tmegôav nnsen, s wannuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 5, 'Ur ten id ippas usmekti amaynut, s$uô Uênin, mebla ma u$alen as d inekkaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 6, 'Ni$ skaddben. Ihi, ad asen d asen isallen, $ef wayen i$ef pmmaâliken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 7, 'Day ur walan ara tamurt? Acêal i Nessenker degs n yal tayuga tukyist!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 8, 'Deg wayagi, s tidep, assekni. Tegwti degsen, ur llin d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 9, 'Mass ik, s tidep, Neppa, d Uzmir, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 10, 'Mi Issawel Mass ik, i Musa: "ôuê s agdud imednas,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 11, 'agdud n Ferâun. Day ur ppezziben ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 12, 'Inna: "a Mass iw! Nek ugade$ ad iyi skiddben,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 13, 'ad sekkwôen idmaren iw, ur ipserriê yiles iw. Ihi, Azen ar Haôun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 14, 'U denbe$ $uôsen. Ugade$ ad iyi n$en".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 15, 'Inna: "Xaîi, ôuêet s issekniyen nne£. Aql a£ yidwen, Nessemêas en. Ôö', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 16, 'Öuêet ar Ferâun, tinem as: "nekwni d amazan n Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 17, 'Seddu, yidne$, At Isôail".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 18, 'Inna: "day ur k nôebba ara $uône$, d llufan? U tesâaddav $uône$, iseggwasen di lâameô ik;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 19, 'u txedmev igi txedmev. Keçç, seg ijehliyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 20, 'Inna: "xedme$ t asmi lli$ seg im$eôôqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 21, 'Rewle$ segwen, mi kwen ugade$. Ifka yi Mass iw, ûûwab. Irra yi seg imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 22, 'D l$it agi, i$ef a yi teppezzmev, i k ibbwin a pperrev, At Isôail, d aklan"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 23, 'Inna Ferâun: "d acu T Mass imavalen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 24, 'Inna: "d Mass n tmurt, igenwan, akked wayen illan garasen, ma tetebbtem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 25, 'Inna i wi s d izzin: "la tsellem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 26, 'Inna: "Mass nnwen, u Mass n lejdud nnwen, imezwura".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 27, 'Inna: "s tidep, amazan nnwen id ippuceggâen $uôwen, d aôehbani".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 28, 'Inna: "Mass n ugmuv, utaram, akked wayen illan garasen, lemmer tefhimem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 29, 'Inna: "ma tedmev Öebbi, ur nelli d nek, a k nerr ar lêebs".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 30, 'Inna: "i lemmer ad ak d awi$ ayen ipbegginen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 31, 'Inna: "awi t id, ma d tidep ay tessawalev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 32, 'Iveggeô taâkwazt is, tu$al d azrem n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 33, 'Issuffe$ ed afus is, d$a d amellal i imfeôoen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 34, 'Inna i imvebbôen i s d izzin: "wagi, s tidep, d aseêêar amusnaw;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 35, 'ib$a a kwen issuffe$, s ssêur is, seg wakal nnwen. D acu t lameô nnwen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 36, 'Nnan: "sgani t, neppa akked gma s; azen ineccaden ar temdinin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 37, 'ad ak d awin yal aseêêar amusnaw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 38, 'Mlalen iseêêaren, di lweqt akked wass ipwassnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 39, 'Nnan i imdanen: "ma ad tenjemâam?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 40, 'Ahat a neddu d iseêêaren, ma d nitni ara irebêen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 41, 'Mi d usan iseêêaren, nnan as i Ferâun: "ma ad a$ tili teqdiât, ma nerbeê"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 42, 'Inna: "ih, d$a, kunwi, war ccekk, a ppu$alem seg iqôiben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 43, 'Inna yasen Musa: "veggôet ayen ara tveggôem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 44, 'Veggôen imraren akked tâakwzin nnsen. Nnan: "s tezmert n Ferâun, ard nekwni ara irebêen"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 45, 'Iveggeô Musa taâkwazt is. Apan tesseblaâ ayen id snulfan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 46, 'Iseêêaren $lin, knan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 47, 'Nnan: "numen s Mass imavalen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 48, 'Mass n Musa akked Haôun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 49, 'Inna: "tumnem yiS, uqbel ma serrêe$ awen? Neppa, war ccekk, d ameqwôan nnwen i wen issêefven ssêur. A ppeéôem, ad awen gezme$ afus sya, avaô sya; a kwen ûûemôe$ akw $ef umidag".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 50, 'Nnan: "ulac u$ilif, acku ar Mass nne$, ara nezzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 51, 'Ih, nessaram ad Isemmeê, Mass nne$, tuccva nne$ imi aql a$ d lmumnin imenza".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 52, 'Nweêêa i Musa: "ôôuê s ugdud iW, deg iv, acku a kwen in vefôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 53, 'Iuzen Ferâun ineccaden ar temdinin:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 54, '"wigi, s tidep, d arbaâ amejîuê,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 55, 'u nitni, s tidep, sserfan a$".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 56, 'Nekwni, Neqquôa akken ma nella.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 57, 'Ihi, Nessuffe$ iten id si tebêirin akked tliwa;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 58, 'igerrujen, ixxamen ukyisen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 59, 'Akka, nweôôet yissen, At Isôail.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 60, 'Vefôen ten mi d inqeô yiîij.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 61, 'Mi mwalan irebbuyaâ, nnan imeddukwal n Musa: "aql a$ a nepwalêeq".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 62, 'Inna: "xaîi! Mass iw, s tidep, yidi. Ad iyi Inhu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 63, 'Nweêêa i Musa: "wwet ill s taâkwazt ik"! Imfaôaq, yal loiha am udrar ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 64, 'Nessqeôb ed wiyav ar dinna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 65, 'Nsellek Musa, akked wid akw iddan yides.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 66, 'Sinna ne$ôeq wiyav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 67, 'Deg wayagi, s tidep, d assekni. Tegwti degsen ur uminen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 68, 'Mass ik, s tidep, Neppa, d Uzmir, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 69, 'Eêku yasen d tamacahup n Ibôahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 70, 'Mi inna i baba s akked ugdud is: "d acu tâabdem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 71, 'Nnan: "naâbed tiâancuôin, mazal a tent njjem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 72, 'Inna: "day awen d sellent, ma tnujem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 73, 'Ne$ nefâant kwen, ne$ vuôôent kwen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 74, 'Nnan: "xaîi, nufa d imezwura nne$, akka ay xeddmen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 75, 'Inna: "day twalam ayen la tâabdem,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 76, 'kunwi akked lejdud nnwen imenza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 77, 'Nitni d icenga w. Siwa kan Mass imavalen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 78, 'iyi Ixelqen; Neppa iyi Inhan;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 79, 'Neppa iyi Icceççan, iyi Isswan;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 80, 'Neppa iyi Isseêluyen ma uvne$;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 81, 'ara iyi In$en, sinna, ara iyi d Ssidren;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 82, 'u, ôe$be$, d Win ara Isemmêen tuccva w, ass iqeîîiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 83, 'A Mass iw, £it iyi d, s ûûwab. Ssemlil iyi d iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 84, 'Err awal iw, d win n tidep, i ineggura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 85, 'Err iyi si lweôôat n Loennet n ssuâada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 86, 'Semmeê i baba. Neppa, s tidep, illa seg im$eôôqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 87, 'Ur iyi Xezzu, ass n tnekra nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 88, 'ass ideg ur infaâ wayla, ne$ derya,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 89, 'siwa win iqublen Öebbi, s wul unûiê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 90, 'A d teppaé Loennet, ar wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 91, 'A d innunnet ujajiê ar im$eôôqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 92, 'Ad asen inin: "anda ten wid tellam tâabdem,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 93, 'war Öebbi? Day a kwen ssellken, ne$ ad ssellken iman nnsen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 94, 'Ad pwagren degs, nitni, akked wid i$elîen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 95, 'akked lâaskeô n Iblis, akken ma llan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 96, 'Ad inin; u nitni, degs, ppemqellaân:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 97, '"s Öebbi, ar nella di ttelfan n ûûeê,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 98, 'mi kwen nessaâdel ar Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 99, 'D ibe$wviyen kan i a$ itelfen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 100, 'Ur nesâi imcafâen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 101, 'ne$ aêbib i $ iêemmlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 102, 'Lemmer ad as nales, a nili d lmumnin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 103, 'Deg wayagi, s tidep, assekni. Tegwti, degsen, ur uminen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 104, 'Mass ik, s tidep, Neppa, d Uzmir, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 105, 'Agdud n Nuê iskaddeb imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 106, 'Mi sen inna gmat sen Nuê: "day ur tepêezzibem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 107, 'Nek, $uôwen, d amazan muman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 108, 'Ihi, êezzbet i Öebbi, ta$em iyi awal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 109, 'Ur awen ssutre$ kra n teqdiât, ilmend n waya. Ih, taqdiât iw, apan kan, ar Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 110, 'Ihi, êezzbet i Öebbi, ta$em iyi awal".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 111, 'Nnan: "day a k namen, mi ddan yidek imezwura n laâôuô"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 112, 'Inna: "ur éôi$ ayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 113, 'Aqeîîi nnsen $eô Mass iw kan, lemmer tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 114, 'Ur swexxiôe$, nek, lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 115, 'Nek d aneddaô kan ipbeginnen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 116, 'Nnan: "ma ur tfukkev, a Nuê, war ccekk, a ppepwaôeomev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 117, 'Inna: "a Mass iw! S tidep, inkeô iyi ugdud iw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 118, 'Seyyi ferru gari yidsen. Sellek a$, nek, akked lmumnin i illan yidi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 119, 'Nsellek it, neppa, akked wid illan yides, di lbabuô iççuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 120, 'Sinna, deffir waya, Ne$ves wid igwran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 121, 'Deg wayagi, d assekni, war ccekk. Tegwti degsen, ur llin d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 122, 'Mass ik, s tidep, Neppa, d Uzmir, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 123, 'Âad skaddben imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 124, 'Mi sen inna gmat sen Hud: "day ur tepêezzibem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 125, 'Nek, $uôwen, d amazan muman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 126, 'Ihi, êezzbet i Öebbi, ta$em iyi awal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 127, 'Ur awen ssutre$ kra n teqdiât, ilmend n waya. Ih, taqdiât iw, apan kan, ar Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 128, 'Day a tbennum, di yal ti$ilt, assekni i tfukal nnwen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 129, 'La tepparam lebôuj, amar haat a pwekkôem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 130, 'Ma tewwtem, tekkatem s leqseê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 131, 'Ihi, êezzbet i Öebbi, ta$em iyi awal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 132, 'Ëezzbet i Win i wen Ifkan ayen teéôam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 133, 'Ifka yawen lmal, tarwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 134, 'tibêirin, tiliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 135, 'Nek, ugade$ aâaqeb fellawen, ass ameqwôaêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 136, 'Nnan: "iaâdel $uône$ tnubav, ne$ ur tnubav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 137, 'Ih, ayagi, siwa d asnulfu imezwura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 138, 'Ur nelli d wid ara ippuâaqben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 139, 'Nekôen t. Nesqucc iten. Deg wayagi d assekni, war ccekk. Tegwti degsen, ur llin d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 140, 'Mass ik, s tidep, Neppa, d Uzmir, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 141, 'Tamud skaddben imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 142, 'Mi sen inna gmat sen ÛüÜaliê: "day ur tepêezzibem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 143, 'Nek, $uôwen, d amazan muman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 144, 'Ihi, êezzbet i Öebbi, ta$em iyi awal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 145, 'Ur awen ssutre$ kra n teqdiât, ilmend n waya. Ih, taqdiât iw, apan kan, ar Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 146, 'Day a kwen ooen, deg wayen illan dagi, testumnem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 147, 'Di tebêirin akked tliwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 148, 'deg igran, tizdayin s ppemôa leqqaqen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 149, 'La tneoôem, d ccaîôin, ixxamen deg idurar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 150, 'Ihi, êezzbet i Öebbi, ta$em iyi awal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 151, 'Ur ssemêaset i lameô iballa$en,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 152, 'i issefsaden di tmurt, ur pleqqimen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 153, 'Nnan: "keçç, aql ak kan, seg iôehbaniyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 154, 'Keçç d amdan kan, am nekwni. Awi d assekni, ma d tidep ay tessawalev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 155, 'Inna: "tal$wemt agi, a ppessew deg wass is, kunwi a ppesswem deg wass nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 156, '£uôwat a p tevvuôem, mulac a kwen iwwet uâaqeb, deg wass abarar".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 157, 'Gezmen as tigwecrar, gwran d di nndama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 158, 'Iwwet iten uâaqeb. Deg wayagi d assekni, war ccekk. Tegwti degsen, ur llin d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 159, 'Mass ik, s tidep, Neppa, d Uzmir, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 160, 'Agdud n Luî iskaddeb imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 161, 'Mi sen inna gmat sen ÛüLuî: "day ur tepêezzibem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 162, 'Nek, $uôwen, d amazan muman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 163, 'Ihi, êezzbet i Öebbi, ta$em iyi awal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 164, 'Ur awen ssutre$ kra n teqdiât, ilmend n waya. Ih, taqdiât iw, apan kan, ar Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 165, 'Teppeddum ar ddkeô deg imavalen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 166, 'Teooam tilawin i wen d Ixleq Mass nnwen? Ihi, kunwi d agdud izegren tilas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 167, 'Nnan: "ma ur tfukkev, a Luî, a k nenfu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 168, 'Inna: "nek, seg wid ikeôhen igiten nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 169, 'A Mass iw, sellek iyi, nek akked twacult iw, seg igiten nnsen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 170, 'Nsellek it, neppa akked twacult is, meôôa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 171, 'siwa tam$aôt, ar wid igwran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 172, 'Sinna, Nessenger wiyav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 173, 'Nesse$li d fellasen ageffur. I icmet ugeffur n wid ippunedôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 174, 'Deg wayagi d assekni, war ccekk. Tegwti degsen, ur llin d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 175, 'Mass ik, s tidep, Neppa, d Uzmir, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 176, 'Agdud n At Teégi iskaddeb imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 177, 'Mi sen inna Cuâayeb: "day ur tepêezzibem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 178, 'Nek, $uôwen, d amazan muman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 179, 'Ihi, êezzbet i Öebbi, ta$em iyi awal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 180, 'Ur awen ssutre$ kra n teqdiât, ilmend n waya. Ih, taqdiât iw, apan kan, ar Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 181, 'Ktilet s lewqama; ur ppilit seg wid issenqasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 182, 'Weznet s lmizan uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 183, 'Ur ccmatet i medden, ayla nnsen; ur ssexsaôet di tmurt s usefsed.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 184, 'Ëezzbet i Win ikwen Ixelqen, kunwi akked isuta imenza".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 185, 'Nnan: "keçç, aql ak kan, seg iôehbaniyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 186, 'Keçç, d amdan kan, am nekwni. Nêesb ik seg wid iskiddiben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 187, 'Sse$li d fellane$ igezman igenni, ma d tidep ay tessawalev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 188, 'Inna: "Mass iw Iéôa, sennig wiyav, ayen txeddmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 189, 'Skaddben t. Iwwet iten uâaqeb, deg wass n tillas. D aâaqeb, s tidep, n wass abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 190, 'Deg wayagi, d assekni, war ccekk. Tegwti degsen, ur llin d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 191, 'Mass ik, s tidep, ar Neppa d Uzmir, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 192, 'Ar wagi, war ccekk, d ayen id Issers Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 193, 'Irs ed, yides, ôôuê n laman', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 194, '$ef wul ik, iwakken a ppiliv seg wid inedôen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 195, 's umeslay aâôab ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 196, 'Neppa, s tidep, deg Ihellilen imezwura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 197, 'Day ur illi ara d assekni i nitni, mi t ssnen imusnawen n At Isôail?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 198, 'Lemmer it id Nessers, i yiwen seg ibeôôaniyen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 199, 'u i$ôa yasen t, ur ppamnen yis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 200, 'Akka, Nessawev it ar wulawen ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 201, 'Ur ppamnen yis, alamma walan aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 202, 'A ten id ias, deqzalla, nitni ur bnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 203, 'Ad inin: "amendeô ma neggani"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 204, 'Day êaren s aâaqeb nne£?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 205, 'Day ur twalav ara, N$at iten, d iseggwasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 206, 'Sinna, iusa ten id wayen i sen ippuwaââden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 207, 'Ula i sen d ibbwi wayen is stumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 208, 'Ur Nesqucc tamdint, siwa tin isâan ineddaôen', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 209, 'i usmekti. Ur Nelli d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 210, 'Ur d risen yides ccwaîen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 211, 'Ur asen issefk, ur zmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 212, 'Nitni, s tidep, pwaâezlen $ef tmesliwt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 213, 'Ur nâaô, ar tama n Öebbi, ôebbi nniven. Mulac a ppiliv seg wid ara ippuâaqben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 214, 'Nabi llezm ik i k iqeôben mavi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 215, 'Ezger tacvaî ik $ef wi i k ivefôen si lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 216, 'Ma âuûan k, ini: "ur ppka$ deg wayen txeddmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 217, 'Ppkel $ef Uzmir Ipêunun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 218, 'I k Ipwalin mara tbeddev,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 219, 'mara d tezziv ar wid iknan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 220, 'Neppa, s tidep, Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 221, 'Ad awen mle$ anwi i$ef d prusun ccwaîen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 222, 'Prusun ed $ef yal akeddab idensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 223, 'Ppaken tameééu$t. Tegwti degsen d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 224, 'Imedyazen, îîafaôen ten im$eôôqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 225, 'Day ur twalav ara, ar nitni, di yal ta$zut pmenîaôen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 226, 'U nitni qqaôen ayen ur xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 227, 'Kkes ed wid iumnen, ixeddmen ayen ilhan, id ismektayen aîas Öebbi, i irebêen mbaâd ma pwadensen. Ad éôen, wid idensen, tama anida ara ppin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 1, 'Ïs. Atnan issekniyen n Leqwôan, akked Tezmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 2, 'D nnhaya u d abecceô i lmumnin:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 3, 'wid ibedden i téallit, ippaken zzakat, ipputebbten $ef laxeôt nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 4, 'Ih, wid ur numin ara s laxeôt, Ncebbeê asen igiten nnsen, d$a ddebdeben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 5, 'Widak, fellasen aâaqeb ucmit mavi. Di laxeôt, d nitni ara ixesôen ugwar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 6, 'S tidep, keçç iusa k id Leqwôan, s$uô Bab n ûûwab, Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 7, 'Mi inna Musa i twacult is: "nek wala$ times, ad awen d awi$, segs, asali, ne$ ad awen d awi$ asafu iôeqqen, amar a ppesseêmum".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 8, 'Mi ibbwev $uôes, ipwanced: "ad iôqu wayen illan di tmes, akked wayen i as d izzin. Gedha s Öebbi, Mass imavalen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 9, 'A Musa! Ih, Nek d Öebbi, Uzmir, Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 10, 'Veggeô taâkwazt ik"! Mi p iwala la tesseêôiîiw, amzun d azrem, ibren, ur iwexxeô. "A Musa! Ur ppagwad! Ar $uôI, ih, ur ppagwaden imazanen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 11, 'siwa win idensen, sinna, iu$al iwqem, deffir tuccva. Nek, s tidep, Psemmiêe$, Pêunnu$.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 12, 'Ger afus ik di loib ik, a d iffe$ d amellal, ur ihlik. Si tza issekniyen, i Ferâun akked ugdud is. Nitni, war ccekk, d agdud icemten".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 13, 'Mi ten id usan issekniyen nne£, âinani, nnan: "wagi iban d ssêur".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 14, 'Ugin ten s ddens d pnefxa, u, deg iman nnsen, pputebbten. Wali, ihi, amek tevôa d ifessaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 15, 'Ni$ Nefka tamusni i Dawed akked Sliman. Nnan: "ccekôan i Öebbi, i a$ Ismenyafen i waîaû n yimdanen iumnen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 16, 'Sliman iwôet Dawed, u inna: "a yimdanen! Nepwaselmed tutlayt n yifôax; ippunefk a$ si yal cci. Ayagi, s tidep, ard lfevl n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 17, 'Pwajemmlen d, i Sliman, i²âsekôiwen is si leonun, imdanen, ifôax. Mdarraren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 18, 'Armi, mi bbwven ar te$zut n twevfin, tenna d tweîuft: "a yaweîîuf, kecmemt ar ixxamen nnkwent, mulac, war ccekk, a kwent iéd Sliman, neppa akked iâsekôiwen is, ur faqen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 19, 'Icmumeê, ivûa, $ef wayen d tenna. Inna: "a Mass iw! Err iyi ad snemmre$ l$it iK, is i $ T$atev, nek akked imawlan iw; ad xedme$ ise$ ara Tôaviv; Ssekcem iyi, s uêunu K, ar imdanen iK imaânen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 20, 'Issefqed ifôax, inna: "acimi ur wala$ ara iççibib, day d l$ayeb?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 21, 'War ccekk, ad sâaddi$ fellas aâaqeb uqsiê, ne$ a t zlu$, ne$ a d iawi tasebbiwt tubrizt".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 22, 'Ur iâaîîel ara. Inna d: "fehme$ ayen ur tefhimev. Usi$ d $uôek si Saba, s usali unûiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 23, 'Ih, ufi$ en tameîîut d tagelliî nnsen. Ippunefk as si yal cci. £uôes asgeld abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 24, 'Ufi$ p in, neppat akked ugdud is, la kennun i yiîij, war Öebbi. Cciîan icebbeê asen igiten nnsen. Iveôf iten seg ubrid, d$a nitni ur pwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 25, 'Acimi ur knan ara i Öebbi, id Issufu$en lesrar, di tmurt akked igenwan, i Iéôan ayen teppeffrem u ayen d tepberriêem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 26, 'Öebbi, ur illi ôebbi siwa Neppa, Mass n usgeld ameqwôaêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 27, 'Inna: "a néeô ma tessawlev d tidep, ne$ ma keçç seg ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 28, 'Öuê s tebôap iw agi, veggeô asen p, sinna, wexxeô asen, wali acu ara d rren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 29, 'Tenna: "a yimvebbôen, tepwaveggeô iyi d tebôap tukyist.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 30, 'Ih, s$uô Sliman. Apan: s yisem n Öebbi Aênin Ipêunun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 31, 'Ur ssem$waôet ara iman nnwen $uôi, aset ed $uôi, d imvuâen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 32, 'Tenna: "a yimvebbôen, fket ed ôôay nnwen af lameô iw. Ur pseyyi$ lameô, siwa garawen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 33, 'Nnan: "nekwni d imawlan n tezmert, nesâa lemêella tuqsiêt. Lameô i kem. Muqel d acu ara d tseyyiv".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 34, 'Tenna: "s tidep, igeldan ssefsaden tamdint ara kecmen. Sdullun imdanen is lâali. Akka ay xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 35, 'Nek, ad asen azne$ tarzeft, ad aôou$ acu ara d awin imcegâan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 36, 'Mi tebbwev ar Sliman, inna: "day ad iyi tâawnem s terkunt? Ayen i yi Ifka Öebbi, yif ayen i wen Ifka. D kunwi kan i ifeôêen, s terzeft nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 37, 'U$al $uôsen. Ih, a nôuê $uôsen s lâaskeô, iwumi ur zmiren. A ten id nessuffe$, syenna, ndellen, d imejîuêen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 38, 'Inna: "a yimvebbôen, anwa degwen, ara yi d iawin asgeld is, uqbel a yi d asen d imvuâen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 39, 'Aâfrit si leonun, inna d: "ad ak t id awi$, uqbel ma tekkrev seg umekkan ik. I wayagi, war ccekk, nek d uzmir muman".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 40, 'Inna d bab n tmusni si Tezmamt: "nek ad ak t id awi$, uqbel a pfukkev asmeômec". Mi t iwala irs ed $uôes, inna: "wagi si lfevl n Mass iw, ad iyi ijeôôeb ma ad snemmre$, ne$ ma ad jehle$. Win isnemmren, isnemmer kan i iman is. Win ijehl, ihi, Mass iw d Asâay, d Ukyis".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 41, 'Inna: "bedlet as udem usgeld is, a néeô ma tepwanha, ne$ haap seg wid ur nepwanha".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 42, 'Mi d tusa, nnan as: "day am wagi, usgeld inem"? Terra d: "amzun d neppa". "Tusa ya$ d tmusni, uqbel neppat, nuzen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 43, 'Isôuê ip wayen tunez, war Öebbi. Tella, s tidep, seg ugdud ijehliyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 44, 'Nnan as: "ekcem ar lbeôo"! Mi t twala, t$il degs aman; tesban ed ifadden is. Inna: "s tidep, d lbeôo ulelluc imzin". Tenna: "a Mass iw! Ih, dense$ iman iw. Akked Sliman, unze$ aS i Öebbi, Mass imavalen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 45, 'Ni$ Nuzen ed, i Tamud, gmat sen Üaliê: "âabdet Öebbi"! Maca, rran snat n trebbuya$, ppemnamarent.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 46, 'Inna: "a yagdud iw! Acimi tep$awalem ar tucmip, uqbel ise$? Lemmer a ppeste$fôem Öebbi, ahat aêunu fellawen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 47, 'Nnan: "tkeêêesev a$, keçç akked wi iddan yidek". Inna: "lfal nnwen ar Öebbi, u kunwi d agdud ara ippuhewwlen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 48, 'Llan, di temdint, tza iterrasen i issefsaden di tmurt, ur pleqqimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 49, 'Nnan: "yyaw a nemmesgal s Öebbi, ard a neévem deg iv fellas, neppa akked twacult is. Sinna, a nini i bab is: ur nelli d inagan n tmen$iwt n tawacult is. Ih, nekwni, d imawlan n tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 50, 'Undin ticeôkep, Nundi ticeôkep, nitni ur faqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 51, 'Wali amek tevôa di tceôkep nnsen. Nen$ed iten, nitni, akked ugdud nnsen, meôôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 52, 'Atnan hudden ixxamen nnsen, ilmend n ddens nnsen. Deg wayagi, war ccekk, assekni i ugdud issnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 53, 'Nsellek wid iumnen u llan pêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 54, 'I Luî, mi inna i ugdud is: "teppeddum ar wayen n dir, u kunwi tepwalim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 55, 'Ih, kunwi teppeddum ar irgazen, teb$am ten, war tilawin. Ih, kunwi d agdud ur nessin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 56, 'Tiririt n ugdud is, siwa mi d nnan: "ssuff$et tawacult n Luî, si temdint nnwen, nitni d imdanen i ib$an tezdeg".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 57, 'Nsellek it, neppa akked twacult is, siwa tameîîut is. Nseyya a ppili seg wid igwran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 58, 'Nesse$li d fellasen ageffur. I icmet ugeffur n wid ippunedôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 59, 'Ini: "ccekôan i Öebbi. Talwit i imdanen iS, wid Ifren". Ppif Öebbi, ne$ ayen pcaraken?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 60, 'Day Win Ixelqen tamurt akked igenwan, i wen d Isse$lin aman, seg igenni - Nessenkar, yissen, iqwiôen ippembehwaoen, ur teêwaoem a d tessem$im ttjuô is -, day illa ôebbi, ar tama n Öebbi? Maca, nitni d agdud issaâdalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 61, 'Day Win Irran tamurt d tanezdu$t, Irra degs isaffen, Irra yas idurar, Irra agadir ger sin ilellen, day illa ôebbi ar tama n Öebbi? Xaîi, tegwti degsen, ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 62, 'Day Win Issemêasen i umevôuô, mara S d isiwel; Itekksen ayen n dir; i kwen Ipparan d igensas di tmurt; day illa ôebbi, ar tama n Öebbi? Drus id tesmektayem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 63, 'Day Win i kwen Inehhun, di tillas n lberr akked yill, id Ippaznen avu, d abecceô n ccira uêunu S; day illa ôebbi, ar tama n Öebbi? Ay Aâlay Öebbi, sennig wayen pcaraken!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 64, 'Day Win Ibeddun lxelq, sinna, Ippales as; ikwen I$aten seg igenni akked tmurt; day illa ôebbi ar tama n Öebbi? Ini: "awit ed atebbet nnwen, ma tessawalem tidep"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 65, 'Ini: "tabavnit, di tmurt akked igenwan, ur p issin yiwen siwa Öebbi. Ur éôin melmi ara d kkren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 66, 'Ih, tamusni nnsen ur tessawev ar laxeôt? Xaîi, nitni di ccekk fellas. Xaîi, nitni, fellas, dre$len.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 67, 'Nnan wid ijehlen: "day ma nu$al d akal, am imezwura nne$, s tidep, fella$ tanekra?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 68, 'Ni$ waââden a$ aya, i nekwni akw i imezwura nne$, zik. Ayagi, d timucuha kan imenza".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 69, 'Ini: "iniget di tmurt, walit amek tevôa d ibe$wviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 70, 'Ur $webben fellasen, ur pxiqqi ilmend n nncub nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 71, 'Nnan: "melmi lemâahda agi, ma d tidep ay tessawalem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 72, 'Ini: "kra n wayen i$ef têarem, ahat atan ivfeô kwen id".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 73, 'Mass ik, s tidep, meqqweô lfevl iS, $ef imdanen. Maca, tegwti degsen ur snemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 74, 'Mass ik, s tidep, Iéôa ayen teffren idmaren nnsen, akked wayen d qqaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 75, 'Ur illi wayen iffren, deg igenni akked tmurt, ur nuri di Tezmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 76, 'Ih, Leqwôan agi iêekku d i At Isôail, tegwti n wayen i$ef mgarraden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 77, 'Neppa, war ccekk, ard nnhaya akked uêunu i lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 78, 'Mass ik, s tidep, ad Iseyyi garasen s uêuddu S. Neppa d Uzmir, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 79, 'Ppkel $ef Öebbi, ih, aql ak di tidep ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 80, 'Ih, keçç, ur tepparav lmeggtin ad slen, ur tepparav iâeééugen ad slen i wancad, ma wexxôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 81, 'Ur fellak nnhaya ider$alen, mgal ttelfan nnsen. Ara islen, siwa wid iumnen s issekniyen nne£. Nitni d imvuâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 82, 'Mi iûaô wawal fellasen, ad asen d Nessuffe$ lweêc si tmurt; ad asen yini ar imdanen ur metbutit $ef issekniyen nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 83, 'Ass ideg ara d Nefser, si yal lois, arbaâ n wid inekôen issekniyen nne£, d tirni,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 84, 'alamma, mi d usan, ad Yini: "day tnekôem issekniyen iW, ur ten teskecmem di tmusni? Ne$ d acu tellam txeddmem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 85, 'Iûaô wawal fellasen, imi densen. Ur d pmeslayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 86, 'Day ur walan ara ar Nerra yasen iv i ureyyeê nnsen, ass iwakken ad walin? Deg wayagi, s tidep, issekniyen i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 87, 'Ass uûuvu n lbuq, ad iagwad i illan deg igenwan, i illan di tmurt, siwa wid i S ihwan i Öebbi. A d asen akw $uôeS, s uêiwet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 88, 'A pwaliv idurar i t$ilev sebken, la teddun am usigna. D igi n Öebbi i Iûegmen yal cci. Neppa, s tidep, Iéôa d acu txedmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 89, 'Win id iusan s ise$, ad iawi it yifen. Widak, assen, mevmunit si tugdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 90, 'Wid id iusan s tucmip, ad ppin wudmawen nnsen ar tmes. Ni$ a ppeppuqeîîim kan $ef wayen txeddmem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 91, 'Pwamôe$ kan ad âabde$ Mass n temdint agi, i Iôqa. IneS yal cci. Pwamôe$ d ad ili$ seg imduâen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 92, 'ad male$ Leqwôan. Win ipwanhan, ipwanha kan i iman is. Win innetlafen, ini: "nek d aneddaô kan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 93, 'Ini: "a neckeô Öebbi. Ad awen Issken issekniyen iS. A ten tâaqlem". Mass ik ur I$effel ara $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 1, 'Ïsm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 2, 'Atnan issekniyen n Tezmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 3, 'Ad ak d Neêku si teqûiî n Musa akked Ferâun, s tidep, i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 4, 'Ih, Ferâun issem$weô iman is di tmurt; imezda$ ifeôq iten d iêôumen. Isrewrew îayfa segsen, izellu arrac nnsen, issidir tilawin nnsen. Ih, neppa seg ifessaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 5, 'Neb$a a Nfeôôeo $ef wid irewrwen di tmurt, a ten Nerr d imeqwôanen, a ten Nerr d iweôôaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 6, 'A ten Nesseqâad di tmurt. A Nessken i Ferâun, Haman, akked iâsekôiwen nnsen, ayen ppagwaden segsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 7, 'Nweêêa i imma s n Musa: "ssuîîev it, sinna, ma tugadev fellas, err it ar wasif. Ur ppagwad, ur $webben. Ad am t id Nerr, u a t Nerr seg imazanen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 8, 'Teddem it twacult n Ferâun. Ad asen iu$al d acengu, d a$ilif. Ih, Ferâun, Haman, akked iâsekôiwen nnsen llan d imsaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 9, 'Tenna tmeîîut n Ferâun: "d nnûib n tiî, i nek akked keçç. Ur tneqq, ahat ad a$ infaâ, ne$ a t nerr d mmit nne$". Nitni ur faqen ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 10, 'Temmar ed tasa n yimma s n Musa. Qôib it id tessken, lemmer ur Nzeyyeô ara ul is, iwakken a ppili si lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 11, 'Tenna i ultma s: "evfeô it"! Teqquôa t si mbâid, nitni ur faqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 12, 'Uqbel, Negdel as tid iûûuîuven. Tenna: "ad awen ssekne$ axxam ar awen itkwelfen fellas, u nitni ad as bedden"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 13, 'Nerra t id i imma s, iwakken ad as kkawent wallen is, ur t$webben, iwakken a péeô ar lemâahda n Öebbi d tidep. Maca, tegwti degsen, ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 14, 'Mi meqqweô, ittaâqel, Nefka yas tussna, ûûwab. Akka ay Nepkafi imdanen lâali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 15, 'Ikcem tamdint, di lweqt ideg stehzan imezda$ is. Iufa n sin irgazen pna$en, yiwen seg uêôum is, wayev seg icenga s. Win n uêôum is, issuter as d afus, mgal win n icenga s. Iwwet it Musa s lbunia, in$a t. Inna: "ayagi, seg igi n Cciîan. Neppa, s tidep, d acengu n ûûeê, itellifen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 16, 'Inna: "a Mass iw! Nek dense$ iman iw, Semmeê iyi". Isemmeê as. Ih, Neppa Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 17, 'Inna: "a Mass iw! S l$it iK felli, ur ppili$, d awez$i, si loiha ibe$wviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 18, 'Iufa d iman is di temdint, iugad, iquôaâ. Atan a d ipâaggiv $uôes, win i s d issutren afus, ass izeryen. Inna yas Musa: "keçç, s tidep, d im$eôôeq n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 19, 'Acengu nnsen, mi ib$a a t iwwet, inna d: "a Musa! Day teb$iv ad iyi ten$ev, akken ten$iv yiwen, ivelli? Teb$iv kan a ppiliv d aqehhaô di tmurt, ur teb$iv ara a ppiliv seg iâaôviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 20, 'Iusa d urgaz si îîerf n temdint, ippazal. Inna d: "a Musa! S tidep, imvebbôen mlalen $ef loal ik, a k n$en. Effe$, nek, seg wid ik ipweûûin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 21, 'Iffe$ segs, iugad, iquôaâ. Inna: "a Mass iw! Sellek iyi seg ugdud imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 22, 'Mi ibbwi tikli ar Madian, inna: "ahat Mass iw ad iyi Iawi d ubrid umâin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 23, 'Mi ibbwev s aman n Madian, iufa n arbaâ n l$aci, la sswan. Iufa, di îîerf nnsen, snat n tlawin, îîfent lmal nnsent. Inna: "d acu txeddmemt"? Nnant ed: "ur nesswa alamma wexxôen imeksawen. Babat ne$ d am$aô ameqwôan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 24, 'Issew asent, iu$al ar tili, inna: "a Mass iw! Nek ôe$be$ $ef yal lxiô, ar iyi d Tessersev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 25, 'Tusa t id yiwet segsent, s tikli ikukran, tenna: "atan ak d issawal baba, a k ikafi imi $ tesswev". Mi iôuê $uôes, u iêka yas i ivôan, inna: "ur ppagwad, tepwasellkev seg ugdud imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 26, 'Yiwet segsent, tenna: "a baba! Eîîef it d acrik, ih, yif icriken ik, iohed, muman".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 27, 'Inna: "b$i$, nek, ad ak fke$ yiwet si yissi yagi, s cceôt a pxedmev $uôi îam iseggwasen. Ma tessawdev mraw, s leb$i k. Ur b$i$ a k hejjne$. Ad ak ili$, ma Irad Öebbi, seg iâaôviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 28, 'Irra: "ayagi, gari yidek. A tin sâadda$ ger snat n tallitin, ur ippili felli u$ilif. Öebbi d Awkil, $ef wayen id nenna".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 29, 'Mi ifukk Musa tallit, u iseyyeê akked twacult is, iwala times ar tama n udrar. Inna i twacult is: "qqimet, wala$ times, ahat ad awen d awi$, segs, asali ne$ asafu, amar a ppesseêmum".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 30, 'Mi ibbwev $uôes, ipwanced ed si ttejôa, di rif ayeffus n te$zut, deg umviq iôqan: "a Musa! S tidep, Nek d Öebbi, Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 31, 'Veggeô taâkwazt ik". Mi p iwala, la tesseêôiîiw amzun d azrem, ibren ur iwexxeô. "A Musa! Qeddem, ur ppagwad, aql ak, ih, di laman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 32, 'Err afus ik di loib ik, a d iffe$ d amellal, ur ihlik. Sseqôeb ed $uôek i$il ik, ad ak tekkes tugwdi. Tigi d sin n ppbut s$uô Mass ik, i Ferâun akked imvebbôen is. Ih, nitni d agdud iballa$en".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 33, 'Inna: "a Mass iw! Nek n$i$ yiwen segsen, ugade$ ad iyi n$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 34, 'Gma Harun yif iyi afeûûeê umeslay. Azen it id yidi d amâiwen, ad iyi tebbet. Nek ugade$ ad iyi nekôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 35, 'Inna: "a Nesseohed tayepp ik s gma k. Ad awen Nefk, i sin, adabu; ur kwen id ppawven. S issekniyen nne£, d kunwi akked wid iddan yidwen ara irebêen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 36, 'Mi ibbwev $uôsen Musa, s issekniyen iberrzen, nnan: "ayagi, siwa ssêur id innulfan. Ur nesli s waya, $uô ibabaten nne$ imezwura".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 37, 'Inna Musa: "Mass iw Iéôa sennig wiyav, anwa iwumi Ifka nnhaya s$uôeS, anwa ara d igwrin deg Uxxam. Imednas, s tidep, ur rebêen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 38, 'Inna Ferâun: "a yimvebbôen, ur awen mli$ ara kra n ôebbi, war nekkini. Ecâal iyi times ar talaxt, a Haman; bnu yi lbeôo aâlayen; ahat ad ali$ ar ÖÔebbi n Musa. Nek, s tidep, êesbe$ t seg wid iskiddiben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 39, 'Neppa, akked iâsekôiwen is, sme$wôen iman nnsen di tmurt, war ssebba. £ilen, ar nitni, ur d ppu$alen $uône£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 40, 'Neppa, akked iâsekôiwen is, Neîîef iten. Nger iten ar yill. Wali amek tevôa d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 41, 'Nerra ten d imeqwôanen i ineccden ar tmes. Ass n tnekra, ur ppusellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 42, 'Neqqen asen xezzu di ddunit agi. Ass n tnekra, nitni seg ucmiten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 43, 'Ni$ Nefka Tazmamt i Musa, mbaâd ma Nesqucc isuta imezwura. D tafat i imdanen, d nnhaya u d aêunu. Amar a d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 44, 'Ur telliv ara di loiha utaram, mi Nseyya lameô i Musa. Ur telliv seg inagan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 45, 'Maca, Nxelq ed tisuta, $wezzif laâmeô nnsent. Ur tellid seg imezda$ n Madian, la sen teqqarev issekniyen nne£. Maca, Nella Neppazen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 46, 'Ur telliv ar tama n udrar, mi d Nessawel. Maca d aêunu s$uô Mass ik, iwakken a pnedrev agdud, u$uô ur d iusi uneddaô, uqbel ik. Amar a d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 47, 'Mulac, ma têuza ten tiyta id urwen ifassen nnsen, a d inin: "a Mass nne$! A lemmer i $ d Tuznev amazan, a neddu d issekniyen iK, a nili seg wid iumnen"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 48, 'Mi ten id tusa tidep s$uône£, nnan: "a lemmer id iusi am wayen id iusan i Musa"! Day ur ugin ara, zik, ayen id iusan i Musa? Nnan: "d sin ssêurat". Mwafaqen, nnan: "nekwni nugi ten i sin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 49, 'Ini: "awit ed Tazmamt, s$uô Öebbi, i yifen snat agi, i nnhaya, ad ddu$ yides, ma tessawalem tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 50, 'Ma ur ak d rran ara, efhem ar ddan kan d lhawiyyat nnsen. Anwa innetlafen, sennig win iteddun d lhawiyya s, war nnhaya s$uô Öebbi? Öebbi, s tidep, ur Inehhu agdud imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 51, 'Aql a£ Nessawwev asen awal, amendeô ma d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 52, 'Umnen yis wid iwumi Nefka Tazmamt, uqbel tagi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 53, 'Ma $ôan asen t, ad inin: "numen yis. Ih, ar neppa d tidep, s$uô Mass nne$. Uqbel is, s tidep, nella d imvuâen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 54, 'Wigi a ten id ias ukafi nnsen berdayen, $ef wayen ûebôen, swexxiôen tucmip s yise$, u seg wayen iten N$at, pseddiqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 55, 'Mi slan i yir awal, ad as veôfen, u qaôen: "i nekwni igiten nne$, i kunwi igiten nnwen. Fellawen talwit. Ur neô$eb $ef at war tussna".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 56, 'Keçç, s tidep, ur tnehhuv win têemlev. Maca, Öebbi Inehhu win i S ihwan. Neppa, Yif akw akken Iéôa wid ipwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 57, 'Nnan: "ma nedda d nnhaya yidek, a nepwaxvef seg wakal nne$". Day ur ten Nesseqâad ara di loamaâ n laman, u$uô d ppawvent yal l$ellat? D l$it s$uône£. Maca, tegwti degsen, ur éôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 58, 'Acêal Nesqucc n temdininn, cerrâent di temâict nnsent. Atnan ixxamen nnsen, ay ten ized$en, deffir sen, siwa ixeîîayen. D Nekwni ay d iweôôaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 59, 'Ur Isquccu Mass ik timdinin, alamma iuzen i imezda$ nnsent, amazan i sen immalen issekniyen nne£. Ur Nesquccu timdinin, mebla ma llan imezda$ nnsent, d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 60, 'Kra n wayen i wen ippunefken n cci, d zzhu n tmeddurt n ddunit, akked ccbuê is. Ayen illan $eô Öebbi, yif it, ad idum kter. Day ur pmeyyizen ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 61, 'Day win iwumi Nefka lemâahda igerzen, u immuger ip, am win i Nezha s l$it n tmeddurt n ddunit; sinna, ass n tnekra, neppa seg wid ara d irsen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 62, 'Ass ideg ara sen d Isiwel, ad Yini: "anda ten wid iyY tepcarakem, u tellam tepkabarem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 63, 'A d inin wid i$ef iûaô wawal: "a Mass nne$! Wigi i njeggeê, njeggeê iten, akken i nepwajeggeê. A nzekki $ureK: maççi d nekwni ay âabden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 64, 'Ad asen inin: "naâôet wid tepcarakem". Ad ten naâôen, ur asen d pparan. Walan aâaqeb. A lemmer llan pwanhan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 65, 'Ass ideg ara sen d Isiwel, ad Yini: "acu d terram i imazanen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 66, 'Assen, ad dergen fellasen isalen, nitni ur pmesteqsayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 67, 'Ma d win isteôoâen, iumnen, ixedmen ayen ilhan, ahat ad yili seg imerbaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 68, 'Mass ik Ixelleq ayen i S ihwan, u Ismenyafa. Ur ten id iûaê usmenyif. Gedha s Öebbi! I Aâlay sennig wayen pcaraken!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 69, 'Mass ik Iéôa ayen iffren deg idmaren nnsen, akked wayen cennâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 70, 'Neppa d Öebbi, ur illi ôebbi siwa Neppa. I Neppa, annuz di tmezwarut, u di tneggarut. I Neppa aêuddu, $uôeS tu$alin nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 71, 'Ini: "acu tmeyyzem, ma Isse$li d Öebbi iv imezgi, fellawen, alamma d ass n tnekra? Anwa ôebbi, war Öebbi, ara wen d iawin tafat? Day ur tsellem ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 72, 'Ini: "acu tmeyyzem, ma Issuli Öebbi ass imezgi, fellawen, alamma d ass n tnekra? Anwa ôebbi, war Öebbi, ara wen d iawin iv, a ppestaâfum degs? Day ur tepwalim ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 73, 'Seg uêunu S, Iga yawen iv akked wass, i ustaâfu nnwen, akked unadi n lfevl iS. Amar a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 74, 'Ass ideg ara sen d Isiwel, ad asen Yini: "anda ten wid iyY tepcarakem, u tellam tepkabarem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 75, 'A d Nawi anagi, si yal lois. A Nini: "awit ed atebbet nnwen". Ad éôen ar tidep n Öebbi. Itelf iten wayen d snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 76, 'Ih, Qaôun illa seg ugdud n Musa. Iqehô iten. Nefka yas igerrujen; s tezmert ugraw ioehden, arfad n tsura nnsen. Mi s inna ugdud is: "ur zehhu! Öebbi, s tidep, ur Iêemmel ara izehwaniyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 77, 'Deg wayen i k Ifka Öebbi, nadi axxam aneggaru. Ur teppu amur ik, di ddunit. Elhu, akken i Ilha Öebbi $uôek. Ur ssaram lefsad di tmurt. Öebbi, s tidep, ur Iêemmel ifessaden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 78, 'Inna: "ippunefk iyi kan, ilmend n tmusni i sâi$". Day ur iéôa ara ar Öebbi Isqucc, uqbel is, ger isuta, wid i t iugaren di tezmert, isemmden kteô? Ur illi usteqsi ibe$wviyen, af ibekkaven nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 79, 'Iffe$ ed s agdud is, s ôôêuê is. Wid ib$an tameddurt n ddunit, nnan: "awufan nesâa am wayen ippunefken i Qaôun! Ih, neppa d bab n terkunt tabarart".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 80, 'Wid, iwumi teppunefk tmusni, nnan: "a ssexv nnwen! Ppwab n Öebbi yif it, i win iumnen, ixeddmen ayen ilhan. Ara d iûaê siwa win iûebôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 81, 'Nger it seddaw tmurt, neppa akked uxxam is. Ur as telli terbaât ara t isellken, war Öebbi. Ur illi seg wid ipselliken iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 82, 'Wid issaramen amkan is, ivelli nni, u$alen nnan: "zi$ Öebbi Issugut ôôeéq i win i S ihwan, deg imdanen iS, u iwezzen. Lemmer ur a$ I$at ara Öebbi, yili Iger a$ seddaw tmurt. Ih, ur rebêen ijehliyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 83, 'Axxam nni aneggaru, a t Nerr i wid ijunben tem$weô akked usefsed, di tmurt. Tirect i wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 84, 'Win id iusan s yise$, ad iawi ayen it yifen. Win id iusan s tucmip, ihi, ad ppuqeîîin wid ixedmen tucmitin, $ef wayen kan xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 85, 'Ih, Win Ilezmen fellak Leqwôan, war ccekk, a k id Irr s axxam. Ini: "Mass iw Yif akw akken Issen anwa id iusan s nnhaya, anwa i illan di ttelfan n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 86, 'Ur tessarmev ara, ad ak ed ters Tezmamt, lemmer maççi d aêunu s$uô Mass ik. Ur ppili d amâiwen ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 87, 'Ur k swexxiôen seg issekniyen n Öebbi, deffir trusi nnsen $uôek. Nuj ar Mass ik, ur ppili seg wid ipcaraken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 88, 'Ur nâaô, ar tama n Öebbi, ôebbi nniven. Ur illi ôebbi, siwa Neppa. Yal cci ad inger, siwa udem iS. IneS aêuddu. £ureS ara tu$alem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 1, 'Alm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 2, 'Day $ilen imdanen a ten ooen qqaôen: "numen", u nitni ur ppuhewwlen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 3, 'Ni$ Nhewwel wid i ten id izwaren. War ccekk, ad Yissin Öebbi wid iqqaôen tidep, ad Yissin ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 4, 'Ne$ $ilen ad a£ zwiren wid ixedmen tucmitin? Dir it wayen pêuddun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 5, 'Win iggunin timlilit akked Öebbi, s tidep, a d ias, war ccekk, lajel n Öebbi. Neppa, Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 6, 'Win ijuhden, ijuhed kan i iman is. Öebbi, s tidep, ur Iêwao ara imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 7, 'Wid iumnen, ixeddmen ayen ilhan, war ccekk, ad asen Nekkes tucmitin nnsen, a ten Nkafi $ef wayen xeddmen ifuqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 8, 'Nweûûa amdan ar lewqama, s imawlan is. Ma lezmen fellak, ad iyI tcarkev ayen ur tessinev, ur asen ppa$ awal. Tu$alin nnwen, $uôI. Ad awen Mle$ acu txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 9, 'Wid iumnen, ixedmen ayen ilhan, war ccekk, a ten Nessekcem ar iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 10, 'Ger imdanen, wid iqqaôen: "numen s Öebbi". Ma meênen, deg ubrid n Öebbi, ad êesben ahewwel n medden, d aâaqeb n Öebbi. Mi d iusa l$elb, s$uô Mass ik, ar ad inin: "ih, nella yidwen". Day ur Iéôa ara Öebbi, i illan deg idmaren imavalen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 11, 'War ccekk, Öebbi Issen wid iumnen, Issen ixabiten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 12, 'Nnan wid ijehlen, i wid iumnen: "ddut d ubrid nne$, a nbibb tuccva nnwen". Nitni ur pbibbin acemma, si tuccva nnsen. S tidep, nitni d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 13, 'War ccekk, ad bibben tiâekkwmin nnsen, akked tiâekkwmin nniven. Ih, ad ppusteqsin, ass n tnekra, af wayen id snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 14, 'Ni$ Nuzen ed Nuê, i ugdud is. Izde$ yides, agim kkes ed smuset iseggwasen. Ibbwi ten uêemmal, nitni d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 15, 'Nsellek it, neppa akked wid iddan di lbabuô. Nerra t d assekni i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 16, 'Ibôahim, mi inna i ugdud is: "âabdet Öebbi, êezzbet aS. Yif it wakka, i kunwi, lemmer teéôim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 17, 'Tâabdem kan tiâancuôin, war Öebbi. Tesnulfam d tikerkas. Ih, wid tâabdem, war Öebbi, ur zmiren a kwen $iten. Ssutret l$it i Öebbi, âabdet eP, snemmret aS. £uôeS ara tu$alem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 18, 'Ma tnekôem, ihi, uqbel nnwen, nekôen leoyus". I iwatan, i umazan, siwa assiwev ubeggen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 19, 'Day ur walan ara, amek id Inezzu Öebbi lxelq, sinna, Ippales as. Ih, ayagi, i Öebbi, d ushil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 20, 'Ini: "iniget di tmurt, walit amek id Inza lxelq. Sinna, Öebbi a d Iawi lxelq aneggaru. Ih, Öebbi Izmer i yal cci".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 21, 'Ikkat win i S ihwan; Ipêunu $ef win i S ihwan. £ureS jebbu nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 22, 'Ur tesfunnugem, kunwi, di tmurt, ne$ deg igenni. Ur tesâim, war Öebbi, bab ne$ asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 23, 'Wid iugin issekniyen n Öebbi, akked temlilit yideS, widak ad aysen aêunu W. I widak, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 24, 'Tiririt n ugdud is, siwa mi d nnan: "en$et ep, ne$ sseô$et ep". Isellek it Öebbi, si tmes. Deg waya, s tidep, d assekni i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 25, 'Inna: "teddmem kan tiâancuôin, war Öebbi. Temêemmalem di tmeddurt n ddunit, sinna, ass n tnekra, kra degwen ad nekôen wiyav, kra ad xzun wiyav. Axxam nnwen d times, ur awen illi usellak".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 26, 'Iumen it Luî. Inna: "nek, d iminig ar Mass iw. Ih, Neppa, d Uzmir, d Bab n ûûwab".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 27, 'N$at it s Isêaq akked Yaâqub. I tarwas, Nefka lambiyya, Tazmamt. Nefka yas taqviât is, di ddunit; u neppa, di laxeôt, war ccekk, seg iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 28, 'Luî, mi inna i ugdud is: "ih, aql akwen la txedmem lâaô, ur ixdim yiwen, zik, deg imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 29, 'La teppeddum, ih, ar irgazen, tgezzmem abrid, txeddmem ayen icemten, deg igrawen nnwen". Tiririt n ugdud is, siwa mi nnan: "awi a$ d aâaqeb n Öebbi, ma telliv seg wid issawalen tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 30, 'Inna: "a Mass iw! Efk iyi afus, mgal agdud ifessaden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 31, 'Mi d usan imceggâen nne£, ar Ibôahim, s ubecceô, nnan as: "ih, a Nesqucc imezda$ n temdint agi. Imezda$ is, s tidep, d imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 32, 'Inna d: "ni$ degs Luî". Nnan as: "Nekwni, Neéôa sennig akw, i illan degs. A t Naâteq, neppa akked twacult is, siwa tameîîut is, ara yilin seg wid igwran".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 33, 'Mi usan imceggâen nne£, ar Luî, i$wbel ilmend nnsen, ur izmir a ten ifukk. Nnan as: "ur ppagwad, ur $webbel. Nekwni a k Naâteq, keçç d twacult ik, siwa tameîîut ik, ara yilin seg wid igwran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 34, 'Ih, nekwni a d Nesse$li ssxev seg igenni, $ef imezda$ n temdint agi, ilmend n lâaô nnsen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 35, 'Ni$ Neooa d segs, assekni iberrzen, i ugdud ipmeyyizen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 36, 'Ar Madian, gmat sen Cuâayeb. Inna: "a yagdud iw! Âabdet Öebbi, gganit ass aneggaru, ur oouôut di tmurt d ifessaden!".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 37, 'Nekôen t. Tewwet iten zzenzla. Gwran d, d loeppat, deg ixxamen nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 38, 'Âad akked Tamud - ni$ iban awen d seg ixxamen nnsen -, icebbeê asen Cciîan igiten nnsen. Issuffe$ iten seg ubrid, nitni pfeôôioen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 39, 'Qaôun, Ferâun, Haman, ni$ iusa ten id Musa, s ubeggen. Sme$wôen iman nnsen, di tmurt, ur rbiêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 40, 'Yal wa, Newwet it $ef ubekkav is. Llan wid iwumi Nuzen tabucivant. Llan wid i iwwet usu$u. Llan wid i Nger seddaw wakal. Llan wid i Ne$meq. Maççi d Öebbi iten idensen, d nitni i idensen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 41, 'Wid iteddun d imawlan, war Öebbi, cban rtila. Tebna tissist. Ihi, axxam ahcican mavi, d tissist n rtila, lemmer ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 42, 'Ih, Öebbi Iéôa akw ayen u$uô naâôen, war Neppa. Neppa, d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 43, 'Imedyaten agi, Neppawi ten id, i l$aci. Siwa imusnawen ara ten ifehmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 44, 'Ixleq Öebbi tamurt akked igenwan, s tidep. Ih, deg waya, assekni i lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 45, 'Mel ayen i k id ippuweêêan si Tezmamt. Bedd i téallit. Ih, taéallit teppekkes lâaô, tuccva. War ccek, iugar ip usmekti n Öebbi. Öebbi Iéôa acu tûenâam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 46, 'Ur pnamaret At Tezmamt, siwa s wawal aéidan, siwa wid degsen idensen. Init: "numen s wayen id irsen $uône$, id irsen $uôwen. Öebbi nne$, akked Öebbi nnwen, Yiwen. Nekwni $uôeS d imvuâen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 47, 'Akka ay ed Nessers, $uôek, Tazmamt. Wid iwumi Nefka Tazmamt, umnen yis. Ger wigi, kra umnen yis. I inekôen issekniyen nne£, siwa ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 48, 'Ur telliv temmalev kra n Tezmamt, uqbel tagi; ur p tepparuv, s uyeffus ik. Yili ad cukken inekkaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 49, 'Xaîi, neppa d issekniyen iberrzen, deg idmaren n wid iwumi teppunefk tmusni. Siwa imednas, i inekôen issekniyen nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 50, 'Nnan: "a lemmer id rsen fellas, issekniyen s$uô Mass is"! Ini: "issekniyen ar Öebbi kan. Nek, d aneddaô kan, ipbegginen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 51, 'Ne$, ur steqnaâen ara s trusi $uôek, s$uône£, n Tezmamt, malen asen p. Deg waya, s tidep, aêunu, akked usmekti i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 52, 'Ini: "Iqadd Öebbi, d anagi gari yidwen. Issen i illan di tmurt akked igenwan. Wid iumnen di tkerkas, u ugin Öebbi, widak d imexsuôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 53, 'Sêirin k $ef uâaqeb. Lemmer maççi d lajel ipwassnen, a ten id ias uâaqeb. Ih, a ten id ias, deqzalla, ur bnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 54, 'Sêirin k $ef uâaqeb. Ih, Loahennama a ppezzi i ijehliyen', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 55, 'Ass ideg ar asen isbur uâaqeb, sennig sen, akw seddaw ivaôen nnsen, ad Yini: "jeôôbet ayen txeddmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 56, 'A yimdanen iW iumnen, ni$ tamurt iW tewsaâ. Ihi, âabdet iyI, Nek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 57, 'Yal iman, ad ijeôôeb tameppant; sinna, $uône£ a d tu$alem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 58, 'Wid iumnen, ixeddmen ayen ilhan, ad asen Nerr tanezdu$t di Loennet m t$uôfatin, ddaw as isaffen ppazzalen, degs ad wekkôen. D asaâdi warraz n wid ixedmen lxiô,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 59, 'wid iûebôen, ippeklen $ef Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 60, 'Acêal n lewêuc, ur d neppawi ôôeéq nnsen. Öebbi Iôeéq iten, u Iôeéq ikwen. Neppa, Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 61, 'Ma testeqûav ten: "anwa i Ixelqen tamurt akked igenwan, i Inuben s yiîij akked waggur"? A d inin, war ccekk: "d Öebbi". Ihi, acimi wexxôen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 62, 'Öebbi Issugut l$it i win i S ihwan, deg imdanen iS, u Iwezzen as. Ih, Öebbi Issen yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 63, 'Ma testeqûav ten: "anwa id Isse$layen aman seg igenni, Issidir yissen akal, deffir tmeppant is"? A d inin, war ccekk, "d Öebbi". Ini: "ccekôan i Öebbi". Maca, tegwti degsen, ur fhimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 64, 'Tameddurt agi, di ddunit, siwa lhawiyya, d wurar. D axxam aneggaru, war ccekk, ay d amuddir, lemmer éôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 65, 'Mara rekben di lbabuô, ad naâôen Öebbi, d idiniyen zeddigen $uôeS. Mi ten Isellek ar lberr, atnan la pcaraken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 66, 'Ad nekôen ayen i sen Nefka, ad zhun, deqqal ad éôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 67, 'Day ur walan ara, Nerra loamaâ n laman, wanag la pwaxvafen imdanen i sen d izzin? Day ad amnen di tkerkas, u ad nekôen l$it n Öebbi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 68, 'Anwa i idensen kteô: win id isnulfan tikerkas af Öebbi, ne$ win irran tidep d tikerkas, mi t id tusa? Day maççi d Loahennama ay d tanezdu$t i ijehliyen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 69, 'Wid ijuhden ar loiha nne£, a ten Nenhu, war ccekk, s iberdan nne£. Ih, Öebbi Ippili ar lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 1, 'Alm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 2, 'IôÔöumiyen rnan ten,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 3, 'deg wakal aqôib mavi. Deffir lexsaôa nnsen, ad rnun,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 4, 'di kra iseggwasen. Lameô ar Öebbi, uqbel aya, u ssyen $eô da. Assen, ad feôêen lmumnin', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 5, 's rrbeê n Öebbi. Isserbaê win i S ihwan. Neppa, d Uzmir, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 6, 'D lemâahda n Öebbi. Öebbi ur Ipxallaf ara lemâahda S, maca, tegwti n medden ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 7, 'Ssnen ayen id innunnten, di tmeddurt n ddunit. £ef laxeôt nitni stehzan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 8, 'Day ur meyyzen ara deg iman nnsen? Ur Ixliq Öebbi tamurt, igenwan, akked wayen illan garasen, siwa s tidep, akked lajel ipwassnen. Ih, aîas n medden i inekôen timlilit d Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 9, 'Day ur unagen ara di tmurt, ad walin amek tevôa d wid i ten id izwaren? Llan ifen ten tazmert, $zan tamurt, $elben ten akken i p âamôen. Usan ten id imazanen nnsen, s ubeggen. Ur ten Idnis Öebbi. Maca d nitni i idensen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 10, 'D$a teqseê taggara n laâôuô. Skaddben issekniyen n Öebbi. Pmmaâliken fellasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 11, 'Öebbi Inezzu lxelq; sinna, Ippales it id. Sinna, $uôeS ara tu$alem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 12, 'Ass ideg ara d ijbu yimir, ad feqâen ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 13, 'Ur ten pselliken wid pcaraken. Ad nekôen wid pcaraken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 14, 'Ass ideg ara d ijbu yimir, assen ad mfaôaqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 15, 'Wanag wid iumnen u xeddmen ayen ilhan, ad zhun di tebêirt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 16, 'Ma d wid ijehlen, inekôen issekniyen nne£, akked temlilit n laxeôt, widak ar uâaqeb ara rsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 17, 'Gedha s Öebbi, tameddit nnwen, taûebêit nnwen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 18, 'I Neppa ccekôan, di tmurt akked igenwan, tameddit u di pnaûfa n wass.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 19, 'Issuffu$ ed amuddir si lmegget. Issuffu$ ed lmegget seg umuddir. Issidir akal, deffir tmeppant is. Akka ara d teff$em.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 20, 'Seg issekniyen iS: Ixelq ikwen seg wakal. Aql akwen d imdanen tembwezzâam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 21, 'Seg issekniyen iS: Ixelq awen, segwen, tiâggaltin nnwen, a pzed$em yidsent. Irra garawen tayri, lmaênana. Deg waya, s tidep, issekniyen i ugdud ipmeyyizen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 22, 'Seg issekniyen iS: lxelq n tmurt akked igenwan, amgirred ger tutlayin nnwen, akked initen nnwen. Deg waya, s tidep, issekniyen i imusnawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 23, 'Seg issekniyen iS: ives nnwen deg iv, deg wass, anadi nnwen n lfevl iS. Deg waya, s tidep, issekniyen i ugdud isellen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 24, 'Seg issekniyen iS: Issenâat awen lebôaq, degs tugdi, asirem. Issadar ed aman seg igenni, Issidir yissen akal, deffir tmeppant is. Deg waya, s tidep, issekniyen i ugdud ifehmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 25, 'Seg issekniyen iS: s lameô iS, igenni akked tmurt bedden. Sinna, ma Isawel awen d, yiwen usiwel, seg wakal kunwi a d teff$em.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 26, 'IneS i illan di tmurt akked igenwan. Akken ma llan, unzen aS.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 27, 'D Neppa i Inezzun lxelq, sinna Ippales it id. D ayen i S isehlen mavi. IneS umedya aâlayan, di tmurt akked igenwan. Neppa d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 28, 'Ibbwi yawen d amedya, seg iman nnwen: day tcerkem d waklan nnwen, ayen i s ikwen N$at, d$a tâadlem yidsen? Day ten teppagwadem, akken teppemyagwadem garawen? Akka ay Nepfeûûil issekniyen i ugdud ipxemmimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 29, 'Xaîi! Wid idensen teddun d lhawiyyat nnsen, ur ssinen. Anwa ara inhun wid Itlef Öebbi? Ur sâin imâiwnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 30, 'Smil udem ik adini ar tidep, d lxelq n Öebbi akken id Ixleq imdanen. Ur illi ubeddel, di lxelq n Öebbi. Wagi d ddin amxallef, maca, tegwti n medden ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 31, 'D imvuâen iS, êezzbet aS, beddet i téallit, ur ppilit seg wid ipcaraken,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 32, 'seg wid ifeôqen ddin nnsen. U$alen d îayfat, yal akabar icôeê s wayen isâa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 33, 'Imdanen, ma iwwet iten wugur, ad naâôen Mass nnsen, d imvuâen iS. Sinna, ma Isêess asen aêunu, s$uôeS, a pwaliv arbaâ degsen pcaraken i Mass nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 34, 'iwakken ad nekôen i sen Nefka. Zhut! Deqqal a ppeéôem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 35, 'Ne$ Nessader asen ed amvebbeô, i ipmeslayen $ef wayen i S pcaraken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 36, 'Mi Nesêess aêunu i imdanen, ad ceôêen yis. Ma têuza ten tucmip, seg wayen id urwen ifassen nnsen, ad aysen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 37, 'Day ur walan ara ar Öebbi Issugut ôôeéq i win i S ihwan, u Iwezzen. Deg waya, s tidep, issekniyen i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 38, 'Efk as leêqq is i llezm ik, i ume$bun, i win id ibbwi ubrid. Ppif akka i wid ib$an udem n Öebbi. D widak ay d imerbaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 39, 'Ayen teppakem n rrba, iwakken ad issem$weô ayla n medden, ar Öebbi ur issim$uô ara. Ayen tepzekkim $ef udem n Öebbi, d ayen ara ibuôekten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 40, 'Öebbi, ikwen id Ixelqen, sinna, ikwen I$aten, sinna, ara kwen In$en, sinna, ara kwen id Issidren. Day ara ixdem kra, seg waya, yiwen seg wid tepcarakem? Gedha s yiS, Aâlayan sennig wid pcaraken!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 41, 'Ivehô ed lefsad di lberr u di yill seg wayen id urwen ifassen n medden, iwakken ad Isukk fellasen kra seg wayen xedmen, amar a d u$alen s abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 42, 'Ini: "iniget di tmurt, muqlet amek tevôa d imezwura. Tegwti, segsen, pcaraken".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 43, 'Err udem ik ar ddin amxallef, uqbel a d ias s$uô Öebbi, ass ur nepwexxiô. Assen, ad pwaferzen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 44, 'Win ijehlen, tijehli s mgal is; wid ixeddmen ayen ilhan, gemren i iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 45, 'Iwakken ad Ikafi, s lfevl iS, wid iumnen u xeddmen ayen ilhan. Neppa, s tidep, ur Iêemmel ara ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 46, 'Seg issekniyen iS: Ippazen ed avu abcir, ad awen Isêess, cwiî, seg uêunu S; ad iaâjel lbabuô, s lameô iS. A pnadim lfevl iS, amar a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 47, 'Ni$ Nuzen ed, uqbel ik, imazanen i igduden nnsen. Usan ten id, s ubeggen. Nerra d ppaô seg wid ibe$wven. Aslak n lmumnin d lwaoeb nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 48, 'Öebbi, id Ippaznen avu isselêayen asigna, a t ifser, deg igenni, akken i S ihwa, a t Issemfaôeq, a pwaliv ageffur a d iteffe$ segs. Mi t Issawev ar wid i S ihwan, deg imdanen iS, a ten tafev ceôêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 49, 'Wanag, iu$ lêal, llan uysen, uqbel ad asen d i$li.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 50, 'Wali lateô uêunu n Öebbi: amek id Issidir akal, deffir tmeppant is. Ih, d Win, s tidep, i Issidiren lmeggtin. Neppa Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 51, 'Mara Nazen avu, ara walin ippiwôi$, a pdum, deffir es, tjehli nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 52, 'Ma d keçç, s tidep, ur tezmirev a pperrev lmeggtin ad slen, ne$ iâeééugen ad slen i tnaâôit, ma u$alen $er deffir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 53, 'Ur tezmirev a penhuv ider$alen, mgal ttelfan nnsen. Ara terrev ad ak slen, siwa wid iumnen s issekniyen nne£. Nitni d imvuâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 54, 'Öebbi, ikwen Ixelqen si ôehfan; sinna, deffir ôehfan, Irra tazmert; sinna, deffir tezmert, Irra ôehfan, akked ccib. Ixelleq ayen i S ihwan. Neppa d Amusnaw, d Aêernuk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 55, 'Ass ideg ara d ijbu yimir, ad gallen ibe$wviyen, ar siwa saâa segmi mmuten. Akka ay skiddiben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 56, 'Ad inin wid iwumi teppunefk tussna, akked liman: "ni$ teqqimem di Tezmamt n Öebbi, ar ass n tnekra. Wagi d ass n tnekra, maca tellam ur tessinem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 57, 'Assen, wid idensen, ur ten tepsellik nndama ne$ asuter n ssmaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 58, 'Ni$ Nefka, i medden, yal amedya di Leqwôan agi. Maca, mi sen d tebbwiv assekni, ad ak inin, war ccekk, wid ijehlen: "kunwi d wid ireoonen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 59, 'Akka i Iselle$ Öebbi ulawen n wid ur nessin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 60, 'Eûbeô, ih, lemâahda n Öebbi d tidep. Ur k sêirin, wid ur nepputebbet!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 1, 'Alm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 2, 'Wigi d issekniyen n Tezmamt tuûwibt;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 3, 'd nnhaya u d aêunu i iâaôviyen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 4, 'wid ibedden i téallit, ipzekkin, ipputebbten af laxeôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 5, 'Wigi, di nnhaya s$uô Mass nnsen. Wigi, d isaâdiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 6, 'Ger yimdanen, wid ippa$en awal n zzhu, iwakken ad nnetlafen seg ubrid n Öebbi, war tamusni. U fellas ttihin. I wigi, aâaqeb isdullun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 7, 'Ma mlan as issekniyen nne£, ad ibren s tem$weô, amzun ur asen isli, amzun âaégen as imeééu$en. Xebbeô it s uâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 8, 'Ih, i wid iumnen, ixeddmen ayen ilhan, leonanat isaâdiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 9, 'Degsen ad wekkôen. Lemâahda n Öebbi d tidep. Neppa d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 10, 'Ixleq igenwan, war tigejda ara twalim. Irra di tmurt idurar, iwakken ur tepzenzil ara yiswen. Iwezzaâ, degs, yal lxelq. Nessader ed aman seg igenni. Nessem$i d degs, yal tayuga tukyist.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 11, 'Wagi d lxelq n Öebbi. Sseknet iyi d, acu d xelqen wid ur nelli d Neppa. Xaîi, imednas atnan di ttelfan n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 12, 'Ni$ Nefka i Luqman ûûwab: "snemmer Öebbi. Win isnemmiren, isnemmir kan i iman is. Ma d wid ijehlen, ihi, Öebbi d Asâay, d Amaâzuz".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 13, 'Mi inna Luqman i mmi s, la t isselmad: "a mmi! Ur pcarak i Öebbi. Ccerk, s tidep, d ddens abarar".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 14, 'Nweûûa amdan $ef imawlan is. Imma s temêen s tadist is. Tuîva s, sin iseggwasen. Snemmer iyI, u i imawlan ik. Tu$alin $uôI.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 15, 'Ma êeppmen fellak, ad iyI tcarkev ayen ur tessinev, ur asen teddu di leb$i. Illi yidsen d uwqim di ddunit. Ddu d ubrid n wid isteôoâen $uôI. Sinna, tu$alin nnwen $uôI, ad awen Mle$ ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 16, '"Ih, a mmi, xas am taéeyt uâaqqa ucceryad, ara yilin di teéôut, ne$ deg igenwan, ne$ di tmurt, a p id Iawi Öebbi. Ih, Öebbi d Laîif, Iéôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 17, 'A mmi, bedd i téallit, ameô lewqama, îîixxeô i wayen n dir, eûbeô i wayen ara k id iasen! Aya, s tidep, seg uâzzem i lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 18, 'Ur sxunzuô ar medden, ur teddu di tmurt s îî$aya! Öebbi, s tidep, ur Iêemmel yal imnefxi, amzuxi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 19, 'Iôqiq di tikli k, ssers ûûut ik! Ni$ ûûut ucmit mavi, d win n ye$yal".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 20, 'Day ur twalam ara, Inub Öebbi fellawen s wayen akw illan deg igenwan, akked wayen illan di tmurt? Isserwa yawen l$it iS, uvhiô, uffir. U llan l$aci i ipnamaren $ef Öebbi, war tamusni, ne$ nnhaya, ne$ Tazmamt timnewweôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 21, 'Ma nnan asen: "ddut akked wayen id Issader Öebbi", a d inin: "xaîi, a neddu akked wayen id nufa ar imezwura nne$". I ma Cciîan atan la ten inecced ar uâaqeb n tmes?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 22, 'Win ifkan i Öebbi udem amvuâ, u neppa d aâeôvi, iîîef deg ufus iûeêêan mavi. Ar Öebbi, tu$alin n lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 23, 'Win ijehlen, ur k t$webben tjehli s! £uône£, tu$alin nnsen; ad asen Nini acu xedmen. Öebbi, s tidep, Iéôa i illan deg idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 24, 'A ten Neoo ad zhun cwiî, sinna, a Nêeppem fellasen aâaqeb iwaâôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 25, 'Ma testeqûav ten: "anwa i Ixelqen tamurt akked igenwan"? A d inin, war ccekk: "d Öebbi". Ini: "ccekôan i Öebbi". Maca, tegwti degsen, ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 26, 'I Öebbi i illan akw di tmurt akked igenwan. Ih, Öebbi d Asâay, d Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 27, 'Xas lukan ttjuô akw n ddunit d leqlamat, u yill, ernu yas ûa ilellen nniven, d lmidad nnsen, ur pqamen awalen n Öebbi. Ih, Öebbi d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 28, 'Lxelq nnwen, tanekra nnwen, amzun d yiman yiwen kan. Ih, Öebbi Issel, Ipwali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 29, 'Day ur twalav ara, Öebbi Issekcam iv deg wass, Issekcam ass deg yiv. Iêeppem i yiîij akked waggur ad lêun, ar lajel ipwassnen. Ih, Öebbi Iéôa ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 30, 'Akka, acku Öebbi d Tidep. Ayen u$uô naâôen, war Neppa, d tikerkas. Öebbi, d Aâlayan, d Ameqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 31, 'Day ur twalav ara ssfina, teppazal di yill s lqwedôa n Öebbi, iwakken ad awen d Issenâat seg issekniyen iS. Ih, deg wayagi, issekniyen i yal aûebôi isnemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 32, 'Ma tesbur asen lmuja, am tillas, ad nujen ar Öebbi, $uôeS s ddin azedgan. Mi ten Isellek ar lberr, kra, degsen, îîfen deg wawal nnsen. I inekôen issekniyen nne£, siwa yal axeddaâ ajehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 33, 'A yimdanen! Ëezzbet i Mass nnwen. Agwadet ass ideg ababat ur d ilehhu d mmi s, u mmi s ur d ilehhu d baba s, s wacemma. Ih, lemâahda n Öebbi, d tidep. Ur kwen tep$uôôu tmeddurt n ddunit. Ur kwen issefôa$ im$weôôi, $ef Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 34, 'Öebbi, s tidep, $uôeS tamusni n yimir. Issadar ed ageffur. Iéôa i illan di tâabbuvin. Ur iéôi yiwen acu ara ikseb azekka; ur iéôi yiwen anwa akal ideg ara immet. Öebbi, s tidep, Iéôa, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 1, 'Alm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 2, 'Tarusi n Tezmamt, ur illi degs ccekk, s$uô Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 3, 'Ne$ a d inin: "isnulfa p id". Xaîi, neppat, d tidep s$uô Mass ik, iwakken a pnedôev agdud u$uô ur d iusi ara uneddaô, uqbel ik, amar ad pwanhun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 4, 'Öebbi i Ixelqen tamurt, igenwan, akked wayen illan garasen, di sdis wussan; sinna, Iâannec $ef usgeld. Ur tesâim, war Neppa, bab, ne$ amcafaâ. Day ula d tesmektayem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 5, 'A d Iseyyi lameô seg igenni ar tmurt; sinna, ad iu$al $uôeS deg ibwass, lmudda s: agim iseggwasen, s leêsab nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 6, 'Akka, Umusnaw n wayen iffren, u n wayen ur neffir, Uzmir Ipêunun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 7, 'I Iûûegmen akw ayen Ixleq. Inza d lxelq n umdan, si talaxt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 8, 'Sinna, Issuffe$ ed tarwa s si l$ella, degs cwiî n waman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 9, 'Sinna, Imesl it, Iûûuv degs, si ôôuê iS. Irra yawen timesliwt, iéôi, ul. Drus ay tesnemmirem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 10, 'Nnan: "ma nweddeô di tmurt, day a d nepwaxleq tikelt nniven"? Xaîi, nekôen timlilit akked Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 11, 'Ini: "ad iddem ôôuê nnwen, lmelk n tmeppant i ippukelfen fellawen. Sinna, ar Mass nnwen a ppu$alem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 12, 'Lemmer a pwaliv ibe$wviyen, ad brun i iqweôôa nnsen, zdat Mass nnsen: "a Mass nne$! Nwala, nesla; Err ane$ a nexdem ayen ilhan. S tidep, numen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 13, 'Lemmer i £ ihwi, yili Nefka, i yal ôôuê, nnhaya s. Maca, ad ivôu wayen Nni$: "war ccekk, ad Acaôe$ Loahennama s leonun akked yimdanen, mejmulen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 14, 'Ihi, jeôôbet imi teppum a d temlilem d wass nnwen agi! Nekwni, ih, Neppu kwen. Jeôôbet aâaqeb, n lebda, ilmend n wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 15, 'I iumnen kan, s issekniyen nne£, d wid, mara ten id mmektin, ara weddin ad knun, ara isbucuâen Mass nnsen s ccekôan, nitni ur pzuxxun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 16, 'Ppensaren d ibeôdiyen nnsen, seg imîeôêen, pnujun $eô Mass nnsen, s tugwdi d usirem. Seg wayen iten N$at, pseddiqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 17, 'Ur iéôi yiwen acu i sen Ffre$ n lfeôê. D arraz n wayen llan xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 18, 'Win illan d lmumen, day am win illan d amed$ul? Ur aâdilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 19, 'Ihi, i wid iumnen, ixeddmen ayen ilhan, leonanat imôaêbiyen, ara zed$en, ilmend n wayen xeddmeùn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 20, 'Wanag wid ide$wlen, di tmes ara zed$en. Yal tikelt ideg ara b$un a d ff$en segs, a ten rren $uôes, ad asen inin: "jeôôbet aâaqeb n tmes i tnekkôem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 21, 'Ih, a Nessukk fellasen aâaqeb aqôib mavi, war aâaqeb abarar. Ahat a d u$alen s abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 22, 'Anwa i idensen sennig n win iwumi d dekôen issekniyen n Mass is, iu$al iwexxeô asen? Ih, a d Nerr ppaô seg ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 23, 'Ni$ Nefka yas Tazmamt i Musa. Ur ppili di ccekk af temlilit yideS! Nerra p d nnhaya i At Isôail.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 24, 'Nesbedd, segsen, iselmaden; nnehun s lameô nne£, mi ûebôen, u llan pputebbten $ef issekniyen nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 25, 'Ih, Mass ik, Neppa, ad Iêudd garasen, ass n tnekra, $ef wayen i$ef mgarraden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 26, 'Day ur ten inha ara wayen Nesqucc isuta, uqbel nnsen? La leêêun $ef tnezdu$in nnsen. Deg waya, s tidep, issekniyen. Day ur sellen ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 27, 'Day ur zôin ara Neppawi aman s akal aquôan; Nessuffu$ ed, yissen, iâaqqayen; teppen, segsen, nitni akked lmal nnsen. Day ur pwalin ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 28, 'Qqaôen: "melmi l$elb agi, ma tessawalem tidep"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 29, 'Ini: "ass n l$elb, liman n wid ijehlen, ur ten infaâ; ur pganin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 30, 'Ihi, wexxeô asen, ggani. Nitni, s tidep, la pganin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 1, 'A Nnbi! Ëezzeb i Öebbi, ur ppa$ awal i ijehliyen akked ixabiten. Öebbi, s tidep, Izga d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 2, 'Ddu akked wayen i k d Ippuweêêan, s$uô Mass ik. Ih, Öebbi Ippuxebbeô $ef wayen txedmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 3, 'Ppkel $ef Öebbi. Iqadd Öebbi d Awkil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 4, 'Ur Irra ara Öebbi sin wulawen di tfekka n urgaz. Ur Irra ara tilawin nnwen, i tmetlem ar iârar n tyimmatin nnwen, d tiyimmatin nnwen. Ur irra ara wid id tessekrem, d tarwa nnwen. Ayagi, d awal nnwen, seg imawen nnwen. Öebbi Issawal tidep. Neppa Ippawi d ubrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 5, 'Ssiwlet asen am ibabaten nnsen; akka i iwqem ar Öebbi. Ma ur tessinen ara anwi ay d ibabaten nnsen, atmaten nnwen di ddin, d iqôiben nnwen. Ur illi u$ilif $ef wayen teffalîam degs, siwa ayen âammden wulawen nnwen. Öebbi Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 6, 'Nnbi iqôeb ar lmumnin, sennig iman nnsen. Tilawin is, d tiyimmatin nnsen. Wid ippemyilin, mqaôaben di Tezmamt n Öebbi, sennig lmumnin akked iminigen. Siwa ma tgam tajmilt i imeddukwal nnwen. Ayagi iura di Tezmamt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 7, 'Mi Neîîef si lambiyya lmitaq nnsen, u si keçç, si Nuê, Ibôahim, Musa, u si Âisa, mmi s n Meryem, Neîîef segsen lmitaq lfayeq,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 8, 'iwakken ad Iêtec imawlan n tidep, af tidep nnsen. Ihegga d, i ijehliyen, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 9, 'A wid iumnen! Mmektit ed l$it ikwen I$at Öebbi. Mi d usan $uôwen iâsekôiwen, Nuzen asen d avu, akked iâsekôiwen ur twalam. Öebbi Izga Ipwali ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 10, 'Mi wen d kkan sennig wen, seddawat wen, mi zzint wallen, ulawen bbwven s ijuxax, tepmeyyizem yal ameyyez $ef Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 11, 'Dinna, ppwajeôôben lmumnin, enhezzen s leqseê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 12, 'Mi d nnan ixabiten, akked imehzulen n wul: "ay $ d Iwaââed Öebbi, akked Umazan iS, siwa a$uôôu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 13, 'Mi d inna urbaâ segsen: "a yAt Yatrib, ur illi umekkan i kunwi, u$alet"! Kra segsen ssutren tsriê i Nnbi, nnan: "ih, ixxamen nne$ aâran". Nitni, ur llin aâran, b$an kan ad rewlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 14, 'Ma kecmen ten id, si leriaf is, sinna, ssutren asen ad xubten, ad xubten. Cwiî kan ara kukrun fellas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 15, 'Ni$ llan âuhden s Öebbi, uqbel, ar ur ppu$alen ar deffir. Aâahed s Öebbi ad ippuqeîîi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 16, 'Ini: "ur kwen tenfaâ trewla, ma trewlem si tmeppant, ne$ si îôad. Ara tezhum, siwa tallit wezzilen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 17, 'Ini: "anwa wa, ara kwen ikksen seg ufus n Öebbi, ma Ib$a yawen cceôô, ne$ Ib$a yawen aêunu"? Ur asen ppafen, war Öebbi, bab, ne$ asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 18, 'Ni$ Öebbi Iéôa wid degwen, i ipâawwiqen, wid iqqaôen i watmaten nnsen: "Yyat $uône$"! Drus kan degsen, i ikecmen îôad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 19, 'D imceêêiyen ar loiha nnwen. Ma tusa d tugdi, a ten twaliv la k pmuqulen, tezzint wallen nnsen, am win tessexciwit tmeppant. Ma tekkes tugdi, a kwen gezren s yilsawen uqviâen. D imceêêiyen $ef lxiô. Wigi, ur uminen ara. Ihi, Imêa Öebbi igiten nnsen. Ayagi, d ayen isehlen i Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 20, '£ilen ikabaren ur ôuêen ara. Lemmer a d asen ikabaren, ad ssirmen, ar nitni, di ûûeêôa ay llan, ar Waâôaben n ucluê, steqsayen fellawen. Lemmer llan yidwen, cwiî kan ara nna$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 21, 'Ni$, i kunwi, Amazan n Öebbi d amedya amxallef i win ippaôoun Öebbi, akked was aneggaru, id ismektayen aîas Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 22, 'Mi walan lmumnin ikabaren, nnan: "ayagi d ayen i $ d Iwaââed Öebbi, akked Umazan iS. Öebbi, akked Umazan iS, Ssawlen tidep". Ay sen irna kan, siwa liman akked wannuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 23, 'Ger lmumnin, llan irgazen i iîîfen deg wayen i$ef âuhden Öebbi. Garasen, wid iêellen timeôoiwt nnsen, garasen wid ipganin. Ur bedlen mavi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 24, 'Iwakken ad Ikafi Öebbi imawlan n tidep, $ef tidep nnsen, u ad Iâaqeb ixabiten, ma ihwa yaS, ne$ ad asen Issuref. Ih, Öebbi Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 25, 'Iééaâ Öebbi wid ijehlen, s iêecciô nnsen. Ur ppaddamen lxiô. Issuli Öebbi îôad i lmumnin. Öebbi Izga d Uohid, d Uzmir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 26, 'Issers ed, si lebôuj nnsen, wid i sen ifkan afus, seg wAt Tezmamt. Issekcem tugdi deg ulawen nnsen. Arbaâ ten$am ten, arbaâ têebsem ten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 27, 'Irra kwen tweôtem akal nnsen, ixxamen nnsen, ayla nnsen. D akal ur taâfisem. Ih, Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 28, 'A Nnbi! Ini i tlawin ik: "maday teb$amt tameddurt n ddunit, akked ccbuê is, yyamt a kwent $ite$, ad a kwent bru$, berru umâin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 29, 'Ma illa teb$amt Öebbi, Amazan iS, akked uxxam aneggaru, ihi, Ihegga d Öebbi, i tâaôviyin, segkwent, arraz ameqwôaêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 30, 'A tilawin n Nnbi! Tid segkwent ara iawin abekkav ufviê, a ppeppuâaqeb berdayen. Ayagi d ayen isehlen i Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 31, 'Tin segkwent i iunzen i Öebbi, akked Umazan iS, u txeddem ayen ilhan, ad as Nefk arraz berdayen, u Nhegga yas d l$it ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 32, 'A tilawin n Nnbi! Ur tellimt am tlawin nniven. Ma têezzbemt, ur teppeccvemt deg wawal, a kwent isirem umuvin n wul. Inimt awal uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 33, 'Ilimt deg ixxamen nnkwent. Ur pcebbiêemt acebbeê n at war tussna imenza. èÈéalemt, zekkimt, ôavimt Öebbi akked Umazan iS. Ib$a kan Öebbi a kwent ipwakkes nnkel, a tawacult n Uxxam. U, a kwent Izzizdeg nezzeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 34, 'Mmektitemt ed ayen i kwent $ôan, deg ixxamen nnkwent, n issekniyen n Öebbi, akw n ûûwab. Ih, Öebbi Izga d Laîif, Ippuxebbeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 35, 'Ih, imvuâen, timvuâin, lmumnin argaz tameîîut, itubiyen, titubiyin, wid akked tid issawalen tidep, iûebôiyen, tiûebôiyin, wid akked tid ippagwaden, wid akked tid ipseddiqen, wid akked tid ippuéumen, wid akked tid ipêaraben $ef tuzzuft nnsen, wid akked tid id immektayen aîas Öebbi; i wigi, Ihegga d Öebbi ssmaê akked warraz abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 36, 'Ur issefk ara i win, ne$ tin iumnen, ad smenyafen lameô nnsen, ma Iseyya d lameô Öebbi, akked Umazan iS. Win inuqmen Öebbi, akked Umazan iS, ni$ innetlaf ttelfan n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 37, 'Mi tenniv i win I$at Öebbi, u t$atev: "jmaâ $uôek, tameîîut ik, êezzeb i Öebbi"; teffrev deg iman ik, ayen ara d Isban Öebbi. Tugadev medden. D Öebbi, i iwatan a T tagwadev. Mi s ibra Zayed, Njewo ik yides, iwakken ur teppili lhejna i lmumnin, ma u$en tilawin n wid id ssekren, mara ad sent brun. Ad iûaô lameô n Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 38, 'Ur telli lhejna f Nnbi, deg wayen Iêeppem fellas Öebbi; d tannumi n Öebbi $ef imezwura. Lameô n Öebbi izga ipwafta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 39, 'Wid issawaven tibôatin n Öebbi, i T ippagwaden, ur ppagwaden yiwen, siwa Öebbi. Öebbi Iqadd i uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 40, 'Ur illi Muêemmed d ababat n yiwen seg irgazen nnwen, maca, d Amazan n Öebbi, u d aneggaru n lambiyya. Öebbi Izga Issen yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 41, 'A wid iumnen! Mmektit ed Öebbi, maççi d izli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 42, 'Sbuccuâet eP, ûûbeê, tameddit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 43, 'D Neppa i d Inuben fellawen, akked lmalayek, iwakken a kwen Issuffe$ si tillas ar tafat. Izga Ipêunu $ef lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 44, 'Asmi ara T magren, azul nnsen d: "tifrat"! Ihegga yasen d arraz ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 45, 'A Nnbi! Nuzen ik id d anagi, d abcir u d aneddaô,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 46, 'i ineccden ar Öebbi, s tsriê iS; d asavef icaâlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 47, 'Becceô lmumnin s lfevl ameqwôan i nitni, s$uô Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 48, 'Ur ppa$ awal i ijehliyen akked ixabiten. Ur ssemêas, i ccum nnsen. Ppkel $ef Öebbi, Iqadd Öebbi d Awkil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 49, 'A wid iumnen! Ma tu$em tid iumnen, sinna, tebram asent, uqbel ma tennulem tent, ur fellawen ad asent têesbem tallit. £itet pent, serrêet asent, s wudem uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 50, 'A Nnbi! Nêell ak tilawin iwumi tefkiv tiqviâen nnsent, tiklatin ik, si tid i k Iqsed Öebbi, iss is n âam ik, tid n tâamtin ik, tid n xal ik, tid n txaltin ik iunagen yidek, tameîîut iumnen, ma tefka iman is i Nnbi, ma ib$a Nnbi a p ya$. D lemziyya i keçç, war lmumnin. Ni$ Neéôa acu i sen Nseyya af tlawin nnsen, akked teklatin nnsen. Iwakken ur teppili fellak lhejna. Öebbi Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 51, 'A ppesganiv tin i k ihwan segsent. A d tawiv $uôek tin i k ihwan, ne$ tin teb$iv si tid tâazlev. Ur fellak tuzzma. Akka i iwulem, iwakken ad qenâant, ur $webbnent, ad ôavint akw, ayen i sent tefkiv. Öebbi Iéôa i illan deg ulawen nnwen. Öebbi Izga d Amusnaw, Iêellem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 52, 'Ur ak êellent tlawin, sya d asawen, ne$ abeddel n tlawin, xas tâaoeb ik ûûifa nnsent, siwa tiklatin ik. Öebbi Izga Issikid yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 53, 'A wid iumnen! Ur keççmet ar texxamin n Nnbi, ar awen iâammed, d inebgawen ar wuççi, ur teggunim. Maca, ma tepwâaôvem, kecmet. Mi teççam, sahlet; ur ssiôxiset ameslay. Ayagi, s tidep, iqelleq Nnbi. Isetêa segwen. Öebbi ur Ipsetêi $ef tidep. Ma tessutrem asent ta$awsa, ssutret ep deffir tsabert. Yif it wakka, i tezdeg n wulawen nnwen, akked wulawen nnsent. Ur awen ilaq ara a pjjerim Amazan n Öebbi, ne$ a ppa$em tilawin is, deffir es, d awez$i. Ayagi, ad yili, ar Öebbi, d lefviêa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 54, 'Ama tessknem d lêaoa, ne$ teffrem p, Öebbi, s tidep, Iéôa yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 55, 'Ur telli tiyta degsent af ibabaten nnsent, arraw nnsent, atmaten nnsent, arraw n wamaten nnsent, arraw n tsetmatin nnsent, tilawin nnsent, ticrikin nnsent. Ad êezzbent i Öebbi. Öebbi, s tidep, d Anagi n yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 56, 'Öebbi akked lmalayek iS, s tidep, Nuban $ef Nnbi. A wid iumnen! Nubet fellas, ternum as azul aêmayan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 57, 'Ih, wid ijjerin Öebbi akked Umazan iS, Ixza ten Öebbi, di ddunit, di laxeôt. Ihegga yasen d aâaqeb isdullun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 58, 'Wid ijjerin lmumnin, argaz tameîîut, $ef wayen ur ksiben, ni$ bbwin acehrir akked ubekkav n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 59, 'A Nnbi! Ini i tlawin ik, i iss ik, i tlawin n lmumnin, ad jemâant ijufaô nnsent. Ppif akka, a tent âaqlen, ur tent pooerin. Öebbi Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 60, 'Ma ur êbisen ara ixabiten, imehzulen n wul, akked wid ipxeôôiven di Lmadina, ad ak Nebges $uôsen. Sinna, siwa cwiî n tallit ara yilin, degs, d loiran ik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 61, 'Ad pwaxzun anda ten nufan, ad pwaîîfen, ad pwan$en akw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 62, 'D tannumi n Öebbi ar wid iâaddan zik. Ur teppafev, d awez$i, abeddel, di tannumi n Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 63, 'Steqsan k imdanen, af yimir. Ini: "it Issnen siwa Öebbi". Anwa ad ak imlen, amar imir iqeôb ed?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 64, 'Öebbi, s tidep, Ixza ijehliyen, Ihegga yasen d u$ud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 65, 'Ad wekkôen degs, i lebda; ur ppafen bab, ne$ asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 66, 'Ass ideg ara zzin wudmawen nnsen, ar tmes, ad inin: "a yamxix nne$! A lemmer nunez i Öebbi, u nunez i Umazan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 67, 'Ad inin: "a Mass nne$! Nekwni nunez i igeldan nne$, i imeqwôanen nne$, telfen a$ ar yir abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 68, 'A Mass nne$! Aâqeb iten berdayen, u Xzu ten s leqseê"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 69, 'A wid iumnen! Ur ppilit am wid i ijjerin Musa. Izekka t Öebbi, seg wayen id nnan. Illa ar Öebbi d amxallef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 70, 'A wid iumnen! Ëezzbet i Öebbi, tinim awal umâin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 71, 'Ad awen Iûeggem igiten nnwen, ad Isemmeê ibekkaven nnwen. Win iôuvan Öebbi akked Umazan iS, ni$ ibbwi arraz ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 72, 'Naâôev a nefk lamana i igenwan, i tmurt, i idurar. Ugin a p îîfen. Ugaden p. Ibubb ip umdan. Neppa ard amednus ur nessin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 73, 'Ihi, ad Isâaddi Öebbi aâaqeb af ixabiten akked txabitin, wid akked tid ipcaraken. Ad Issuref Öebbi i wid akked tid iumnen. Öebbi Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 1, 'Ccekôan i Öebbi, i iIan i illan deg igenwan, i illan di tmurt. I Neppa, ccekôan di laxert. Neppa, d Bab n ûûwab, Ippuxebbeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 2, 'Iéôa ayen ikeççmen di tmurt, ayen id iteff$en segs, ayen id iprusun seg igenni, ayen ippalin $uôes. Neppa Ipêunu, Ipsemmiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 3, 'Nnan wid ijehlen: "ur a$ d ippas yimir". Ini: "xaîi, s Mass iw, ara kwen id ias"! Amusnaw n tbavnit, ur idrig fellaS ubruy ubelkim, ama deg igenwan, ama di ddunit; ama seddaw wannect is, ama sennig es; akw, di Tezmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 4, 'Ad Ikafi wid iumnen, ixedmen ayen ilhan. I wigi, ssmaê akked ôôeéq ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 5, 'Wid ikkaten deg issekniyen nne£, sfunnugen, widak, fellasen aâaqeb n twa$it taqeôêant.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 6, 'Wid iwumi teppunefk tmusni, walan ar ayen id irsen $uôek, s$uô Mass ik, d tidep. Ippawi s abrid n Uzmir, Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 7, 'Nnan wid ijehlen: "day ad awen nessken argaz, ar awen d yinin ar ma teftutsem, yal aftutes, i kunwi lxelq amaynut?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 8, 'Iger ed tikerkas $ef Öebbi, ne$ d aôehbani"? Xaîi, wid ur numin ara s laxeôt, haaten deg uâaqeb, akked ttelfan u$miq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 9, 'Day ur walan ara ayen illan zdat sen, u deffir sen, di tmurt akked igenwan? Ma ihwa ya£, a ten Nger seddaw tmurt, ne$ a d Nesse$li fellasen igezzim seg igenni. Deg wayagi, ih, d assekni i yal amdan ucâif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 10, 'Ni$ Nefka s$uône£ lfevl i Dawed. A yidurar, alset yides akked ifrax. Nerra yas uzzal d aleqqaq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 11, 'Eûnaâ tibedâiyin n wuzzal, qiss tindar. Xeddmet ayen ilhan. Nek, Pwali$ ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 12, 'I Sliman: avu. Win n ûûbeê, aggur; win n tmeddit, aggur. Nelli yas taâwint n nnêas. Kra n leonun ad xedmen fellas, s tsriê n Mass is. Win degsen, iveôfen i lameô nne£, Nessukk fellas, aâaqeb ujajiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 13, 'Xeddmen as ayen ib$a: leowamaâ, tiâancuôin, loefnat am iêvunen, ticcuytin iqaâden. Exdem s tnemmirt, a tawacult n Dawed, drus n yimdanen iW i isnemmiren!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 14, 'Mi Nseyya fellas tameppant, ur as faqen ara immut, armi içça taâkwazt is, ubaââuc n wakal. Mi i$li, êulfan leonun ar, lemmer day ssinen tabavnit, ur qqimen deg uâaqeb isdullun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 15, 'Ni$, i Saba, assekni di tnezdu$in nnsen. Snat tebêirin, ta yeffus, ta zelmev. Eççet si l$it n Mass nnwen, u snemmret aS. Tamurt ilhan, Mass Ipsemmiêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 16, 'Wexxôen. Nuzen asen aêemmal n Âarim. Tibêirin nnsen, nerra tent d tibêirin id ippaken l$ella ôéagen, tammemayt, akked tzegwart taxeîîayt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 17, 'Akka ay ten Nqeîîi $ef tijehli nnsen. Day a Nqeîîi wur nejhil?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 18, 'Nerra garasen u ger temdinin i$ef Nburek, timdinin id ivehôen. Nektal tikli garasent: "merêet degsent di laman, am yiv, am ass"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 19, 'Nnan: "a Mass nne$! Zzi$wzef tallit ger zziaôat nne$"! Densen iman nnsen. Nerra ten d tiqûivin. Nesqucc iten wakali. Ih, deg wayagi, war ccek, d issekniyen i yal aûebôi isnemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 20, 'Ni$ Iblis itebbet ed, segsen, ameyyez is. Vefôen t, siwa arbaâ si lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 21, 'Ur isâi kra udabu fellasen. Iwakken kan, a Nissin anwa iumnen s laxeôt, u anwa i illan, fellas, di ccekk. Mass ik Ipêarab af yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 22, 'Ini: "naâret wid i tepkabarem, war Öebbi. Ur sâin taéeyt ubelkim, deg igenwan ne$ di tmurt; ur criken degsen; ur aS illi, garasen, umâiwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 23, 'Cafuâa, s$uôeS, tenfaâ kan win iwumi ip Irad. Alamma, ma tekkes tugdi seg wulawen nnsen, a d inin: "acu id Inna, Mass nnwen"? A d inin: "d tidep, u Neppa d Aâlayen, d Ameqwôan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 24, 'Ini: "anwa ikwen ip$aten, si tmurt akked igenwan"? Ini: "d Öebbi". Nekwni am kunwi, amendeô ma nella di nnhaya, ne$ di ttelfan n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 25, 'Ini: "ur teppuqeîîim $ef wayen nfalîa, ur neppuqeîîi $ef wayen txeddmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 26, 'Ini: "ad a$ Issemlil Mass nne$, sinna, ad Iêudd garane$, s tidep. Neppa d Amêaddi Amusnaw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 27, 'Ini: "sseknet iyi d wid i tqeônem $uôeS, d icriken"! Xaîi, Neppa d Öebbi Uzmir, Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 28, 'Ur k id Nuzen, i imdanen, armi d uqniâ; a pbecôôev, a pnedôev. Maca, tegwti n yimdanen, ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 29, 'Qqaôen: "melmi lemâahda agi, ma tessawalem tidep"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 30, 'Ini: "$uôwen ppaâud ass, ur tezmirem a t teswexxôem, ne$ a t id tesqeôbem, s saâa".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 31, 'Nnan wid ijehlen: "ur neppamen, d awez$i, s Leqwôan agi, ne$ s wayen it id izwaren". Lemmer a pwaliv mara bedden imednas, ar Mass nnsen, pmeslayen garasen. Ad inin uôhifen i imzuxiyen: "lemmer maççi d kunwi, yili nella d lmumnin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 32, 'Ad inin imzuxiyen i uôhifen: "day d nekwni ikwen isfeô$en af nnhaya, mi kwen id iusa? Xaîi, tellam d ibe$wviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 33, 'Ad inin uôhifen, i imzuxiyen: "xaîi! Nncub, iv akked wass, mi têeppmem, fellane$, a nagwi Öebbi, u ad aS negg tanudda". Ffren nndama mi walan aâaqeb. Nerra tiqwlavin $ef imegôav n wid ijehlen. Day ara ppuqeîîin $ef wayen ur xdimen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 34, 'Ur Nuzen ara kra uneddaô ar temdint, mebla ma nnan imeôkantiyen is: "nekwni, ih, nugwi ayen is id teppuceggâam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 35, 'Nnan: "nekwni, n$elb ik ayla, tarwa. Ur nelli d wid ara ippuqeîîin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 36, 'Ini: "ihi Mass iw Ip$iti win i S ihwan u Iwezzen; maca, tegwti n imdanen, ur ssinen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 37, 'Maççi d ayla nnwen, ne$ d tarwa nnwen, ara kwen id iééiéen nezzeh $uône£, siwa wid iumnen, ixedmen ayen ilhan. I nitni arraz berdayen, ilmend n wayen xedmen. Ad ilin, di laman, di t$uôfatin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 38, 'Ma d wid ikkaten deg issekniyen nne£, sfunnugen, widak a d rsen i uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 39, 'Ini: "ih, Mass iw Ip$iti win i S ihwan, deg imdanen iS. Iwezzen as. Ayen akw ara tefkem n cci, ad awen t id Irr. Neppa, Yif akw im$iten".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 40, 'Ass ideg ara ten Ifser, akken ma llan, imiren ad Yini i lmalayek: "wigi, day llan âabden kwent"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 41, 'A d inint: "gedha s yiseK! D Keçç ay d Bab nne$, war nitni. Xaîi, llan âabden leonun. Tegwti degsen umnen yissen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 42, 'Assa, ur imlik yiwen i wayev, segwen, aba$uô ne$ ccqa. A Nini i wid idensen: "jeôôbet aâaqeb n tmes, i tellam tnekôem t"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 43, 'Ma $ôan asen issekniyen nne£ ipbegginen, ad inin: "wagi d argaz kan, i ib$an a kwen istixeô, seg wayen llan âabden imezwura nnwen". Ad inin: "ayagi, siwa d tikerkas id innulfan". Wid ijehlen i tidep, mi ten id tusa, ad inin: "ayagi d ssêur n ûûeê kan"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 44, 'Ur asen Nefki tizmamin, ara lemden; ur asen d Nuzen, uqbel ik, aneddaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 45, 'Skaddben wid i ten id izwaren. Ur asen tebbwiv ara tis mraw n wayen i ippunefken mi skaddben imazanen iW. A tuzzma W, imiren!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 46, 'Ini: "ar yiwet kan, ara kwen nabi$: a pbeddem zdat Öebbi, di sin, ne$ weêêedwen; sinna, a d tesmektim. Ameddakwel nnwen ur illi d aôehbani. Neppa d aneddaô nnwen kan, uqbel aâaqeb uqsiê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 47, 'Ini: "ur awen ssutre$ kra n teqdiât; apan nnwen. Ih, taqdiât iw, ar Öebbi kan. Neppa, $ef yal cci, d Anagi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 48, 'Ini: "ih, Mass iw Ipqeddim tidep, d Amusnaw n tbavnit".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 49, 'Ini: "tusa d tidep, ur d nezzunt tkerkas, ur d ppalsent".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 50, 'Ini: "ma nnetlafe$, nnetlafe$ kan i iman iw. Ma pwanha$, d ayen iyi d Iweêêa Mass iw. Neppa, ih, d Aqôib, Isell".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 51, 'Lemmer a pwaliv mi xelâan, tarewla ur telli. Pwaîîfen, si tama iqeôben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 52, 'Nnan: "numen yis". Amek ara d ssiwven, si tama ibaâden?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 53, 'Ni$ llan zik, nekôen t. Rran akin tabavnit, si tama ibaâden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 54, 'Ad yili ufûil, garasen d wayen ctaqen, akken tevôa, zik, d wid i ten icban. Ih, nitni llan di ccekk imcebbwel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 1, 'Ccekôan i Öebbi, Axellaq n tmurt akked igenwan, i Irran lmalayek d timersulin sut sin, krav, akked kué iferrawen. Irennu, di lxelq, ayen i S ihwan. Öebbi, s tidep, Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 2, 'Ayen Ifka Öebbi uêunu, i medden, ur t itekkes yiwen. Ayen Iîîef, ur izmir yiwen a t id iazen, deffir eS. Neppa d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 3, 'A yimdanen! Mmektit ed a$iti nnwen s$uô Öebbi. Day illa uxellaq, war Öebbi, ikwen iôeéqen seg igenni akked tmurt? Ur illi ôebbi siwa Neppa, ihi acimi tessaâwajem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 4, 'Ma nekôen k, ni$ pwanekôen imazanen, uqbel ik. Ar Öebbi, ara qqlen lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 5, 'A yimdanen! Ih, lemâahda n Öebbi d tidep. Ur kwen tep$uôôu tmeddurt n ddunit! Ur kwen ipkellix um$weôôi, af Öebbi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 6, 'Cciîan, s tidep, d acengu nnwen. Ëesbet ep d acengu. Issawal kan, i ukabar is, ad ilin seg wat tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 7, 'I wid ijehlen, aâaqeb uqsiê. I wid iumnen, ixeddmen ayen ilhan, ssmaê akked warraz meqqwôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 8, 'Day win iwumi Icebbeê yir igiten is, iwakken ad ioâal gerzen…? S tidep, Öebbi Itellif win i S ihwan, Inehhu win i S ihwan. Ur hellek ara iman ik, fellasen. Ih, Öebbi Iéôa acu la ûûenâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 9, 'Öebbi i Ippaznen avu, issalayen asigna. Neppawi t ar tmurt immuten, Nessidir ed, yis, akal, deffir tmeppant is. Akka, tanekra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 10, 'Win ib$an tazmert, tazmert akw ar Öebbi. Awal ukyis ippali $uôeS. Igi ilhan, Iteg as ccan. Aâaqeb uqsiê i wid ippandin tucmitin. A ppemêu tandit nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 11, 'Ixelq ikwen Öebbi seg wakal; sinna, si tiqqit; sinna, Irra kwen d tiyugiwin. Ur treffed tadist, ur tepparew nnta, siwa ma Iéôa t. Ur Izzi$wzif laâmeô i umuddir, ur as t Issenqas, siwa ma di tezmamt. Ayagi, ih, d ayen isehlen i Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 12, 'Ur aâdilen sin ilellen: wa zeddig, éid, iwata i tissit; wayev d ameô$an, d aôéagan. Segsen teppeppem aksum aleqqaq, teppekksem d iâqqucen i teppeqnem. Twalav sfina tepcerrig iten, iwakken a pnadim lfevl iS. Amar a ppesnemmrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 13, 'Issekcam iv deg wass, Issekcam ass deg yiv. Iêeppem i yiîij akked waggur, ad lêun ar lajel ipwassnen. D wagi ay d Öebbi, Mass nnwen. IneS tagelda. Wid i tnaâôem, war Neppa, ur rebêen iclem utemôiw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 14, 'Ma tnaâôem ten, ur sellen i tnaâôit nnwen. Xas slan, ur awen d pparan. Ass n tnekra, ad nekôen ccerk nnwen. Ur k ipxebbiô yiwen am Win Ippuxebbôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 15, 'A yimdanen! Kunwi d ime$ban zdat Öebbi. Öebbi d Asâay, d Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 16, 'Ma ihwa yaS, a kwen Ikkes, a d Iawi lxelq amaynut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 17, 'I Öebbi, ayagi, ur illi d aéayan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 18, 'Win ibubben ur ipbibbi taâkkwemt n wayev. Ma isuter ed afus win iâabban, ur s ipwakkas wacemma, xas ma si llezm is. Nabi kan wid ippagwaden Mass nnsen di tbavnit, u péallan. Win ipzekkin, i iman is kan i ipzekki. Tu$alin ar Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 19, 'Ur iaâdil uder$al akked win ipwalin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 20, 'ne$ tillas akked tafat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 21, 'ne$ tili akked una$uô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 22, 'Ur aâdilen imuddiren akked lmeggtin. Öebbi, s tidep, Issel i win i S ihwan. Keçç, ur tezmirev a ppeslev i wid illan di tneîlin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 23, 'Keçç, d aneddaô kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 24, 'Ih, Nuzen ik id, s tidep, d abeccaô, d aneddaô. Ur illi lois, mebla ma iusa t id uneddaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 25, 'Ma skaddben k, ni$ skaddben wid i ten id izwaren. Usan ten id imazanen nnsen, s ubeggen, s Ihellilen, s Tezmamt timnewweôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 26, 'D$a Ssemêalqe$ i wid ijehlen. Amek tuzzma W imiren!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 27, 'Ur twalav ara Öebbi Isse$li d aman seg igenni? Nessuffe$ ed, yissen, ppemôa n yal ini. Deg idurar, isôiden icebêanen, izegwa$en n yal ini, akked iberkanen mavi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 28, 'Imdanen, lewêuc, lmal, n yal ini ula d nitni. Akka, ger imdanen iS, d imusnawen kan i ippagwaden Öebbi. Ih, Öebbi d Uzmir, Ipsemmiê', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 29, 'Ih, wid iqqaôen Tazmamt n Öebbi, ipéallan, ipseddiqen seg wayen iten N$at, s tuffra ne$ âinani, ad ssirmen ttjaôa ur nepquccu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 30, 'Akken ad asen Ifk tiqvaâin nnsen, ad asen Irnu si lfevl iS. Neppa, s tidep, Ipsemmiê, Ippara tajmilt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 31, 'Ayen i k Nweêêa, si Tezmamt, d tidep id itebbten ayen ip id izwaren. Ih, Öebbi, $ef imdanen iS, Ippuxebbeô, Ipwali ten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 32, 'Sinna, Nerra d iweôôaten n Tezmamt, wid Nefren, ger imdanen nne£. Garasen, llan win idensen iman is, garasen alemmas, garasen win izeggwiren ar lxiô, s wannuf n Öebbi. Wagi d lfevl ameqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 33, 'Loennet n Âaden, ara kecmen. Din, ad qqnen imeqyasen n ddheb, akked tyuqat. Leêrir, di lebsa nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 34, 'Ad inin: "cekôan i Öebbi i Issaferen fella$ le$wben. Ih, Mass nne$ Ipsemmiê, Ippara tajmilt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 35, 'I a$ Irran, s lefvl iS, axxam i tnezdu$t; ur a$ ipnal, degs, wugur; ur a$ ipnal, degs, âaggu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 36, 'I wid ijehlen, times n Loahennama. Ur tepfukku fellasen, ad mmten; ur ippifsus, fellasen, uâaqeb is. Akka, ay Nepqeîîi yal ajehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 37, 'Degs, ad ppu$un: "a Mass nne$! Ssuffe$ ane$, a nexdem ayen ilhan, maççi am akken nella nxeddem"! Day ur awen Nesse$wzef ara laâmeô, akken a d immekti win id ismektayen? Iusa kwen id uneddaô. Ihi jeôôbet. I imednas, ur illi umâiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 38, 'Öebbi Issen tabavnit n tmurt akked igenwan. Neppa, s tidep, Iéôa i illan deg idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 39, 'D Neppa i kwen Iran d igensas di tmurt. Win ijehlen, tijehli s mgal iman is. Tijehli ijehliyen, siwa a$unzu i trennu ar Mass nnsen. Tijehli ijehliyen, siwa taxessaôt i trennu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 40, 'Ini: "twalam icriken nnwen, la tnaâôem, war Öebbi; sseknet iyi d acu xelqen, si tmurt, ne$ ma sâan amur deg igenwan, ne$ ma Nefka yasen Tazmamt i sen d ipbegginen? Xaîi, aâahed imednas, garasen, d a$uôôu kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 41, 'D Öebbi, s tidep, i Iîfen tamurt akked igenwan, ur $ellin ara. Lemmer ad $lin, ur illi yiwen, deffir eS, ara ten iîîfen. Neppa, ih, Izga Iêellem, Ipsemmiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 42, 'Gullen s Öebbi, tagalit meqwôen, ar ma iusa ten id uneddaô, ar ad ddun d ubrid, sennig akw leoyus. Mi ten id iusa uneddaô, i asen d irna, siwa tugin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 43, 'tem$weô di tmurt, akked tnaâuôt tucmip. Ur teppaîîaf tnaâuôt tucmip, siwa bab is. Day ur muqlen ara ar tannumi imezwura? Ur teppafev, d awez$i, abeddel di tannumi n Öebbi. Ur teppafev ara adewwel di tannumi n Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 44, 'Day ur unagen ara di tmurt, ad walin amek tevôa d wid i ten id izwaren? Llan $elben ten tazmert. Ur illi win ara sfunngen Öebbi, s wacemma, deg igenwan, ne$ di tmurt. Neppa, ih, Izga d Amusnaw, d Uzmir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 45, 'Lemmer Ipqeîîi Öebbi imdanen, $ef wayen kesben, ur Ippaooa kra n lxelq sufella n tmurt. Maca, Iswexxiô iten, ar lajel ipwassnen. Ma iusa d lajel nnsen, ihi, Öebbi, deg imdanen iS, Izga Ipwali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 1, 'Is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 2, 'S Leqwôan uûwib!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 3, 'Keçç, d ûûeê, ar seg imazanen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 4, '$ef ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 5, 'Tarusi n Uzmir Ipêunun,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 6, 'iwakken a pnedôev agdud; ur pwanedôen imezwura nnsen, d$a stehzan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 7, 'Ni$ iûaô wawal, $ef tegwti degsen, d$a ur uminen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 8, 'Ih, Nurez iten si tmegôav ar tmira, d$a ndellen, ur îîinizen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 9, 'Nerra aêdid zdat sen, aêdid deffir sen. Nesbur asen, ihi ur pwalin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 10, 'Iâuva fellasen: ama tnubav ten, ne$ ur ten tnubav; ur ppamnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 11, 'Nabi kan wid iîîafaôen asmekti, ippagwaden Aênin, di tbavnit. Ihi, becceô it s ssmaê, akked warraz ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 12, 'Ih, Nekwni Nessidir lmeggtin. Nepparu ayen xeddmen akked lateô nnsen. Neêseb yal cci di Tezmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 13, 'Awi asen d amedya: at temdint, mi ten id usan imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 14, 'Mi sen Nuzen sin, nekôen ten. Null s wis krav. Nnan: "nekwni d imazanen $uôwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 15, 'Nnan: "kunwi d imdanen kan, am nekwni. Aênin ur d Issers acemma. Kunwi, teskiddibem kan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 16, 'Nnan: "Mass nne$ Iéôa, s tidep, ar $uôwen id neppuceggaâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 17, 'Ay fella$ kan d timenna ipbegginen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 18, 'Nnan: "war ccekk, tesskeêsem a$. Ma ur teêbisem ara, a kwen neôoem, u a nessuk fellawen, aâaqeb aqeôêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 19, 'Nnan: "lkeês nnwen yidwen. Day imi i kwen smektin? Maca, kunwi d agdud amaâfun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 20, 'Iusa d si îeôf ibaâden n temdint, urgaz s tazzla. Inna: "a yagdud iw! Ddut d imazanen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 21, 'Ddut d wid ur awen d nessuter taqviât, nitni pwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 22, 'Amek ur âabde$ ara Win iyi d Ixelqen, u $uôeS tu$alin nnwen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 23, 'Day ad sâu$, war Neppa, iôebbiten? Ur iyi d teppawi acemma cafuâa nnsen, ma Irad iyi Uênin ccqa; ur iyi pselliken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 24, 'Yili nek, war ccekk, di ttelfan n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 25, 'Nek, umne$ s Mass nnwen. Ihi selt iyi d".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 26, 'Nnan as: "ekcem ar Loennet"! Inna: "anna$, a lemmer ad iéeô ugdud iw,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 27, 'amek iyi Isemmeê Mass iw, u Irra yi seg imaâzuzen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 28, 'Ur d Nuzen ara, i ugdud is, deffir es, aâsekôiw, seg igenni. Ur d Neppazen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 29, 'Siwa yiwet n ti$ôi kan, d$a nitni negren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 30, 'A tawa$it n imdanen! Ur ten id ippas umazan, mebla ma ttahan fellas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 31, 'Day ur éôin ara acêal isuta i Nen$a, uqbel nnsen? Nitni, s tidep, ur d ppu$alen $uôsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 32, 'U, akken ma llan akw, a d rsen, zdat nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 33, 'Assekni i nitni, d akal immuten. Nessider t id, Nessuffe$ ed segs, iâaqqayen, teppen segsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 34, 'Nerra degs tibêirin n tezdayin akked tfeôôant. Nessenfeg degs tiliwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 35, 'Iwakken ad ççen seg izwayen iS, akked wayen d ssawven ifassen nnsen. Day ur snemmiren ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 36, 'Gedha s Win Ixelqen akw tiyugiwin, seg wayen d issenkar wakal, seg wayen d ssenkaren nitni, u seg wayen ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 37, 'Assekni i nitni: iv. Nekkes ass, segs, d$a atnan di tillas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 38, 'Iîij ippazalen s amkan is; ayagi, d lqwedôa n Uzmir Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 39, 'Aggur, Neôûem as udmawen, alamma iu$al am uâaôoun aqdim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 40, 'Ur ippunefk ara i iîij ad imager aggur, ne$ i iv, a d izwir ass. Akw, ppâumun deg iberdan nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 41, 'Assekni i nitni: Neddem tarwa nnsen di sfina iççuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 42, 'Nxelq asen d, seg umedya s, ayen i$ef rekkben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 43, 'Lemmer i £ ihwi, a ten Ne$meq, ur d psu$un, ur pwaselken,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 44, 'siwa aêunu nne£; ad zhun tallit kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 45, 'Mara ad asen inin: êezzbet i wayen illan zdat wen, akked wayen illan deffir wen, amar aêunu fellawen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 46, 'Ur ten id ippas ussekni, seg issekniyen n Mass nnsen, mebla ma numren t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 47, 'Ma pwanecden: "seddqet seg wayen is ikwen id I$at Öebbi", ad inin wid ijehlen, i wid iumnen: "day a necceçç win ara Icceçç Öebbi ma ihwa yaS? Kunwi di ttelfan kan n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 48, 'La qqaôen: "melmi p lemâahda yagi, ma tessawalem tidep"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 49, 'Ad ganin kan asu$u yiwen, ara ten iêazen, wayel ppemqellaâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 50, 'Ur zmiren ad weûûin, ne$ ad qqwlen ar twacult nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 51, 'Aûuvu di lbuq: atnan la qefzen, si tneîlin, ar Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 52, 'Qqaôen: "a ssexv nne$! Anwa i $ d issekren, seg usu nne$, agi? D aya i d Iwaââed Uênin, u nnan tidep imazanen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 53, 'Asu$u yiwen kan: a d rsen akw, zdat nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 54, 'Assa, ur ipwadennes ôôuê, s wacemma. A ppeppuqeîîim kan, $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 55, 'Ih, at Loennet, assa, ad lhin di lfeôê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 56, 'Nitni akked tlawin nnsen, di tili, élen deg imîeôêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 57, 'I nitni, degs, izwayen. I nitni ayen ssutren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 58, 'Talwit! Awal s$uô Mass Ipêunun. ¨¨', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 59, 'Öuêet akin, assa, a yibe$wviyen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 60, 'Day ur kwen Nuba$ ara, a tarwa n Adem, ur tâabdem ara Cciîan? Neppa, war ccekk, d acengu nnwen n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 61, 'Ad iyI tâabdem, d wagi ay d abrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 62, 'Ni$ itlef ayen ur nferru, n imdanen segwen. Day tezgam ur tepmeyyizem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 63, 'Tagi d Loahennama i wen ippuwaââden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 64, 'Eô$et degs, assa, ilmend n tijehli nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 65, 'Assa, a Neskweô imawen nnsen, a £ d hedôen ifassen nnsen, a d cehhden ivaôen nnsen, af wayen kesben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 66, 'Lemmer i £ ihwi, ad asen nergel allen nnsen, ad mzizlen s abrid. Amek ara walin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 67, 'Lemmer i £ ihwi, ad asen nbeddel udem deg imukan nnsen, ur zmiren ad qqedmen, ne$ ad wexxôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 68, 'Win iwumi Nessi$wzef laâmeô, Neppara yas lxelq amengal. Day ur pxemmimen ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 69, 'Ur as Nesseêfev tamedyazt, ur as tlaq. Ayagi, siwa asmekti akked Leqwôan ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 70, 'Ad inabi win idren, ad iûaô wawal af ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 71, 'Day ur walan ara ar Nexleq asen lmal, s ufus nne£, a ten sâun?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 72, 'Nerra ten d ixdimen nnsen, kra rekben ten, kra teppen ten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 73, 'I nitni, segsen, aba$uô, tissit. Day ur snemmiren ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 74, 'Ddmen iôebbiten, war Öebbi, iwakken amar ad pwassellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 75, 'Ur zmiren a ten ssellken; d nitni ay d iâsekôiwen id ikren $uôsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 76, 'Ur k $webbent tmenna nsen. Neéôa, s tidep, ayen teffren d wayen d qqaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 77, 'Day ur iéôa ara umdan, ar Nxelq it id si tiqqit? Atan neppa d axûim n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 78, 'Ifka ya£ d amedya, ippu lxelq is, inna: "anwa ara d issidren i$san iu$alen d a$webbaô"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 79, 'Ini: "a ten id Issider Win iten id Ixelqen, abrid amenzu. Neppa Iéôa yal lxelq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 80, 'Win i wen Irran times di ttejôa tazegzawt; d$a, segs, kunwi tepcaâlam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 81, 'Win Ixelqen tamurt akked igenwan, day ur Izmir ara ad Ixleq i ten icban? Ih, u Neppa, d Axellaq, Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 82, 'Lameô iS kan, ma illa wayen Ib$a, ad as Yini: "ili"! Ad yili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 83, 'Gedha s Win Isâan, deg ufus iS, tagelda n yal cci! £uôeS ara kwen rren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 1, 'S leûfuf d tirni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 2, 'S tid i t inehôen, nehôent!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 3, 'S tid iqqaôen asmekti!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 4, 'Öebbi nnwen, s tidep, ard Yiwen:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 5, 'Mass n tmurt, igenwan, akked wayen illan garasen, Mass n yigmav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 6, 'Ih, Ncebbeê igenni aqôib mavi, s ccbaêa n yitran,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 7, 'i uêareb si yal cciîan amnafeq;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 8, 'ur ssemêasen i le$wat aâlayen nezzeh; ad pwaôeomen, si yal tama;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 9, 'ad pwanfun; fellasen aâaqeb idumen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 10, 'Ma illa win iccleqfen ayen iccelqef, a t id ivfeô usafu ifellun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 11, 'Steqsi ten: day nitni, axlaq nnsen, iwâaô sennig win n wiyav, i Nexleq? Ni$ Nexleq iten s talaxt ibbelîuvêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 12, 'Xaîi, twehmev, la ttihin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 13, 'Ma pwafekkôen d, ur d smektayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 14, 'Ma walan assekni, ad mmaâlken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 15, 'Nnan: "wagi, ih, iban kan d ssêur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 16, 'Ma nemmut, nu$al d akal, d i$san, day a d nu$al?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 17, 'akked lejdud nne$ imezwura"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 18, 'Ini: "ih, u a ppilim d imedlulen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 19, 'Yiwet n ti$ôi kan, d$a nitni pmuqulen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 20, 'Nnan: "a ssexv nne$, wagi d ass uqeîîi"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 21, 'Wagi d ass uêuddu, i$ef tellam d inekkaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 22, 'Ssemlilet ed wid idensen, tilawin nnsen, akked wayen âabden,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 23, 'war ÔÖebbi. Nehôet pen s abrid n wu$ud. ¨¨', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 24, 'Eîîfet pen, ih, nitni fellasen asteqsi. Ê', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 25, 'Ay$eô ur teppemsellakem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 26, 'Xaîi! Assa, nitni ad fken mayna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 27, 'Ad zzin kra degsen, ar wiyav, pmesteqsayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 28, 'Ad inin: "ni$ kunwi teppasem d $uône$, s tgallit".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 29, 'A d inin: "xaîi, ur tellim d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 30, 'Ur nesâi kra udabu, fellawen. Xaîi, tellam d agdud ijuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 31, 'Iûaô fella$ wawal n Mass nne$, aql a$, ih, la nessisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 32, 'Nes$eôq ikwen; nella, nekwni, d i$eôôaqen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 33, 'Ih, assen, nitni, deg uâaqeb ad dduklen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 34, 'Akka, s tidep, ay Nxeddem i ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 35, 'Ih, nitni, mara asen inin: "ur illi ôebbi siwa Öebbi", ssem$waôen iman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 36, 'Qqaôen: "day a neoo iôebbiten nne$, ilmend umedyaz aôehbani"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 37, 'Xaîi, iusa d s tidep, itebbet ed imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 38, 'Kunwi, war ccekk, a pjeôôben aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 39, 'A ppeppuqeîîim kan, af wayen txeddmem,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 40, 'kkes ed imdanen n Öebbi izedganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 41, 'I widak, l$it ipwassnen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 42, 'lfakya; u nitni ad ppuâuzzen', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 43, 'di leonanat isaâdiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 44, 'Mqabalen $ef imîeôêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 45, 'Ad asen tezzin s lkas n waman ipfeggiven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 46, 'D imellalen, d iéidanen i wid itessen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 47, 'Ur qeôôêen, ur helken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 48, '£uôsen, sut wallen ibran;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 49, 'nitenti, am tmelli iffren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 50, 'Ad zzin, kra $eô kra, pmesteqsayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 51, 'Yiwen id ihedôen, segsen, inna d: "illa $uôi umeddakwel', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 52, 'iyi d iqqaôen: "ma, d ûûeê, keçç, seg wid issawalen tidep?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 53, 'Ma nemmut, nu$al d akal, akked i$san, day mazal fella$ îîlaba"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 54, 'Inna: "kunwi ma la tepmuqulem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 55, 'Imuqel, iwala t di pnaûfa n wu$ud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 56, 'Inna d: "s Öebbi, ar qôib iyi tessôuêev!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 57, 'Lemmer maççi d tacvaî n Mass iw, yili aql i seg wid id irsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 58, 'Day ur nepmeppat ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 59, 'Tameppant nne$ kan tamezwarut, nekwni ur neppuâaqab"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 60, 'Ayagi, s tidep, d arraz ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 61, 'I wayen icban aya, aânut a wid iâannun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 62, 'D wagi ay d axxam igerzen, ne$ d ttejôa n Zaqqum?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 63, 'Nerra p, ih, d ahewwel i imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 64, 'Neppat, ih, d ttejôa id iff$en si pnaûfa n tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 65, 'Ppemôa s, amzun d iqweôôa n ccwaîen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 66, 'Nitni, war ccekk, ad ççen segs, ad ççaôen, segs, iâabbav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 67, 'Sinna, deffir es ad xelven aman ippayzagen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 68, 'Sinna, war ccekk, ad u$alen ar wu$ud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 69, 'Ih, ufan d ibabaten nnsen d im$eôôqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 70, 'D$a nitni, di lateô nnsen, ddehmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 71, 'Ni$ nnetlafen, uqbel nnsen, tegwti seg imezwura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 72, 'Irna Nuzen asen ed ineddaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 73, 'Muqel amek tevôa d wid ipwanedôen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 74, 'kkes ed imdanen n Öebbi izedganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 75, 'Ni$ Nuê inuj ed $uône£. Amaqwa n Wid ipjawaben!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 76, 'Nsellek it, neppa akked twacult is, si lefqaâ tabarart.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 77, 'Nerra arraw is, d wid ara d iqqimen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 78, 'Neooa d fellas i ineggura:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 79, '"talwit i Nuê, deg imavalen"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 80, 'Ih, akka ay Nepkafi izedganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 81, 'Neppa, ih, seg imdanen nne£ i iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 82, 'Sinna, Ne$ôeq wiyav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 83, 'U si tnudda s, war ccekk: Ibôahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 84, 'Mi d iusa, ar Mass is, s wul iûfan;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 85, 'mi inna i baba s, akked ugdud is: "d acu tâabdem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 86, 'D iôebbiten n tkerkas, war Öebbi, ay teb$am?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 87, 'Acu tepmeyyizem di Mass imavalen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 88, 'Iger tiî ar itran,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 89, 'inna: "aql i ulwa$".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 90, 'Ooan t, wexxôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 91, 'Izzi ar iôebbiten nnsen, inna: "day ur teppeppem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 92, 'Acu ikwen iu$en, ur d tneîqem ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 93, 'Idhem fellasen, iwwet s uyeffus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 94, 'U$alen d $uôes, zeêêfen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 95, 'Inna: "day a ppâabdem ayen tmeslem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 96, 'Öebbi Ixelq ikwen, akked wayen txeddmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 97, 'Nnan: "bnut as tazeqqa, terrem t ar wu$ud".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 98, 'B$an ad as p andin; Nekwni Nesseméi iten mavi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 99, 'Inna: "nek, ad ôuêe$ ar Mass iw, ad iyi Iawi d ubrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 100, 'A Mass iw, £it iyi d, s iâaôviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 101, 'Nbecceô it s tlalit n uqcic iêelmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 102, 'Mi ibda iteddu yides, inna: "a mmi! Nek wala$, di targit, a k zlu$. Muqel d acu twalav"? Inna: "a baba! Exdem ayen ik ippumôen; ad iyi tafev, ma Irad Öebbi, seg iûebôiyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 103, 'D$a, mi unzen, u iééel it $ef uniyr,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 104, 'Nessawel as: "a Ibôahim!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 105, 'Tumnev s targit. Akka, ih, ay Nepkafi lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 106, 'Wagi, s tidep, d ajeôôeb n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 107, 'Nefda t id, s tmezliwt tabarart.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 108, 'Neooa d fellas i ineggura:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 109, '"tifrat i Ibôahim"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 110, 'Akka ay Nepkafi iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 111, 'Neppa, s tidep, seg imdanen nne£ iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 112, 'Nbecceô it s Isêaq, d nnbi, seg iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 113, 'Nburek iten, neppa d Isêaq. Si tarwa nnsen, iban win iddan d ubrid, iban win idensen iman is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 114, 'Ni$ N$at Musa akked Haôun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 115, 'Nsellek iten, nitni akked ugdud nnsen, si lefqaâ tabarart.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 116, 'Nefka yasen afus, d$a d nitni ay d imerbaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 117, 'Nefka yasen Tazmamt ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 118, 'Nebbwi ten d ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 119, 'Neooa d fellasen, i ineggura:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 120, '"talwit i Musa, akked Haôun"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 121, 'Akka, ih, ay Nepkafi iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 122, 'Nitni, s tidep, seg imdanen nne£ iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 123, 'Ih, Ilyas ar seg imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 124, 'Mi inna i ugdud is: "day ur tepêezziben ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 125, 'Day la tepnujum $eô Baâla, a ppeooem Üûam ixellaqen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 126, 'Öebbi, Mass nnwen, Mass n lejdud nnwen imezwura"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 127, 'Skaddben t. S tidep, nitni a d rsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 128, 'kkes ed imdanen n Öebbi, izedganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 129, 'Neooa d fellas, i ineggura:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 130, '"talwit i Ilyas"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 131, 'Akka, ih, ay Nepkafi iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 132, 'Neppa, s tidep, seg imdanen nne£ iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 133, 'Ih, Luî seg imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 134, 'Mi t Nsellek, akked twacult is, s lekmal is,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 135, 'siwa tam$aôt, seg wid igwran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 136, 'Sinna, Nemêa wiyav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 137, 'Aql akwen la tleêêum fellasen, deg uzal,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 138, 'deg yiv. Day ur tepmeyyizem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 139, 'Ih, Yunes ar seg imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 140, 'Mi irwel ar sfina iççuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 141, 'Ijbed taseqqaôt, iûbeê ed seg wid ipwaveggôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 142, 'Isseblaâ it uslem, u neppa degs tiyta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 143, 'Lemmer ur illi, neppa, seg wid isbuccuâen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 144, 'ad iqqim deg uâabbuv is, ar ass n tu$alin nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 145, 'Nveggeô it id, s aqeôqaô, d amuvin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 146, 'Nessenker ed $uôes, ttejôa n texsayt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 147, 'Nuzen it ar twinas igima, uger.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 148, 'Umnen. Neooa ten zzhan kan tallit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 149, 'Steqsi ten maday, i Mass ik, tullas; i nitni, arrac?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 150, 'Ne$ Nexleq lmalayek d nnta, nitni d inagan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 151, 'Day, s tkerkas nnsen, ihi, a d inin:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 152, '"Iurew ed Öebbi"? Nitni, s tidep, d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 153, 'Ismenyaf tullas i warrac!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 154, 'Acu ikwen iu$en? Amek tepêuddum?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 155, 'Day ur d tesmektayem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 156, 'Ne$ tesâam adabu n ûûeê?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 157, 'Aset ed s tezmamt nnwen, ma tessawalem tidep!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 158, 'Gren d nnesba garaS d leonun. Irna leonun éôan ara d rsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 159, 'Gedha s Öebbi, mgal ayen qqaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 160, 'Kkes ed imdanen n Öebbi izedganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 161, 'Ihi, kunwi, akked wayen tâabdem,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 162, 'ur d tesskarem ahewwel, mgal iS;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 163, 'siwa win ara iô$en di tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 164, 'Ur illi yiwen, degne$, ur nesâi amekkan ipwassnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 165, 'Ih, nekwni d leûfuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 166, 'Ih, nekwni d wid i isbuccuâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 167, 'Llan la qqaôen:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 168, '"lemmer day $uône$ asmekti seg imezwura,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 169, 'a nili, war ccekk, d imdanen iâaôviyen n Öebbi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 170, 'Nekôen T. Deqqal ad éôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 171, 'Ih, izwar ed wawal nne£, i imdanen nne£ imazanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 172, 'Ih, d nitni ara ipwasellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 173, 'S tidep, d iâsekôiwen nne£, ara irebêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 174, 'Ihi, îîixeô asen kra n tallit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 175, 'Ssiked iten, deqqal ad walin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 176, 'Day êaren af uâaqeb nne£?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 177, 'Ma irs ed ar umekkan nnsen, ay dir ip tûebêit n wid ippunedôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 178, 'Ïîixeô asen kra n tallit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 179, 'Ssiked, deqqal ad walin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 180, 'Gedha s Mass ik, Mass n tezmert, mgal ayen qqaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 181, 'Tifrat $ef imazanen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 182, 'Ccekôan i Öebbi, Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 1, 'Ü. S Leqwôan id ismektayen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 2, 'Xaîi, wid ijehlen, atnan di tem$weô d ticuîna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 3, 'Acêal isuta ay Nesqucc, uqbel nnsen! Ssawlen d. Ur mazal akud i leslak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 4, 'Wehmen, iusa ten id uneddaô segsen. Nnan ijehliyen: "wagi d aseêêar, d akeddab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 5, 'Aâni ad irr iôebbiten, d Öebbi Yiwen? Ayagi d ayen issewhamen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 6, 'Kkren imeqwôanen segsen, nnan: "elêut, illit d imezgiyen ar iôebbiten nnwen. Ayagi, d ayen iwatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 7, 'Ur nesli i waya, di ddin aneggaru. Ihi, aya, siwa asnulfu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 8, 'Day, garane$, d neppa iwumi d irs usmekti"? Xaîi, nitni di ccekk, $ef usmekti W, mazal ur jeôôben ara aâaqeb iW.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 9, 'Ne$ sâan lexzayen uêunu n Mass ik, Uzmir, A$eyyat?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 10, 'Ne$, nnsen tagelda n tmurt, igenwan, akked wayen illan garasen? Anef ad alin ihi, s imraren!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 11, 'Nitni siwa d iâeskôiwen imexsuôen, seg ikabaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 12, 'Zwaren ten id, ar uskiddeb, agdud n Nuê, Âad, Ferâun bu ibudiden,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 13, 'Tamud, agdud n Luî, At Laika; d widak ay d ikabaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 14, 'Akw, skaddben imazanen, ihi, iwata uâaqeb iW.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 15, 'Wigi, ad gganin kan ti$ôi yiwet, ur as ippili wallus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 16, 'Nnan: "a Mass nne$! £iwwel ane$ deg umur nne$, uqbel ass iqeîîiyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 17, 'Eûbeô i wayen d qqaôen. Mmekti d amdan nne£ Dawed, bab n tezmert. Ih, Neppa ippales.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 18, 'Ih, Nêeppem i idurar ad sbuccuâen yides, tameddit, tafara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 19, 'Ifôax mlalen. Akw, i Neppa, ppalsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 20, 'Nesseohed tagelda s, Nefka ias ûûwab, awal iqaâden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 21, 'Ma ibbwev ik id usali n yixûimen, mi ulin ar tmezgida?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 22, 'Mi kecmen ar Dawed, iugad iten. Nnan: "ur ppagwad, d sin ixûimen, yiwen degne$, ijuô $ef wayev. Eêkem garane$ s tidep, war taneêyaft. Enhu ya$ s abrid umâin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 23, 'Ihi, gma yagi, isâa tza u tzat n wulli, nek tixsi yiwet. Inna yi d: kwellef iyi p. Irna yi s wawal".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 24, 'Inna: "ni$ idens ik s usuter n texsi inek, a p irnu ar wulli ines. Aîas n yicriken i ippemjuôen, siwa wid iumnen, ixeddmen ayen ilhan, drus nnsen ay llan". Ifhem Dawed Njeôôeb it kan; iste$feô Mass is, i$li, iîîanez, indem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 25, 'Nsemmeê as ayagi. Ih, i neppa, $uône£, amkan n tu$alin aqôib, umâin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 26, 'A Dawed, Nerra k, ih, d agensas di tmurt. Ëudd ger imdanen s tidep, ur îîafaô lhawiyya, a k tetlef seg ubrid n Öebbi. Ihi, wid innetlafen seg ubrid n Öebbi, fellasen aâaqeb uqsiê, imi ppun ass iqeîîiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 27, 'Ur Nexliq tamurt, igenwan, akked wayen illan garasen, di rrayaâ, akken nwan wid ijehlen. A tawa$it n tmes, i wid ijehlen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 28, 'Day a Nerr wid iumnen, ixeddmen ayen ilhan, am wid issefsaden di ddunit? Ne$ a Nerr wid ipêezziben am laâôuô?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 29, 'Tazmamt Nessers ak p id, teôqa, iwakken ad meyyzen issekniyen is, a d mmektin uâqilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 30, 'N$at Dawed s Sliman, amdan ukiys ippalsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 31, 'Mi s d sseknen, tameddit, tigmarin lâali,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 32, 'inna: "nek, smenyafe$ tayri n wayla, i usmekti n Mass iw, armi sberbren fellasent.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 33, 'Erret pent id $uôi". Igezm asent ivaôen, timegrav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 34, 'Ni$, Njeôôeb Sliman; Nessers loeppa af usgeld is. Iu$al indem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 35, 'Inna: "a Mass iw! Semmeê iyi, £it iyi s tgelda ur nepûaê yiwen, deffir i. S tidep, Keçç d A$iyyat".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 36, 'Nenub fellas s wavu. Ipûuvu, s lameô is, d abeêri, s anda i s ihwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 37, 'Ccwaîen akw ibennun, ip$emmisen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 38, 'Wiyad pwarzen, s slasel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 39, 'Tagi d tikci nne£. Efk ne$ eîîef, war aktili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 40, 'Ih, i neppa, $uône£, amkan n tu$alin aqôib, umâin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 41, 'Mmekti d amdan nne£ Yub, mi inâaô Mass is: "nek, iêuza yi Cciîan, s cedda akked uâaqeb".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 42, '"Aâfes s uvaô ik, wagi d amkan semmven, i tarda u i tissit".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 43, 'N$at it s twacult is, akked yides tin i p icban, d aêunu s$uône£, d asmekti i uâqilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 44, '"Eddem deg ufus ik taseîîa, ewwet yis ur êennet". Ni$ Nufa t d aûebôi, d amdan amxallef ippalsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 45, 'Mmekti d imdanen nne£: Ibôahim, Isêaq, Iaâqub. D imawlan n tezmert akked yiéôi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 46, 'Ih, Nûeffa ten, s ûûfawa usmekti n Uxxam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 47, 'Nitni, $uône£, war ccekk, seg wid iufraren, i Nefren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 48, 'Mmekti d: Ismaâil, Lyasaâ, Du-al-Kifl. Akw, seg wid Nefren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 49, 'Wagi d asmekti. Ih, i wid ipêezziben, tisin igerzen mavi:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 50, 'leonanat n Âaden. Llin asen tibbura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 51, 'Ad ttekkin dinna. Ad ssutren degsen; izwayen s lufa, akked tisit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 52, '£uôsen, sut wallen ibran, ppizyiwin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 53, 'D wagi i wen ippuwaââden, i wass iqeîîiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 54, 'D wagi, s tidep, ay d l$it nne£, ur nepfukku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 55, 'Akka. Wanag, i iqehhaôen, tisin icemten mavi:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 56, 'Loahennama, ad degs ô$en; a yir usu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 57, 'Akka, ad jeôôben aman ippayzagen, akked wid ipfuêun;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 58, 'akked wayen nniven i ten icban, d tiyugiwin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 59, 'Atan urbaâ i iddehmen yidwen, ur anûuf yissen. Ih, di tmes ad ô$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 60, 'Nnan: "xaîi, ur anûuf yiswen, kunwi! D kunwi i $ p id iheggan". A yaxxam adiran!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 61, 'Nnan: "a Mass nne$! Sâaddi berdayen aâaqeb n tmes, $ef wid i $ d iheggan aya".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 62, 'Nnan: "acu i $ iu$en, ur nwala ara irgazen, i nella nêesb iten seg imcumen mavi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 63, 'Day nemsexxeô fellasen, ne$ dergen i wallen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 64, 'Ih, aya d tidep, d amqellaâ n at tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 65, 'Ini: "nek, d aneddaô kan. Ur illi ôebbi siwa Öebbi, Yiwen, Aqehhaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 66, 'Mass n tmurt, igenwan, akked wayen illan garasen, Uzmir Ipsemmiêen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 67, 'Ini: "d asali ameqwôahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 68, 'Kunwi, teooam t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 69, 'Ur illi wayen éôi$ $eô le$wat aâlayen meôôa, mi mqellaân.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 70, 'Ppuweêêa$ d kan, ar nek d aneddaô ipbegginen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 71, 'Mi Inna Mass ik i lmalayek: "Nek ad Xelqe$ amdan, si talaxt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 72, 'Mi t Mesle$, Suve$ degs, si ôôuê iW, îinzemt $uôes, s lekni".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 73, 'Knant akw lmalayek, akken ma llant,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 74, 'siwa Iblis i izuxxen, illa seg ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 75, 'Inna: "A Iblis, w ik igedlen lekni i win Xelqe$ s ifassen iW? Tzuxxev, ne$ telliv seg wid iufraren"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 76, 'Inna: "Nek ife$ t. Txelqev iyi si tmes, Txelqev t si talaxt".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 77, 'Inna: "Effe$ segs, keçç d imenfi"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 78, 'Inna: "fellak xezzu, alamma d ass iqeîîiyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 79, 'Inna: "A Mass iw, eoo iyi ar ass ideg ara d kkren".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 80, 'Inna: "keçç, ih, seg wid Ooi$', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 81, 'ar ass n wukud ipwassnen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 82, 'Inna: "s tezmert iK, a ten $ewwu$, akken ma llan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 83, 'siwa imdanen iK izedganen segsen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 84, 'Inna: "tidep, d tidep ay Nni$.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 85, 'Ad Acare$ Loahennama yissek, akked wid, segsen, i k ivefôen, akken ma llan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 86, 'Ini: "ur awen ssutre$ taqdiât af waya. Ur lli$, nek, seg wid ippestaâmilen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 87, 'Neppa, s tidep, d asmekti kan i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 88, 'Mi tâadda tallit, war ccekk, a kwen id iawev usali s.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 1, 'Tarusi n Tezmamt s$uô Öebbi, Uzmir, Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 2, 'Ih, Nessader ak d Tazmamt, s tidep. Ihi, aâbed Öebbi, s laâqida i Neppa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 3, 'Day maççi i Öebbi laâqida? Wid ippaddamen imawlan, war Neppa, nnan: "naâbed iten kan, iwakken ad a$ rnun aseqôeb ar Öebbi". Ih, Öebbi ad Iêudd garasen, $ef wayen i$ef mgarraden. Öebbi, war ccekk, ur Inehhu win illan d akeddab, d ajehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 4, 'Lemmer Ib$i Öebbi ad Isâu aqcic, yili Ifren, deg wayen Ixelleq, ayen i S ihwan. Gedha s yiS! Neppa d Öebbi Yiwen, Aqehhaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 5, 'Ixleq tamurt akked igenwan, s tidep. Innev Iv i wass, Innev ass i yiv. Iêeppem i yiîij akked waggur, ad lêun, yal wa, ar lajel ipwassnen. Day Neppa maççi d Uzmir Ipsemmiêen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 6, 'Ixelq ikwen si yiwen n lxelq. Irra, segs, tislit is. Issers awen d îam n tyugiwin n lmal. Ixelq ikwen di tâabbuvin n tyimmatin nnwen, lxelq deffir lxelq, di krav n tellisat. D wagi ay d Öebbi, Mass nnwen. IneS tagelda, ur illi ôebbi siwa Neppa. Amek ihi tugim?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 7, 'Ma tjehlem, Öebbi ur kwen Iêwao ara. Ur Ipôadi tijehli i imdanen iS. Ma tesnemmrem, a kwen Iôavi. Ur ipbibbi yiwen taâkkwemt n wayev; sinna, ar Mass nnwen tu$alin nnwen; ad awen Imel acu txeddmem. Ih, Neppa, Issen i illan deg idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 8, 'Amdan, ma iêuza t ccqa, ad inuj ar Mass is, d ucâif $uôes; sinna, ma I$at it s$uôeS, ad ippu ayen i$ef inuj $uôeS, uqbel; ad irr i Öebbi tanudda, ad innetlaf seg ubrid iS. Ini: "zzhu cwiî di tijehli k, ihi, keçç seg wat tmes".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 9, 'Day win ippanzen deg iv, ikna u ibedd, ipêebbiô i laxeôt, issaram aêunu n Mass is…? Ini: "day âadlen wid issnen akked wid ur nessin? Ay d ismektayen, kan, d uâqilen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 10, 'Ini: "a yimdanen iW iumnen, êezzbet i Mass nnwen. Ayen ilhan i wid imaânen di ddunit agi. Tamurt n Öebbi tewsaâ. Ihi, arraz, war aktili, ad ippunefk i iûebôiyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 11, 'Ini: "nek pwamôe$ d ad âabde$ Öebbi, s laâqida i Neppa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 12, 'Pwamôe$ d, ad ili$ d amvuâ amenzu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 13, 'Ini: "nek, ugade$, ma aâûa$ Mass iw, aâaqeb n wass ameqwôaêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 14, 'Ini: "ad âabde$ Öebbi, s laâqida i Neppa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 15, 'Ihi, âabdet i wen ihwan, war Neppa". Ini: "imexsuôen d wid iwedôen iman nnsen, akked twacult nnsen, ass n tnekra". Ni$ d tagi ay d taxessaôt n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 16, 'A$embabu n tmes, sennig sen, wayev seddawat sen. Ayagi, Issagwad yis Öebbi imdanen iS: a yimdanen iW, êezzbet iyI!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 17, 'Wid ijunben aâbad iôebbiten n tkerkas, u iutuben Öebbi, a ten id ias lfeôê. Ihi, ssefôeê imdanen iW', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 18, 'i issemêasen i wawal, teddun d ûûam ines. D wigi i Inha Öebbi, d wigi ay d uâqilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 19, 'Day win i$ef ippuseyya ad isâaddi aâaqeb, day a psellkev keçç, win illan di tmes?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 20, 'Ma d wid iêezzben i Mass nnsen, ad sâun ti$uôfatin, bnant ta sennig ta, isaffen seddawat sent ppazzalen, d lemâahda n Öebbi. Öebbi ur Ixeîîu i lemâahda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 21, 'Ur twalav ara, Öebbi Isse$li d aman, seg igenni, Issekcem iten ad sswen akal. Sinna, yissen, a d Issuffe$ im$an n yal ini, ara iu$alen ad isliwen. A ten twaliv d iwôa$en, sinna, a ten Irr d iquôanen. Deg waya, s tidep, asmekti i uâqilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 22, 'Day win iwumi Illi Öebbi, idmaren is, ar wannuz, d$a neppa di tafat s$uô Mass is…? A ssxev n at wulawen iqquôen, ur d smektayen Öebbi! Widak di ttelfan n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 23, 'Issader ed Öebbi ûûam n wawal. Tazmamt, degs acbi, allus. Ad ccirwen segs igwelman akked wulawen n wid ippagwaden Mass nnsen, sinna, igwelman akked wulawen nnsen ad iêninen ar usmekti n Öebbi. D tagi ay d nnhaya n Öebbi. Inehhu yis, win i S ihwan. Win Itlef Öebbi, ur illi wa ara t inhun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 24, 'Day win ipêezziben, s wudem is, seg uâaqeb ucmit, ass n tnekra…? Ad inin i imednas: "jeôôbet ayen tkeppbem"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 25, 'Skaddben wid i ten id izwaren. Iusa ten id uâaqeb, seg wanda ur bnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 26, 'Issukk fellasen Öebbi aâaqeb, di tmeddurt n ddunit; war ccekk, aâaqeb n laxeôt iugar it, lemmer éeôôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 27, 'Ni$ Nefka i imdanen, di Leqwôan agi, yal amedya, amar a d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 28, 'Leqwôan s taâôabt, ur degs tiââawji; amar ad êezzben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 29, 'Ifka d Öebbi amedya n urgaz icerken akked wid ipmeréan, u argaz di tifrat akked yiwen urgaz. Day âadlen sin imedyaten? Ccekôan i Öebbi. Xaîi, tegwti degsen ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 30, 'War ccekk, keçç a ppemmtev, nitni ad mmten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 31, 'Sinna, kunwi, ass n tnekra, ar Mass nnwen, a ppemqellaâm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 32, 'Anwa i idensen sennig win iskaddben af Öebbi, iskaddben tidep ma tusa t id? Day maççi di Loahennama, i illa uxxam ijehliyen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 33, 'Wid id iusan s tidep, u pputebbten yis, wigi d wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 34, 'Ad sâun ayen b$an, ar Mass nnsen. D wagi ay d arraz iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 35, 'Iwakken ad asen Ikkes Öebbi, ayen xedmen adiran mavi; a ten I$it s wayen xeddmen d amxallef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 36, 'Day ur Ipqam ara Öebbi amdan iS? La k ssagwaden s wid, war Neppa. Win Itlef Öebbi, ur illi w ara t inhun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 37, 'Win Inha Öebbi, ur illi w ara t itelfen. Ni$ Öebbi d Uzmir, Bab n ppaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 38, 'Ma testeqsav ten: "anwa i Ixelqen tamurt akked igenwan? Ad inin, war ccekk: d Öebbi". Ini: "ma twalam wigi tnaâôem, war Öebbi, day zemren, ma Ib$a yi Öebbi ccqa, ad kksen ccqa S? Ne$, ma Ib$a yi aêunu, ad ssbeîlen aêunu S"? Ini: "Iqennaâ iyi Öebbi; fellaS ay ppeklen wid ipkalen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 39, 'Ini: "a yagdud iw! Xedmet akken tennumen, nek la xeddme$". Deqqal a ppeéôem', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 40, 'anwa u$uô ara d ias uâaqeb ara t isdullen, u$uô ara d irs uâaqeb imezgi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 41, 'Ih, Nessader ed $uôek, Tazmamt i medden, s tidets. Win ipwanhan, i iman is, win innetlafen, innetlaf kan, mgal is. Ur telliv, keçç, d awkil nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 42, 'Öebbi Ippaddam leôwaê mara mmten, akked wid ur nemmut, deg ives nnsen. Iâatteq wid i$ef Iseyya tameppant, Ippara d wiyav, ar lajel ipwassnen. Ih, deg wayagi, ard issekniyen i ugdud ipmeyyizen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 43, 'Ne$ ad ddmen, war Öebbi, imcafâan? Ini: "i ma ur sâin acemma, ur fhimen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 44, 'Ini: "akw ccafuâa n Öebbi. IneS tagelda n tmurt akked igenwan. Sinna, $uôeS ara tu$alem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 45, 'Mara d Ipwadder Öebbi Yiwen, ad zemven wulawen n wid ur numin ara s laxeôt. Ma pwadren d wid, war Neppa, imiren nitni ad ceôêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 46, 'Ini: "a Öebbi! Axellaq n tmurt akked igenwan, Amusnaw n wayen iffren d wayen ivehôen, d Keçç ara Iêudden ger imdanen iK, $ef wayen llan mgarraden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 47, 'Wid idensen, lemmer nnsen ayen akw i illan di tmurt, rnu yas am neppa, ur ten id ifeddu, seg uâaqeb ucmit, ass n tnekra. Ad asen d iban, s$uô Öebbi, ayen i$ef ur bnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 48, 'Ad asen d banent tucmitin kesben, ad asen innev wayen i$ef ttahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 49, 'Ma iêuza umdan ccqa, ad a£ d inâaô. Sinna, ma Nezger tacvaî nne£ fellas, ad yini: "tusa yi d kan si tmusni". Xaîi! D ajeôôeb, maca aîas degsen ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 50, 'Ni$ nnan t id imezwura nnsen. Acu i sen d ibbwi wayen keppben?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 51, 'Iwwet iten wayen kesben n tucmitin. Wid idensen, seg wigi, a ten iwwet wayen kesben n tucmitin. Ur zmiren ad sfunngen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 52, 'Day ur éôin ara ar Öebbi Ip$iti win i S ihwan, u Iwezzen? Ih, deg waya, ard issekniyen i ugdud iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 53, 'Ini: "a yimdanen iw i ipêawalen mgal iman nnsen! Ur ppayset aêunu n Öebbi. Ih, Öebbi Ipsemmiê akw ibekkaven. Ih, Neppa Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 54, 'Steôoâet i Mass nnwen, anzet aS, uqbel a kwen id ias uâaqeb, d$a ula ikwen isellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 55, 'Ddut d ûûam n wayen i wen d irsen, s$uô Mass nnwen, uqbel a kwen id ias uâaqeb, deqzalla, kunwi ur tebnim";', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 56, 'u a d yini ôôuê: "a ssexv iw, $ef wayen stehza$ ar loiha n Öebbi! Lli$, s tidep, seg wid ittihin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 57, 'Ne$ a d yini: "lemmer iyi Inha Öebbi, yili lli$ seg wid ipêezziben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 58, 'Ne$ a d yini mara iwali aâaqeb: "lemmer iyi illi wallus, ad ili$ si lâuûam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 59, 'Xaîi! Usan k id issekniyen iW, teskaddbev ten, tzuxxev, telliv seg ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 60, 'Ass n tnekra, a pwaliv berrikit wudmawen n wid id igren tikerkas af Öebbi. Day maççi di Loahennama, i illa uxxam imzuxiyen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 61, 'Ad Isellek Öebbi wid iêezzben; ar rebêen. Ur ten ikkat wugur, ur $webbnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 62, 'Öebbi Ixleq yal cci. Neppa d Awkil n yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 63, 'IneS tsura n tmurt akked igenwan. Wid inekôen issekniyen n Öebbi, widak d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 64, 'Ini: "day ad yi tamôem ad âabde$, war Öebbi, a wid ur nessin"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 65, 'Ni$ iusa k id uweêêi, u $eô wid i k izwaren. Ma tcurkev, ad mêun igiten ik, a ppiliv seg imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 66, 'Xaîi! Aâbed Öebbi. Ili seg wid isnemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 67, 'Ur qudôen ara Öebbi, azal n lqedô iS. Akw tamurt, ass n tnekra, di tumeét iS. Igenwan ad nnefvasen deg ufus iS ayeffus. Gedha s yiS! I Aâlay sennig wayen pcaraken!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 68, 'Aûuvu di lbuq: ad ixsef i illan deg igenwan, i illan di tmurt, kkes ed i S ihwan i Öebbi. Aûuvu nniven: nitni a d kkren pmuqulen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 69, 'A pfeooeo tmurt, si tafat n Mass is. A d ters Tezmamt, a d awin lambiyya akked inagan. Ad âaddin di ccôaâ, s tidep, ur pwadensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 70, 'Yal yiwen ad i$ellet ayen ixdem. Neppa, Yif akw akken Issen, d acu xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 71, 'Ad pwanehôen wid ijehlen, d igrawen, ar Loahennama. Mi bbwven $uôes, u llint tebbura s, ad asen inin iâssasen is: "day ur kwen in usan ara imazanen, segwen, mmalen awen issekniyen n Mass nnwen, nedôen kwen af temlilit n wass nnwen agi"? A d inin: "Ih. Maca, ad iûaô wawal uâaqeb, af ijehliyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 72, 'A d inin: "kecmet si tebbura, ar Loahennama! Degs, wekkôet". Ay d ucmit uxxam n imzuxiyen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 73, 'Wid iêezzben i Mass nnsen, ad pwanehôen ar Loennet, d igrawen. Mi bbwven $uôes, u llint tebbura s, ad asen inin iâssasen is: "tifrat fellawen, tgerzem; kecmet ep, twekkôem"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 74, 'Ad inin: "ccekôan i Öebbi i $ Issawven lemâahda S. Ifka ya$ tamurt d lweôt; a nili, di Loennet, anda i $ ihwa. A yarraz asaâdi n wid ixeddmen lxiô!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 75, 'A pwaliv lmalayek zzint ed i usgeld, sbuccuâent s ccekôan Mass nnsent. Iâadda ccôaâ garasen, s tidep. Ad inin: "a neckeô Öebbi, Mass imavalen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 1, 'Ëm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 2, 'Tarusi n Tezmamt, s$uô Öebbi, Uzmir, Amusnaw;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 3, 'Ipsemmiêen tuccva, Iqeblen nndama, Ipâaqaben s teqseê, Bab n terkunt. Ur illi ôebbi siwa Neppa. £uôeS taggara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 4, 'Siwa wid ijehlen i ipnamaren $ef issekniyen n Öebbi. Ur k ip$uôôu ucali nnsen, di tmurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 5, 'Uqbel nitni, agdud n Nuê, akked ikabaren deffir sen, skaddben. Yal lois iclaâ ad ixvef amazan is. Ipnamar s tkerkas, iwakken, s yissent, ad iveggeô tidep. Ëekme$ ten. A tiyta W imiren!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 6, 'Akka iûaô wawal n Mass ik, af wid ijehlen. Nitni, war ccekk, d at tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 7, 'Tid irefden asgeld, akked tid i s izzin, sbuccuâen s ccekôan Mass nnsent, umnent yiS. Ssuturent ad pwasemmêen wid iumnen: "a Mass nne$! Terriv yal cci d aêunu, u d tamusni. Semmeê i wid isteôoâen u ddan d ubrid iK; Sellek iten seg uâaqeb n wu$ud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 8, 'A Mass nne$! Ssekcem iten ar leonanat n Âaden, i Tâahdev, i nitni, u i iâaôviyen seg ibabaten nnsen, tilawin nnsen, tarwa nnsen. Keçç, ih, d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 9, 'Aâteq iten si tucmitin. Win Tâatqev, assen, si tucmitin, ni$ Têunev fellas. D wagi ay d rrbeê ameqwôaêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 10, 'Ad pwanecden wid ijehlen: "taâdawt n Öebbi te$leb taâdawt bbwaygarawen. Mi tepwanecdem ar liman, tugim".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 11, 'A d inin: "a Mass nne$! Ten$iv a$ berdayen, Tessidrev a$ berdayen. Nqaôô s ibekkaven nne$. Day illa ubrid n tuff$a"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 12, 'Akka, imi mara ipwanâaô Öebbi Yiwen, kunwi tjehlem. Mara S pcaraken, kunwi tumnem. Aêuddu ar Öebbi Aâlayen, Ameqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 13, 'D Neppa i wen Issnaâtan issekniyen iS. Issadar awen d l$it, seg igenni. Siwa win isteôoiâen, id ismektayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 14, 'Nujet $uô Öebbi, s laâqida i Neppa, xas ugin ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 15, 'Aâlayen nnig idurra, Bab n usgeld, Ippak ôôuê s lameô iS, i win i S ihwan, deg imdanen iS, iwakken ad indeô af wass umlili,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 16, 'ass ideg ara d awven, ur illi wayen iffren, degsen, i Öebbi. W ip ilan tgelda, assen? D Öebbi, Yiwen, Aqehhaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 17, 'Ass ideg ara ippuqeîîi yal iman $ef wayen ikseb; ur ippili ddens assen. Ih, Öebbi Ip$awal deg uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 18, 'Nabi ten af ass aqôib, ideg ulawen ad rewlen s igerjumen, ad qebôen. Ur ippilli i imednas, uêbib ne$ amcafaâ, iwumi ara ssemêessen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 19, 'Issen nncub n yiéôi, akked wayen teffren idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 20, 'Öebbi Iferru s tidep. Wid ipnujun ar war Neppa, ur qeîîun acemma. Ih, Öebbi d Win Isellen, Ipwalin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 21, 'Day ur nudan ara tamurt, ad walin amek tevôa d wid i ten id izwaren. Llan ifen ten tazmert, akked lateô, di tmurt. Issemêelleq asen Öebbi, ilmend ibekkaven nnsen. Ur asen illi umêareb, mgal Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 22, 'Akka, acku ppasen $uôsen, imazanen nnsen, s ubeggen, u nitni jehlen. Issemêelleq asen Öebbi. Ih, Neppa, d Uzmir, d Bab uâaqeb uqsiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 23, 'Ni$ Nuzen ed Musa s issekniyen nne£, s udabu iberrzen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 24, 'ar Ferâun, Haman, akked Qaôun. Nnan: "d aseêêar, d akeddab".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 25, 'Mi sen d iusa, s tidep s $uône£, nnan: "en$et arrac n wid iumnen yides, ssidret tilawin nnsen". Tandit ijehliyen siwa di ttelfan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 26, 'Inna Ferâun: "anfet iyi ad n$e$ Musa, xas ad inuj ar Mass is. Ugade$, nek, ad ibeddel ddin nnwen, ne$ a d issekcem lefsad di tmurt".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 27, 'Inna Musa: "nek, ad iyi Iûûeô Mass iw u Mass nnwen, si yal amzuxi, ur numin s wass uqeîîi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 28, 'Inna urgaz lmumen, i iffren liman is, si twacult n Ferâun: "day a ppen$em argaz, imi d iqqaô: Mass iw d Öebbi, u irna ibbwi yawen d abeggen, s$uô Mass nnwen? Ma iskaddeb, lkedb is fellas. Ma issawel tidep, a kwen iêaz kra seg wayen ikwen issagwad. Öebbi ur Inehhu amaâfun iskiddiben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 29, 'A yagdud iw! Assa, nnwen tagelda, tufrarem di tmurt. W ad a$ isellken si tiyta n Öebbi, ma tusa ya$ d"? Inna d Ferâun: "i wen ssekne$ ayen kan wala$; s anda i kwen nehhu$, siwa ar ubrid imaânen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 30, 'Inna d win iumnen: "a yagdud iw! Nek, ugade$ fellak tin n wass ikabaren,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 31, 'akken tevôa d ugdud n Nuê, Âad, Tamud, akked wid i ten id ivefôen. Öebbi ur Ib$a ara ddens i imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 32, 'A yagdud iw! Nek ugade$, ay kwen ippa$en, ass umnamar,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 33, 'ass ideg ara trewlem ar deffir. Ur awen illi umêareb mgal Öebbi. Ur illi nnahi i win Itlef Öebbi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 34, 'Ni$ iusa kwen id Yusef, zik, s ubeggen. Tezgam di ccekk, $ef wayen i wen d ibbwi. Armi immut, tennam: "ur d Ippazen ara Öebbi amazan, deffir es, d awez$i". Akka i Itellif Öebbi amaâfun amcekki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 35, 'Wid ipnamaren issekniyen n Öebbi, ur ten id iusi udabu, nezzeh ara ten i$unfu Öebbi, akked wid iumnen. Akka ara Icemmaâ Öebbi, yal ul amzuxi, aâfrit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 36, 'Inna Ferâun: "a Haman, bnu yi lbeôo, amar ad awve$ ar iberdan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 37, 'iberdan igenwan. Ad ali$ ar Öebbi n Musa. Nek êesbe$ t d akeddab". Akka i s ippucebbeê i Ferâun, igi s ucmit. Ippuveôôef seg ubrid. Tandit n Ferâun, siwa taxeûûart.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 38, 'Inna d win iumnen: "a yagdud iw! Ddu yidi, a k nhu$ s abrid umâin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 39, 'A yagdud iw! Tameddurt agi, di ddunit, d zzhu kan; wanag laxeôt d axxam n leqôaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 40, 'Win ixedmen tucmip, ad ippuqeîîi, kan, s tin i p icban. Wid ixedmen ayen ilhan, d ddkeô ne$ d nnta, u nitni umnen, widak ad kecmen Loennet; din, ad aten $iten, war aktili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 41, 'A yagdud iw! Acu iyi bbwin, a kwen neccde$ ar leslak; kunwi, a yi tneccdem ar tmessi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 42, 'A yi tneccdem ad aâûu$ Öebbi, ad aS carke$ ayen ur ssine$. Nek, neccde$ kwen ar Uzmir Ipsemmiêen', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 43, 'War ccekk, ayen u$uô a yi tneccdem, ur as iwata unuju di ddunit, u di laxeôt. Ih, tu$alin nne$ ar Öebbi. Imaâfan ard at tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 44, 'A d tesmektim ayen i wen qqaôe$. Öôay iw fki$ t i Öebbi. Ni$ Öebbi Ipwali imdanen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 45, 'Isellek it Öebbi si tucmitin i undin. I$wellef lois n Ferâun, s uâaqeb iugaren wiyav:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 46, 'times. Ad pwafessren degs, ûûbeê, tameddit. Ass ideg ara d ias yimir: "ekcem, a lois n Ferâun, aâaqeb uwâiô mavi"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 47, 'Mara ppemqellaâen di tmes, ad inin uôhifen i imzuxiyen: "ni$ nella nedda yidwen. Ma tzemrem, kunwi, ad a$ tesneqsem cwiî, si tmes"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 48, 'A d inin imzuxiyen: "aql a$, akw, degs. S tidep, Öebbi Iêudd ger imdanen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 49, 'Ad inin wid illan di tmes, i iâessasen n Loahennama: "naâôet Mass nnwen, ad a$ Issifes ibwass uâaqeb".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 50, 'Ad inin: "day ur kwen id usan ara imazanen nnwen, s ubeggen"? Ad inin: "ih". Ad inin: "naâret"! Ar ttelfan, kan, tanaârit ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 51, 'War ccekk, a Nsellek imazanen nne£, akked wid iumnen, di tmeddurt n ddunit, u deg wass ideg ara d bedden inagan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 52, 'ass ideg ur infaâ uste$feô imednas. Ad pwaxzun, ad zed$en deg uxxam ucmit mavi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 53, 'Ni$ Nefka, i Musa, nnhaya. Nefka, i At Isôail, Tazmamt d lweôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 54, 'D nnhaya, u d asmekti i uâqilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 55, 'Eûbeô. Ih, lemâahda n Öebbi, d tidep. Ssuter ssmaê ubekkav ik. Sbuccaâ s ccekôan Mass ik, tameddit, taûebêit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 56, 'Ih, wid ipnamaren issekniyen n Öebbi, ur ten id iusi udabu, d tem$weô kan i illan deg idmaren nnsen; ur as ssawven. Ggani Öebbi, Neppa, s tidep, Isell, Ipwali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 57, 'Ih, lxelq n tmurt akked igenwan iugar lxelq n imdanen, maca aîas n imdanen ur éôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 58, 'Ur iaâdil ara uder$al akked win ipwalin, wid iumnen u xeddmen ayen ilhan, akked bu tucmitin. Cwiî id tesmektayem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 59, 'Ihi, imir a d ias, ur illi ccekk fellas, maca tegwti n imdanen ur uminen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 60, 'Inna Mass nnwen: "naâret iyI, ad awen d Jawbe$. Wanag wid igelzen aâbed iW, ad kecmen Loahennama, d imedlulen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 61, 'Öebbi i wen Irran iv, i ureyyeê degs, ass i tmu$li. Öebbi, ih, d Bab n lfevl i imdanen, maca tegwti n imdanen, ur snemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 62, 'D wagi ay d Öebbi, Mass nnwen. Ixleq yal cci, ur illi ôebbi, siwa Neppa. Ihi, acimi tezzim akin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 63, 'Akka ay wexxôen wid iugin issekniyen n Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 64, 'Öebbi i wen Irran tamurt d leqôaô, igenni d ssqef; ikwen Imeslen. Iûeggem udem nnwen. I$at ikwen s wayen ilhan. D wagi ay d Öebbi, Mass nnwen. D Asaâdi Öebbi, Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 65, 'Neppa d Amuddir, ur illi ôebbi siwa Neppa. Ihi, naâôet eP, s lâaqida i Neppa. Ccekôan i Öebbi, Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 66, 'Ini: "nek, ipwakkes iyi uâbad n wid tnaârem war Öebbi, mi yi d iusa ubeggen, s$uô Mass iw. Pwamôe$ d, ad anze$ i Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 67, 'Neppa, ikwen Ixelqen seg wakal; sinna, si tiqqit; sinna, seg urgen; sinna, Issuffe$ ikwen id d igwerdan; sinna, a ppim$uôem; sinna, a ppu$alem d im$aôen. Kra segwen, pmeppaten uqbel. Iwakken a ppawvem ar lajel ipwassnen. Amendeô ma a pfehmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 68, 'D Neppa i Issidiren, i Ineqqen. Ma Iseyya d lameô, ad as Yini kan: "ili"! Ad yili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 69, 'Day ur twalav ara amek ssuff$en i ubrid, wid ipnamaren issekniyen n Öebbi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 70, 'Wid iskaddben Tazmamt, akked wayen i$ef id Nuzen imazanen nne£, deqqal ad éôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 71, 'Mara pwazu$ôen, s teqlavin d slasel,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 72, 'ar waman ippayzagen; sinna, ar tmes, ad pwaveggôen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 73, 'sinna, ad asen inin: "anda t wayen tepcarakem', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 74, 'war Öebbi"? A d inin: "dergen fella$. Xaîi! Ur illi wayen u$uô nepnuju, zik". Akka i Itellif Öebbi ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 75, 'Akka, $ef wayen tzehhum di tmurt, ur teklalem, akked wayen tqebêem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 76, 'Kecmet Loahennama, si tebbura; degs twekkôem. Ay dir tanezdu$t imzuxiyen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 77, 'Eûbeô, war ccekk, lemâahda n Öebbi d tidep. Ad ak Nessken kra n wayen i sen Nâahed, ne$ a Neddem ôôuê ik. £uône£ ara d u$alen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 78, 'Ni$ Nuzen ed imazanen uqbel ik. £ef kra segsen, Neêka yak d. £ef kra nniven, ur ak d Neêka ara. Ur iwata ara i umazan, a d iawi assekni, siwa ma s tsriê n Öebbi. Ma iusa d lameô n Öebbi, aseyyi s tidep. Ad xesôen, imiren, laâôuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 79, 'Öebbi i wen Ifkan lmal i rekba nnwen. Segsen teppeppem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 80, 'Degsen, i kunwi, aba$uô akked agwav ar wayen id ssuturen idmaren nnwen. Fellasen, akw f ssfinat, teppâabbim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 81, 'Issenâat awen d issekniyen iS. Anwi issekniyen n Öebbi ara tnekôem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 82, 'Day ur nudan ara tamurt ad walin amek tevôa d wid i ten id izwaren. Llan ifen ten akken îîuqten, ifen ten tazmert akked lateô di tmurt. Ulay sen d ibbwi wayen la keppben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 83, 'Mi ten id usan imazanen nnsen s ubeggen, feôêen s tmusni i illan $uôsen. Izzi fellasen wayen i$ef ppemsexxiôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 84, 'Mi walan tamnirt nne£, nnan: "numen s Öebbi Yiwen, nveggeô ayen i nella ncurek aS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 85, 'Ur izmir ara a ten infaâ liman nnsen, mi walan tamnirt nne£. D tannumi n Öebbi, si zik, i imdanen iS. Akka ay xesôen ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 1, 'Ëm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 2, 'Tarusi s$uô Uênin Ipêunun,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 3, 'Tazmamt, feûûlen issekniyen is; Leqwôan s taâôabt, i ugdud issnen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 4, 'ipbecciôen, ineddôen. Tegwti degsen numren, d$a ur sellen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 5, 'Nnan: "ulawen nne$ ddurin i wayen i$eô la $ tneccdev; di tmejjin nne$: tiâéegt; garane$ yidek: sîeô. Ihi, exdem, nekwni la nxeddem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 6, 'Ini: "nek d amdan kan, am kunwi. Weêêan iyi d kan ar Öebbi nnwen, d Öebbi Yiwen. Sweqmet $uôeS, ssutret aS ssmaê". A tawa$it n imcurak,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 7, 'wid ur nepzekki, u nitni nekôen laxeôt!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 8, 'Ih, i wid iumnen, ixeddmen ayen ilhan: arraz ur nepnegzay.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 9, 'Ini: "kunwi aql akwen la tnekôem Win Ixelqen tamurt, di sin wussan. La S tepparam nned. Wagi d Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 10, 'Irra degs idurar sufella. Iôqa p, Iwzen degs tagwella s, di kué wussan. Akka i wid isteqsayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 11, 'Sinna, Izzi ar igenni i illan d abbu. Inna yas, u i tmurt: "aset ed, teb$am ne$ tugim"! Nnan: "a n nas, d imvuâen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 12, 'Iseyya ten d ûa igenwan, di sin wussan. Iweêêa lameô is, i yal igenni. Ncebbeê igenni aqôib mavi, s teftilin, u d laânaya. D aya ay d Iqeddeô n Uzmir, Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 13, 'Ma numren, ini: "ssagwde$ kwen s ssiâqa, am ssiâqa n Âad u Tamud".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 14, 'Mi ten id usan imazanen, zdat sen, u deffir sen: "ur âabdet, siwa Öebbi"! Nnan: "lemmer i S ihwi i Mass nne$, a d Issers lmalayek. Nekwni, ihi, nenkeô ayen i s id teppuceggâam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 15, 'Wanag Âad, sme$wôen iman nnsen di tmurt, ur klalen. Nnan: "anwa i $ i$elben di tezmert"? Day ur walan ara, Öebbi, iten id Ixelqen, I$elb iten di tezmert? Llan la nekôen issekniyen nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 16, 'Nuzen asen aûeôûaô, deg ussan imevyaôen, iwakken a Nessukk fellasen, aâaqeb imdelli di tmeddurt n ddunit. Aâaqeb n laxeôt, war ccekk, isdullu kteô. Ur asen ippili umâiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 17, 'Wanag Tamud, Nebbwi ten d ubrid. Smenyafen tider$elt i nnhaya. Tewwet iten ssiâqa n uâaqeb issrusun, ilmend n wayen keppben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 18, 'Nsellek wid iumnen, i illan pêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 19, 'Ass ideg ara ssemlilen ar tmessi, icenga n Öebbi, nitni ad pwajemmlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 20, 'Alamma, mara awven $uôes, ad cehhden fellasen, $ef wayen xeddmen, imeééu$en nnsen, allen nnsen, d igwelman nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 21, 'Ad inin i igwelman nnsen: "acimi id tcuhhdem fella$"? A d inin: "Issenîeq a$ d Öebbi, id Issentaqen yal cci. Neppa, Ixelq ikwen tikelt tamezwarut, u $uôeS ara tu$alem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 22, 'Ur tezmirem ara a ppeffrem, ur cehhden fellawen imeééu$en nnwen, allen nnwen, akked igwelman nnwen. Maca, t$ilem ur Iéeô ara Öebbi, aîas n wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 23, 'Akka ameyyez nnwen $ef Mass nnwen. Isqucc ikwen, tegwram d d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 24, 'Xas ûebôen, di tmes ara zed$en. Ma ssutren ssmaê, ur llin d wid ara ipwaqeblen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 25, 'Nefka yasen imeddukwal i sen icebbêen ayen illan zdat sen, akked wayen illan deffir sen. Iûaô fellasen wawal ger leoyus n yimdanen akw n leonun, i i$aben, uqbel nnsen. Ih, nitni d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 26, 'Nnan wid ijehlen: "ur ssemêaset i Leqwôan agi. Ssekret fellas, ta$wegwa, ahat a prebêem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 27, 'A Nessukk $ef wid ijehlen, aâaqeb uqsiê. A ten Nqeîîi sennig wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 28, 'D wagi ay d aqeîîi icenga n Öebbi: times; i nitni degs axxam n lebda; d aqeîîi, imi la nekôen issekniyen nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 29, 'Ad inin, wid ijehlen: "a Mass nne$! Essken a$ wid i $ i$elîen, d loenn ne$ d amdan; a ten neôkev, ad u$alen seg wid indellen mavi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 30, 'Ih, wid innan: "Mass nne$ d Öebbi", sinna, nudan lewqama, a d rsent $uôsen lmalayek: "ur ppagwadet, ur $webblet; ppubeccôet s Loennet i wen ippuwaââden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 31, 'Nekwni d imawlan nnwen di tmeddurt n ddunit u di laxeôt. Dinna, i kunwi, ayen i cedhant teôwiêin nnwen. Dinna, i kunwi, ayen tessutrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 32, 'D tarusi s$uô Win Ipsemmiêen, Ipêunun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 33, 'Anwa yifen awal umâin n win inaâôen Öebbi, ixeddmen ayen ilhan, id innan: "nek, ih, seg imvuâen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 34, 'Ur iaâdil ise$ akked tucmip. Err ip akin, s wayen ip yifen. Ma tella cceêna, garak d yiwen, ad iu$al d aêbib i k iêemmlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 35, 'Ur teppunefk siwa i wid iûebbôen. Ur teppunefk, siwa i bu sser abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 36, 'Ma iccacev ak Cciîan tuccva, ssuter laânaya n Öebbi. Ih, Neppa d win Isellen, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 37, 'Seg issekniyen iS, ass akked yiv, iîij akked waggur. Ur kennut ara i yiîij, ne$ i waggur. Knut i Öebbi, iten id Ixelqen, ma d Neppa ay tâabbdem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 38, 'Ma zuxxen, ihi, wid illan ar Mass ik, sbuccuâen T iv akked wass, ur âaggun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 39, 'Seg issekniyen iS: a pwaliv, keçç, akal iqquô; lemmer ad as Nesse$li aman, a d iakwi, ad icuff. Win it id Issadren, d Win ara d Issidren lmeggtin. Ih, Neppa, Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 40, 'Ih, wid issexûaôen issekniyen nne£, ur drigen fellane£. Menyif win ara ipwaveggôen ar tmes, ne$ win ara iasen di laman, ass n tnekra? Xedmet ayen i wen ihwan. Neppa, s tidep, Ipwali ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 41, 'Akka, wid inekôen asmekti, mi ten id iusa, u neppat ard Tazmamt tuzmirt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 42, 'Ur d iusi le$wlav zdat es, ne$ deffir es. D tarusi s$uô Bab n ûûwab, Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 43, 'Awal i k id iusan, d win kan id iusan imazanen, uqbel ik. Mass ik, ih, ard Bab n ssmaê, d Bab uâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 44, 'Lemmer Nerri Leqwôan s tmeslayt tabeôôanit, a d inin: "lemmer feûûlen issekniyen iS s wawal abeôôani, u s taâôabt"? Ini: "neppa, i wid iumnen, d nnhaya u d ccafuâa. Wid ur numin ara, âaégent tmejjin nnsen. Neppa, i nitni, d tider$elt. Widak pwanecden seg umkan ibaâden".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 45, 'Ni$ Nefka yas Tazmamt i Musa. Mgarraden fellas. Lemmer ur d izwar ara wawal s$uô Mass ik, yili tefra garasen. Nitni, fellas, di ccekk imcebbwel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 46, 'Win ixedmen ayen ilhan, i iman is; win iccven, mgal iman is. Mass ik ur Idennis ara imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 47, '£uôeS ay tella tmusni n yimir. Ur d iteffe$ uzway si txeddact is, ur treffed nnta tadist, ur tepparew, siwa ma Iéôa. Ass ideg ar asen Isiwel: "anda ten icriken iW"? A d inin: "ad aK nini, ur illi garane$ unagi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 48, 'Iooa ten wayen u$uô pnujun zik. Fehmen, ur asen illi ssôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 49, 'Ur ifeccel ara umdan di tuppra n lxiô. Ma inul it lqeôê, ad iayes, ad innu$ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 50, 'Ma Nseêess as aêunu nne£, deffir ccqa i t iêuzan, war ccekk, ad yini: "ayagi inu. Ur cukke$ ara imir a d ias. Ma bbwve$ s afus n Mass iw, ad afe$ $uôeS ûûam". Ih, a Nbeggen ayen xedmen, i wid ijehlen, u, ih, ad Nsâaddi fellasen aâaqeb iwaâôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 51, 'Ma N$at amdan ad iwexxeô, izzi akin. Ma iêuza t lêif, ad ipnuju, irennu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 52, 'Ini: "tmeyyzem ma iusa d s$uô Öebbi, u kunwi tnekôem t"? Anwa innetlafen sennig win illan di ticuîna tu$miqt?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 53, 'Ad asen Nessken issekniyen nne£ di tmurt akked igenwan, u deg iman nnsen, alamma pputebbten ar neppa d tidep. Day ur Iqadd ara Mass ik mi Neppa, war ccekk, d Anagi n yal cci?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 54, 'Day, s tidep, cukken timlilit d Mass nnsen? Day Neppa, s tidep, ur Izzi ara i yal cci?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 1, 'Ëm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 2, 'Âsq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 3, 'Akka i Iweêêa i keçç, akked wid ik id izwaren, Öebbi, Uzmir, Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 4, 'IneS i illan deg igenwan, i illan di tmurt. Neppa, d Aâlayen, d Ameqwôahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 5, 'Qôib ad ccergen igenwan seg ixfawen nnsen, mara d lhint lmalayek deg usbuccaâ s ccekôan n Mass nnsent, u ssuturent ad pwassemêen kra illan di tmurt. War ccekk, Öebbi Ipsemmiê, Ipêunu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 6, 'Wid irran imawlan, war Neppa, Iquôaâ ten Öebbi. Ur telliv, keçç, d awkil nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 7, 'Akka ay k n Nweêêa Leqwôan, s taâôabt, iwakken a pnedôev tayimmap n temdinin, akked wayen i s d izzin; a pnedôev af ass n temlilit, ur degs ccekk; arbaâ di Loennet, arbaâ deg ujajiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 8, 'Lemmer i S ihwi i Öebbi, yili Izdukkel iten d yiwen n lois. Maca, ad Issekcem win i S ihwan ar uêunu S. Imednas, ur sâin bab ne$ asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 9, 'Ne$ rran imawlan, war Neppa. Öebbi d Neppa ay d Bab, d Neppa i Issidiren lmeggtin, d Neppa i Izemren i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 10, 'Ayen akw i$ef temgarradem, aêuddu s ar Öebbi. Akka Öebbi, Mass iw; fellaS ppekle$, $eô Neppa ay steôoiâe$.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 11, 'Axellaq n tmurt akked igenwan. Seg iman nnwen Irra yawen tiyugiwin; si lmal nnwen, tiyugiwin. Isfukti kwen yisent. Ur illi wayen i T icban. Neppa Issel, Ipwali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 12, 'IneS tisura n tmurt akked igenwan. Issugut ôôeéq i win i S ihwan, Iwezzen. Ih, Neppa Issen yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 13, 'Issers awen d, di ddin, ayen i$ef Iweûûa Nuê. Ayen i k Nweêêa, d ayen i$ef Nweûûa Ibôahim, Musa, akked Âisa: "sbeddet ddin, ur ppemgarradet fellas". èÈÈéay, i imcurak, wayen u$uô la ten tneccdev. Öebbi Ippawi $uôeS, win i S ihwan; Inehhu $uôeS, win isteôoiâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 14, 'Ur mfaôaqen armi ten id tusa tussna. Ppemvuddun. Lemmer ur d izwar wawal s$uô Mass ik $ef lmijal ipwassnen, yili myefran. Ih, wid iweôten Tazmamt deffir sen, haaten, fellas, di ccekk imcebbwel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 15, 'Ilmend n waya, enced, ssewqem akken i tepwamôev, ur teddu d cchawi nnsen. Ini: "umne$ s wayen id Issader Öebbi n Tira. Pwamôe$ d ad wezne$ garawen. Öebbi d Mass nne$, u d Mass nnwen. I nekwni igiten nne$, i kunwi igiten nnwen. Ur teppili nnmara garane$. Öebbi ad a$ Issemlil. Tu$alin $uôeS".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 16, 'Wid ipnamaren af Öebbi, deffir wagwav n loawab $uôsen, ur teswi nnmara nnsen, ar Mass nnsen. Fellasen zzâaf, fellasen aâaqeb uqsiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 17, 'Öebbi id Issadren Tazmamt, s tidep, akked lmizan. W ad ak imlen, ahat imir iqeôb ed?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 18, 'Ëaren $uôes wid ur numin ara yis. Ma d wid iumnen, ugaden t; éôan ar neppa d tidep. Ih, wid icukken deg imir, haaten, war ccekk, di ttelfan u$miq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 19, 'Öebbi d Laîif i imdanen iS. Ip$iti win i S ihwan. Neppa d Uohid, d Uzmir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 20, 'Win ib$an tayerza n laxeôt, ad as Nernu di tyerza ines. Win ib$an tayerza n ddunit, ad as Nefk segs. Ur as illi umur di laxeôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 21, 'Ne$ sâan icriken, sse$ôen ten di ddin ur Iqbil Öebbi? Lemmer ur d izwir ara wawal n ufraz, a p fru garasen. I imednas, war ccekk, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 22, 'A pwaliv imednas feqâen ilmend n wayen kesben, u neppa iddehm ed fellasen. Wid iumnen, ixeddmen ayen ilhan, ad ilin di tebêirin n leonanat. Nnsen i sen ihwan $uô Mass nnsen. D wagi ay d lfevl ameqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 23, 'D wagi is Ipbecciô Öebbi imdanen iS, wid iumnen, ixeddmen ayen ilhan. Ini: "ur awen ssutre$ taqdiât, af waya, siwa lmaênana i llezm nnwen". Win ixedmen ise$, ad as Nernu degs lehhu. Öebbi, ih, Ipsemmiê, Ippara tajmilt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 24, 'Ne$ a d inin: "isnulfa d tikerkas af Öebbi". Ma ihwa yaS i Öebbi, ad Icemmaâ ul ik. S wawal iS, ad Isqucc Öebbi tikerkas, ad Iêeqqeq tidep. Ih, Neppa Iéôa tababnit n idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 25, 'D Neppa i Iqeblen nndama n yimdanen iS. Ipsemmiê tucmitin. Issen ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 26, 'Issemêas i wid iumnen, ixeddmen ayen ilhan. Ad asen Irnu si lfevl iS. I ijehliyen, aâaqeb uqsiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 27, 'Ma Issuget Öebbi l$it i imdanen iS, ad be$wven di tmurt. Maca, Issrusu d, s lmizan, ayen i S ihwan. Ih, Neppa Ippuxebbeô $ef imdanen iS, Ipwali ten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 28, 'D Neppa id Isse$layen ageffur mara aysen. Iweppaâ aêunu S. Neppa d Bab, d Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 29, 'Seg issekniyen iS, lxelq n tmurt, igenwan, akked wayen illan n lewêuc, degsen. Izmer Neppa, ma ihwa yaS, a ten id Issemlil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 30, 'Kra n tiyta ikwen iwwten, siwa ayen d bbwin ifassen nnwen. Aîas i Ipsemmiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 31, 'Ur tezmirem a ppesfunngem di tmurt. Ur awen illi, war Öebbi, bab ne$ asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 32, 'Seg issekniyen iS, ssfinat di yill, amzun d idurar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 33, 'Ma ihwa yaS ad Issens avu, ad êebsent, d tusbivin sufella s. War ccekk, ayagi d issekniyen i yal aûebôi isnemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 34, 'Ne$ a ten Issenger ilmend n wayen kesben. Aîas i Ipsemmiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 35, 'Ad éôen wid ipnamaren $ef issekniyen nne£, ar ur asen illi ssôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 36, 'Ayen akw i wen ippunefken n wayla, d zzhu n tmeddurt di ddunit. Ayen illan ar Öebbi, yif it; ad idum kteô, i wid iumnen, ippeklen $ef Mass nnsen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 37, 'wid ijunben ibekkaven ibararen, akked lâaô, u ssurufen i wid i ten isserfan;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 38, 'wid id ipjawaben i Mass nnsen, péallan, ppemcawaôen $ef lameô nnsen, pseddiqen seg wayen iten N$at;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 39, 'wid, ma iusa ten lbe$wv, ad qablen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 40, 'Aqeîîi n tucmip, d tucmip i p icban. Win isemmêen, issweqmen, arraz is ar Öebbi. Neppa, ih, ur Iêemmel ara imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 41, 'Ma d wid id irran ppaô mi pwadensen, ur telli tiyta degsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 42, 'Tiyta, kan, deg wid ivuôôen imdanen, iqehôen di tmurt, war ssebba. I wigi, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 43, 'Ma d win iûebôen, isemmêen, ayagi, s tidep, d aseyyi n lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 44, 'Win Itlef Öebbi, ur isâi bab, deffir eS. A pwaliv imednas, mara éôen aâaqeb, ad inin: "ma illa ubrid n tu$alin"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 45, 'A ten twaliv pwafessren fellas, ndellen, ggaren tiî s tugwdi. Ad inin wid iumnen: "imexsuôen, s tidep, d wid i sxesôen iman nnsen, akked twacult nnsen, ass n tnekra". War ccekk, deg uâaqeb imezgi, ara yilin imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 46, 'Ur asen llin imawlan, ara ten isellken, war Öebbi. Win Itlef Öebbi, ur isâi abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 47, 'Jawbet i Mass nnwen, uqbel a d ias, s$uô Öebbi, ass ur nepwexxiô. Ur awen ippili ssôan assen, ur tezmirem a pnekôem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 48, 'Ma numren, ur k id Nuzen ara d amêareb nnsen. Ay fellak, siwa timenna. Ih, mara Nesêess i umdan aêunu s$uône£, ad ifôeê yis. Mara t tsami tucmip, id bbwin ifassen is, s tidep, amdan ad ikaraâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 49, 'N Öebbi, tagelda n tmurt akked igenwan. Ixelleq ayen i S ihwan. Ippak nnta i win i S ihwan, Ippak ddkeô i win i S ihwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 50, 'Ne$ Ipcarak ddkeô d nnta. Isaâqaô win i S ihwan. Ih, Neppa Issen, Izmer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 51, 'Ur ippunefk ara i umdan, ad as Immeslay Öebbi, siwa aweêêi, ne$ deffir ucembir, ne$ a d iazen amazan iwumi ara Iweêêi, s tsriê iS, ayen Ib$a. Ih, Neppa d Aâlayen, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 52, 'Akka ik d Nweêêa ôôuê, si lameô nne£; ur telliv d win issnen d acu p Tezmamt, ne$ liman. Maca, nerra p d tafat. Yis Nenehhu win i £ ihwan, seg imdanen nne£. Ih, d Keçç i ippawin d ubrid uwqim;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 53, 'abrid n Öebbi, i Isâan i illan di tmurt, i illan deg igenwan. War ccekk, ar Öebbi ay teddun lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 1, 'Ëm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 2, 'S Tezmamt ipbegginen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 3, 'Nerra p d Leqwôan s taâôabt, amar a pfehmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 4, 'Neppa, ih, ata $uône£, ar Tyimmap n Tezmamt, d aâlayan, d uûwib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 5, 'Day a kwen Nêewwej seg usmekti, imi kunwi d agdud ipêawalen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 6, 'Acêal id Nuzen d nnbi i imezwura!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 7, 'Ur ten id ippas nnbi, mebla ma mmaâlken fellas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 8, 'Nemêa wid i ten yifen tazmert. U iûaô umedya imezwura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 9, 'Ma testeqûav ten: "anwa i Ixelqen tamurt akked igenwan"? A d inin, war ccekk: "Ixelq iten Uzmir, Amusnaw";', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 10, 'i wen Irran tamurt d dduê; i wen Igan, degs, iberdan - amendeô ma a ppeppwanhum -;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 11, 'id Isse$layen, seg igenni, aman s lmizan - Nessakway yissen tamurt immuten; akka ara d tekkrem -;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 12, 'id Ixelqen akw tiyugiwin, i wen Ifkan, si sfinat akked lmal, ara trekbem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 13, 'A pâanncem $ef iârar nnsen; sinna, a d tesmektim l$it n Mass nnwen, mara pâanncem fellasen. A ppinim: "gedha s Win i d Inuben fella$ s waya, ur t nemlik!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 14, 'Ih, a nu$al ar Mass nne$".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 15, 'Ëesben ay T iâabden d amur segS. Amdan, s tidep, d anekkaô n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 16, 'Ne$ day d Iddem tullas seg wayen Ixleq, u Ifren awen d arrac?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 17, 'Ma ibbwev ed usali yiwen segsen, $ef wayen id ifka d amedya i Uênin, ad yibrik wudem is, ad ikkufer:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 18, '"ayen d ikren di rrêuê, ur nessifrir anamer"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 19, 'Ëesben lmalayek, i illan d ixdimen n Uênin, d nnta. Day êevôen i uxlaq nnsent? Tira $ef ccada nnsen; fellasen asteqsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 20, 'Nnan: "lemmer Irad Uênin, yili ur ten naâbbid". Ur sâin kra n tmusni $ef waya. Nitni la pxeôôiven kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 21, 'Ne$ Nefka yasen Tazmamt, uqbel Tagi, d$a, degs, îîfen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 22, 'Xaîi! Nnan: "nufa d, ih, imezwura nne$, di laâqida. D$a, nekwni, Nedda di lateô nnsen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 23, 'Am akka, ur d Nuzen, uqbel ik, aneddaô ar temdint, mebla ma nnan isâiyen is: "nufa d imezwura nne$ di laâqida. D$a, nedda d lateô nnsen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 24, 'Inna: "i ma bbwi$ awen d nnhaya yifen tin id tufam ar imezwura nnwen"? Nnan: "nekwni, ihi, nugwi ayen is id teppuceggâam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 25, 'Nerra d ppaô, segsen. Muqel amek tevôa d inekkaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 26, 'Mi inna Ibôahim i baba s, akked ugdud is: "nek, ur pkka$ deg wayen la tâabdem,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 27, 'kkes ed Win iyi d Ixelqen. D Neppa, s tidep, ara iyi Inhun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 28, 'Irra t d awal imezgi i texlift is, amar a d u$alen s abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 29, 'U £ate$ ten, nitni akked imezwura nnsen, armi ten id tusa tidep, akked umazan ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 30, 'Mi ten id tusa tidep, nnan: "wagi d ssêur, ihi, nekwni nugi t".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 31, 'Nnan: "A lemmer id ssadren Leqwôan agi ar urgaz ameqwôaêan n snat temdinin"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 32, 'Day d nitni i ifeôôqen aêunu n Mass ik? D Nekwni i sen Ifeôôqen tamâict nnsen, di tmeddurt n ddunit, u Nessuli kra segsen, tidekkaôin sennig wiyav, iwakken kra, ad sxedmen wiyav. Aêunu n Mass ik yif ayen jemâan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 33, 'Lemmer maççi yiwen n lois kan ara yilin imdanen, a Nerr tiseddura n lfeîîa i ixxamen n wid inekôen Aênin, akw i tiseddaôin i$ef ara alin;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 34, 'i ixxamen nnsen, tibbura; imîeôêen ideg ara élen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 35, 'akked uzewweq. Maca, ayagi akw, d astumen i tmeddurt n ddunit. Laxeôt, ar Mass ik, i wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 36, 'Win iooan asmekti n Uênin, ad as Nqelled Cciîan, ad as yili d amsaâef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 37, 'Ih, Nitni veôôifen ten seg ubrid, u $ilen ar nitni pwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 38, 'Alamma ma iusa d $uône£, inna d: "ah, awufan gari yidek, amecwaô illan ger ugmuv d wayev". A yir amsaâef!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 39, 'Ur kwen infaâ, assa, d awez$i, ma tdensem. Aql akwen tcerkem aâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 40, 'Day a pperrev, keçç, aâeééug ad issel, ne$ a ppenhuv ader$al, akked win illan di ttelfan n ûûeê?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 41, 'Amar a k id Nekkes, d$a a d Nerr ppaô segsen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 42, 'ne$ ak Nessken ayen i sen d Nhegga. £uône£, ih, adabu fellasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 43, 'Ïîef deg wayen i k d ippuweêêan. Keçç, war ccekk, aql ak deg ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 44, 'Wagi, ih, d asmekti i keçç, akked ugdud ik; deqqal fellawen asteqsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 45, 'Steqsi wid id Nuzen, uqbel ik, seg imazanen nne£. Day Nerra, war Aênin, iôebbiten ara âabden?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 46, 'Ni$ Nuzen ed Musa s issekniyen nne£, ar Ferâun akked imvebbôen is. Inna: "nek d amazan n Mass imavalen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 47, 'Mi sen d ibbwi issekniyen nne£, nitni la ppavsan degsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 48, 'Ur asen Nessenâata assekni, siwa ma i$leb gma s. Nesâadda fellasen aâaqeb, amar a d u$alen s abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 49, 'Nnan: "a yaseêêar, nâaô a$ Mass ik, s lemâahda i k Ifka. Nekwni ara nepwanhu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 50, 'Mi Nessafer aâaqeb fellasen, imiren ad xedâan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 51, 'Imdeê Ferâun i ugdud is, inna: "a yagdud iw, day maççi inu tagelda n Maseô, akked isaffen agi, i ippazalen seddaw i. Day ur twalam ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 52, 'Ne$ nek ur ife$ ara imdelli agi, ur nezmir ad ibeggen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 53, 'Acimi ur as qqnen ara imeqyasen n uwôe$, ne$ ur d usint ara yides lmalayek, pwazdan t"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 54, 'Issefqaâ agdud is. Unzen as. Wigi, ih, d agdud ucmit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 55, 'Mi £ zzaâfen, Nerra d ppaô segsen, Ne$meq iten meôôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 56, 'Nerra ten d asmekti u d amedya, i ineggura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 57, 'Mi sen d ippunefk mmi s n Meryem, d amedya, agdud ik iugwi t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 58, 'Qqaôen: "ppif iôebbiten nne$, ne$ Neppa"? Qqaôen ak d akka, i nnmara. Ih, nitni d agdud ipmeôéan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 59, 'Neppa d amdan kan. N$at it, Nerra t d amedya i At Isôail.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 60, 'Lemmer i£ £ ihwi, a Nerr lmalayek di tmurt, deg umkan nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 61, 'Neppa, s tidep, d ppbut n yimir. Ur ppilit di ccekk fellas. Ddut yidi; wagi d abrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 62, 'Ur kwen issefra$ Cciîan! Ih, neppa d acengu nnwen n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 63, 'Mi n iusa Âisa s issekniyen, inna: "usi$ d $uôwen s ûûwab, ad awen beggne$ kra, seg wayen i$ef temgarradem. Ihi, êezzbet i Öebbi, ta$em iyi awal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 64, 'Öebbi, s tidep, d Mass iw u d Mass nnwen. Ihi, âabdet eÏ, d wagi ay d abrid uwqim".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 65, 'Mgarraden ikabaren garasen. A tawa$it n wid idensen, ilmend uâaqeb n wass aqeôêan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 66, 'Day a pôaoun imir, ad asen d ias, deqzalla, nitni ur bnin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 67, 'Iêbiben, assen, ad u$alen wa d acengu n wa, kkes ed wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 68, 'A yimdanen iW, assa, ur telli tugdi fellawen, ur $webblet!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 69, '- Wid iumnen s issekniyen nne£, u llan d imvuâen -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 70, 'Kecmet Loennet, kunwi akked tlawin nnwen, a ppezhum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 71, 'Ad asen ddewwiôen, s sniwat n uwôe$, akked ibuqalen; degsen ayen cihwant teôwiêin, ayen iqennâen allen. Kunwi, din, ad twekkôem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 72, 'D tagi ay d Loennet i tweôtem, ilmend n wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 73, 'Degs, i kunwi, aîas n izwayen, segsen a ppeççem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 74, 'Ibe$wviyen, s tidep, deg uâaqeb n Loahennama, ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 75, 'Ur ipfukku fellasen. Nitni, degs, ad kkufferen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 76, 'Ur ten Nednis, maca llan, nitni, d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 77, 'Ad necden: "a Malik, xas ad a$ Iqfeô Mass ik"! A d ini: "war ccekk, a pwellfem"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 78, 'Ni$ Nusa n $uôwen, s tidep, maca tegwti, degwen, keôhen tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 79, 'Ne$ undin ticeôkep. Ula d Nekwni Neppandi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 80, 'Ne$ $ilen ur Nsell ara i lesrar nnsen, akked tumlin nnsen. Ihi, imceggâen nne£, $uôsen, pparun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 81, 'Ini: "lemmer illi mmi s i Uênin, nek d aâbad amenzu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 82, 'Gedha s Mass n tmurt akked igenwan, Mass n usgeld, mgal ayen pxeôôiven!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 83, 'Anef asen ad nexxôen, ad uraren, alamma mmugren ass nnsen, i sen ippuwaââden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 84, 'D Neppa ay d Öebbi deg igenni, d Öebbi di tmurt, u d Bab n ûûwab, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 85, 'Iôqa Win Ilan tagelda n tmurt, igenwan, akked wayen illan garasen. Iéôa melmi ay d imir. £uüôeS, ara tu$alem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 86, 'Wid i la naâôen, war Neppa, ur $uôsen kra n ccafuâa, kkes ed inagan n tidep, u nitni éôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 87, 'Ma testeqûav ten anwa iten Ixelqen, a d inin, war ccekk, "d Öebbi". Ihi, acimi zzin akin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 88, 'Timenna s: "a Mass iw! Wigi, s tidep, d agdud ur numin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 89, 'Wexxeô asen, ini: "tifrat"! Deqqal ad éôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 1, 'Ëm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 2, 'S Tezmamt ipbegginen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 3, 'Nessader ip id, ih, deg iv iôqan. Ih, Nekwni, Nella d ineddaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 4, 'Iban ed degs, yal lameô uûwib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 5, 'Lameô s$uône£. Ih, Nekwni Nella d wid Ippaznen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 6, 'Aêunu s$uô Mass ik. Ih, Neppa Isell, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 7, 'Mass n tmurt, igenwan akked wayen illan garasen, ma tepputebbtem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 8, 'Ur illi ôebbi siwa Neppa. Issidir, Ineqq. D Mass nnwen, u Mass n lejdud nnwen, imezwura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 9, 'Xaîi! Nitni, di ccekk, ppuraren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 10, 'Qaôaâ ass, ideg ara d iawi igenni, abbu ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 11, 'Ad i$umm imùdanen. Wagi d aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 12, '"A Mass nne$! Kkes a$ aâaqeb; nekwni d lmumnin"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 13, 'Amek ara sâun asmekti, wanag iusa ten id Umazan ipbegginen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 14, 'D$a wexxôen as, u nnan: "d aselmad aôehbani". ²', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 15, 'Ma Nessenqes awen cwiî uâaqeb, ihi, kunwi, a ppu$alem ar din.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 16, 'Ass ideg ara Neédem fellasen, ééedma tabarart, war ccekk, a d Nerr ppaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 17, 'Ni$ Njeôôeb, uqbel nnsen, agdud n Ferâun. Iusa ten id umazan ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 18, '"Seddut yidi imdanen n Öebbi; nek, $uôwen, d amazan muman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 19, 'Ur ssem$waôet iman nnwen, zdat Öebbi. Nek, usi$ d $uôwen, s udabu n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 20, 'Nek, ad iyi Isseô Mass iw u d Mass nnwen, ur iyi tôeoomem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 21, 'Ma ur iyi tuminem ara, aâzlet iyi".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 22, 'Inuj $eô Mass is ar wigi d agdud ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 23, '"Awi imdanen iW deg iv. War ccekk, a kwen in vefôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 24, 'Eoo ill ildi; nitni, ih, d lâaskeô ara i$emqen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 25, 'Ay ooan di tebêirin, akked tliwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 26, 'igran, ixxamen ukyisen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 27, 'l$it swayes zehhun!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 28, 'Akka ay ten Nefka d lweôt i ugdud nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 29, 'Ur d run, fellasen, igenni akked tmurt. Ur ggunin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 30, 'Ni$ Nsellek At Isôail, seg uâaqeb isdullun,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 31, 'si Ferâun, i illan, s tidep, d amnefxi ger imaâfan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 32, 'S tmusni ay ten Nefren deg imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 33, 'Nefka yasen seg issekniyen, wid ujeôôeb ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 34, 'Ih, widak la qqaôen:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 35, '"Siwa tameppant nne$ tamezwarut, ur fella$ tanekra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 36, 'Awit ed imezwura nne$, ma tessawalem tidep"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 37, 'Menyif nitni ne$ agdud n Tubbaâ, akked wid i ten id izwaren? Nessenger iten. S tidep, nitni llan d ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 38, 'Ur Nexliq ara tamurt, igenwan, akked wayen illan garasen, i wurar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 39, 'Nxelq iten kan s tidep, maca, tegwti degsen, ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 40, 'S tidep, ass n ufraz, ad mlilen meôôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 41, 'Ass ideg aêbib ur i$ennu aêbib, s wacemma; nitni ur pwasellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 42, 'Kkes ed wid i$ef Iêun Öebbi. Neppa, s tidep, d Uzmir, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 43, 'Ih, ttejôa n Zaqqum,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 44, 'uççi umednub,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 45, 'am nnêas ifsin, ippayzag di tâabbuvin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 46, 'akken ppayzagen waman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 47, '"Ddemt ep, zu$ôet ep, ar pnaûfa ujajiê,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 48, 'sinna, smiret sufella uqeôôu s, aâaqeb ippayzagen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 49, '"Jeôôeb! Ni$ keçç d uzmir, d ukyis"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 50, 'Ih, wagi d ayen i la tepcukkum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 51, 'Wanag wid iêezzben, deg umekkan n laman;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 52, 'di leonanat akked tliwa;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 53, 'lebsa nnsen s leêrir, leêrir iêewwcen. Mqabalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 54, 'Akka, a ten Njewweo akked têuôtin lâin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 55, 'A d ssutren, dinna, yal izwayen, di laman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 56, 'Ur pjeôôiben, dinna, tameppant, siwa tameppant tamezwarut. Isellek iten seg uâaqeb ujajiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 57, 'D lfevl n Mass ik, d wagi ay d rrbeê ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 58, 'Nsehhel it kan, s tmeslayt ik, amendeô ma a d mmektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 59, 'Ggani, ula d nitni la pganin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 1, 'Ëm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 2, 'Tarusi n Tezmamt s$uô Öebbi, Uzmir, Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 3, 'Di tmurt akked igenwan, s tidep, llan issekniyen i lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 4, 'Di lxelq nnwen, akked wayen id Issefôuôex n lewêuc, d issekniyen i ugdud ipputebbten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 5, 'Di lemgarda n yiv akked wass, akked wayen id Issrusu Öebbi n ôôeéq, seg igenni - Issidir yis tamurt, deffir tmeppant is -, deg udewwel n wavu, issekniyen i ugdud ipmeyyizen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 6, 'D wigi ay d issekniyen n Öebbi; Nemmal ak ten, s tidep. Anwa ameslay ara amnen, deffir Öebbi akked issekniyen iS?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 7, 'A ssxev n yal akeddab amednub!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 8, 'Issemêas i issekniyen n Öebbi, qqaôen as ten, sinna, iggernen di tem$weô, amzun ur asen isli. Ihi, becceô it s uâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 9, 'Ma illa wayen iwumi isla, seg issekniyen nne£, ad ittihi fellas. I widak, aâaqeb isdullun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 10, 'Deffir sen Loahennama. Ur ten i$ennu s wacemma wayen kesben akked wayen rran d imawlan, war Öebbi. I nitni, aâaqeb abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 11, 'Tagi d nnhaya. Wid iugin issekniyen n Mass nnsen, fellasen aâaqeb n daâwessu taqeôêant.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 12, 'Öebbi i Inuben fellawen s yill; ipcali, fellas, lbabuô, s lameô iS; a pnadim l$it iS. Amar a ppesnemrem!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 13, 'Inub fellawen s wayen akw illan deg igenwan, akked wayen illan di tmurt. Akw s$uôeS. S tidep, deg waya, d issekniyen i ugdud ismektayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 14, 'Ini i wid iumnen ad semmêen i wid ur negguni ara ussan n Öebbi, iwakken ad Ikafi agdud $ef wayen keppben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 15, 'Win ixedmen ayen ilhan, i iman is; win ifalîan, mgal is. Sinna, ar Mass nnwen tu$alin nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 16, 'Ni$ Nefka, i At Isôail, Tazmamt, ûûwab, lambiyya. Nôeéq iten s wayen ilhan. Nesmenyaf iten i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 17, 'Nefka yasen abeggen si Lameô. Ur mgarraden, armi i ten id tusa tmusni, wa iqheô wa. Ih, Mass ik ad Iêudd garasen, ass n tnekra, $ef wayen i$ef mgarraden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 18, 'Sinna, Nebbwi k deg ubrid n Lameô. Ddu degs, ur teddu akked chawi n wid ur nessin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 19, 'Ih, nitni ur ak d ppawin acemma s$uô Öebbi. Imednas, ih, d imawlan wa n wa. Öebbi d Bab n wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 20, 'Ayagi d assekni i l$aci, d nnhaya u d aêunu i ugdud ipputebbten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 21, 'Ne$ $ilen wid imôôeôen iman nnsen s tucmitin, a ten Neêseb am wid iumnen, ixeddmen ayen ilhan, d imuddiren ne$ d lmeggtin. Dir it uêuddu nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 22, 'Öebbi Ixleq tamurt akked igenwan, s tidep, iwakken yal amdan ad ippuqeîîi af wayen ikseb. Nitni ur pwadensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 23, 'Twalav win irran lhawiyya s d ôebbi is? Itelf it Öebbi, asali $uôeS. Iskweô as ul, timejjin, Irra yas aâbôuq af allen is. Anwa ara t inhun, deffir Öebbi? Day u la tesmektayem ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 24, 'Nnan: "i illan kan, d tudert nne$, di ddunit. A nemmet, a nidir. Ad a$ in$en kan d akud". £ef ayagi, ur sâin kra n tmusni. Nitni $ilen kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 25, 'Ma mlan asen issekniyen nne£ iberrzen, anamer nnsen, siwa mara d inin: "erret ed imezwura nne$, ma tessawalem tidep"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 26, 'Ini: "Öebbi Issidir ikwen, sinna, Ineqq ikwen. Sinna a kwen Issemlil ass n tnekra, ur illi degs ccekk". Maca, tegwti n yimdanen ur ssinen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 27, 'N Öebbi, tagelda n tmurt akked igenwan. Ass ideg ara d ias yimir, ass nni, ad xesôen ucmiten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 28, 'A pwaliv yal lois $ef tgwecrar, yal lois ipwanced ar tezmamt is. Assa, a p$eltem ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 29, 'Tagi d tazmamt nne£, tessawal tidep fellawen. Nella Nepjerrid ayen akw txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 30, 'Ihi, wid iumnen, ixeddmen ayen ilhan, a ten Issekcem, Mass nnsen, s aêunu S. Wagi d rrbeê n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 31, 'Wanag wid ijehlen: "day ur awen $ôan ara issekniyen iW? Tesme$wôem iman nnwen, tellam d agdud ibe$wviyen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 32, 'Mi nnan: "ih, lemâahda n Öebbi, d tidep; imir, ur degs ccekk", tennam: "ur neéôi d acu ay d imir; $uône$ d nnwaya kan, ur nepputebbet".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 33, 'Ad asen d vehôent tucmitin xedmen, ad asen izzi wayen i$ef ttihin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 34, 'Ad asen Inin: "assa, a kwen Neppu, akken teppum timlilit n wass nnwen agi. Axxam nnwen d times, ur awen illi useîîaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 35, 'Ayagi, acku kunwi la tettihim $ef issekniyen n Öebbi. T$uôô ikwen tudert n ddunit. Assa, ur d teff$en segs". Ur isti$fiô êedd fellasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 36, 'I Öebbi annuz, Mass igenwan, Mass n tmurt, Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 37, 'I Neppa akw ayen iufraren, di tmurt akked igenwan. Neppa, d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 1, 'Ëm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 2, 'Tarusi n Tezmamt s$uô Öebbi, Uzmir, Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 3, 'Ur Nexliq tamurt, igenwan, akked wayen illan garasen, siwa s tidep, ar lajel ipwassnen. Wid ijehlen numren ayen u$uô pwanedôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 4, 'Ini: "day ur twalam ara wigi u$uô la tepnujum, war Öebbi? Sseknet iyi d, d acu xelqen si tmurt, ne$ ma sâan amur deg igenwan? Awit iyi d tazmamt id izwaren tagi, ne$ lateô n tmusni, ma tessawalem tidep".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 5, 'Anwa innetlafen sennig wid ipnujun, war Öebbi, $eô wayen ur asen d nepparra, ar ass n tnekra, u nitni stehzan deg unuju nnsen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 6, 'Mara twafesrem imdanen, ad ilin d icenga nnsen, ad skiddben aâbad nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 7, 'Ma $ôan asen issekniyen nne£ iberrzen, wid iugin tidep, mi ten id tusa, ad inin: "wagi d ssêur n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 8, 'Ne$ ad inin: "isnulfa t id". Ini: "lemmer it id snulfa$, ur tezmirem ad iyi tsellkem, s wacemma, si Öebbi. Neppa, Yif akw akken Issen, acu têekkum fellas. Iqadd Neppa d Anagi gari yidwen. Neppa, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 9, 'Ini: "ur lli$, ger imazanen, d win id isnulfuyen. Ur éôi$ acu ara ivôun yidi, ne$ yidwen. La îîafaôe$, kan, ayen iyi d ippuweêêan. Aql i, kan, nek, d aneddaô ipbegginen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 10, 'Ini: "meyyzet ma, ayagi, s$uô Öebbi, u tnekôem t? Icehhed unagi n At Isôail, $ef lmetl is, d$a iumen. Tesme$wrem iman nnwen". Ih, Öebbi ur Inehhu agdud imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 11, 'Nnan wid ijehlen, i wid iumnen: "lemmer d ayen ilhan, ur a$ zeggwiren $uôes". Imi ur pwanhan ara syis, qqaôen: "ayagi d tikerkas n zik".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 12, 'Uqbel is, Tazmamt n Musa, d nnhaya u d aêunu. Tagi d Tazmamt itebbiten, s wawalen n taâôabt, a ppendeô wid idensen, a ppessefôeê lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 13, 'Ih, wid iqqaôen: "Mass nne$ d Öebbi, d$a îfen degs, ur ppagaden, ur $weblen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 14, 'Widak d at Loennet, degs ad wekkôen, d arraz n wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 15, 'Nweûûa amdan ar lewqama s imawlan is. Imma s temêen s tadist, temêen di tinnufra. Ger tadist akked ujumi, caret wagguren. Armi ibbwev d anqaqôi, issawev kuéet isegwasen, inna: "a Mass iw! Eoo iyi a K snemmre$ af l$it i $ T$atev, nek akked lwaldin iw; ad xedme$ ayen ilhan ara K iôavin. Efk iyi d tarwa ilhan. Aql i utube$ K, aql i seg imvuâen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 16, '£uô wigi, Nqebbel lmefruz igiten nnsen, a Nessuref i tucmitin nnsen, ger at Loennet; d lemâahda n tidep, i sen ippuwaââden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 17, 'Win innan i imawlan is: "tfuh nnwen! Day yi tâahdem a d kkre$? Ni$ âaddan isuta uqbel i". Nitni teppren tacvaî n Öebbi: "a ssexv ik, amen! Ih, lmâahda n Öebbi, d tidep". A d yini: "ayagi, siwa tiêkayin imezwura".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 18, 'D wigi i$ef iûaô wawal iaânan leoyus n leonun akked yimdanen, i ten id izwaren. Ih, nitni d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 19, 'I akw tiseddarin n wayen xedmen, iwakken ad yili warraz igiten nnsen. Nitni ur pwadensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 20, 'Ass ideg ara kecmen ar tmes, wid ijehlen: "tvegâam tiéidanin i s tezham, di tmeddurt nnwen di ddunit. Assa, a ppeppuqeîîim s uâaqeb isdullun, imi tessem$waôem iman nnwen di tmurt, ur teklalem; imi tellam tbe$wlem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 21, 'Mmekti d agmat n Âad, mi indeô agdud is deg igidan, u, s tidep, âaddan d ineddaôen zdat es, u zdeffir es: "siwa Öebbi ara tâabdem. Nek ugade$, fellawen, aâaqeb n wass abarar".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 22, 'Nnan d: "day a$ d tusiv, ad a$ tfaôqev akked iôebbiten nne$? Awi a$ d ayen i$ef la $ tessagwadev, ma tessawalev tidep"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 23, 'Inna: "tamusni ar Öebbi kan. Ssawve$ awen ayen i$ef id ppuceggâa$. Maca, wala$ kwen d agdud ur nessin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 24, 'Mi t walan d asigna id ileêêun ar t$wezza nnsen, nnan: "wagi d asigna ar a$ d iawin ageffur". Xaîi! D ayen i$ef têarem, d avu, degs aâaqeb aqeôêan;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 25, 'ad isqucc yal cci, s lameô n Mass is. Gwran d ur tepwaliv siwa ixxamen nnsen. Akka i Nepqeîîi igduden ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 26, 'Ni$ Nessakrer asen ayen ur awen Nessakrer. Nefka yasen imeééu$en, allen, akked wulawen. Ula i sen d bbwin deg wacemma imeééu$en, allen, akked wulawen, mi skaddben issekniyen n Öebbi. Ayen i$ef ttihin, izzi d fellasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 27, 'Ni$ nessenger akw timdinin i wen d izzin, u Nenewwel asent issekniyen, amar a d u$alent s abrid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 28, 'Acimi ur ten sellken ara wid rran d iôebbiten iééaéan, war Öebbi? Xaîi! Ooan ten. D ayagi ay d tikerkas nnsen, u d wayen id snulfuyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 29, 'Mi k ed Nebbwi agraw n leonun, ad ssemêessen i Leqwôan; mi s êedôen, nnan: "êesset"! Mi ifukk, u$alen s agdud nnsen d ineddaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 30, 'Nnan: "a yagdud nne$, aql a$ nesla i Tezmamt id irsen, deffir Musa, id itebbten ayen ip id izwaren, i inehhun ar tidep akked ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 31, 'A yagdud nne$, erret awal i uberraê n Öebbi, amnet yiS, ad awen Isemmeê seg ibekkaven nnwen, a kwen Isellek seg uâaqeb aqeôêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 32, 'Win isâaweégen i uberraê n Öebbi, ur ipsellik di tmurt, ur ippaf imawlan, war Neppa. Widak di ttelfan n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 33, 'Day ur walan ara ar Öebbi d Win Ixelqen tamurt akked igenwan, ur Ifcil seg uxlaq nnsen? Izmer a d Issider lmeggtin. Ih, Neppa Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 34, 'Ass ideg ara d rsen, ar tmes, wid ijehlen: "maççi s tidep ayagi"? A d inin: "ih, s Mass nne$"! A d Yini: "jeôôbet aâaqeb $ef wayen la tnekôem"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 35, 'Eûbeô akken ûebôen wid iôeûmen seg imazanen. I nitni, ur p$awal. Ass ideg ara walin acu i sen ippuwaââden, amzun ur kminen siwa saâa n wass. D aberreê: "anwa ara ipwakksen, siwa agdud icemten"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 1, 'Wid ijehlen, u ssefôa$en abrid n Öebbi, Itlef igiten nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 2, 'Wid iumnen, ixeddmen ayen ilhan, umnen s wayen id irsen ar Muêemmed, u neppa d tidep s$uô Mass nnsen; Issemsa yasen tucmitin nnsen, Iûeggem asen lêala nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 3, 'Ayagi, acku wid ijehlen îîafaôen tikerkas; ma d wid iumnen, îîafaôen tidep n Mass nnsen. Akka id Ippak Öebbi imedyaten nnsen i imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 4, 'Mara d temlilem akked wid ijehlen, ewwtet ar tmegrav ar ten t$elbem. Arzet pen nezzeh. Sinna, d aserreê ne$ d feddu, alamma isers îôad tiâekkwmin is. Akka, lemmer i S ihwi i Öebbi, yili I$leb iten, maca a kwen Ijeôôeb, kra s kra. Wid ipwan$an deg ubrid n Öebbi, ur pôuêun igiten nnsen, d awez$i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 5, 'A ten Inhu, ad Iûeggem lêala nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 6, 'A ten Issekcem di Loennet i sen Imla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 7, 'A wid iumnen! Ma tefkam afus i Öebbi, ad awen Ifk afus, ad awen itebbet isurifen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 8, 'Wid ijehlen, ay amxix nnsen, ad weddôen igiten nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 9, 'Ayagi, acku ugwin ayen id Issers Öebbi; ihi, Imêa igiten nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 10, 'Aâni ur nudan ara tamurt, ad walin amek tevôa d imezwura nnsen? Issexv iten Öebbi. Am akka i ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 11, 'Ayagi, acku Öebbi d bab n wid iumnen. Ijehliyen, ur asen illi bab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 12, 'Ih, Öebbi ad Issekcem wid iumnen, ixeddmen ayen ilhan, di leonanat, ddawat sen isaffen ppazzalen. Wid ijehlen zehhun, teppen akken itepp lmal. D times ay d leqôaô nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 13, 'Acêal n at temdinin i yifen, di tezmert, tamdint i k id iéâan! Nesqucc iten, ur asen illi useîîaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 14, 'Day win illan ar ubeggen n Mass is, am win, iwumi ppucebbêen yir igiten is, u iîîafaôen chawi nnsen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 15, 'Amek tga Loennet i ippuwaââden i wid ipêezziben: degs isaffen n waman ur nxeppeô, isaffen n yi$i ur tfessed lbenna s, isaffen n ccôab aéidan i wid itessen, isaffen n tament ippuneqqan. Degs, i nitni, yal ppemôa, akked ssmaê n Mass nnsen. Day am wid iwekkôen di tmes; sswan ten s waman ippayzagen, ara icergen afwad nnsen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 16, 'Llan garasen wid i k issemêasen. Sifat ff$en d s$uôek, ad inin i wid iwumi teppunefk tmusni: "d acu id inna kan, llinna"? Wigi d wid iwumi Isle$ Öebbi ulawen, teddun kan d chawi nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 17, 'Wid ipwanhan, Irna asen nnhaya, Ifka yasen aêezzeb nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 18, 'Day la pôaoun kan imir, a ten id ias, deqzalla? Ni$ usant ed licaôat is. Ma iusa d $uôsen, iwumi t usmekti nnsen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 19, 'Cfu ar, s tidep, ur illi ôebbi siwa Öebbi; ssuter ssmaê ubekkav ik, akked wid n lmumnin, argaz tameîîut. Öebbi Iéôa anda têebkem, akked wanda tberrkem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 20, 'La qqaôen wid iumnen: "a lemmer a d ters tsuôep"! Maca, mi d ters tsuôep tuêkimt, ideg id ipwader umennu$, a pwaliv at wul iblan, la k id pmuqulen s tiî n win tessexcawat tmeppant. Yif it i nitni', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 21, 'wannuz, akked wawal uwqim. Mi ipwagzem ôôay, ma ssawlen tidep ar Öebbi yif it i nitni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 22, 'Day maççi, ma twexxôem, ahat a ppesfesdem tamurt, a pfaôqem alag nnwen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 23, 'Wigi d wid i Ixza Öebbi; Isgugem iten, Isder$el iéôi nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 24, 'Day ur pmeyyizen ara Leqwôan, ne$ u$alent tsergal $ef wulawen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 25, 'Ih, wid ixedâan, deffir ubeggen n nnhaya $uôsen, ikellex iten Cciîan. Iooa ten tallit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 26, 'Ayagi, acku nitni nnan i wid iugin ayen d Issader Öebbi: "ad awen na$ awal di kra n lumuô". Öebbi Iéôa lesrar nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 27, 'Amek ihi, ma ddment lmalayek leôwaê nnsen, la ten kkatent ar udmawen nnsen, iârar nnsen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 28, 'Akka, ihi, ddan akked wayen isserfayen Öebbi. Ugin llza S. D$a Isseôxes igiten nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 29, 'Ne$ $ilen at wul amehzul, ard awez$i, ur d Issuffu$ ara Öebbi leb$wev nnsen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 30, 'Lemmer i £ ihwi, ad ak ten id Nessken, war ccekk, a ten tâaqlev ar udem nnsen, a ten tâaqlev ar ûûenf umeslay. Öebbi Issen igiten nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 31, 'S tidep, a kwen Njeôôeb, alamma Nessen imjuhad, akked iûebôiyen, segwen. A Njeôôeb isallen nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 32, 'Ih, wid ijehlen, issefôa$en abrid n Öebbi, i inuqmen Amazan, deffir ubeggen n nnhaya $uôsen, ur vuôôen Öebbi s wacemma. Ad Isseôxes igiten nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 33, 'A wid iumnen! A$et awal i Öebbi, a$et awal i Umazan, ur ssiôxiset igiten nnwen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 34, 'Ih, wid ijehlen, issefôa$en abrid n Öebbi, sinna, mmuten d ijehliyen, war ccekk, ur sen Ipsemmiê Öebbi, d awez$i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 35, 'Ur ppiôhifet, ur ssuturet tifrat, mara tilim d ine$laben! U Öebbi yidwen, ur kwen Ipêewwio, d awez$i, seg igiten nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 36, 'Tameddurt di ddunit, d urar kan, akked lhawiyya. Ma tumnem u têezbem, ad awen d Ifk arrazen nnwen. Ur awen issutur ayla nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 37, 'Ma Issuter awen t, a kwen Icebbwel, a pcuêêem, a d iffe$ leb$wev nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 38, 'D kunwi i ipwanecden a pseddqem deg ubrid n Öebbi. Llan degwen wid ipcuêêun. Win ipcuêêun, ipcuêêu kan $ef yiman is. Öebbi d Asâay, kunwi d igellilen. Ma twexxôem, a kwen Ineûûef s ugdud ur nelli segwen. D$a ur ppemcabin $uôwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 1, 'Ih, Nefya yak l$elb iberrzen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 2, 'iwakken ad Isemmeê Öebbi ibekkaven ik id izwaren akked wid igwran. Ad ak Itim l$it iS, a k Iawi d ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 3, 'A k Iall Öebbi tallalt tuzmirt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 4, 'D Neppa id Issersen talwit deg ulawen n lmumnin, iwakken ad yim$uô liman nnsen. N Öebbi Iâsekôiwen n tmurt akked igenwan. Öebbi Izga Iééeô, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 5, 'Iwakken ad Issekcem wid akked tid iumnen, ar leonanat, ddawat sen isaffen ppazzalen, degsen ad wekkôen. Ad asen Issemsu tucmitin nnsen. D wagi, ar Öebbi, ay d rrbeê abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 6, 'Ad Iâaqeb ixabiten, tixabitin, imcurak, timcurak, wid id ipfekkiôen Öebbi yir afekkeô. Izzi yasen ddens. Irfa Öebbi fellasen, Ixza ten. Ihegga yasen d Loahennama. A tu$alin tucmip!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 7, 'N Öebbi iâsekôiwen n tmurt akked igenwan. Öebbi Izga d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 8, 'Ih, Nuzen ik id d anagi, d abcir, d aneddaô,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 9, 'iwakken a ppamnem s Öebbi akked Umazan iS, a T kfum, ad aS tanzem, a T tesbuccuâem taûebêit, tameddit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 10, 'Wid iâaqden yidek âaqden kan d Öebbi. Afus n Öebbi nnig ufus nnsen. Win iêenten, d imanis kan i isseênet. Win iîîfen deg wayen i$ef iâuhed Öebbi, ad as Ifk arraz abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 11, 'Ad ak inin wid igwran, seg uâôaben n ucluê: "i $ ice$wlen, d ayla nne$ akked twaculin nne$. Ssuter a neppusemmeê". Qqaôen s yilsawen nnsen, ayen ur nelli deg ulawen nnsen. Ini: "anwa ara kwen iselken si Öebbi, s wacemma, ma Ib$a yawen vveôô, ne$ ma Ib$a yawen aba$uô? Xaîi, Izga Öebbi Ippuxebbeô af wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 12, 'Xaîi, t$ilem Amazan akked lmumnin ur d ppu$alen ara, d awez$i, ar twaculin nnsen. Ayagi, issefôeê ulawen nnwen. Nnwaya nnwen dir ip. Kunwi d agdud imsenger.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 13, 'Wid ur numin s Öebbi, akked Umazan iS, ihi, aql a£ Nhegga d ajajiê i ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 14, 'N Öebbi, tagelda n tmurt akked igenwan. Ipsemmiê i win i S ihwan, Ipâuqub win i S ihwan. Öebbi Izga Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 15, 'A d inin wid igwran: "ma tôuêem a d t$eltem, ooet a$ a neddu yidwen". B$an ad bedlen awalen n Öebbi. Ini: "ur teppeddum yidne$, d awez$i. Akka ay d izwar wawal n Öebbi". A d inin: "teêsedm a$"! Xaîi, cwiî kan ay fehhmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 16, 'Ini i wid igwran, seg uâôaben n ucluê: "a ppepwanecdem s agdud amaâwaôu, uqsiê; a t tenna$em, ne$ ad anzen. Ma tu$em awal, ad awen Ifk Öebbi arraz igerzen. Ma twexxôem, akken twexxôem uqbel, a kwen Iâaqeb s lqeôê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 17, 'Ur telli tiyta deg uder$al, ne$ deg urejdal, ne$ deg umuvin. Win iunzen i Öebbi akked Umazan iS, a t Issekcem di leonanat, ddawat sen isaffen ppazzalen. Win iwexxôen, a t Iâaqeb s lqeôê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 18, 'Ni$ Iôuva Öebbi lmumnin, mi âaqden yidek, seddaw ttejôa. Iéôa i illan deg ulawen nnsen, Issers d fellasen talwit, I$na ten s l$elb aqôib,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 19, 'akked waîas n lerbaê, ara îîfen. Öebbi Izga d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 20, 'Iwaââed awen Öebbi a d teîîfem lerbaê aîas. I$awel awen d deg waya. Ikkes fellawen afus n medden. Akken ad yili ussekni i lmumnin, a kwen iawi d ubrid uwqim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 21, 'Tayev, iwumi ur tezmirem, ihi, Izzi as Öebbi. Öebbi Izga Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 22, 'Lemmer i kwen nnu$en wid ijehlen, ad rewlen, sinna, ur ppafen bab, ne$ asettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 23, 'D tannumi n Öebbi i illan si zik. Ur teppafev abeddel, d awez$i, di tannumi n Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 24, 'D Neppa i Ikksen afus nnsen segwen, akked ufus nnwen segsen, di te$zut n Mekka, siwev Iss$elb ikwen fellasen. Öebbi Izga Ipwali ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 25, 'D nitni i ijehlen. Swexxôen kwen si Loamaâ n Lêaôam, ugin ad iawev usfel s amkan is. Lemmer maççi d lmumnin, argaz tameîîut, ur ten tessinem, a ten têazem ur teéôim; segsen a d tegwrim di le$ôuô - ni$ Öebbi Issekcam s aêunu S, win i S ihwan - lemmer mfaôaqen, yili, war ccekk, Nesâadda, $ef wid segsen ijehlen, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 26, 'Mi rran wid ijehlen, aêernun deg ulawen nnsen, aêernun n war tussna, Issers ed Öebbi talwit iS af Umazan iS, akked lmumnin. Iqqen asen awal uêezzeb. Iwata ten, klalen t. Öebbi Izga Iéôa yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 27, 'Ni$ Issawev Öebbi, i Umazan iS, tamu$li s tidep: war ccekk, a pkecmem Loamaâ n Lêaôam, ma Irad Öebbi, di laman, iqweôôa nnwen ûûeîlen u qeôcen, ur teppagwadem. Iéôa ayen ur teéôim. Ihegga yawen d, ugwar aya, l$elb aqôib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 28, 'Neppa id Iuznen Amazan iS s nnhaya, akked ddin n tidep, iwakken a t Issifrer $ef ddin meôôa. Iqadd Öebbi d Anagi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 29, 'Muêemmed d Amazan n Öebbi. Wid illan yides, qesêen ar ijehliyen, êninit garasen. A ten twaliv îîinizen, kennun, ssuturen lfevl s$uô Öebbi akked llza. Ccama nnsen, deg udmawen nnsen, d lateô n lekni. Ata wayen i ten icban di Tuôa akked wayen i ten icban di Linoil: am uâaqqa, iger ed im$i s, isoehd it. Ad iuzur, ad iâaooeô $ef yile$ is. Ippaâoab ifellaêen; i$webben yissen ijehliyen. Iwaââed Öebbi ssmaê akked warraz abarar, i wid degsen iumnen, ixeddmen ayen ilhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 1, 'A wid iumnen! Ur zeggwiret zdat Öebbi akked Umazan iS. Ëezzbet i Öebbi. Öebbi, s tidep, Issel, d Amusnaw.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 2, 'A wid iumnen! Ur zzuhriyet tu$ac nnwen, sennig ta$wect n Nnbi. Ur zaââvet $uôes, akken tepzaââvam garawen, mulac ad mêun igiten nnwen, kunwi ur tfaqem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 3, 'Ih, wid issrusun ûut n ta$wect nnsen, ar Umazan n Öebbi, d wid iwumi Issefsi Öebbi ulawen nnsen, ar uêezzeb. Ad asen ippunefk ssmaê akked warraz abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 4, 'Ih, tegwti n wid ik n issawlen, deffir texxamin, ur pmeyyizen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 5, 'Lemmer ûbiôen ard teff$ev $uôsen, ppif i nitni. Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 6, 'A wid iumnen! Aballa$ ma ibbwi yawen d asali, ppuêeqqeqet, mulac a pvuôôem agdud, war tamusni, a ppu$alem tnedmem deg wayen txedmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 7, 'Cfut illa garawen Umazan n Öebbi. Ma issemêes awen deg waîas n lumuô, a pjafem. Maca, Öebbi Issaâzez awen liman, Imelleê it deg ulawen nnwen, Isseôéeg awen tijehli, dd$el, lmaâûegga. Widak d wid ipwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 8, 'D lfevl s$uô Öebbi, d l$it. Öebbi Iéôa, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 9, 'Ma nnu$ent snat n îayfat n lmumnin, êuddet pent. Ma tebw$ev yiwet degsent, $ef tayev, nna$et tin ibwe$ven alamma tevfeô lameô n Öebbi. Ma tevfeô it, ssemûalêet pent, s lmizan. Wezznet. Öebbi Iêemmel wid iwezznen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 10, 'Lmumnin d atmaten kan i illan. Ssemûalêet atmaten nnwen, êezzbet i Öebbi, amar fellawen aêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 11, 'A wid iumnen! £uôwat ad imaâlek ugdud $ef wayev, ahat d widen i ten yifen. Ne$ tilawin $ef tiyav, ahat d tiden i tent yifen. Ur pqeôôidet iman nnwen, ur pmirgamet s tselleqwbin. Dir it isem n dd$el, anda illa liman. Wid ur nutub ara, d widak ay d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 12, 'A wid iumnen! Janbet aîas n nnwaya. Ih, nnwaya, tikwal, d abekkav. Ur ppemâassat ara. Ur kkatet wa deg wa. Day ib$u yiwen, degwen, ad içç aksum n gmas lmegget? A t tagwim. Ëezzbet i Öebbi. Ih, Öebbi Issuruf, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 13, 'A yimdanen! Ni$ Nxelq ikwen si ddker akked nnta. Nerra kwen d igduden, d laâôac, a ppemyussanem. Ihi, ukyis nnwen amxallef, ar Öebbi, d win degwen ipêezziben sennig wiyav. Ih, Öebbi Iéôa, Ippuxebbeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 14, 'Nnan uâôaben n ucluê: "numen". Ini: "ur tuminem". Maca init ed: "nunez"; ur ikcim ara liman ar wulawen nnwen. Ma tôuvam Öebbi akked Umazan iS, ur awen Isôuêu acemma seg igiten nnwen. Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 15, 'Lmumnin d wid kan iumnen s Öebbi akked Umazan iS, d$a, ur pcukun. Pna$en s wayla nnsen akked yiman nnsen, deg ubrid n Öebbi. D widak ay d imawlan n tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 16, 'Ini: "day ad aS temlem i Öebbi, ddin nnwen"? Öebbi Iéôa i illan deg igenwan, i illan di tmurt. Öebbi Issen yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 17, 'Rran ak annuz nnsen, d tajmilt. Ini: "ur iyi telli tejmilt deg annuz nnwen. Xaîi, d Öebbi ikwen I$aten mi kwen Inha ar liman, ma d imawlan n tidep ay tellam".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 18, 'Ih, Öebbi Issen tabavnit n tmurt akked igenwan. Öebbi Ipwali ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 1, 'Q. S Leqwôan, mucaâ!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 2, 'Xaîi! Wehmen mi ten id iusa uneddaô, segsen. Nnan ijehliyen: "ayagi d lwehma!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 3, 'Ma nemmut, nu$al d akal, ayagi d tu$alin si mbâid"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 4, 'Ni$ Neéôa acêal, segsen, i issenqes wakal. £uône£ Tazmamt iêerrzen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 5, 'Xaîi! Nekôen tidep, mi ten id tusa, d$a terwi lêala nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 6, 'Day ur muqlen ara igenni, sennig sen, amek i t Nebna? Ncebbeê it, ur isâi i$isan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 7, 'Tamurt, Nvelq ip, Nerra degs idurar, Nessem$i d degs tayuga n yal ûûenf amxallef,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 8, 'i tmu$li akked usmekti n yal amdan isteôoiâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 9, 'Nesse$li d seg igenni aman iôqan. Nessem$i d yissen leonanat akked uâqqa n tmegra,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 10, 'akked tezdayin ti$wezfanin, s ijeooigen mbabben,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 11, 'd ôôeéq i imdanen. Nessider d yissen tamurt immuten. Akka tanekra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 12, 'Inkeô, uqbel nnsen, ugdud n Nuê, At Rrass, Tamud,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 13, 'Âad, Ferâun, atmaten n Luî,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 14, 'At Laika, akked ugdud n Tubbaâ. Nekôen akw imazanen. Iûaô ussigwed iW.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 15, 'Day £ issefcel uxlaq amezwaru? Wanag nitni di ccekk $ef uxlaq amaynut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 16, 'Ni$ Nxelq ed amdan. Neéôa s wacu i t t$ewwu, teôwiêt is. Neqôeb $uôes, sennig iéuôan n temgaôt is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 17, 'Mara îîfen wid ippaîîafen; qqimen, wa $eô yeffus, wa $eô zelmev,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 18, 'ur d iqqaô awal, siwa ma illa $uôes, uâssas imêelles.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 19, 'Iusa d ddux n tmeppant, ibbwi d tidep: "atan wayen iseg la treggwlev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 20, 'Aûuvu di lbuq. D wagi ay d ass n ussigwed.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 21, 'Yal iman a d ias s unehhaô, akked unagi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 22, 'Ni$ telliv testehzav $ef waya. Nekkes ak taduli k. Iéôi k, assa, d uzzal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 23, 'Ad yini umsaâef is: "ata $uôi wayen id ippuheggan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 24, 'Veggôet, ar Loahennama, yal ajehli amâaûi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 25, 'i iugwin lxiô, amjuô, imcebbwel,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 26, 'i irran ar tama n Öebbi, ôebbi nniven. Ihi, veggôet ep s aâaqeb uqsiê!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 27, 'A d yini umsaâef is: "a Mass nne$! Ur t rri$ d amjuô, d neppa i illan di ttelfan u$miq".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 28, 'Inna: "ur ppemnamaret ara $uôI, imi wen d Zzewre$ aâggen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 29, 'Ur ipbeddil $uôI wawal. Nek, ur Ïîuôôu$ imdanen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 30, 'Ass ideg ara Nini i Loahennama: "ma teççuôev"? A d tini: "ma tella tmerna"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 31, 'Tqeôb ed Loennet, ar wid ipêezziben, ur tebâad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 32, '"D tagi i wen ippuwaââden; i yal atubi iêerzen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 33, 'ippagwaden Aênin di tbavnit, iteddun s wul ucâif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 34, 'Ekcemt ep, di tifrat, d wagi ay d ass uwekkeô"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 35, 'Nnsen, dinna, ayen i sen ihwan; s$uône£, timerna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 36, 'Acêal isuta ay Nesqucc uqbel nnsen! Llan $elben ten di loehd. Qelben, di tmurt, anda t ssôan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 37, 'Deg waya, s tidep, asmekti i win isâan ul, ne$ ifkan tameééu$t, u d anagi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 38, 'Ni$ Nxelq ed tamurt, igenwan, akked wayen illan garasen, di sdis wussan, ur Naâyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 39, 'Eûbeô i wayen d qqaôen, sbuccaâ s ccekôan Mass ik, uqbel ad inqeô yiîij, uqbel ad i$li.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 40, 'Deg iv sbuccaâ iT, akked deffir lekni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 41, 'Ssemêes, ass ideg ara d iberreê uberraê, si tama iqeôben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 42, 'Ass ideg ara slen i usu$u, s tidep, ass nni, d ass n tuff$a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 43, 'Ih, Nekwni Nessidir u Nneqq. £uône£ tu$alin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 44, 'Ass ideg ara tceqqeq tmurt $uôsen s tazla. Afesser agi d ayen isehlen fellane£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 45, 'Nekwni Nif akw akken Neéôa acu id qqaôen. Ur telliv fellasen d aqehhaô. Mmekti d, s Leqwôan, wid ippagwaden aâggen iW.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 1, 'S wavu iwezzâen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 2, 'I ibubben taâkkwemt!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 3, 'Wid ippazalen s shala!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 4, 'Tid ifeôqen lameô!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 5, 'Ar ayen i wen ippuâahden, d tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 6, 'Aqeîîi, ih, ad iûaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 7, 'S igenni bu idurra!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 8, 'Kunwi temgarradem $ef wawal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 9, 'Iooa t win iooan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 10, 'Tameppant i ikeddaben!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 11, 'Nitni, di maylellif, stehzan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 12, 'steqsayen: "anda t wass uqeîîi"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 13, 'Ass ideg, ara ppuhewlen di tmes:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 14, '"Jeôôbet ahewwel nnwen agi i$ef têarem"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 15, 'Ih, wid ipêezziben, di leonanat akked tliwa;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 16, 'Ïîfen ayen i sen Ifka Mass nnsen. Ih, nitni llan, iu$ lêal, d lâuûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 17, 'Deg iv, cwiî ay gganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 18, 'Di tafrara, nitni ste$fiôen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 19, 'deg wayla nnsen: amur i umappar akked ume$bun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 20, 'U di tmurt, issekniyen i wid ipputebbten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 21, 'Llant deg iman nnwen. Aâni ur tepwalim ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 22, 'U deg igenni, ôôeéq nnwen, akked wayen i wen ippuwaââden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 23, 'S Mass n tmurt akked igenwan, ar neppa d tidep, am akken kunwi tepmeslayem!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 24, 'Ma tebbwev ik id tedyant inebgawen ukyisen n Ibôahim?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 25, 'Kecmen $uôes, nnan as: "tifrat"! Inna: "tifrat a wid ur nessin!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 26, 'Inser ar twacult is, ibbwi d aâjmi iqebbwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 27, 'Iqeôb asen t id; inna: "day ur teppeppem ara"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 28, 'Iêus iugad iten. Nnan as: "ur ppagwad"! D$a beccôen t s uqcic amusnaw', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 29, 'Tqeôb ed tmeîîut is, tsu$, tewwet deg udem is, tenna d: "tam$aôt tiâiqeôt?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 30, 'Nnan: "akka id Inna Mass im. Ih, Neppa, d Bab n ûûwab, d Amusnaw".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 31, 'Inna: "anwa ay d awal nnwen, a yimceggâan"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 32, 'Nnan: "nekwni neppuceggaâ d ar ugdud ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 33, 'Iwakken a ten neôoem s uéôu n talaxt', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 34, 'i ipwaôecmen s$uô Mass ik i ucmiten".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 35, 'Nessuffe$ kra illan, degs, n lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 36, 'Nufa kan degs, yiwen uxxam n imvuâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 37, 'Neooa p id d assekni i wid iugaden aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 38, 'I di Musa, mi t id Nuzen i Ferâun, s udabu n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 39, 'Iaâûa, akked imalalen is, inna: "d aseêêar, ne$ d aôehbani".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 40, 'Neddem it, neppa akked iâsekriwen is, Nveggeô iten ar yill. Tiyta degs.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 41, 'I di Âad, mi sen Nuzen avu asexvi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 42, 'Ur ippaooa ayen immuger, alamma irra t am rrmim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 43, 'I Tamud, mi pwanecden: "siwa tallit ara tezhum".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 44, 'Âuûan lameô n Mass nnsen. Tewwet iten id ssiâqa, nitni la pwalin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 45, 'Ur zmiren a d kren, ur pwasellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 46, 'Agdud n Nuê, uqbel, llan, s tidep, d agdud iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 47, 'Igenni, Nebna t s loehd, d Nekwni it Issewsaân.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 48, 'Tamurt, Nessa p. Ay gerzen Wid Itessun!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 49, 'Di yal cci, Nexleq tayuga, ahat a d tesmektim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 50, 'Ihi, srifget ar Öebbi. Nek, ih, s$uôeS ar $uôwen, d aneddaô ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 51, 'Ur sâut, ar tama n Öebbi, ôebbi nniven! Nek, ih, s$uôeS ar $uôwen, d aneddaô ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 52, 'Akka, ur iusi umazan ar wid i ten id izwaren, mebla ma nnan as: "d aseêêar ne$ d aôehbani".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 53, 'Day ppuweûûan $ef waya? Xaîi, nitni d agdud izegren tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 54, 'Ïîixxeô asen; ur deg k tiyta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 55, 'Smektay ed. Asmekti, s tidep, infaâ lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 56, 'Xelqe$ leonun akked imdanen, iwakken kan ad iyI âabden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 57, 'Ur b$i$ segsen ôôeéq, ur b$i$ ad iyi cceççen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 58, 'Öebbi, s tidep, d Aôeééaq, d Bu tezmert n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 59, 'Ih, i wid idensen, amur am umur imeddukwal nnsen. Ulay$eô iyI $eûben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 60, 'A tawa$it n wid ijehlen, ilmend n wass i sen ippuwaââden!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 1, 'S udrar!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 2, 'S Tezmamt ippujerrden', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 3, 'di lka$ev ivelqen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 4, 'S texxamt iâamôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 5, 'S tseddarit aâlayen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 6, 'S yill icebbwlen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 7, 'Aâaqeb n Mass ik, s tidep, ad ivôu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 8, 'Ur isâi ara t sfunngen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 9, 'Ass ideg ara imbwiwel igenni, d ambwiwel,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 10, 'Ad lêun idurar, d tikli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 11, 'A ssexv, assen, n wid iskiddiben!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 12, 'Wid inexôen deg uraren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 13, 'Ass ideg ara pwaveggôen ar tmes n Loahennama, d aveggeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 14, 'Apan tmes nni i la tnekôem!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 15, 'D ssêur waya, ne$ d kunwi ur nwala ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 16, 'Kecmet ep. Iâuva fellawen, tûebôem, ne$ ur teûbiôem. A ppeppuqeîîim kan $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 17, 'Wanag wid ipêezziben, di leonanat, akked zzhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 18, 'Feôêen s wayen i sen Ifka Mass nnsen. Isellek iten, Mass nnsen, seg uâaqeb ujajiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 19, 'àçet, teswem, di lehna, ilmend n wayen txeddmem!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 20, 'èélen af imîeôêen, d idurra; d tiêuôiyin lâin ukud iten Njewweo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 21, 'Wid iumnen, u âanden ten, warraw nnsen, ar liman nnsen, a ten Nessemlil akked warraw nnsen. Ur Nessenqas acemma seg igiten nnsen. Yal amdan ad immager ayen ikseb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 22, 'Ad asen d Nefk izwayen akked uksum seg wayen cedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 23, 'Dinna ad ppemyeppaken lkas, ideg ur illi usîeômel, ne$ ssebba n tuccva.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 24, 'Garasen, ddewiôen ilmeéiyen i nitni, amzun d tiyaqutin mesîuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 25, 'Zzin, kra $er kra, pmesteqsayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 26, 'Nnan d: "ni$ nella, zik, di twacult nne$, nugad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 27, 'I$at a$ Öebbi, Isellek a$ seg ujajiê n tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 28, 'Ni$ nella, zik, nepnuju $uôeS. Neppa, s tidep, d A$eyyat Ipêunun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 29, 'Ihi, ccfu ar keçç, s l$it n Mass ik, ur telliv d agezzan, ne$ d aôehbani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 30, 'Ne$, ad inin: "d amedyaz. A naôou asali s akud".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 31, 'Ini: "gganit! Nek, yidwen, seg wid ipganin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 32, 'Ne$ d tirga nnsen i sen iumôen aya, ne$ nitni d agdud izegren tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 33, 'Ne$ ad inin: "isnulfa t id". Xaîi! Ur uminen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 34, 'Ihi, a d awin ameslay i t icban, ma d tidep ay ssawalen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 35, 'Ne$ pwaxelqen seg ulac, ne$ d nitni ay d ixellaqen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 36, 'Ne$ xelqen tamurt akked igenwan? Xaîi, ur pputebbten!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 37, 'Ne$ $uôsen lexzayen n Mass ik, ne$ nitni d imvebbôen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 38, 'Ne$ sâan sellum ad ssemêessen, segs. Ihi, win islan segsen, a d iawi adabu n ûûeê!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 39, 'Ne$ i Neppa tullas, i kunwi arrac?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 40, 'Ne$ tessutrev asen taqdiât, fellasen d îîlaba ééayen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 41, 'Ne$ $uôsen tabavnit, d$a la pparun?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 42, 'Ne$ b$an ad andin? D wid ijehlen ara ipwaîîfen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 43, 'Ne$ sâan ôebbi, ur Nelli d Öebbi? Gedha s Öebbi, seg wayen pcaraken!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 44, 'Lemmer ad walin amur igenni i$li, ad as inin: "d asigna i izdin".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 45, 'Ihi, eoo iten, ard mlilen d wass n ssiâqa nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 46, 'Ass, ideg ur asen d teppawi acemma, tandit nnsen; ur asen illi usettaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 47, 'I wid idensen, s tidep, aâaqeb nniven, maca tegwti degsen, ur éôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 48, 'Eûbeô i wayen d Iêudd Mass ik, aql ak, s tidep, ger wallen nne£. Sbuccaâ s ccekôan Mass ik, mara d tekkrev.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 49, 'Sbuccaâ iT deg iv, u mara xsin yitran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 1, 'S yitri mara ixeppi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 2, 'Ur innetlaf, ur i$liv umeddakwel nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 3, 'Ur d iqqaô akken i s ihwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 4, 'D aweêêi kan, id ippuweêêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 5, 'Islemd it bab n tezmert iqwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 6, 'D bab n tezmert irs ed', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 7, 'u neppa di lejba aâlayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 8, 'Sinna iqeôb ed, ippucengel,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 9, 'atan tasurift n sin ixtucen, ne$ ur tebbwiv.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 10, 'D$a iweêêa i umdan iS, ayen iweêêa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 11, 'Ur iskaddeb wul deg wayen iwala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 12, 'Day a t tnaqwmem, $ef wayen iwala?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 13, 'Ni$ iéôa t di trusi s nniven,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 14, 'ar tedxwent n talast,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 15, 'u$uô illa leonan usemlili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 16, 'Mi tesbur tedxwent ta$wlaft,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 17, 'ur iwweônenni yiéôi, ur izgir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 18, 'Ni$ iwala kra issekniyen imeqwôaêanen, n Mass is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 19, 'Twalam Allat akked Lâuzza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 20, 'Akked Manat, tis krav nniven?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 21, 'Day i kunwi ddkeô, i Neppa nnta?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 22, 'Wagi, ihi, d beîîu aneêyaf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 23, 'Wigi d ismawen kan i sent tefkam, kunwi akked imezwura nnwen. Ur sent d Issers Öebbi kra udabu. Ïîafaôen kan nnwaya, akked wayen cehwant teôwiêin. Ni$ tusa ten id nnhaya s$uô Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 24, 'Aâni, i umdan, ayen issaram?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 25, 'Tamezwarut akked tneggarut, n Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 26, 'Acêal n lmalayek deg igenwan, ur d teppawi acemma ccafuâa nnsent, siwa deffir tsriê n Öebbi, $ef win Ib$a u Iôuva.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 27, 'Ih, wid ur numin ara di laxeôt, ppaken i lmalayek ismawen n nnta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 28, 'Ur sâin fellas kra n tmusni. Ïîafaôen kan nnwaya. Wanag nnwaya ur tebbwi acemma si tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 29, 'Ihi, eoo win iwexxôen i usmekti nne£, i ib$an kan tudert n ddunit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 30, 'D aya ay sen tefka tmusni. Mass ik, war ccekk, Iéôa sennig akw, anwa innetlafen seg ubrid iS; Iéôa sennig akw, anwa i ipwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 31, 'N Öebbi ayen akw illan deg igenwan, illan di tmurt. Ad Iqeîîi wid ifalîan $ef wayen xedmen, ad Ioazi wid issweqmen, s ûûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 32, 'Wid ijunben ibekkaven ibararen akked tucmitin, siwa lfalîat fessusen, ihi, d uwsiâ ssmaê n Mass ik. Neppa Issen ikwen sennig akw, mi kwen id Ixleq seg wakal, mi tellam d icelleqluqen, deg iâabbav n tyimmatin nnwen. Ur staâmilet tezdeg deg iman nnwen! Neppa Iéôa sennig akw, anwa iêezzben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 33, 'Twalav win iwexxôen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 34, 'i ifkan cwiî, iccuêen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 35, 'Day isâa tamusni n tbavnit, d$a iwala?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 36, 'Ne$ ur ippuxebbeô $ef tewôiqin n Musa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 37, 'Akked Ibôahim ineûêen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 38, 'Ur ipbibbi yiwen taâkkwemt n wayev.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 39, 'I umdan, siwa ayen inki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 40, 'Ankay is a t iwali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 41, 'Sinna, a t Ikafi s lufa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 42, 'Ih, ar Mass ik, taggara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 43, 'D Neppa i Issevûan, i Issruyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 44, 'D Neppa i Ineqqen, i Issidiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 45, 'D Neppa i Ixelqen tayuga, ddkeô akked nnta,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 46, 'Si tiqqit n l$ella ma tuzzel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 47, 'FellaS, axlaq nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 48, 'D Neppa i I$ennun, i Iqenâan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 49, 'D Neppa i d Mass n Ciâra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 50, 'D Neppa i Isnegren Âad imezwura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 51, 'Si Tamud, ur d Iooi ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 52, 'Agdud n Nuê, uqbel nnsen, war ccekk, iugar iten ddens, lbbwe$v.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 53, 'Issenger tid inneqlaben;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 54, 'Idel iten s wayen idellen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 55, 'Anta talalt n Mass ik ara tnamerev?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 56, 'Wagi d aneddaô seg ineddaôen n zik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 57, 'A d taéé tin d ippaééen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 58, 'War Öebbi, ur illi ara p id issdehôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 59, 'Iswehm ikwen wawal a?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 60, 'La tdessem ur la tepprum!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 61, 'Kunwi di zzhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 62, 'Knut i Öebbi, âabdet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 1, 'Iqeôb ed yimir; ifelleq waggur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 2, 'Ma walan assekni, ad wexxôen, ad inin: "ipkemmil ssêur"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 3, 'Nekôen, îîafaôen lemcihwat nnsen. Ad iûaô yal lameô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 4, 'Ni$ usan ten id kra isallen, u wayen degsen iswexxiôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 5, 'Üûwab issakwayen. Maca ula iwumi aâaggen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 6, 'Ihi, îîixxeô asen! Asmi ara d isiwel, uberraê, ar wayen iwaâôen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 7, 's wallen ibran, ara d ff$en si tneîlin, am ujôad iwezzâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 8, 'Ad éedmen, âaooôen, ar uberraê, ad inin ijehliyen: "wagi d ass uwâiô".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 9, 'Agdud n Nuê, uqbel nnsen, iskaddeb. Skaddben amdan nne$. Nnan: "d aôehbani". Rran t id.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 10, 'Inuj ar Mass is: "nek pwa$elbe$, Awes"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 11, 'Nelli tibbura igenni, i waman d ihedman,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 12, 'Nesgguffaâ d laânaûeô n tmurt, mlalen waman akken ipwagzem lameô;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 13, 'Nebbwi t af tencirin, akked tavuî n tiffest.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 14, 'Teppeddu zdat wallen nne£, d arraz i win ipwanekôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 15, 'Ni$ Neooa p id d assekni. Day llan wid id ismektayen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 16, 'Amek illa uqeîîi W u llant licaôat iW!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 17, 'Ni$ Nsehhel Leqwôan i usmekti. Day llan wid id ismektayen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 18, 'Âad skaddben. Amek illa uqeîîi W u llant licaôat iW!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 19, 'Ih, Nuzen asen aûeôûaô, ass amekêus, imezgi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 20, 'Ippawi medden amzun d iqeôôumen n tezdayin ipwaqelâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 21, 'Amek illa uqeîîi W u llant licaôat iW!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 22, 'Nsehhel Leqwôan i usmekti. Day llan wid id ismektayen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 23, 'Tamud skaddben aâeggen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 24, 'Nnan: "day a neddu d yiwen n umdan segne$? Ihi, nekwni, war ccekk, di ttelfan, akked tisselbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 25, 'Day d neppa, garane$, u$uô id iusa uneddeô? Wanag neppa, d akeddab uqbiê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 26, 'Ad walin azekka, anwa ay d akeddab uqbiê!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 27, 'A Nazen, ih, tal$wemt i ujeôôeb nnsen. Qaôaâ ten, ili k d aûebôi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 28, 'Xebbeô iten ar aman ad pwafeôqen. Mkul tissit s tidwelt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 29, 'Ssawlen i umeddakwel nnsen. Iusa d, igezm as ivaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 30, 'Amek illa uqeîîi W u llant licaôat iW!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 31, 'Nuzen asen d, s tidep, yiwen usu$u. U$alen am alim di tbergent.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 32, 'Nsehhel Leqwôan i usmekti. Day llan wid id ismektayen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 33, 'Agdud n Luî skaddben aâeggen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 34, 'Ihi, Nuzen asen ajebwani, kkes ed tawacult n Luî, i Nsellek qbel tafara,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 35, 'd l$it s$uône£. Akka ay Nepkafi wid isnemmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 36, 'Ni$ iâaggen asen, Newâaô. Rran aâeggen di ccekk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 37, 'Ni$ ssutren t $ef inebgawen is. Nesder$el allen nnsen: "jeôôbet aâaqeb iW, akked uâaggen iW".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 38, 'Iusa ten id, ssbeê zik, uâaqeb imezgi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 39, 'Jeôôbet aâaqeb iW, akked uâeggen iW!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 40, 'Nsehhel Leqwôan i usmekti. Day llan wid id ismektayen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 41, 'Ni$ iusa n uâeggen ar twacult n Ferâun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 42, 'Skaddben issekniyen nne£, meôôa. Naâtad iten s ufus ioehden, izemren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 43, 'Aâni ijehliyen nnwen ifen wigi? Ne$ tesâam laânaya deg Ihellilen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 44, 'Ne$ a d inin: "nekwni d agraw ara irebêen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 45, 'Agraw ad ixseô, ad wexxôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 46, 'Ih, imir d ppaâud nnsen. Imir d lhejna, u ôéag kteô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 47, 'Ih, ibe$wdiyen di ttelfan akked tisselbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 48, 'Asmi ara kkerkren ar tmes, $ef udmawen nnsen: "jeôôbet tanalit ujajiê"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 49, 'Ih, yal cci, Nxelq it s lmizan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 50, 'Lameô nne£ siwa yiwen, am unqej n tiî.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 51, 'Ni$ Nesqucc wid i kwen icban. Day llan wid ara d ismektin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 52, 'Yal igi nnsen deg Ihellilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 53, 'Akw, meééi meqqweô, ppujerrden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 54, 'Wid ipêezziben, s tidep, di leonanat akked isaffen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 55, 'deg umekkan n tidep, ar Ugellid Uzmir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 1, 'Aênin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 2, 'Isseêfev Leqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 3, 'Ixleq amdan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 4, 'Isselmed as ôôkuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 5, 'Iîij akked waggur, s leêsab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 6, 'Itran akked ttjuô, knan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 7, 'Igenni, Issuli t; Issers ed lmizan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 8, 'Ur xedâat di lmizan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 9, 'Weznet s tidep, ur ssexsaôet lmizan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 10, 'Issewsaâ tamurt i imexlaq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 11, 'Degs izwayen, tizdayin sut tkummiwin;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 12, 'iâqqayen s usa$uô, iferrawen utebtil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 13, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 14, 'Ixleq amdan si talaxt, am ujeqduô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 15, 'Ixleq loenn seg ujajiê n tmessi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 16, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 17, 'Mass n sin igmav, Mass n sin ituram.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 18, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 19, 'Iooa sin ilellen ad mqaôaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 20, 'Garasen agadir, ur zegren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 21, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 22, 'Teff$ent ed, segsen, tyuqat akked lmeôoan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 23, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 24, 'IneS lembwabeô pwabnan di yill, am idurar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 25, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 26, 'Ad ifut degs kra illan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 27, 'A d igwri udem n Mass ik, Bab n ccan akked cciâa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 28, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 29, 'Teppren T, yal ass, kra illan di tmurt akked igenwan, Neppa la Ixelleq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 30, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 31, 'A d Nelhi yidwen, a sin iéayanen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 32, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 33, 'A yagraw n leonun akked imdanen, ma tzemrem a pzegrem akin i tmurt akked igenwan, zegret! Ur tepzeggirem siwa ma s udabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 34, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 35, 'A d teppewwtem s ijujaê n tmes akked nnêas. Ur tepsellikem iman nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 36, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 37, 'Ma ifelleq igenni, iu$al d azeggwa$ am u$eggwad,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 38, '- Anwa seg i$iten n Mass nnwen ara teskiddben, i sin? -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 39, 'assen, amdan ne$ loenn, ur fellas asteqsi $ef ubekkav is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 40, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 41, 'Ibe$wviyen, a d banen ar ccwami nnsen. Ad pwaîîfen seg icebbuben akked ivaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 42, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 43, 'D tagi ay d Loahennama i skaddben ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 44, 'Ad ddewwiôen garas akked wayen ippayzagen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 45, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 46, 'I win iugaden ibeddi zdat Mass is, sin leonanat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 47, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 48, 'S tzegzew, d imselîen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 49, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 50, 'Degs sin i$bula pfeggiven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 51, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 52, 'Degs yal izwayen, d tiyugiwin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 53, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 54, 'èélen af imîeôêen ippuêewcen; izwayen n sin leonanat wâan asen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 55, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 56, 'Dinna, sut usekkud ipsetêin, ur tent innul yiwen, uqbel nnsen, d loenn ne$ d amdan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 57, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 58, 'Amzun nitenti d lyaqut akked lmeôoan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 59, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 60, 'Nni$ arraz n wayen ilhan, d ayen ilhan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 61, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 62, 'Sin leonanat nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 63, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 64, 'S tzegzewt isemmxen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 65, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 66, 'Degsen snat n tliwa gguffant.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 67, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 68, 'Degsen izwayen, tizdayin, ôemman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 69, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 70, 'Degsen tiferni akked ûûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 71, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 72, 'Tiêuôiyin ized$en di texxamin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 73, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 74, 'Ur tent innul yiwen, uqbel nnsen, d loenn ne$ d amdan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 75, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 76, 'Ad élen af imîeôêen izegzawen akked d tôakniwin ilhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 77, 'Anwa seg i$iten n Mass nnwen ara teskiddben, i sin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 78, 'Iôqa ism n Mass ik, Bab n ccan akked cciâa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 1, 'Mara d tas, tin ara d iasen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 2, '$ef tisin is, ur illi ucehrir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 3, 'Tessrusu, treffed.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 4, 'Ma tenhez tmurt, lhezz iqesêen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 5, 'idurar ftutsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 6, 'u$alen d a$ebbaô ippuwezzâen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 7, 'a d tevêum krav leûnaf:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 8, 'at uyeffus. At uyeffus, anwi ten?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 9, 'At uzelmav. At uzelmav, anwi ten?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 10, 'Akked imezwura, imezwura,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 11, 'Widak d iqôiben;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 12, 'di leonanat isaâdiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 13, 'Seg imenza, deg waîas idsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 14, 'Seg ineggura, drus nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 15, '£ef imîeôêen iévan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 16, 'éélen fellasen, mqabalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 17, 'Tezzin asen ilmeéiyen iwekkôen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 18, 's tbuqalin, iqbucen, akked lkas n tissit iûfan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 19, 'Yis, ur ppavnen, ur sekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 20, 'Izwayen, seg wid smenyafen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 21, 'Aksum n yifôax, seg win cedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 22, 'Tiêuôiyin lâin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 23, 'am tyaqutin iffren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 24, 'D arraz n wayen xeddmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 25, 'Ur din sellen awal n leqbaêa, ne$ n tuccva;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 26, 'siwa awal n tifrat, tifrat!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 27, 'At uyeffus, at uyeffus, d acu ten?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 28, 'Ar tzegwart, war isennanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 29, 'Tulmatin iurwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 30, 'Tili iwsâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 31, 'Aman ippazalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 32, 'Aîas n yizwayen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 33, 'ur zegzawit, ur ppugedlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 34, 'Imîeôêen aâlayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 35, 'D Nekwni itent Ixelqen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 36, 'Nerra tent d tiêuôiyin;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 37, 'pêemmilent, d tizyiwin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 38, 'i at uyeffus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 39, 'Seg imenza, deg aîas idsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 40, 'Seg ineggura, deg aîas idsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 41, 'At uzelmav, at uzelmav, d acu ten?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 42, 'Deg wavu, akked waman iô$an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 43, 'Tili n wabbu iô$an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 44, 'Ur degs tasmuvi, lekyasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 45, 'Ih, nitni zik, llan ôwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 46, 'Zgan deg ubekkav abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 47, 'Llan qqaôen: "ma nemmut, nu$al d akal, akked i$san, day a d a$ d rren?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 48, 'Akked imezwura nne$ imenza"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 49, 'Ini: "ih, imezwura akked ineggura,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 50, 'ad ppujemmlen ar temlilit n wass ipwassnen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 51, 'D$a, ih, a yim$eôôqen, i illan d inekkaôen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 52, 'a ppeççem, war ccekk, si ttejôa n Zaqqum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 53, 'A ppacaôem segs ifwaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 54, 'Sinna, a ppernum tissit seg waman iô$an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 55, 'A ppetessem tissit ile$wman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 56, 'D wagi ar asen d irsen, ass uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 57, 'D Nekwni ikwen Ixelqen. Lemmer a ppamnem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 58, 'Twalam l$ella id iteff$en segwen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 59, 'D kunwi ip ixelqen, ne$ d Nekwni ay d ixellaqen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 60, 'Nseyya tameppant garawen. Ur a£ izeggwir yiwen', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 61, 'iwakken a Nerr deg umkan nnwen wid i kwen icban; u kunwi, a kwen Nexleq d ayen ur tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 62, 'Ni$ tesnem axlaq amenzu, lemmer tesmektayem!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 63, 'Twalam ayen tkerrzem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 64, 'D kunwi i t ikerzen, ne$ d Nekwni ay d imekrazen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 65, 'Ma ihwa ya£, a t Nerr d uêvim, d$a a kwen tekkat lwehma:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 66, '"Aql a$ nepwalas!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 67, 'Sennig waya: aql a$ neppuêeôôem"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 68, 'Twalam aman i teppessem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 69, 'D kunwi iten id isse$layen seg usigna, ne$ d Nekwni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 70, 'Ma ihwa ya£, a ten Nerr d imeô$anen. A lemmer tesnemmiren!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 71, 'Twalam times i tesskarem s uêukku?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 72, 'D kunwi i s d ixelqen ttjuô is, ne$ d Nekwni ay d Ixellaqen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 73, 'D Nekwni i p Irran d asmekti, u d lâafia i wid ineêwwaoen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 74, 'Sbuccaâ, s ccekôan, isem n Mass ik, Ameqwôaêan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 75, 'Ih, gulle$ seg wanda llan itran!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 76, 'U, tagi, lemmer a ppeéôem, ard tagallit tameqwôaêant!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 77, 'Ar neppa d Leqwôan ukyis,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 78, 'di Tezmamt iffren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 79, 'Ur t pnalen, siwa wid zeddigen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 80, 'D tarusi s$uô Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 81, 'S usali agi, amendeô ma a ppiéidem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 82, 'S ôôeéq nnwen, kunwi tnekôem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 83, 'Mara d tawev s agerjum,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 84, 'kunwi, imiren, teppaôoum,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 85, 'Nekwni, sennig wen, i Neqôeb $uôes, maca, ur twalam ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 86, 'Xas ma ur tellim d wid ur nepwalas,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 87, 'erret p id, ma tessawalem tidep!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 88, 'Ma illa seg iqôiben,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 89, 'ihi, abeêri, laâîeô, di leonan n ssuâada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 90, 'Ma illa seg iyeffusen:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 91, '"i keçç tifrat, seg iyeffusen"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 92, 'Ma illa seg inekkaôen innetlafen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 93, 'axxam is seg waman ippayzagen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 94, 'ad iô$ deg ujajiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 95, 'Ayagi, ih, d tidep itebbten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 96, 'Sbuccaâ, s ccekôan, isem n Mass ik Ameqwôaêan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 1, 'Sbuccuâen, s ccekôan Öebbi, ayen akw illan di tmurt akked igenwan. Neppa d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 2, 'IneS tagelda n tmurt akked igenwan; Issidir, Ineqq; u Neppa Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 3, 'D Neppa ay d amezwaru, ay d aneggaru; d ayen d ibanen akked wayen iffren. Neppa Iéôa yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 4, 'D Neppa i Ixelqen tamurt akked igenwan di sdis wussan. Sinna, Iâannec af usgeld. Iéôa i ikeççmen ar tmurt, akked wayen id iteff$en segs, ayen id ippadren seg igenni, akked wayen ippalin $uôes. Neppa yidwen, anda ma tellam. Öebbi Ipwali ayen txedmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 5, 'IneS tagelda n tmurt akked igenwan. Ar Öebbi ara u$alen lumuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 6, 'Issekcam iv deg wass, Issekcam ass deg yiv. Iéôa ayen illan deg idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 7, 'Amnet s Öebbi akked Umazan iS! Efket seg wayen i$ef i kwen Irra, degs, d igensas. Wid iumnen segwen, iseddqen, d ameqwôan warraz nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 8, 'Acu ikwen iu$en, ur tuminem ara s Öebbi? Amazan ipnabi kwen a ppamnem s Mass nnwen. Ni$ $uôes nnesba nnwen, ma tellam d lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 9, 'D Neppa id Issadren i umdan iS, issekniyen iberrzen, iwakken a kwen Issuffe$ si tillas ar tafat. Ih, Öebbi, fellawen, d Umâin Ipêunun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 10, 'Acu ikwen iu$en, ur tepseddiqem deg ubrid n Öebbi? N Öebbi lweôt n tmurt akked igenwan. Ur taâdilem ara: wid iseddqen uqbel l$elb, u nnu$en, widak, ad aâlayen, nezzeh, sennig wid iseddqen sin $er da, u nnu$en. Iwaââed asen akw Öebbi ûûam. Öebbi Iéôa ayen txedmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 11, 'Win iôevlen i Öebbi aôeîîal umâin, ad as d Irr s lufa, u ines warraz ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 12, 'Asmi ara twaliv lmumnin, argaz tameîîut, teddun tafat nnsen zdat sen, u yeffus nnsen: "a lxiô nnwen, assa, di leonanat, ddawat sen isaffen ppazzalen, degsen a pwekkôem! D wagi ay d rrbeê ameqwôaêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 13, 'Ass ideg ixabiten, argaz tameîîut, ad inin i wid iumnen: "arout a$, a neddem si tafat nnwen"! A d inin: "u$alet ar deffir, a d tqelbem tafat"! Ad yili garasen lêiv, s tebburt. Zdaxel d aêunu, beôôa, zdat es: aâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 14, 'Ad sen d siwlen: "day ur nella ara yidwen"? Ad inin: "ih! Maca, thewwlem iman nnwen, tekkukram, tcukkem, $elvent kwen lemcihwat, armi d iusa lameô n Öebbi. I$elv ikwen af Öebbi, u$ellav".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 15, 'Assa, ur ipwaîîaf feddu segwen, ne$ seg wid ijehlen. Axxam nnwen d times; d neppat ay d bab nnwen. A tu$alin tucmip!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 16, 'Âani maççi d lawan, i wid iumnen, ad rgagin wulawen nnsen ar usmekti n Öebbi, akked wayen id Issers n tidep? Ur ppilin am wid iwumi teppunefk Tezmamt, zik, u tvul fellasen lmudda. D$a qquôen wulawen nnsen; aîas degsen d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 17, 'Ecfut ar Öebbi Issidir tamurt, deffir tmeppant is. Ni$ Nbeggen awen d issekniyen, amendeô ma a pfehmem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 18, 'Ih, wid akked tid ipseddiqen, iôeîlen i Öebbi aôeîîal umâin, ad asen d Irr s lufa, u nnsen arraz ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 19, 'Wid iumnen s Öebbi akked imazanen iS, d nitni ay d iêeqqiyen, u d inagan ar Mass nnsen. Ad awin arraz nnsen akked tafat nnsen. Wid ijehlen u skaddben issekniyen nne£, widak d at ujajiê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 20, 'Cfut ar tameddurt n ddunit d urar kan, d zzhu, d acebbeê, d zzux garawen, asuget n wayla akked derya. Am umedya ugeffur. Im$an is âaoben ijehliyen; sinna, ad isliwen, a ten twaliv ppiwôi$en; d$a ad êevmen. Di laxeôt, aâaqeb uqsiê akked ssmaê s$uô Öebbi, akked llza. Tameddurt n ddunit d zzehwa kan ip$uôôun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 21, '£iwlet ar ssmaê n Mass nnwen, akked Loennet iwesâan am tmurt akked igenni, teppuhegga d i wid iumnen s Öebbi akked imazanen iS. D wagi ay d lfevl n Öebbi. Ippak it i win i S ihwan. Öebbi d Bab n lfevl ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 22, 'Ur d tveôôu twa$it di tmurt, ne$ deg iman nnwen, siwa ma tura di Tezmamt, uqbel a p id Nawi. Ayagi, s tidep, d ayen isehlen i Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 23, 'Iwakken ur kwen ip$av wayen tzeglem, ur kwen issefôaê wayen i wen Ifka. Öebbi ur Iêemmel ara yal amzuxi, imnefxi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 24, 'wid ipcuêêun, iêeppmen ccêa af medden. Win i iwexxôen…ihi, Öebbi d Asâay, d Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 25, 'Nuzen ed imazanen nne£, s ubeggen. Nessader ed yidsen Tazmamt akked lmizan, iwakken ad ddun imdanen s lêeqq. Nessader ed uzzal, degs vveôô uqsiê, akked uba$uô i medden, iwakken ad Iéeô Öebbi anwa ara ifken afus i Neppa akked imazanen iS, di tbavnit. Ih, Öebbi d Uohid, d Uzmir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 26, 'Ni$ Nuzen ed Nuê akked Ibôahim. Nerra, si tarwa nnsen, Lambiyya, Tira. Degsen llan wid ipwanhan; aîas segsen d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 27, 'Sinna, Nessevfeô ed, deffir sen, imazanen nne$. Nessevfeô ed Âisa, mmi s n Meryem, Nefka yas Linoil. Nessekcem deg ulawen n wid iddan yides leênana akked tiéeî. Taxelwit, ur p Nuri fellasen; snulfan p id i llza n Öebbi. Ur qumen ara yis, akken iwata. Nefka arraz nnsen i wid iumnen segsen. Aîas, segsen, d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 28, 'A wid iumnen! Ëezzbet i Öebbi. Amnet s Umazan iS. Ad awen Ifk sin imuren seg uêunu S, ad awen Irr tafat a ppeddum yis, ad awen Isemmeê. Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 29, 'Akken ad éôen At Tezmamt, ar ur zmiren acemma di lfevl n Öebbi. Ih, lfevl deg ufus n Öebbi; Ippak it i win i S ihwan. Öebbi d Bab n lfevl ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 1, 'Ni$ Isla Öebbi i wawal n tin i k d ihedôen $ef urgaz is. Tepcetkay i Öebbi. Öebbi Isla i umeslay nnwen. Öebbi, s tidep, Isell, Iéeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 2, 'Wid ipmettilen tilawin nnsen ar izugar n tyimmatin nnsen, ur llint d tiyimmatin nnsen - imi tiyimmatin d tid, kan, i ten id iurwen -, ihi, ar d nnan yir awal, akked tikerkas. Ih, Öebbi ard Win Ipsemmiêen, Ipqilin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 3, 'Wid imetlen, akka, tilawin nnsen, sinna, wexxôen i wayen d nnan, ad brun i wakli, uqbel a tent nnalen. D ayen u$uô i kwen nuban. Öebbi Iéôa ayen txedmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 4, 'Win ur newâa ara, ilaq ad iuéum sin wagguren, wa deffir wa, uqbel a p innal. Win, da$en, ur nezmir ara, ad icceçç sdiset igellilen. Akka, iwakken a ppamnem s Öebbi akked Umazan iS. D tigi ay d tilisa n Öebbi. I ijehliyen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 5, 'Ih, wid ipqamaôen Öebbi akked Umazan iS, ad nneqlaben, akken nneqlaben wid i ten id izwaren. Ni$ Nessers ed issekniyen iberrzen. I ijehliyen, aâaqeb isdullun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 6, 'Ass ideg ara ten id Issker Öebbi, meôôa, ad asen Issken ayen xedmen. Öebbi Iêesb iten, nitni ppun ten. Öebbi d Anagi n yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 7, 'Day ur twalav ara ar Öebbi Iéôa i illan di tmurt, i illan deg igenwan? Ur ippili wawal ger krav, mebla ma Illa, Neppa, d wis kué; ne$ ger smus, u Neppa, d wis sdis. Ama seddaw, ne$ sennig waya, ad Yili yidsen, anda ma llan. D$a, ad asen Imel acu xedmen, ass n tnekra. Ih, Öebbi Iéôa yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 8, 'Ur twalav ara wid i$ef tepwagdel temlilit i umeslay, sinna, u$alen ar wayen i sen ipwagedlen? Ppemlilin i ubekkav, i wanfal, i âaûûu i Umazan. Ma usan k id, ad sellmen fellak s wayen ur d Ipsellim fellak Öebbi. Qqaôen deg ulawen nnsen: "awi d kan ur a$ Ipâuqub ara Öebbi $ef wayen neqqaô"! Loahennama beôka ten. Ad ô$en degs. A tu$alin icemten!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 9, 'A wid iumnen! Ma temlalem i wawal, ur ppemlilit ara i ubekkav, i wanfal, i âaûûu i Umazan. Ppemlilit i tezdeg akked uêezzeb. Ëezzbet i Öebbi u$uô ara tepwafesrem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 10, 'Timlilit i wawal si Cciîan kan, iwakken ad $weblen wid iumnen. Acemma ur ten iîîuôôu, siwa ma Irad Öebbi. £ef Öebbi ara ppeklen lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 11, 'A wid iumnen! Ma nnan awen: "get amkan" di temliliyin, get amkan! Öebbi ad awen Ig amkan. Ma nnan awen: "ooet amkan", ooet amkan! Ad Issali Öebbi tidekkaôin, wid iumnen segwen, akked wid iwumi teppunefk tmusni. Öebbi Iéôa ayen txedmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 12, 'A wid iumnen! Ma temlalem i wawal akked Umazan, seddqet uqbel timlilit. Akka i wen ilha, i wen iûfa. Ma ur tewâam ara, ihi, Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 13, 'Tekukram a pseddqem uqbel timlilit nnwen? Ma ur tseddqem ara, u Issuref awen Öebbi, ééallet, zekkit, a$et awal i Öebbi akked Umazan iS. Öebbi Iéôa ayen txedmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 14, 'Day ur twalav ara wid idduklen akked ugdud i$ef Izzaâf Öebbi? Ur llin segwen ne$ segsen. Pgalan s tkerkas, u nitni éôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 15, 'Ihegga yasen d Öebbi aâaqeb uqsiê. Ih, ar dir it wayen xeddmen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 16, '£ilen tagallit nnsen d ssôan. Swexxiôen seg ubrid n Öebbi. Fellasen aâaqeb isdullun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 17, 'Ur sen d ippawi acemma wayla nnsen, ne$ dderya nnsen, mgal Öebbi, d awez$i. Widak d at tmes. Degs, nitni, ad wekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 18, 'Ass ideg ara ten id Issker Öebbi, meôôa, ad aS gallen akken i wen pgallan. Ad $ilen ar ad yili wacu ideg ara îîfen. Aâni maççi, war ccekk, nitni d ikeddaben?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 19, 'Imelk iten Cciîan armi ppun asmekti n Öebbi. Widak d akabar n Cciîan. Ni$ akabar n Cciîan d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 20, 'Ih, wid ipqamaôen Öebbi akked Umazan iS, widak, ad ndellen sennig wiyav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 21, 'Iura Öebbi: war ccekk, d Nek akked imazanen iW, ara irebêen. Öebbi, s tidep, d Uohid, d Uzmir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 22, 'Ur teppafev ara agdud iumnen s Öebbi akked wass aneggaru, ad iddukwel akked wid ipqamaôen Öebbi akked Umazan iS. Xas ma llan d ibabaten nnsen, ne$ d arraw nnsen, d atmaten nnsen, d alag nnsen. Widak, Iura yasen liman deg ulawen nnsen, Iul iten s ôôuê s$uôeS. A ten Issekcem di leonanat, ddawat sen isaffen ppazzalen, degsen ad wekkôen. Öuvan Öebbi, Iôuva ten. Widak d akabar n Öebbi. Day akabar n Öebbi maççi d win ara irebêen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 1, 'Sbuccuâen Öebbi kra illan deg igenwan, akked kra illan di tmurt. Neppa d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 2, 'D Neppa i Issuff$en seg ixxamen nnsen wid ijehlen seg At Tezmamt, i ujemmal amezwaru. Ur tuminem ara ad ff$en. £ilen leswaô nnsen a ten sellken si Öebbi. Ikka yasen d Öebbi seg wanda ur bnin. Issekcem tugdi deg ulawen nnsen. Hudden ixxamen nnsen, s ifassen nnsen, akked ifassen n lmumnin. Meyyzet a wid ipwalin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 3, 'Lemmer ur asen Iura ara Öebbi neffu, yili Iqeîîa ten di ddunit, u, di laxeôt, fellasen aâaqeb n tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 4, 'Ayagi, acku numren Öebbi akked Umazan iS. Win inumren Öebbi, ihi, Öebbi, Iwâaô i uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 5, 'Ayen tgezmem n tezdayin akked wayen teooam beddent af iéuôan nnsent, s wannuf n Öebbi, iwakken a d Isdull iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 6, 'Ayen i s Ifka Öebbi, s$uôsen, i Umazan iS, ur tebgisem fellas s ioedâen akked lemrakeb. Maca, Öebbi Ippak adabu i Umazan iS, $ef wid i S ihwan. Öebbi Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 7, 'Ayen Ifka Öebbi i Umazan iS, s$uô at tuddar, n Öebbi akked Umazan iS, llezm is, igujilen, ime$ban, akked win d ibbwi ubrid. Iwakken ur ippu$al ara ger ifassen imeôkantiyen nnwen. Ayen i wen ifka Umazan, ddmet ep. Ayen i wen ikkes, kkset ep. Ëezzbet i Öebbi. Ih, Öebbi, Iwâaô i uqeîîi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 8, 'I igellilen iminigen, id ssuff$en seg ixxamen nnsen akked seg wayla nnsen, ssaramen lfevl n Öebbi akked llza, fkan afus i Öebbi akked Umazan iS, d widak ay d imawlan n tidep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 9, 'Wid ized$en ixxamen, iumnen uqbel nnsen, êemmlen wid id iunagen $uôsen. Ur néifen idmaren nnsen af wayen i sen ippunefken, smenyafen ten i iman nnsen, xas ma gwran d xuûûen. Wid irran akin ccêa af yiman nnsen, widak d imerbaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 10, 'Wid id iusan deffir sen, qqaôen: "a Mass nne$! Semmeê a$, akked wamaten nne$, i $ d izwaren ar liman. Ur Ppara deg ulawen nne$, a$ullu n wid iumnen. A Mass nne$! Keçç, s tidep, d Umâin Ipêunun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 11, 'Ur twalav ara ixabiten, la qqaôen i watmaten nnsen ijehlen, seg wAt Tezmamt: "ma ssuff$en kwen, ard a neffe$ yidwen, ur nessemêas i yiwen, d awez$i, mgal nnwen. Ma nnu$en kwen, ar ad awen nefk afus". Ad Icehhed Öebbi, ar nitni d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 12, 'Ma ssuff$en ten, ur teff$en yidsen. Ma nnu$en ten, ur asen ppaken afus. Ma âawnen ten, ad rewlen; ihi, ur ppâawanen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 13, 'D kunwi, sennig Öebbi, ay ugaden idmaren nnsen, ayagi, acku nitni d agdud ur nefhim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 14, 'Ur kwen pna$en, ddukwlen, siwa ma di temdinin ippwaéeôben, ne$ deffir leswaô. Lbe$wv garasen qesseê. A pxilev dduklen, wanag rwin wulawen nnsen. Ayagi, acku nitni d agdud ur nepxemmim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 15, 'Cban wid i ten id izwaren s cwiî kan, jeôôben lwexda igiten nnsen, fellasen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 16, 'Cban Cciîan, mi s inna i umdan: "ejhel"! Mi ijhel, inna: "nek mgirrde$ k, nek ugade$ Öebbi, Mass imavalen"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 17, 'D times, ih, ara yilin d taggara nnsen, ad wekkôen dinna. Ayagi d arraz imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 18, 'A wid iumnen! Ëezzbet i Öebbi. Yal yiwen iwata ad iwali acu ihegga i uzekka. Ëezzbet i Öebbi. Ih, Öebbi Ippuxebbeô $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 19, 'Ur ppilit am wid ippun Öebbi. Irra ten, ppun iman nnsen. Widak d iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 20, 'Ur aâdilen ara at tmes akked at Loennet. At Loennet d imerbaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 21, 'Lemmer id Nessader Leqwôan agi af udrar, a t twaliv iunez, ifelleq, si tugdi n Öebbi. D wigi ay d imedyaten id Neppawi i medden, amar ad meyyzen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 22, 'Neppa d Öebbi, ur illi ôebbi siwa Neppa, Amusnaw n wayen iffren akked wayen ur neffir. Neppa, d Aênin Ipêunun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 23, 'D Neppa, ur illi ôebbi siwa Neppa, ay d Agellid, d Ssid, d Tifrat, d Bab n liman, d Aâssas, d Uzmir, d Ajebbaô, d Ameqwôaêan. Gedha s Öebbi, mgal wayen pcaraken!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 24, 'Neppa d Öebbi, d Axellaq, d Bab usisi, d Amessal. I Neppa ismawen imxulaf mavi. Sbuccuâen T akw kra illan di tmurt akked igenwan. Neppa, d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 1, 'A wid iumnen! Ur ddukulet d icenga W akked icenga nnwen. Teram ten d iêbiben, u nitni nekôen ayen id iusan, $uôwen, n tidep. Èèéaân Amazan, ééaân kwen, imi tumnem s Öebbi, Mass nnwen. Ma teff$em a ppenna$em deg ubrid iW, u tepnadim ôôva W, day a ten terrem, s tuffra, d iêbiben? Nek, Ife$ akw akken èôi$, ayen teffrem akked wayen tennam. Win, segwen, ixedmen akka, innetlaf seg ubrid umâin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 2, 'Ma $elben kwen, ad u$alen d icenga nnwen, a kwen merten s ifassen nnsen akked yilsawen nnsen, ad ssirmen a pjehlem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 3, 'Ass n tnekra, ur kwen infaâ walag, ne$ tarwa nnwen, d awez$i. Ad Ifrez garawen. Öebbi Ipwali igiten nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 4, 'Ni$ illa i kunwi umedya ucbiê di Ibôahim akked wid illan yides, mi nnan i ugdud nnsen: "nemgirred ikwen, kunwi akked wayen teppanzem, war Öebbi. Nenkeô ikwen. Taâdawt akked dd$el, ersen d garane$, i lebda, alamma tumnem s Öebbi Yiwen". Kkes ed awalen i inna Ibôahim, i baba s: "ad velbe$ a ppeppusemmêev, xas ur iyi Ikellef Öebbi, fellak, s wacemma". A Mass nne$! Ppkal nne$ fellaK; nutub iK; $uôeK tu$alin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 5, 'A Mass nne$ ur a$ Ppara d ahewwel i wid ijehlen. A Mass nne$! Semmeê a$. Ih, Keçç d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 6, 'Ni$, i kunwi, amedya nnsen ucbiê, i wid iggunin Öebbi akked wass aneggaru. Ma d win iwexxôen, ihi, Öebbi d Asâay, d Amaâzuz!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 7, 'Ahat Öebbi ad Irr tadukli garawen akked wid, segsen, i illan d icenga nnwen. Öebbi d Uzmir, Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 8, 'Ur awen Ikkis ara Öebbi, a pmaânem u tweznem, ar wid ur kwen nepna$ di ddin, ur kwen nessuffu$ seg ixxamen nnwen. Öebbi, s tidep, Iêemmel wid iweznen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 9, 'I awen Ikkes Öebbi, d tadukli akked wid i kwen ipna$en di ddin, i kwen issuff$en seg ixxamen nnwen, ppaken afus mara kwen ssuff$en. Wid iddan yidsen, widak d imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 10, 'A wid iumnen! Ma usant ed $uôwen tid iumnen, iunagen, jeôôbet pent. Öebbi Iéôa sennig akw liman nnsent. Ma tufam tent d tid iumnen, ur tent pparat ara i ijehliyen. Ur asen êellent, ur asent êellen. Efket asen ayen ûûeôfen. Ulac u$ilif ma tu$em tent, ma tefkam asent tuççit nnsent. Ur pnasabet tijehliyin. Ssutret ayen tûeôôfem, ad ssutren ayen ûûeôfen. Akka ay d aêuddu n Öebbi. Ipêuddu garawen. Öebbi d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 11, 'Ma terwel tmeîîut, si tlawin nnwen, ar ijehliyen, sinna, tâaqbem, efket, ayen ûûeôfen, i wid iwumi ôôuêent tlawin nnsen. Ëezzbet i Öebbi, syiS ay tumnem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 12, 'A Nnbi! Ma usant ed $uôek tid iumnen, ad ak gallent ur pcarakent i Öebbi acemma, ur ppakwrent, ur zennunt, ur neqqent tarwa nnsent, ur teccvent s ifassen ne$ s ivaôen nnsent, ur k ppâuûunt di lewqama, eôêeb yisent, ssuter i Öebbi ad asent Isemmeê. Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 13, 'A wid iumnen! Ur ddukulet akked agdud i$ef Izzâaf Öebbi. Ni$ uysen laxeôt, akken uysen ijehliyen wid illan di tneîlin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 1, 'Sbuccuâen Öebbi, kra illan deg igenwan, akked kra illan di tmurt. Neppa d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 2, 'A wid iumnen! Acimi id teqqaôem ayen ur txeddmem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 3, 'D lâaô meqqwôen, ar Öebbi, ma teqqaôem ayen ur txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 4, 'Ih, Öebbi Iêemmel wid ipna$en deg ubrid iS, d ûûef, nitni, amzun d lebni, iéevêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 5, 'Mi inna Musa i ugdud is: "a yagdud iw! Acimi la yi teîîuôum, u ni$ teéôam nek d amazan n Öebbi $uôwen"? Mi ff$en i ubrid, Öebbi Issuffe$ i ubrid ulawen nnsen. Öebbi ur Inehhu ara agdud iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 6, 'Mi inna Âisa, mmi s n Meryem: "A yAt Isôail! Nek d amazan n Öebbi $uôwen, ad tebbte$ ayen iyi d izwaren n Tuôa. U a kwen beccôe$ s Umazan ara d iasen, deffir i, ism is Aêmed". Mi ten id iusa s ubeggen, nnan: "wagi d ssêur n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 7, 'Anwa idensen sennig win id igren tikerkas af Öebbi, u neppa ipwanced ar wannuz? Öebbi ur Inehhu agdud imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 8, 'B$an ad ssexsin tafat n Öebbi, s imawen nnsen. Öebbi ad Itim tafat iS, di nneqwma ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 9, 'D Neppa id Iuznen Amazan iS, s nnhaya, d ddin n tidep, iwakken a t issifrir f ddin meôôa, di nneqwma ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 10, 'A wid iumnen! Ma d awen Mle$ ssuq ara kwen isellken seg uâaqeb aqeôêan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 11, 'Amnet s Öebbi akked Umazan iS. Nna$et deg ubrid n Öebbi s wayla nnwen, u s yiman nnwen; ppif akka i kunwi, lemmer tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 12, 'Ad awen Isemmeê ibekkaven nnwen; a kwen Issekcem ar leonanat degsen isaffen ppazzalen, tinezdu$in igerzen, di leonanat n Âaden; d wagi ay d rrbeê ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 13, 'Ayen têemmlem nniven: afus s$uô Öebbi akked l$elb aqôib. Ssefôeê lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 14, 'A wid iumnen! Illit d iwiziwen n Öebbi, akken inna Âisa, mmi s n Meryem, i inmahalen is: "anwi ay d iwiziwen iw ar Öebbi"? Nnan d inmahalen: "nekwni d iwiziwen n Öebbi". Tumen terbaât, tejhel terbaât, n At Isôail. Nefka afus i wid iumnen, mgal icenga nnsen, d$a rebêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 1, 'Sbuccuâen Öebbi, kra illan deg igenwan, u kra illan di tmurt. Agellid, Ssid, Uzmir, Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 2, 'D Neppa id Iuznen i wid ur ne$ôi, Amazan segsen, iqqaô asen issekniyen iS. Izizdig iten, isselmad asen Tazmamt akked ûûwab, xas llan, zik, di ttelfan n ûûeê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 3, 'U i wid nniven, mara awven $uôsen. Neppa, d Uzmir, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 4, 'D wagi ay d lfevl n Öebbi. Ippak it i win Ib$a. Öebbi, d bab n lfevl ameqwôahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 5, 'Am wid iwumi ippukelfen s Tuôa, ur p ssawven. Cuban a$yul ibubben tizmamin. I icmet umedya n ugdud inekôen issekniyen n Öebbi! Öebbi ur Inehhu ara agdud imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 6, 'Ini: "a yudayen, ma t$ilem d kunwi ay d iêbiben n Öebbi, war imdanen, ssutret tameppant, ma tessawalem tidep"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 7, 'Ur p ssuturen ara, d awez$i, ilmend igiten nnsen. Öebbi Issen imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 8, 'Ini: "tameppant iwumi tregwlem, a kwen id temmager, war ccekk. Sinna, a kwen awin ar Win Iéôan ayen iffren akked wayen ur neffir. Ad awen Imel ayen txeddmem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 9, 'A wid iumnen! Ma ssawlen d i téallit, ass unejmuâ, $iwlet ar usmekti n Öebbi, êebset ttjaôa. Ppif akka i kunwi, lemmer tessinem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 10, 'Mi tfukk téallit, mfaôaqet di tmurt, nadit lfevl n Öebbi, mmektit ed aîas Öebbi, amar a prebêem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 11, 'Mi walan ssuq, ne$ anecôeê, ad azlen $uôes, a k ooen tbeddev. Ini: "ayen illan ar Öebbi yif anecôeê akked ssuq. Öebbi Yif akw iôeééaqen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 1, 'Ma usan d $uôek ixabiten, ad ak inin: "a ncehhed ar keçç, war ccekk, d Amazan n Öebbi". Öebbi Iéôa ar keçç, war ccekk, d Amazan iS. Öebbi ad Icehhed ar, s tidep, ixabiten d ikeddaben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 2, 'Ëesben tagallit nnsen d laânaya, d$a ssefôa$en abrid n Öebbi. Ihi, a yicmet wayen xeddmen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 3, 'Akka, acku llan umnen, sinna, jehlen. Ppusel$en wulawen nnsen, d$a nitni ur mêiûen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 4, 'Mi ten twalav, a k taâoeb tiddi nnsen. Ma mmeslayen, tessemêasev i wawal nnsen. Amzun nitni d is$aôen i isenden, $ilen yal ti$ôi fellasen. Acengu, d nitni; êader iman ik segsen. A ten Ine$ Öebbi! Acêal wexxôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 5, 'Ma nnan asen: "yyaw, ad issuter Umazan n Öebbi a ppeppusemmêem", ad bernen iqweôôa nnsen, a ten twaliv wexxôen s tem$weô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 6, 'Iâuva fellasen tessutrev, ne$ ur tessutrev ad ppusemmêen. Ur sen Ipsemmiê Öebbi, d awez$i. Öebbi, s tidep, ur Inehhu agdud iballa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 7, 'Nitni i iqqaôen: "ur pseddiqet, i wid iddan akked Umazan n Öebbi, alamma mmebruzzâen". N Öebbi igerrujen igenwan akked tmurt, maca ixabiten ur mêiûen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 8, 'Qqaôen: "ma nu$al ar Lmadina, war ccekk, uzmir ad issuffe$, segs, uôhif". Tazmert, n Öebbi akked Umazan iS, akked lmumnin, maca, ixabiten ur éôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 9, 'A wid iumnen! £uôwat a kwen ssbaâden, af usmekti n Öebbi, wayla nnwen akked tarwa nnwen! Wid igan akka, ihi, widak d imexsuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 10, 'Ssedqet seg wayen i wen Nefka, uqbel a d tas tmeppant ar yiwen degwen, ad yini: "a Mass iw! Lemmer ad iyi Teswexxôev ar lajel aqôib, ad seddqe$, ad ili$ seg wid imaânen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 11, 'Ur Irennu Öebbi di laâmeô, d awez$i, ma iusa d lajel is. Öebbi Ippuxebbeô $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 1, 'I illan deg igenwan, i illan di tmurt, sbuccuâen Öebbi. IneS tagelda; ineS wannuz; Neppa Izmer i yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 2, 'Neppa ikwen Ixelqen; segwen ajehli, segwen lmumen. Öebbi Ipwali ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 3, 'Ixleq tamurt akked igenwan, s tidep. Imsel ikwen, Iûeggem amsal nnwen. £uôeS tu$alin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 4, 'Iéôa i illan di tmurt akked igenwan. Iéôa ayen teffrem akked wayen tennam. Öebbi Iéôa i illan deg idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 5, 'Ma iusa kwen id usali n wid illan, zik, d ijehliyen? Jeôben lwexda n tikli nnsen. Fellasen, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 6, 'Ayagi, imi sen ppasen imazanen nnsen s ubeggen. Nnan: "aâni d amdan ara $ inhun"? D$a jehlen, xedâan. Ur Iclaâ Öebbi. Öebbi d Asâay, d Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 7, 'Pputebten ijehliyen ar, d awez$i, ur d pnekkaren. Ini: "xaîi! S Mass iw, ard a d tekkrem, sinna ard a ppepwaxebbôem $ef wayen txeddmem"! Ayagi, i Öebbi, d ushil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 8, 'Ihi, amnet s Öebbi akked Umazan iS, akked tafat id Nessers. Öebbi Ippuxebbeô $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 9, 'Ass ideg ara kwen Issemlil, i wass ujemmel, ass nni, d ass um$uôôu. Win iumnen s Öebbi, ixeddmen ayen ilhan, ad as Ikkes tucmitin is, a t Issekcem ar leonanat, ddawat sen isaffen ppazzalen, degsen ad iwekkeô i lebda. D wagi ay d rrbeê ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 10, 'Wid ijehlen u inekôen issekniyen nne£, widak d at tmes, degs ad wekkôen. A taggara icemten!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 11, 'Ur d teppas twa$it, siwa ma Irad Öebbi. Win iumnen s Öebbi, ad Inhu ul is. Öebbi Iéôa yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 12, 'A$et awal i Öebbi, a$et awal i Umazan! Ma twexxôem, i iwatan kan, i Umazan nne£, siwa anabi ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 13, 'Öebbi, ur illi ôebbi siwa Neppa. £ef Öebbi ara ppeklen lmumnin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 14, 'A wid iumnen! S tidep, kra n tlawin nnwen akked tarwa nnwen, d icenga nnwen. Ëadret iman nnwen segsen! Ma tsemmêem, teppum, tsemmêem, Öebbi, s tidep, Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 15, 'Ayla nnwen akked dderya nnwen, d ahewwel kan, wanag, ar Öebbi, illa warraz ameqwôahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 16, 'Ëezzbet i Öebbi ayen iwumi tzemrem. Ëesset, ôavit, seddqet! Yif it i iman nnwen. Wid ikksen ccêa i iman nnsen, widak d imerbaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 17, 'Ma tôevlem i Öebbi aôeîîal igerzen, ad awen d Irr sin imuren, ad awen Isemmeê. Öebbi Iceffu, Iêellem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 18, 'Amusnaw n wayen iffren akked wayen ivehôen, Uzmir, Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 1, 'A Nnbi! Mara tebrum i tlawin, brut asent mara tâaddi tallit n tarda nnsent. Ëesbet tallit. Ëezzbet i Öebbi, Mass nnwen. Ur tent ssuffu$et si texxamin nnsent, ur d teff$ent, siwa ma, s tidep, ccvent. D tigi ay d tilisa n Öebbi. Win izegren tilisa n Öebbi, ni$ idens imanis. Ur teéôiv ara, ahat Öebbi a d Iazen lameô, ssyen $eô da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 2, 'Mi ssawvent lajel nnsent, âacôet pent s lewqama, ne$ mfaôaqet yidsent, s lewqama. Awit ed sin inagan iêeqqiyen segwen, a d cehhden zdat Öebbi. Ataya wayen u$uô ppunedôen, wid iumnen s Öebbi akked wass aneggaru. Win ipêezziben i Öebbi, ad as Ildi tibbura,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 3, 'a t I$it s wanda ur iêtim. Win iîîfen di Öebbi, a t Iqennaâ. Ih, Öebbi Issâadday lameô iS. Ni$ Öebbi Iwzen yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 4, 'I tigad, n tlawin nnwen, i iuysen tarda, ma illa ccekk, tallit ugani nnsent: krav wagguren. Akken i tid ur nebdi tarda. Tid ibbwin tadist, tallit nnsent ar tinnufra nnsent. Win ipêezziben i Öebbi, s lameô iS, ad as Istiser.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 5, 'D wagi ay d lameô n Öebbi i wen d Issers. Win ipêezziben i Öebbi, ad as Ikkes tucmitin is, ad Issali arraz is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 6, 'Ad asent tefkem tanezdu$t anda tzed$em, akken tewâam. Ur tent îîuôôut s tririt nnsent ar lêeôs. Ma llant s tadist, ûeôôfet fellasent, alamma d tinnufra nnsent. Ma ssuîvent tarwa nnwen, efket asent taqdiât nnsent; mwafaqet s tiéeî. Ma temnamarem, a ppessuîîev tmeîîut nniven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 7, 'Bu udrim ad iûeôôef segs. Win ixuû ôôeéq ad iûeôôef seg wayen i s Ifka Öebbi. Ur Ipkellif Öebbi taôwiêt, siwa ar ayen i s Ifka. Öebbi ad Issuffe$ laâtab ar tafat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 8, 'Acêal n temdinin i inuqmen lameô n Mass nnsent akked imazanen iS! Nêuseb itent leêsab uqsiê. Nâaqeb itent s uâaqeb issexven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 9, 'Jeôôbent lwexda igiten nnsent. D lexsaôa ay d iooa lameô nnsent.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 10, 'Öebbi Ihegga yasen aâaqeb uqsiê. Ëezzbet i Öebbi a yuâqilen iumnen! Ni$ Öebbi Issers awen d asmekti;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 11, 'Amazan i wen immalen issekniyen n Öebbi iberrzen, iwakken ad Issuffe$, si tillas ar tafat, wid iumnen, ixeddmen ayen ilhan. Wid iumnen s Öebbi, ixeddmen ayen ilhan, a ten Issekcem ar leonanat, ddawat sen isaffen ppazzalen, degsen ad wekkôen i lebda. Ni$ Öebbi Igerrez asen ôôeéq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 12, 'Öebbi i Ixelqen ûa igenwan, akked tmurt am nitni. Lameô iprusu garasen, iwakken a ppeéôem ar Öebbi Izmer i yal cci, u Öebbi Izzi i yal cci s tmusni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 1, 'A Nnbi! Ay$eô tgedlev ayen i k Iêell Öebbi? Tqennâav tilawin ik. Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 2, 'Öebbi Iêeppem fellawen a pêentem. Öebbi d Bab nnwen. Neppa d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 3, 'Mi inna Nnbi sser, i yiwet si tlawin is, u temla, Öebbi Issken it i neppa. Ixebbeô s wumur, iffer amur, segs. Mi p iaâlem s waya, tenna: "wi k imlan aya"? Inna: "Imla yi t Win Issnen, Ippuxebbôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 4, 'Ma tutubemt Öebbi, ihi knan wulawen n kwent. Ma tedduklemt as, ihi, d Öebbi ay d Bab is, u, deffir waya, ad ilin di talalt is: Jebrayen, ûûam n lmumnin, u lmalayek ad fkent afud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 5, 'Ma ibra yakwent, Izmer Öebbi ad as d Inûef s tlawin i kwent yifen, timvuâin, tid iumnen, ipéallan, iutuben, iâabden, ippuéumen, tid ijeôben tissulya, ne$ tiâazriyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 6, 'A wid iumnen! Ëadret iman nnwen akked twacult nnwen, si tmes, is$aôen is d imdanen akked id$a$en! Fellas lmalayek tuohidin, tuqsiêin, ur nepwexxiô i wayen i sent Iumeô Öebbi, i ixedmen i sent ipwamôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 7, 'A wid ijehlen, ulay$eô teste$fôem assa! A ppeppuqeîîim kan $ef wayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 8, 'A wid iumnen! Utubet Öebbi, ppuba n ûûeê! Ahat Mass nnwen ad awen Ikkes tucmitin nnwen, u a kwen Issekcem ar Loennet, ddaw as isaffen ppazzalen. Assen, Öebbi ur Isdullu Nnbi akked wid iumnen yides. Tafat nnsen teppeddu zdat sen, u yeffus nnsen. Ad qqaôen: "a Mass nne$! Tim ane$ tafat nne$, Semmeê ane$; ih, Keçç, Tzemrev i yal cci".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 9, 'A Nnbi! Nna$ ijehliyen akked ixabiten! Iqsiê $uôsen! Axxam nnsen d Loahennama, d tu$alin tucmip.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 10, 'Ifka d Öebbi amedya i wid ijehlen: tameîîut n Nuê akked tmeîîut n Luî. Llant ger ifassen n sin imdanen, seg wid imaânen n imdanen nne$. £uüôôent pen. Ur zmiren a tent sselken s wacemma, seg ufus n Öebbi. Ancad: "kecmemt ar tmes akked wid ikecmen"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 11, 'Ifka d Öebbi amedya i wid iumnen, tameîîut n Ferâun, mi tenna: "a Mass iw! Ebnu yi, $uôeK, taxxamt di Loennet, Sellek iyi si Ferâun akked igiten is, Sellek iyi si lqum imednas"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 12, 'U Meryem ult Âimôan i izazdgen tuzzuft is. Nenfes $uôes si ôôuê nne£, tepputebbet $ef wawalen akked tezmamin n Mass is. Neppat seg wid ipéallan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 1, 'Iôqa Bu tgelda deg ufus iS, u Neppa, Izmer i yal cci;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 2, 'i Ixelqen tameppant, tameddurt, iwakken a kwen Ijeôôeb: anwa degwen ara ixedmen igiten ilhan sennig wiyav. Neppa d Uzmir, Ipsemmiê;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 3, 'i Ixelqen ûa igenwan d idurra. Deg wayen Ixleq Uênin, ur tepwaliv ayen ixuûûen. Ernu sikked ma a pwaliv i$isiyen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 4, 'Sinna, ger tiî ik berdayen. Iéôi a d iu$al $uôek, iêfa, u inzef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 5, 'Ni$ Ncebbeê igenni aqôib s teftilin, Nôeooem yisent cwaîen, Nhegga yasen aâaqeb n tmes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 6, 'I wid inekôen Mass nnsen, aâaqeb n Loahennama. A tu$alin tucmip!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 7, 'Mi pwaveggôen $uôes, ad slen la tesraâriâ, u neppat trekkem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 8, 'Qôib a ppeftutes seg iûiv. Yal tikelt ara iwaveggeô $uôes urbaâ, a ten steqsin iâssasen is: "aâni ur kwen id iusi ara uneddaô"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 9, 'Ad inin: "ih, iusa ya$ d uneddaô, nenkeô u nenna: ur illi ay d Issuder Öebbi, aql akwen kan di le$wlav meqqwôen"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 10, 'U nnan: "lemmer nelli nsell ne$ nfehhem, ur nelli seg wat tmes".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 11, 'Qaôôen s ibekkaven nnsen. Asêaq i at tmes!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 12, 'Wanag, i wid ippagwaden Mass nnsen, di tbavnit, ssmaê akked warraz meqqwôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 13, 'Hedôet s sser ne$ âinani, ihi, Neppa Iéôa ayen illan deg idmaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 14, 'Day ur Iéôi ara Win Ixelqen, Laîif Ippuxebbôen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 15, 'Neppa i wen Irran tamurt d tamvuât. Elêut deg ibraêen is, ççet si ôôeéq is. £uôeS tanekra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 16, 'Ma tepputebtem ar, Win Illan deg igenni, ad Irr tamurt a ppertem yiswen? Appan la teppembwiwil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 17, 'Ma tepputebtem, ar Win Illan deg igenni, awen d Iazen tabucivant n yid$a$en? D$a, a ppissinem anwa t unabi W.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 18, 'Ni$ nekôen imezwura nnsen. Amek d Zzi$ fellasen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 19, 'Ahat ur walan ara ifôax, sennig sen, d idurra, afriwen ceôqen, ur côiqen. Siwa Aênin iten Iîfen. Neppa, ih, Issikkid yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 20, 'Anwa wa ay d aâsekôiw nnwen, ara kwen isellken, war Aênin? Ijehliyen atnan kan di le$ôuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 21, 'Anwa wa ara kwen iôeéqen ma Ijmaâ l$it iS? Maca, vellelen deg u$unfu akked leqbaêa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 22, 'Win iteddun, ibra i uqeôôu, day ipwanha sennig win iteddun, irfed aqeôôu, deg ubrid uwqim?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 23, 'Ini: "d Neppa ikwen id Ixelqen. Irra yawen timejjin, allen, ulawen. Drus ay tesnemmirem"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 24, 'Ini: "d Neppa ikwen isseftin di tmurt, ar $uôeS ara tepwafesrem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 25, 'La qqaôen: "melmi lemâahda agi, ma d tidep ay tessawalem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 26, 'Ini: "i Iéôan siwa Öebbi. Nek d aneddaô kan ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 27, 'Mara a t walin iqeôb ed, ad ndellen wudmawen n wid ijehlen. A d inin: "atan wayen tessuturem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 28, 'Ini: "ma twalam ma In$a ya$ Öebbi, nek d imeddukwal iw, ne$ ma Iêun fella$? Ihi, anwa ara isellken ijehliyen seg uâaqeb aqeôêan"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 29, 'Ini: "Neppa d Aênin, syiS numen, fellaS neppkel. A ppeéôem anwa i illan di ttelfan n ûûeê".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 30, 'Ini: "ma twalam, lemmer ad zzren waman nnwen, w ar awen d iawin aman ippazalen"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 1, 'N. S wamru akked wayen pjerriden!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 2, 'Keçç, s l$it n Mass ik, ur telliv d aôehbani!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 3, 'Ih, i keçç arraz ur nepnegzay.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 4, 'Ih, keçç, lxaîeô ik d ûûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 5, 'A pwaliv, ad walin', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 6, 'anwa degwen ippuhewwlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 7, 'D Mass ik, ih, i Izôan sennig wiyav, anwa iff$en abrid iS. D Neppa i Izôan, sennig wiyav, anwi ipwanhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 8, 'Ihi, ur ppak awal i inekkaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 9, 'Ssaramen a ppestaâmlev, akken ad staâmlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 10, 'Ur ssemêas i yal afuêan ipgallan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 11, 'aqeôôad ileêêun iplemmim,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 12, 'i igelden lxiô, ippawven, idenben,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 13, 'amjuô, u irna d akluc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 14, 'Xas $uôes ayla, igwerdan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 15, 'Ma $ôan as issekniyen nne£, iqqaô: "d timucuha imezwura".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 16, 'A t Nweccem deg wanzaren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 17, 'Ih, Njeôôeb iten akken Njeôôeb at leonan, mi gullen, ar di tûebêit, ad $elten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 18, 'Ggulen ur êniten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 19, 'Tezzi yas tbucivant s$uô Mass ik, nitni îîsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 20, 'Iu$al amzun d lbuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 21, 'Di tûebêit msawalen:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 22, '"ekkret zik, ar lexla nnwen, ma a p$elltem"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 23, 'Teddun, sbecbucen garasen:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 24, '"igellil, assa, ur t ppaooat a p id ikçem". ö', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 25, 'Öuêen ppeklen, zemren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 26, 'Mi t walan, nnan: "nekwni d im$eôôqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 27, 'Ih, aql a$ nepwaêeôôem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 28, 'Inna uêdiq mavi nnsen: "day ur awen nni$ ara: a lemmer tesbuccuâem"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 29, 'Nnan: "nesbuccaâ Mass nne$. Nella, s tidep, d imednas".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 30, 'Mqabalen, ppemyuzzamen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 31, 'Nnan: "a ssexv nne$, nella d imjuôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 32, 'Ahat Mass nne$ ad a$ d I$ôem sennig waya; ih, nekwni, ar Mass nne$, d imectaqen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 33, 'Am akka, aqeîîi. Aqeîîi n laxeôt, war ccekk, meqqweô kteô, lemmer éôin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 34, 'Ih, i wid ipêezziben i Mass nnsen, Loennet n ssuâada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 35, 'Aâni Nerr imvuâen am ibe$wviyen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 36, 'Acu ikwen iu$en? Amek tepêuddum?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 37, 'Ne$ tesâam tazmamt ideg tlemdem,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 38, 'degs, i kunwi, s tidep, ayen tesmenyafem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 39, 'Ne$ $uôwen tuqqna s$uône$, ar ass iqeîîiten, ara kwen id ias wayen têuddem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 40, 'Steqsi ten ma, $ef waya, $uôsen îîamen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 41, 'ne$ $uôsen icriken? Ihi, a d awin icriken nnsen, ma d tidep ay ssawalen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 42, 'Ass ideg ara tepwafveê twa$it, ad asen inin ad knun, ur zmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 43, 'Ad brunt wallen, ddell iwwet iten. Ni$ pwanecden ar lekni, mi llan ûeêêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 44, 'Eoo iyI akked wid iskaddben awal agi. Ad asen Ddu$ cwiî, cwiî, seg wanda ur éôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 45, 'Ad asen Fke$ lmudda. Ni$ tiêeôci W teéweô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 46, 'Ne$ tessutrev taqdiât, fellasen d îîlaba ééayen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 47, 'Ne$ $uôsen tabavnit, d$a la pparun?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 48, 'Eûbeô i ôôay n Mass ik, ur ppili am bu uslem, i d issawlen mi ippuêeyyeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 49, 'Lemmer ur t id issukkes l$it n Mass is, a d iu$al ar lxali, d amaâfun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 50, 'Ifren it Mass is, Irra t seg iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 51, 'Qôib i k smalen ijehliyen, s wallen nnsen, mi slan i usmekti. La qqaôen: "ar neppa d aôehbani".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 52, 'Neppa, d asmekti kan i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 1, 'Tin imuêeppmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 2, 'D acu ay d tin imuêeppmen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 3, 'W ar ak imlen d acu p, tin imuêeppmen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 4, 'Tamud akked Âad skaddben tin ipôuéun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 5, 'Tamud pwan$an s termegt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 6, 'Âad pwan$an s uûeôûaô aqesêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 7, 'Iêeppem it, fellasen, ûa wavan, îam wussan, d imezgi. A pwaliv din imdanen seôâan, am ize$wôan n tezdayt iruzen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 8, 'Twalav ma illa wacu d igwran segsen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 9, 'Iusa d Ferâun akked wid i t id izwaren, akked tid ippin, s lfalîat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 10, 'Âuûan amazan n Mass nnsen. Issemêalleq asen s lqewwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 11, 'Ih, aman asmi ccewcwen, Nebbwi kwen di lbabur,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 12, 'iwakken ad awen t Nerr d asmekti, ad as ccfun imeééu$en isellen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 13, 'Ma ûuven di lbuq, aûuvu yiwen:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 14, 'idurar akked swaêel ad pwarefden, yiwet n tiôéi ara ten iôéen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 15, 'Ass nni, a ppevôu tedyant.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 16, 'Ad iceqqeq igenni, ad icerreg, assen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 17, 'Lmalayek, di leriaf is. Assen, di îam ad refdent, sennig sent, asgeld n Mass ik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 18, 'A ppepufesren, assen; iccer ur iteffer segwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 19, 'Wanag win iwumi fkan tazmamt is, yeffus is, a d yini: "atan, e$ôet adlis iw;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 20, 'êsi$, nek, ad afe$ iyi twaêesben".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 21, 'D$a ad yili di tudert igerzen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 22, 'di leonan aâlayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 23, 'Izwayen is, iwâa yasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 24, 'àçet, teswem di lehna, ilmend n wayen tweqmem, ussan iâaddan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 25, 'Wanag win iwumi fkan tazmamt is, zelmev is, a d yini: "a ssexv iw, awufan adlis iw ur d iusi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 26, 'Iqeîîiyen iw, ur éôi$ anwi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 27, 'Awufan tameppant dayenni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 28, 'Ayla w, ula iyi d ibbwi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 29, 'Adabu w, ipwakkes iyi". ï', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 30, '"Ïîfet ep, tarzem t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 31, 'D$a ar wu$ud, terrem t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 32, 'D$a s slesla n ûavet i$alen, teqqnem t"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 33, 'Ih, illa ur iumin ara s Öebbi Ameqwôaêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 34, 'Ur ipnabi ar uceççi uéawali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 35, 'Dagi, ur as illi, assa, uêbib,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 36, 'ne$ uççi siwa iôesvan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 37, 'Teppen ten kan imednuben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 38, 'Ihi, ad Galle$ s wayen tepwalim,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 39, 'akked wayen ur tepwalim,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 40, 'ar wagi, s tidep, d awal Umazan ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 41, 'Ur illi d awal umedyaz; drus kan ay tumnem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 42, 'Ur illi d awal ugezzan; drus ay d tepmektayem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 43, 'D tarusi s$uô Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 44, 'Lemmer a d iskiddeb fella£ deg wawalen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 45, 'seg uyeffus ar at Neddem;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 46, 'd$a, aéaô n wul is, ad as Negzem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 47, 'Ur ippili degwen w ara t ifukken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 48, 'Neppa, ih, ar d asmekti i wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 49, 'Neéôa, s tidep, ar llan garawen inekkaôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 50, 'Neppa, ih, d tawa$it ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 51, 'Neppa, ih, d tidep itebbtenÊ', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 52, 'Sbuccaâ isem n Mass ik Ameqwôaêan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 1, 'Isteqsa yiwen, af uâaqeb iuran', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 2, 'i ijehliyen. Ur t ipxaûam yiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 3, 'S$uô Öebbi, Bab n tseddaôin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 4, 'Lmalayek akked ôôuê, ppalin $uôeS, deg wass idumen smuset igima iseggwasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 5, 'Ihi, eûbeô ûûebô ifazen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 6, 'Nitni, s tidep, walan t ibâad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 7, 'Nwala t d aqôib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 8, 'Asmi ara yili igenni, am uzzal ifsin;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 9, 'idurar ad ilin am tavuî.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 10, 'Aêbib ur isteqsay aêbib,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 11, 'u mwalan. Ad ib$u ube$wvi, assen, ad isebbel tarwa s iwakken, seg uâaqeb, ad ipwafdu;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 12, 'akked tmeîîut is, akked gma s,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 13, 'akked walag is it iûûôen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 14, 'akked wayen illan di tmurt meôôa; iwakken a t sellken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 15, 'Xaîi, atan ujajiê!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 16, 'Isexxev agwlim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 17, 'Issawel i win ixedâan, iaâûa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 18, 'ippadamen, ipsemmiden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 19, 'Amdan, s tidep, ipwaxleq d aêemmaq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 20, 'Ma innul it cceôô, atan di leqlala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 21, 'Ma innul it lxiô, ad isquceê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 22, 'Kkes ed iméulla,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 23, 'imezgiyen di téilla nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 24, 'i ippaken seg ayla nnsen, lêeqq ipwassnen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 25, 'i umappar, akked ume$bun;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 26, 'wid ipputebbten s wass iqeîîiyen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 27, 'wid iugaden aâaqeb n Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 28, 'War ccekk, aâaqeb n Mass nnsen ur illi segs usellek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 29, 'Wid iêurben af tuzzuft nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 30, 'kkes ed ar tilawin nnsen, ne$ piklatin nnsen; akka, ur ppulummun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 31, 'Wid ib$an sennig waya, widak d tilas ay zegren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 32, 'Wid ippaîîafen deg wawal nnsen, di tgallit nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 33, 'wid ippaîîafen di ccada nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 34, 'wid ipêaraben $ef téilla nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 35, 'Widak, di leonanat, d imaâzuzen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 36, 'Acu iu$en ijehliyen, uzlen d $uôek, imegrav qquôen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 37, 'Yeffus, zelmev, d igrawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 38, 'Yal amdan, segsen, issarem ad ikcem Loennet n ssaâd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 39, 'Xaîi! S tidep, Nxelq iten seg wayen éÈôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 40, 'Ihi, ggulle$ s Mass igmav akked ituram, ar Nekwni d Wid izemren', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 41, 'a d Nawi ay ten yifen, deg umkan nnsen! Ur a£ izeggwir yiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 42, 'Eoo iten ad slullven, ad uraren, ar d magren ass nnsen, win i sen ippuwaââden;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 43, 'ass ideg ara d ff$en si tneîlin, ppazzalen, amzun ar id$a$en sbedden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 44, 'Ad brun i wallen, ddell fellasen. D wagi ay d ass i sen ippuwaââden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 1, 'S tidep, Nuzen ed Nuê i ugdud is: "endeô agdud ik, uqbel a ten id ias uâaqeb aqeôêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 2, 'Inna: "a yagdud iw! Nek, i kunwi, d aneddaô ipbegginen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 3, 'Âabdet Öebbi, têezzbem aS, tessemêessem iyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 4, 'Ad Isemmeê seg ibekkaven nnwen, ad awen Ifk lmudda ar lajel ipwassnen. S tidep, lajel n Öebbi, ma iusa d, ur ipwexxiô, lemmer peéôim"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 5, 'Inna: "a Mass iw! Nek, ssawale$ i ugdud iw, am yiv am ass.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 6, 'Siwa tugin i sen terna ti$ôi w.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 7, 'Nek, yal tikelt ara ten neccde$ iwakken a sen Tsemmêev, ad rren ivudan nnsen deg imeééu$en nnsen, ad pplen deg iceîîiven nnsen. Ggernennen, zuxxen s tem$weô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 8, 'Sinna, ssawle$ asen s uâaggev.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 9, 'Sinna, âinani nni$ asen; s tuffra, sser, mli$ assen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 10, 'Nni$: "ssutret ssmaê i Mass nnwen; Neppa ard Win Ipsemmiêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 11, 'Ippazen awen d ageffur, seg igenni, d ihedman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 12, 'Ayla akked tarwa, Issuget awen; Ifka yawen timizar; Irra yawen isaffen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 13, 'Acu kwen iu$en, Öebbi, ur aS tgim ccan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 14, 'Ni$ i waya, Ixelq ikwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 15, 'Ur twalam ara amek Ixleq Öebbi ûa igenwan d idurra?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 16, 'Irra degsen, aggur d tafat. Irra iîij d asavef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 17, 'Öebbi Issem$i kwen seg wakal, am im$an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 18, 'Sinna, a kwen Irr $uôes; sinna, d tuff$a ara kwen id Issuffe$.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 19, 'Öebbi Irra yawen tamurt d tuwsiât,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 20, 'iwakken, degs, a ppafem iberdan d tiza".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 21, 'Inna Nuê: "a Mass iw! Atnan âuûan iyi. Ddan akked win iwumi, ayla s akked tarwa s, ay s rnan, siwa lexsaôa".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 22, 'Sxedmen tiêila meqqwôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 23, 'Nnan: "ur ppaooat iôebbiten nnwen! Ur ppaooat Wadd, Suwaâ, Ya$ut, Yaâuq, akked Naûô"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 24, 'Ni$ aîas ay telfen. Ur Trennuv i imednas, siwa ttelfan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 25, 'Ilmend n tuccva nnsen, $evûen, sinna kecmen ar tmes. War Öebbi, ur ppafen imâiwnen nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 26, 'Inna Nuê: "a Mass iw! Ur Ppaooa, seg ijehliyen, amezda$ di tmurt!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 27, 'Aql aK id ma Teooiv ten, ad telfen imdanen iK. Siwa tijehli akked lâaô, ara d arwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 28, 'A Mass iw, Semmeê a$, nek akked imawlan iw, akked win id ikecmen s axxam iw, iumen, akked wid d tid iumnen. Ur Rennu i imednas, siwa aquccu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 1, 'Ini: "ippuweêêa yi d, ar agraw n leonun ssemêessen, u nnan: ih, nesla i Leqwôan, d lwehma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 2, 'Inehhu ar ûûwab, d$a numen yis. I Mass nne$, ur nepcarak yiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 3, 'U Neppa, gedha s loeôs n Mass nne$ Aâlayan, ur Isâi tameddakwelt, ne$ ùùmmi S!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 4, 'Ih, abuhal nne$ iêekku, af Öebbi, ixmiôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 5, 'Nekwni nenwa leonun akked imdanen, ur sawalen, af Öebbi, tikerkas, d awez$i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 6, 'Ih, seg imdanen, llan irgazen ijjemen ddkeô n leonun. Snernan lbe$wv nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 7, 'S tidep, $ilen, akken t$ilem, ar Öebbi ur d Isskar yiwen, d awez$i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 8, 'Aql a$ nqelleb igenni, nufa t iççuô d iâssasen uqsiêen, akked ijujaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 9, 'Nella nep$imi $uôes, seg imukan nessemêas; win issemêessen tura, a t id immager usafu d aâessas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 10, 'Nekwni, ur neéôi ma iura lhemm, af at ddunit, ne$ ma Ib$a, Mass nnsen, ad pwanhun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 11, 'Llan garane$ iâaôviyen, llan wid ur nemâin; ur naâdil iberdan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 12, 'Nmeyyez nufa, war ccekk, ur nesfunnug Öebbi di tmurt, ur T nesfunnug ma nerwel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 13, 'Nnhaya mi s nesla, yis numen. Win iumnen s Mass is, ur ippagwad ara t ixaûen, ne$ ara t ivuôôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 14, 'Ih, garane$ imvuâen, garane$ lâaûûap. Wid iunzen, widak, xtaôen lewqam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 15, 'Ma d lâaûûap, di Loahennama, d nitni ay d is$aôen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 16, 'Lemmer deg ubrid ay ddan, yili Nefka yasen aman iqwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 17, 'A ten njeôôeb yissen. Win iooan asmekti n Mass is, ad isâaddi aâaqeb aqesêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 18, 'Leowamaâ n Öebbi. Ur naâôet yiwen ar tama n Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 19, 'Atan, mi ikker umdan n Öebbi ad inuj $ureS, qôib lesqen $uôes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 20, 'Ini: "pnuju$ kan ar Mass iw, ur aS pcarake$ yiwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 21, 'Ini: "nek, ur pwakelfe$ $ef vveôô nnwen ne$ $ef nnhaya nnwen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 22, 'Ini: "nek, ur iyi ipfukku yiwen seg ufus n Öebbi, d awez$i. War Neppa, ur ppafe$ ssôan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 23, 'siwa anabi s$uô Öebbi, akked tebrap iS". Ih, i wid iâuûan Öebbi akked Umazan iS, times n Loahennama, ad wekkôen degs, i lebda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 24, 'Alamma mi walan ayen i sen ippuwaââden, ad éôen anwi ay d uôhifen mavi, i leslak, anwi drus iten mavi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 25, 'Ini: "ur éôi$ ma iqeôb ed wayen i wen ippuweââden, ne$ ma a t Iweooel Mass iw;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 26, 'Amusnaw n tbavnit; tabavnit iS, ur p Immal i yiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 27, 'Kkes ed win Iôuva d amazan. Winna, iteddu, zdat deffir, s iâssasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 28, 'Ad Iéeô ma ssawven tibratin n Mass nnsen. Izzi i wayen akw illan $uôsen, Iêeppeb yal cci s imvanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 1, 'A win isburen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 2, 'Aâwez, xas cwiî.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 3, 'Azgen n yiv, ne$ ssenqes segs, acemma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 4, 'Ne$ rnu yas. Di Leqwôan ûûun leqôaya!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 5, 'Aql a£, ad ak d Nini awal amray.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 6, 'Ccaw n yiv, iééaéay kteô asurif, u issewqam kteô leqôaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 7, 'Deg wass, s tidep, tce$wlev, maççi d kra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 8, 'Mmekti d isem n Mass ik, lhu yideS, akken iwata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 9, 'Mass ugmuv akked utaram, ur illi ôebbi siwa Neppa. Ihi, sâu T d Awkil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 10, 'Eûbeô i innan nnsen, faôeq iten s leêdaqa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 11, 'Eoo iyI inekkaôen, akked usâiyen; efk asen cwiî n lmudda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 12, '£uône£, s tidep, slasel akked tmes iôeqqen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 13, 'lqut ipceôôiqen, aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 14, 'Ass ideg tamurt akked idurar ad rgagin, idurar ad u$alen am ôômel ippazalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 15, 'Atan Nuzen awen ed Amazan, d anagi nnwen, akken Nuzen amazan i Ferâun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 16, 'Ferâun iâuûa amazan. Newwet it tiyta tuqsiêt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 17, 'Amek ara têezzbem, ma tnekkôem ass ideg igwerdan ad caben?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 18, 'Segs, ad icerreg igenni, ad iûaô wayen i wen Iwaââed.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 19, 'Atan wagi d asmekti; win iôe$ben ad iawi abrid ar Mass is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 20, 'Ih, Iéôa Mass ik, keçç akked urbaâ seg wid illan yidek, teppekkrem deg iv, qôib sin imuren, ne$ azgen, ne$ amur wis kué. Öebbi Iwezzen iv akked wass; Iéôa ur ten têepbem ara. Issuref awen. E$ôet, si Leqwôan, ayen isehlen fellawen. Iéôa ad ilin segwen imuvan. Wiyav ppinigen di tmurt, pnadin lfevl n Öebbi. Wiyav pna$en deg ubrid n Öebbi. Ihi, e$ôet, segs, ayen isehlen fellawen; éallet; zekkit; ôevlet aS i Öebbi, aôeîîal umâin. Lxiô ara txedmem i iman nnwen, a t tafem ar Öebbi. D arraz it yifen, it i$elben. Ssutret ssmaê i Öebbi. Ih, Öebbi Ipsemmiê, Ipêunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 1, 'A win ipwadlen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 2, 'Ekker, endeô!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 3, 'Mass ik, ssem$weô!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 4, 'Iceîîiven ik, zzizdeg!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 5, 'Timenqas janeb!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 6, 'Ur ppak ma tuôoiv kteô!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 7, 'I Mass ik, eûbeô!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 8, 'Ma ûuven di lbuq,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 9, 'assen, ihi, d ass uwâiô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 10, 'Ur ippili d yiser, i ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 11, 'Eooet iyI, akked win Xelqe$ d afôid.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 12, 'Fki$ as ayla iwerrken,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 13, 'akked tarwa d imsaâfen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 14, 'Ssehle$ as, ad istumen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 15, 'Sinna issarem ad Rnu$.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 16, 'Xaîi! Atan, issekniyen nne£, inkeô iten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 17, 'Ad êeppme$ fellas ssxev.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 18, 'Ih, ixemmem, d$a iseyya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 19, 'Ipwasxev f akken iseyya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 20, 'Da$en, ipwasxev f akken iseyya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 21, 'Sinna, imuqel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 22, 'Sinna, ikres tagwenza, innu$ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 23, 'Sinna, izzux, ibren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 24, 'D$a inna: "wagi d ssêur kan ippulemden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 25, 'Ayagi d awal kan n umdan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 26, 'A t Fke$ i tmes iôeqqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 27, 'W ara k imlen, d acu p tmes iôeqqen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 28, 'Ur teppaooa, ur tessagwar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 29, 'Tesseô$a igwelman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 30, 'Nnig es mrawtza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 31, 'D lmalayek kan i Nerra d imawlan n tmes. Nefka d kan amvan nnsent, iwakken ad hewwlen wid ijehlen; ad pputebbten wid iwumi teppunefk Tezmamt; ad innerni liman n wid iumnen; ur ippili ccekk ar wid iwumi teppunefk Tezmamt, akked lmumnin; akken ad inin at wul iblan, akked ijehliyen: "acu i Ib$a Öebbi s umedya agi"? Akka, Itellif Öebbi win i S ihwan, Inehhu win i S ihwan. Iâsekôiwen n Mass ik, siwa Neppa iten Issnen. Wagi d asmekti kan i imdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 32, 'Xaîi! S waggur!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 33, 'S yiv ma isahel!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 34, 'S tafrara ma tecâal!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 35, 'Ar neppat d tabarart.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 36, 'D aâggen i medden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 37, 'I win ib$an, segwen, ad iqeddem, ne$ ad iwexxeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 38, 'Yal iman d ameôhun n wayen ixdem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 39, 'Kkes ed iyeffusen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 40, 'Di Loennet pmesteqsayen', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 41, 'af ibe$wviyen:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 42, '"ar tmes acu i kwen ibbwin"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 43, 'A d inin: "ur nelli seg wid iéullen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 44, 'Ur necceççay aéawali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 45, 'Nella nepjuôu akked imjuôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 46, 'Nella d inekkaôen n wass iqeîîiyen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 47, 'armi d iusa i a$ itebbten".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 48, 'Ur ten tenfaâ ccafuâa imcafâen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 49, 'Mi ugin asmekti, d acu ten iu$en?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 50, 'Cuban i$wyal ixelâan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 51, 'i irewlen i izem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 52, 'Zi$ yal yiwen degsen ib$a ad as d asen isebtar ifesren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 53, 'Xaîi! Laxeôt, ur p ugaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 54, 'Xaîi! Wagi, war ccekk, d asmekti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 55, 'Win ib$an, a t ismekti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 56, 'Siwa ma Ib$a Öebbi ara d smektayen. D Neppa ay d Bab uêezzeb, d Bab n ssmaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 1, 'Ggule$ s wass n tnekra!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 2, 'Ggule$ s yiman bu tuzzma!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 3, 'Aâni i$il umdan, i$san is, ur ten Nessemlili ara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 4, 'Xaîi! Nezmer a Nesserked iduren is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 5, 'Maca, ib$a umdan ad irnu di tucmitin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 6, 'Isteqsay anda t wass n tnekra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 7, 'Ma tullsent wallen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 8, 'u i$ab waggur,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 9, 'u iîij akked waggur pwazdin;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 10, 'assen, amdan ad yini: "tarewla sani"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 11, 'Xaîi! Ssôan ur illi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 12, 'Axxam ippuôe$ben, ar Mass ik, ass nni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 13, 'Assen, ad ippuxebbeô umdan $ef wayen ibbwi ar zdat, akked wayen irra ar deffir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 14, 'Ih, amdan, deg iman is, ad iwali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 15, 'Xas issuter ssmaê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 16, 'Ur pêerrik, yis, iles ik, a d t$iwlev yis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 17, 'Fella£ ajemmel is akked t$uôi s.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 18, 'Mara t N$eô, ihi, ssel i t$uôi s.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 19, 'Sinna, ih, fella£ abeggen is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 20, 'Xaîi! Wanag têemmlem taêemmaqt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 21, 'Di laxeôt, testehzayem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 22, 'Udmawen, assen, ad feooeoen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 23, 'Ar Mass nnsen, ad pmuqulen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 24, 'Udmawen, assen, ad neééfen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 25, 'Ëûan, i twa$it ad ppunefken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 26, 'Xaîi! Mi tuli ar irawen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 27, 'ad inin: "anwa ay d agezzan"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 28, 'U iêûa ar wagi d lefôaq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 29, 'Imlal ufud ar ufud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 30, 'Ar Mass ik, assen, tanheôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 31, 'Ur iumin, ur ipéalla;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 32, 'U irna inkeô, iwexxeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 33, 'Sinna, ar twacult is irra s pnefxa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 34, 'A lwexda k, a lwexda!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 35, 'D$a, a lwexda k, a lwexda!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 36, 'Aâni i$il umdan d ilelli i ippuserreê?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 37, 'Aâni ur illi d tiqqit iuzlen n l$ella?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 38, 'Sinna, iu$al d argen. D$a Ixleq, Imsel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 39, 'Irra segs tayuga, ddkeô akked nnta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 40, 'Aâni Wa ur Izmir a d Issider lmeggtin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 1, 'Day tâadda tallit $ef umdan ideg ur illi d ayen ipwabedren?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 2, 'Ih, Nexleq amdan si tiqqit n l$ella ixelven. A t Njeôôeb, Nerra t isell, ipwali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 3, 'Nebbwi t d ubrid, ama isnemmir, ne$ inkeô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 4, 'Nhegga, ih, i ijehliyen, sslasel, aruz, u$ud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 5, 'Iâaôviyen, s tidep, ad swen, di lkas, ayen ixelîen akked lkafuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 6, 'Tala ideg tessen ixdimen n Öebbi, aman is pfeggiven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 7, 'Ppaîîafen di tuqqna, ugaden ass ideg lhemm immebruzzaâ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 8, 'Ppaken lqut, ilmend n lemêibba S, i igellil, i ugujil, i umeêbus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 9, '"F udem n Öebbi kan, ay kwen necceççay. Ur neb$i segwen tiririt ne$ tajmilt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 10, 'Nekwni, ih, nugad Mass nne$, ass awaâôan, aqessêan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 11, 'Isellek iten Öebbi si lhemm n wassen. Ccbaêa, lfeôê, Ifka yasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 12, 'Ikufa ten af wayen ûebôen: leonan, leêrir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 13, 'Ad éélen din af imîeôêen; ur pwalin iîij, asemmiv.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 14, 'Tili ines $uôsen, izwayen wâan asen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 15, 'A sen tezzin ibuqalen n lfeîîa, lkisan ulelluc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 16, 'Alelluc n lfeîîa; taceôt nnsen, s lmizan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 17, 'Dinna sswan asen lkas n wayen iwumi xelîen skenjbir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 18, 'Dinna tala; Salsabil i s ssawalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 19, 'Ilmeéiyen imezgiyen tezzin asen. Ma twalav ten, ad as tiniv d tiyuqat imfaôaqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 20, 'Ma tmuqlev ar din, a pwaliv ssaâd akked tgelda meqqwôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 21, 'Iceîîiven i llsan d leêrir aêcici iêewwcen; imeqqyasen n lfeîîa; Isswa ten Mass nnsen, s tissit iûfan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 22, 'Ih, wagi d arraz nnwen, u d tajmilt igiten nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 23, 'D Nekwni, s tidep, i k id Issersen Leqwôan, s lmizan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 24, 'Eûbeô i uêuddu n Mass ik; segsen, ur teccev, ur jehhel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 25, 'Mmekti d isem n Mass ik, tafrara, tameddit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 26, 'Deg iv, knu yaS, u sbuccaâ iT tallit $wezzifen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 27, 'Ih, wigi êemmlen taêemmaqt, stehzan deg wass amôay.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 28, 'Nekwni Nxelq iten, Nesseohed i$san nnsen. Ma ihwa ya£, a Nerr ay ten icban, wakali, deg umkan nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 29, 'Wagi, s tidep, d asmekti. Win ib$an, ad iddem abrid ar Mass is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 30, 'Ur tbeqqum, siwa ma Ib$a Öebbi. Öebbi, s tidep, d Amusnaw, d Bab n ûûwab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 31, 'Win i S ihwan, a t Issekcem ar uêunu S; ma d imednas, Ihegga yasen aâaqeb aqeôêan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 1, 'S tmersulin, ta s ta!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 2, 'Ipûuvun s lqewwa. ï', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 3, 'Veôôêent anevôuê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 4, 'S tid ifeôqen akken iwata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 5, 'Ssawavent asmekti,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 6, 'i ssmaê ne$ i uâaggen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 7, 'A d ias, s tidep, wayen i wen ippuwaââden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 8, 'Itran, ma xsin;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 9, 'igenni ma inceqq;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 10, 'idurar ma pwiôôéen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 11, 'imazanen, ma d lweqt nnsen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 12, 'Anwa t wass u$uô pweoolen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 13, 'D ass n ufraz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 14, 'Anwa a d ak imlen d acu t wass n ufraz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 15, 'Assen, a ssxev inekkaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 16, 'Day ur Nesqucc ara imezwura?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 17, 'Sinna, Nerra ineggura deffir sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 18, 'Akka ay Nxeddem i ibe$wviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 19, 'Assen, a nnger inekkaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 20, 'Day ur kwen Nexliq ara si cwiî n waman?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 21, 'Nerra ten deg umekkan muman,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 22, 'ar lajel ipwassnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 23, 'Nseyya. Amarezg n Wid Ipseyyin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 24, 'Assen, a nnger inekkaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 25, 'Day ur nerra ara tamurt d ayen ijemâen', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 26, 'wid idren, akked wid immuten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 27, 'Nerra degs idurar âaooôen. S waman iéidanen, Nesswa kwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 28, 'Assen, a nnger inekkaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 29, 'Ddut ar wayen tepnekkiôem!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 30, 'Ddut ar tili m krav idurna!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 31, 'Ur tesburru, ur tesdaray si tmes iôeqqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 32, 'Neppat teîîegiô ifîiwjen, am lebôuj aâlayen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 33, 'amzun d ile$wman iwôa$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 34, 'Assen, a nnger inekkaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 35, 'Assa, d ass ideg ur d pmmeslayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 36, 'I usuter n ssmaê, ur sen pserriêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 37, 'Assen, a nnger inekkaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 38, 'Assa d ass n ufraz. Nessemlal ikwen akked imezwura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 39, 'Ma tundim, andit iyI!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 40, 'Assen, a nnger inekkaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 41, 'S tidep, di tili akked tliwa, ara ilin wid ipêezziben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 42, 'Lfakia, d ayen ccihwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 43, 'Eççet tesswem, di lehna, ilmend n wayen txeddmem!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 44, 'Ih, akka ay Nepkafi izedganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 45, 'Assen, a nnger inekkaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 46, 'Eççet, zzhut cwiî kan, kunwi, war ccekk, d ibe$wviyen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 47, 'Assen, a nnger inekkaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 48, 'Ma nnan asen: "îîinzet"! Ur îîinizen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 49, 'Assen, a nnger inekkaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 50, 'Ihi, anwa awal, deffir wagi, ara amnen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 1, '£ef aydeg pmesteqsayen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 2, '£ef usali abarar,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 3, 'i$ef mgarraden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 4, 'Xaîi, ad éôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 5, 'Sinna, xaîi, ad éôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 6, 'Day ur Nerra ara tamurt d usu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 7, 'idurar, d ibudiden?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 8, 'Nexleq ikwen d tiwugiwin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 9, 'Nerra ives nnwen d ôôaêa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 10, 'Nerra iv d talaba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 11, 'Nerra ass i tmeddurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 12, 'Nebna sennig wen ûa uohiden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 13, 'Nerna asavef ipôeqôiqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 14, 'Nesse$li d, seg usigna, aman d ihedman,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 15, 'iwakken a Nessker, yissen, im$an, iâqqayen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 16, 'tibêirin ideôsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 17, 'Ih, ass n ufraz ipwassen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 18, 'Ass uûuvu n lbuq, a d tasem d iorawen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 19, 'Ad ildi igenni, d$a ad ilint tebbura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 20, 'Ad lêun idurar, u$alen d aylal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 21, 'Ih, Loahennama teqquôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 22, 'D axxam imednas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 23, 'Aîas ara qqimen dinna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 24, 'Tissit, tasmuvi, ur degs, ppafen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 25, 'siwa aman iô$an, akked iôeûvan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 26, 'D aqeîîi iwulmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 27, 'Nitni, s tidep, ur oaâlen ara ad ppuqeîîin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 28, 'Isekniyen nne£, s leqseê ay ten nekkôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 29, 'Yal cci, Nêesb it s tira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 30, 'Ihi, jeôôbet! Ur awen Nernu, d awez$i, siwa aâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 31, 'S tidep, i wid ipêezziben, amkan n laman;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 32, 'tifeôôanin, iqwiôen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 33, 'tizzyiwin ifazen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 34, 'lkisan ifalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 35, 'Ur din sellen yir awal ne$ tikerkas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 36, 'D arraz s$uô Mass ik, d tikci klalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 37, 'Mass n tmurt, igenwan, akked wayen illan garasen; Aênin, ur zmiren a ten Ioo a d mmeslayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 38, 'Asmi ara beddent lmalayek akked ôôuê, d idurra, siwa win Iooa Uênin ara d immeslayen; a d yini awal uûwib.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 39, 'D wagi ay d ass n tidep; win ib$an, idda d ubrid n tu$alin ar Mass is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 40, 'Ih, Nâaggen awen: aâaqeb d ayen iqeôben. Ass ideg ara iéeô umdan, acu xedmen ifassen is, ad yini ujehli: "a ssexv iw, a lemmer lli$ d akal"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 1, 'S tid iqelâen $evsent!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 2, 'S tid iteddun éewôent!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 3, 'S tid ippâumun s sshala!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 4, 'S tid ipêizwaren d amêizwer!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 5, 'S tid idebbiôen lameô!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 6, 'Ass ideg ara d i$eô ûûut,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 7, 'a t id ivfeô uvfiô,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 8, 'ulawen, ad rgagin, assen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 9, 'Ad brunt wallen nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 10, 'Ad inin: "day, s tidep, a d nu$al akken nella?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 11, 'Xas nekwni d i$san irkan"?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 12, 'Ad inin: "ayagi, ihi, d tu$alin n lexsaôa"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 13, 'Neppa, d yiwet n ti$ôi kan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 14, 'Atnan u$alen ar tmurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 15, 'Ma tusa k id tedyant n Musa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 16, 'Mi s d Issawel Mass is di Ïuwa, ta$zut iôqan:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 17, '"ôuê ar Feôâun, atan ijuô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 18, 'Ini: ma tzemrev a ppizdigev?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 19, 'A k nhu$ ar Mass ik, d$a a ppagwadev".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 20, 'Issenâat as assekni abarar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 21, 'D$a, iskaddeb, iâuûa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 22, 'Sinna, ibren, icqa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 23, 'Issemlal ed, iberreê.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 24, 'Inna: "d nek ay d mass nnwen aâlayan"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 25, 'Irra t Öebbi d amedya uâaqeb, di tmezwarut u di tneggarut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 26, 'Ih, tagi degs nnqida i win iugaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 27, 'Day d lxelq nnwen i iwaâôen, ne$ d igenni mi t Ibna?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 28, 'Issuli lqus is, Iwezn it.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 29, 'Issebrek iv is; Issuffe$ ed tafat is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 30, 'Deffir waya, Issewsaâ tamurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 31, 'Issuffe$ ed segs aman is, akked tkessawt is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 32, 'Idurar, Iôûa ten;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 33, 'd l$it i kunwi, akw i lmal nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 34, 'Mara d tas twa$it tabarart,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 35, 'ayen ixdem umdan, a t id ismekti, assen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 36, 'times a d tban i win ipwalin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 37, 'Wanag win ijuôen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 38, 'ismenyafen tameddurt n ddunit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 39, 'Ihi, d times ay d ûûôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 40, 'Wanag win iugaden ibeddi zdat Mass is, u ikkes cchawi i teôwiêt,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 41, 'ihi, d Loennet ay d ûûôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 42, 'Steqsan k af yimir, melmi tisin is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 43, 'Amek ara t id tdekôev, keçç?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 44, 'Ar Mass ik, agwav is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 45, 'Keçç d aneddaô kan i win it iugaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 46, 'Ihi, nitni, ass ideg ara t walin, amzun qqimen kan tameddit, ne$ tasebêit nni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 1, 'Ikres anyir, ibren,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 2, 'imi d ader$al it id iusan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 3, 'W ar ak yinin, ahat d azedgan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 4, 'Ne$ ismektay, asmekti isfayda t?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 5, 'Wanag, win isâan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 6, 'd neppa iwumi tgiv ccan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 7, 'Ur d terziv ma d azedgan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 8, 'Ma d amsuter id iusan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 9, 's wudem ikukran,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 10, 'keçç, degs, d win istehzan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 11, 'Xaîi! Ihi wagi d asmekti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 12, 'Ismekti t id win ib$an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 13, 'Di tewôeqtin ikeysen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 14, 'aâlayen, zeddigen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 15, 'ger ifassen imqeddmin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 16, 'leêôaô, izedganen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 17, 'Tameppant i umdan! Ay d ajehli!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 18, 'S wacu it Ixleq?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 19, 'Si tiqqit, Ixelq it, Iwezn it.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 20, 'Sinna, abrid Isehhel as t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 21, 'Sinna, In$a t, Inîel it.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 22, 'Sinna, ma ihwa yaS, a t id Isker.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 23, 'Xaîi! Ur iuqim ayen i s Iêeppem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 24, 'Ad iwali tagwella s, umdan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 25, 'D Nekwni id Ifkan aman, d ihedman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 26, 'Sinna, Ne$za tamurt, d i$isan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 27, 'Nessuffe$ ed, segs, iâaqqayen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 28, 'tiéuôin, akked wayen zegzawen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 29, 'tizemrin, tizdayin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 30, 'iqwiôen iveôsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 31, 'tikessawin akked izwayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 32, 'D l$it i kunwi, akked lmal nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 33, 'Ma tusa d tin ippiééifen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 34, 'ass ideg amdan ad irwel i gma s,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 35, 'i imma s, akked baba s,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 36, 'i tmeddakwelt is, akked warraw is;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 37, 'yal amdan segsen, assen, a d ilhu deg wayen i t iaânan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 38, 'Ad feooeoen udmawen assen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 39, 'ad dessen, feôêen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 40, 'Assen, udmawen a$webbaô fellasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 41, 'Le$wmam idel iten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 42, 'Widak d ijehliyen, d ucmiten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 1, 'Ma iu$al itij d akennur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 2, 'Ma $lin itran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 3, 'Ma pwanehôen idurar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 4, 'Ma pwasebblent tle$wmatin, s tdisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 5, 'Ma pwafessren lêayawan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 6, 'Ma îwakenfen ilellen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 7, 'Ma rran imanen d tiyugiwin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 8, 'Ma tepwavleb teqcict ipwaneîlen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 9, 'anwa abekkav i$ef te$wan$a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 10, 'Ma pwafessrent tewôeqtin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 11, 'Igenni ma cerrgen t.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 12, 'Times, ma smendgen p.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 13, 'Loennet, ma tuéa d.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 14, 'Ad yissin, yiman, ayen d ihegga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 15, 'Ihi, Gulle$ s yitran iteffren,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 16, 'ippazalen, ppâidayen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 17, 'S yiv, ma iôuê!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 18, 'S tûebêit, ma tecôuôeq!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 19, 'Wigi ard awalen Umazan ukyis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 20, 'Bu tezmert s$uô Bab n usgeld iôesmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 21, 'Bab n wannuz, u Muman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 22, 'Ur illi d aôehbani, umeddakwel nnwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 23, 'Ih, iwala t, di lejba ibanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 24, 'Di tbavnit ur ipmunnu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 25, 'Ur neppa d awal n Cciîan imenfi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 26, 'Ihi, aniwer teppeddum?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 27, 'Neppa, d asmekti kan i imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 28, 'I win, segwen, ib$an ad issewqem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 29, 'Ur tbeqqum, siwa ma Ib$a Öebbi, Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 1, 'Igenni, ma iqlaâ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 2, 'itran, ma mebruzzâen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 3, 'ilellen, ma falen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 4, 'iéekwan, ma nneqlaben,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 5, 'ad iéeô yiman ayen d ibbwi, akked wayen iooa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 6, 'A yamdan, d acu k i$uôôen, $ef Mass ik Ukyis', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 7, 'ik Ixelqen, ik Imesslen, ik Iwezznen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 8, 'Ifka yak udem i aS iwulmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 9, 'Xaîi! Teskiddibem ddin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 10, 'Ni$ $urwen imêaraben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 11, 'D imura ukyisen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 12, 'èôan ayen txeddmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 13, 'Ih, di ssaâd, ara ilin iâaôdiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 14, 'Ih, di tmessi, ara ilin ucmiten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 15, 'A p kecmen, ass iqeîîiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 16, 'Tuff$a segs, ur zmiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 17, 'Anwa ara k imlen, d acu t wass iqeîîiyen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 18, 'Ih! Anwa ara k imlen, d acu t wass iqeîîiyen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 19, 'D ass ideg yiwen ur izmir ad ifukk yiwen, s wacemma. Assen, lameô i Öebbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 1, 'Imed$al, a nnegr nnsen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 2, 'Wid, mara d ktilen ar medden, pêeppimen taceôt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 3, 'Wanag, nitni, mara ktilen ne$ wezznen, ssenqasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 4, 'Wigi, day ur uminen ar aten id ssekren', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 5, 'ass ameqwôaêan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 6, 'Ass ideg ara bedden medden, zdat Mass imavalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 7, 'Xaîi! War ccekk, imcumen, di Siooin ara ppujerrden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 8, 'Siooin, w ara k t imlen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 9, 'D tazmamt ipwanesxen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 10, 'Assen, a nnegr inekkaôen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 11, 'Wid iskiddiben ass iqeîîiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 12, 'I t inekkôen, siwa amâaûi amednub.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 13, 'Isekniyen nne£, ma $ôan as ten, yini: "d tiêkayin imezwura".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 14, 'Xaîi! Maca dubben wulawen nnsen seg wayen kesben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 15, 'Xaîi! Assen, war ccekk, ad êêurrmen i Mass nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 16, 'Sinna, deg u$ud ara ô$en.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 17, 'Sinna, ad pwanecden: "atan wacu tnekkôem".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 18, 'Xaîi! S tidep, ar di Âiliyun, ayen ippujerden i iâaôviyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 19, 'Âiliyun, anwa ara k t imlen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 20, 'D tazmamt ipwanesxen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 21, 'Inagan is d iqôiben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 22, 'Di ssaâd ara ilin, war ccekk, iâaôviyen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 23, 'F imîeôêen, ssikiden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 24, 'A pwaliv deg udmawen nnsen, ticci isaâdiyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 25, 'Tissit nnsen d lfayeq ipwacemâen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 26, 'cmaâ ines d lmesk, f ayagi ad mêizwiren wid ippemêizwiren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 27, 'Aman n Tasmin, ad as xelîen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 28, 'D tala ideg tessen iqôiben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 29, 'Ih, wid ibe$wven llan ppavûan deg wid iumnen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 30, 'Ppem$emmazen mara ten mmagren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 31, 'Mi zzin ar twaculin nnsen, tezzin, ppuraren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 32, 'Mara ten walin, ad inin: "s tidep, wigi nnetlafen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 33, 'Ur d pwaznen ara $uôsen, a ten âassen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 34, 'Assa, d wid iumnen i ippavûan deg ijehliyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 35, '£ef imîeôêen, ssikiden', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 36, 'ma $elten ijehliyen, tirect igiten nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 1, 'Ma icerreg igenni,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 2, 'issemêess i Mass is, ippuêeppem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 3, 'Ma temsawi tmurt,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 4, 'tveggeô i illan degs, texla;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 5, 'têess i Mass is, teppuêeppem,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 6, 'a yamdan iôe$ben aîas Mass ik, yideS a ppemlilev!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 7, 'Wanag, win ibbwev leêsab is, yeffus is,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 8, 'ad ishel lêisab is;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 9, 's lferê ara iqqwel ar twacult is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 10, 'Ma d win ibbwev leêsab is, deffir waârur is,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 11, 'ad issawal i ssxev,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 12, 'ad ir$ di tmessi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 13, 'Ni$ illa ifôeê ar twacult is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 14, 'Neppa, ih, inwa ur d ippu$al.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 15, 'Xaîi! Zi$ la t Issikid Mass is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 16, 'Xaîi! Gulle$ s lme$ôeb!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 17, 'S yiv akked wayen i$umm!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 18, 'S waggur n tziri ma iççuô!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 19, 'War ccekk, a ppeddum si lêala ar tayev!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 20, 'Acu iten iu$en, ur uminen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 21, 'Mara sen $ôen Leqwôan, ur kennun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 22, 'Xaîi! Wid ijehlen skiddiben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 23, 'Öebbi Issen, sennig akw, ayen teffren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 24, 'Becceô iten s uâaqeb aqeôêan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 25, 'Kkes ed wid iumnen, ixeddmen ayen ilhan; d imezgi warraz nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 1, 'S igenni bu itran!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 2, 'S wass ippuwaââden!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 3, 'S unagi akked ccada s!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 4, 'At uxenduq pwan$an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 5, 'Times m iseô$an;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 6, 'mi nitni qqimen $uôes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 7, 'D nitni ay d inagan n lmumnin f wayen i sen xedmen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 8, 'Ur illi ay sen stebâan, siwa imi umnen s Öebbi, Uzmir, Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 9, 'IneS tagelda n tmurt akked igenwan. Öebbi d Anagi n yal cci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 10, 'Ih, wid ihewwlen lmumnin, argaz tameîîut, ur steôoâen, ad ppuâaqben s Loahennama, ad ppuâaqben s tmeô$iwt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 11, 'Wanag, i wid iumnen, ixeddmen ayen ilhan, leonanat, ddawat sen isaffen ppazzalen. D wagi ay d rrbeê ameqwôan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 12, 'Tiyta n Mass ik, s tidep, tewâaô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 13, 'Neppa, s tidep, Ibeddu, Ippales.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 14, 'Neppa, Ipsemmiê, Iêemmel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 15, 'Bab n usgeld, Amaâzuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 16, 'Ixeddem ayen i S ihwan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 17, 'Ma tebbwev ik id teqsiî iâsekôiwen', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 18, 'n Feôâun akked Tamud?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 19, 'Maca, wid ijehlen, deg uskiddeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 20, 'Öebbi, deffir, Izzi yasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 21, 'Maca, wagi d Leqwôan muccaâ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 22, 'di telwiêt ipwaêerzen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 1, 'S igenni, akked yitri n yiv!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 2, 'W ara k imlen d acu t itri n yiv?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 3, 'Ipôeôiq itri n yiv.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 4, 'Yal iman fellas amêareb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 5, 'Ad iwali umdan seg wacu ipwaxleq.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 6, 'Ipwaxleq s waman id ifin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 7, 'Ff$en ed ger tgeééal akked tgwejda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 8, 'Ih, Izmer a t id Issker, Neppa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 9, 'Ass ideg lesrar ur drigen ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 10, 'Ur isâi kra n tezmert ne$ n tallalt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 11, 'S igenni bab n tririt!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 12, 'S tmurt ipceqqiqen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 13, 'Ar neppa d awal ifeûûlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 14, 'Ur illi d urar waya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 15, 'Atnan, ih, ppandin ticeôkep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 16, 'Ad Andi$ ticeôkep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 17, 'I ijehliyen eoo lmudda, eoo asen cwiî lmudda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 1, 'Sbuccaâ ism n Mass ik, Aâlayan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 2, 'Ixelqen, Issemsaway,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 3, 'Iwezznen, Inhan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 4, 'I d Issuff$en takessawt,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 5, 'sinna, Ippara p d asa$uô aberkan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 6, 'A k Ness$eô, ur teppu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 7, 'siwa ayen Irad Öebbi. Ih, Neppa, Issen ayen ibanen, akked wayen iffren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 8, 'A k Nawi ar liser.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 9, 'Smmekti mi infaâ usmekti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 10, 'A d ismmekti win iugaden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 11, 'Ageswaê ijuneb it.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 12, 'Di tmes tabarart mavi ara iô$.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 13, 'Degs, ur ipmeppat, ur ippidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 14, 'Amarezg n win zeddigen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 15, 'I ismektayen ism n Mass is, d$a ipéalla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 16, 'Maca, tesmenyafem tameddurt n ddunit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 17, 'Tif ip laxeôt, a pdum kteô.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 18, 'Ayagi, illa di tewôeqtin timezwura,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 19, 'Tiwôeqtin n Ibôahim akked Musa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 1, 'Ma tebbweb ik id teqsiî n te$wlalt?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 2, 'Ad anzen wudmawen, assen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 3, 'Ad xedmen, ad merten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 4, 'Ad ô$en di tmes izehren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 5, 'Ad asen sswen aman ippayzagen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 6, 'Ur asen illi wuççi, siwa timeôéuga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 7, 'Ur ssufayent, ur sseôwayent.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 8, 'Udmawen, assen nnecôaêen. öÔ', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 9, 'Öuvan laâtab nnsen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 10, 'di Loennet aâlayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 11, 'Yir awal, ur din sellen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 12, 'Degs, tala ippazalen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 13, 'Degs, imîeôêen aâlayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 14, 'Iqbucen wejden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 15, 'Tisumtiwin iderrsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 16, 'Tiôakniwin issan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 17, 'Acimi ur pmuqulen ara al$wem, amek ipwaxleq,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 18, 'u igenni, amek iuli,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 19, 'u idurar, amek âaoôen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 20, 'u tamurt, amek temsuwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 21, 'Ihi, mmekti! Keçç d win kan ismektayen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 22, 'Ur telliv d amôay nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 23, 'Kkes ed win iwexxôen, ijehlen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 24, 'Ad as Iheggi Öebbi aâaqeb abarar mavi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 25, 'Ni$ $uône£ tu$alin nnsen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 26, 'Sinna, s tidep, fella£ aqeîîi nnsen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 1, 'S tafrara!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 2, 'S mraw wavan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 3, 'S wayugan akked waryugan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 4, 'S yiv, ma ilêa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 5, 'Day maççi dagi d tagallit i lfahem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 6, 'Day ur twalav ara amek Ixdem Mass ik, i Âad?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 7, 'Iôam m tgejda;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 8, 'ur tepwaxleq temtilt is, di tmura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 9, 'U Tamud, di te$zut, i i$zan tiéôa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 10, 'Ferâun, bu ibudiden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 11, 'Wid ijuôen di tmurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 12, 'Degs ssugten lefsad', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 13, 'Iwwet iten Mass ik, s ujekwav uâaqeb.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 14, 'Ih, Mass ik d Amâassi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 15, 'Amdan ma Ijeôôeb it Mass is, I$at it, Iga yas ccan, ad yini: "d Mass iw iyi Iâuzzen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 16, 'Wanag, ma Ijeôôeb it, I$at it kan s lmizan, ad yini: "d Mass iw iyi Igelzen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 17, 'Xaîi! Agujil, ur t tepâuzzum!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 18, 'Ur teppemtebbatem ar ume$bun, a t tecceççem!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 19, 'Teppeppem lweôt, têellqem!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 20, 'Têemlem ayla, tayri war tilas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 21, 'Xaîi! Ma temsawi tmurt, yal amsawi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 22, 'u Iusa d Mass ik, akked lmalayek, d idurra,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 23, 'assen, a d ters Loahennama. Assen, a d ismekti umdan. Acu ar as d iawi usmekti?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 24, 'Ad yini: "a ssexv iw! A lemmer hegga$ i tmeddurt iw"!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 25, 'Aâaqeb is, assen, ur t isâadda yiwen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 26, 'Yiwen ur ipwaqqen akken ipwaqqen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 27, 'A yiman illan di laman,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 28, 'u$al ar Mass ik, d amôavi ôuvan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 29, 'Ekcem ger imdanen iW!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 30, 'Ekcem di Loennet iW!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 1, 'Xaîi! Gulle$ s temdint a!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 2, 'U keçç d ilelli, di temdint a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 3, 'S ubabat akked wayen id iurew!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 4, 'Ar Nxelq ed amdan d ûûam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 5, 'Day inwa ur as izmir yiwen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 6, 'Iqqaô: "sgullze$ lerbaê, werrken".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 7, 'Day inwa ur t iéôi yiwen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 8, 'Day ur as Nefka ara snat wallen,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 9, 'iles, sin icenfiren?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 10, 'Nenha t di sin iberdan meqqwôen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 11, 'Ur idhim deg win iulin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 12, 'Abrid iulin, anwa ara k t imlen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 13, 'Aserreê i wakli,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 14, 'ne$ acceççi, di tallit n cceôô,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 15, 'ugujil aqôib,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 16, 'igellil izellîen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 17, 'Akked tilin seg wid iumnen, i ppemyenhun ar ûûbeô, u ppemyenhun ar lmaênana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 18, 'Widak d at yeffus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 19, 'Wid iugin issekniyen nne£, nitni d at zelmev.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 20, 'Times a ppezzi fellasen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 1, 'S tafugt akked tafat is!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 2, 'S waggur, mara p ivfeô!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 3, 'S wass, mi p ifet!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 4, 'S yiv, mi s isburr!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 5, 'S igenni, akked Win i t ibnan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 6, 'S tmurt, akked Win ip issewsâan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 7, 'S teôwiêt, akked Win ip imeslen!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 8, 'Iwehheb as laâwayeô is, aêezzeb is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 9, 'Ni$ irbeê win ip izzazdgen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 10, 'Ni$ ixseô win ip itelfen.', '');
