INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 11, 'Iwumi yas wayla s, imi ad i$li?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 12, 'Nnhaya, s tidep, fellane£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 13, 'Ih, taneggarut akked tmezwarut, d ayla nne£.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 14, 'Âaggne$ awen: times d taqesêant.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 15, 'Ara p ikecmen, siwa imceôôi mavi,', '');
