INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 1, 'Ijehliyen seg At Tezmamt, akked imcurak, ur steôoiâen alamma irs ed, $uôsen, ubeggen:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 2, 'Amazan s$uô Öebbi, i immalen tiwôeqtin zeddigen;', '');
