INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 4, 'Ur myefrazen wid iwumi teppunefk Tezmamt, armi ten id iusa ubeggen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 5, 'Ppwamôen, kan, ad âabden Öebbi s ddin iûfan, ad malen ar tidep, ad bedden i téallit, ad zzekkin. D wagi ay d ddin umâin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 6, 'Ih, wid ijehlen, seg At Tezmamt akked imcurak, di tmes n Loahennama ad wekkôen. Widak, d aâar n yimdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 7, 'Ma d wid ippamnen, i xeddmen ayen ilhan, widak d lxetyaô n yimdanen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 8, 'Arraz nnsen, ar Mass nnsen, d leonanat n Âaden, ddawat sen isaffen ppazzalen, degsen ad wekkôen, i lebda. Öebbi Iôuva ten, nitni ôuvan T. Akka i win i ippagwaden Mass is.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 1, 'Mara tezlez tmurt zzelzla s,', '');
